"""City guide: stations connect to hotels and attractions; a walker from each station
shortlists only attractions rated 4 stars or higher and prints the itinerary."""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
    has nightly_rate: float = 0.0;
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

edge ConnectsTo {}

walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can arrive with Station entry {
        print(f"Arrived at station: {here.name}");
        visit [-->];
    }

    # Only attractions are reviewed; hotels are skipped via a separate ability.
    can skip_hotel with Hotel entry {
        print(f"  (skipping hotel: {here.name})");
        visit [-->];
    }

    can review with Attraction entry {
        status = "SHORTLIST" if here.stars >= 4 else "PASS";
        print(f"  [{status}] {here.name} ({here.stars}★)");
        visit [-->];
    }
}

with entry {
    central = Station(name="Central Station");
    riverside = Station(name="Riverside Station");

    # Stations connect to hotels and attractions via ConnectsTo edges.
    central +>:ConnectsTo:+> Hotel(name="Grand Plaza", nightly_rate=220.0);
    central +>:ConnectsTo:+> Attraction(name="City Museum", stars=5);
    central +>:ConnectsTo:+> Attraction(name="Old Bridge", stars=3);

    riverside +>:ConnectsTo:+> Hotel(name="Riverside Inn", nightly_rate=95.0);
    riverside +>:ConnectsTo:+> Attraction(name="Harbor Cruise", stars=4);
    riverside +>:ConnectsTo:+> Attraction(name="Lighthouse Walk", stars=4);
    riverside +>:ConnectsTo:+> Attraction(name="Dockside Cafe", stars=2);

    root spawn Tourist();
    print("---");
    root spawn Tourist();
}

"""Vet clinic round: pets as nodes, vet walker accumulates patient list and shot count."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print("Vet starting the clinic round");
        visit [-->];
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"  Vaccinated {here.name} the {here.species}");
        } else {
            print(f"  Checked {here.name} the {here.species} - no vaccine needed");
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=True)
        ++> Pet(name="Bun", species="rabbit", needs_vaccine=False)
        ++> Pet(name="Luna", species="cat", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"\nRound complete: {len(vet.patients)} patients seen, {vet.shots_given} shots given");
    print(f"Patient roster: {vet.patients}");
}

"""Cloud Streams subscriber retry policy bypass: failed dispatches recurse with no backoff.

Models neuroglia-io/cloud-streams#131 — RetryDispatchAsync and DispatchAsync mutually
recurse, resetting Polly counters and inflating TotalDeliveryFailures instead of honoring
maxAttempts, backoffDuration, and circuitBreaker settings.
"""

edge RetryToDispatch {
    has label: str = "retry";
}

edge DispatchToRetry {
    has label: str = "dispatch";
}

edge DeliversTo {
    has since_offset: int = 0;
}

node RetryPolicy {
    has max_attempts: int = 3;
    has backoff_seconds: int = 3;
    has break_after: int = 3;
    has break_duration_seconds: int = 5;
}

node Subscription {
    has name: str = "";
    has subscriber_uri: str = "";
    has policy: RetryPolicy = RetryPolicy();
    has available: bool = True;
}

node Subscriber {
    has uri: str = "";
    has returns_success: bool = False;
    has available: bool = True;
}

node DispatchAttempt {
    has offset: int = 0;
    has http_status: int = 503;
    has available: bool = True;
}

walker BrokenBroker {
    has delivery_failures: int = 0;
    has policy_builds: int = 0;
    has attempt_in_policy: int = 0;
    has recursion_depth: int = 0;
    has max_demo_depth: int = 6;

    can start with Root entry {
        print("=== Broken path: mutual recursion bypasses retry policy ===");
        visit [-->];
    }

    can retry_dispatch with Subscription entry {
        self.policy_builds += 1;
        self.attempt_in_policy = 0;
        print(
            f"RetryDispatch: fresh Polly policy #{self.policy_builds} "
            f"(maxAttempts={here.policy.max_attempts} never reached)"
        );
        visit [->:RetryToDispatch:->] else { disengage; };
    }

    can dispatch_async with DispatchAttempt entry {
        self.recursion_depth += 1;
        self.attempt_in_policy += 1;
        self.delivery_failures += 1;
        outcome = "FAIL" if here.http_status >= 400 else "OK";
        print(
            f"  DispatchAsync(retryOnError=false) depth={self.recursion_depth} "
            f"status={here.http_status} [{outcome}] "
            f"policy_attempt={self.attempt_in_policy} "
            f"total_failures={self.delivery_failures}"
        );
        if here.http_status >= 400 {
            if self.recursion_depth >= self.max_demo_depth {
                print(
                    f"  Demo cap at depth {self.max_demo_depth}; "
                    f"real broker recurses with NO backoff and NO cap"
                );
                disengage;
            }
            visit [->:DispatchToRetry:->] else { disengage; };
        } else {
            visit [-->];
        }
    }
}

walker PolicyBroker {
    has attempts: int = 0;
    has delivery_failures: int = 0;
    has consecutive_failures: int = 0;
    has circuit_open: bool = False;

    can start with Root entry {
        print("=== Correct path: single policy governs bounded retries ===");
        visit [-->];
    }

    can apply_policy with Subscription entry {
        if self.circuit_open {
            print(
                f"Circuit OPEN — delivery paused to {here.subscriber_uri} "
                f"for {here.policy.break_duration_seconds}s"
            );
            disengage;
        }
        while self.attempts < here.policy.max_attempts {
            self.attempts += 1;
            self.delivery_failures += 1;
            self.consecutive_failures += 1;
            print(
                f"  Polly attempt {self.attempts}/{here.policy.max_attempts} "
                f"-> {here.subscriber_uri} [503 FAIL]"
            );
            if self.consecutive_failures >= here.policy.break_after {
                self.circuit_open = True;
                print(
                    f"  Circuit breaker opened after "
                    f"{here.policy.break_after} consecutive failures"
                );
                break;
            }
            if self.attempts < here.policy.max_attempts {
                print(
                    f"  Backoff: waiting {here.policy.backoff_seconds}s "
                    f"before next attempt"
                );
            }
        }
        print(
            f"Policy stopped after {self.attempts} real attempts, "
            f"failures={self.delivery_failures}, "
            f"circuit_open={self.circuit_open}"
        );
        visit [-->];
    }
}

with entry {
    failing_sub = Subscriber(
        uri="http://localhost:8888/some-endpoint",
        returns_success=False
    );
    sub = Subscription(
        name="all-events",
        subscriber_uri="http://localhost:8888/some-endpoint",
        policy=RetryPolicy(
            max_attempts=3,
            backoff_seconds=3,
            break_after=3,
            break_duration_seconds=5
        )
    );
    attempt = DispatchAttempt(offset=-1, http_status=503);

    root ++> sub;
    sub +>:RetryToDispatch:+> attempt;
    attempt +>:DispatchToRetry:+> sub;
    sub +>:DeliversTo(since_offset=-1):+> failing_sub;

    root spawn BrokenBroker();
    root spawn PolicyBroker();
}

"""Wildlife park feeding rounds.

The info kiosk greets every tour party via a union trigger; zookeepers
hand out species-appropriate meals; school groups only observe.
"""

# Base animal node so a union ability can touch shared fields/methods.
node Animal {
    has name: str;
    has fed: bool = False;
    has species: str = "animal";

    def preferred_meal() -> str {
        return "standard feed";
    }
}

node Lion(Animal) {
    override def preferred_meal() -> str {
        return "meat";
    }
}

node Parrot(Animal) {
    override def preferred_meal() -> str {
        return "seed";
    }
}

node Zebra(Animal) {
    override def preferred_meal() -> str {
        return "standard feed";
    }
}

node InfoKiosk {
    has kiosk_name: str;

    # Union trigger: fires for any tour party (zookeeper or school group).
    can greet with Zookeeper | SchoolGroup entry {
        print(f"Welcome {visitor.party_label} to the {self.kiosk_name} info kiosk!");
        visitor.kiosk_visits += 1;
    }
}

walker Zookeeper {
    has party_label: str = "Zookeepers";
    has kiosk_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach_kiosk with InfoKiosk entry {
        visit [-->];
    }

    # Union trigger: serve any animal species with the right meal.
    can feed with Lion | Parrot | Zebra entry {
        meal = here.preferred_meal();
        kind = here.species;
        print(f"Zookeeper feeds {here.name} the {kind}: {meal}");
        here.fed = True;
        visit [-->];
    }
}

walker SchoolGroup {
    has party_label: str = "School Group";
    has kiosk_visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach_kiosk with InfoKiosk entry {
        visit [-->];
    }

    can observe with Lion | Parrot | Zebra entry {
        print(f"School group watches {here.name} ({here.preferred_meal()})");
        visit [-->];
    }
}

with entry {
    kiosk = InfoKiosk(kiosk_name="Savannah");
    simba = Lion(name="Simba", species="lion");
    polly = Parrot(name="Polly", species="parrot");
    ziggy = Zebra(name="Ziggy", species="zebra");

    root ++> kiosk ++> simba ++> polly ++> ziggy;

    zk = Zookeeper();
    root spawn zk;
    sg = SchoolGroup();
    root spawn sg;

    print(f"Zookeeper greeted at {zk.kiosk_visits} kiosks, "
          f"School group greeted at {sg.kiosk_visits} kiosks");
    print(f"Simba fed? {simba.fed}; Polly fed? {polly.fed}; Ziggy fed? {ziggy.fed}");
}

"""Kitchen line health inspection: check station temperatures, flag violations, and log every station visit."""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
    has violation_count: int = 0;

    def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: station '{self.name}' logged");
    }

    def check_temperature() -> None {
        if self.temperature > 40.0 {
            self.violation_count += 1;
            print(f"  VIOLATION at '{self.name}': {self.temperature} C exceeds 40 C "
                  f"(total violations: {self.violation_count})");
        } else {
            print(f"  OK: '{self.name}' at {self.temperature} C");
        }
    }
}

# Cold prep station: stays safe below 40 C.
node ColdPrep(Station) {
    override def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: cold-prep station '{self.name}' logged");
    }
}

# Grill station: hot, but flag if it drifts above 40 C (probe misplacement).
node Grill(Station) {
    override def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: grill station '{self.name}' logged");
    }
}

# Fryer station: hot oil, flag if it drifts above 40 C.
node Fryer(Station) {
    override def log_visit(visit_num: int) -> None {
        print(f"Visit #{visit_num}: fryer station '{self.name}' logged");
    }
}

walker Inspector {
    has station_count: int = 0;

    can start with Root entry {
        print("Inspector starting kitchen line walk...");
        visit [-->];
    }

    can check_station with ColdPrep | Grill | Fryer entry {
        self.station_count += 1;
        # Both checks run at every station.
        here.log_visit(self.station_count);
        here.check_temperature();
        visit [-->];
    }
}

with entry {
    # Build the kitchen line.
    grill = Grill(name="Grill #1", temperature=185.0);
    fryer = Fryer(name="Fryer #2", temperature=160.0);
    cold = ColdPrep(name="Salad Cold Prep", temperature=4.0);

    root ++> grill ++> fryer ++> cold;

    # Spawn the inspector on the root; the union ability fires at each station.
    root spawn Inspector();
}

"""Kitchen line health inspection: probe each station's temperature and log every visit.

Both the temperature check (flagging > 40 C as a violation) and the visit log
must run at every station, regardless of station type.
"""

node Station {
    has name: str = "";
    has temp_c: float = 0.0;

    # shared accessor: every station can be temperature-checked
    def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

node Grill(Station) {
    has fuel: str = "gas";
    override def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

node Fryer(Station) {
    has oil_level: int = 100;
    override def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

node ColdPrep(Station) {
    has chiller: str = "walk-in";
    override def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

walker HealthInspector {
    has violations: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Inspector entering kitchen line");
        visit [-->];
    }

    can traverse with Grill | Fryer | ColdPrep entry {
        # (1) visit log: every station, no exceptions
        self.log.append(f"visited {here.name} ({here.temp_c} C)");
        # (2) temperature check: flag > 40 C as a violation
        if here.is_violation() {
            self.violations += 1;
            print(f"[VIOLATION] {here.name} at {here.temp_c} C");
        } else {
            print(f"[OK] {here.name} at {here.temp_c} C");
        }
        visit [-->];
    }
}

with entry {
    line = [
        Grill(name="Grill-1", temp_c=210.0),
        Fryer(name="Fryer-1", temp_c=180.0),
        ColdPrep(name="Cold-1", temp_c=4.0),
        ColdPrep(name="Cold-2", temp_c=12.0)
    ];
    for st in line {
        root ++> st;
    }
    inspector = HealthInspector();
    root spawn inspector;
    print(f"Inspector logged {len(inspector.log)} visits, found {inspector.violations} violations");
}

"""Tiny dungeon crawler: a chain of rooms with a hidden treasure vault.

A Hunter walker traverses the dungeon room by room, counting how many it
has inspected, and disengages the moment it finds the treasure room so
that rooms past the vault are never visited.
"""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can search with Room entry {
        self.rooms_inspected += 1;
        if here.has_treasure {
            print(f"Treasure found in '{here.name}' after inspecting {self.rooms_inspected} room(s)!");
            print("Hunter grabs the loot and bolts for the exit.");
            disengage;
        }
        print(f"  searched '{here.name}' — empty.");
        visit [-->] else { disengage; }
    }
}

with entry {
    entry_room = Room(name="Dusty Antechamber");
    armory = Room(name="Rusted Armory");
    library = Room(name="Whispering Library");
    vault = Room(name="Sealed Vault", has_treasure=True);
    cavern = Room(name="Echoing Cavern");
    exit_gate = Room(name="Exit Gate");

    root ++> entry_room
        ++> armory
        ++> library
        ++> vault
        ++> cavern
        ++> exit_gate;

    hunter = Hunter();
    root spawn hunter;

    print(f"Final tally: hunter inspected {hunter.rooms_inspected} room(s).");
    print("Rooms past the vault: cavern, exit_gate — neither was reached.");
}

"""Road-trip playlist: tracks created inline inside connection expressions."""

node Track {
    has title: str = "";
    has artist: str = "";
    has runtime_sec: int = 0;

    def label() -> str {
        return f"{self.title} — {self.artist}";
    }
}

walker Player {
    has total_sec: int = 0;

    can start with Root entry {
        print("=== Road-trip playlist ===");
        visit [-->];
    }

    can play with Track entry {
        self.total_sec += here.runtime_sec;
        minutes = self.total_sec // 60;
        seconds = self.total_sec % 60;
        print(f"▶ Now playing: {here.label()} ({here.runtime_sec}s) "
              f"— running total {minutes}m {seconds:02d}s");
        visit [-->];
    }
}

with entry {
    root ++> Track(title="Highway Star", artist="Deep Purple", runtime_sec=372)
        ++> Track(title="Life in the Fast Lane", artist="Eagles", runtime_sec=286)
        ++> Track(title="Born to Run", artist="Bruce Springsteen", runtime_sec=270);

    root spawn Player();
}

"""Existing-project enhancement audit with drift, impact, regression, and cycle checks."""

node Requirement {
    has record_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "requirement";
    has reference: str = "";
    has drifted: bool = False;
    has impacted: bool = False;
    has passed: bool = True;
}

node Component {
    has record_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "component";
    has reference: str = "";
    has drifted: bool = False;
    has impacted: bool = False;
    has passed: bool = True;
}

node AcceptanceTest {
    has record_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "acceptance-test";
    has reference: str = "";
    has drifted: bool = False;
    has impacted: bool = False;
    has passed: bool = True;
}

node DesignDocument {
    has record_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "design-document";
    has reference: str = "";
    has drifted: bool = False;
    has impacted: bool = False;
    has passed: bool = True;
}

edge Contains { }
edge Impacts { }
edge DescribedBy { }
edge CoveredBy { }
edge DependsOn { }

walker EnhancementAuditor {
    has seen_ids: list[str] = [];
    has drift_count: int = 0;
    has impact_count: int = 0;
    has failure_count: int = 0;
    has revisit_count: int = 0;

    can begin with Root entry {
        print("Starting existing-project enhancement audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Requirement | Component | AcceptanceTest | DesignDocument entry {
        if here.record_id in self.seen_ids {
            self.revisit_count += 1;
            print(f"cycle or repeated reachability detected at {here.record_id}");
        } else {
            self.seen_ids.append(here.record_id);

            if here.drifted {
                self.drift_count += 1;
                print(f"document/code drift: {here.record_id} -> {here.reference}");
            }

            if here.impacted {
                self.impact_count += 1;
                print(f"expected impacted record: {here.record_id}");
            }

            if here.passed == False {
                self.failure_count += 1;
                print(f"regression blocks delivery: {here.record_id}");
            }

            print(f"checked {here.role}: {here.title}");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    requirement = Requirement(
        record_id="REQ-42",
        title="Add incremental document update support",
        year=2026,
        impacted=True
    );
    unrelated_requirement = Requirement(
        record_id="REQ-07",
        title="Preserve existing search behavior",
        year=2025
    );

    enhancement = Component(
        record_id="COMP-42",
        title="Incremental update engine",
        year=2026,
        impacted=True,
        reference="src/update-engine.ts"
    );
    search = Component(
        record_id="COMP-07",
        title="Existing search engine",
        year=2025,
        reference="src/search.ts"
    );

    new_test = AcceptanceTest(
        record_id="TEST-42",
        title="Incremental update acceptance test",
        year=2026,
        reference="tests/incremental-update.test.ts"
    );
    regression = AcceptanceTest(
        record_id="TEST-07",
        title="Existing search regression test",
        year=2025,
        passed=False,
        reference="tests/search-regression.test.ts"
    );

    design = DesignDocument(
        record_id="DOC-42",
        title="Enhancement design",
        year=2026,
        drifted=True,
        reference="docs/design.md:18"
    );
    baseline = DesignDocument(
        record_id="DOC-07",
        title="Search design",
        year=2025,
        reference="docs/search.md:11"
    );

    root +>:Contains:+> requirement;
    root +>:Contains:+> unrelated_requirement;

    requirement +>:Impacts:+> enhancement;
    requirement +>:DescribedBy:+> design;
    enhancement +>:CoveredBy:+> new_test;

    unrelated_requirement +>:Impacts:+> search;
    unrelated_requirement +>:DescribedBy:+> baseline;
    search +>:CoveredBy:+> regression;

    enhancement +>:DependsOn:+> search;
    search +>:DependsOn:+> enhancement;

    auditor = EnhancementAuditor();
    root spawn auditor;

    print(f"drift records: {auditor.drift_count}");
    print(f"impacted records: {auditor.impact_count}");
    print(f"regressions: {auditor.failure_count}");
    print(f"cycle revisits: {auditor.revisit_count}");

    if auditor.failure_count > 0 {
        print("delivery blocked by an independent regression check");
    } else {
        print("delivery checks passed");
    }
}

"""Kitchen line health inspection: walk each station, flag temperature
violations, and log every station visit."""

node Station {
    has name: str = "";
    has temp_c: float = 0.0;

    def is_violation() -> bool {
        return self.temp_c > 40.0;
    }
}

walker Inspector {
    has violation_count: int = 0;
    has visit_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect with Station entry {
        self.visit_log.append(here.name);
        if here.is_violation() {
            self.violation_count += 1;
            print(f"[VIOLATION] {here.name} at {here.temp_c} C");
        } else {
            print(f"[OK] {here.name} at {here.temp_c} C");
        }
        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", temp_c=180.0);
    fryer = Station(name="Fryer", temp_c=165.0);
    cold_prep = Station(name="Cold Prep", temp_c=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = Inspector();
    root spawn inspector;

    print(f"Visited {len(inspector.visit_log)} stations, "
          f"violations: {inspector.violation_count}");
    print(f"Visit log: {inspector.visit_log}");
}

"""Restaurant recommender: walk linked restaurants and filter by minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker RestaurantFinder {
    has min_rating: float = 0.0;
    has pass_label: str = "";

    can start with Root entry {
        header = "=== " + self.pass_label + " (rating >= " + str(self.min_rating) + ") ===";
        print(header);
        visit [-->];
    }

    can review with Restaurant entry {
        if here.rating >= self.min_rating {
            line = "  " + here.name + " | " + here.cuisine + " | " + str(here.rating);
            print(line);
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Restaurant(name="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sushi Nakazawa", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Joe's Pizza", cuisine="Italian", rating=3.8)
        ++> Restaurant(name="Taco Truck", cuisine="Mexican", rating=3.9)
        ++> Restaurant(name="The Corner Cafe", cuisine="American", rating=3.2);

    root spawn RestaurantFinder(min_rating=4.5, pass_label="Date night");
    root spawn RestaurantFinder(min_rating=3.5, pass_label="Casual lunch");
}

