"""Effect Language Service rollout: model the monorepo's package graph and
walk it with a diagnostician walker that fans out from `root` along
`DependsOn` edges, surfacing per-package diagnostics (missing context,
floating effects, missing yield-star, etc.) just like `@effect/tsgo` does
during a `tsc --noEmit` pass.
"""

# ----- Domain nodes ---------------------------------------------------------

node Package {
    has name: str = "";
    has uses_effect: bool = False;
    has effect_version: str = "";
    has plugin_enabled: bool = False;
    has diagnostics: list[str] = [];
}

node Toolchain {
    has name: str = "";
    has version: str = "";
}

node PluginConfig {
    has name: str = "";
    has severity: str = "error";
}

# ----- Edges ---------------------------------------------------------------

edge DependsOn { has kind: str = "runtime"; }
edge Targets { has match_pattern: str = ""; }

# ----- Walker --------------------------------------------------------------

walker Diagnostician {
    has visited: list[str] = [];
    has report_lines: list[str] = [];

    can start with Root entry {
        print("Starting Effect Language Service diagnostics sweep");
        visit [-->];
    }

    can scan_toolchain with Toolchain entry {
        line = f"[toolchain] {here.name} @ {here.version}";
        self.report_lines.append(line);
        print(line);
        visit [-->];
    }

    can scan_plugin with PluginConfig entry {
        sev = here.severity;
        line = f"[plugin]    {here.name} severity={sev}";
        self.report_lines.append(line);
        print(line);
        visit [-->];
    }

    can audit_package with Package entry {
        if here.name in self.visited {
            note = f"[skip]      {here.name} already audited";
            print(note);
            visit [-->] else { disengage; }
        }
        self.visited.append(here.name);

        tag = "EFFECT" if here.uses_effect else "plain";
        head = f"[package]   {here.name} ({tag}, effect={here.effect_version})";
        self.report_lines.append(head);
        print(head);

        if here.uses_effect and not here.plugin_enabled {
            warn = f"            ! {here.name} uses Effect but plugin NOT enabled";
            self.report_lines.append(warn);
            print(warn);
        }

        if here.diagnostics {
            for d in here.diagnostics {
                diag_line = f"            - {d}";
                self.report_lines.append(diag_line);
                print(diag_line);
            }
        }

        visit [->:DependsOn:->];
    }
}

# ----- Demo graph ----------------------------------------------------------

with entry {
    root ++> Toolchain(name="typescript", version="7.0-rc")
           ++> PluginConfig(name="@effect/language-service", severity="error");

    pkg_mg = Package(
        name="@ethang/markdown-generator",
        uses_effect=True,
        effect_version="3.22.0",
        plugin_enabled=True,
        diagnostics=["floatingEffect at src/gen.ts:42"]
    );
    pkg_sc = Package(
