    );
    pkg_plain = Package(
        name="@ethang/utils",
        uses_effect=False,
        effect_version="",
        plugin_enabled=False,
        diagnostics=[]
    );

    root +>:DependsOn(kind="dev"):+> pkg_mg;
    root +>:DependsOn(kind="dev"):+> pkg_sc;
    root +>:DependsOn(kind="dev"):+> pkg_st;
    root +>:DependsOn(kind="dev"):+> pkg_plain;

