    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Audit begins");
        visit [-->];
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "HALT";
        } elif not here.valid {
            action = "SKIP";
        } else {
            action = "OK";
        }
        print(f"[{action}] {here.label} amount={here.amount}");
        if here.fraud {
            disengage;
        }
        if not here.valid {
            # skip just this order; keep walking the rest of the chain
            visit [-->] else { disengage; }
        }
        visit [-->];
    }
}

