"""Milestone pipeline: manifest-controlled ordering of setup/verify/generate
phases. Demonstrates how typed edges replace numeric-prefix sequencing so that
reordering, insertion, and invalidation become graph operations rather than
filesystem glob-and-sort plumbing."""

node Milestone {
    has name: str = "";
    has prompt: str = "";
    has verify: str = "";
    has generate: str = "";
    has hint: str = "";
    has completed: bool = False;
}

node Manifest {
    has sequence: list[str] = [];
    has completed_set: list[str] = [];
}

edge Sequence { has position: int = 0; }
edge DependsOn { }
edge Invalidates { }
edge RunsBefore { }

walker Setup {
    has visited: list[str] = [];

    can begin with Root entry {
        visit [->:Sequence:->];
    }

    can prepare with Manifest entry {
        print(f"--- setup hook: reading manifest with {len(here.sequence)} entries ---");
        visit [->:Sequence:->];
    }

    can precheck with Milestone entry {
        self.visited.append(here.name);
        status = "DONE" if here.completed else "PENDING";
        print(f"  setup: {here.name} -> {status}");
        visit [->:DependsOn:->];
    }
}

walker Runner {
    has order: list[str] = [];
    has log: list[str] = [];

    can begin with Root entry {
        visit [->:Sequence:->];
    }

    can dispatch with Manifest entry {
        print(f"--- runner: dispatching in declared order ---");
        visit [->:Sequence:->];
    }

    can run with Milestone entry {
        # dependency check: ensure any DependsOn targets are already done
        deps = [here];
        visit [->:DependsOn:->];
        for d in deps {
            if d.completed {
                self.log.append(f"dep {d.name} ok");
            } else {
                self.log.append(f"BLOCKED by {d.name}");
                return;
            }
        }
        self.order.append(here.name);
        print(f"  run: {here.name} (verify={here.verify})");
        here.completed = True;
        visit [->:RunsBefore:->];
    }

    can propagate with Milestone entry {
        # an Invalidates edge means: when this milestone completed, any
        # successor linked by Invalidates must drop its completed flag.
        here.completed = False;
        self.log.append(f"INVALIDATED {here.name}");
    }

    can finish with Manifest entry {
        print(f"--- runner done ---");
        print(f"order = {self.order}");
    }
}

walker Auditor {
    has reachable: list[str] = [];

    can begin with Root entry {
        print(f"--- auditor: forward reachability from sequence ---");
        visit [->:Sequence:->];
    }

    can count with Manifest entry {
        visit [->:Sequence:->];
    }

    can collect with Milestone entry {
        self.reachable.append(here.name);
        # guarded forward step: avoid revisiting
        if here.completed {
            visit [->:Sequence:->];
        } else {
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    manifest = Manifest(sequence=["scaffold", "pre-commit", "config", "http", "tests"]);

    scaffold = Milestone(
        name="scaffold",
        prompt="scaffold prompt",
        verify="bash verify.sh",
        generate="python generate.py",
        hint="start by creating pyproject.toml",
        completed=False,
    );
    precommit = Milestone(
        name="pre-commit",
        prompt="pre-commit prompt",
        verify="bash verify.sh",
        generate="python generate.py",
        hint="add .pre-commit-config.yaml",
        completed=False,
    );
    config_m = Milestone(
        name="config",
        prompt="config prompt",
        verify="bash verify.sh",
        hint="dynaconf boundary",
        completed=False,
    );
    http_m = Milestone(
        name="http",
        prompt="http prompt",
        verify="bash verify.sh",
        completed=False,
    );
    tests_m = Milestone(
        name="tests",
        prompt="tests prompt",
        verify="bash verify.sh",
        completed=False,
    );

    root ++> manifest;

    # typed Sequence edges with payload position preserve manifest order
    # without numeric prefixes on the directory names
    manifest +>:Sequence(position=0):+> scaffold;
    manifest +>:Sequence(position=1):+> precommit;
    manifest +>:Sequence(position=2):+> config_m;
    manifest +>:Sequence(position=3):+> http_m;
    manifest +>:Sequence(position=4):+> tests_m;

    # domain relationships carried as typed edges
    precommit +>:DependsOn:+> scaffold;
    config_m +>:DependsOn:+> precommit;
    http_m +>:DependsOn:+> config_m;
    tests_m +>:DependsOn:+> http_m;

    # invalidation: editing config invalidates downstream tests
    config_m +>:Invalidates:+> tests_m;

    # runner precedence: setup runs before the milestone verify
    scaffold +>:RunsBefore:+> precommit;
    precommit +>:RunsBefore:+> config_m;

    # --- demo 1: setup hook walks all sequence entries ---------------
    s = Setup();
    root spawn s;
    print(f"setup hook visited: {s.visited}");
    print();

    # --- demo 2: manifest-driven run order with cascading deps -------
    r = Runner();
    root spawn r;
    print(f"runner log:");
    for `entry in r.log {
        print(f"  - {`entry}");
    }
    print();

    # --- demo 3: invalidation propagation ----------------------------
    print("triggering config_m -> tests_m invalidation:");
    config_m +>:Invalidates:+> http_m;
    print(f"tests_m.completed after invalidation = {tests_m.completed}");
    print();

    # --- demo 4: reachability audit ----------------------------------
    a = Auditor();
    root spawn a;
    print(f"auditor reachable in order: {a.reachable}");
}

"""UDLM profile conformance walker.

Models the issue's core scenario: a UDLM mechanism (a profile record shape
with a `contains` bundle of references plus settings) decoupled from a
named Profile Set artifact. The walker audits which profiles an estate
declares against which profile-set version it pins, then cascades
invalidation down `contains` chains when a referenced sub-bundle is
missing or stale.
"""

node Mechanism {
    has spec_version: str = "";
    has profile_set_ref: str = "";
    has profile: str = "";
    has valid: bool = True;
}

node ProfileSet {
    has set_id: str = "";
    has set_version: str = "";
    has posture_count: int = 0;
}

node Posture {
    has name: str = "";
    has kind: str = "";
}

node Reference {
    has target: str = "";
    has stale: bool = False;
}

edge Conforms {
    has since: str = "";
}

edge Contains {
    has ordinal: int = 0;
}

edge Defines {
    has slot: str = "";
}

edge References {
    has optional: bool = False;
}

walker ProfileAuditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect with Mechanism entry {
        m = here;
        self.findings.append(
            f"udlm={m.spec_version} set={m.profile_set_ref} profile={m.profile}"
        );
        if m.spec_version == "" or m.profile_set_ref == "" {
            m.valid = False;
            self.findings.append("  FAIL: missing udlm_version or profile_set");
            disengage;
        }
        visit [-->];
    }

    can cross_set with ProfileSet entry {
        s = here;
        if s.set_version == "" {
            self.findings.append(f"  FAIL: profile set {s.set_id} has no version");
        } else {
            self.findings.append(
                f"  OK: profile set {s.set_id}@{s.set_version} "
                f"defines {s.posture_count} postures"
            );
        }
        visit [-->];
    }

    can check_posture with Posture entry {
        p = here;
        self.findings.append(f"  posture: {p.name} ({p.kind})");
        visit [-->];
    }

    can invalidate_references with Reference entry {
        r = here;
        if r.stale {
            r.target = "[INVALIDATED]";
            self.findings.append(f"  CASCADE: reference -> {r.target} marked stale");
        }
        visit [-->];
    }
}

with entry {
    fsi_set = ProfileSet(set_id="udlm/profiles", set_version="2.0", posture_count=6);
    fsi_posture = Posture(name="fsi", kind="regulated");
    sovereign_posture = Posture(name="sovereign", kind="data-sovereignty");

    estate = Mechanism(
        spec_version="1.0",
        profile_set_ref="udlm/profiles@2.0",
        profile="fsi"
    );

    ref_audit = Reference(target="audit-trail");
    ref_retention = Reference(target="retention-7y");
    ref_retention.stale = True;
    ref_provider = Reference(target="attestation-gated");

    root +>:Conforms(since="2024-01"):+> estate;
    estate +>:Defines(slot="profile"):+> fsi_set;
    fsi_set +>:Defines(slot="posture"):+> fsi_posture;
    fsi_set +>:Defines(slot="posture"):+> sovereign_posture;
    estate +>:Contains(ordinal=1):+> ref_audit;
    estate +>:Contains(ordinal=2):+> ref_retention;
    estate +>:Contains(ordinal=3):+> ref_provider;

    auditor = ProfileAuditor();
    root spawn auditor;

    print("=== UDLM conformance audit ===");
    for note in auditor.findings {
        print(note);
    }
    print(f"estate.valid = {estate.valid}");
    print(f"retention ref after cascade = {ref_retention.target}");
}

