"""Data center clearance walk: technicians traverse a corridor of server rooms,
are granted or denied based on their clearance level vs the room's required
level, and disengage on first denial. Reports rooms reached per technician."""

node Room {
    has name: str = "";
    has required_level: int = 0;
}

node Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied_at: str = "";
}

walker TechWalker {
    has tech: Technician = Technician();

    can start with Root entry {
        visit [-->];
    }

    can enter with Technician entry {
        self.tech = here;
        self.tech.rooms_reached = 0;
        self.tech.denied_at = "";
        print(f"Technician {self.tech.name} (clearance {self.tech.clearance}) entering corridor");
        visit [-->];
    }

    can audit with Room entry {
        if self.tech.clearance >= here.required_level {
            self.tech.rooms_reached += 1;
            print(f"  GRANTED: {here.name} (needs {here.required_level})");
            visit [-->];
        } else {
            self.tech.denied_at = here.name;
            print(f"  DENIED at {here.name} (needs {here.required_level}, has {self.tech.clearance}); walkthrough ends");
            disengage;
        }
    }
}

with entry {
    r1 = Room(name="Server Room A", required_level=1);
    r2 = Room(name="Server Room B", required_level=2);
    r3 = Room(name="Secure Vault", required_level=5);
    r4 = Room(name="Cold Storage", required_level=3);
    r5 = Room(name="Lobby", required_level=1);

    root ++> r1 ++> r2 ++> r3 ++> r4 ++> r5;

    alice = Technician(name="Alice", clearance=3);
    bob = Technician(name="Bob", clearance=6);
    carol = Technician(name="Carol", clearance=1);

    TechWalker(tech=alice) spawn root;
    TechWalker(tech=bob) spawn root;
    TechWalker(tech=carol) spawn root;

    print(f"Alice reached {alice.rooms_reached} rooms");
    print(f"Bob reached {bob.rooms_reached} rooms");
    print(f"Carol reached {carol.rooms_reached} rooms");
}

"""Project every ancestor collection into a document's transitive collection field."""

node Document {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has field_name: str = "collection";
    has transitive: bool = True;
    has projected_collections: list[str] = [];
}

node Collection {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

edge PartOf {
    has predicate: str = "schema:isPartOf";
}

walker AncestorProjector {
    has seen: list[Collection] = [];
    has active_document: Document | None = None;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can project with Document entry {
        here.projected_collections = [];
        self.seen = [];
        self.active_document = here;
        print(f"Projecting {here.title} through {here.field_name}+");

        if here.transitive {
            visit [->:PartOf:->] else {
                disengage;
            }
        }
    }

    can collect with Collection entry {
        if here in self.seen {
            print(f"Cycle detected at {here.title}; stopping this branch");
            disengage;
        } else {
            self.seen.append(here);

            if self.active_document is not None {
                self.active_document.projected_collections.append(here.title);
                print(f"Collection field: {self.active_document.projected_collections}");
            }

            visit [->:PartOf:->] else {
                disengage;
            }
        }
    }
}

with entry {
    document = Document(title="The Jewish Bride", year=1669);
    late_works = Collection(
        title="Rembrandt's late works",
        slug="late-works"
    );
    dutch_masters = Collection(
        title="Dutch Masters",
        slug="dutch-masters"
    );
    masterpieces = Collection(
        title="Masterpieces",
        slug="masterpieces"
    );

    root ++> document;
    document +>:PartOf:+> late_works;
    late_works +>:PartOf:+> dutch_masters;
    dutch_masters +>:PartOf:+> masterpieces;

    root spawn AncestorProjector();
}

"""Knowledge-graph evaluation model for WISPACE retrieval.

This is a discovery/architecture demo (no graph database implementation).
It models the core domain: knowledge entities as nodes, typed relationships
as edges, a provenance/version trail, and a walker that evaluates retrieval
scope while enforcing untrusted-knowledge isolation rules.
"""

# Provenance + freshness live on the relationship itself, so they travel
# with the edge wherever the graph is traversed.
edge Related {
    has weight: float = 0.0;
    has source: str = "";
    has version: str = "";
    has confidence: float = 0.0;
    has fresh: bool = True;
    has trustworthy: bool = True;
}

# Base node: every knowledge entry exposes a domain-kind label and a
# freshness signal that the evaluator walker can compare uniformly.
node KnowledgeItem {
    has kind: str = "";
    has title: str = "";
    has summary: str = "";
    has fresh: bool = True;
}

node Concept(KnowledgeItem) {
    has definition: str = "";
}

node Prerequisite(KnowledgeItem) {
    has skill_level: int = 0;
}

node Constraint(KnowledgeItem) {
    has rule: str = "";
}

node Source(KnowledgeItem) {
    has uri: str = "";
    has authority: float = 0.0;
}

# Tenant boundary — every knowledge item belongs to exactly one tenant.
# Server-derived learner facts NEVER appear inside the knowledge graph.
node Tenant {
    has tenant_id: str = "";
}

walker Evaluator {
    has tenant_id: str = "";
    has visited: list[str] = [];
    has depth_cap: int = 4;
    has cycle_detected: bool = False;
    has depth: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can scope with Tenant entry {
        # Bind tenant context, then walk into the tenant's knowledge subgraph.
        if here.tenant_id != self.tenant_id {
            print(f"[SKIP] tenant mismatch: walker={self.tenant_id}, node={here.tenant_id}");
            disengage;
        }
        print(f"[TENANT] scoping to {here.tenant_id}");
        visit [-->];
    }

    # Union ability: every knowledge-item subclass exposes kind/title/fresh,
    # so we can score it with a single routine instead of four duplicates.
    can score with Concept | Prerequisite | Constraint | Source entry {
        self.visited.append(here.title);

        trust = "TRUSTED" if here.fresh else "STALE";
        print(f"  [{trust}] {here.kind}: {here.title}");

        # Stop descending when the item is stale — untrusted knowledge cannot
        # be propagated further down the traversal.
        if not here.fresh {
            print("    -> halting descent (stale knowledge)");
            disengage;
        }

        # Forward traverse only along Related edges whose own freshness and
        # trust flags are still true. This is the typed-edge filter that
        # replaces the hand-rolled adjacency walk.
        next_nodes = [here ->:Related:->];
        if not next_nodes {
            disengage;
        }
        self.depth += 1;
        if self.depth > self.depth_cap {
            print("    -> depth cap reached");
            disengage;
        }
        visit next_nodes;
    }
}

with entry {
    # Two tenants — proves the walker only walks its own slice.
    acme = Tenant(tenant_id="acme");
    globex = Tenant(tenant_id="globex");

    # Build the knowledge subgraph for tenant acme.
    prereq = Prerequisite(kind="prerequisite", title="linear-algebra",
                          summary="vectors, matrices, eigenvalues",
                          skill_level=2);
    concept = Concept(kind="concept", title="gradient-descent",
                      summary="iterative optimization method",
                      definition="theta -= lr * grad");
    constraint = Constraint(kind="constraint", title="non-convexity",
                           rule="must check convexity before applying GD");
    src = Source(kind="source", title="boyd-vandenberghe",
                 uri="https://example.org/bv.pdf", authority=0.9);

    # Wire knowledge under acme.
    acme ++> prereq
        +>:Related(weight=0.8, source="curriculum-map", version="2024-Q1",
                   confidence=0.9, fresh=True, trustworthy=True):+> concept;
    prereq +>:Related(weight=0.5, source="syllabus", version="2024-Q1",
                      confidence=0.7, fresh=True, trustworthy=True):+> constraint;
    concept +>:Related(weight=0.4, source="textbook", version="2023-1",
                       confidence=0.6, fresh=False, trustworthy=False):+> src;

    # A second, completely isolated tenant slice (must NOT be reached).
    globex_concept = Concept(kind="concept", title="secret-tenant-thing",
                             summary="must never leak",
                             definition="REDACTED");
    globex ++> globex_concept;

    # Spawn the evaluator on acme's slice only.
    root ++> acme;
    root spawn Evaluator(tenant_id="acme", depth_cap=4);

    print(f"visited titles: {Evaluator().visited}");
}

