"""Restaurant recommender: find eateries by minimum rating with a finder walker."""

node Restaurant {
    has title: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker RestaurantFinder {
    has min_rating: float = 4.5;

    can start with Root entry {
        visit [-->];
    }

    can review with Restaurant entry {
