"""SDD lifecycle: model the verify-report identity cycle as a graph and walk it.

The bug: a passing verify-report references a predecessor candidate, lineage,
and binding. Refreshing the report changes the workspace candidate, which
forces a new review, which can introduce a correction, which stales the
report again — an unbounded verify->review->verify cycle.

We model the lifecycle as nodes (VerifyReport, ReviewAuthority, Binding,
Archive) connected by typed edges (Refreshes, Stales, Binds, Clears) and
walk the graph to detect the cycle. The walker proves that when a report
references a stale candidate, the report must be treated as identity-neutral
once the bound authority matches the current binding — breaking the cycle.
"""

node VerifyReport {
    has title: str = "";
    has candidate_ref: str = "";
    has lineage_ref: str = "";
    has binding_ref: str = "";
    has evidence_hash: str = "";
}

node ReviewAuthority {
    has lineage: str = "";
    has approved: bool = False;
}

node SDDBinding {
    has revision: str = "";
}

node Archive {
    has ready: bool = False;
}

edge Refreshes {
    has reason: str = "";
}

edge Stales {
    has kind: str = "";
}

edge Binds {
}

edge Clears {
}

walker LifecycleAuditor {
    has target_lineage: str = "";
    has target_binding: str = "";
    has cycle_detected: bool = False;
    has steps: int = 0;
    has max_steps: int = 20;
    has seen: list[str] = [];

    can start with Root entry {
        print(f"Auditing SDD lifecycle for lineage={self.target_lineage}");
        visit [-->];
    }

    can audit_report with VerifyReport entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            self.cycle_detected = True;
            print("[ABORT] step budget exceeded — identity cycle confirmed");
            disengage;
        }
        report_id = f"{here.title}|{here.candidate_ref}|{here.lineage_ref}";
        if report_id in self.seen {
            self.cycle_detected = True;
            print(f"[CYCLE] revisited report {here.title} — verify->review->verify loop");
            disengage;
        }
        self.seen.append(report_id);
        print(f"[REPORT] {here.title} ref={here.candidate_ref} lineage={here.lineage_ref}");

        # If the report's lineage matches the approved authority AND its
        # binding matches the active binding, the report is identity-neutral
        # and the archive path is reachable — stop here, no refresh needed.
        auth_match = False;
        bind_match = False;
        for n in [-->] {
            if isinstance(n, ReviewAuthority) and n.lineage == here.lineage_ref and n.approved {
                auth_match = True;
            }
            if isinstance(n, SDDBinding) and n.revision == here.binding_ref {
                bind_match = True;
            }
        }
        if auth_match and bind_match {
            print(f"[OK] {here.title} is identity-neutral against current authority+binding");
            visit [here ->:Clears:->];
        } else {
            print(f"[STALE] {here.title} still references predecessor — refresh would re-open review");
            visit [here ->:Stales:->];
        }
    }

    can follow_stale with VerifyReport entry {
        print(f"  -> following stale chain to refreshed report");
        visit [-->];
    }

    can follow_clear with Archive entry {
        print(f"[ARCHIVE] archive ready = {here.ready}");
        disengage;
    }

    can follow_auth with ReviewAuthority entry {
        print(f"  -> authority lineage={here.lineage} approved={here.approved}");
        visit [-->];
    }

    can follow_bind with SDDBinding entry {
        print(f"  -> binding revision={here.revision}");
        visit [-->];
    }
}

with entry {
    # A passing verify-report whose references still point at a predecessor.
    stale_report = VerifyReport(
        title="verify-report-attempt-33",
        candidate_ref="candidate-predecessor",
        lineage_ref="review-unit2-verify-refresh-recovery-1050c6f4",
        binding_ref="sha256:d944d9efc3e38e8e625bd1fcb3ec3b3d5780859e658d935384db1dba19d8d73e",
        evidence_hash="sha256:2952d353df99704b6bbc2dc2824b31a6df0832de6b8d85d127e3f11869723c32",
    );

    # A refreshed report that would be created if the maintainer tried to
    # recover — this is the next link in the cycle.
    refreshed_report = VerifyReport(
        title="verify-report-attempt-33-refreshed",
        candidate_ref="candidate-after-refresh",
        lineage_ref="review-unit2-verify-refresh-recovery-1050c6f4",
        binding_ref="sha256:d944d9efc3e38e8e625bd1fcb3ec3b3d5780859e658d935384db1dba19d8d73e",
        evidence_hash="sha256:2952d353df99704b6bbc2dc2824b31a6df0832de6b8d85d127e3f11869723c32",
    );

    approved = ReviewAuthority(
        lineage="review-unit2-verify-refresh-recovery-1050c6f4",
        approved=True,
    );

    bound = SDDBinding(
        revision="sha256:d944d9efc3e38e8e625bd1fcb3ec3b3d5780859e658d935384db1dba19d8d73e",
    );

    archive = Archive(ready=True);

    root ++> stale_report;
    stale_report +>:Stales(kind="predecessor-candidate"):+> refreshed_report;
    refreshed_report +>:Stales(kind="predecessor-candidate"):+> stale_report;
    stale_report +>:Binds:+> bound;
    stale_report +>:Binds:+> approved;
    approved +>:Clears:+> archive;

    auditor = LifecycleAuditor(
        target_lineage="review-unit2-verify-refresh-recovery-1050c6f4",
        target_binding="sha256:d944d9efc3e38e8e625bd1fcb3ec3b3d5780859e658d935384db1dba19d8d73e",
    );
    root spawn auditor;
    print(f"\nresult: cycle_detected={auditor.cycle_detected} steps={auditor.steps}");
}

"""Workflowy MCP migration demo: model the stateless MCP handler refactor.

The real issue replaces a stateful Durable Object (``WorkflowyMCP``) with a
stateless ``createMcpHandler`` factory.  The interesting graph problem is the
*tool registry*: nine tools depend on each other (some call others internally)
and share two resources (the D1 mirror ``DB`` and the Workflowy ``API_KEY``).
Cascade teardown of the old DO must drop every tool registration so a fresh
factory can rebuild them in a known order.  We model that as native Jac
nodes/edges and walk it.
"""

node Tool {
    has name: str = "";
    has schema_wrapped: bool = False;
    has deprecated_overload: bool = False;
    has uses_db: bool = True;
    has uses_api_key: bool = True;
}

node Resource {
    has name: str = "";
    has kind: str = "";
}

node LegacyDO {
    has class_name: str = "";
    has deployed: bool = True;
}

edge Registers {
    has order: int = 0;
}

edge Dependson {}

edge MountedOn {}

walker CascadeAudit {
    has visited: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("MCP 2026-07-28 migration audit starting...");
        visit [-->];
    }

    can audit_tool with Tool entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            print(f"  cycle hit on tool {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        status = "wrapped" if here.schema_wrapped else "raw(deprecated)";
        print(f"  tool[{here.name}] schema={status}");
        visit [->:Registers:->];
    }

    can audit_resource with Resource entry {
        print(f"  resource[{here.name}] kind={here.kind}");
        visit [->:MountedOn:->];
    }

    can audit_legacy with LegacyDO entry {
        print(f"  legacy DO class={here.class_name} deployed={here.deployed}");
        print("  -> must run wrangler migration with deleted_classes before teardown");
        visit [->:Registers:->];
    }
}

walker CascadeTeardown {
    can start with Root entry {
        print("Cascade teardown: dropping every tool registration on the legacy DO...");
        visit [->:Registers:->];
    }

    can drop_tool with Tool entry {
        print(f"  unregistering tool {here.name}");
        here.schema_wrapped = False;
        here.deprecated_overload = False;
        visit [->:Registers:->];
    }

    can drop_legacy with LegacyDO entry {
        print(f"  destroying DO class {here.class_name}");
        here.deployed = False;
        visit [->:Registers:->];
    }
}

walker RebuildFactory {
    has wired: list[str] = [];

    can start with Root entry {
        print("Rebuilding stateless handler: createMcpHandler(createServer)");
        visit [->:MountedOn:->];
    }

    can rewire with Resource entry {
        print(f"  wiring resource {here.name} ({here.kind}) into factory");
        visit [->:MountedOn:->];
    }

    can retag_tool with Tool entry {
        self.wired.append(here.name);
        print(f"  re-registering {here.name} with z.object() wrapper");
        visit [-->];
    }
}

with entry {
    db = Resource(name="DB", kind="d1_databases");
    api_key = Resource(name="WORKFLOWY_API_KEY", kind="secret");
    oauth_kv = Resource(name="OAUTH_KV", kind="kv_namespaces");

    legacy = LegacyDO(class_name="WorkflowyMCP", deployed=True);

    search_nodes = Tool(name="search_nodes");
    sync_now = Tool(name="sync_now");
    get_node = Tool(name="get_node");
    update_node = Tool(name="update_node");
    delete_node = Tool(name="delete_node");

    # Register order is observable (matches the v1 init() sequence).
    legacy +>:Registers(order=1):+> search_nodes;
    legacy +>:Registers(order=2):+> get_node;
    legacy +>:Registers(order=3):+> update_node;
    legacy +>:Registers(order=4):+> delete_node;
    legacy +>:Registers(order=5):+> sync_now;

    # Resource mounting (typed edges carry meaning here).
    db +>:MountedOn:+> search_nodes;
    db +>:MountedOn:+> get_node;
    db +>:MountedOn:+> update_node;
    db +>:MountedOn:+> delete_node;
    api_key +>:MountedOn:+> sync_now;
    oauth_kv +>:MountedOn:+> legacy;

    # Internal call edges model tool-to-tool dependencies.
    search_nodes +>:Dependson:+> get_node;
    update_node +>:Dependson:+> get_node;

    root ++> legacy ++> db ++> api_key ++> oauth_kv;
    root ++> search_nodes ++> get_node ++> update_node ++> delete_node ++> sync_now;

    root spawn CascadeAudit();
    print("");
    root spawn CascadeTeardown();
    print("");
    root spawn RebuildFactory();
}

