node Member {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
}

edge Contains {
    has label: str = "";
}

edge Predecessor {
    has relation: str = "";
}

edge Includes {
    has position: int = 0;
}

walker FrontierAuditor {
    has depth: int = 0;
    has max_depth: int = 5;
    has visited_frontiers: int = 0;

    can start with Root entry {
        print("Starting frontier ancestry audit");
        visit [-->] else {
            disengage;
        }
    }

    can open_session with Session entry {
        print(f"Session: {here.title} ({here.year})");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can audit_frontier with Frontier entry {
        if (self.depth >= self.max_depth) {
            print(f"Depth guard stopped ancestry walk at {here.title}");
            disengage;
