        self.visited_frontiers = self.visited_frontiers + 1;
        status = "divergent" if here.divergent else "consistent";
        print(f"Frontier {here.title}: {here.member_count} members, {status}");

        self.depth = self.depth + 1;
        visit [->:Predecessor:->] else {
            disengage;
        }
    }
}

