"""Effect-native agent runs modeled as a typed dependency graph."""

node Agent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has agent_id: str = "";
}

node Run {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_id: str = "";
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has invalidated: bool = False;
}

edge Hosts { }
edge Starts { }
edge Includes { }
edge DependsOn {
    has required: bool = True;
}

walker DependencyAudit {
    has seen_ids: list[str] = [];
    has execution_order: list[str] = [];
    has invalidated_ids: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        print("Auditing the agent run graph");
        visit [->:Hosts:->] else { disengage; }
    }

    can announce with Agent | Run entry {
        print(f"Entering {here.title}");
        visit [-->];
    }

    can order_task with Task entry {
        if here.task_id in self.seen_ids {
            self.cycle_found = True;
            print(f"Cycle guard: {here.task_id} was already reached");
            return;
        }

        self.seen_ids.append(here.task_id);
        visit [->:DependsOn:->] else { disengage; }

        if here.invalidated {
            self.invalidated_ids.append(here.task_id);
            print(f"Invalidated task: {here.task_id}");
        } else {
            self.execution_order.append(here.task_id);
            print(f"Dependency-ready task: {here.task_id}");
        }
    }

    can summarize with Root exit {
        report {
            "execution_order": self.execution_order,
            "invalidated": self.invalidated_ids,
            "cycle_found": self.cycle_found
        };
    }
}

with entry {
    agent = Agent(title="Coding Agent", agent_id="agent-7");
    run = Run(title="Generalist v1 run", run_id="run-42");
    plan = Task(title="Plan", task_id="task-plan");
    implement = Task(title="Implement", task_id="task-implement");
    verify = Task(title="Verify", task_id="task-verify", invalidated=True);

    root +>:Hosts:+> agent;
    agent +>:Starts:+> run;
    run +>:Includes:+> plan;
    run +>:Includes:+> implement;
    run +>:Includes:+> verify;
    implement +>:DependsOn:+> plan;
    verify +>:DependsOn:+> implement;
    plan +>:DependsOn:+> verify;

    audit = DependencyAudit();
    root spawn audit;
    print(f"Execution order: {audit.execution_order}");
    print(f"Invalidated: {audit.invalidated_ids}; cycle detected: {audit.cycle_found}");
}

"""Docker doctor scenario graph: model diagnostic stacks and walk verdicts.

Models a small Docker/MCP scenario corpus: stacks, services, diagnostics, and
scenarios connected by typed edges. A walker descends the graph, collecting
verdicts for each scenario and reporting any blocking findings so reviewers can
see whether a fixture is healthy or intentionally broken.
"""

