"""Codex gateway ownership audit with typed graph traversal and cycle protection."""

node GatewaySession {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
}

node CodexThread {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has thread_id: str = "";
    has writer_pid: int = 0;
    has writer_active: bool = False;
    has resume_allowed: bool = True;
    has audited: bool = False;
}

node Turn {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sequence: int = 0;
    has completed: bool = False;
    has audited: bool = False;
}

edge OwnsThread {
    has writer_pid: int = 0;
}

edge ContainsTurn {
    has ordinal: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

walker OwnershipAudit {
    has expected_pid: int = 0;
    has visited_count: int = 0;
    has cycle_count: int = 0;
    has refused_resume: int = 0;

    can start with Root entry {
        print("Starting gateway ownership audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_session with GatewaySession entry {
        print(f"Session {here.session_id} is reachable");
        visit [->:OwnsThread:->] else {
            disengage;
        }
    }

    can inspect_thread with CodexThread entry {
        if here.audited {
            self.cycle_count += 1;
            print(f"Cycle or duplicate thread visit: {here.thread_id}");
            disengage;
        } else {
            here.audited = True;
            self.visited_count += 1;

            if here.writer_active {
                if here.writer_pid == self.expected_pid {
                    print(f"Writer {here.writer_pid} owns {here.thread_id}");
                } else {
                    here.resume_allowed = False;
                    self.refused_resume += 1;
                    print(f"Resume refused for {here.thread_id}: active writer {here.writer_pid}");
                }
            } else {
                print(f"{here.thread_id} has no active writer");
            }

            visit [->:ContainsTurn:->] else {
                disengage;
            }
        }
    }

    can inspect_turn with Turn entry {
        if here.audited {
            self.cycle_count += 1;
            print(f"Cycle or duplicate turn visit at sequence {here.sequence}");
            disengage;
        } else {
            here.audited = True;
            self.visited_count += 1;

            status = "complete" if here.completed else "in progress";
            print(f"Turn {here.sequence}: {status}");
            visit [->:DependsOn:->] else {
