"""Performance analytics dependency graph (Phase-3 placeholder).

Models the scheduling scenario from issue #46: analytics cannot start until
Phase-1 is complete, the spec is approved, and the workspace boundary plus
application history are in place. The walker performs the reachability /
dependency-ordering traversal that the issue complains about being
hand-rolled.
"""

node Phase {
    has title: str = "";
    has complete: bool = False;
}

node Spec {
    has title: str = "";
    has approved: bool = False;
    has owner: str = "";
    has reviewer: str = "";
}

node Workspace {
    has name: str = "";
    has boundary_defined: bool = False;
}

node History {
    has source_issue: int = 0;
    has retained: bool = False;
}

node Prerequisite {
    has label: str = "";
    has satisfied: bool = False;
}

node Analytics {
    has title: str = "";
}

edge DependsOn { }
edge Unlocks { }

walker PrerequisiteChecker {
    has issues: list[str] = [];
    has ok: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can scan with Analytics entry {
        print(f"Evaluating analytics feature: {here.title}");
        visit [->:DependsOn:->];
    }

    can check with Prerequisite entry {
        label = here.label;
        if here.satisfied {
            print(f"  [OK] {label}");
        } else {
            self.ok = False;
            self.issues.append(f"Prerequisite '{label}' not satisfied");
        }
    }
}

walker SpecInspector {
    has notes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can review with Spec entry {
        if here.approved {
            print(f"  [OK] Spec '{here.title}' approved");
        } else {
            note = f"Spec '{here.title}' not approved (owner={here.owner}, reviewer={here.reviewer})";
            self.notes.append(note);
        }
    }
}

with entry {
    p1 = Phase(title="Phase 1", complete=True);
    spec = Spec(title="Permit Performance Analytics", approved=False, owner="jzeng151", reviewer="unassigned");
    workspace = Workspace(name="pop-engine", boundary_defined=True);
    history = History(source_issue=17, retained=True);
    analytics = Analytics(title="F-501 Permit Performance Analytics");

    # Build a typed DependsOn fan-out from analytics to each prerequisite node.
    analytics +>:DependsOn:+> Prerequisite(label="Phase 1 complete", satisfied=True);
    analytics +>:DependsOn:+> Prerequisite(label="Spec approved", satisfied=False);
    analytics +>:DependsOn:+> Prerequisite(label="Workspace boundary defined", satisfied=True);
    analytics +>:DependsOn:+> Prerequisite(label="Application history retained (#17)", satisfied=True);

    # The spec lives off the spec-prerequisite node so the SpecInspector
    # walker can traverse it independently.
    spec_prereq = Prerequisite(label="Spec approved", satisfied=False);
    spec_prereq +>:DependsOn:+> spec;

    p1 +>:Unlocks:+> analytics;

    root ++> analytics ++> spec_prereq;

    checker = PrerequisiteChecker();
    root spawn checker;

    inspector = SpecInspector();
    root spawn inspector;

    print("");
    if checker.ok and not inspector.notes {
        print("All prerequisites satisfied — analytics may proceed.");
    } else {
        print("Analytics blocked. Outstanding prerequisites:");
        for note in checker.issues {
            print(f"  - {note}");
        }
        for note in inspector.notes {
            print(f"  - {note}");
        }
    }
}
