"""Maven transitive dependency resolution respecting repository definitions.

Models the MNG-6397 scenario: a pom.xml declares its own repositories, but
transitive resolution must NOT silently fall back to repositories defined in
ancestor poms. A walker climbs the parent-pom tree to collect declared repos,
then another walker audits transitive dependencies and flags any that try to
resolve through a repository that wasn't declared by the originating pom.

Entities:
- Project   : a Maven project / pom (has g/a/v coordinates)
- Repo      : a <repository> declaration (has id/url/enabled flags)
- Artifact  : a declared dependency (groupId:artifactId coordinates)
- Requires  : typed edge carrying a scope label; the dependency relation

Walks:
- AncestorClimber : collects every <repository> visible at the project by
                    following Requires edges UP to parent poms, merging
                    repos with the originating pom's own repos authoritative.
- ResolveAuditor  : walks the dependency graph from the root artifact and
                    flags any artifact whose pom declares a repo not in the
                    originating project's effective repo set (the MNG-6397
                    bug shape).
"""

node Project {
    has coords: str = "";
    has label: str = "";
    has blockers: int = 0;
}

node Repo {
    has repo_id: str = "";
    has url: str = "";
    has releases_enabled: bool = True;
    has snapshots_enabled: bool = True;
    has declared_by: str = "";
}

node Artifact {
    has coords: str = "";
    has scope: str = "compile";
    has owner_project: str = "";
}

edge Requires {
    has scope: str = "compile";
}

edge DeclaresRepo { }

walker AncestorClimber {
    has effective_repos: list[str] = [];
    has target_project: str = "";

    can start with Root entry {
        visit [-->];
    }

    can climb with Project entry {
        if here.coords == self.target_project or self.target_project == "" {
            visit [->:Requires:->];
            return;
        }
        visit [->:Requires:->];
    }

    can collect_repo with Repo entry {
        repo_id = here.repo_id;
        if repo_id not in self.effective_repos {
            self.effective_repos.append(repo_id);
        }
        visit [-->];
    }
}

walker ResolveAuditor {
    has effective_repos: list[str] = [];
    has violations: list[str] = [];
    has visited: list[str] = [];
    has current_origin: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit_project with Project entry {
        self.current_origin = here.coords;
        visit [->:Requires:->];
    }

    can audit_artifact with Artifact entry {
        if here.coords in self.visited {
            disengage;
        }
        self.visited.append(here.coords);
        print(f"resolving transitive: {here.coords} (scope={here.scope})");
        visit [-->];
    }

    can audit_repo with Repo entry {
        declared_here = here.declared_by;
        if declared_here == self.current_origin {
            visit [-->];
            return;
        }
        is_foreign = here.repo_id not in self.effective_repos;
        if is_foreign {
            violation = (
                f"artifact owned by {self.current_origin} tried to resolve "
                f"through foreign repo '{here.repo_id}' ({here.url})"
            );
            self.violations.append(violation);
            print(f"  [VIOLATION] {violation}");
        }
        visit [-->];
    }
}

with entry {
    # --- Project graph (parent-pom chain) ---
    root_pom = Project(coords="com.example:demo-root:1.0.0", label="root pom");
    sb_deps = Project(coords="org.springframework.boot:spring-boot-dependencies:2.0.0.RELEASE",
                      label="spring-boot-dependencies");
    sb_starter = Project(coords="org.springframework.boot:spring-boot-starter-web:2.0.0.RELEASE",
                         label="spring-boot-starter-web");
    hv = Project(coords="org.hibernate.validator:hibernate-validator:6.0.7.Final",
                 label="hibernate-validator");
    shrinkwrap = Project(coords="org.jboss.shrinkwrap:shrinkwrap-bom:1.2.3",
                         label="shrinkwrap-bom (foreign parent)");

    # Parent-pom chain (Requires edges from child -> parent pom)
    sb_starter +>:Requires:+> sb_deps;
    sb_deps +>:Requires:+> root_pom;

    # Hibernate validator pulls in shrinkwrap-bom as a parent pom
    hv +>:Requires:+> shrinkwrap;

    # --- Repositories declared at each project ---
    # Root pom declares only the internal mirror — the user's MNG-6397 setup.
    internal = Repo(repo_id="central", url="https://artifacts.example.com/repository/maven/",
                    declared_by="com.example:demo-root:1.0.0");
    root_pom +>:DeclaresRepo:+> internal;

    # spring-boot-dependencies (inherited) declares the offending foreign repo.
    spring_milestone = Repo(repo_id="spring-milestone", url="https://repo.spring.io/milestone",
                            snapshots_enabled=False,
                            declared_by="org.springframework.boot:spring-boot-dependencies:2.0.0.RELEASE");
    sb_deps +>:DeclaresRepo:+> spring_milestone;

    # shrinkwrap-bom (the leaf foreign parent) also declares its own repo.
    shrinkwrap_repo = Repo(repo_id="shrinkwrap-public", url="https://repo.jboss.org/nexus/content/groups/public",
                           declared_by="org.jboss.shrinkwrap:shrinkwrap-bom:1.2.3");
    shrinkwrap +>:DeclaresRepo:+> shrinkwrap_repo;

    # --- Artifacts (declared dependencies) ---
    starter_json = Artifact(coords="org.springframework.boot:spring-boot-starter-json:2.0.0.RELEASE",
                            owner_project="org.springframework.boot:spring-boot-starter-web:2.0.0.RELEASE");
    tomcat_ws = Artifact(coords="org.apache.tomcat.embed:tomcat-embed-websocket:8.5.28",
                         owner_project="org.springframework.boot:spring-boot-starter-web:2.0.0.RELEASE");
    hv_jar = Artifact(coords="org.hibernate.validator:hibernate-validator:6.0.7.Final",
                      owner_project="org.springframework.boot:spring-boot-starter-web:2.0.0.RELEASE");
    classmate = Artifact(coords="com.fasterxml:classmate:1.3.1",
                         owner_project="org.hibernate.validator:hibernate-validator:6.0.7.Final");

    sb_starter +>:Requires(scope="compile"):+> starter_json;
    sb_starter +>:Requires(scope="compile"):+> tomcat_ws;
    sb_starter +>:Requires(scope="compile"):+> hv_jar;
    hv_jar +>:Requires(scope="compile"):+> classmate;

    # Wire everything to root so a single spawn reaches it.
    root ++> root_pom;

    # --- Walk 1: climb ancestors to collect effective repos ---
    climber = AncestorClimber(target_project="org.springframework.boot:spring-boot-starter-web:2.0.0.RELEASE");
    root spawn climber;
    print(f"\nEffective repos visible to spring-boot-starter-web: {climber.effective_repos}");
    print("(Notice: shrinkwrap-public is NOT here — it lives on a sibling branch.)");

    # --- Walk 2: audit resolution and catch foreign-repo leakage ---
    print("\nAuditing transitive resolution:");
    auditor = ResolveAuditor(effective_repos=climber.effective_repos);
    root spawn auditor;
    violation_count = len(auditor.violations);
    print(f"\nTotal MNG-6397 violations detected: {violation_count}");
    for v in auditor.violations {
        print(f"  - {v}");
    }
}
