"""Sandbox dependency cache: model stale-by-name bug as native Jac graph.

Demonstrates how caching installed pip requirements keyed only on a logical
sandbox name goes stale when the container behind that name is replaced.
Two distinct Sandbox instances share a lifecycle name; only the first ever
gets its packages recorded. When the second container is created and a
walker traverses the dependency relationship, the dependency walker reports
"already installed" even though this container's filesystem is fresh.
"""

node Sandbox {
    has name: str = "";
    has instance_id: str = "";
    has installed_packages: list[str] = [];
}

node Tool {
    has title: str = "";
    has requires: list[str] = [];
}

edge DependsOn {
    has resolved: bool = False;
}

walker DependencyInstaller {
    has sandbox_key: str = "";
    has installed_cache: dict[str, list[str]] = {};

    can start with Root entry {
        visit [-->];
    }

    can install with Sandbox entry {
        self.sandbox_key = here.name;
        prior = self.installed_cache.get(self.sandbox_key, []);
        for pkg in here.installed_packages {
            if pkg not in prior {
                prior.append(pkg);
            }
        }
        self.installed_cache[self.sandbox_key] = prior;
        print(f"  sandbox '{here.name}' (instance={here.instance_id}) "
              + f"now cached as installed: {prior}");
        visit [->:DependsOn:->];
    }

    can check_tool with Tool entry {
        missing = [];
        for pkg in here.requires {
            if pkg not in self.installed_cache.get(self.sandbox_key, []) {
                missing.append(pkg);
            }
        }
        if missing {
            print(f"  tool '{here.title}' MISSING on sandbox "
                  + f"'{self.sandbox_key}': {missing}");
        } else {
            print(f"  tool '{here.title}' OK on sandbox "
                  + f"'{self.sandbox_key}' (cache hit -- but container "
                  + "may be a DIFFERENT instance with empty filesystem)");
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    s1 = Sandbox(
        name="worker-A",
        instance_id="container-001",
        installed_packages=["requests", "mcp"]
    );
    s2 = Sandbox(
        name="worker-A",
        instance_id="container-002",
        installed_packages=[]
    );

    t1 = Tool(title="list_tools_in_sandbox", requires=["mcp", "requests"]);
    t2 = Tool(title="vibe_summarize", requires=["requests"]);

    s1 +>:DependsOn:+> t1;
    s1 +>:DependsOn:+> t2;
    s2 +>:DependsOn:+> t1;
    s2 +>:DependsOn:+> t2;

    print("=== Container #1 (first allocation under name 'worker-A') ===");
    installer = DependencyInstaller();
    root spawn installer;
    print("  cache state:", installer.installed_cache);
    print("  spawn a fresh walker so each sandbox is visited once:");
    print("=== Container #2 (replacement, same logical name) ===");
    installer2 = DependencyInstaller();
    root spawn installer2;
    print("  cache state:", installer2.installed_cache);
    print("=== Notice: cache for 'worker-A' was populated only by container #1; ===");
    print("=== container #2's freshly empty filesystem is treated as fully installed. ===");
}

