# for them, so their pass through the wards is completely silent.
walker FamilyVisitor {
    can start with Root entry {
        visit [-->];
    }

    can wander with Ward entry {
        visit [-->];
    }
}

with entry {
    icu = Ward(ward_name="ICU");
    general = Ward(ward_name="General");
    root ++> icu ++> general;

    nurse = Nurse(badge="N-101");
    root spawn nurse;
    doctor = Doctor(badge="D-55");
    root spawn doctor;
    guest = FamilyVisitor();
    root spawn guest;

    print(
        f"nurse visited {nurse.shift_visits} wards, "
        f"doctor visited {doctor.shift_visits}; "
        f"the family visitor triggered no ward response at all"
    );
}

