"""Gateway memory and client-cache graph with orphan detection and cycle-safe invalidation."""

node Gateway {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has rss_mb: int = 0;
    has listening: bool = True;
    has alive: bool = True;
}

node DesktopWindow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gateway_pid: int = 0;
    has socket_open: bool = True;
}

node SessionCache {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gateway_pid: int = 0;
    has weight_mb: int = 0;
}

node Transcript {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gateway_pid: int = 0;
    has session_key: str = "";
}

edge Hosts {
    has channel: str = "";
}

edge Caches {
    has scope: str = "";
}

edge Stores {
    has chunk_count: int = 0;
}

edge Retains {
    has reason: str = "";
}

walker GatewayAudit {
    has seen_titles: list[str] = [];
    has orphan_pids: list[int] = [];
    has gateway_count: int = 0;
    has orphan_count: int = 0;
    has cycle_count: int = 0;
    has invalidated_count: int = 0;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_gateway with Gateway entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
        } else {
            self.seen_titles.append(here.title);
            self.gateway_count += 1;
            if not here.listening {
                here.alive = False;
                here.available = False;
                self.orphan_pids.append(here.pid);
                self.orphan_count += 1;
            }
            visit [->:Hosts:->] else { disengage; }
        }
    }

    can inspect_window with DesktopWindow entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
        } else {
            self.seen_titles.append(here.title);
            if here.gateway_pid in self.orphan_pids {
                here.available = False;
                here.socket_open = False;
                self.invalidated_count += 1;
            }
            visit [->:Caches:->] else { disengage; }
        }
    }

    can inspect_cache with SessionCache entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
        } else {
            self.seen_titles.append(here.title);
            if here.gateway_pid in self.orphan_pids {
                here.available = False;
                self.invalidated_count += 1;
            }
            visit [->:Stores:->] else { disengage; }
        }
    }

    can inspect_transcript with Transcript entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
        } else {
            self.seen_titles.append(here.title);
            if here.gateway_pid in self.orphan_pids {
                here.available = False;
                self.invalidated_count += 1;
            }
            visit [->:Retains:->] else { disengage; }
        }
    }

    can summarize with Root exit {
        report self.seen_titles;
    }
}

with entry {
    primary = Gateway(
        title="gateway-primary",
        year=2025,
        pid=1304517,
        rss_mb=1313,
        listening=True
    );
    orphan = Gateway(
        title="gateway-orphan",
        year=2025,
        pid=688094,
        rss_mb=269,
        listening=False
    );

    primary_window = DesktopWindow(
