"""Dependency-aware subagent planning with a guarded native graph walk."""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has complexity: int = 0;
    has state: str = "planned";
}

node Agent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has model_tier: str = "standard";
}

edge DependsOn: Task --> Task {
    has rationale: str = "";
}

edge AssignedTo: Task --> Agent {
    has role: str = "";
}

walker DependencyAuditor {
    has seen_titles: list[str] = [];
    has execution_order: list[str] = [];
    has cycle_found: bool = False;
    has reports: list[list[str]] = [];

    can begin with Root entry {
        visit [-->];
    }

    can inspect_task with Task entry {
        if here.title in self.seen_titles {
            self.cycle_found = True;
            print(f"cycle guard stopped at {here.title}");
            skip;
        } else {
            self.seen_titles.append(here.title);
            self.execution_order.append(here.title);
            availability = "ready" if here.available else "blocked";
            print(f"audit {here.title}: {availability}, complexity {here.complexity}");
            visit [->:DependsOn:->] else { disengage; };
        }
    }

    can inspect_agent with Agent entry {
        print(f"assigned {here.title} using {here.model_tier} model");
    }

    can finish with Root exit {
        report self.execution_order;
    }
}

with entry {
    intake = Task(title="write task brief", year=2026, complexity=1);
    planning = Task(title="batch independent work", year=2026, complexity=2);
    implementation = Task(title="implement optimization layer", year=2026, complexity=5);
    review = Task(title="review implementation", year=2026, complexity=3);
    builder = Agent(title="implementation agent", year=2026, model_tier="strong");

    root ++> intake;
    intake +>:DependsOn(rationale="brief precedes planning"):+> planning;
    planning +>:DependsOn(rationale="planning precedes implementation"):+> implementation;
    implementation +>:DependsOn(rationale="implementation precedes review"):+> review;
    review +>:DependsOn(rationale="intentional cycle for audit"):+> planning;
    implementation +>:AssignedTo(role="primary implementer"):+> builder;

    root spawn DependencyAuditor();
}

