"""Spec Builder + Task Exec demo: model a multi-task execution graph with
parallel lanes, dependencies, and live status, then walk it to surface
what Task Exec would visualize inline in Spec Builder.

Entities are native archetypes; the dependency graph is encoded as typed
edges so the walker can traverse it without any hand-rolled adjacency
machinery. A cycle guard prevents infinite walks; an invalidation sweep
cascades a failure downstream to every dependent task.
"""

node Spec {
    has title: str = "";
    has phase: str = "Draft";
}

node Task {
    has title: str = "";
    has lane: int = 0;
    has status: str = "pending";  # pending | running | done | failed
}

edge BelongsTo { }                 # Task -> Spec
edge Blocks { has reason: str = ""; }   # Task -> Task (dependency)

walker ExecutionView {
    has blocked_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        print("=== Execution graph for spec ===");
        visit [-->];
    }

    can view_spec with Spec entry {
        print(f"Spec: {here.title}  phase={here.phase}");
        visit [->:BelongsTo:->];
    }

    can view_task with Task entry {
        # Avoid revisiting — walkers have no built-in dedup, so guard manually.
        if here.title in self.visited {
            return;
        }
        self.visited.append(here.title);

        lane_label = f"lane {here.lane}";
        print(f"  - [{here.status:>7}] {lane_label}: {here.title}");

        # Dependency ordering: surface what this task blocks.
        dependents = [here ->:Blocks:->];
        if len(dependents) > 0 {
            nxt = ", ".join([d.title + "(" + d.status + ")" for d in dependents]);
            print(f"      blocks -> {nxt}");
        }
        if here.status == "blocked" {
            self.blocked_count += 1;
        }
        visit [->:Blocks:->];
    }
}

walker CascadeInvalidator {
    has failed_title: str = "";
    has invalidated: list[str] = [];
    has invalidated_set: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can find_target with Spec entry {
        visit [->:BelongsTo:->];
    }

    can invalidate with Task entry {
        if here.title in self.invalidated_set {
            disengage;
        }
        self.invalidated_set.append(here.title);

        if here.title == self.failed_title {
            print(f"[cascade] source failure: {here.title}");
            visit [->:Blocks:->];
        } else {
            prior = here.status;
            here.status = "blocked";
            self.invalidated.append(here.title);
            print(f"[cascade] {here.title}: {prior} -> blocked");
            visit [->:Blocks:->];
        }
    }
}

walker CycleInspector {
    has guard: list[str] = [];
    has cycles: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_spec with Spec entry {
        visit [->:BelongsTo:->];
    }

    can scan_task with Task entry {
        key = here.title;
        if key in self.guard {
            cycle = " -> ".join([k for k in self.guard] + [key]);
            self.cycles.append(cycle);
            print(f"[cycle] detected: {cycle}");
            disengage;
        }
        self.guard.append(key);
        visit [->:Blocks:->];
        self.guard.pop();
    }
}

with entry {
    # Build a 6-task Terraform-style spec with parallel lanes and dependencies.
    terraform = Spec(title="Terraform module: gcs-bucket", phase="Tasks");

    scaffold   = Task(title="scaffold module",     lane=0, status="done");
    core       = Task(title="write core files",    lane=1, status="done");
    examples   = Task(title="create examples",     lane=1, status="running");
    format_val = Task(title="format & validate",   lane=2, status="pending");
    docs       = Task(title="generate docs",       lane=2, status="pending");
    precommit  = Task(title="run pre-commit",      lane=3, status="pending");

    # Attach tasks to the spec via typed BelongsTo edges.
    terraform +>:BelongsTo:+> scaffold;
    terraform +>:BelongsTo:+> core;
    terraform +>:BelongsTo:+> examples;
    terraform +>:BelongsTo:+> format_val;
    terraform +>:BelongsTo:+> docs;
    terraform +>:BelongsTo:+> precommit;

    # Dependency edges: who blocks whom.
    scaffold   +>:Blocks(reason="core needs layout"):+> core;
    core       +>:Blocks(reason="examples need APIs"):+> examples;
    core       +>:Blocks(reason="validation needs code"):+> format_val;
    examples   +>:Blocks(reason="docs need examples"):+> docs;
    format_val +>:Blocks(reason="pre-commit gates on format"):+> precommit;
    docs       +>:Blocks(reason="pre-commit gates on docs"):+> precommit;

    # Mount the whole graph off root for spawnability.
    root ++> terraform;

    # 1. Render the inline execution view (the missing Spec Builder feature).
    root spawn ExecutionView();

    # 2. Simulate the examples task failing and cascade-invalidate downstream work.
    print("");
    print("=== invalidation sweep ===");
    examples.status = "failed";
    root spawn CascadeInvalidator(failed_title="examples");

    # 3. Run a cycle probe — walkers must guard against cycles explicitly.
    print("");
    print("=== cycle probe (clean graph) ===");
    root spawn CycleInspector();
}
```

"""Weather sweep: stations report temperature as a walker passes through."""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        print(f"{here.location}: {here.celsius} C");
        self.readings.append([here.location, here.celsius]);
        visit [-->];
    }
}

with entry {
    root ++> Station(location="Northfield", celsius=18.5)
        ++> Station(location="Eastbank", celsius=22.0)
        ++> Station(location="Southridge", celsius=15.2)
        ++> Station(location="Westport", celsius=19.8);

    sweeper = WeatherSweep();
    root spawn sweeper;

    readings = sweeper.readings;
    print(f"All readings: {readings}");

    mins = [r[1] for r in readings];
    lo = mins[0];
    for v in mins {
        lo = v if v < lo else lo;
    }
    hi = mins[0];
    for v in mins {
        hi = v if v > hi else hi;
    }
    print(f"Min: {lo} C, Max: {hi} C");
}

