"""Dependency resolution walk: model a build module that fails to resolve
a transitive dependency, and use a walker to traverse the dependency graph,
reporting the broken path the way `last compilerBridge2_10 / update` does.

The scenario is sbt issue #7608: `publishLocal` on the zinc module fails
because the compiler-bridge resolution chain walks from a Scala version
through a zinc compiler dependency into an unresolved semanticdb-scalac
artifact. We model the graph with typed edges and let a walker perform the
cascade, mirroring the resolver's behavior.
"""

node ScalaVer {
    has version: str = "";
}

node CompilerBridge {
    has name: str = "";
    has available: bool = True;
}

node ZincCompiler {
    has artifact: str = "";
    has available: bool = True;
}

node SemanticDbScalac {
    has artifact: str = "";
    has version: str = "";
    has available: bool = True;
}

# A Scala version depends on a compiler bridge.
edge UsesBridge {
    has note: str = "";
}

# A compiler bridge depends on a zinc compiler artifact.
edge UsesZinc {
    has note: str = "";
}

# A zinc compiler artifact depends on the semanticdb-scalac plugin jar.
edge UsesSemanticDb {
    has note: str = "";
}

walker ResolveWalker {
    has path: list[str] = [];
    has broken: list[str] = [];

    can start with Root entry {
        print(f"Updating compiler-bridge_2.10...");
        visit [-->];
    }

    can hop_bridge with ScalaVer entry {
        self.path.append(f"ScalaVer({here.version})");
        visit [->:UsesBridge:->];
    }

    can hop_zinc with CompilerBridge entry {
        status = "Resolved" if here.available else "NOT FOUND";
        self.path.append(f"CompilerBridge({here.name}, {status})");
        if not here.available {
            self.broken = self.path;
            print("[error] Unresolved dependencies path:");
            for step in self.path {
                print(f"[error]   -> {step}");
            }
            disengage;
        }
        visit [->:UsesZinc:->];
    }

    can hop_semantic with ZincCompiler entry {
        status = "Resolved" if here.available else "NOT FOUND";
        self.path.append(f"ZincCompiler({here.artifact}, {status})");
        if not here.available {
            self.broken = self.path;
            print("[error] Unresolved dependencies path:");
            for step in self.path {
                print(f"[error]   -> {step}");
            }
            disengage;
        }
        visit [->:UsesSemanticDb:->];
    }

    can inspect with SemanticDbScalac entry {
        status = "Resolved" if here.available else "NOT FOUND";
        self.path.append(f"SemanticDbScalac({here.artifact}:{here.version}, {status})");
        if not here.available {
            self.broken = self.path;
            print("[error] Unresolved dependencies path:");
            for step in self.path {
                print(f"[error]   -> {step}");
            }
            disengage;
        }
        # Happy path: full chain resolved.
        print("[info] Resolved compiler-bridge_2.10 dependencies");
        for step in self.path {
            print(f"[info]   -> {step}");
        }
    }
}

with entry {
    v210 = ScalaVer(version="2.10.7");
    bridge = CompilerBridge(name="compilerBridge2_10", available=True);
    zinc = ZincCompiler(artifact="zinc", available=True);
    broken_sem = SemanticDbScalac(
        artifact="org.scalameta:semanticdb-scalac_2.10.7",
        version="4.9.7",
        available=False,
    );

    # Wire the dependency chain exactly as sbt's resolver would walk it.
    v210 +>:UsesBridge(note="bridge lookup"):+> bridge;
    bridge +>:UsesZinc(note="zinc compiler dep"):+> zinc;
    zinc +>:UsesSemanticDb(note="scalac plugin jar"):+> broken_sem;

    root ++> v210;
    root spawn ResolveWalker();
}

