"""BI lineage connector demo: datasets, BI assets, and edges that record which upstream tables a dashboard or workbook depends on.

Demonstrates the core scenario from issue #242: when something breaks, an
impact walker walks upstream-table edges from BI assets back to registered
Datasets and reports which dashboards are affected.
"""

node Dataset {
    has table_key: str = "";
    has name: str = "";
    has registered: bool = True;
}

node BiSource {
    has name: str = "";
    has kind: str = "tableau";
    has enabled: bool = True;
    has last_error: str = "";
}

node BiAsset {
    has external_id: str = "";
    has kind: str = "dashboard";
    has name: str = "";
    has upstream_tables: list[str] = [];
}

edge OwnsAsset {
    has since: str = "";
}

edge DependsOnTable {
    has table_ref: str = "";
    has matched: bool = False;
}

walker ImpactAuditor {
    has visited: list[object] = [];

    can start with Root entry {
        self.visited = [];
        visit [-->];
    }

    can descend_source with BiSource entry {
        if not here.enabled {
            return;
        }
        visit [->:OwnsAsset:->];
    }

    can descend_asset with BiAsset entry {
        self.visited.append(here);
        visit [->:DependsOnTable:->];
    }

    can resolve with Dataset entry {
        if not here.registered {
            print(f"  [STALE] upstream table not registered: {here.table_key}");
            return;
        }
        print(f"  [OK]    upstream dataset found: {here.table_key} ({here.name})");
    }
}

walker BrokenReportFinder {
    has broken_table_key: str = "";
    has affected: list[object] = [];

    can start with Root entry {
        visit [-->];
    }

    can check_source with BiSource entry {
        visit [->:OwnsAsset:->];
    }

    can check_asset with BiAsset entry {
        for (i, tref) in enumerate(here.upstream_tables) {
            if tref.lower() == self.broken_table_key {
                self.affected.append(here);
                print(f"  -> affected asset: [{here.kind}] {here.name} ({here.external_id})");
            }
        }
        visit [-->];
    }
}

walker CascadeInvalidator {
    has seen: list[object] = [];

    can start with Root entry {
        self.seen = [];
        visit [-->];
    }

    can scan with BiSource entry {
        visit [->:OwnsAsset:->];
    }

    can record_asset with BiAsset entry {
        self.seen.append(here);
        print(f"  invalidated asset: [{here.kind}] {here.name}");
        visit [-->];
    }
}

with entry {
    ds_orders = Dataset(table_key="warehouse.public.orders", name="orders");
    ds_customers = Dataset(table_key="warehouse.public.customers", name="customers");
    ds_legacy = Dataset(table_key="legacy.sales.legacy_orders", name="legacy_orders", registered=False);

    src = BiSource(name="prod-tableau", kind="tableau", enabled=True);

    exec_dash = BiAsset(
        external_id="dash-exec-001",
        kind="dashboard",
        name="Executive Revenue",
        upstream_tables=["warehouse.public.orders", "warehouse.public.customers"]
    );

    finance_wb = BiAsset(
        external_id="wb-finance-014",
        kind="workbook",
        name="Finance Detail",
        upstream_tables=["warehouse.public.orders"]
    );

    stale_dash = BiAsset(
        external_id="dash-stale-200",
        kind="dashboard",
        name="Legacy Sales View",
        upstream_tables=["legacy.sales.legacy_orders"]
    );

    root ++> src;
    src +>:OwnsAsset(since="2024-Q1"):+> exec_dash;
    src +>:OwnsAsset(since="2024-Q1"):+> finance_wb;
    src +>:OwnsAsset(since="2023-Q4"):+> stale_dash;

    exec_dash +>:DependsOnTable(table_ref="warehouse.public.orders", matched=True):+> ds_orders;
    exec_dash +>:DependsOnTable(table_ref="warehouse.public.customers", matched=True):+> ds_customers;
    finance_wb +>:DependsOnTable(table_ref="warehouse.public.orders", matched=True):+> ds_orders;
    stale_dash +>:DependsOnTable(table_ref="legacy.sales.legacy_orders", matched=False):+> ds_legacy;

    print("=== Impact audit: which assets are wired to which datasets? ===");
    root spawn ImpactAuditor();

    print("\n=== Broken-report finder: who depends on warehouse.public.orders? ===");
    finder = BrokenReportFinder(broken_table_key="warehouse.public.orders");
    root spawn finder;
    print(f"  total affected: {len(finder.affected)}");

    print("\n=== Cascade invalidation: enumerate assets under the BI source ===");
