"""Order auditor: skip invalid orders but halt on fraud with two early returns."""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Auditor beginning walk...");
        visit [-->];
    }

    can audit with Order entry {
        # Fraud: halt the entire walk immediately (early return #1).
        if here.fraud {
            print(f"HALT on {here.label}: fraud flag set, aborting audit");
            disengage;
        }

        # Invalid: skip this order, but keep auditing the rest (early return #2).
        if not here.valid {
            print(f"SKIP {here.label}: invalid order, continuing");
            visit [-->];
            return;
        }

        # Otherwise: log the audited order and keep walking.
        print(f"AUDIT {here.label}: amount={here.amount:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="ORD-001", amount=120.50, valid=True)
        ++> Order(label="ORD-002", amount=80.00, valid=False)
        ++> Order(label="ORD-003", amount=45.75, valid=True)
        ++> Order(label="ORD-004", amount=999.99, valid=True, fraud=True)
        ++> Order(label="ORD-005", amount=30.00, valid=True);

    root spawn OrderAuditor();
}

