}

node Observation(LineageItem) {
    has byte_evidence: bool = False;
}

node Verification(LineageItem) {
    has accepted: bool = False;
}

edge LineageLink {
    has relation: str = "";
}

walker LineageAuditor {
    has path: list[str] = [];
    has cycle_found: bool = False;
    has visited_count: int = 0;

    can start with Root entry {
        visit [->:LineageLink:->] else {
            disengage;
        }
