    can inspect with Release | Index | Observation | Verification entry {
        if here.key in self.path {
            self.cycle_found = True;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.path.append(here.key);
            self.visited_count += 1;
            print(f"audited {here.title}");
            visit [->:LineageLink:->] else {
                disengage;
            }
        }
    }
