"""Vulnerable npm package audit walker.

Models a dependency graph where packages (nodes) depend on each other via
typed `DependsOn` edges, carry a vulnerability severity, and are installed
in a backend project. An auditor walker traverses the dependency tree and
reports every vulnerable package it can reach from the project's root
manifest. A second walker cascades a security fix by invalidating every
package transitively reachable from a vulnerable one.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has severity: str = "none";
    has fixed: bool = False;

    def is_vulnerable() -> bool {
        return self.severity in ["moderate", "high", "critical"];
    }
}

node Manifest {
    has project: str = "";
}

edge DependsOn {
    has kind: str = "runtime";
}

walker Auditor {
    has findings: list[str] = [];
    has visited: list[Package] = [];

    def seen(pkg: Package) -> bool {
        for p in self.visited {
            if p.name == pkg.name {
                return True;
            }
        }
        return False;
    }

    def mark(pkg: Package) -> None {
        self.visited.append(pkg);
    }

    can start with Root entry {
        print("Running vulnerability audit on backend dependencies...");
        visit [-->];
    }

    can descend with Manifest entry {
        print(f"Project: {here.project}");
        visit [->:DependsOn:->];
    }

    can inspect with Package entry {
        if self.seen(here) {
            visit [->:DependsOn:->];
        }
        self.mark(here);
        if here.is_vulnerable() and not here.fixed {
            label = "FIXED" if here.fixed else "OPEN";
            note = f"[{here.severity.upper()}] {here.name}@{here.version} - {label}";
            self.findings.append(note);
            print(note);
        }
        visit [->:DependsOn:->];
    }
}

walker CascadeInvalidator {
    has visited: list[Package] = [];
    has invalidations: list[str] = [];

    def seen(pkg: Package) -> bool {
        for p in self.visited {
            if p.name == pkg.name {
                return True;
            }
        }
        return False;
    }

    def mark(pkg: Package) -> None {
        self.visited.append(pkg);
    }

    can start with Root entry {
        print("Cascading invalidation from vulnerable packages...");
        visit [-->];
    }

    can descend with Manifest entry {
        visit [->:DependsOn:->];
    }

    can invalidate with Package entry {
        if self.seen(here) {
            visit [->:DependsOn:->];
        }
        self.mark(here);
        if here.is_vulnerable() {
            record = f"{here.name}@{here.version} ({here.severity})";
            self.invalidations.append(record);
            here.fixed = True;
            print(f"Invalidated: {record}");
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    backend = Manifest(project="backend");

    express = Package(name="express", version="4.17.1");
    lodash = Package(name="lodash", version="4.17.20", severity="high");
    minimist = Package(name="minimist", version="1.2.5", severity="critical");
    node_fetch = Package(name="node-fetch", version="2.6.7", severity="high");
    follow_redirects = Package(name="follow-redirects", version="1.14.0", severity="moderate");
    mongoose = Package(name="mongoose", version="6.4.0");
    tough_cookie = Package(name="tough-cookie", version="2.5.0", severity="moderate");
    ws = Package(name="ws", version="5.2.2", severity="high");
    nanoid = Package(name="nanoid", version="3.1.30");

    root ++> backend;

    backend +>:DependsOn(kind="runtime"):+> express;
    backend +>:DependsOn(kind="runtime"):+> mongoose;

    express +>:DependsOn(kind="transitive"):+> lodash;
    express +>:DependsOn(kind="transitive"):+> node_fetch;
    mongoose +>:DependsOn(kind="transitive"):+> tough_cookie;

    lodash +>:DependsOn(kind="transitive"):+> minimist;
    node_fetch +>:DependsOn(kind="transitive"):+> follow_redirects;
    mongoose +>:DependsOn(kind="transitive"):+> ws;

    root spawn Auditor();
    print("---");
    root spawn CascadeInvalidator();
}

