"""School Canonical Bidding Engine: canonical vs external knowledge bases and audit walks.

Models the two machine-readable knowledge bases from the School of Sports
Bridge bidding program (SCHOOL CANON + WORLD / EXTERNAL KNOWLEDGE), the
provenance/approval lifecycle of a canonical rule, and a walker that audits
the gap between the active canon and the live external evidence available
for a given auction context.
"""

node CanonRule {
    has title: str = "";
    has body: str = "";
    has approved: bool = False;
    has version: int = 0;
    has source_ref: str = "";
}

node WorldRule {
    has title: str = "";
    has body: str = "";
    has origin: str = "";
    has provenance_class: str = "external";
}

node AuctionContext {
    has auction_id: str = "";
    has position: str = "";
    has last_bid: str = "";
}

node Gap {
    has reason: str = "";
    has severity: str = "info";
}

# Typed relationships:
#   Provenance    : WorldRule -- Provenance --> CanonRule (a canonical rule was
#                    promoted from a specific external knowledge object).
#   Activates     : CanonRule -- Activates --> AuctionContext (this canon rule
#                    is live for the given auction context).
#   RelevantTo    : WorldRule -- RelevantTo --> AuctionContext (this external
#                    rule is candidate evidence for the given context).
#   DiscoveredIn  : Gap       -- DiscoveredIn --> AuctionContext (the gap was
#                    observed while serving this auction context).
#   WantsFrom     : Gap       -- WantsFrom --> WorldRule (a world object that
#                    could fill the gap, if ever promoted to canon).

edge Provenance    { has note: str = ""; }
edge Activates     { }
edge RelevantTo   { has weight: float = 0.0; }
edge DiscoveredIn { }
edge WantsFrom     { }

walker CanonAuditor {
    has gap_count: int = 0;

    can start with Root entry {
        print(f"CanonAuditor: beginning gap audit over active auctions");
        visit [-->];
    }

    can scan with AuctionContext entry {
        print(f"Auction {here.auction_id} (pos={here.position}, last={here.last_bid})");

        active_canon = [here ->:Activates:->];
        candidates   = [here ->:RelevantTo:->];

        titles_active = [c.title for c in active_canon];
        titles_cands  = [w.title for w in candidates];
        print(f"  active canon rules: {titles_active}");
        print(f"  world candidates  : {titles_cands}");

        if len(active_canon) == 0 {
            gap = Gap(
                reason="no approved canonical rule activates this auction context",
                severity="high"
            );
            here +>:DiscoveredIn:+> gap;
            for w in candidates {
                gap +>:WantsFrom:+> w;
            }
            gap_count_label = f"  [GAP] no canon for {here.auction_id}; "
                + f"{len(candidates)} candidate(s) pending promotion";
            print(gap_count_label);
            self.gap_count = self.gap_count + 1;
        } else {
            print("  canon coverage OK");
        }

        visit [-->];
    }

    can finish with Root entry {
        print(f"CanonAuditor: total gaps surfaced = {self.gap_count}");
    }
}

walker GapReviewer {
    can start with Root entry {
        print("GapReviewer: walking every discovered gap");
        visit [-->];
    }

    can review with Gap entry {
        candidates = [here ->:WantsFrom:->];
        proposed = [];
        for w in candidates {
            proposed.append(w.title);
        }
        print(f"  gap[{here.severity}] {here.reason} -> candidates {proposed}");
        visit [-->];
    }
}

walker Promotion {
    has rule_name: str = "";

    can start with Root entry {
        print(f"Promotion: requested canonical rule '{self.rule_name}'");
        visit [-->];
    }

    can approve with CanonRule entry {
        if here.title == self.rule_name {
            here.approved = True;
            here.version = here.version + 1;
            print(f"  APPROVED '{here.title}' v{here.version} (source: {here.source_ref})");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    # Canonical rules: only one is approved; the rest sit in the canon store
    # waiting for owner authorization. External knowledge (world rules) is
    # linked by provenance to the canonical rule it was promoted from.
    open_1nt = CanonRule(
        title="Open 1NT after 1m",
        body="Rebid 1NT (15-17) over partner's 1m response with balanced min.",
        approved=True,
        version=1,
        source_ref="BEN/BBA reconstructed"
    );

    jacoby_2nt = CanonRule(
        title="Jacoby 2NT",
        body="After 1H-2H, 2NT is a strong limit-raise asking for shortness.",
        approved=False,
        version=0,
        source_ref="Pons convention card"
    );

    stayman = CanonRule(
        title="Stayman",
        body="2C over 1NT asks for a 4-card major.",
        approved=False,
        version=0,
        source_ref="World textbook"
    );

    ben_world = WorldRule(
        title="ben: open 1NT 15-17",
        body="Sampler recommends balanced min over 1m response.",
        origin="BEN",
        provenance_class="learned"
    );

    pons_world = WorldRule(
        title="pons: jacoby 2NT",
        body="Constraint DSL fires jacoby 2NT over 1H-2H.",
        origin="Pons",
        provenance_class="heuristic"
    );

    bridgit_world = WorldRule(
        title="bridgit: stayman",
        body="Convention card lists 2C as stayman over 1NT.",
        origin="Bridgit",
        provenance_class="literature"
    );

    # Two auction contexts the engine is currently serving.
    ctx_a = AuctionContext(auction_id="A-001", position="N", last_bid="1H");
    ctx_b = AuctionContext(auction_id="A-002", position="S", last_bid="1NT");

    # Wire the graph:
    #   external -> canonical provenance edges (only approved promotion lives)
    root +>:Provenance(note="promoted 2024-08"):+> ben_world +>:Provenance:+> open_1nt;
    root +>:Provenance:+> pons_world;
    root +>:Provenance:+> bridgit_world;

    #   ctx_a has the 1H-over-1m canonical rule activated; world candidates hang
    #   off it as RelevantTo (with weights) but none is canon yet.
    ctx_a +>:Activates:+> open_1nt;
    ctx_a +>:RelevantTo(weight=0.9):+> pons_world;
    ctx_a +>:RelevantTo(weight=0.4):+> bridgit_world;

    #   ctx_b has no approved canon -> the auditor will surface a gap and
