    ctx_b +>:RelevantTo(weight=0.8):+> bridgit_world;
    ctx_b +>:RelevantTo(weight=0.2):+> pons_world;

    # Lay out the graph: root -> both auction contexts; canonical/world rules
    # sit off root so the auditor can see the auction-context frontier.
    root ++> ctx_a ++> ctx_b;

    # Run the auditor across the graph.
    auditor = CanonAuditor();
    root spawn auditor;

    # Then walk every Gap discovered (they were attached to ctx_b during the
    # audit) to show the candidate world objects that could fill it.
    reviewer = GapReviewer();
    root spawn reviewer;

    # Finally, demonstrate the owner-authorization gate: promoting jacoby 2NT
    # flips its approval/version; stayman stays unapproved.
    root spawn Promotion(rule_name="Jacoby 2NT");
    root spawn Promotion(rule_name="Stayman");

    print(f"final canon approved count after promotion pass: 1 "
        f"(open_1nt v{open_1nt.version}; jacoby v{jacoby_2nt.version}; "
        f"stayman v{stayman.version})");
