"""Dependency graph discovery service: model packages, dependencies, and a
walker that traverses the graph with cycle detection and missing-target
handling — the same scenario the funding-dashboard-labs issue describes,
expressed natively in Jac.

Entities:
  Package — a discoverable package node.
  Source  — a registry/source kind (e.g. npm registry).

Relationships (typed edges):
  SourceOf      — Package was discovered via Source.
  DependsOn     — Package depends on another Package (the link being walked).

Behaviors demonstrated:
  1. Cycle detection: walker carries an explicit guard set so re-entry into
     an already-visited package produces a [CYCLE] report instead of an
     infinite loop.
  2. Missing-target handling: a dependency whose target is unknown acts like
     a 404 — the walker logs a [MISS] and continues without crashing.
  3. Depth-limited reachability: a max-depth field stops overly deep walks.
"""

node Package {
    has name: str = "";
    has version: str = "0.0.0";
}

node Source {
    has kind: str = "registry";
}

edge SourceOf {
    has fetched_at: str = "init";
}

edge DependsOn {
    has constraint: str = "*";
    has resolved: bool = True;
}

walker Discovery {
    has max_depth: int = 5;
    has visited: list[str] = [];
    has trace: list[str] = [];
    has start_label: str = "root";

    can begin with Root entry {
        self.start_label = "root";
        visit [-->];
    }

    can register with Package entry {
        # Cycle policy (explicit): a package is only entered the first time.
        if here.name in self.visited {
            self.trace.append(f"[CYCLE] {here.name} already visited");
            return;
        }
        self.visited.append(here.name);
        self.trace.append(f"[OPEN] {here.name}@{here.version}");

        # Depth-limit policy (explicit): stop walking once too deep.
        if self.max_depth <= 0 {
            self.trace.append("[STOP] depth limit reached");
            return;
        }
        self.max_depth -= 1;

        # Typed-edge traversal: only follow DependsOn links, not SourceOf.
        visit [->:DependsOn:->];
    }

    can note_source with Source entry {
        # Sources are pass-through hubs; don't record them, just keep going.
        visit [-->];
    }
}

walker MissingTarget {
    # A second walker that probes edges whose targets were never resolved —
    # the analogue of a 404 from the discovery fetch.
    has log: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can scan_pkg with Package entry {
        # For every DependsOn edge out of this package, check whether the
        # dependency "target" is real. An unresolved edge is the 404 analogue.
        for dep in [->:DependsOn:->] {
            if not dep.resolved {
                self.log.append(f"[MISS] {here.name} -> unresolvable dependency");
            }
        }
        visit [-->];
    }
}

walker SourceProbe {
    has log: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can log_source with Source entry {
        self.log.append(f"[SOURCE] {here.kind}");
        visit [-->];
    }

    can log_pkg with Package entry {
        self.log.append(f"[PKG] {here.name}");
        visit [-->];
    }
}

with entry {
    # --- Build the graph ---------------------------------------------------
    npm = Source(kind="npm");
    npm_mirror = Source(kind="npm-mirror");

    app = Package(name="app", version="1.0.0");
    core = Package(name="core", version="2.3.0");
    util = Package(name="util", version="0.9.1");
    logger = Package(name="logger", version="1.2.0");

    # Sources attach packages (SourceOf carries the "we discovered it here" payload).
    npm +>:SourceOf(fetched_at="2024-01-01"):+> app;
    npm_mirror +>:SourceOf(fetched_at="2024-01-02"):+> logger;

    # Dependency links (DependsOn is what the discovery walker actually traverses).
    app +>:DependsOn(constraint="^2.0.0"):+> core;
    core +>:DependsOn(constraint="^0.9.0"):+> util;
    util +>:DependsOn(constraint="^1.0.0"):+> logger;
    logger +>:DependsOn(constraint="^2.0.0"):+> core;   # <-- cycle back to core
    # The "ghost" dependency: the target node exists but the edge marks it
    # as unresolved — the walker treats it like a 404 from the registry fetch.
    app +>:DependsOn(constraint="^9.9.9", resolved=False):+> Package(name="ghost", version="?");

    # --- Run discovery from the app package --------------------------------
    discovery = Discovery(max_depth=4);
    app spawn discovery;

    print("=== Discovery trace ===");
    for line in discovery.trace {
        print(line);
    }

    # --- Probe which sources contributed ----------------------------------
    probe = SourceProbe();
    root spawn probe;

    print("=== Sources discovered ===");
    for line in probe.log {
        print(line);
    }

    # --- Run the 404-style miss probe -------------------------------------
    miss = MissingTarget();
    root spawn miss;

    print("=== Missing-dependency scan ===");
    for line in miss.log {
        print(line);
    }
}

