"""Flight network: priced legs normalize against the scout's peak fare report."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has origin_code: str = "";
    has dest_code: str = "";

    def fare_fraction(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.price / peak;
    }
}

walker FareScout {
    has peak_fare: float = 0.0;
    has fare_report: list[float] = [];
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can sweep with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            self.fare_report.append(leg.price);
            if leg.price > self.peak_fare {
                self.peak_fare = leg.price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
