    leg_lax_ord = FlightLeg(
        price=320.0, origin_code="LAX", dest_code="ORD"
    );
    lax +>:leg_lax_ord:+> ord;

    leg_ord_bos = FlightLeg(
        price=580.0, origin_code="ORD", dest_code="BOS"
    );
    ord +>:leg_ord_bos:+> bos;

    leg_bos_jfk = FlightLeg(
