"""In-process dependency reachability over typed graph edges."""

node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Artifact(GraphItem) {
    has category: str = "";
}

node Revision(GraphItem) {
    has revision_number: int = 0;
}

edge DependsOn {
    has tier: int = 0;
    has reason: str = "";
}

walker ReachabilityAudit {
    has max_depth: int = 8;
    has depth: int = 0;
    has visited_titles: list[str] = [];
    has incident_lookups: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Artifact | Revision entry {
        if here.title in self.visited_titles {
            print(f"Cycle detected at {here.title}; stopping this branch");
            disengage;
        } else {
            self.visited_titles.append(here.title);
            self.incident_lookups += 1;
            self.depth += 1;
            state = "available" if here.available else "stale";
            print(f"Visited {here.title} ({state})");

            if self.depth >= self.max_depth {
                print("Depth limit reached");
                disengage;
            } else {
                visit [->:DependsOn:->] else {
                    disengage;
                }
            }
        }
    }
}

with entry {
    platform = Artifact(
        title="Platform",
        year=2024,
        category="runtime"
    );
    api = Artifact(
        title="Public API",
        year=2024,
