    );
    release = Revision(
        title="Release 7",
        year=2025,
        revision_number=7,
        available=False
    );

    root ++> platform;
    platform +>:DependsOn(
        tier=1,
        reason="runtime exposes API"
    ):+> api;
    api +>:DependsOn(
        tier=2,
        reason="API ships in release"
    ):+> release;
    release +>:DependsOn(
        tier=9,
        reason="intentional cycle"
    ):+> platform;

    audit = ReachabilityAudit(max_depth=6);
    root spawn audit;

    print(
        f"Reachable entities: {len(audit.visited_titles)}; "
        f"incident lookups: {audit.incident_lookups}"
    );
}
