"""Shell component dependency scan: model components as nodes, walk consumers
to find orphaned files (like LabelValue.vue left behind after Harvester pkg removal)."""

node Component {
    has name: str = "";
    has package: str = "";
    has size_lines: int = 0;
    has orphaned: bool = False;
}

edge ImportedBy {
    has from_pkg: str = "";
}

walker OrphanHunter {
    has checked: list[str] = [];
    has orphans_found: list[str] = [];
    has target_name: str = "LabelValue";

    can start with Root entry {
        print(f"Scanning component graph for orphaned component: {self.target_name}");
        visit [-->];
    }

    can scan with Component entry {
        if here.name in self.checked {
            visit [-->];
            return;
        }
        self.checked.append(here.name);

        if here.name == self.target_name {
            here.orphaned = True;
            consumer_edges = [here->:ImportedBy:->];
            if not consumer_edges {
                self.orphans_found.append(here.name);
                print(f"[ORPHAN] {here.name} ({here.size_lines} lines, pkg={here.package}) - no consumers remain");
                disengage;
            }
            for c in consumer_edges {
                self.orphans_found.append(here.name);
                print(f"[ORPHAN] {here.name} ({here.size_lines} lines, pkg={here.package}) - last consumer was {c.name}");
            }
        }
        visit [-->];
    }
}

