"""Public poll endpoint: vote and read live tallies over HTTP.

`vote` bumps a counter from its request body, `tally` reports counts
back; the entry block simulates a few clicks for standalone runs.
"""

node PollOption {
    has title: str;
    has votes: int = 0;
}

walker:pub setup_poll {
    has titles: list[str];

    can run with Root entry {
        for t in self.titles {
            here ++> PollOption(title=t);
        }
    }
}

walker:pub vote {
    has choice: str;

    can run with Root entry {
        for opt in [-->][?:PollOption] {
            if opt.title == self.choice {
                opt.votes += 1;
                report {"counted": opt.title, "total": opt.votes};
                disengage;
            }
        }
        report {"error": "unknown option", "choice": self.choice};
    }
}

walker:pub tally {
    can run with Root entry {
        report {opt.title: opt.votes for opt in [-->][?:PollOption]};
    }
}

with entry {
    root spawn setup_poll(titles=["The Dispossessed", "Snow Crash", "Ancillary Justice"]);

    # Pretend these arrived as HTTP POSTs.
    root spawn vote(choice="Snow Crash");
    root spawn vote(choice="Snow Crash");
    root spawn vote(choice="The Dispossessed");

    result = root spawn tally();
    print(result.reports);
}

"""Build system dependency audit: count total build minutes across tasks in a diamond-shaped DAG, auditing each task exactly once."""

node Task {
    has name: str = "";
    has minutes: int = 0;
    has audited: bool = False;
}

walker Auditor {
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if not here.audited {
            here.audited = True;
            self.total_minutes = self.total_minutes + here.minutes;
            print(f"Audited {here.name} (+{here.minutes} min, total={self.total_minutes})");
        } else {
            print(f"Skipped {here.name} (already audited)");
        }
        visit [-->];
    }
}

with entry {
    # Diamond DAG: root -> A -> C, root -> A -> D, root -> B -> C, root -> B -> D
    # A and B are shared upstream; C and D are shared downstream.
    a = Task(name="lib-a", minutes=5);
    b = Task(name="lib-b", minutes=3);
    c = Task(name="app-c", minutes=10);
    d = Task(name="app-d", minutes=7);

    # Build the diamond: root -> a, root -> b, a -> c, a -> d, b -> c, b -> d
    root ++> a ++> c;
    root ++> b ++> d;
    a ++> d;
    b ++> c;

    auditor = Auditor();
    root spawn auditor;

    # Expected: 5 + 3 + 10 + 7 = 25 (each task audited exactly once)
    print(f"\nFinal total build minutes: {auditor.total_minutes} (expected 25)");
}

