"""Native schema dictionary and lineage graph demo."""

node SchemaTable {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has table_kind: str = "TABLE";
    has ordinal: int = 0;
}

node Column {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has table_name: str = "";
    has data_type: str = "";
    has ordinal: int = 0;
    has description: str = "";
    has null_meaning: str = "";
}

edge HasColumn {
    has ordinal: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

edge DerivedFrom {
    has rule: str = "";
}

walker DependencyAuditor {
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with SchemaTable entry {
        print(f"dependency: {here.title}");

        # A bounded depth is the explicit cycle policy.
        if self.depth >= 4 {
            print(f"cycle guard at {here.title}");
            disengage;
        }

        self.depth += 1;
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker LineageAuditor {
    can start with Root entry {
        visit [-->];
    }

    can inspect_table with SchemaTable entry {
        print(f"table: {here.title}");
        visit [->:HasColumn:->] else {
            disengage;
        }
    }

    can inspect_column with Column entry {
        print(f"field: {here.table_name}.{here.title} [{here.data_type}]");
        visit [->:DerivedFrom:->] else {
            disengage;
        }
    }
}

with entry {
    course = SchemaTable(
        title="course_material",
        table_kind="CANONICAL"
    );
    source = SchemaTable(
        title="comprehensive_data",
        table_kind="SOURCE"
    );

    course_id = Column(
        title="course_id",
        table_name="course_material",
        data_type="VARCHAR",
        ordinal=1,
        description="Stable course identifier",
        null_meaning="Missing when source lacks an identifier"
    );
    course_title = Column(
        title="title",
        table_name="course_material",
        data_type="VARCHAR",
        ordinal=2,
        description="Published course title",
        null_meaning="Missing when no usable title exists"
    );
    course_source_id = Column(
        title="source_course_id",
        table_name="course_material",
        data_type="VARCHAR",
        ordinal=3,
        description="Identifier from source rows",
        null_meaning="Missing when lineage is unavailable"
    );

    source_course_id = Column(
        title="course_id",
        table_name="comprehensive_data",
        data_type="VARCHAR",
        ordinal=1,
        description="Imported source course identifier",
        null_meaning="Missing in the upstream source"
    );
    source_loaded_at = Column(
        title="loaded_at",
        table_name="comprehensive_data",
        data_type="DATE",
        ordinal=2,
        description="Source ingestion date",
        null_meaning="Missing for legacy source rows"
    );

    root ++> course;
    root ++> source;

    course +>:HasColumn(ordinal=1):+> course_id;
    course +>:HasColumn(ordinal=2):+> course_title;
    course +>:HasColumn(ordinal=3):+> course_source_id;

    source +>:HasColumn(ordinal=1):+> source_course_id;
    source +>:HasColumn(ordinal=2):+> source_loaded_at;

    course +>:DependsOn(reason="canonical rows derive from source rows"):+> source;
    source +>:DependsOn(reason="demonstrates a guarded dependency cycle"):+> course;

    course_source_id +>:DerivedFrom(
        rule="comprehensive_data.course_id"
    ):+> source_course_id;

    root spawn DependencyAuditor();
    root spawn LineageAuditor();
}

