"""Model the downgrade QA dependency mutation and precompile cycle."""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has test_only: bool = False;
    has promoted_to_runtime: bool = False;
}

node QAJob {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn {
    has declared_kind: str = "runtime";
}

edge Audits {
    has check_name: str = "stale-dependencies";
}

walker DependencyAuditor {
    has seen: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("Starting downgrade QA dependency audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_job with QAJob entry {
        print(f"QA job: {here.title}");
        visit [->:Audits:->] else {
            disengage;
        }
    }

    can inspect_package with Package entry {
        if here.title in self.seen {
            print(f"[CYCLE] dependency loop revisits {here.title}");
            self.cycle_detected = True;
            disengage;
        } else {
            self.seen.append(here.title);
            if here.test_only {
                if here.promoted_to_runtime {
                    print(f"[STALE] test-only package promoted into runtime: {here.title}");
                }
            }
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

with entry {
    qa = QAJob(title="ModelingToolkitBase downgrade QA", year=2025);

    base = Package(title="ModelingToolkitBase", year=2025);
    standard = Package(title="ModelingToolkitStandardLibrary", year=2025);
    extension = Package(title="MTKDiffEqNoiseProcessExt", year=2025);
    dynamic = Package(
        title="DynamicQuantities",
        year=2025,
        test_only=True,
        promoted_to_runtime=True
    );
    latexify = Package(
        title="Latexify",
        year=2025,
        test_only=True,
        promoted_to_runtime=True
    );

    root ++> qa;
    qa +>:Audits(check_name="Aqua stale dependency check"):+> base;

    base +>:DependsOn(declared_kind="runtime"):+> standard;
    base +>:DependsOn(declared_kind="runtime"):+> dynamic;
    base +>:DependsOn(declared_kind="runtime"):+> latexify;
    standard +>:DependsOn(declared_kind="extension"):+> extension;
    extension +>:DependsOn(declared_kind="extension"):+> base;

    root spawn DependencyAuditor();
}

