"""Mesh pipeline demo: components, generators, junctions, and an executor walker.

Models the moose #33227 scenario where the order of ``addMeshGenerator`` calls
on a component matters: junctions look up an aggregate component's *last*
mesh generator, so if a junction is processed before a generator is appended
the junction ends up stitching from a disconnected / non-final generator.
The executor walker reproduces that ordering hazard by walking components in
declaration order and triggering junctions at the point it finds them, just
like the original hand-rolled machinery.
"""

node MeshGenerator {
    has name: str = "";
    has offset: float = 0.0;
}

node ComponentJunction {
    has name: str = "";
}

node Component {
    has name: str = "";
    has generators: list = [];
    has junctions: list = [];
}

edge HoldsGen { }
edge HoldsJunc { }
edge DependsOn { }

walker PipelineExecutor {
    has log: list = [];

    can start with Root entry {
        print("=== Mesh Pipeline Executor (issue #33227 reproducer) ===");
        visit [-->];
    }

    can dispatch with Component entry {
        # Process the component's generators first (declaration order),
        # THEN its junctions. This mirrors the moose behavior where the
        # junctions look up the aggregate component's *last* generator.
        i = 0;
        while i < len(here.generators) {
            g = here.generators[i];
            self.log.append(f"addMeshGenerator on {here.name}: {g.name}");
            i += 1;
        }
        # Now the junctions fire. Each junction needs the *last* generator
        # on the aggregate component to exist BEFORE the junction runs.
        j = 0;
        while j < len(here.junctions) {
            jc = here.junctions[j];
            if len(here.generators) == 0 {
                self.log.append(
                    f"!! junction {jc.name} on {here.name} found "
                    f"NO generator -> stitches disconnected mesh"
                );
            } else {
                last_gen = here.generators[len(here.generators) - 1];
                self.log.append(
                    f"junction {jc.name} on {here.name} -> stitches "
                    f"from last generator {last_gen.name}"
                );
            }
            j += 1;
        }
        visit [->:DependsOn:->];
    }

    can note_gen with MeshGenerator entry {
        self.log.append(f"traversed generator node {here.name}");
        visit [-->];
    }

    can note_junc with ComponentJunction entry {
        self.log.append(f"traversed junction node {here.name}");
        visit [-->];
    }
}

with entry {
    # Three components in a small dependency graph.
    block = Component(name="block");
    assembly = Component(name="assembly");
    full_model = Component(name="full_model");

    # Populate each component's hand-rolled machinery: a list of mesh
    # generators and a list of junctions. These lists are the *original*
    # representation that the issue complains about -- the junctions
    # implicitly depend on whatever generator was appended last.
    block.generators = [
        MeshGenerator(name="block_gen_1", offset=0.0),
        MeshGenerator(name="block_gen_2", offset=1.0),
    ];
    block.junctions = [];

    assembly.generators = [
        MeshGenerator(name="assembly_gen_1", offset=2.0),
    ];
    assembly.junctions = [
        ComponentJunction(name="assembly_to_block"),
    ];

    full_model.generators = [];
    full_model.junctions = [
        ComponentJunction(name="full_to_assembly"),
        ComponentJunction(name="full_to_block"),
    ];

    # Wire the component graph with typed edges so the executor can walk it.
    root +>:HoldsGen:+> (b1 := MeshGenerator(name="root_g", offset=0.0));
    root ++> block +>:DependsOn:+> assembly +>:DependsOn:+> full_model;

    # Build a problematic variant where full_model ends up declaring a
    # generator AFTER its junction was already created -- this is the
    # ordering hazard the issue describes.
    late = Component(name="late_declare");
    late.generators = [];
    late.junctions = [ComponentJunction(name="late_junc")];
    root ++> late;
    # ...then "later" code calls addMeshGenerator, but the junction has
    # already been registered on the component and will run first.
    late.generators = [MeshGenerator(name="late_gen", offset=9.0)];

    print("--- normal order: block -> assembly -> full_model ---");
    exec1 = PipelineExecutor();
    root spawn exec1;
    for `entry in exec1.log {
        print(`entry);
    }

    print("");
    print("--- hazard: junction declared before generator exists ---");
    exec2 = PipelineExecutor();
    # Re-spawn against the same root so the walker visits every component,
    # including `late_declare` whose junction fires against an empty
    # generator list -- reproducing the disconnected-stitch bug.
    root spawn exec2;
    for `entry in exec2.log {
        print(`entry);
    }
}

