"""Native graph model for a cybersecurity knowledge-map visualizer."""

node Canvas {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has viewport: str = "";
}

node VisualizationMap {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has map_id: str = "";
}

node KnowledgeUnit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stable_id: str = "";
    has lifecycle: str = "current";
}

edge Displays {
    has view_name: str = "";
}

edge Contains {
    has role: str = "";
}

edge Prerequisite {
    has reason: str = "";
}

walker DependencyAuditor {
    has visited_ids: list[str] = [];
    has checked_count: int = 0;
    has cycle_count: int = 0;

    can begin with Root entry {
        print("Starting dependency audit from the visualization canvas");
        visit [-->] else {
            disengage;
        }
    }

    can open_canvas with Canvas entry {
        print(f"Canvas: {here.title} ({here.viewport})");
        visit [->:Displays:->] else {
            disengage;
        }
    }

    can open_map with VisualizationMap entry {
        print(f"Map {here.map_id}: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_unit with KnowledgeUnit entry {
        if here.stable_id in self.visited_ids {
            self.cycle_count += 1;
            print(f"Cycle detected at {here.stable_id}; dependency walk stops on this branch");
        } else {
            self.visited_ids.append(here.stable_id);
            self.checked_count += 1;
            status = "eligible" if here.available else "unavailable";
            print(f"{here.stable_id}: {here.title} [{status}, {here.lifecycle}]");
            visit [->:Prerequisite:->] else {
                disengage;
            }
        }
    }

    can finish with Root exit {
        print(f"Audit complete: {self.checked_count} units checked, {self.cycle_count} cycle(s) guarded");
        report self.checked_count;
    }
}

with entry {
    canvas = Canvas(
        title="Cybersecurity knowledge workspace",
        viewport="1440x900"
    );
    knowledge_map = VisualizationMap(
        title="Incident response pathway",
        map_id="ir-01"
    );
    triage = KnowledgeUnit(
        title="Incident triage",
        stable_id="ku-triage",
        lifecycle="current"
    );
    logging = KnowledgeUnit(
        title="Security logging",
        stable_id="ku-logging",
        lifecycle="current"
    );
    containment = KnowledgeUnit(
        title="Threat containment",
        stable_id="ku-containment",
        available=False,
        lifecycle="draft"
    );

    root ++> canvas;
    canvas +>:Displays(view_name="Graph"):+> knowledge_map;
    knowledge_map +>:Contains(role="focus"):+> triage;
    triage +>:Prerequisite(reason="requires telemetry"):+> logging;
    logging +>:Prerequisite(reason="feeds response"):+> containment;
    containment +>:Prerequisite(reason="intentional cycle probe"):+> triage;

    root spawn DependencyAuditor();
}
