"""Translation-table catalog demo with locale fallback and cycle-safe traversal."""

node Product {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

node Category {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
    has audit_seen: bool = False;
}

node Brand {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

node Translation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has entity_kind: str = "";
    has locale: str = "";
    has name: str = "";
    has slug: str = "";
    has description: str = "";
}

edge ProductTranslation {
    has source_column: str = "";
}

edge CategoryTranslation {
    has source_column: str = "";
}

edge BrandTranslation {
    has source_column: str = "";
}

edge CategoryParent {
    has relation: str = "parent";
}

edge ProductCategory { }
edge ProductBrand { }

walker ProductReader {
    has requested_locale: str = "";
    has default_locale: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Product entry {
        print(f"product: {here.title} ({here.slug})");
        visit [->:ProductTranslation:->] else {
            disengage;
        }
    }

    can resolve with Translation entry {
        if here.locale == self.requested_locale {
            print(f"selected {here.entity_kind} [{here.locale}]: {here.name}");
        } else {
            if here.locale == self.default_locale {
                print(f"fallback {here.entity_kind} [{here.locale}]: {here.name}");
            }
        }
        visit [-->] else {
            print("translation branch complete");
        }
    }
}

walker CatalogAudit {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_category with Category entry {
        if here.audit_seen {
            print(f"cycle detected at category {here.slug}");
            disengage;
        } else {
            here.audit_seen = True;
            print(f"category: {here.title}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_brand with Brand entry {
        print(f"brand: {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_translation with Translation entry {
        print(f"catalog translation [{here.locale}]: {here.name}");
        visit [-->] else {
            print("catalog translation branch complete");
        }
    }
}

with entry {
    product = Product(
        title="Wireless Headphones",
        year=2024,
        available=True,
        slug="wireless-headphones"
    );
    product_vi = Translation(
        entity_kind="product",
        locale="vi",
        name="Tai nghe không dây",
        slug="tai-nghe-khong-day",
        description="Tai nghe Bluetooth"
    );
    product_en = Translation(
        entity_kind="product",
        locale="en",
        name="Wireless Headphones",
        slug="wireless-headphones",
        description="Bluetooth headphones"
    );

    category = Category(
        title="Audio",
        year=2024,
        available=True,
        slug="audio"
    );
    category_vi = Translation(
        entity_kind="category",
        locale="vi",
        name="Âm thanh",
        slug="am-thanh",
        description="Thiết bị âm thanh"
    );
    category_en = Translation(
        entity_kind="category",
        locale="en",
        name="Audio",
        slug="audio",
        description="Audio equipment"
    );

    brand = Brand(
        title="Acme Audio",
        year=2024,
        available=True,
        slug="acme-audio"
    );
    brand_vi = Translation(
        entity_kind="brand",
        locale="vi",
        name="Acme Audio",
        slug="acme-audio",
        description="Thương hiệu âm thanh"
    );
    brand_en = Translation(
        entity_kind="brand",
        locale="en",
        name="Acme Audio",
        slug="acme-audio",
        description="Audio brand"
    );

    root ++> product;
    root ++> category;
    root ++> brand;

    product +>:ProductTranslation(source_column="nameVi"):+> product_vi;
    product +>:ProductTranslation(source_column="nameEn"):+> product_en;
    product +>:ProductCategory:+> category;
    product +>:ProductBrand:+> brand;

    category +>:CategoryTranslation(source_column="nameVi"):+> category_vi;
    category +>:CategoryTranslation(source_column="nameEn"):+> category_en;
    category +>:CategoryParent:+> category;

    brand +>:BrandTranslation(source_column="nameVi"):+> brand_vi;
    brand +>:BrandTranslation(source_column="nameEn"):+> brand_en;

    root spawn ProductReader(requested_locale="ko", default_locale="en");
    root spawn CatalogAudit();
}

"""Tiny dungeon crawler: chain of rooms with one vault; a hunter walker counts rooms and stops the moment it finds the treasure."""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has seen: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can search with Room entry {
        self.seen += 1;
        if here.is_treasure {
            print(f"Found treasure in {here.name} after inspecting {self.seen} room(s).");
            disengage;
        }
        print(f"Searched {here.name} ({self.seen} so far).");
        visit [-->] else { disengage; }
    }
}

with entry {
    entry_hall = Room(name="Entry Hall");
    armory = Room(name="Armory");
    library = Room(name="Library");
    vault = Room(name="Vault", is_treasure=True);
    forbidden = Room(name="Forbidden Chamber");

    root ++> entry_hall
        ++> armory
        ++> library
        ++> vault
        ++> forbidden;

    root spawn Hunter();
}

"""Sync dependency graph: model sync files as nodes, depends_on as typed
edges, and walk the DAG to print topological order and catch cycles.

The original drt-hub/drt issue #426 asks for a declarative dependency
graph between sync files so that ``drt run --all`` can topologically
order execution and ``drt validate`` can reject cycles. Here we model
that scenario natively in Jac: a ``Sync`` node archetype carries the
file name and an ``executed`` flag, a ``DependsOn`` typed edge carries
the declared dependency, and a ``Scheduler`` walker does the
topological traversal with explicit cycle detection (because walkers
in jac 0.36.1 do not dedupe visited nodes on their own).
"""

node Sync {
    has title: str = "";
    has executed: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

walker Scheduler {
    has order: list[str] = [];
    has cycle_target: str = "";

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can order_sync with Sync entry {
        if here.executed {
            if self.cycle_target != "" {
                print(f"CYCLE detected at {here.title}");
                disengage;
            }
            visit [->:DependsOn:->];
        } else {
            here.executed = True;
            self.order.append(here.title);
            visit [->:DependsOn:->];
        }
    }
}

walker DryRun {
    has layers: list[list[str]] = [];
    has seen: list[str] = [];

    can start with Root entry {
        self.layers.append([]);
        visit [->:DependsOn:->];
    }

    can lay_out with Sync entry {
        if here.title in self.seen {
            return;
        }
        self.seen.append(here.title);
        self.layers.append([here.title]);
        visit [->:DependsOn:->];
    }
}

with entry {
    companies = Sync(title="company_lookup.yaml");
    contacts = Sync(title="contacts.yaml");
    deals = Sync(title="deals.yaml");
    reports = Sync(title="reports.yaml");

    root +>:DependsOn:+> companies;
    companies +>:DependsOn:+> contacts;
    contacts +>:DependsOn:+> deals;
    deals +>:DependsOn:+> reports;

    print("=== topological execute order ===");
    sched = Scheduler();
    root spawn sched;
    print("order: " + str(sched.order));

    print("=== --graph dry-run layout ===");
    graph = DryRun();
    root spawn graph;
    print("levels: " + str(graph.layers));
}

"""Hiking trail: chain waypoints from trailhead to summit; a hiker walker counts each stop."""

node TrailHead {
    has title: str = "";
}

node Waypoint {
    has title: str = "";
}

node Summit {
    has title: str = "";
}

walker Hiker {
    has stop: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter_trail with TrailHead entry {
        visit [-->];
    }

    can hike with Waypoint entry {
        self.stop += 1;
        print(f"Stop {self.stop}");
        visit [-->];
    }

    can finish with Summit entry {
        print(f"Trail complete — passed {self.stop} waypoint(s).");
        disengage;
    }
}

with entry {
    root ++> TrailHead(title="North Ridge Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(title="Eagle Peak");
    root spawn Hiker();
}

"""Weather sweep: stations report temperature as the walker passes, then summarize."""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker Sweep {
    has readings: list[tuple[str, float]] = [];
    has mins: list[tuple[str, float]] = [];
    has maxs: list[tuple[str, float]] = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        print(f"  reading {here.celsius}C at {here.location}");
        self.readings.append((here.location, here.celsius));
        if len(self.mins) == 0 or here.celsius < self.mins[0][1] {
            self.mins = [(here.location, here.celsius)];
        } elif here.celsius == self.mins[0][1] {
            self.mins.append((here.location, here.celsius));
        }
        if len(self.maxs) == 0 or here.celsius > self.maxs[0][1] {
            self.maxs = [(here.location, here.celsius)];
        } elif here.celsius == self.maxs[0][1] {
            self.maxs.append((here.location, here.celsius));
        }
        visit [-->];
    }
}

with entry {
    root ++> Station(location="North", celsius=12.5)
        ++> Station(location="East", celsius=17.0)
        ++> Station(location="South", celsius=23.8)
        ++> Station(location="West", celsius=9.2)
        ++> Station(location="Summit", celsius=-3.0);

    sweeper = Sweep();
    root spawn sweeper;

    print("\nAll readings:");
    for (loc, temp) in sweeper.readings {
        print(f"  {loc}: {temp}C");
    }

    min_loc = sweeper.mins[0][0];
    min_val = sweeper.mins[0][1];
    max_loc = sweeper.maxs[0][0];
    max_val = sweeper.maxs[0][1];
    print(f"\nMin: {min_val}C at {min_loc}");
    print(f"Max: {max_val}C at {max_loc}");
}

"""Call-path reachability demo: model symbols and `calls` edges, then walk the
graph with a BFS-style walker that visits only the current frontier instead of
materializing the full adjacency list up-front (the issue's complaint).

The walker's `visited` set is its only state — there is no precomputed
adjacency map. Each step queries outgoing `calls` edges of the current
symbol via typed-edge traversal `visit [->:Calls:->]`.
"""

node Symbol {
    has name: str = "";
    has kind: str = "";
}

edge Calls {
    has line: int = 0;
}

walker CallPath {
    has origin: str = "";
    has target: str = "";
    has max_depth: int = 32;
    has visited: list[str] = [];
    has found: bool = False;
    has path: list[str] = [];

    can start with Root entry {
        self.visited = [];
        self.found = False;
        self.path = [];
        visit [->:Calls:->];
    }

    can step with Symbol entry {
        sym_name = here.name;
        # Cycle policy: explicit guard set, since walkers don't dedupe on cycles.
        if sym_name in self.visited {
            return;
        }
        self.visited.append(sym_name);

        depth = len(self.visited);
        marker = "  " * depth;
        print(f"{marker}[d{depth}] enter {here.name} ({here.kind})");

        if here.name == self.target {
            self.found = True;
            self.path = list(self.visited);
            print(f"{marker}  -> reached target {self.target}");
            disengage;
        }

        if depth >= self.max_depth {
            print(f"{marker}  -> depth cap {self.max_depth} hit");
            disengage;
        }

        # Forward along typed Calls edges only — no full adjacency load.
        visit [->:Calls:->];
    }
}

walker Summary {
    has visited: list[str] = [];
    has target: str = "";
    has origin: str = "";

    can start with Root entry {
        # Replay the walk from origin, accumulating visited names; mirrors
        # how the demo's `with entry` block re-runs the BFS from another root.
        self.visited = [];
        visit [->:Calls:->];
    }

    can step with Symbol entry {
        if here.name in self.visited {
            return;
        }
        self.visited.append(here.name);
        reach = "target" if here.name == self.target else "transit";
        print(f"  summary[{reach}] {here.name}");
        visit [->:Calls:->];
    }
}

with entry {
    # A small call graph:
    #   main -> parse -> tokenize -> lex
    #                     \-> error
    #          \-> validate -> check
    #   unrelated_node (isolated)
    main = Symbol(name="main", kind="function");
    parse = Symbol(name="parse", kind="function");
    tokenize = Symbol(name="tokenize", kind="function");
    lex = Symbol(name="lex", kind="function");
    err = Symbol(name="error_handler", kind="function");
    validate = Symbol(name="validate", kind="function");
    check = Symbol(name="check", kind="function");
    unrelated = Symbol(name="unrelated_node", kind="function");

    # Typed edges: the relationship itself (`calls`) carries the line number.
    main +>:Calls(line=10):+> parse;
    main +>:Calls(line=12):+> validate;
    parse +>:Calls(line=24):+> tokenize;
    parse +>:Calls(line=27):+> err;
    tokenize +>:Calls(line=58):+> lex;

    # A cycle: validate <-> check (intentional, mirrors real call graphs).
    validate +>:Calls(line=71):+> check;
    check +>:Calls(line=92):+> validate;

    root ++> unrelated;

    print("== BFS from main to lex ==");
    cp = CallPath(origin="main", target="lex");
    root spawn cp;
    print(f"found={cp.found} path={cp.path}");

    print("\n== BFS from main to missing_node (dead-end) ==");
    cp2 = CallPath(origin="main", target="missing_node");
    root spawn cp2;
    print(f"found={cp2.found} visited={cp2.visited}");

    print("\n== Cycle probe: main -> check (cycle in graph) ==");
    cp3 = CallPath(origin="main", target="check", max_depth=8);
    root spawn cp3;
    print(f"found={cp3.found} path={cp3.path}");
}

"""Restaurant recommender: walk the dining graph and filter spots by a spawn-time minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker RestaurantFinder {
    has min_rating: float = 0.0;
    has pass_label: str = "";

    can start with Root entry {
        header = "--- " + self.pass_label + " (min rating " + str(self.min_rating) + "+) ---";
        print(header);
        visit [-->];
    }

    can review with Restaurant entry {
        if here.rating >= self.min_rating {
            print(f"[MATCH] {here.name} ({here.cuisine}) rating={here.rating}");
        }
        visit [-->];
    }
}

