"""Recursive Parquet partition discovery using native Jac graph traversal."""

node TableRoot {
    has table_name: str = "";
}

node PartitionDirectory {
    has column_name: str = "";
    has partition_value: str = "";
    has path: str = "";
    has depth: int = 0;
}

node ParquetFile {
    has path: str = "";
    has bytes: int = 0;
}

edge Contains {
    has kind: str = "";
}

walker PartitionScanner {
    has partition_columns: list[str] = [];
    has files_seen: list[str] = [];
    has visited_paths: list[str] = [];

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can enter_table with TableRoot entry {
        print(f"Scanning table: {here.table_name}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can scan_partition with PartitionDirectory entry {
        if (here.path in self.visited_paths) {
            print(f"Cycle skipped at {here.path}");
            disengage;
        }

        self.visited_paths.append(here.path);

        if (here.column_name in self.partition_columns) {
            print(f"Partition column already seen: {here.column_name}");
        } else {
            self.partition_columns.append(here.column_name);
        }

        print(f"Partition: {here.path}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can record_file with ParquetFile entry {
        self.files_seen.append(here.path);
        print(f"File: {here.path} ({here.bytes} bytes)");
    }
}

with entry {
    table = TableRoot(table_name="events");

    east = PartitionDirectory(
        column_name="zone",
        partition_value="east",
        path="zone=east",
        depth=1
    );
    east_date = PartitionDirectory(
        column_name="date",
        partition_value="2024-01-01",
        path="zone=east/date=2024-01-01",
        depth=2
    );
    east_file = ParquetFile(
        path="zone=east/date=2024-01-01/part-000.parquet",
        bytes=1200
    );

    west = PartitionDirectory(
        column_name="zone",
        partition_value="west",
        path="zone=west",
        depth=1
    );
    west_date = PartitionDirectory(
        column_name="date",
        partition_value="2024-01-02",
        path="zone=west/date=2024-01-02",
        depth=2
    );
    west_file = ParquetFile(
        path="zone=west/date=2024-01-02/part-001.parquet",
        bytes=1400
    );

    root +>:Contains(kind="table"):+> table;
    table +>:Contains(kind="partition"):+> east;
    east +>:Contains(kind="partition"):+> east_date;
    east_date +>:Contains(kind="file"):+> east_file;
    table +>:Contains(kind="partition"):+> west;
    west +>:Contains(kind="partition"):+> west_date;
    west_date +>:Contains(kind="file"):+> west_file;

    scanner = PartitionScanner();
    root spawn scanner;

    print(f"Partition columns: {scanner.partition_columns}");
    print(f"Files discovered: {scanner.files_seen}");
}

"""Factory zone monitoring with a single patrol routine for both sensor types.

One walker ability handles two sensor archetypes via a union trigger,
printing each reading as nominal or an alert, and summarizing the
alerts at the end.
"""

node Sensor {
    has label: str = "";
    has reading: float = 0.0;

    def is_alert() -> bool {
        return False;
    }

    def kind() -> str {
        return "Sensor";
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }

    override def kind() -> str {
        return "TempSensor";
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }

    override def kind() -> str {
        return "SmokeSensor";
    }
}

node Zone {
    has name: str = "";
}

walker Patrol {
    has alert_log: list[str] = [];
    has nominal_count: int = 0;
    has alert_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with Zone entry {
        print(f"--- Patrolling zone: {here.name} ---");
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        is_alerting = here.is_alert();
        if is_alerting {
            self.alert_count += 1;
            line = f"[ALERT]   {here.kind()} '{here.label}' -> {here.reading}";
            self.alert_log.append(line);
        } else {
            self.nominal_count += 1;
            line = f"[nominal] {here.kind()} '{here.label}' -> {here.reading}";
        }
        print(line);
    }
}

with entry {
    zone_a = Zone(name="Assembly");
    zone_b = Zone(name="Packaging");

    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="T-A1", reading=68.0, celsius=68.0);
    zone_a ++> TempSensor(label="T-A2", reading=91.5, celsius=91.5);
    zone_a ++> SmokeSensor(label="S-A1", reading=12.0, ppm=12.0);

    zone_b ++> TempSensor(label="T-B1", reading=74.9, celsius=74.9);
    zone_b ++> SmokeSensor(label="S-B1", reading=75.0, ppm=75.0);
    zone_b ++> SmokeSensor(label="S-B2", reading=20.0, ppm=20.0);

    patrol = Patrol();
    root spawn patrol;

    print("");
    print(f"Summary: {patrol.alert_count} alert(s), {patrol.nominal_count} nominal");
    if patrol.alert_count > 0 {
        print("Alerts:");
        for `entry in patrol.alert_log {
            print(f"  {`entry}");
        }
    }
}

