"""Signal Matrix Static Dashboard V1: per-timeframe primitive signal inventory.

Models a transparent asset x timeframe matrix where primitive signals
(HTF/LTF, Breath/Fibo frame, regime context, external catalyst context,
freshness, replay-readiness, local pattern candidates) are exposed as
nodes connected via typed edges. A walker audits the matrix for reachability,
freshness, and explicit primitive conflicts without collapsing them into a
single composed advice label.
"""

node Asset {
    has symbol: str = "";
    has market: str = "";
}

node Timeframe {
    has label: str = "";
    has minutes: int = 0;
}

node PrimitiveSignal {
    has name: str = "";
    has payload: str = "";
    has stale: bool = False;
}

node RegimeContext {
    has regime: str = "";
    has confidence: float = 0.0;
}

node CatalystContext {
    has source: str = "";
    has fresh: bool = True;
}

edge HasTimeframe { }
edge SignalsOn { }
edge HasRegime { }
edge HasCatalyst { }
edge ConflictsWith { }

walker MatrixAuditor {
    has visited_assets: list[str] = [];
    has conflict_count: int = 0;
    has stale_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_asset with Asset entry {
        if here.symbol not in self.visited_assets {
            self.visited_assets.append(here.symbol);
            print(f"[ASSET] {here.symbol} market={here.market}");
        }
        visit [->:HasTimeframe:->];
    }

    can inspect_timeframe with Timeframe entry {
        print(f"  [TF] {here.label} ({here.minutes}m)");
        visit [-->];
    }

    can inspect_primitive with PrimitiveSignal entry {
        status = "STALE" if here.stale else "LIVE";
        print(f"    [SIG {status}] {here.name} :: {here.payload}");
        if here.stale {
            self.stale_count += 1;
        }
        visit [-->];
    }

    can inspect_regime with RegimeContext entry {
        print(f"    [REGIME] {here.regime} conf={here.confidence:.2f}");
        visit [-->];
    }

    can inspect_catalyst with CatalystContext entry {
        fresh_tag = "FRESH" if here.fresh else "STALE";
        print(f"    [CATALYST {fresh_tag}] {here.source}");
        visit [-->];
    }

    can inspect_conflict with PrimitiveSignal entry {
        conflicts = [->:ConflictsWith:->];
        for (idx, nbr) in enumerate(conflicts) {
            if isinstance(nbr, PrimitiveSignal) {
                self.conflict_count += 1;
                print(f"  [CONFLICT] {here.name} <-> {nbr.name}");
            }
        }
        visit [-->];
    }
}

with entry {
    btc = Asset(symbol="BTC-USD", market="crypto");
    eth = Asset(symbol="ETH-USD", market="crypto");
    root ++> btc;
    root ++> eth;

    tf_1h = Timeframe(label="1H", minutes=60);
    tf_4h = Timeframe(label="4H", minutes=240);
    tf_1d = Timeframe(label="1D", minutes=1440);

    sig_htf_up = PrimitiveSignal(name="HTF_TREND_UP", payload="ema_stack_bull", stale=False);
    sig_ltf_up = PrimitiveSignal(name="LTF_BREATH_UP", payload="higher_highs", stale=False);
    sig_fibo_retrace = PrimitiveSignal(name="FIBO_RETRACEMENT", payload="0.618 hold", stale=False);
    sig_ltf_div = PrimitiveSignal(name="LTF_DIVERGENCE", payload="rsi_bear_div", stale=True);
    sig_replay = PrimitiveSignal(name="REPLAY_READY", payload="bar_count_ok", stale=False);

    regime_bull = RegimeContext(regime="BULL", confidence=0.72);
    regime_wary = RegimeContext(regime="CAUTIOUS_BULL", confidence=0.55);

    cat_onchain = CatalystContext(source="onchain_whale_flow", fresh=True);
    cat_macro = CatalystContext(source="macro_cpi_print", fresh=False);

    btc +>:HasTimeframe:+> tf_1h;
    tf_1h +>:SignalsOn:+> sig_htf_up;
    tf_1h +>:SignalsOn:+> sig_ltf_up;
    tf_1h +>:SignalsOn:+> sig_ltf_div;
    tf_1h +>:HasRegime:+> regime_bull;
    tf_1h +>:HasCatalyst:+> cat_onchain;

    btc +>:HasTimeframe:+> tf_4h;
    tf_4h +>:SignalsOn:+> sig_fibo_retrace;
    tf_4h +>:HasRegime:+> regime_wary;
    tf_4h +>:HasCatalyst:+> cat_macro;

    btc +>:HasTimeframe:+> tf_1d;
    tf_1d +>:SignalsOn:+> sig_replay;

    sig_ltf_up +>:ConflictsWith:+> sig_ltf_div;

    root spawn MatrixAuditor();

    final_assets = ",".join([btc.symbol, eth.symbol]);
    print(f"Matrix audited: assets={final_assets} | "
          f"conflicts exposed=1 | stale primitives surfaced=1");
}

"""Order auditor: invalid orders are skipped, fraudulent orders halt the walk.

Demonstrates two flavors of early return side by side:
  - skip-like: re-enter traversal after reporting a skipped order.
  - halt-like: bail out of the entire walk on fraud.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has skipped: int = 0;
    has halted_on: str = "";

    can start with Root entry {
        print("Audit begins");
        visit [-->] else { disengage; }
    }

    can review with Order entry {
        # Fraud halts the whole walk -- disengage on the spot.
        if here.fraud {
            self.halted_on = here.label;
            print(f"[HALT] fraud detected on {here.label} (${here.amount:.2f})");
            disengage;
        }

        # Invalid orders are skipped -- audit keeps going.
        if not here.valid {
            self.skipped += 1;
            print(f"[SKIP] {here.label} (${here.amount:.2f}) invalid");
            visit [-->] else { disengage; }
        } else {
            # Happy path: record the audit and keep walking.
            self.audited += 1;
            print(f"[OK]   {here.label} (${here.amount:.2f})");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(label="A-1001", amount=42.50, valid=True)
        ++> Order(label="A-1002", amount=19.99, valid=False)
        ++> Order(label="A-1003", amount=125.00, valid=True)
        ++> Order(label="A-1004", amount=7.25, valid=True)
        ++> Order(label="A-1005", amount=999.99, valid=True, fraud=True)
        ++> Order(label="A-1006", amount=55.00, valid=True);

    auditor = OrderAuditor();
    root spawn auditor;

    print(
        f"Audit summary: audited={auditor.audited} "
        f"skipped={auditor.skipped} "
        f"halted_on={auditor.halted_on}"
    );
}

"""Provider-native session binding to governed runtime executions.

Models issue #1889: a provider-native session (Codex, Claude, ...) is bound to
one governed RuntimeExecution epoch via an opaque reference, with explicit
host-vs-guest enforcement coverage and lifecycle re-evaluation. A stale binding
must fail closed.
"""

node RuntimeExecution {
    has name: str = "";
    has snapshot: str = "";
    has lease: str = "";
    has evidence: str = "";
    has revoked: bool = False;

    def is_authority_valid() -> bool {
        return not self.revoked;
    }
}

node ProviderBinding {
    has provider: str = "";
    has adapter_version: str = "";
    has opaque_ref: str = "";
    has coverage: str = "host-only";
}

node ToolEgress {
    has surface: str = "";
    has degraded: bool = False;
}

edge BoundTo {
    has epoch: int = 0;
}

edge HostsEgress {
    has side: str = "";
}

walker BindingAuditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_execution with RuntimeExecution entry {
        if not here.is_authority_valid() {
            self.findings.append(f"[FAIL-CLOSED] {here.name}: stale or revoked authority");
            disengage;
        }
        self.findings.append(f"[OK] execution={here.name} lease={here.lease}");
        visit [->:BoundTo:->];
    }

    can audit_binding with ProviderBinding entry {
        status = "experimental" if here.coverage == "experimental" else "supported";
        self.findings.append(
            f"[{status}] provider={here.provider} v{here.adapter_version} ref={here.opaque_ref}"
        );
        visit [->:HostsEgress:->];
    }

    can audit_egress with ToolEgress entry {
        flag = "DEGRADED" if here.degraded else "OK";
        self.findings.append(f"[{flag}] egress surface={here.surface}");
        visit [-->];
    }
}

walker StaleInvalidator {
    has target_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can find with RuntimeExecution entry {
        if here.name == self.target_name {
            here.revoked = True;
            print(f"revoked execution {here.name}; any binding fails closed");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    exec_a = RuntimeExecution(
        name="exec-A",
        snapshot="snap-001",
        lease="lease-A",
        evidence="ev-A"
    );
    exec_b = RuntimeExecution(
        name="exec-B",
        snapshot="snap-002",
        lease="lease-B",
        evidence="ev-B",
        revoked=True
    );

