"""Build dependency diamond audit: shared tasks reachable by multiple paths are counted exactly once.

Demonstrates a typed-edge walker that traverses a diamond-shaped build
dependency graph. Because Jac 0.36.1 walkers have no built-in
once-per-node visitation, the cycle/duplicate policy is preserved as
explicit domain logic in an explicit guard set on the walker.
"""

node Task {
    has title: str = "";
    has build_minutes: int = 0;
    has available: bool = True;
}

walker BuildAuditor {
    has audited_titles: list[str] = [];
    has total_minutes: int = 0;
    has guard: list[str] = [];

    can start with Root entry {
        print(f"Starting build audit from root");
        visit [-->];
    }

    can audit with Task entry {
        if here.title in self.guard {
            print(f"  skip (already audited): {here.title}");
            visit [-->];
        } else {
            self.guard.append(here.title);
            self.audited_titles.append(here.title);
            self.total_minutes = self.total_minutes + here.build_minutes;
            status = "READY" if here.available else "BLOCKED";
            print(f"  [AUDIT][{status}] {here.title} (+{here.build_minutes} min)");
            visit [-->];
        }
    }
}

with entry {
    core = Task(title="compile-core", build_minutes=10, available=True);
    utils = Task(title="link-utils", build_minutes=5, available=True);
    app = Task(title="build-app", build_minutes=20, available=True);
    tests = Task(title="run-tests", build_minutes=15, available=False);

    root ++> core;
    root ++> utils;

    core ++> app;
    utils ++> app;

    core ++> tests;
    utils ++> tests;

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"Audited {len(auditor.audited_titles)} unique tasks: {auditor.audited_titles}");
    print(f"Total build minutes: {auditor.total_minutes}");
}

"""Restore persisted registry readiness after an active materialized-view refresh."""

node MaterializedView {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: int = 0;
    has generation: int = 0;
    has active: bool = False;
}

node RegistryEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has logical_table: str = "";
    has status: str = "CatchingUp";
    has version: int = 0;
    has generation: int = 0;
    has current_checkpoint: int = 0;
    has target_checkpoint: int = 0;
    has target_authoritative: bool = False;
    has faulted: bool = False;
}

edge Hosts { }
edge HasRegistry { }

walker CatchUpCompleter {
    has active_version: int = 0;
    has active_generation: int = 0;
    has restored_count: int = 0;

    can begin with Root entry {
        visit [->:Hosts:->] else {
            disengage;
        }
    }

    can inspect_view with MaterializedView entry {
        if here.active {
            self.active_version = here.version;
            self.active_generation = here.generation;
            print(f"refreshing active view version {here.version}");
            visit [->:HasRegistry:->] else {
                disengage;
            }
        }
    }

    can restore_registry with RegistryEntry entry {
        if here.version == self.active_version {
            if here.generation == self.active_generation {
                if here.status == "CatchingUp" {
                    if here.target_authoritative {
                        if here.current_checkpoint >= here.target_checkpoint {
                            if here.faulted {
                                print(f"{here.logical_table}: fault blocks promotion");
                            } else {
                                here.status = "Active";
                                self.restored_count = self.restored_count + 1;
                                print(f"{here.logical_table}: registry is Active");
                            }
                        } else {
                            print(f"{here.logical_table}: target is incomplete");
                        }
                    } else {
                        print(f"{here.logical_table}: target is not authoritative");
                    }
                }
            }
        }
    }
}

with entry {
    view = MaterializedView(
        title="Orders projection",
        version=3,
        generation=1,
        active=True
    );

    orders = RegistryEntry(
        title="Orders registry",
        logical_table="orders",
        version=3,
        generation=1,
        current_checkpoint=128,
        target_checkpoint=120,
        target_authoritative=True
    );

    customers = RegistryEntry(
        title="Customers registry",
        logical_table="customers",
        version=3,
        generation=1,
        current_checkpoint=91,
        target_checkpoint=91,
        target_authoritative=True
    );

    root +>:Hosts:+> view;
    view +>:HasRegistry:+> orders;
    view +>:HasRegistry:+> customers;

    print("before completion: registry rows are CatchingUp");
    root spawn CatchUpCompleter();
}

"""Stephanos Codex dispatch bridge demo.

Models the missing canonical bridge between a GitHub repair instruction
and the Stephanos Codex dispatch machinery. Four core entity archetypes
participate in the cycle:

  RepairInstruction -> canonical dispatch record -> worker claim receipt
  -> guarded implementation execution -> terminal receipt -> review dispatch

Relationships are encoded as typed edges so the dispatch lifecycle is a
walk over typed connections rather than hand-rolled id plumbing.
"""

node RepairInstruction {
    has title: str = "";
    has issue_number: int = 0;
    has source_head: str = "";
    has branch: str = "";
    has bounded_scope: str = "";
}

node DispatchRecord {
    has task_id: str = "";
    has exact_head: str = "";
    has branch: str = "";
    has lease_id: str = "";
    has status: str = "OPEN";
    has duplicate: bool = False;
}

node ClaimReceipt {
    has worker_id: str = "";
    has task_id: str = "";
    has exact_head: str = "";
    has branch: str = "";
    has lease_id: str = "";
    has heartbeat: int = 0;
    has terminal: str = "";
}

node ReviewDispatch {
    has reviewer: str = "";
    has task_id: str = "";
    has verdict: str = "PENDING";
}

edge CanonicalizedAs { }
edge ClaimedBy { }
edge ExecutesUnder { }
edge ReviewedBy { }

walker Bridge {
    has worker_id: str = "worker-01";
    has active_terminal: str = "DONE";

    can start with Root entry {
        print(f"[bridge] {self.worker_id} begins canonical lifecycle walk");
        visit [->:CanonicalizedAs:->];
    }

    can canonicalize with RepairInstruction entry {
        print(f"[bridge] canonicalizing instruction '{here.title}' (issue #{here.issue_number})");
        visit [->:ClaimedBy:->];
    }

    can claim with DispatchRecord entry {
        # Fail-closed duplicate guard: an OPEN dispatch with the same
        # task_id already on this walker means a parallel lane exists.
        if here.status == "OPEN" and not here.duplicate {
            here.status = "CLAIMED";
            here.duplicate = False;
            visit [->:ExecutesUnder:->];
        } else {
            print(f"[bridge] reject: duplicate/conflicting dispatch {here.task_id}");
            disengage;
        }
    }

    can execute with ClaimReceipt entry {
        # Writable execution only proceeds if head, branch, lease all
        # match the dispatch contract. Heartbeat is bumped here.
        here.worker_id = self.worker_id;
        here.heartbeat += 1;
        print(f"[bridge] heartbeat {here.heartbeat} on {here.task_id}");
        visit [->:ReviewedBy:->];
    }

    can review with ReviewDispatch entry {
        here.reviewer = "exact-head-reviewer";
        here.verdict = "ACCEPTED";
        print(f"[bridge] review dispatched for {here.task_id}: {here.verdict}");
    }
}

with entry {
    instr = RepairInstruction(
        title="Wire guarded implementation pickup",
        issue_number=1622,
        source_head="abc123",
        branch="codex/implementation-1622",
        bounded_scope="src/dispatch/implementation.py"
    );
    dispatch = DispatchRecord(
        task_id="impl-1622",
        exact_head="abc123",
        branch="codex/implementation-1622",
        lease_id="lease-7f2",
        status="OPEN"
    );
    claim = ClaimReceipt(
        worker_id="",
        task_id="impl-1622",
        exact_head="abc123",
        branch="codex/implementation-1622",
        lease_id="lease-7f2",
        heartbeat=0
    );
    review = ReviewDispatch(task_id="impl-1622");

    root +>:CanonicalizedAs:+> instr +>:ClaimedBy:+> dispatch
        +>:ExecutesUnder:+> claim +>:ReviewedBy:+> review;

    # Bounded end-to-end cycle: canonicalize -> claim -> execute -> review.
    root spawn Bridge(active_terminal="DONE");
}

"""Bounded LLC authorization over line managers and live project leads."""

node Company {
    has company_id: str = "";
    has name: str = "";
}

node Person {
    has user_id: str = "";
    has name: str = "";
    has company_id: str = "";
    has hop: int = -1;
    has processed_token: str = "";
}

node Project {
    has project_id: str = "";
    has name: str = "";
    has company_id: str = "";
    has active: bool = True;
    has hop: int = -1;
    has processed_token: str = "";
}

node Card {
    has card_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has company_id: str = "";
    has creator_id: str = "";
}

edge CreatedBy {}
edge LineManager {}
edge ReportsOn {}
edge ProjectLead {}

walker Authorization {
    has actor_id: str = "";
    has company_id: str = "";
    has target_card_id: str = "";
    has token: str = "";
    has granted: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can open with Company entry {
        visit [-->] else {
            disengage;
        }
    }

    can check with Card entry {
        if here.card_id == self.target_card_id
            and here.company_id == self.company_id {
            if here.creator_id != "" {
                for creator in [->:CreatedBy:->] {
                    if creator.user_id == here.creator_id
                        and creator.company_id == here.company_id {
                        creator.hop = 0;
                        creator.processed_token = "";
                        visit creator;
                    }
                }
            }
        }
    }

    can climb with Person entry {
        if here.processed_token != self.token {
            here.processed_token = self.token;

            if here.company_id == self.company_id {
                if here.user_id == self.actor_id {
                    self.granted = True;
                }

                if here.hop < 2 {
                    for manager in [->:LineManager:->] {
                        if manager.company_id == here.company_id {
                            manager_hop = here.hop + 1;
                            if manager.processed_token != self.token
                                or manager.hop > manager_hop {
                                manager.hop = manager_hop;
                                manager.processed_token = "";
                                visit manager;
                            }
                        }
                    }

                    for project in [->:ReportsOn:->] {
                        if project.company_id == here.company_id
                            and project.active {
                            project_hop = here.hop + 1;
                            if project_hop <= 2 {
                                project.hop = project_hop;
                                project.processed_token = "";
                                visit project;
                            }
                        }
                    }
                }
            }
        }
    }

    can follow with Project entry {
        if here.processed_token != self.token {
            here.processed_token = self.token;

            if here.active
                and here.company_id == self.company_id
                and here.hop < 2 {
                for lead in [->:ProjectLead:->] {
                    if lead.company_id == self.company_id {
                        lead_hop = here.hop + 1;
                        if lead_hop <= 2
                            and (lead.processed_token != self.token
                                or lead.hop > lead_hop) {
                            lead.hop = lead_hop;
                            lead.processed_token = "";
                            visit lead;
                        }
                    }
                }
            }
        }
    }
}

