"""Kanban dispatcher: model orphaned claim locks on non-running cards.

Demonstrates the gap where a card in ready/todo/blocked that still carries
a stale claim_lock/claim_expires is invisible to the dispatcher. A
``Dispatcher`` walker traverses ready cards via a typed ``Claim`` edge and
runs a ``ReclaimSweep`` walker that clears only truly orphaned claims,
using a grace window so a second ticker cannot nuke a freshly claimed card.
"""

node Worker {
    has worker_id: str = "";
    has pid: int = 0;
}

node Card {
    has title: str = "";
    has status: str = "ready";
    has claim_lock: str | None = None;
    has claim_expires: str | None = None;
}

node WorkerRoster {
    has alive_ids: list[str] = [];
}

edge Claim {
    has claimed_by: str = "";
    has expires_at: str = "";
}

edge Rostered { }

# --- Dispatcher: walks ready cards and reports those it can/can't see ----
walker Dispatcher {
    has dispatched: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Card entry {
        if here.status in ["ready", "todo", "blocked"] {
            if here.claim_lock is None {
                self.dispatched.append(here.title);
                print(f"[DISPATCH] {here.title} (status={here.status})");
            } else {
                print(f"[SKIP]    {here.title} holds stale claim '{here.claim_lock}'");
            }
        }
        visit [-->];
    }
}

# --- Reclaim sweep: clear only orphaned claims (dead PID + expired/grace) -
walker ReclaimSweep {
    has grace_seconds: int = 30;
    has now_epoch: int = 100000;
    has cleared: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Card entry {
        if here.status in ["ready", "todo", "blocked"] and here.claim_lock is not None {
            # Simulate PID-alive lookup: only worker "alive-worker" is considered alive.
            worker_alive = here.claim_lock == "alive-worker";
            claim_expired_or_graced = (here.claim_expires is not None)
                and ((self.now_epoch - int(here.claim_expires)) >= self.grace_seconds);

            if (not worker_alive) and claim_expired_or_graced {
                victim = here.title;
                here.claim_lock = None;
                here.claim_expires = None;
                self.cleared.append(victim);
                print(f"[RECLAIM] {victim} -> claim cleared");
            }
        }
        visit [-->];
    }
}

with entry {
    # Build the graph: root -> roster + a chain of cards.
    roster = WorkerRoster(alive_ids=["alive-worker"]);
    root ++> roster;

    # Card A: clean, dispatchable.
    a = Card(title="A-clean");
    # Card B: claimed by a worker whose PID is dead and claim is expired -> orphan.
    b = Card(title="B-orphan", claim_lock="dead-worker", claim_expires="99900");
    # Card C: claimed by a still-alive worker; must NOT be reclaimed.
    c = Card(title="C-fresh", claim_lock="alive-worker", claim_expires="99990");
    # Card D: claimed by dead worker but claim is within grace window -> keep.
    d = Card(title="D-just-claimed", claim_lock="dead-worker", claim_expires="99985");

    # Typed Claim edges express the relationship between card and claimer.
    a +>:Claim(claimed_by="", expires_at=""):+> Worker(worker_id="none");
    b +>:Claim(claimed_by="dead-worker", expires_at="99900"):+> Worker(worker_id="W-9");
    c +>:Claim(claimed_by="alive-worker", expires_at="99990"):+> Worker(worker_id="W-1");
    d +>:Claim(claimed_by="dead-worker", expires_at="99985"):+> Worker(worker_id="W-7");

    root ++> a ++> b ++> c ++> d;

    print("--- Before sweep: dispatcher sees ---");
    disp = Dispatcher();
    root spawn disp;

    print("--- Running reclaim sweep ---");
    sweep = ReclaimSweep(grace_seconds=30, now_epoch=100000);
    root spawn sweep;

    print("--- After sweep: dispatcher sees ---");
    disp2 = Dispatcher();
    root spawn disp2;

    print(f"cleared cards: {sweep.cleared}");
    print(f"dispatched cards: {disp2.dispatched}");
}

"""Azure Compute Gallery image lineage: model VM image versions, their
typed parent/child derivation chain, and walk the ancestry with a
lineage auditor. Recursive, immutable, cycle-safe."""

# ---------------------------------------------------------------------------
# Core entity archetypes
# ---------------------------------------------------------------------------

node Resource {
    has resource_id: str = "";
    has resource_type: str = "";
    has subscription: str = "";
    has tenant: str = "";
    has created_at: str = "";
    has content_hash: str = "";
    has lineage_unavailable: bool = False;
}

node GalleryImageVersion(Resource) {
    has version_name: str = "";
    has published: bool = False;
}

node ManagedImage(Resource) {
    has image_name: str = "";
}

node ManagedDisk(Resource) {
    has disk_name: str = "";
    has size_gb: int = 0;
}

node Snapshot(Resource) {
    has snapshot_name: str = "";
}

# ---------------------------------------------------------------------------
# Typed edges: derivation relationships carry the workflow that produced the
# child artifact. The payloads are kept so traversal and reporting can show
# exactly how a child was produced from its parent.
# ---------------------------------------------------------------------------

edge DerivedFrom {
    has workflow: str = "";
    has recorded_at: str = "";
}

# ---------------------------------------------------------------------------
# Walker: Lineage Auditor
#
# Walks the derivation graph upward via [<-:DerivedFrom:<-] from any starting
# artifact, accumulating the full ancestry chain up to a golden root. Cycle
# policy is explicit: a guard set tracks visited nodes because jac 0.36.1
# walkers have no built-in dedupe on cyclic graphs.
# ---------------------------------------------------------------------------

walker LineageAuditor {
    has visited_ids: list[str] = [];
    has lineage_chain: list[dict] = [];
    has root_reached: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Resource entry {
        # Cycle policy: refuse to re-visit a node we've already audited so
        # cyclic derivation chains (e.g. mutual copies) cannot hang the walk.
        if here.resource_id in self.visited_ids {
            print(f"[cycle] revisiting {here.resource_id}; stopping upward walk");
            self.root_reached = True;
            disengage;
        }
        self.visited_ids.append(here.resource_id);

        if here.lineage_unavailable {
            print(f"[imported] {here.resource_id} ({here.resource_type}) "
                  f"-- lineage unavailable, was imported externally");
            self.root_reached = True;
            disengage;
        }

        record = {
            "resource_id": here.resource_id,
            "resource_type": here.resource_type,
            "subscription": here.subscription,
            "tenant": here.tenant,
            "created_at": here.created_at,
            "content_hash": here.content_hash,
            "lineage_unavailable": here.lineage_unavailable,
        };
        self.lineage_chain.append(record);
        print(f"[step] {here.resource_id} ({here.resource_type}) "
              f"sub={here.subscription} tenant={here.tenant} "
              f"hash={here.content_hash}");

        # Walk upward along the derivation edge. If there is no parent we
        # have reached the root source of this lineage.
        parents = [<-:DerivedFrom:<-];
        if parents {
            visit parents;
        } else {
            self.root_reached = True;
            print(f"[root] reached golden source: {here.resource_id}");
        }
    }
}

# ---------------------------------------------------------------------------
# Walker: Cycle Detector
#
# Starts from any node and reports whether a cycle is reachable in the
# derivation graph. Uses the same guard-set policy as the auditor.
# ---------------------------------------------------------------------------

walker CycleDetector {
    has visited_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with Resource entry {
        if here.resource_id in self.visited_ids {
            self.cycle_found = True;
            print(f"[cycle] re-entered {here.resource_id}");
            disengage;
        }
        self.visited_ids.append(here.resource_id);

        children = [->:DerivedFrom:->];
        if children {
            visit children;
        }
    }
}

# ---------------------------------------------------------------------------
# Demo graph: build a small golden -> derivative -> modified -> gallery chain
# and a separate imported artifact, then audit each.
# ---------------------------------------------------------------------------

with entry {
    # Golden root: a published gallery image version in the central sub.
    golden = GalleryImageVersion(
        resource_id="/sub/central/giv/golden-1.0",
        resource_type="GalleryImageVersion",
        subscription="central",
        tenant="contoso",
        created_at="2025-01-15T00:00:00Z",
        content_hash="sha256:golden",
        version_name="1.0.0",
        published=True,
    );

    # Approved derivative: a managed image copied from golden.
    approved_image = ManagedImage(
        resource_id="/sub/child-a/img/approved-1",
        resource_type="ManagedImage",
        subscription="child-a",
        tenant="contoso",
        created_at="2025-02-01T00:00:00Z",
        content_hash="sha256:approved",
        image_name="approved-1",
    );

    # Modified copy: a managed disk derived from the approved image.
    modified_disk = ManagedDisk(
        resource_id="/sub/child-a/disk/modified-1",
        resource_type="ManagedDisk",
        subscription="child-a",
        tenant="contoso",
        created_at="2025-03-10T00:00:00Z",
        content_hash="sha256:modified",
        disk_name="modified-1",
        size_gb=128,
    );

    # Registered derivative: a snapshot of the modified disk, republished.
    registered_snapshot = Snapshot(
        resource_id="/sub/child-a/snap/registered-1",
        resource_type="Snapshot",
        subscription="child-a",
        tenant="contoso",
        created_at="2025-04-05T00:00:00Z",
        content_hash="sha256:registered",
        snapshot_name="registered-1",
    );

    # A new gallery image version produced from the registered snapshot.
    child_giv = GalleryImageVersion(
        resource_id="/sub/child-a/giv/derived-2.0",
        resource_type="GalleryImageVersion",
        subscription="child-a",
        tenant="contoso",
        created_at="2025-05-01T00:00:00Z",
        content_hash="sha256:derived",
        version_name="2.0.0",
        published=True,
    );

    # Imported artifact: lineage is explicitly unavailable.
    imported_disk = ManagedDisk(
        resource_id="/sub/child-b/disk/imported-1",
        resource_type="ManagedDisk",
        subscription="child-b",
        tenant="contoso",
        created_at="2025-02-20T00:00:00Z",
        content_hash="sha256:imported",
        disk_name="imported-1",
        size_gb=64,
        lineage_unavailable=True,
    );

    # Wire the derivation graph with typed edges carrying the workflow.
    root ++> golden;
    golden +>:DerivedFrom(workflow="publish", recorded_at="2025-01-15T00:00:00Z"):+> approved_image;
    approved_image +>:DerivedFrom(workflow="copy", recorded_at="2025-02-01T00:00:00Z"):+> modified_disk;
    modified_disk +>:DerivedFrom(workflow="snapshot", recorded_at="2025-04-05T00:00:00Z"):+> registered_snapshot;
    registered_snapshot +>:DerivedFrom(workflow="gallery-create", recorded_at="2025-05-01T00:00:00Z"):+> child_giv;
    root ++> imported_disk;

    # --- Demo 1: audit a fully traced derivative ---
    print("=== audit: child_giv (full chain to golden) ===");
    auditor1 = LineageAuditor();
    child_giv spawn auditor1;
    print(f"chain length = {len(auditor1.lineage_chain)}, "
          f"root reached = {auditor1.root_reached}");
    last = auditor1.lineage_chain[-1];
    print(f"root source = {last['resource_id']} "
          f"(type={last['resource_type']}, sub={last['subscription']})");

    # --- Demo 2: audit the imported artifact ---
    print("\n=== audit: imported_disk (lineage unavailable) ===");
    auditor2 = LineageAuditor();
    imported_disk spawn auditor2;
    print(f"chain length = {len(auditor2.lineage_chain)}, "
          f"root reached = {auditor2.root_reached}");

    # --- Demo 3: detect a cycle if one is introduced ---
    print("\n=== cycle detection on the approved-derivative chain ===");
    detector = CycleDetector();
    child_giv spawn detector;
    print(f"cycle_found = {detector.cycle_found}");
}

