"""Custom-attribute guard/decode agreement: model the byte-exactness invariant
that the guard must skip exactly the bytes the decoder consumes.

Two implementations (a guard and a decoder) walk the same custom-attribute
blob and must agree on width. A divergence is a safety defect because the
guard's approval stops bounding the decode: trailing bytes become an
attacker-chosen count that was already approved. We model that here with a
walker that traverses serialized-attribute payloads via typed edges and
surfaces any guard/decoder disagreement as a fidelity violation.
"""

node AttrBlob {
    has name: str = "";
    has raw_bytes: int = 0;
}

node EnumDef {
    has enum_name: str = "";
    has width: int = 4;
}

node SzArrayElem {
    has kind: str = "";
    has payload_len: int = 0;
    has elem_width: int = 4;
}

edge HoldsArg { has ordinal: int = 0; }
edge ResolvesTo { has resolved_width: int = 0; }

walker GuardDecoder {
    has divergences: int = 0;

    can start with Root entry {
        print("Guard/decoder agreement walk starting on root");
        visit [-->] else { disengage; }
    }

    can inspect_blob with AttrBlob entry {
        print(f"--- blob: {here.name} ({here.raw_bytes} raw bytes) ---");
        visit [->:HoldsArg:->];
    }

    can inspect_arg with SzArrayElem entry {
        # The guard's assumption: a fixed 4-byte element width.
        guard_bytes = 2 + (here.payload_len * 4);
        # The decoder's actual consumption: the per-element width that was
        # resolved for this argument's enum type (the bug #4981 fixed).
        decode_bytes = 2 + (here.payload_len * here.elem_width);

        if guard_bytes != decode_bytes {
            self.divergences += 1;
            print(
                f"  DIVERGENCE on {here.kind}: guard={guard_bytes} "
                f"decoder={decode_bytes} (elem_width={here.elem_width})"
            );
        } else {
            print(
                f"  ok   {here.kind}: guard=decoder={guard_bytes} "
                f"(elem_width={here.elem_width})"
            );
        }
    }

    can show_enum with EnumDef entry {
        print(f"  enum def {here.enum_name} canonical width = {here.width}");
    }
}

with entry {
    # The element type resolves to an enum whose canonical width is 2.
    enum_def = EnumDef(enum_name="MyEnum", width=2);

    # Element #0: guard and decoder agree (elem_width = 2, payload_len = 2
    # => guard=2+2*4=10, decoder=2+2*2=6 -- mismatch is the safety defect).
    # Element #1: guard and decoder agree.
    elem0 = SzArrayElem(kind="MyEnum", payload_len=2, elem_width=2);
    elem1 = SzArrayElem(kind="MyEnum", payload_len=3, elem_width=2);
    # Element #2: deliberately mis-resolved to width 4 to model a guard
    # that approves 4-byte elements while the decoder still consumes 2.
    elem2 = SzArrayElem(kind="MyEnum", payload_len=4, elem_width=4);

    blob = AttrBlob(name="MyAttr", raw_bytes=24);

    blob +>:HoldsArg(ordinal=0):+> elem0;
    blob +>:HoldsArg(ordinal=1):+> elem1;
    blob +>:HoldsArg(ordinal=2):+> elem2;

    elem0 +>:ResolvesTo(resolved_width=2):+> enum_def;
    elem1 +>:ResolvesTo(resolved_width=2):+> enum_def;
    elem2 +>:ResolvesTo(resolved_width=2):+> enum_def;

    root ++> blob ++> enum_def;

    print("=== run 1: three SZ array arguments on one blob ===");
    w1 = GuardDecoder();
    root spawn w1;
    print(f"run 1 divergences: {w1.divergences}");
}

"""Production-grade release contract demo: model release pipelines as a graph
of artifacts, gates, and provenance edges. A walker audits the release by
walking the dependency graph, validating each gate in topological order, and
reporting failures on invalidation."""

# Release artifacts: the things a release ships.
node Artifact {
    has name: str = "";
    has sha256: str = "";
    has byte_size: int = 0;
    has deterministic: bool = True;
}

# An engineering gate that must pass before a release ships (tests, lint,
# SBOM, smoke, license-presence, etc.). Gates can depend on other gates.
node Gate {
    has name: str = "";
    has passed: bool = False;
    has required: bool = True;
}

# A license artifact bundled with the ship.
node License {
    has name: str = "";
    has present: bool = True;
}

# Dependency between gates (e.g. "unit tests" must run before "smoke test").
# Carries meaning -> typed edge.
edge MustPassBefore {}

# A gate produces / attests to an artifact.
edge Produces {}

# A gate requires a license to be bundled.
edge RequiresLicense {}

walker ReleaseAuditor {
    has failures: list[str] = [];
    has visited_gates: list[str] = [];
    has artifact_ok: bool = True;
    has license_ok: bool = True;

    can start with Root entry {
        print("Release audit: walking dependency graph from gates...");
        visit [-->];
    }

    can audit_gate with Gate entry {
        # Cycle safety: explicit guard (jac 0.36.1 walkers have no
        # built-in once-per-node visitation on cyclic graphs).
        if here.name in self.visited_gates {
            return;
        }
        self.visited_gates.append(here.name);

        # Gate-level rule: required gates must pass.
        if here.required and not here.passed {
            self.failures.append(f"GATE-FAIL: {here.name} did not pass");
        } else {
            print(f"  [gate-ok] {here.name}");
        }

        # Visit upstream prerequisites first so audit follows dependency
        # order, then produced artifacts and required licenses.
        visit [->:MustPassBefore:->];
        visit [->:Produces:->];
        visit [->:RequiresLicense:->];
    }

    can audit_artifact with Artifact entry {
        # Determinism + size invariants.
        if not here.deterministic {
            self.artifact_ok = False;
            self.failures.append(
                f"ARTIFACT-FAIL: {here.name} is not byte-deterministic"
            );
        }
        if here.byte_size <= 0 {
            self.artifact_ok = False;
            self.failures.append(
                f"ARTIFACT-FAIL: {here.name} has non-positive byte size"
            );
        }
        if here.sha256 == "" {
            self.artifact_ok = False;
            self.failures.append(
                f"ARTIFACT-FAIL: {here.name} missing SHA-256"
            );
        }
        if self.artifact_ok {
            print(f"  [artifact-ok] {here.name} "
                  f"(sha256={here.sha256[:8]}..., {here.byte_size}B)");
        }
    }

    can audit_license with License entry {
        if not here.present {
            self.license_ok = False;
            self.failures.append(
                f"LICENSE-FAIL: {here.name} not bundled with ship"
            );
        } else {
            print(f"  [license-ok] {here.name}");
        }
    }
}

with entry {
    # --- Build the release graph ---
    # Artifacts
    grapher = Artifact(
        name="grapher.bundle.js",
        sha256="abc123def456abc123def456abc123def456abc123def456abc123def456abcd",
        byte_size=482310,
        deterministic=True
    );
    sbom = Artifact(
        name="release.sbom.json",
        sha256="111222333444555666777888999aaabbbccc",
        byte_size=12044,
        deterministic=True
    );
    # A flaky artifact: deterministic flag missing -> audit must fail.
    flaky = Artifact(
        name="flaky.artifact",
        sha256="",
        byte_size=0,
        deterministic=False
    );

    # License bundled with the ship.
    mit = License(name="MIT-license.txt", present=True);
    missing_license = License(name="GPL-notice.txt", present=False);

    # Gates with their dependency edges.
    unit = Gate(name="unit-tests", passed=True, required=True);
    lint = Gate(name="lint", passed=True, required=True);
    smoke = Gate(name="chromium-smoke", passed=True, required=True);
    sbom_gate = Gate(name="sbom-gen", passed=True, required=True);
    # A failing required gate -> audit must record it.
    audit_log = Gate(name="runtime-audit", passed=False, required=True);

    # Dependency ordering: unit + lint + sbom-gen must precede smoke;
    # smoke precedes the final release audit gate.
    unit +>:MustPassBefore:+> smoke;
    lint +>:MustPassBefore:+> smoke;
    sbom_gate +>:MustPassBefore:+> smoke;
    smoke +>:MustPassBefore:+> audit_log;

    # Gates produce / attest artifacts.
    sbom_gate +>:Produces:+> sbom;
    smoke +>:Produces:+> grapher;

    # Gates require license artifacts.
    smoke +>:RequiresLicense:+> mit;
    smoke +>:RequiresLicense:+> missing_license;
    # A gate referencing a flaky one to show cascade invalidation.
    audit_log +>:Produces:+> flaky;

    # Wire onto the root graph.
    root ++> unit ++> lint ++> sbom_gate ++> smoke ++> audit_log;

    # Spawn the auditor on the graph and report results.
    auditor = ReleaseAuditor();
    root spawn auditor;

    print("\n--- release audit summary ---");
    if auditor.failures {
        print(f"FAILURES ({len(auditor.failures)}):");
        for f in auditor.failures {
            print(f"  - {f}");
        }
    } else {
        print("all gates, artifacts, and licenses passed");
    }
    print(f"gates visited in order: {auditor.visited_gates}");
    print(f"artifact invariants ok : {auditor.artifact_ok}");
    print(f"license invariants ok : {auditor.license_ok}");
}

