"""NYC official-source catalog demo.

Models the BORG inventory of alternate official NYC APIs as nodes
(Source, ConflictAssertion, Observation) connected by typed edges
(SourceDeclares, AssertsCompeting, PreservesRaw). A walker traverses
the registry, collecting conflicts without overwriting competing
assertions and reporting circuit-breaker freshness status.
"""

node Source {
    has source_id: str = "";
    has authority_class: str = "";
    has jurisdiction: str = "";
    has endpoint: str = "";
    has cadence: str = "";
    has schema_fingerprint: str = "";
    has license_notes: str = "";
    has consumer_status: str = "candidate";
    has circuit_open: bool = False;
}

node Observation {
    has source_native_id: str = "";
    has raw_preserved: bool = True;
    has record_kind: str = "";
}

node ConflictAssertion {
    has field_name: str = "";
    has field_value: str = "";
    has selected_reason: str = "";
}

edge SourceDeclares {
    has registered_at: str = "";
}

edge AssertsCompeting {
    has assertion_role: str = "candidate";
}

edge PreservesRaw {
    has ingestion_phase: str = "pre-normalization";
}

walker BorgRegistrar {
    has catalog: list = [];
    has conflicts: list = [];
    has open_circuits: list = [];

    can start with Root entry {
        visit [-->];
    }

    can ingest with Source entry {
        self.catalog.append(here.source_id);
        if here.circuit_open {
            self.open_circuits.append(here.source_id);
