    can reconcile with ConflictAssertion entry {
        label = "SELECTED" if here.selected_reason else "COMPETING";
        self.conflicts.append(here.field_name);
        print(f"  conflict on {here.field_name}={here.field_value} "
              f"-> {label}: {here.selected_reason}");
        visit [-->];
    }
}

