"""Offline retrospective workflow demo with typed relationships and cycle-safe walking."""

node DemoProject {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Retrospective {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stage: str = "COLLECTING";
    has summary: str = "";
}

node Card {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has author: str | None = None;
    has anonymous: bool = False;
    has position: int = 0;
    has vote_points: int = 0;
}

node Cluster {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has vote_budget: int = 0;
    has votes_used: int = 0;
}

edge HasRetrospective { }
edge ContainsContent {
    has kind: str = "";
}
edge ContainsCard { }
edge VoteOn {
    has points: int = 0;
}

walker DemoAuditor {
    has remaining_depth: int = 9;

    can begin with Root entry {
        print("Auditing the retrospective demo");
        visit [-->] else {
            disengage;
        }
    }

    can audit_project with DemoProject entry {
        if self.remaining_depth <= 0 {
            print("Depth limit reached; stopping safely");
            disengage;
        }
        self.remaining_depth = self.remaining_depth - 1;
        print(f"Project: {here.title}");
        visit [->:HasRetrospective:->] else {
            disengage;
        }
    }

    can audit_retrospective with Retrospective entry {
        if self.remaining_depth <= 0 {
            print("Depth limit reached; stopping safely");
            disengage;
        }
        self.remaining_depth = self.remaining_depth - 1;
        print(f"Cycle: {here.title} [{here.stage}]");
        if here.stage == "PUBLISHED" {
            print(f"Published summary: {here.summary}");
        }
        visit [->:ContainsContent:->] else {
            disengage;
        }
    }

    can audit_cluster with Cluster entry {
        if self.remaining_depth <= 0 {
            print("Depth limit reached; stopping safely");
            disengage;
        }
        self.remaining_depth = self.remaining_depth - 1;
        if here.votes_used <= here.vote_budget {
            print(f"Cluster: {here.title} votes {here.votes_used}/{here.vote_budget}");
        } else {
            print(f"Invalid vote budget in cluster: {here.title}");
        }
        visit [->:ContainsCard:->] else {
            disengage;
        }
    }

    can audit_card with Card entry {
        if self.remaining_depth <= 0 {
            print("Depth limit reached; stopping safely");
            disengage;
        }
        self.remaining_depth = self.remaining_depth - 1;
        if here.anonymous {
            print(f"Anonymous card: {here.title} at position {here.position}");
        } else {
            print(f"Attributed card: {here.title} by {here.author}");
        }
        print(f"Vote points: {here.vote_points}");
        visit [->:VoteOn:->] else {
            disengage;
        }
    }
}

