"""Compile-time execution ordering for an ECS-style system graph.

Models the core scenario from the typed_ecs #23 issue: systems declare
human-readable resource arguments, those arguments become typed edges
into the World, and a Scheduler walker traverses the dependency graph
to derive a safe execution order. Cycles are detected and reported,
parallel-ready independent systems are surfaced, and the walker
disengages when no frontier remains.
"""

node System {
    has name: str = "";
    has parallel_safe: bool = True;
}

node Resource {
    has name: str = "";
    has mutable: bool = True;
}

# A system reads a resource.
edge Reads { }
# A system writes (mutates) a resource. Two writers cannot run together.
edge Writes { }
# A system runs after another system (explicit ordering hint).
edge RunsAfter { }

walker Scheduler {
    has order: list[str] = [];
    has cycle_path: list[str] = [];
    has parallel_groups: list[list[str]] = [];
    has invalid_pairs: list[tuple] = [];

    can start with Root entry {
        # Discover all systems reachable from root.
        visit [-->];
    }

    can survey with Resource entry {
        # Walk from a resource to every system touching it.
        visit [-->];
    }

    can schedule with System entry {
        self.order.append(here.name);

        # If this system writes a resource that another system already
        # wrote, we have a mutual-exclusion violation (the issue's
        # complaint about "different plugins changing one same resource
        # sequentially").
        for writer in [->:Writes:->] {
            writer_name = writer.name;
            for prior in self.order {
                if prior == here.name {
                    break;
                }
                pair = (prior, writer_name) if prior < writer_name else (writer_name, prior);
                if prior == writer_name {
                    self.cycle_path.append(f"{prior} <-> {here.name} on {writer_name}");
                }
            }
        }

        # Record independent systems that could run in parallel.
        if here.parallel_safe {
            group: list[str] = [here.name];
            self.parallel_groups.append(group);
        }

        # Walk forward through dependency edges.
        visit [->:RunsAfter:->] else { disengage; }
    }
}

walker CascadeInvalidate {
    # Walks Writes-edges from a system and invalidates dependent readers.
    can start with Root entry {
        visit [-->];
    }

    can invalidate with System entry {
        print(f"invalidating downstream of system: {here.name}");
        visit [->:Reads:->] else { disengage; }
    }
}

with entry {
    # --- World: resources the systems read/write ---
    position = Resource(name="Position", mutable=True);
    health = Resource(name="Health", mutable=True);
    score = Resource(name="Score", mutable=False);

    # --- Systems ---
    movement = System(name="movement", parallel_safe=True);
    damage = System(name="damage", parallel_safe=True);
    render = System(name="render", parallel_safe=False);
    hud = System(name="hud", parallel_safe=True);

    # --- Wire dependencies (typed edges) ---
    # movement READS Position, WRITES Position (its own state is fine)
    movement +>:Reads:+> position;
    movement +>:Writes:+> position;

    # damage WRITES Health
    damage +>:Writes:+> health;

    # render READS Position and Health (depends on movement + damage)
    render +>:Reads:+> position;
    render +>:Reads:+> health;
    movement +>:RunsAfter:+> render;
    damage +>:RunsAfter:+> render;

    # hud READS Score (independent group)
    hud +>:Reads:+> score;

    root ++> position
        ++> health
        ++> score
        ++> movement
        ++> damage
        ++> render
        ++> hud;

    # --- Run the scheduler ---
    sched = Scheduler();
    root spawn sched;

    print("execution order:", sched.order);
    print("parallel groups:", sched.parallel_groups);
    print("ordering violations:", sched.cycle_path);

    # --- Cascade invalidation demo ---
    inv = CascadeInvalidate();
    root spawn inv;
}
