"""Pipeline tracer: walk a network of pipes from the intake, noting dead ends."""

node Valve {
    has label: str = "";
}

node Pipe {
    has label: str = "";
    has is_dead_end: bool = False;
}

walker Tracer {
    has route: list[str] = [];
    has dead_ends: list[str] = [];
    has dead_end_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter_valve with Valve entry {
        self.route.append(here.label);
        visit [-->] else {
            disengage;
        }
    }

    can walk_pipe with Pipe entry {
        self.route.append(here.label);
        if here.is_dead_end {
            self.dead_ends.append(here.label);
            self.dead_end_count += 1;
            visit [<--] else {
                disengage;
            }
        } else {
            visit [-->] else {
                disengage;
            }
        }
    }

    can summarize with Root exit {
        print(f"Full route: {' -> '.join(self.route)}");
        print(f"Dead ends hit: {self.dead_end_count}");
        for stub in self.dead_ends {
            print(f"  [STUB] {stub}");
        }
    }
}

with entry {
    intake = Valve(label="Intake-A");
    pipe1 = Pipe(label="Main-1");
    pipe2 = Pipe(label="Branch-2");
    pipe3 = Pipe(label="Junction-3");
    stub = Pipe(label="Cap-X", is_dead_end=True);
    pipe4 = Pipe(label="Run-4");
    stub2 = Pipe(label="Cap-Y", is_dead_end=True);

    intake ++> pipe1 ++> pipe2 ++> pipe3 ++> stub;
    pipe3 ++> pipe4 ++> stub2;

    root spawn Tracer();
}

"""Bug tracker: connect-and-grab a ticket node from the project root.

Demonstrates the grouped connection form (``root ++> (t := Ticket(...));``)
which returns the freshly created node, so we can read its fields right
away instead of running a separate lookup query. A FilingClerk walker
spawned on the root walks the ticket tree and prints every filed ticket.
