"""UX case receipt v2: derive pass/fail from load-bearing checks; block bogus finish_pass."""

node UxCase {
    has case_id: str = "";
    has target_name: str = "";
    has full_test_name: str = "";
}

node LoadBearingCheck {
    has name: str = "";
    has passed: bool = True;
    has load_bearing: bool = True;
}

node UxCaseReceipt {
    has schema_version: str = "ux_case_receipt.v2";
    has case_id: str = "";
    has result: str = "pending";
    has assertions_failed: int = 0;
    has finalized: bool = False;
    has valid: bool = False;
    has failure_kind: str = "";
    has caller_requested_pass: bool = False;
}

node ExecutionPlan {
    has plan_digest: str = "";
    has tier: str = "";
    has feature_profile: str = "";
}

edge UnderPlan { }
edge RecordedCheck { has order: int = 0; }
edge ReceiptFor { }

walker ReceiptFinalizer {
    has failed_count: int = 0;
    has check_count: int = 0;
    has bound_case_id: str = "";

    can start with UxCase entry {
        self.bound_case_id = here.case_id;
        self.failed_count = 0;
        self.check_count = 0;
        visit [->:RecordedCheck:->] else { disengage; };
    }

    can tally with LoadBearingCheck entry {
        self.check_count += 1;
        if here.load_bearing and not here.passed {
            self.failed_count += 1;
        }
    }

    can route_to_receipt with UxCase exit {
        visit [->:ReceiptFor:->] else { disengage; };
    }

    can seal with UxCaseReceipt entry {
        here.assertions_failed = self.failed_count;
        identity_ok = here.case_id == self.bound_case_id;
        if not identity_ok {
            here.result = "receipt_instrument_failure";
            here.failure_kind = "case_id_mismatch";
            here.valid = False;
            print(f"[REJECT] receipt case_id={here.case_id} != bound {self.bound_case_id}");
        } elif here.caller_requested_pass and self.failed_count > 0 {
            here.result = "assertion_mismatch";
            here.failure_kind = "pass_invariant_violation";
            here.valid = False;
            print(f"[REJECT] {here.case_id}: finish_pass() blocked — "
                  f"{self.failed_count} load-bearing check(s) failed");
        } elif self.failed_count > 0 {
            here.result = "assertion_mismatch";
            here.failure_kind = "assertion_mismatch";
            here.valid = False;
            print(f"[FAIL] {here.case_id}: {self.failed_count} assertion(s) failed");
        } else {
            here.result = "assertions_passed";
            here.failure_kind = "";
            here.valid = True;
            print(f"[PASS] {here.case_id}: all {self.check_count} checks passed");
        }
        here.finalized = True;
        disengage;
    }
}

with entry {
    plan = ExecutionPlan(
        plan_digest="2da40e51",
        tier="gate",
        feature_profile="ux-v2"
    );
    root ++> plan;

    case_pass = UxCase(
        case_id="case-001",
        target_name="perl_lsp_ux",
        full_test_name="ux::hover_exact"
    );
    plan +>:UnderPlan:+> case_pass;
    case_pass +>:RecordedCheck(order=1):+> LoadBearingCheck(name="rpc_ready", passed=True);
    case_pass +>:RecordedCheck(order=2):+> LoadBearingCheck(name="hover_text", passed=True);
    receipt_pass = UxCaseReceipt(case_id="case-001");
    case_pass +>:ReceiptFor:+> receipt_pass;

    case_fail = UxCase(
        case_id="case-002",
        target_name="perl_lsp_ux",
        full_test_name="ux::completion_exact"
    );
    plan +>:UnderPlan:+> case_fail;
    case_fail +>:RecordedCheck(order=1):+> LoadBearingCheck(name="rpc_ready", passed=True);
    case_fail +>:RecordedCheck(order=2):+>
        LoadBearingCheck(name="completion_items", passed=False);
    receipt_fail = UxCaseReceipt(case_id="case-002", caller_requested_pass=True);
    case_fail +>:ReceiptFor:+> receipt_fail;

    case_pass spawn ReceiptFinalizer();
    case_fail spawn ReceiptFinalizer();
}
