"""Recursive lineage walker over parent DAG, lifted to typed edges.

Models the Flock SYNTHESIZE scenario: findings form a parent DAG, and a
synthesis must recursively walk its ancestors up to a depth cap, then
produce a new synthesis node annotated with depth metadata. The walker
replaces hand-rolled CTE-style recursion with an explicit depth-bounded
traversal over a typed ``ParentOf`` edge, carrying its own visited set so
cyclic graphs cannot loop forever.
"""

node Finding {
    has title: str = "";
    has cluster_id: int = 0;
    has synthesis_depth: int = 0;
}

node Synthesis {
    has title: str = "";
    has cluster_id: int = 0;
    has synthesis_depth: int = 0;
}

edge ParentOf {
    has role: str = "source";
}

walker LineageWalker {
    has max_depth: int = 10;
    has lineage_titles: list[str] = [];
    has visited_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Synthesis | Finding entry {
        if id(here) not in self.visited_ids and len(self.visited_ids) <= self.max_depth {
            self.visited_ids = self.visited_ids + [id(here)];
            tag = "synthesis" if isinstance(here, Synthesis) else "finding";
            label = f"{here.title} ({tag}, d={here.synthesis_depth}, cluster {here.cluster_id})";
            self.lineage_titles = self.lineage_titles + [label];
            visit [->:ParentOf:->];
        }
    }
}

walker RecursiveSynthesizer {
    has max_depth: int = 10;
    has new_title: str = "";
    has seen: list[int] = [];
    has combined_clusters: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with Synthesis | Finding entry {
        if len(self.seen) <= self.max_depth and id(here) not in self.seen {
            self.seen = self.seen + [id(here)];
            self.combined_clusters = self.combined_clusters + [here.cluster_id];
            visit [->:ParentOf:->];
        }
    }

    can finalize with Root entry {
        new_depth = 2;
        created = Synthesis(title=self.new_title, cluster_id=99, synthesis_depth=new_depth);
        root ++> created;
        priority_score = new_depth * 10;
        print(f"Produced second-order synthesis: {created.title}");
        print(f"  walked {len(self.seen)} ancestors across clusters {self.combined_clusters}");
        print(f"  synthesis_depth={created.synthesis_depth}, priority_boost={priority_score}");
    }
}

with entry {
    f_root = Finding(title="root-cause observation", cluster_id=7);
    f_a = Finding(title="corroborating data point", cluster_id=7);
    f_b = Finding(title="cross-cluster evidence", cluster_id=12);
    f_c = Finding(title="anomalous reading", cluster_id=12);

    s1 = Synthesis(title="S1 (round-1 synthesis)", cluster_id=7, synthesis_depth=1);

    s1 +>:ParentOf:+> f_root;
    f_root +>:ParentOf:+> f_a;
    f_b +>:ParentOf:+> f_c;

    root ++> f_b;

    print("--- LineageWalker spawned on S1 (depth-capped recursive ancestry) ---");
    walker1 = LineageWalker(max_depth=10);
    s1 spawn walker1;
    print("Ancestry titles in walk order:");
    for title in walker1.lineage_titles {
        print(f"  - {title}");
    }

    print("");
    print("--- RecursiveSynthesizer: produce S2 combining cluster 7 + cluster 12 ---");
    synth = RecursiveSynthesizer(max_depth=10, new_title="S2 (cross-cluster meta-synthesis)");
    s1 spawn synth;
    synth spawn root;
}

