```jac
"""Tauri rewrite impact analysis: model the dependency cascade from a
complete Electron -> Tauri migration. Walkers simulate the recursion the
issue describes (parent->child module impact, cascade invalidation of
dependencies, and cycle detection among modules) using typed edges and
walker traversal instead of hand-rolled adjacency machinery."""

node Module {
    has name: str = "";
    has status: str = "pending";   # pending | migrated | dropped | deferred
    has depth: int = 0;
}

# Typed edge: a module DependsOn another module (carries relationship meaning).
edge DependsOn {
    has weight: int = 1;           # how critical the dependency is
}

# Typed edge: OwnedBy marks a module as belonging to a runtime layer.
edge OwnedBy {
    has layer: str = "";           # "electron" | "tauri" | "renderer" | "infra"
}

node Milestone {
    has label: str = "";
    has order: int = 0;
}

walker ImpactAnalyzer {
    # Carries the explicit visited set: walkers in jac 0.36.1 have NO
    # built-in once-per-node visitation, so cycle policy is domain logic
    # that must survive the lift to idiomatic form.
    has visited: list[str] = [];
    has impact_order: list[str] = [];
    has pending: list = [];

    can start with Root entry {
        # Begin by hopping to the first Milestone via typed edge.
        visit [->:OwnedBy:->];
    }

    can analyze with Milestone entry {
        print(f"=== Milestone {here.order}: {here.label} ===");
        # From a milestone, fan out to the modules OwnedBy this milestone.
        visit [->:OwnedBy:->];
    }

    can collect with Module entry {
        # Recursive dependency walk with explicit cycle guard. The guard
        # is the hand-rolled machinery the issue complains about; in the
        # idiomatic form we keep the guard but express traversal as visit.
        name = here.name;
        if name in self.visited {
            print(f"[cycle] revisiting {name} - skipping");
            disengage;
        }
        self.visited.append(name);
        self.impact_order.append(name);
        print(f"  impact -> {name} (status={here.status})");
        # Visit dependents via typed DependsOn edges. Front-end fallback
        # handles dead-ends (leaf modules with no further dependencies).
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker CascadeDropper {
    # Walks a module's dependency subtree and "invalidates" everything that
    # was dropped from the Electron rewrite, simulating the cascade-delete
    # behavior the maintainer had to hand-roll before.
    has invalidated: list[str] = [];
    has stack: list = [];

    can start with Root entry {
        visit [->:OwnedBy:->];
    }

    can descend with Milestone entry {
        visit [->:OwnedBy:->];
    }

    can drop with Module entry {
        name = here.name;
        status = here.status;
        if status == "dropped" {
            print(f"[drop] {name} -> invalidating dependents");
        } elif status == "migrated" {
            print(f"[ok]   {name} migrated cleanly");
        } else {
            print(f"[skip] {name} status={status}");
        }
        self.invalidated.append(name);
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker CycleHunter {
    # Dependency-graph cycle detector. Emits a cycle report and stops.
    has path: list[str] = [];
    has cycles: list[list[str]] = [];

    can start with Root entry {
        visit [->:OwnedBy:->];
    }

    can trace with Milestone entry {
        visit [->:OwnedBy:->];
    }

    can probe with Module entry {
        name = here.name;
        if name in self.path {
            # Found a cycle: slice the path back to the repeated node.
            start = self.path.index(name);
            cycle = self.path[start:] + [name];
            self.cycles.append(cycle);
            print(f"[cycle] {' -> '.join(cycle)}");
            disengage;
        }
        self.path.append(name);
        visit [->:DependsOn:->] else {
            # Leaf: pop self from path before disengaging.
            self.path.pop();
            disengage;
        }
    }
}

with entry {
    # ----- Layer 1: milestones (the migration cutover targets) -----
    mvp = Milestone(label="MVP macOS cutover", order=1);
    parity = Milestone(label="Linux/Windows parity", order=2);
    polish = Milestone(label="Updater & mobile polish", order=3);

    # ----- Layer 2: modules, each OwnedBy a milestone -----
    tauri_backend = Module(name="tauri-backend", status="migrated", depth=0);
    pty_runtime = Module(name="pty-runtime", status="migrated", depth=1);
    ssh_core = Module(name="ssh-core", status="migrated", depth=1);
    git_service = Module(name="git-service", status="migrated", depth=2);

    browser_pane = Module(name="browser-pane", status="dropped", depth=0);
    design_mode = Module(name="design-mode", status="dropped", depth=1);
    analytics = Module(name="analytics", status="dropped", depth=1);

    automations = Module(name="automations", status="deferred", depth=1);
    pdf_preview = Module(name="pdf-preview", status="deferred", depth=1);

    # ----- Wire the ownership graph (Milestone -OwnedBy-> Module) -----
    mvp +>:OwnedBy(layer="tauri"):+> tauri_backend;
    mvp +>:OwnedBy(layer="tauri"):+> pty_runtime;
    mvp +>:OwnedBy(layer="tauri"):+> ssh_core;
    mvp +>:OwnedBy(layer="tauri"):+> git_service;

    mvp +>:OwnedBy(layer="electron"):+> browser_pane;
    mvp +>:OwnedBy(layer="electron"):+> design_mode;
    mvp +>:OwnedBy(layer="electron"):+> analytics;

    parity +>:OwnedBy(layer="tauri"):+> automations;
    parity +>:OwnedBy(layer="tauri"):+> pdf_preview;

    # ----- Wire the dependency graph (Module -DependsOn-> Module) -----
    # Including one intentional cycle (browser-pane <-> design-mode) so
    # the CycleHunter has something to report.
    tauri_backend +>:DependsOn(weight=3):+> pty_runtime;
    pty_runtime +>:DependsOn(weight=2):+> ssh_core;
    ssh_core +>:DependsOn(weight=1):+> git_service;
    git_service +>:DependsOn(weight=1):+> ssh_core;       # cycle seed

    browser_pane +>:DependsOn(weight=3):+> design_mode;
    design_mode +>:DependsOn(weight=3):+> browser_pane;   # cycle

    automations +>:DependsOn(weight=1):+> tauri_backend;
    pdf_preview +>:DependsOn(weight=1):+> tauri_backend;

    # ----- Attach the whole graph to root -----
    root ++> mvp ++> parity ++> polish;

    # ----- Demo 1: dependency-ordered impact analysis -----
    print(">>> ImpactAnalyzer (recursive walk with cycle guard)");
    root spawn ImpactAnalyzer();
    print("");

    # ----- Demo 2: cascade-dropper for the dropped Electron modules -----
    print(">>> CascadeDropper (invalidates dropped-module subtree)");
    root spawn CascadeDropper();
    print("");

    # ----- Demo 3: cycle detection across the dependency graph -----
    print(">>> CycleHunter (finds dependency cycles)");
    root spawn CycleHunter();
}
