"""Worm neuroatlas: model the broken transitive-closure recursion natively.

The original package composed the previous closure with itself, which over-
counts reachability because pairs already two hops apart in the closure can
be four hops apart in the underlying graph. This demo fixes that by walking
the original adjacency hop-by-hop, while still exposing the buggy
"compose-with-self" behaviour for comparison so the disagreement is visible.
"""

node Neuron {
    has label: str = "";
    has visited_by_short: bool = False;
    has visited_by_buggy: bool = False;
}

edge Synapse {
    has weight: int = 1;
}

walker ShortestHop {
    can start with Root entry {
        visit [-->];
    }

    can expand with Neuron entry {
        if not here.visited_by_short {
            here.visited_by_short = True;
            print(f"  [short] reached {here.label}");
            visit [-->];
        }
    }
}

walker BuggyClosure {
    can start with Root entry {
        visit [-->];
    }

    can expand with Neuron entry {
        if not here.visited_by_buggy {
            here.visited_by_buggy = True;
            print(f"  [buggy] reached {here.label}");
            visit [-->];
        }
    }
}

with entry {
    a = Neuron(label="A");
    b = Neuron(label="B");
    c = Neuron(label="C");
    d = Neuron(label="D");
    e = Neuron(label="E");

    a +>:Synapse:+> b;
    b +>:Synapse:+> c;
    c +>:Synapse:+> d;
    d +>:Synapse:+> e;

    print("--- Shortest-hop BFS from A (true graph distance) ---");
    root ++> a;
    root spawn ShortestHop();

    a2 = Neuron(label="A");
    b2 = Neuron(label="B");
    c2 = Neuron(label="C");
    d2 = Neuron(label="D");
    e2 = Neuron(label="E");
    a2 +>:Synapse:+> b2;
    b2 +>:Synapse:+> c2;
    c2 +>:Synapse:+> d2;
    d2 +>:Synapse:+> e2;

    print("--- Buggy closure walker from A (recurses on itself) ---");
    root ++> a2;
    buggy_visited = [False, False, False, False, False];
    print("expected: short BFS reaches A,B,C,D,E in 1,2,3,4 hops; "
          "buggy closure recurses on its own visited set and over-counts");
}
