"""PWA shell: model the responsive app frame, its navigation routes, and the
capture/accessibility subsystems as a graph and walk it to verify that every
top-level route is reachable, capture degrades when the microphone is missing,
and the offline shell can serve its content without the network."""

node Section {
    has title: str = "";
    has width_min: int = 320;
    has installed: bool = False;
}

node Route {
    has title: str = "";
    has priority: int = 0;
    has persistent: bool = False;
}

node CaptureSurface {
    has kind: str = "";
    has mic_supported: bool = True;
    has pwa_supported: bool = True;
}

node AuthSurface {
    has kind: str = "";
}

node ShellState {
    has online: bool = True;
    has stale: bool = False;
    has has_error: bool = False;
    has reduced_motion: bool = False;
    has contrast_ok: bool = True;
    has target_px: int = 44;
}

edge NavLink { has order: int = 0; }
edge Contains { }
edge CapturesVia { }
edge Authenticates { }
edge Renders { }

walker ShellAuditor {
    can start with Root entry {
        print("[shell] auditing responsive PWA shell");
        visit [-->];
    }

    can scan_shell with Section entry {
        print(f"[section] {here.title} (min-width={here.width_min}px, "
              f"installed={here.installed})");
        visit [-->];
    }

    can audit_route with Route entry {
        marker = "persistent" if here.persistent else "route";
        print(f"[route:{marker}] {here.title} (priority={here.priority})");
        visit [-->];
    }

    can inspect_capture with CaptureSurface entry {
        degraded = (not here.mic_supported) or (not here.pwa_supported);
        mode = "typed-only" if degraded else "voice+pwa";
        print(f"[capture] {here.kind} -> {mode} (mic={here.mic_supported}, "
              f"pwa={here.pwa_supported})");
        visit [-->];
    }

    can check_auth with AuthSurface entry {
        print(f"[auth] {here.kind}");
        visit [-->];
    }

    can report_shell with ShellState entry {
        ok_targets = here.target_px >= 44;
        ok_contrast = here.contrast_ok;
        offline_ok = (not here.online) and (not here.has_error);
        print(f"[state] online={here.online} stale={here.stale} "
