"""Precondition contracts — model the scenario where a "board is set"
fact doesn't cross a method-return boundary (F1/F3 of issue #53).

We model columns that require a `board` precondition before they can be
`save`d. A factory `Column.build` returns a column whose board is
already set; a `setup!` postcondition establishes the same fact. A
walker audits columns reachable from `root` and reports which ones
satisfy their `save` precondition — exactly the class of false-positive
the issue tracks.
"""

node Column {
    has title: str = "";
    has board: str = "";          # "" means unset (modeling nil)
    has set_by_factory: bool = False;
    has set_by_setup: bool = False;
}

node Board {
    has name: str = "";
}

edge Holds {
    has label: str = "";
}

walker Auditor {
    has satisfied: int = 0;
    has unsatisfied: int = 0;

    can start with Root entry {
        visit [->:Holds:->];
    }

    can audit with Column entry {
        ok = here.board != "";
        verdict = "OK" if ok else "MISSING board precondition";
        print(f"Column {here.title!r}: {verdict}");
        if ok {
            self.satisfied += 1;
        } else {
            self.unsatisfied += 1;
        }
        visit [->:Holds:->];
    }
}

# Factory boundary: returns a column whose board is established inside
# the factory — the postcondition that F3 says the inferrer cannot see.
walker BuildFactory {
    can produce with Root entry {
        b = Board(name="Factory-Board");
        c = Column(title="factory-built", board=b.name, set_by_factory=True);
        root +>:Holds(label="produces"):+> c;
        root +>:Holds(label="depends-on"):+> b;
        visit [->:Holds:->];
    }
}

# Setup postcondition: a method call that the inferrer can't follow
# (F3). We model it explicitly with a typed edge from setup! to the
# column it validates.
walker SetupPostcondition {
    can validate with Root entry {
        c = Column(title="setup-validated", set_by_setup=True);
        c.board = "Setup-Board";
        root +>:Holds(label="validates"):+> c;
        b = Board(name="Setup-Board");
        root +>:Holds(label="depends-on"):+> b;
        visit [->:Holds:->];
    }
}

# Raw column with no factory, no setup — the control case where the
# precondition truly is missing and the auditor must report it.
walker RawColumn {
    can introduce with Root entry {
        c = Column(title="raw", board="");
        root +>:Holds(label="introduces"):+> c;
        visit [->:Holds:->];
    }
}

with entry {
    # Build three columns via different paths so the auditor sees the
    # full mix the issue tracks: factory-set, setup-set, and unset.
    BuildFactory() spawn root;
    SetupPostcondition() spawn root;
    RawColumn() spawn root;

    a = Auditor();
    root spawn a;

    print(f"audit summary: {a.satisfied} satisfied, "
          f"{a.unsatisfied} unsatisfied preconditions");
}
