"""Control-plane task supersession with dependency recovery and cycle detection."""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has repository: str = "";
    has product: str = "";
    has logical_key: str = "";
    has state: str = "active";
    has worker_eligible: bool = True;
    has completion: bool = False;
}

node ControlPlane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mode: str = "";
}

edge Contains { }

edge BlockedBy {
    has reason: str = "";
}

edge Supersedes {
    has contract_version: int = 1;
    has validated: bool = False;
}

walker DependencyResolver {
    has seen_ids: list[str] = [];
    has expected_repository: str = "";
    has expected_product: str = "";
    has expected_logical_key: str = "";

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter with ControlPlane entry {
        if here.mode == "recovery" {
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can resolve with Task entry {
        if here.task_id in self.seen_ids {
            print(f"cycle or repeated task detected at {here.task_id}");
            disengage;
        }

        self.seen_ids.append(here.task_id);

        if here.state == "abandoned" {
            print(f"preserving historical worker identity for {here.task_id}");
            self.expected_repository = here.repository;
            self.expected_product = here.product;
            self.expected_logical_key = here.logical_key;
            visit [->:Supersedes:->] else {
                disengage;
            }
        } elif here.state == "active" {
            print(f"checking blocked dependency from {here.task_id}");
            visit [->:BlockedBy:->] else {
                disengage;
            }
        } elif here.state == "completed" {
            if here.repository == self.expected_repository
                and here.product == self.expected_product
                and here.logical_key == self.expected_logical_key
                and here.completion {
                print(f"logical task {here.logical_key} is satisfied by {here.task_id}");
            } else {
                print(f"invalid successor scope for {here.task_id}");
            }
            disengage;
        }
    }
}

walker ContractAuditor {
    has seen_ids: list[str] = [];

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_plane with ControlPlane entry {
        if here.mode == "cycle" {
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_task with Task entry {
        if here.task_id in self.seen_ids {
            print(f"governance error: cyclic supersession at {here.task_id}");
            disengage;
        }

        self.seen_ids.append(here.task_id);
        visit [->:Supersedes:->] else {
            disengage;
        }
    }
}

with entry {
    recovery_plane = ControlPlane(
        title="Recovery contracts",
        mode="recovery"
    );
    cycle_plane = ControlPlane(
        title="Invalid cycle fixture",
        mode="cycle"
    );

    dependent = Task(
        title="Downstream task",
        task_id="#6",
        repository="Leion-wp/micro-saas-boilerplate",
        product="micro-saas-boilerplate",
        logical_key="managed-recovery",
        state="active",
        worker_eligible=True
    );

    abandoned = Task(
