"""Policy cache & async audit path demo.

Models the H6-IMPL-CACHING-ASYNC concern:
- Policies (nodes) produce Assessments (nodes) via a typed edge.
- A Policy change MUST invalidate every Assessment in its subtree.
- Evidence writes go to an async audit queue; the walker reports
  durable totals at the end.
- A ReAnalyze walker proves INV-7: re-analysis is NEVER served from
  the assessment cache. It is forced to bypass by clearing the cache
  for the target node before producing a fresh assessment.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Policy {
    has name: str = "";
    has version: int = 1;
}

node Subject {
    has label: str = "";
}

node Assessment {
    has score: float = 0.0;
    has cached: bool = False;
}

node EvidenceRecord {
    has note: str = "";
    has durable: bool = False;
}

# ---------------------------------------------------------------------------
# Edge archetypes (relationships carry meaning -> typed)
# ---------------------------------------------------------------------------

edge Governs { }
edge AssessedBy { }
edge AuditedBy { }

# ---------------------------------------------------------------------------
# Walker: invalidator
# ---------------------------------------------------------------------------

# Walks every Assessment transitively under a Policy via Governs->Subject
# ->AssessedBy, marks each one stale, and reports how many were
# invalidated. This is the hand-rolled cascade invalidation the issue
# asks us to make native.
walker Invalidator {
    has invalidated_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can find_policy with Policy entry {
        print(f"[Invalidator] policy changed: {here.name} v{here.version}");
        visit [->:Governs:->];
    }

    can cascade with Subject entry {
        visit [->:AssessedBy:->];
    }

    can stamp with Assessment entry {
        here.cached = False;
        self.invalidated_count += 1;
        print(f"  - invalidated {here}");
    }
}

# ---------------------------------------------------------------------------
# Walker: async audit writer
# ---------------------------------------------------------------------------

# Replaces the manual queue/stack loop the maintainer used to batch
# evidence writes. Each evidence node is visited exactly once and
# marked durable; the walker reports totals at the end.
walker AsyncAuditor {
    has durable_count: int = 0;
    has pending_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can collect with Subject entry {
        visit [->:AuditedBy:->];
    }

    can persist with EvidenceRecord entry {
        if here.durable {
            self.durable_count += 1;
        } else {
            here.durable = True;
            self.pending_count += 1;
            self.durable_count += 1;
            print(f"  - flushed async evidence: {here.note}");
        }
    }
}

# ---------------------------------------------------------------------------
# Walker: re-analysis (INV-7 guard)
# ---------------------------------------------------------------------------

# The contract: re-analysis MUST NOT be served from the assessment cache.
# The walker first clears any cached assessment for the target subject,
# then forces a fresh one. We assert cached=False both before and after.
walker ReAnalyze {
    has subject_label: str = "";
    has fresh_score: float = 0.0;

    can start with Root entry {
        for s in [-->][?:Subject] {
            if s.label == self.subject_label {
                visit s;
                return;
            }
        }
        print(f"[ReAnalyze] no subject named {self.subject_label}");
        disengage;
    }

    can bypass with Subject entry {
        prior = [->:AssessedBy:->];
        for old in prior {
            old.cached = False;
            print(f"  - cache bypass: dropped cached assessment");
        }
        fresh = Assessment(score=self.fresh_score, cached=False);
        here +>:AssessedBy:+> fresh;
        print(f"[ReAnalyze] fresh score for {here.label}: {fresh.score}");
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # --- build the small graph ------------------------------------------------
    p = Policy(name="trust-policy", version=1);
    root ++> p;

    s1 = Subject(label="alpha");
    s2 = Subject(label="beta");
    p +>:Governs:+> s1;
    p +>:Governs:+> s2;

    a1 = Assessment(score=0.42, cached=True);
    a2 = Assessment(score=0.77, cached=True);
    a3 = Assessment(score=0.10, cached=True);
    s1 +>:AssessedBy:+> a1;
    s1 +>:AssessedBy:+> a2;
    s2 +>:AssessedBy:+> a3;

    ev1 = EvidenceRecord(note="alpha: source=A");
    ev2 = EvidenceRecord(note="alpha: source=B");
    s1 +>:AuditedBy:+> ev1;
    s1 +>:AuditedBy:+> ev2;

    # --- 1. policy change invalidates cache -----------------------------------
    p.version = 2;
    root spawn Invalidator();

    # --- 2. async evidence flush ----------------------------------------------
    root spawn AsyncAuditor();

    # --- 3. INV-7 proof: re-analysis bypasses the cache -----------------------
    # After invalidation a1/a2/a3 are cached=False; we still prove that even
    # if a cache entry existed, re-analysis would bypass it.
    a1.cached = True;
    print(f"before re-analyze a1.cached = {a1.cached}");
    ReAnalyze(subject_label="alpha", fresh_score=0.99) spawn root;
    print(f"after  re-analyze a1.cached = {a1.cached}");
}
