"""Roadmap demo: memory layer traversal with native walkers.

Models the issue's scenario — a maintainer walks a versioned roadmap graph
where milestones (Completed/Open/Future) connect to features via typed
edges (DependsOn, Blocks, MigratesTo). A walker performs cascade
invalidation: when a feature is marked deprecated, dependent and blocking
features downstream are recursively invalidated through typed edges, with
an explicit cycle guard (no built-in dedupe in jac 0.36.1).
"""

node Feature {
    has title: str = "";
    has version: str = "";
    has status: str = "open";
    has deprecated: bool = False;
    has notes: str = "";
}

edge DependsOn {
    has strength: str = "hard";
}

edge Blocks {
    has reason: str = "";
}

edge MigratesTo {
    has threshold: str = "";
}

walker RoadmapAuditor {
    has deprecation_target: str = "Neo4j Backend";
    has guard: list[str] = [];
    has invalidations: list[str] = [];

    can start with Root entry {
        print(f"Auditor targeting deprecation: {self.deprecation_target}");
        visit [-->];
    }

    can fan_out with Feature entry {
        # Cycle guard: explicit (jac walkers do not dedupe by default).
        if here.title in self.guard {
            print(f"  cycle skip: {here.title}");
            visit [-->] else { disengage; }
            return;
        }
        self.guard.append(here.title);

        # Check if THIS feature is the deprecation target.
        if here.title == self.deprecation_target and not here.deprecated {
            here.deprecated = True;
            print(f"DEPRECATED: {here.title} ({here.version}) — {here.notes}");
        } else {
            print(f"[{here.status.upper():>9}] {here.version:>8}  {here.title}");
        }

        # Cascade: walk downstream dependents + blockers + migrations.
        visit [->:DependsOn:->];
        visit [->:Blocks:->];
        visit [->:MigratesTo:->];
    }
}

walker DependencySweeper {
    has seen: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        print("\nDependency order (Features only, typed-edge traversal):");
        visit [-->];
    }

    can rank with Feature entry {
        if here.title in self.seen {
            visit [-->] else { disengage; }
            return;
        }
        self.seen.append(here.title);
        self.order.append(here.title);
        visit [->:DependsOn:->];
        visit [->:Blocks:->];
        visit [->:MigratesTo:->];
    }

    can finalize with Root exit {
        for (i, name) in enumerate(self.order) {
            print(f"  {i + 1}. {name}");
        }
    }
}

with entry {
    # ---- Build the roadmap graph ------------------------------------------
    cost_routing = Feature(
        title="Cost-Aware Routing",
        version="v0.8.0",
        status="completed",
        notes="tier-based embedding provider selection",
    );
    kg_layer = Feature(
        title="Knowledge Graph Layer",
        version="v0.7.0",
        status="completed",
        notes="entity extraction, typed relationships, graph traversal",
    );
    session_pipe = Feature(
        title="Session->Memory Pipeline",
        version="v0.6.0",
        status="completed",
        notes="native fact extraction in on_session_end",
    );
    supersession = Feature(
        title="Auto-Supersession",
        version="v0.5.1",
        status="completed",
        notes="similarity > 0.90",
    );
    guardrails = Feature(
        title="Active Guardrails",
        version="v0.5.0",
        status="completed",
        notes="memory-driven prevention of destructive actions",
    );
    sica = Feature(
        title="SICA Self-Improvement",
        version="v0.9.0",
        status="open",
        notes="LLM-assisted memory consolidation",
    );
    neo4j = Feature(
        title="Neo4j Backend",
        version="v1.0.0",
        status="future",
        notes="migrate graph layer at ~100K entities",
    );

    # Completed layer — linear historical chain.
    root ++> cost_routing
        ++> kg_layer
        ++> session_pipe
        ++> supersession
        ++> guardrails;

    # Open + Future attached from root.
    root ++> sica;
    root ++> neo4j;

    # Typed relationships — SICA depends on KG Layer; KG Layer blocks Neo4j
    # migration (must wait for deprecation); Neo4j migrates to replace the
    # Qdrant graph layer.
    sica +>:DependsOn(strength="hard"):+> kg_layer;
    sica +>:DependsOn(strength="hard"):+> guardrails;
    kg_layer +>:Blocks(reason="Qdrant under threshold"):+> neo4j;
    sica +>:Blocks(reason="uses current graph API"):+> neo4j;
    neo4j +>:MigratesTo(threshold="100K entities"):+> kg_layer;

    # ---- Demo 1: cascade invalidation ------------------------------------
    print("=== Cascade Invalidation Demo ===");
    auditor = RoadmapAuditor(deprecation_target="Neo4j Backend");
    root spawn auditor;
    print(f"\nInvalidations recorded: {auditor.invalidations}");
    print(f"Neo4j deprecated? {neo4j.deprecated}");

    # ---- Demo 2: dependency ordering via typed-edge walker ---------------
    sweeper = DependencySweeper();
    root spawn sweeper;
}

"""Maze level modeling the difficulty-spike scenario from the arcade issue.

Entities are modeled as nodes (Level, Maze, Cell, Goal) connected by typed
edges that carry the relationships the issue talks about: maze generation,
shortest-path discovery via a walker traversal, and the time-vs-budget
mismatch that becomes pathological at level 6+. A walker performs the
BFS-style reachability walk the maintainer hand-rolled in their analysis.
"""

node Level {
    has number: int = 0;
    has size: int = 0;
    has time_budget: float = 0.0;
    has vision_radius: float = 0.0;

    def shortest_path_estimate() -> float {
        # Approximate shortest-path length for a fully-grown blind maze:
        # grows with size until the cap at level 6, then plateaus.
        cap = 19;
        cells = self.size * self.size;
        return 0.30 * cells + 12.0 if self.size >= cap else 0.55 * cells;
    }

    def pressure() -> str {
        # The maintainer's complaint: at level 6+ the path grows while the
        # budget keeps shrinking. Encode the regime as a label.
        est = self.shortest_path_estimate();
        ratio = est / self.time_budget;
        if ratio > 2.0 {
            return "BRUTAL";
        }
        if ratio > 1.3 {
            return "TIGHT";
        }
        return "FAIR";
    }
}

node Maze {
    has label: str = "";
}

node Cell {
    has row: int = 0;
    has col: int = 0;
    has passable: bool = True;
}

node Goal {
    has label: str = "";
}

edge Generates {
    has seed: int = 0;
}

edge Links {
    has weight: int = 1;
}

edge LeadsTo {
}

walker Pathfinder {
    has visited_count: int = 0;
    has path_length: int = 0;
    has reached_goal: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can pick_level with Level entry {
        print(f"Level {here.number}: {here.size}x{here.size}, "
              f"budget={here.time_budget}s, "
              f"vision={here.vision_radius}, "
              f"est_path={here.shortest_path_estimate():.1f} "
              f"-> {here.pressure()}");
        visit [-->];
    }

    can enter_maze with Maze entry {
        print(f"  exploring maze '{here.label}'");
        visit [->:Generates:->];
    }

    can walk_cells with Cell entry {
        self.visited_count += 1;
        # Continue BFS-style along passable links; guards against cycles.
        if self.visited_count > 200 {
            print("  [guard] bailing: traversal exceeded safety cap");
            disengage;
        }
        visit [->:Links:->];
    }

    can finish with Goal entry {
        self.path_length = self.visited_count;
        self.reached_goal = True;
        print(f"  reached goal '{here.label}' after {self.path_length} cells");
        disengage;
    }
}

with entry {
    # Build three levels that mirror the maintainer's table.
    lvl1 = Level(number=1, size=9, time_budget=42.0, vision_radius=2.60);
    lvl6 = Level(number=6, size=19, time_budget=29.5, vision_radius=2.25);
