"""Observation chain model with traversal, find-by-type, and replacement.

Models the essential scenario from the issue: an observation model is a
chain of wrappers around an inner model. We expose traversal over the
chain, locating components by type, and replacing them in place. The
walker walks the chain via typed `Wraps` edges, accumulating wrappers in
order, and demonstrates sum-over-wrappers (the `_lead_in` use case).
"""

# --- Core entity archetypes ----------------------------------------------

node ErrorModel {
    has name: str = "base";

    def lead_in() -> int {
        return 0;
    }
}

node LatentDelay {
    has name: str = "delay";
    has delay_length: int = 0;

    def lead_in() -> int {
        return self.delay_length - 1;
    }
}

node ObservationModel {
    has label: str = "obs";
}

# --- Relationships -------------------------------------------------------

edge Wraps {
    has slot: str = "model";
}

edge BranchOf {
    has index: int = 0;
}

# --- Walker: traverse the chain ------------------------------------------

walker ChainWalker {
    has chain: list = [];
    has total_lead_in: int = 0;
    has find_type: str = "";

    can begin with Root entry {
        visit [-->];
    }

    can step with ObservationModel | LatentDelay | ErrorModel entry {
        # Record this node in the chain order.
        label = "";
        if isinstance(here, ObservationModel) {
            label = here.label;
        } elif isinstance(here, LatentDelay) {
            label = here.name;
        } else {
            label = here.name;
        }
        self.chain.append(label);

        # Sum lead-in for every LatentDelay encountered.
        if isinstance(here, LatentDelay) {
            self.total_lead_in += here.lead_in();
            if self.find_type == "LatentDelay" {
                print(f"  found LatentDelay: {here.name} (delay={here.delay_length})");
            }
        }
        if isinstance(here, ErrorModel) and self.find_type == "ErrorModel" and here.name != "base" {
            print(f"  found inner ErrorModel: {here.name}");
        }

        # Continue walking along Wraps edges; end the walk at the leaf.
        visit [->:Wraps:->] else {
            disengage;
        };
    }
}

# --- Walker: replace a wrapper by name -----------------------------------

walker Replacer {
    has target_name: str = "";
    has new_delay: int = 0;
    has replaced: bool = False;
    has chain_after: list = [];

    can begin with Root entry {
        visit [-->];
    }

    can step with ObservationModel | LatentDelay | ErrorModel entry {
        label = "";
        if isinstance(here, ObservationModel) {
            label = here.label;
        } elif isinstance(here, LatentDelay) {
            label = here.name;
        } else {
            label = here.name;
        }
        self.chain_after.append(label);

        if isinstance(here, LatentDelay) and here.name == self.target_name and not self.replaced {
            print(f"  swapping {here.name}: delay {here.delay_length} -> {self.new_delay}");
            here.delay_length = self.new_delay;
            self.replaced = True;
        }

        visit [->:Wraps:->] else {
            disengage;
        };
    }
}

# --- Demo ---------------------------------------------------------------

with entry {
    obs = ObservationModel(label="ObsMux");
    delay = LatentDelay(name="primary", delay_length=4);
    inner_err = ErrorModel(name="NegBinom");

    obs +>:Wraps(slot="model"):+> delay;
    delay +>:Wraps(slot="model"):+> inner_err;

    print("=== ChainWalker: traverse and sum lead-in ===");
    w = ChainWalker(find_type="");
    root spawn w;
    print(f"  chain order: {w.chain}");
    print(f"  total lead-in = {w.total_lead_in} (expected 3 = 4-1)");

    print("");
    print("=== ChainWalker: find by type ===");
    f = ChainWalker(find_type="LatentDelay");
    root spawn f;

    print("");
    print("=== Replacer: swap a wrapper by name ===");
    print(f"  before: primary.delay_length = {delay.delay_length}");
    r = Replacer(target_name="primary", new_delay=7);
    root spawn r;
    print(f"  replaced = {r.replaced}");
    print(f"  chain_after = {r.chain_after}");
    print(f"  after: primary.delay_length = {delay.delay_length}");

    verify = ChainWalker();
    root spawn verify;
    print(f"  verified lead-in after swap = {verify.total_lead_in} (expected 6)");
}
