    smallest = 0;
    for (i, row) in enumerate(result.reports) {
        print(f"{row['sku']}: {row['quantity']} units");
        total_units += row['quantity'];
        if i == 0 {
            smallest = row['quantity'];
        } else {
            new_min = row['quantity'] if row['quantity'] < smallest else smallest;
            smallest = new_min;
        }
    }
    print(f"Total units: {total_units}");
    print(f"Smallest shelf count: {smallest}");
}

