"""Dependency-install safety policy and runtime enforcement demo."""

node Workflow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node InstallPolicy {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "osv";
    has threshold_score: int = 7;
    has action: str = "warn";
    has minimum_enforcement: str = "advisory";
    has preferred_enforcement: str = "intercept";
}

node InstallAttempt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has package: str = "";
    has requested_version: str = "";
    has runtime_enforcement: str = "advisory";
}

node Dependency {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has package: str = "";
    has version: str = "";
    has vulnerability_source: str = "";
    has risk_score: int = 0;
    has fixed_version: str = "";
}

edge GovernedBy { }
edge Evaluates { }
edge Requests { }
edge LoopsTo { }

walker DependencySafetyAudit {
    has seen_titles: list[str] = [];
    has decisions: list[str] = [];
    has diagnostics: list[str] = [];
    has action: str = "warn";
    has threshold_score: int = 7;
    has required_enforcement: str = "advisory";
    has preferred_enforcement: str = "intercept";
    has package_name: str = "";
    has requested_version: str = "";

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_workflow with Workflow entry {
        if here.title in self.seen_titles {
            self.diagnostics.append(f"cycle detected at {here.title}");
            skip;
        }
        self.seen_titles.append(here.title);
        print(f"workflow: {here.title}");
        visit [->:GovernedBy:->] else { disengage; }
    }

    can inspect_policy with InstallPolicy entry {
        if here.title in self.seen_titles {
            self.diagnostics.append(f"cycle detected at {here.title}");
            skip;
        }
        self.seen_titles.append(here.title);
        self.action = here.action;
        self.threshold_score = here.threshold_score;
        self.required_enforcement = here.minimum_enforcement;
        self.preferred_enforcement = here.preferred_enforcement;
        print(f"policy source={here.source}, action={self.action}, minimum={self.required_enforcement}");
        visit [->:Evaluates:->] else { disengage; }
    }

    can inspect_attempt with InstallAttempt entry {
        if here.title in self.seen_titles {
            self.diagnostics.append(f"cycle detected at {here.title}");
            skip;
        }
        self.seen_titles.append(here.title);
        self.package_name = here.package;
        self.requested_version = here.requested_version;
        print(f"install request: {self.package_name}@{self.requested_version}");
        if self.required_enforcement == "intercept" {
            if here.runtime_enforcement != "intercept" {
                self.diagnostics.append(f"runtime provides {here.runtime_enforcement}, below required {self.required_enforcement}");
                print(f"diagnostic: requested {self.required_enforcement} exceeds runtime guarantee {here.runtime_enforcement}");
            }
        }
        visit [->:Requests:->] else { disengage; }
    }

    can inspect_dependency with Dependency entry {
        if here.title in self.seen_titles {
            self.diagnostics.append(f"cycle detected at {here.title}");
            skip;
        }
        self.seen_titles.append(here.title);
        risk_label = "known vulnerability" if here.risk_score >= self.threshold_score else "no known vulnerability";
        if here.risk_score >= self.threshold_score {
            if self.action == "block" {
                decision = "BLOCK";
            } else {
                decision = self.action;
            }
            self.decisions.append(f"{decision} {here.package}@{here.version}");
            print(f"{decision}: {here.package}@{here.version} ({risk_label}, source={here.vulnerability_source})");
            if here.fixed_version != "" {
                self.diagnostics.append(f"suggested fixed version {here.fixed_version} needs compatibility validation");
                print(f"suggestion only: try {here.fixed_version} after normal dependency validation");
            }
        } else {
            self.decisions.append(f"ALLOW {here.package}@{here.version}");
            print(f"ALLOW: {here.package}@{here.version}; no known vulnerability is not a safety guarantee");
        }
        visit [->:LoopsTo:->] else { disengage; }
    }

    can summarize with exit {
        print(f"decisions: {self.decisions}");
        print(f"diagnostics: {self.diagnostics}");
    }
}

with entry {
    workflow = Workflow(title="release-agent", year=2025);
    policy = InstallPolicy(
        title="strict-osv-policy",
        year=2025,
        source="osv",
        threshold_score=7,
        action="block",
        minimum_enforcement="intercept",
        preferred_enforcement="intercept"
    );
    attempt = InstallAttempt(
        title="mid-task-npm-install",
        year=2025,
        package="unsafe-helper",
        requested_version="2.3.0",
        runtime_enforcement="advisory"
    );
    dependency = Dependency(
        title="unsafe-helper-2.3.0",
        year=2025,
        package="unsafe-helper",
        version="2.3.0",
        vulnerability_source="osv",
        risk_score=9,
        fixed_version="2.4.1"
    );

    root ++> workflow;
    workflow +>:GovernedBy:+> policy;
    policy +>:Evaluates:+> attempt;
    attempt +>:Requests:+> dependency;
    dependency +>:LoopsTo:+> workflow;

    root spawn DependencySafetyAudit();
}

