"""Bounded explain-filter normalization with typed graph traversal and cycle protection."""

node FilterDocument {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has operator_name: str = "";
    has depth: int = 0;
}

node FilterClause {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has operator_name: str = "";
    has depth: int = 0;
}

edge Contains {
    has position: int = 0;
}

walker Canonicalizer {
    has max_depth: int = 4;
    has seen_titles: list[str] = [];
    has visited_nodes: int = 0;

    can start with Root entry {
        print("normalizing explain filter");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can normalize with FilterDocument | FilterClause entry {
        if here.title in self.seen_titles {
            print(f"cycle detected at {here.title}; stopping safely");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.visited_nodes += 1;
            if here.depth > self.max_depth {
                print(f"depth limit reached at {here.title}; filter left bounded");
                disengage;
            } else {
                kind_label = here.operator_name if here.operator_name != "" else "document";
                state_label = "active" if here.available else "inactive";
                print(f"{kind_label}: {here.title} [{state_label}] depth={here.depth}");
                visit [->:Contains:->] else {
                    disengage;
                }
            }
        }
    }
}

with entry {
    document = FilterDocument(
        title="explain filter",
        operator_name="parsedQuery",
        depth=0
    );
    outer = FilterClause(
        title="outer $and",
        operator_name="$and",
        depth=1
    );
    nested = FilterClause(
        title="nested $and",
        operator_name="$and",
        depth=2
    );
    disjunction = FilterClause(
        title="$or branch",
        operator_name="$or",
        depth=3
    );
    element = FilterClause(
        title="$elemMatch",
        operator_name="$elemMatch",
        depth=4
    );

    root +>:Contains(position=0):+> document;
    document +>:Contains(position=0):+> outer;
    outer +>:Contains(position=0):+> nested;
    nested +>:Contains(position=0):+> disjunction;
    disjunction +>:Contains(position=0):+> element;
    element +>:Contains(position=0):+> outer;

    root spawn Canonicalizer(max_depth=4);
}

