"""Graph-addressed communication with recursive completion and cycle detection."""

node Interaction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has recursion_seen: bool = False;
    has message_seen: bool = False;
    has cycle_hits: int = 0;
}

node Completion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has recursion_seen: bool = False;
    has message_seen: bool = False;
    has cycle_hits: int = 0;
}

node Message {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has message_seen: bool = False;
    has cycle_hits: int = 0;
}

node Layer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has accepted: bool = False;
    has observed: bool = False;
}

edge Starts {
    has channel: str = "";
}

edge ChildCompletion {
    has relation: str = "child";
}

edge Publishes {
    has state: str = "working";
}

edge Sends {
    has kind: str = "";
}

edge Targets {
    has address: str = "completion";
}

walker RecursiveCompletionAudit {
    can start with Root entry {
        print("recursive completion audit started");
        visit [-->] else {
            disengage;
        }
    }

    can follow_interaction with Interaction entry {
        if here.recursion_seen {
            here.cycle_hits += 1;
            print(f"interaction cycle detected: {here.title}");
            disengage;
        } else {
            here.recursion_seen = True;
            print(f"following interaction: {here.title}");
            visit [->:Starts:->] else {
                disengage;
            }
        }
    }

    can follow_completion with Completion entry {
        if here.recursion_seen {
            here.cycle_hits += 1;
            print(f"completion cycle detected: {here.title}");
            disengage;
        } else {
            here.recursion_seen = True;
            print(f"following completion: {here.title}");
            visit [->:ChildCompletion:->] else {
                disengage;
            }
        }
    }
}

walker MessageRelayAudit {
    can start with Root entry {
        print("message relay audit started");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_interaction with Interaction entry {
        print(f"communication source: {here.title}");
        visit [->:Starts:->] else {
            disengage;
        }
    }

    can inspect_completion with Completion entry {
        if here.message_seen {
            here.cycle_hits += 1;
            print(f"message cycle detected at: {here.title}");
            disengage;
        } else {
            here.message_seen = True;
            print(f"checking messages for: {here.title}");
            visit [->:Sends:->] else {
                disengage;
            }
        }
    }

    can inspect_message with Message entry {
        if here.message_seen {
            here.cycle_hits += 1;
            print(f"duplicate message detected: {here.title}");
            disengage;
        } else {
            here.message_seen = True;
            print(f"relaying message: {here.title}");
            visit [->:Targets:->] else {
                disengage;
            }
        }
    }
}

walker PublishedLayerAudit {
    can start with Root entry {
        print("published layer audit started");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_interaction with Interaction entry {
        visit [->:Starts:->] else {
            disengage;
        }
    }

    can inspect_completion with Completion entry {
        visit [->:Publishes:->] else {
            disengage;
        }
    }

    can inspect_layer with Layer entry {
        here.observed = True;
        print(f"observed layer: {here.title}");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    request = Interaction(
        title="Recursive completion request",
        year=2025
    );
    parent = Completion(
        title="Root completion",
        year=2025,
        available=True
    );
    child = Completion(
        title="Child completion",
        year=2025,
        available=False
    );
    result = Layer(
        title="Accepted root layer",
        year=2025,
        available=True,
        accepted=True
    );
    objective = Message(
        title="Child objective",
        year=2025
    );
    correction = Message(
        title="Parent correction",
        year=2025
    );

    root ++> request;
    request +>:Starts(channel="completion"):+> parent;
    parent +>:ChildCompletion(relation="recursive-child"):+> child;
    child +>:ChildCompletion(relation="cycle-back"):+> parent;

    parent +>:Publishes(state="accepted"):+> result;

    parent +>:Sends(kind="objective"):+> objective;
    objective +>:Targets(address="child-completion"):+> child;
    child +>:Sends(kind="correction"):+> correction;
    correction +>:Targets(address="parent-completion"):+> parent;

    root spawn RecursiveCompletionAudit();
    root spawn MessageRelayAudit();
    root spawn PublishedLayerAudit();
}

