"""Plan graph validation with domain-aware dangling dependency errors."""

node Plan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has plan_id: str = "";
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
}

node DependencyReference {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has known: bool = False;
}

edge Contains { }

edge Dependency {
    has relation: str = "";
}

walker PlanValidator {
    has seen_ids: list[str] = [];
    has domain_failures: int = 0;
    has cycle_count: int = 0;
    has first_missing: str = "";

    can start with Root entry {
        print("validating plan graph");
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_plan with Plan entry {
        print(f"plan: {here.title}");
        visit [->:Contains:->] else { disengage; }
    }

    can order_dependencies with Task entry {
        if here.task_id in self.seen_ids {
            self.cycle_count += 1;
            print(f"cycle detected at task {here.task_id}");
        } else {
            self.seen_ids.append(here.task_id);
            print(f"checking task {here.task_id}: {here.title}");
            visit [->:Dependency:->] else { disengage; }
        }
    }

    can validate_reference with DependencyReference entry {
        if here.known {
            print(f"dependency reference resolved: {here.task_id}");
        } else {
            self.domain_failures += 1;
            self.first_missing = here.task_id;
            print(f"TaskNotFoundError: dangling dependency '{here.task_id}'");
        }
    }

    can summarize with Root exit {
        print(f"domain failures: {self.domain_failures}; cycles: {self.cycle_count}");
    }
}

with entry {
