"""Memory entity-linker demo: model how PassiveMemoryInjector resolves entity
mentions across memories using a graph of EntityNodes connected by typed edges,
then walk the graph to expand query terms and boost shared-entity memories.

The original issue hand-rolled adjacency in a registry and walked it manually.
Here relationships are native typed edges and traversal is a walker."""

# --- Node archetypes --------------------------------------------------------

node EntityNode {
    has entity_id: str = "";
    has canonical_name: str = "";
    has aliases: list[str] = [];
}

node MemoryRecord {
    has memory_id: str = "";
    has text: str = "";
    has mentions: list[str] = [];
}

# --- Typed edges (relationships carry meaning) -----------------------------

edge RefersTo {
    has confidence: float = 0.0;
}

edge AliasOf {
    has weight: float = 1.0;
}

# --- Walkers ---------------------------------------------------------------

# Walk from a query surface form to its canonical entity, then expand to
# aliases, so "my manager John" / "he" / "the user" collapse onto one entity.
walker EntityLinker {
    has original_query: str = "";
    has resolved_ids: list[str] = [];
    has expanded_terms: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # A MemoryRecord entry: collect every entity it points at, then continue.
    can index_memory with MemoryRecord entry {
        for eid in here.mentions {
            if eid not in self.resolved_ids {
                self.resolved_ids.append(eid);
            }
        }
        visit [->:RefersTo:->];
    }

    # An EntityNode entry: register its canonical name + every alias edge.
    can expand with EntityNode entry {
        if here.entity_id not in self.resolved_ids {
            self.resolved_ids.append(here.entity_id);
        }
        if here.canonical_name != "" and here.canonical_name not in self.expanded_terms {
            self.expanded_terms.append(here.canonical_name);
        }
        visit [->:AliasOf:->] else {
            disengage;
        }
    }

    # Final report: one structured exit payload summarising the linker run.
    def summarize -> dict {
        return {
            "original_query": self.original_query,
            "resolved_entity_ids": self.resolved_ids,
            "expanded_terms": self.expanded_terms,
        };
    }
}

# Walk every memory reachable from Root, gather the entities each one touches,
# and rank memories by how many of their entities overlap the query's resolved
# set — this is the "boost shared-entity memories" half of the issue.
walker MemoryRanker {
    has query_entity_ids: list[str] = [];
    has ranked: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can score with MemoryRecord entry {
        overlap = 0;
        for eid in here.mentions {
            if eid in self.query_entity_ids {
                overlap += 1;
            }
        }
        self.ranked.append({
            "memory_id": here.memory_id,
            "text": here.text,
            "shared_entities": overlap,
        });
        visit [->:RefersTo:->];
    }

    def summarize -> list {
        return sorted(self.ranked, key=lambda (r: dict) { -r["shared_entities"] });
    }
}

# --- Demo wiring -----------------------------------------------------------

with entry {
    # Three entities that the issue says must collapse onto one another.
    alice = EntityNode(
        entity_id="E-ALICE",
        canonical_name="Alice",
        aliases=["the user", "the researcher", "her", "my manager Alice"],
    );
    john = EntityNode(
        entity_id="E-JOHN",
        canonical_name="John",
        aliases=["my manager John", "he"],
    );
    bob = EntityNode(
        entity_id="E-BOB",
        canonical_name="Bob",
        aliases=["Bob"],
    );

    # Surface-form nodes — what "link_query" sees before resolution.
    surface_alice = EntityNode(entity_id="S-USER", canonical_name="the user");
    surface_john = EntityNode(entity_id="S-MANAGER", canonical_name="my manager John");

    # Memories in the store; some share entities with the query, some don't.
    m1 = MemoryRecord(
        memory_id="M-1",
        text="Alice shipped the LoCoMo fix last Friday.",
        mentions=["E-ALICE"],
    );
    m2 = MemoryRecord(
        memory_id="M-2",
        text="The researcher thanked the team for the +27pts gain.",
        mentions=["E-ALICE"],
    );
    m3 = MemoryRecord(
        memory_id="M-3",
        text="Bob filed the embedding-port PR.",
        mentions=["E-BOB"],
    );
    m4 = MemoryRecord(
        memory_id="M-4",
        text="John reviewed the entity-linker design on Monday.",
        mentions=["E-JOHN"],
    );

    # Wire the graph: Root owns surfaces; surfaces alias to canonical entities;
    # memories refer to canonical entities. Typed edges everywhere.
    root ++> surface_alice ++> surface_john;
    surface_alice +>:AliasOf(weight=1.0):+> alice;
    surface_john +>:AliasOf(weight=1.0):+> john;

    root ++> m1 ++> m2 ++> m3 ++> m4;
    m1 +>:RefersTo(confidence=0.95):+> alice;
    m2 +>:RefersTo(confidence=0.88):+> alice;
    m3 +>:RefersTo(confidence=0.91):+> bob;
    m4 +>:RefersTo(confidence=0.97):+> john;

    # 1) Linker run: query mentions surface forms; walker expands aliases.
    linker = EntityLinker(original_query="What did the user ship last week?");
    root spawn linker;
    linked = linker.summarize();
    print(f"[linker] query={linked['original_query']!r}");
    print(f"[linker] resolved={linked['resolved_entity_ids']}");
    print(f"[linker] expanded_terms={linked['expanded_terms']}");

    # 2) Ranker run: boost memories whose mentions overlap the linked set.
    ranker = MemoryRanker(query_entity_ids=linked["resolved_entity_ids"]);
    root spawn ranker;
    ranked = ranker.summarize();
    print("[ranker] memories by shared-entity score:");
    for row in ranked {
        print(f"  - {row['memory_id']} shared={row['shared_entities']} "
              f"text={row['text']!r}");
    }
}

