    max_r = sweeper.readings[0];
    for r in sweeper.readings {
        lo = r if r < min_r else min_r;
        hi = r if r > max_r else max_r;
        min_r = lo;
        max_r = hi;
    }
    print(f"min: {min_r}C, max: {max_r}C");
}

