"""A native graph model of a write meeting a daemon during startup."""

node WriteRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has operation: str = "write";
    has completed: bool = False;
}

node StateLock {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has held: bool = False;
    has holder: str = "";
}

node Daemon {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has start_time: str = "";
    has migrating: bool = False;
}

node ControlSocket {
    has title: str = "";
    has year: int = 0;
    has available: bool = False;
    has appears_after_ms: int = 0;
    has wait_bound_ms: int = 0;
}

edge NeedsLock { }
edge OwnedBy { }
edge Exposes { }

walker WritePlanner {
    has successful_writes: int = 0;
    has contention_reports: int = 0;

    can begin with Root entry {
        print("planning writes through the graph");
        visit [-->] else { disengage; }
    }

    can inspect_request with WriteRequest entry {
        print(f"write request: {here.operation} ({here.title})");
        visit [->:NeedsLock:->] else { disengage; }
    }

    can inspect_lock with StateLock entry {
        if here.held {
            print(f"lock held by {here.holder}; do not report contention yet");
        } else {
            print("lock is free");
        }
        visit [->:OwnedBy:->] else { disengage; }
    }

    can inspect_daemon with Daemon entry {
        if here.migrating {
            print(f"daemon migration is active (started {here.start_time}); bounded wait is visible");
        } else {
            print("daemon is not migrating");
        }
        visit [->:Exposes:->] else { disengage; }
    }

    can resolve_socket with ControlSocket entry {
        if here.available {
            print(f"socket is ready; {here.title} succeeds");
            self.successful_writes = self.successful_writes + 1;
        } else {
            print(f"socket absent; waiting up to {here.wait_bound_ms} ms");
            if here.appears_after_ms <= here.wait_bound_ms {
                here.available = True;
                print(f"socket appeared after {here.appears_after_ms} ms; write succeeds");
                self.successful_writes = self.successful_writes + 1;
            } else {
                print(f"socket did not appear within {here.wait_bound_ms} ms; contention is genuine");
                self.contention_reports = self.contention_reports + 1;
            }
        }
    }
}

with entry {
    early_request = WriteRequest(title="early-write", operation="create schedule");
    early_lock = StateLock(title="startup-state", held=True, available=False, holder="paceq-daemon");
    early_daemon = Daemon(title="daemon", start_time="09:00:00", migrating=True);
    early_socket = ControlSocket(title="early-write", appears_after_ms=120, wait_bound_ms=500);

    root ++> early_request;
    early_request +>:NeedsLock:+> early_lock;
    early_lock +>:OwnedBy:+> early_daemon;
    early_daemon +>:Exposes:+> early_socket;

    stuck_request = WriteRequest(title="stuck-write", operation="delete schedule");
    stuck_lock = StateLock(title="wedged-state", held=True, available=False, holder="wedged-daemon");
    stuck_daemon = Daemon(title="daemon", start_time="08:42:10", migrating=True);
    stuck_socket = ControlSocket(title="stuck-write", appears_after_ms=2000, wait_bound_ms=500);

    root ++> stuck_request;
    stuck_request +>:NeedsLock:+> stuck_lock;
    stuck_lock +>:OwnedBy:+> stuck_daemon;
    stuck_daemon +>:Exposes:+> stuck_socket;

    root spawn WritePlanner();
}

