"""Warehouse stock take: model shelves as nodes and walk the warehouse with a counter walker."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total: int = 0;
    has smallest: int = 0;
    has seen_first: bool = False;
    has count: int = 0;

    can start with Root entry {
        self.smallest = 0;
        visit [-->] else { disengage; }
    }

    can tally with StockItem entry {
        qty = here.quantity;
        self.total = self.total + qty;
        if self.seen_first {
            if qty < self.smallest {
                self.smallest = qty;
            }
        } else {
            self.smallest = qty;
            self.seen_first = True;
        }
        self.count = self.count + 1;
        print(f"[item {self.count}] sku={here.sku} quantity={qty}");
        visit [-->] else { disengage; }
    }
}

