"""Model the short-digest index lookup defect with native graph traversal."""

node HashAlgorithm {
    has title: str = "";
    has digest_bytes: int = 0;
    has supported: bool = True;
}

node HashIndex {
    has title: str = "";
    has prefix_bytes: int = 8;
    has stored_prefix_hex: str = "";
}

node HashEntry {
    has word: str = "";
    has digest_hex: str = "";
    has stored_prefix_hex: str = "";
}

node LookupQuery {
    has title: str = "";
    has hash_hex: str = "";
    has digest_hex: str = "";
    has hash_chars: int = 0;
    has accepted: bool = True;
    has classification: str = "";
}

edge Builds { }
edge Stores { }
edge Receives { }

walker LookupAuditor {
    can start with Root entry {
        print("Walking the algorithm-to-index lookup graph");
        visit [-->];
    }

    can inspect_algorithm with HashAlgorithm entry {
        print(f"algorithm={here.title}, digest bytes={here.digest_bytes}");
        visit [->:Builds:->];
    }

    can inspect_index with HashIndex entry {
        print(f"index={here.title} stores {here.prefix_bytes}-byte prefixes");
        visit [-->] else { disengage; }
    }

    can inspect_entry with HashEntry entry {
        print(f"builder stored {here.word} as prefix {here.stored_prefix_hex}");
    }

    can inspect_query with LookupQuery entry {
        if here.hash_chars < 16 {
            here.accepted = False;
            here.classification = "Rejected: query is shorter than 16 hex characters";
        } else {
            here.accepted = True;
            if here.hash_hex == here.digest_hex {
                here.classification = "Full";
            } else {
                here.classification = "Partial: padded query cannot equal 4-byte digest";
            }
        }
        print(f"{here.title}: {here.classification}");
    }
}

with entry {
    algorithm = HashAlgorithm(title="crc32", digest_bytes=4);
    index = HashIndex(
        title="crc32.idx",
        prefix_bytes=8,
        stored_prefix_hex="062c021500000000"
    );
    hash_entry = HashEntry(
        word="example",
        digest_hex="062c0215",
        stored_prefix_hex="062c021500000000"
    );
    natural_query = LookupQuery(
        title="natural 4-byte query",
        hash_hex="062c0215",
        digest_hex="062c0215",
        hash_chars=8
    );
    padded_query = LookupQuery(
        title="manual zero-padded query",
        hash_hex="062c021500000000",
        digest_hex="062c0215",
        hash_chars=16
    );

    root ++> algorithm;
    algorithm +>:Builds:+> index;
    index +>:Stores:+> hash_entry;
    index +>:Receives:+> natural_query;
    index +>:Receives:+> padded_query;

    root spawn LookupAuditor();
}

"""A change entry reopens a task and cascades that state to completed ancestors."""

node Task {
