    has action: str = "";
    has note: str = "";
}

edge ParentOf { }
edge AuthoredBy { }
edge Affects { }

walker CascadingReopener {
    has seen_titles: list[str] = [];
    has reopened_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
