"""DGGS hierarchy relations: coverage (sub-zone), lineage, ownership.

Models the three distinct hierarchy readings the issue calls out for
non-congruent Discrete Global Grid Systems. Coverage is a many-to-many
"interior intersects parent" relation (zones straddling boundaries
belong to two or more parents). Lineage is a deterministic id-truncation
ancestor relation, transitive by construction but drifting outside the
geometric ancestor for deep descendants. Ownership assigns each zone to
exactly one super-zone under a documented convention so that aggregation
counts are exact (N^d per parent) and descendant sets partition the
domain. The walker demonstrates that the three relations are distinct
and that aggregation over coverage double-counts straddlers while
ownership does not.
"""

# --- Entity archetypes ------------------------------------------------------

node Zone {
    has zone_id: str = "";
    has depth: int = 0;
    # geometric centre used to test "is descendant inside ancestor region"
    has lat: float = 0.0;
    has lon: float = 0.0;
    # a zone straddles a boundary if its centre sits within a small band
    # around the meridian chosen as the ownership seam; the walker uses
    # this to classify zones as unambiguous (one parent) vs straddlers.
    has straddle_band: float = 0.05;
}

# --- Relation archetypes ----------------------------------------------------

# Coverage: the Standard's sub-zone (term 4.11). A zone at depth d is a
# sub-zone of every parent whose interior it intersects. For boundary-
# straddling zones this is a many-to-many relation.
edge SubZone {
    has intersect_area: float = 0.0;
}

# Lineage: id-truncation ancestry. Transitive, cheap, but deep descendants
# drift outside the geometric ancestor. We model it explicitly so the
# walker can show lineage ≠ coverage for the same pair of zones.
edge LineageOf {
    has via_truncation: bool = True;
}

# Ownership: unique geometric assignment under a documented convention.
# Every zone at relative depth d is the owned sub-zone of exactly one
# zone at the shallower depth. Counts are exact N^d and descendant sets
# partition the domain.
edge OwnedSubZone {
    has convention: str = "centre-in-parent-halfplane";
}

# --- Walker: aggregate counts under each of the three relations -------------

walker HierarchyAuditor {
    has audit_depth: int = 2;
    # accumulators: how many descendants does each relation see, and how
    # many of them straddle the ownership seam (the seam is what makes
    # coverage diverge from ownership).
    has coverage_total: int = 0;
    has lineage_total: int = 0;
    has ownership_total: int = 0;
    has coverage_straddlers: int = 0;
    has ownership_straddlers: int = 0;
    # for the audit roll-up: a zone straddles if its longitude is within
    # straddle_band of 0.0 (the meridian we picked as the ownership seam).
    has seen: list[str] = [];

    can start with Root entry {
        print(f"Hierarchy audit to relative depth {self.audit_depth}");
        visit [-->];
    }

    can audit with Zone entry {
        if here.zone_id in self.seen {
            visit [-->];
            return;
        }
        self.seen.append(here.zone_id);

        # Count descendants under each of the three relations and how
        # many of those descendants straddle the ownership seam.
        c_subs = [->:SubZone:->];
        c_line = [->:LineageOf:->];
        c_owns = [->:OwnedSubZone:->];

        cov_count = 0;
        cov_strad = 0;
        for z in c_subs {
            cov_count += 1;
            if z.lon > -z.straddle_band and z.lon < z.straddle_band {
                cov_strad += 1;
            }
        }
        lin_count = 0;
        for _ in c_line {
            lin_count += 1;
        }
        own_count = 0;
        own_strad = 0;
        for z in c_owns {
            own_count += 1;
            if z.lon > -z.straddle_band and z.lon < z.straddle_band {
                own_strad += 1;
            }
        }

        self.coverage_total += cov_count;
        self.lineage_total += lin_count;
        self.ownership_total += own_count;
        self.coverage_straddlers += cov_strad;
        self.ownership_straddlers += own_strad;

        print(
            f"zone {here.zone_id} d{here.depth} -> "
            f"coverage={cov_count} (straddlers={cov_strad}) | "
            f"lineage={lin_count} | "
            f"ownership={own_count} (straddlers={own_strad})"
        );
        visit [-->];
    }
}

# --- Demo graph -------------------------------------------------------------
# One anchor zone at depth 0, three depth-1 children of which one is an
# unambiguous inboard zone, one is an unambiguous inboard zone, and one
# straddles the meridian so it is a SubZone of TWO parents under coverage
# but OwnedSubZone of exactly ONE parent under ownership.

with entry {
    anchor_a = Zone(zone_id="A0", depth=0, lat=0.0, lon=-0.30);
    anchor_b = Zone(zone_id="A1", depth=0, lat=0.0, lon=0.30);

    child_inboard_left = Zone(
        zone_id="C-L", depth=1, lat=0.01, lon=-0.20
    );
    child_inboard_right = Zone(
        zone_id="C-R", depth=1, lat=0.01, lon=0.20
    );
    child_straddler = Zone(
        zone_id="C-S", depth=1, lat=0.01, lon=-0.02
    );

    # Build the hierarchy off root.
    root ++> anchor_a ++> anchor_b;

    # Coverage: each child intersects both anchors (interior-intersection
    # in a small band). The straddler is a sub-zone of BOTH anchors under
    # coverage, which is the double-counting pathology the issue names.
    anchor_a +>:SubZone(intersect_area=0.8):+> child_inboard_left;
    anchor_b +>:SubZone(intersect_area=0.8):+> child_inboard_left;
    anchor_a +>:SubZone(intersect_area=0.8):+> child_inboard_right;
    anchor_b +>:SubZone(intersect_area=0.8):+> child_inboard_right;
    anchor_a +>:SubZone(intersect_area=0.6):+> child_straddler;
    anchor_b +>:SubZone(intersect_area=0.6):+> child_straddler;

    # Lineage: id-truncation ancestry. Transitive by construction. Here
    # both anchors are treated as lineage ancestors of all three children
    # for the demo; in a real DGGRS this is a function of the id.
    anchor_a +>:LineageOf:+> child_inboard_left;
    anchor_b +>:LineageOf:+> child_inboard_left;
    anchor_a +>:LineageOf:+> child_inboard_right;
    anchor_b +>:LineageOf:+> child_inboard_right;
    anchor_a +>:LineageOf:+> child_straddler;
    anchor_b +>:LineageOf:+> child_straddler;

    # Ownership: unique assignment. The straddler is owned by exactly
    # ONE anchor under the documented convention (centre-in-parent-
    # halfplane). Inboard children have unambiguous ownership.
    anchor_a +>:OwnedSubZone:+> child_inboard_left;
    anchor_b +>:OwnedSubZone:+> child_inboard_right;
    anchor_a +>:OwnedSubZone:+> child_straddler;

    auditor = HierarchyAuditor(audit_depth=1);
    root spawn auditor;

    print("--- roll-up ---");
    print(
        f"coverage  total={auditor.coverage_total} "
        f"straddlers={auditor.coverage_straddlers}"
    );
    print(
        f"lineage   total={auditor.lineage_total}"
    );
    print(
        f"ownership total={auditor.ownership_total} "
        f"straddlers={auditor.ownership_straddlers}"
    );
    print(
        "note: coverage double-counts the straddler (3+3 instead of 3); "
        "ownership is exact and the straddler belongs to exactly one parent."
    );
}

