}

node Contract {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has critical: bool = False;
    has selected: bool = False;
    has selection_reason: str = "";
    has skip_reason: str = "";
    has evidence: str = "";
}

edge GraphItem { }

edge Catalog { }

edge Impact {
    has provenance: str = "";
    has confidence: float = 1.0;
}

walker ImpactSelector {
    has seen_keys: list[str] = [];
    has path: str = "";

    can start with Root entry {
        print("starting impact traversal");
        visit [->:GraphItem:->] else {
            disengage;
        }
