"""Long interaction-aware pruning sequence validation.

Models the essential entities and traversal of the issue: a sequence of
mutation checkpoints (horizons) is exercised through stateless and
state-aware policies; cycles in deployment lineage must be detected
without hanging the walker; cumulative regret / violations are tallied;
and unsafe rollbacks are flagged.
"""

# ---------- Edge archetypes (relationships carry meaning) ----------

edge NextHorizon {
    has step: int = 0;
}

edge AdoptedBy {
    has policy: str = "stateless";
}

edge RollbackTo {
    has reason: str = "";
}

# ---------- Node archetypes ----------

node Checkpoint {
    has title: str = "";
    has horizon: int = 0;
    has cumulative_regret: float = 0.0;
    has violations: int = 0;
    has invalidated: bool = False;
    has lineage_id: str = "";
}

node Policy {
    has name: str = "stateless";
    has state_aware: bool = False;
}

node Outcome {
    has verdict: str = "unknown";
    has evidence: str = "";
}

# ---------- Walker: traverse a long pruning sequence ----------

walker SequenceAuditor {
    has visited_count: int = 0;
    has guard: list[str] = [];
    has total_regret: float = 0.0;
    has total_violations: int = 0;
    has unsafe_rollbacks: int = 0;
    has frontier: list[tuple] = [];

    can start with Root entry {
        print(f"[AUDIT] Begin long-sequence audit from root");
        visit [-->];
    }

    can audit_chain with Policy entry {
        policy_label = "STATE-AWARE" if here.state_aware else "STATELESS";
        print(f"[AUDIT] policy={here.name} ({policy_label})");
        visit [->:AdoptedBy:->];
    }

    can audit_checkpoint with Checkpoint entry {
        # Cycle guard: explicit, since jac 0.36 has no built-in visited set.
        if here.lineage_id in self.guard {
            print(f"[LOOP] cycle at horizon {here.horizon} -> disengage");
            disengage;
        }
        self.guard.append(here.lineage_id);
        self.visited_count += 1;
        self.total_regret += here.cumulative_regret;
        self.total_violations += here.violations;

        # Invalidation rule: preserved domain semantics.
        if here.invalidated {
            verdict = "invalidated";
        } elif here.cumulative_regret > 5.0 {
            verdict = "unsafe_rollback";
            self.unsafe_rollbacks += 1;
        } else {
            verdict = "ok";
        }
        print(
            f"[CHK] h={here.horizon} '{here.title}' "
            f"regret={here.cumulative_regret:.2f} "
            f"viol={here.violations} -> {verdict}"
        );
        self.frontier.append((here.horizon, here.cumulative_regret));

        next_hop = [->:NextHorizon:->];
        if next_hop {
            visit next_hop;
        } else {
            visit [->:RollbackTo:->];
        }
    }

    can record_outcome with Outcome entry {
        verdict_msg = here.verdict;
        evidence_msg = here.evidence;
        print(f"[OUTCOME] {verdict_msg}: {evidence_msg}");
    }
}

# ---------- Demo wiring ----------

with entry {
    # Two model families, three horizons each, three seeds.
    stat_policy = Policy(name="stateless-v1");
    aware_policy = Policy(name="state-aware-v1", state_aware=True);

    # Stateless chain: a horizon-10, 20, 50 with regret/violations.
    s1 = Checkpoint(title="stateless-h10", horizon=10,
                    cumulative_regret=1.2, violations=0,
                    lineage_id="S-1");
    s2 = Checkpoint(title="stateless-h20", horizon=20,
                    cumulative_regret=3.4, violations=1,
                    lineage_id="S-2");
    s3 = Checkpoint(title="stateless-h50", horizon=50,
                    cumulative_regret=8.9, violations=3,
                    invalidated=True, lineage_id="S-3");

    # State-aware chain: lower cumulative regret, no invalidations.
    a1 = Checkpoint(title="aware-h10", horizon=10,
                    cumulative_regret=0.4, violations=0,
                    lineage_id="A-1");
    a2 = Checkpoint(title="aware-h20", horizon=20,
                    cumulative_regret=0.9, violations=0,
                    lineage_id="A-2");
    a3 = Checkpoint(title="aware-h50", horizon=50,
                    cumulative_regret=1.7, violations=0,
                    lineage_id="A-3");

    # Forward edges along each sequence with explicit step counters.
    stat_policy +>:AdoptedBy:+> s1;
    s1 +>:NextHorizon(step=1):+> s2;
    s2 +>:NextHorizon(step=2):+> s3;
    s3 +>:RollbackTo(reason="regret_cap_exceeded"):+> (
        Outcome(verdict="unsafe", evidence="stateless-h50 invalidated")
    );

    aware_policy +>:AdoptedBy:+> a1;
    a1 +>:NextHorizon(step=1):+> a2;
    a2 +>:NextHorizon(step=2):+> a3;
    a3 +>:RollbackTo(reason="ok"):+> (
        Outcome(verdict="supported", evidence="state-aware frontier under cap")
    );

    # Cyclic rollback edge to demonstrate cycle guard + disengage.
    s2 +>:NextHorizon(step=99):+> s1;

    root ++> stat_policy ++> aware_policy;

    # Spawn the auditor from root; it will visit both policies and
    # walk each checkpoint chain, accumulating evidence.
    root spawn SequenceAuditor();
}

