"""Inference coverage gate: extend-receiver residual probe walker.

Models the gap-3 scenario where a closure passed into a generic extend
body drops spans that the inference table should keep. The walker
traverses an ``extend`` graph, classifying each method body as either
covered (every expression has a span record) or as a residual that
will trip the hard error when restored.
"""

node Method {
    has name: str = "";
    has body_size: int = 0;
    has span_table_len: int = 0;
    has missing_exprs: list[str] = [];
}

node ExtendBlock {
    has receiver: str = "";
    has type_param: str = "";
}

edge Hosts { }
edge Calls { }

walker CoverageProbe {
    has residual_count: int = 0;
    has covered_count: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        print("Probe: scanning extend bodies for span-keyed inference gaps");
        visit [-->];
    }

    can visit_extend with ExtendBlock entry {
        print(f"  extend {here.receiver}<{here.type_param}> {{");
        visit [-->];
    }

    can classify with Method entry {
        key = f"{here.name}@{here.body_size}";
        already = False;
        for tag in self.seen {
            if tag == key {
                already = True;
            }
        }
        if already {
            return;
        }
        self.seen.append(key);

        is_residual = False;
        if here.missing_exprs {
            is_residual = True;
        }

        if is_residual {
            self.residual_count = self.residual_count + 1;
            label = "RESIDUAL";
        } else {
            self.covered_count = self.covered_count + 1;
            label = "COVERED";
        }
        print(
            f"    [{label}] {here.name} body={here.body_size} "
            f"table={here.span_table_len} missing={here.missing_exprs}"
        );
    }
}

with entry {
    vec_extend = ExtendBlock(receiver="Vec", type_param="number");
    opt_extend = ExtendBlock(receiver="Option", type_param="T");

    m_sum = Method(
        name="sum_all",
        body_size=11,
        span_table_len=4,
        missing_exprs=["BinaryOp@96-101"]
    );
    m_flat = Method(
        name="flatten",
        body_size=19,
        span_table_len=9,
        missing_exprs=["CallExpr@210-228", "Ident@229-235"]
    );
    m_map = Method(
        name="map_to_str",
        body_size=7,
        span_table_len=3,
        missing_exprs=[]
    );
    m_then = Method(
        name="then_chain",
        body_size=27,
        span_table_len=15,
        missing_exprs=["Closure@440-475"]
    );

    vec_extend +>:Hosts:+> m_sum;
    vec_extend +>:Hosts:+> m_flat;
    vec_extend +>:Hosts:+> m_map;
    opt_extend +>:Hosts:+> m_then;
    opt_extend +>:Calls:+> m_then;

    root ++> vec_extend ++> opt_extend;
    probe = CoverageProbe();
    root spawn probe;

    print(
        f"covered={probe.covered_count} residuals={probe.residual_count}"
    );
}

"""PWA icon import and adaptive-processing cache.

Models the core scenario from Paladin173/pwa-manager issue #31: a user
picks a local image, it is normalized into an adaptive-friendly PNG,
cached on disk, and the cache is invalidated when the source artifact
changes. The hand-rolled cache walks a parent/child profile tree to
cascade-invalidate icons belonging to a profile — here it is lifted
into a typed ``OwnsIcon`` edge and a ``CacheJanitor`` walker that visits
owned icons and purges stale ones.
"""

node Profile {
    has name: str = "";
    has pwa_id: str = "";
}

node IconAsset {
    has display_name: str = "";
    has source_uri: str = "";
    has processed_path: str = "";
    has source_hash: str = "";
    has cached_hash: str = "";
    has is_valid: bool = True;
    has failure_reason: str = "";
}

node Attribution {
    has author: str = "";
    has license: str = "";
}

node PreLaunchRule {
    has rule_name: str = "";
    has enabled: bool = True;
}

edge OwnsIcon { }
edge AttributedTo { }
edge GovernedBy { }
edge IconImport { has original_format: str = ""; }

walker CacheJanitor {
    has purged_count: int = 0;
    has stale_count: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        print(f"[Janitor] starting cache sweep");
        visit [-->];
    }

    can sweep with Profile entry {
        if here.name in self.seen {
            visit [-->] else { disengage; }
        }
        self.seen.append(here.name);
        print(f"[Janitor] inspecting profile {here.pwa_id} ({here.name})");
        visit [->:OwnsIcon:->] else { disengage; }
    }

    can inspect_icon with IconAsset entry {
        stale = here.cached_hash != "" and here.cached_hash != here.source_hash;
        if not here.is_valid {
            print(f"[Janitor]   invalid asset {here.display_name}: {here.failure_reason}");
            self.purged_count += 1;
        } elif stale {
            print(f"[Janitor]   stale cache for {here.display_name} (reprocessing)");
            self.purged_count += 1;
            self.stale_count += 1;
        } else {
            print(f"[Janitor]   fresh: {here.display_name} -> {here.processed_path}");
        }
        visit [-->] else { disengage; }
    }

    can note_attr with Attribution entry {
        visit [-->] else { disengage; }
    }

    can note_rule with PreLaunchRule entry {
        visit [-->] else { disengage; }
    }
}

walker IconImporter {
    has original_format: str = "png";
    has expected_source_hash: str = "abc123";

    can start with Root entry {
        print(f"[Importer] format={self.original_format}, expected_hash={self.expected_source_hash}");
        visit [->:IconImport:->];
    }

    can normalize with IconAsset entry {
        if here.source_uri == "" {
            here.is_valid = False;
            here.failure_reason = "empty source URI";
            print(f"[Importer] FAILED: {here.display_name} has no source URI");
            disengage;
        }
        supported = ["png", "jpg", "jpeg", "webp"];
        if here.source_uri.lower().endswith(".ico") {
            here.is_valid = False;
            here.failure_reason = "ICO not supported for adaptive icons";
            print(f"[Importer] FAILED: {here.display_name} — ICO format rejected");
            disengage;
        }
        fmt = self.original_format;
        here.processed_path = f"/cache/icons/{here.display_name}.adaptive.png";
        here.cached_hash = self.expected_source_hash;
        here.is_valid = True;
        msg = "imported" if fmt in supported else f"imported (converted from {fmt})";
        print(f"[Importer] {msg}: {here.display_name} -> {here.processed_path}");
    }
}

with entry {
    work = Profile(name="Work", pwa_id="com.example.work");
    personal = Profile(name="Personal", pwa_id="com.example.personal");

    work_icon = IconAsset(
        display_name="work-launcher",
        source_uri="file:///picker/work.png",
        source_hash="abc123",
        cached_hash="abc123"
    );
    stale_icon = IconAsset(
        display_name="work-shortcut",
        source_uri="file:///picker/work-shortcut.png",
        source_hash="def456",
        cached_hash="old000"
    );
    broken_icon = IconAsset(
        display_name="personal-bad",
        source_uri="",
        source_hash="",
        cached_hash=""
    );

    work_attr = Attribution(author="Acme", license="CC-BY-4.0");
    work_rule = PreLaunchRule(rule_name="warm-cache", enabled=True);

    root ++> work ++> personal;

    work +>:OwnsIcon:+> work_icon;
    work +>:OwnsIcon:+> stale_icon;
    personal +>:OwnsIcon:+> broken_icon;

    work_icon +>:AttributedTo:+> work_attr;
    work +>:GovernedBy:+> work_rule;

    root +>:IconImport(original_format="png"):+> work_icon;
    root +>:IconImport(original_format="webp"):+> stale_icon;
    root +>:IconImport(original_format="ico"):+> broken_icon;

    importer = IconImporter(original_format="png", expected_source_hash="abc123");
    root spawn importer;

    janitor = CacheJanitor();
    root spawn janitor;
    print(f"[Demo] janitor purged {janitor.purged_count} entries "
          f"({janitor.stale_count} were stale)");
}

