"""Bounded rollout admission with flushed artifacts and cycle-safe dependency walks."""

node Driver {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has max_in_flight: int = 0;
    has retain_results: bool = True;
    has persisted_incrementally: bool = True;
}

node Rollout {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has row_key: str = "";
    has ordinal: int = 0;
    has admitted: bool = False;
    has active: bool = False;
    has completed: bool = False;
    has retained: bool = True;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has record_count: int = 0;
    has flushed: bool = False;
}

edge Admission {
    has slot: int = 0;
}

edge Produces {
    has channel: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker AdmissionAudit {
    has seen_keys: list[str] = [];
    has window: int = 0;
    has active_tasks: int = 0;
    has peak_tasks: int = 0;
    has retained_tasks: int = 0;
    has cycle_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_driver with Driver entry {
        self.window = here.max_in_flight;
        print(f"window={here.max_in_flight}, retain_results={here.retain_results}");
        visit [->:Admission:->] else { disengage; }
    }

    can inspect_rollout with Rollout entry {
        if here.row_key in self.seen_keys {
            self.cycle_count += 1;
            print(f"cycle detected at {here.row_key}");
            skip;
        }

        self.seen_keys.append(here.row_key);

        if here.admitted {
            if here.active {
                self.active_tasks += 1;
                if self.active_tasks > self.peak_tasks {
                    self.peak_tasks = self.active_tasks;
                }
                if self.active_tasks > self.window {
                    print(f"admission bound exceeded at {here.row_key}");
                }
            }
        }

        if here.retained {
            self.retained_tasks += 1;
        }

        print(f"rollout {here.ordinal}: {here.row_key}, completed={here.completed}");
        visit [->:DependsOn:->] else { skip; }
    }
}

walker ArtifactAudit {
    has seen_paths: list[str] = [];
    has flushed_records: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_driver with Driver entry {
        visit [->:Produces:->] else { disengage; }
    }

    can inspect_artifact with Artifact entry {
        if here.path in self.seen_paths {
            skip;
        }

        self.seen_paths.append(here.path);

        if here.flushed {
            self.flushed_records += here.record_count;
        }

        print(f"artifact {here.path}: records={here.record_count}, flushed={here.flushed}");
        visit [-->] else { skip; }
    }
}

with entry {
    driver = Driver(
        title="rollout-driver",
        year=2025,
        max_in_flight=2,
        retain_results=False,
        persisted_incrementally=True
    );
    root ++> driver;

    first = Rollout(
        title="first-row",
        year=2025,
        row_key="row-1",
        ordinal=1,
        admitted=True,
        active=True,
        completed=True,
        retained=False
    );
    second = Rollout(
        title="second-row",
        year=2025,
        row_key="row-2",
        ordinal=2,
        admitted=True,
        active=True,
        completed=True,
        retained=False
    );
    third = Rollout(
        title="third-row",
        year=2025,
        row_key="row-3",
        ordinal=3,
        admitted=False,
        active=False,
        completed=False,
        retained=False
    );

    driver +>:Admission(slot=1):+> first;
    driver +>:Admission(slot=2):+> second;

    first +>:DependsOn(reason="shared prompt preparation"):+> second;
    second +>:DependsOn(reason="shared prompt preparation"):+> third;
