"""Schema-typed set diffing over nested blocks (idiomatic Jac demo).

Models the gap from issue #285: a Terraform resource schema that carries
nested blocks with `nesting_mode: "set"`. Top-level set attrs were already
collapsed by hash in #280/#284, but set-nested blocks still produce
positional findings. This demo builds a small `PlanSchemaTypes` tree,
walks it with a walker that diffs each set surface by hash (the desired
behavior), and contrasts that with the old positional walk that over-
reports on insertion.
"""

edge Owns { }
edge ContainsSet { }

node SchemaAttribute {
    has name: str = "";
    has kind: str = "";
    has collapsed: bool = False;
}

node SetAttribute {
    has name: str = "";
    has members: list[str] = [];
    has prior: list[str] = [];
}

node BlockInstance {
    has addr: str = "";
    has prior_addr: str = "";
    has child_attrs: list[str] = [];
}

node Resource {
    has type_name: str = "";
    has child_attrs: list[str] = [];
}

walker SchemaSetDiff {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can at_resource with Resource entry {
        for attr_name in here.child_attrs {
            self.findings.append(
                f"[top-set] {here.type_name}.{attr_name}: multiset-delta members"
            );
        }
        visit [->:Owns:->];
    }

    can at_block with BlockInstance entry {
        for attr_name in here.child_attrs {
            self.findings.append(
                f"[nested-set] {here.addr}.{attr_name}: multiset-delta members"
            );
        }
        visit [->:ContainsSet:->];
    }

    can at_set with SetAttribute entry {
        prior = here.prior;
        curr = here.members;
        added = [m for m in curr if m not in prior];
        removed = [m for m in prior if m not in curr];
        self.findings.append(
            f"  set[{here.name}] added={added} removed={removed}"
        );
    }
}

walker PositionalSetDiff {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can at_resource with Resource entry {
        visit [->:Owns:->];
    }

    can at_block with BlockInstance entry {
        visit [->:ContainsSet:->];
    }

    can at_set with SetAttribute entry {
        prior = here.prior;
        curr = here.members;
        prior_len = len(prior);
        curr_len = len(curr);
        max_len = prior_len if prior_len > curr_len else curr_len;
        for i in range(max_len) {
            old_val = prior[i] if i < prior_len else "<absent>";
            new_val = curr[i] if i < curr_len else "<absent>";
            if old_val != new_val {
                self.findings.append(
                    f"  positional[{here.name}@{i}] {old_val} -> {new_val}"
                );
            }
        }
    }
}

walker AddressAudit {
    has unaddressed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can at_resource with Resource entry {
        visit [->:Owns:->];
    }

    can at_block with BlockInstance entry {
        if here.addr == "" {
            self.unaddressed.append("<unaddressed block instance>");
        }
        visit [->:ContainsSet:->];
    }
}

with entry {
    r = Resource(
        type_name="example.dest_ip_groups",
        child_attrs=["name"],
    );

    b0 = BlockInstance(
        addr="dest_ip_groups[0]",
        prior_addr="dest_ip_groups[0]",
        child_attrs=["cidrs"],
    );
    b1 = BlockInstance(
        addr="dest_ip_groups[1]",
        prior_addr="dest_ip_groups[1]",
        child_attrs=["cidrs"],
    );
    b2 = BlockInstance(
        addr="dest_ip_groups[2]",
        prior_addr="dest_ip_groups[2]",
        child_attrs=["cidrs"],
    );

    r +>:Owns:+> b0;
    r +>:Owns:+> b1;
    r +>:Owns:+> b2;

    s0 = SetAttribute(
        name="cidrs",
        prior=["10.0.0.1", "10.0.0.2", "10.0.0.3"],
        members=["10.0.0.1", "10.0.0.5", "10.0.0.3"],
    );
    s1 = SetAttribute(
        name="cidrs",
        prior=["10.0.0.10", "10.0.0.11"],
        members=["10.0.0.10", "10.0.0.11"],
    );
    s2 = SetAttribute(
        name="cidrs",
        prior=["10.0.0.20"],
        members=["10.0.0.20"],
    );
    b0 +>:ContainsSet:+> s0;
    b1 +>:ContainsSet:+> s1;
    b2 +>:ContainsSet:+> s2;

    root ++> r;

    print("=== desired: hash-collapsed multiset diff over nested blocks ===");
    diff_walker = SchemaSetDiff();
    root spawn diff_walker;
    for line in diff_walker.findings {
        print(line);
    }

    print("");
    print("=== broken: positional diff (over-reports on insertion) ===");
    pos_walker = PositionalSetDiff();
    root spawn pos_walker;
    for line in pos_walker.findings {
        print(line);
    }

    print("");
    print("=== sanity: every block instance has an address ===");
    audit = AddressAudit();
    root spawn audit;
    if len(audit.unaddressed) == 0 {
        print("all block instances addressed; reviewer can act on findings");
    } else {
        for u in audit.unaddressed {
            print(f"unaddressed: {u}");
        }
    }
}

