"""Stationarity audit for a durable agent run using typed graph traversal."""

node AgentRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has policy: str = "Balanced";
    has stop_reason: str = "";
    has budget: int = 0;
}

node Turn {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has action: str = "";
    has stationary: bool = False;
    has uncertain_dispatch: bool = False;
}

node Observation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has externally_attributed: bool = False;
    has novel: bool = False;
    has witness_advances: bool = False;
    has deadline_open: bool = False;
}

edge Includes { }

edge Records {
    has evidence: str = "";
}

edge FollowUp { }

walker StationarityAuditor {
    has visited_titles: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_run with AgentRun entry {
        print(f"run={here.title} policy={here.policy} budget={here.budget}");
        if here.stop_reason != "" {
            print(f"durable stop={here.stop_reason}");
        }
        visit [->:Includes:->] else { disengage; }
    }

    can inspect_turn with Turn entry {
        if here.title in self.visited_titles {
            print(f"cycle detected at {here.title}; traversal stopped");
            disengage;
        }

        self.visited_titles.append(here.title);

        if here.uncertain_dispatch {
            print(f"{here.title}: uncertain dispatch is absorbing; no retry");
        } elif here.stationary {
            print(f"{here.title}: repeated action is a no-op");
        } else {
            print(f"{here.title}: action={here.action}");
        }

        visit [->:Records:->] else { disengage; }
    }

    can inspect_observation with Observation entry {
        if here.externally_attributed and here.novel {
            print(f"{here.title}: progress from {here.kind}");
        } elif here.kind == "wait" and here.witness_advances and here.deadline_open {
            print(f"{here.title}: witnessed wait is productive");
        } else {
            print(f"{here.title}: no externally attributable progress");
        }

        visit [->:FollowUp:->] else { disengage; }
    }
}

with entry {
    run = AgentRun(
        title="nightly-agent",
        policy="Economy",
        stop_reason="stationary-no-op",
        budget=3
    );

    first = Turn(
        title="turn-1",
        action="repeat plan",
        stationary=True
    );

    wait_turn = Turn(
        title="turn-2",
        action="wait for host test",
        stationary=False
    );

    observation = Observation(
        title="observation-1",
        kind="wait",
        witness_advances=True,
        deadline_open=True
    );

    repeated = Observation(
        title="observation-2",
        kind="model claim",
        externally_attributed=False,
        novel=False
    );

    root ++> run;
    run +>:Includes:+> first;
    first +>:Records(evidence="repeated action"):+> repeated;
    repeated +>:FollowUp:+> wait_turn;
    wait_turn +>:Records(evidence="host witness"):+> observation;
    observation +>:FollowUp:+> first;

    root spawn StationarityAuditor();
}

