"""Holon space membership: model Holons and HolonSpaces with typed OwnedBy/Owns
edges and demonstrate membership creation, version inheritance (no re-anchor),
self-ownership guard, and retraction on delete.
"""

node HolonSpace {
    has name: str = "";
}

node Holon {
    has title: str = "";
    has version: int = 1;
    has deleted: bool = False;
}

edge OwnedBy {
    has since: str = "";
}

edge Owns {
    has since: str = "";
}

# Stages membership: owned_by the bound space, unless the holon IS the space.
walker MembershipStager {
    has space_name: str = "";

    can stage with Root entry {
        bound_space: HolonSpace | None = None;
        for n in [-->] {
            if isinstance(n, HolonSpace) {
                bound_space = n;
            }
        }
        if bound_space is None {
            print("WARN: no HolonSpace bound to this transaction");
            disengage;
        }
        visit [-->];
        print(f"Staged membership for space: {bound_space.name}");
    }

    can stage_with_holon with Holon entry {
        if here.deleted {
            visit [-->];
        }
        for n in [-->] {
            if isinstance(n, HolonSpace) {
                # Self-ownership guard: a space does not own itself.
                if here.title == n.name {
                    visit [-->];
                }
            }
        }
        print(f"  -> Holon '{here.title}' v{here.version} staged for membership");
        visit [-->];
    }
}

# Resolves the inverse structurally: OwnedBy on a Holon -> Owns on the Space.
walker InverseResolver {
    can start with Root entry {
        visit [-->];
    }

    can resolve_inverse with Holon entry {
        space_node: HolonSpace | None = None;
        for n in [-->] {
            if isinstance(n, HolonSpace) {
                space_node = n;
            }
        }
        if space_node is not None {
            label = "Owns";
        } else {
            label = "UNRESOLVED";
        }
        print(f"Inverse of {here.title}'s OwnedBy -> {label}");
        visit [-->];
    }
}

# Versioning walker: a new version inherits its lineage root's space membership
# rather than acquiring its own.
walker VersionProducer {
    has new_version: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can produce_version with Holon entry {
        if here.version >= self.new_version {
            visit [-->];
        }
        here.version = self.new_version;
        print(f"Produced v{self.new_version} of '{here.title}' (inherits lineage root's space)");
        visit [-->];
    }
}

# Retraction walker: deletes the Owns link on the space and the OwnedBy link on the holon.
walker MembershipRetractor {
    can start with Root entry {
        visit [-->];
    }

    can retract with Holon entry {
        if not here.deleted {
            visit [-->];
        }
        # Retract Owns from the space side first (the side future discovery reads).
        for n in [-->] {
            if isinstance(n, HolonSpace) {
                print(f"Retracting Owns from space '{n.name}' for deleted holon '{here.title}'");
                n del --> here;
            }
        }
        # Then retract OwnedBy on the holon itself.
        here del --> [-->];
        print(f"Retracted OwnedBy on deleted holon '{here.title}'");
        visit [-->];
    }
}

# Membership auditor: walks every holon and reports its bound space (or none).
walker MembershipAuditor {
    has total: int = 0;
    has bound: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Holon entry {
        self.total += 1;
        found_space: HolonSpace | None = None;
        for n in [-->] {
            if isinstance(n, HolonSpace) {
                found_space = n;
            }
        }
        if found_space is not None {
            self.bound += 1;
            print(f"  AUDIT: '{here.title}' v{here.version} -> space '{found_space.name}'");
        } else {
            print(f"  AUDIT: '{here.title}' v{here.version} -> NO SPACE");
        }
        visit [-->];
    }

    can audit_space with HolonSpace entry {
        members: list = [];
        for n in [-->] {
            if isinstance(n, Holon) and not n.deleted {
                members.append(n.title);
            }
        }
        print(f"  AUDIT: space '{here.name}' owns {len(members)} holon(s): {members}");
    }
}

with entry {
    local_space = HolonSpace(name="LocalHolonSpace");
    root ++> local_space;

    h1 = Holon(title="Alpha");
    h2 = Holon(title="Beta");
    h3 = Holon(title="Gamma");
    local_space ++> h1;
    local_space ++> h2;
    local_space ++> h3;

    print("=== Stage membership on create ===");
    root spawn MembershipStager();

    print("\n=== Resolve inverses structurally ===");
    root spawn InverseResolver();

    print("\n=== Audit membership ===");
    root spawn MembershipAuditor();

    print("\n=== Produce a new version of Alpha (must NOT re-anchor) ===");
    root spawn VersionProducer(new_version=2);

    print("\n=== Mark Beta as deleted and retract its membership ===");
    h2.deleted = True;
    root spawn MembershipRetractor();

    print("\n=== Final audit ===");
    root spawn MembershipAuditor();
}

"""Recursive wrap of nested mappings with conditional path-access.

Models the essential scenario from the ``dol`` ``conditional_data_trans``
issue: a tree of nested mappings should be walked depth-first, and at
every node whose value is itself a mapping the same wrapping transform
should be re-applied. A walker over typed ``Child`` edges does the
recursion; the walker carries the cycle guard that the hand-rolled
Python version had to maintain by hand. ``add_path_access`` is faked
in-memory: keys can be tuples (path access) or scalars (direct access)."""

node MappingNode {
    # The "value" of this node, expressed as a flat dict for demo purposes.
    has key: str = "";
    has value: object = None;
    has wrapped: bool = False;
}

# A typed edge carries the "this node holds another mapping as a sub-value"
# relationship. Cycle-safe traversal goes through ``Child`` edges.
edge Child {
    has label: str = "";
}

# A ``MappingStore`` models the wrapped container that the user holds.
# ``lookup`` implements path-style access (tuple keys) and direct access
# (scalar keys), and is the surface ``conditional_data_trans`` exposes.
node MappingStore {
    has name: str = "store";
}

# Base walker carrying the cycle-guard visited set. Both walkers that
# traverse ``Child`` edges inherit this so the cycle policy is shared.
walker RecursiveWalkerBase {
    has visited_keys: list[str] = [];
}

# The recursive wrap walker. It visits ``MappingNode`` instances along
# ``Child`` edges, applies the ``add_path_access`` transform at each node
# that hasn't already been wrapped, and recurses into its children. The
# walker tracks a visited set so cyclic mappings don't hang the traversal
# (mirroring the cycle policy of the source Python implementation).
walker RecursiveWrap(RecursiveWalkerBase) {
    has store_name: str = "s";

    can begin with Root entry {
        print(f"Recursive wrap starting for store '{self.store_name}'");
        visit [-->];
    }

    can wrap_store with MappingStore entry {
        # Enter the top-level mapping node hanging off the store.
        visit [->:Child:->];
    }

    can apply_transform with MappingNode entry {
        guard = f"{here.key}";
        if guard in self.visited_keys {
            print(f"  skip (cycle): {here.key}");
            disengage;
        }
        self.visited_keys.append(guard);

        if not here.wrapped {
            here.wrapped = True;
            print(f"  wrap: {here.key} -> add_path_access applied");
        }

        # Recurse into child mapping nodes.
        children = [->:Child:->];
        if len(children) > 0 {
            visit children;
        } else {
            disengage;
        }
    }
}

# A second walker exercises the same graph from a different angle:
# path-style read. It also walks ``Child`` edges, but instead of wrapping,
# it resolves a tuple-style path against the nested mapping, returning
# the leaf value. Cycle policy (visited set) is preserved.
walker PathReader(RecursiveWalkerBase) {
    has path: list[str] = [];
    has result: object = None;

    can begin with Root entry {
        print(f"PathReader resolving {self.path}");
        visit [-->];
    }

    can enter_store with MappingStore entry {
        visit [->:Child:->];
    }

    can walk_path with MappingNode entry {
        guard = f"{here.key}";
        if guard in self.visited_keys {
            disengage;
        }
        self.visited_keys.append(guard);

        if len(self.path) == 0 {
            self.result = here.value;
            print(f"  leaf: {here.key} = {here.value}");
            disengage;
        }

        head = self.path[0];
        rest = self.path[1:];
        if head != here.key {
            # Not the level we're looking for; keep descending.
            visit [->:Child:->];
            return;
        }

        if len(rest) == 0 {
            self.result = here.value;
            print(f"  resolved: {here.key} = {here.value}");
            disengage;
        }

        # Drop the head and keep walking into children.
        self.path = rest;
        visit [->:Child:->];
    }
}

# Helper: build a nested mapping graph under a ``MappingStore``. Pure
# in-memory construction; no I/O.
with entry {
    # The original nested dict from the issue:
    # {'a': {'b': {'c': 42}}}
    a = MappingNode(key="a");
    b = MappingNode(key="b");
    c = MappingNode(key="c", value=42);

    s = MappingStore(name="s");
    root ++> s +>:Child(label="root->a"):+> a
              +>:Child(label="a->b"):+> b
              +>:Child(label="b->c"):+> c;

    # 1) Run the recursive wrap walker from the store.
    wrapper = RecursiveWrap(store_name="s");
    s spawn wrapper;

    # 2) Read back via path access through the PathReader walker.
    reader = PathReader(path=["a", "b", "c"]);
    s spawn reader;
    print(f"path-style read result: {reader.result}");

    # 3) Demonstrate cycle safety: re-enter the walker on a graph that
    # has a back-edge (a2 -> b2 -> a2). Without the visited guard, the
    # walker would hang (jac 0.36.1 has no built-in dedupe).
    a2 = MappingNode(key="a2");
    b2 = MappingNode(key="b2");
    s2 = MappingStore(name="s2");
    root ++> s2 +>:Child:+> a2 +>:Child:+> b2 +>:Child:+> a2;
    cycle_walker = RecursiveWrap(store_name="s2");
    s2 spawn cycle_walker;
}

