"""Dynamic child-region supervision and recovery on a factory floor.

Models the essential scenario from issue #38: a parent region supervises
dynamically created child regions, each with explicit completion, timeout,
cancellation, restart-recovery, and failure-propagation semantics. A
``Supervisor`` walker recursively propagates cancellation across descendants,
fences stale work, and prunes abandoned retries; an ``Inspector`` walker
collects the supervisor's authoritative state and projections."""

node WorkRegion {
    has name: str = "";
    has epoch: int = 0;
    has cancelled: bool = False;
    has blocked_reason: str = "";
    has terminal_outcome: str = "pending";  # pending | success | failed | timeout | cancelled
}

edge Supervises {
    has budget_ms: int = 1000;
    has attempt: int = 0;
    has abandoned: bool = False;
}

walker Supervisor {
    has trace_log: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can supervise with WorkRegion entry {
        self.trace_log.append(f"supervise:{here.name}:epoch={here.epoch}:outcome={here.terminal_outcome}");
        if here.cancelled {
            self.trace_log.append(f"fence-stale:{here.name}");
            visit [-->] else { disengage; }
            return;
        }
        # Propagate cancellation to descendants, advance epoch, fence stale work.
        here.cancelled = True;
        here.epoch += 1;
        here.terminal_outcome = "cancelled";
        self.trace_log.append(f"propagate-cancel:{here.name}");
        visit [->:Supervises:->];
    }

    can prune with WorkRegion entry {
        # Abandoned retries: keep history but no longer a live successor.
        here.terminal_outcome = "abandoned";
        self.trace_log.append(f"prune-abandoned:{here.name}");
    }
}

walker Inspector {
    has report_lines: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can inspect with WorkRegion entry {
        blocked = "none" if here.blocked_reason == "" else here.blocked_reason;
        line = f"region={here.name} epoch={here.epoch} outcome={here.terminal_outcome} blocked={blocked}";
        self.report_lines.append(line);
        visit [-->];
    }
}

with entry {
    parent = WorkRegion(name="parent-line");
    child_a = WorkRegion(name="child-A", terminal_outcome="success");
    child_b = WorkRegion(name="child-B", terminal_outcome="failed");
    child_c = WorkRegion(name="child-C", terminal_outcome="timeout", blocked_reason="deadline");
    # Abandoned retry of child-B: history preserved, not a live successor.
    child_b_retry = WorkRegion(name="child-B#retry1", terminal_outcome="abandoned");
    grandchild = WorkRegion(name="grandchild-A1");

    root ++> parent;
    parent +>:Supervises(budget_ms=500, attempt=1):+> child_a;
    parent +>:Supervises(budget_ms=500, attempt=1):+> child_b;
    parent +>:Supervises(budget_ms=250, attempt=1):+> child_c;
    parent +>:Supervises(budget_ms=500, attempt=2, abandoned=True):+> child_b_retry;
    child_a +>:Supervises(budget_ms=200, attempt=1):+> grandchild;

    supervisor = Supervisor();
    root spawn supervisor;
    print("supervision trace:");
    for `entry in supervisor.trace_log {
        print(f"  {`entry}");
    }

    inspector = Inspector();
    root spawn inspector;
    print("inspection report:");
    for line in inspector.report_lines {
        print(f"  {line}");
    }
}

"""Build system dependency auditor: traverses a diamond-shaped task graph
