"""Segmented layer pairing: branches disagree about what "nothing declared" means.

Models the issue's core asymmetry: depending on the element shape
(`<rect>` vs `<path>`), the same layer with the same absent `domMapping`
gets paired row-major in one branch and column-major in the other.

Three node archetypes:
    SegmentedLayer  — the consumer; holds the declared dom_order.
    RectMark        — Highcharts v10 square-corner mark.
    PathMark        — Highcharts v11+ rounded-corner mark.

Two walkers:
    PathPairer      — fires on PathMark; absent dom_order -> row-major.
    RectPairer      — fires on RectMark; absent dom_order -> column-major.

A walk over a mixed graph demonstrates the bug: the same absent
`dom_order` resolves to opposite pairings in the two branches.
"""

node SegmentedLayer {
    has name: str = "";
    has dom_order: str = "";   # "row", "column", or "" for undeclared
}

node RectMark {
    has series: int = 0;
    has index: int = 0;
}

node PathMark {
    has series: int = 0;
    has index: int = 0;
}

# Edge archetypes declared at module level (required for typed visits).
edge LayerOf { }

walker PathPairer {
    has layer_name: str = "";
    has pairs: list[str] = [];

    can start with Root entry {
        visit [->:LayerOf:->];
    }

    can on_layer with SegmentedLayer entry {
        self.layer_name = here.name;
        self._layer_order = here.dom_order;
        visit [->:LayerOf:->];
    }

    # Path branch default: absent dom_order => row-major.
    can pair_path with PathMark entry {
        effective = "row" if self._layer_order == "" else self._layer_order;
        pair_key = f"r{here.series}.{here.index}" if effective == "row" else f"c{here.index}.{here.series}";
        self.pairs.append(pair_key);
        visit [-->];
    }

    has _layer_order: str = "";
}

walker RectPairer {
    has layer_name: str = "";
    has pairs: list[str] = [];

    can start with Root entry {
        visit [->:LayerOf:->];
    }

    can on_layer with SegmentedLayer entry {
        self.layer_name = here.name;
        self._layer_order = here.dom_order;
        visit [->:LayerOf:->];
    }

    # Rect branch default: absent dom_order => column-major.
    can pair_rect with RectMark entry {
        effective = "column" if self._layer_order == "" else self._layer_order;
        pair_key = f"r{here.series}.{here.index}" if effective == "row" else f"c{here.index}.{here.series}";
        self.pairs.append(pair_key);
        visit [-->];
    }

    has _layer_order: str = "";
}

with entry {
    # Build a small graph: one SegmentedLayer with both mark shapes.
    layer = SegmentedLayer(name="stackedBar", dom_order="");  # nothing declared

    root +>:LayerOf:+> layer;

    # Highcharts v10: a rect mark.
    layer +>:LayerOf:+> RectMark(series=0, index=0);
    layer +>:LayerOf:+> RectMark(series=0, index=1);
    layer +>:LayerOf:+> RectMark(series=1, index=0);

    # Highcharts v11+: a path mark.
    layer +>:LayerOf:+> PathMark(series=0, index=0);
    layer +>:LayerOf:+> PathMark(series=0, index=1);
    layer +>:LayerOf:+> PathMark(series=1, index=0);

    # Walk it twice, once per branch, with the same absent dom_order.
    p_walker = PathPairer();
    root spawn p_walker;
    print(f"PATH branch  (absent dom_order): {p_walker.pairs}");

    r_walker = RectPairer();
    root spawn r_walker;
    print(f"RECT branch  (absent dom_order): {r_walker.pairs}");

    print("Same layer, same absent dom_order -> OPPOSITE pairings.");
}

