"""Contract amendment resolution: graph-grounded retrieval honors amendment precedence to find the operative termination clause, not superseded language."""

node Clause {
    has clause_id: str = "";
    has topic: str = "";
    has days: int = 0;
    has operative: bool = True;
}

node ContractDoc {
    has title: str = "";
    has doc_type: str = "";
}

edge Contains { }

edge Supersedes {
    has effective_date: str = "";
}

walker VectorOnlyRetriever {
    has query_topic: str = "";
    has selected_days: int = 0;
    has locked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan with ContractDoc entry {
        visit [->:Contains:->];
        visit [-->];
    }

    can pick_first with Clause entry {
        if not self.locked and here.topic == self.query_topic {
            self.selected_days = here.days;
            self.locked = True;
            status = "operative" if here.operative else "superseded";
            print(
                f"[VECTOR] Picked clause {here.clause_id}: "
                f"{here.days}-day termination ({status}, no precedence check)"
            );
            disengage;
        }
        visit [-->];
    }
}

walker GraphGroundedRetriever {
    has query_topic: str = "";
    has operative_days: int = 0;
    has operative_clause_id: str = "";
    has resolved: bool = False;
    has visited_docs: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can review with ContractDoc entry {
        if here.title in self.visited_docs {
            visit [-->];
        } else {
            self.visited_docs.append(here.title);
            print(f"[GRAPH] Reviewing {here.doc_type} document: {here.title}");
            visit [->:Contains:->];
            if here.doc_type == "amendment" {
                visit [->:Supersedes:->];
            }
            visit [-->];
        }
    }

    can assess with Clause entry {
        if here.topic == self.query_topic {
            label = "OPERATIVE" if here.operative else "SUPERSEDED";
            print(
                f"[GRAPH] Clause {here.clause_id}: "
                f"{here.days}-day termination ({label})"
            );
            if here.operative {
                self.operative_days = here.days;
                self.operative_clause_id = here.clause_id;
                self.resolved = True;
            }
        }
        visit [-->];
    }
}

with entry {
    base = ContractDoc(title="Master Services Agreement", doc_type="base");
    amend = ContractDoc(title="Amendment No. 1", doc_type="amendment");
    old_term = Clause(
        clause_id="4.2",
        topic="termination",
        days=60,
        operative=False
    );
    new_term = Clause(
        clause_id="4.2",
        topic="termination",
        days=90,
        operative=True
    );

    root ++> base ++> amend;
    base +>:Contains:+> old_term;
    amend +>:Supersedes(effective_date="2023-01-15"):+> old_term;
    amend +>:Contains:+> new_term;

    print("=== Vector-only retrieval (first semantic match) ===");
    root spawn VectorOnlyRetriever(query_topic="termination");

    print("=== Graph-grounded retrieval (amendment precedence) ===");
    root spawn GraphGroundedRetriever(query_topic="termination");

    print(
        f"Outcome: vector-only answers 60 days; "
        f"controlling operative term is 90 days."
    );
}

"""Track conda-forge win-arm64 packages needed to drop environment-dev-win-arm64.yml.

Models the core entities from the issue as graph nodes:
- Package nodes (the things we want to install from conda-forge)
- Test nodes (the things that depend on those packages)
- Platform nodes (the win-arm64 architecture and the CI environment files)

Relationships are typed edges:
- Package --TestDependsOn--> Test
- Package --Blocks--> Platform   (a package that is unsolvable on a platform)
- Platform --UsesEnv--> EnvFile (which environment file a platform uses)

A walker (``ReleaseHunter``) traverses the platform -> blocked-package -> test
graph and reports the dependency closure we have to wait on before we can
unify on ``environment-dev.yml`` and delete ``environment-dev-win-arm64.yml``.
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Package {
    has name: str = "";
    has category: str = "";      # "compiled" | "noarch-blocked" | "ready"
    has available_on_arm64: bool = False;
}

node Test {
    has name: str = "";
    has skip_mechanism: str = "";  # e.g. "pytest.importorskip(\"xprocess\")"
    has still_skipped: bool = True;
}

node Platform {
    has arch: str = "";
    has env_file: str = "";
}

node EnvFile {
    has filename: str = "";
    has unified: bool = False;
}

# ---------------------------------------------------------------------------
# Edge archetypes (typed because the relationship carries meaning)
# ---------------------------------------------------------------------------

edge TestDependsOn {
    has optional: bool = False;   # True => may be added incrementally
}

edge Blocks {
    has reason: str = "";         # why the platform cannot resolve it
}

edge UsesEnv { }

# ---------------------------------------------------------------------------
# Walker: report the work still required to retire the win-arm64 env file
# ---------------------------------------------------------------------------

walker ReleaseHunter {
    has unresolved: list[str] = [];
    has blocked_tests: list[str] = [];
    has ready_to_unify: bool = False;

    can start with Root entry {
        # Enter every platform we care about.
        visit [-->];
    }

    can scan_platform with Platform entry {
        print(f":: platform {here.arch} uses env file '{here.env_file}'");
        # From a platform: follow its blocked packages + the env-file link.
        visit [->:Blocks:->];
        visit [->:UsesEnv:->];
    }

    can record_blocker with Package entry {
        if not here.available_on_arm64 {
            self.unresolved.append(here.name);
            print(f"   blocker: {here.name} ({here.category})");
        }
        visit [->:TestDependsOn:->];
    }

    can record_test with Test entry {
        if here.still_skipped {
            self.blocked_tests.append(here.name);
            print(f"      test still skipped: {here.name}");
        }
        # Walk to the next platform when the chain ends.
        visit [-->] else { disengage; }
    }

    can check_env with EnvFile entry {
        unified = here.unified and len(self.unresolved) == 0;
        self.ready_to_unify = unified;
        marker = "OK" if unified else "WAIT";
        print(f"   env file '{here.filename}' -> [{marker}]");
        if not unified {
            print(f"      waiting on {len(self.unresolved)} package(s) "
                  f"and {len(self.blocked_tests)} skipped test(s)");
        }
    }
}

# ---------------------------------------------------------------------------
# Demo graph
# ---------------------------------------------------------------------------

with entry {
    # --- platforms ---------------------------------------------------------
    win_arm64 = Platform(arch="win-arm64", env_file="environment-dev-win-arm64.yml");
    win_x64   = Platform(arch="win-x64",   env_file="environment-dev.yml");
    root ++> win_arm64 ++> win_x64;

    # --- env files ---------------------------------------------------------
    arm_env  = EnvFile(filename="environment-dev-win-arm64.yml", unified=False);
    main_env = EnvFile(filename="environment-dev.yml",           unified=True);
    win_arm64 +>:UsesEnv:+> arm_env;
    win_x64   +>:UsesEnv:+> main_env;

    # --- packages that block win-arm64 today -------------------------------
    cxx      = Package(name="cxx-compiler",  category="compiled",       available_on_arm64=False);
    pkgconf  = Package(name="pkg-config",    category="compiled",       available_on_arm64=False);
    crypt    = Package(name="cryptography",  category="noarch-blocked", available_on_arm64=False);
    bcrypt   = Package(name="bcrypt",        category="noarch-blocked", available_on_arm64=False);
    mitm     = Package(name="mitmproxy",     category="noarch-blocked", available_on_arm64=False);
    cct      = Package(name="conda-content-trust", category="noarch-blocked", available_on_arm64=False);
    mypy     = Package(name="mypy",          category="compiled",       available_on_arm64=False);
    doxygen  = Package(name="doxygen",       category="compiled",       available_on_arm64=False);
    binutils = Package(name="binutils",      category="compiled",       available_on_arm64=False);

    # --- packages that ARE solvable on win-arm64 (kept as optional deps) ---
    xprocess = Package(name="pytest-xprocess", category="ready", available_on_arm64=True);
    pywin32  = Package(name="pywin32",         category="ready", available_on_arm64=True);
    zstd     = Package(name="zstandard",       category="ready", available_on_arm64=True);
    memprof  = Package(name="memory_profiler", category="ready", available_on_arm64=True);

    # win-arm64 is blocked by the compiled/noarch-blocked packages.
    for pkg in [cxx, pkgconf, crypt, bcrypt, mitm, cct, mypy, doxygen, binutils] {
        win_arm64 +>:Blocks(reason=f"{pkg.name} missing for win-arm64"):+> pkg;
    }

    # --- tests that are currently skipped ----------------------------------
    test_proxy  = Test(name="micromamba/tests/test_proxy.py",   skip_mechanism="pytest.skip");
    test_login  = Test(name="micromamba/tests/test_login.py",   skip_mechanism="pytest.importorskip(\"xprocess\")");
    test_menu   = Test(name="micromamba/tests/test_menuinst.py", skip_mechanism="pytest.importorskip(\"win32com.client\")");
    test_pkg    = Test(name="micromamba/tests/test_package.py", skip_mechanism="pytest.importorskip(\"zstandard\")");
    test_create = Test(name="micromamba/tests/test_create.py::test_create_with_empty_lines_and_comments",
                       skip_mechanism="pytest.importorskip(\"memory_profiler\")");
    test_pe     = Test(name="Check micromamba PE dependencies",  skip_mechanism="job step skipped when matrix.arch == 'arm64'");

    # test_proxy is blocked by mitmproxy (which transitively needs crypt+bcrypt)
    mitm     +>:TestDependsOn:+> test_proxy;
    crypt    +>:TestDependsOn:+> test_proxy;
    bcrypt   +>:TestDependsOn:+> test_proxy;

    # the noarch-blocked packages gate conda-content-trust tests
    cct      +>:TestDependsOn:+> test_login;

    # the "ready" packages gate tests that could already be re-enabled
    xprocess +>:TestDependsOn(optional=True):+> test_login;
    pywin32  +>:TestDependsOn(optional=True):+> test_menu;
    zstd     +>:TestDependsOn(optional=True):+> test_pkg;
    memprof  +>:TestDependsOn(optional=True):+> test_create;

    # the compiled package binutils gates the static-build PE check
    binutils +>:TestDependsOn:+> test_pe;

    # --- run the walker ----------------------------------------------------
    root spawn ReleaseHunter();

    print("--- summary ---");
    hunter = ReleaseHunter();
    # Re-spawn to collect results purely for the demo summary (idempotent).
    root spawn hunter;
    print(f"unresolved packages : {hunter.unresolved}");
    print(f"blocked tests       : {hunter.blocked_tests}");
    print(f"ready to unify env  : {hunter.ready_to_unify}");
}

