"""Health-inspect a restaurant kitchen line (grill, fryer, cold prep).

Two parallel inspections run at every station:
  1. Temperature check -- flag any station above 40 C as a violation.
  2. Visit log -- record every station the inspector passes through.
"""

# Three station archetypes share a common base so a single union ability
# can handle all of them at once.
node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Grill(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Fryer(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
