"""Agent harness: model bounded coding subagents and walk their lineage.

Entities: Workspace, Principal, Agent (parent/child), TaskLineage.
Traversal: cascade cancel from a parent agent through its whole task tree,
budget invalidation, and a reachability audit across principals/workspaces.
"""

node Principal {
    has name: str = "";
    has role: str = "user";
}

node Workspace {
    has ws_name: str = "";
    has network_isolated: bool = True;
}

node TaskLineage {
    has lineage_id: str = "";
    has created_at: str = "2026-01-01T00:00:00Z";
}

node Agent {
    has agent_id: str = "";
    has title: str = "";
    has status: str = "running";
    has ttl_seconds: int = 600;
    has token_budget: int = 0;
    has tokens_used: int = 0;
    has idempotency_key: str = "";
    has tool_policy: str = "default";
    has provider: str = "default";
    has model: str = "default";
}

edge OwnedBy { has granted_at: str = "2026-01-01T00:00:00Z"; }
edge MemberOf { has joined_at: str = "2026-01-01T00:00:00Z"; }
edge SpawnedIn { has bound_at: str = "2026-01-01T00:00:00Z"; }
edge ChildOf { has depth: int = 1; }
edge ImplementsTask { has order: int = 0; }

walker CascadeCancel {
    has cancelled_count: int = 0;
    has seen: list[str] = [];
    has depth_cap: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can enter_workspace with Workspace entry {
        visit [-->];
    }

    can enter_lineage with TaskLineage entry {
        visit [-->];
    }

    can cancel_agent with Agent entry {
        already = False;
        for tag in self.seen {
            if tag == here.agent_id {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(here.agent_id);
        if here.status != "cancelled" {
            here.status = "cancelled";
            self.cancelled_count += 1;
            print(f"[CANCEL] {here.agent_id} ({here.title}) ttl={here.ttl_seconds}s tokens={here.tokens_used}/{here.token_budget}");
        }
        if len(self.seen) >= self.depth_cap {
            disengage;
        }
        visit [->:ChildOf:->];
    }

    can audit_principal with Principal entry {
        print(f"[AUDIT] principal={here.name} role={here.role}");
        visit [-->];
    }

    can audit_workspace with Workspace entry {
        print(f"[AUDIT] workspace={here.ws_name} network_isolated={here.network_isolated}");
        visit [-->];
    }
}

walker BudgetInvalidator {
    has threshold: int = 0;
    has evicted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can check_agent with Agent entry {
        over_budget = False;
        if here.token_budget > 0 {
            if here.tokens_used > here.token_budget {
                over_budget = True;
            }
        }
        if over_budget {
            here.status = "invalidated";
            self.evicted += 1;
            print(f"[INVALIDATE] {here.agent_id} tokens={here.tokens_used} budget={here.token_budget}");
        }
        visit [-->];
    }
}

walker ReachabilityAuditor {
    has target_ws: str = "";
    has target_principal: str = "";
    has leaks: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_agent with Agent entry {
        ws_name = "";
        principal_name = "";
        bad = False;
        for neighbour in [-->] {
            if isinstance(neighbour, Workspace) {
                ws_name = neighbour.ws_name;
                if self.target_ws != "" and ws_name != self.target_ws {
                    bad = True;
                    note = f"agent {here.agent_id} leaked into workspace {ws_name}";
                    self.leaks.append(note);
                }
            }
            if isinstance(neighbour, Principal) {
                principal_name = neighbour.name;
                if self.target_principal != "" and principal_name != self.target_principal {
                    bad = True;
                    note = f"agent {here.agent_id} reachable from principal {principal_name}";
                    self.leaks.append(note);
                }
            }
        }
        if bad {
            print(f"[LEAK] {here.agent_id} -> ws={ws_name} principal={principal_name}");
        }
        visit [-->];
    }
}

with entry {
    alice = Principal(name="alice", role="owner");
    bob = Principal(name="bob", role="owner");
    mallory = Principal(name="mallory", role="guest");

    ws_alpha = Workspace(ws_name="alpha", network_isolated=True);
    ws_beta = Workspace(ws_name="beta", network_isolated=True);
    ws_other = Workspace(ws_name="other-tenant", network_isolated=True);

    lineage = TaskLineage(lineage_id="lineage-001");

    planner = Agent(
        agent_id="a-planner",
        title="task planner",
        status="running",
        ttl_seconds=900,
        token_budget=200000,
        tokens_used=120000,
        idempotency_key="plan-001",
        tool_policy="read-only",
        provider="pi-sdk",
        model="claude-opus"
    );

    coder = Agent(
        agent_id="a-coder",
        title="code writer",
        status="running",
        ttl_seconds=300,
        token_budget=80000,
        tokens_used=95000,
        idempotency_key="code-001",
        tool_policy="code-write",
        provider="pi-sdk",
        model="claude-sonnet"
    );

    reviewer = Agent(
        agent_id="a-reviewer",
        title="code reviewer",
        status="running",
        ttl_seconds=120,
        token_budget=40000,
        tokens_used=10000,
        idempotency_key="rev-001",
        tool_policy="read-only",
        provider="pi-sdk",
        model="claude-haiku"
    );

    root ++> alice ++> ws_alpha;
    root ++> bob ++> ws_beta;
    root ++> mallory ++> ws_other;

    alice +>:OwnedBy:+> ws_alpha;
    bob +>:OwnedBy:+> ws_beta;
    mallory +>:OwnedBy:+> ws_other;

    ws_alpha +>:MemberOf:+> lineage;
    ws_beta +>:MemberOf:+> lineage;
    ws_other +>:MemberOf:+> lineage;

    alice +>:SpawnedIn:+> planner;
    planner +>:SpawnedIn:+> ws_alpha;

    planner +>:ChildOf:+> coder;
    coder +>:SpawnedIn:+> ws_alpha;

    coder +>:ChildOf:+> reviewer;
    reviewer +>:SpawnedIn:+> ws_alpha;

    planner +>:ImplementsTask:+> lineage;
    coder +>:ImplementsTask:+> lineage;
    reviewer +>:ImplementsTask:+> lineage;

    print("=== CascadeCancel from planner ===");
    cc = CascadeCancel();
    planner spawn cc;
    print(f"cancelled {cc.cancelled_count} agents, seen={cc.seen}");

    print("=== BudgetInvalidator sweep ===");
    bi = BudgetInvalidator();
    root spawn bi;
    print(f"invalidated {bi.evicted} agents over budget");

    print("=== ReachabilityAuditor (cross-tenant check) ===");
    ra = ReachabilityAuditor(target_ws="alpha", target_principal="alice");
    root spawn ra;
    if len(ra.leaks) == 0 {
        print("[OK] no cross-tenant leaks detected");
    } else {
        print(f"[FAIL] leaks: {ra.leaks}");
    }

    print(f"final planner.status={planner.status}");
    print(f"final coder.status={coder.status}");
    print(f"final reviewer.status={reviewer.status}");
}
