"""Skinned BLAS rebuild scheduling with per-entity stagger.

Models the lockstep rebuild spike from issue PERF-D6-2026-08-30-01. Every
animated NPC in a cohort accumulates dirty frames at the same rate; with
a single global threshold they all trip on the same frame and saturate
the BUILD pipeline. A walker walks the cohort, advancing each entity's
refit counter by one dirty frame, then decides — per entity, with a
jittered threshold — whether to schedule a rebuild.
"""

node NPC {
    has name: str = "";
    has entity_id: int = 0;
    has refit_count: int = 0;
    has needs_rebuild: bool = False;
}

node Cohort {
    has label: str = "";
}

node RebuildBatch {
    has frame_label: str = "";
}

edge MemberOf { has cohort: str = ""; }
edge ScheduledFor { has frame_label: str = ""; }

walker TickDirtyFrames {
    can start with Root entry {
        visit [->:MemberOf:->];
    }

    can tick with NPC entry {
        here.refit_count += 1;
        visit [-->];
    }

    can tick_with_cohort with Cohort entry {
        visit [->:MemberOf:->];
    }
}

walker ScheduleRebuilds {
    has threshold: int = 600;
    has jitter: int = 47;

    can start with Root entry {
        visit [->:MemberOf:->];
    }

    can evaluate with NPC entry {
        per_entity_threshold = self.threshold + (here.entity_id % self.jitter);
        here.needs_rebuild = here.refit_count >= per_entity_threshold;
        visit [-->];
    }

    can evaluate_cohort with Cohort entry {
        visit [->:MemberOf:->];
    }
}

walker ApplyRebuilds {
    can start with Root entry {
        visit [->:ScheduledFor:->];
    }

    can rebuild with NPC entry {
        if here.needs_rebuild {
            print(f"  [REBUILD] {here.name} (id={here.entity_id}, refits={here.refit_count})");
            here.needs_rebuild = False;
            here.refit_count = 0;
        }
        visit [-->];
    }

    can rebuild_with_batch with RebuildBatch entry {
        visit [->:ScheduledFor:->];
    }
}

with entry {
    npcs = [
        NPC(name="Guard-A", entity_id=101),
        NPC(name="Guard-B", entity_id=102),
        NPC(name="Wanderer", entity_id=207),
        NPC(name="Merchant", entity_id=358),
    ];

    cohort = Cohort(label="InstituteInterior");
    root ++> cohort;
    for n in npcs {
        cohort +>:MemberOf(cohort="InstituteInterior"):+> n;
    }

    batch = RebuildBatch(frame_label="rebuild-batch-0");
    root ++> batch;
    for n in npcs {
        batch +>:ScheduledFor(frame_label="rebuild-batch-0"):+> n;
    }

    print("=== Run 1: lockstep (no jitter) — every NPC hits 600 together ===");
    for n in npcs {
        n.refit_count = 0;
        n.needs_rebuild = False;
    }
    cohort spawn TickDirtyFrames();
    Scheduler = ScheduleRebuilds(threshold=600, jitter=1);
    cohort spawn Scheduler;
    batch spawn ApplyRebuilds();

    print("\n=== Run 2: jittered threshold — rebuilds spread out per entity ===");
    for n in npcs {
        n.refit_count = 0;
        n.needs_rebuild = False;
    }
    cohort spawn TickDirtyFrames();
    Staggered = ScheduleRebuilds(threshold=600, jitter=47);
    cohort spawn Staggered;
    batch spawn ApplyRebuilds();
}

