"""Order auditor: invalid orders are skipped, fraud orders halt the walk."""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has halted: bool = False;

    can start with Root entry {
        print("Beginning order audit...");
        visit [-->];
    }

    can audit with Order entry {
        # Invalid orders are skipped: print a note and move on.
        if not here.valid {
            print(f"[SKIP]   {here.label}: invalid (${here.amount:.2f})");
            visit [-->];
        }
        # Fraud orders halt the whole walk on the spot.
        elif here.fraud {
            print(f"[HALT]   {here.label}: fraud flagged (${here.amount:.2f})");
            self.halted = True;
            disengage;
        }
        # Otherwise it's a clean pass.
        else {
            print(f"[PASS]   {here.label}: valid (${here.amount:.2f})");
            visit [-->];
        }
    }
}

with entry {
    # Build a small chain of orders: valid, invalid, valid, fraud, valid.
    # The walker should SKIP the invalid one, continue, then HALT on the fraud.
    root ++> Order(label="A-001", amount=120.00, valid=True, fraud=False)
        ++> Order(label="A-002", amount= 45.50, valid=False, fraud=False)
        ++> Order(label="A-003", amount=310.75, valid=True, fraud=False)
        ++> Order(label="A-004", amount=999.99, valid=True, fraud=True)
        ++> Order(label="A-005", amount= 60.00, valid=True, fraud=False);

    auditor = OrderAuditor();
    root spawn auditor;

    if auditor.halted {
        print("Audit halted early on fraud.");
    } else {
        print("Audit completed cleanly.");
    }
}

"""Order auditor: skip invalid orders but halt on any fraud-flagged one.

Orders are nodes carrying an amount, a validity flag, and a fraud flag.
The walker walks the order chain via plain ``-->`` edges. On every
order it prints exactly one line describing which action fired:

- ``SKIP``  -- the order is marked invalid; traversal continues.
- ``HALT``  -- the order is flagged for fraud; the walker disengages.
- ``OK``    -- the order is clean; traversal continues.

The "skip but keep going" behavior uses ``continue`` semantics: the
ability falls through and still issues ``visit [-->]``. The "halt now"
behavior uses ``disengage`` which terminates the entire walk.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: beginning audit");
        visit [-->] else {
            disengage;
        }
    }

    can audit with Order entry {
        action = "";
        if here.fraud_flag {
            action = "HALT";
            print(f"[{action}] amount={here.amount} fraud detected -- aborting walk");
            disengage;
        } elif not here.valid {
            action = "SKIP";
            print(f"[{action}] amount={here.amount} invalid -- continuing");
            visit [-->] else {
                disengage;
            }
        } else {
            action = "OK";
            print(f"[{action}] amount={here.amount} clean -- continuing");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    root ++> Order(amount=120.50, valid=True, fraud_flag=False)
        ++> Order(amount=9.99, valid=False, fraud_flag=False)
        ++> Order(amount=450.00, valid=True, fraud_flag=True)
        ++> Order(amount=75.00, valid=True, fraud_flag=False);

    root spawn OrderAuditor();
    print("OrderAuditor: done");
}

