    );

    root +>:Contains(kind="scan root"):+> workspace;
    workspace +>:Contains(kind="source file"):+> main_file;
    workspace +>:Contains(kind="child directory"):+> subdir;
    subdir +>:Contains(kind="source file"):+> nested_file;
    subdir +>:Contains(kind="symlink"):+> loop;
    loop +>:Contains(kind="resolved child directory"):+> subdir;

    root spawn TypeScanner();
}

"""Recursive type dependency demo.

Models the TypeScript issue about a type alias that "circularly references
itself" through variadic/mapped-type inference.  We use it as a teaching
example for graph traversal in Jac: a ``TypeDef`` node can depend on other
``TypeDef`` nodes via ``DependsOn`` edges, and a walker explores the
dependency closure while enforcing a recursion guard so that real cycles
do not hang the runtime (Jac 0.36.1 walkers have no built-in once-per-node
visitation -- see OSP_IDIOMIZE_SOL_REVIEW §2).
"""

node TypeDef {
    has name: str = "";
    has kind: str = "";
    has depth: int = 0;
}

edge DependsOn {
    has via: str = "";
}

walker DependencyInspector {
    has order: list[str] = [];
    has guard: set[str] = set();
    has max_depth: int = 8;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can inspect with TypeDef entry {
        if here.name in self.guard {
            self.cycle_found = True;
            print(f"[cycle] re-entry on {here.name}");
            disengage;
        }
        if here.depth > self.max_depth {
            print(f"[depth-cap] stopping at {here.name}");
            disengage;
        }
        self.guard.add(here.name);
        self.order.append(here.name);
        print(f"[enter] {here.kind} {here.name} (depth={here.depth})");
        visit [->:DependsOn:->];
    }
}

with entry {
    A = TypeDef(name="A", kind="alias", depth=0);
    B = TypeDef(name="B", kind="alias", depth=1);
    C = TypeDef(name="C", kind="alias", depth=2);
    D = TypeDef(name="D", kind="alias", depth=3);

    root +>:DependsOn(via="Row"):+> A;
    A +>:DependsOn(via="Rows"):+> B;
    B +>:DependsOn(via="Component"):+> C;
    C +>:DependsOn(via="AArgument"):+> D;
    D +>:DependsOn(via="ARow"):+> A;

    inspector = DependencyInspector();
    root spawn inspector;

    print("");
    print(f"order      = {inspector.order}");
    print(f"guard      = {sorted(inspector.guard)}");
    print(f"cycle_found = {inspector.cycle_found}");
}

"""Diamond build-graph auditor.

Models a build system's task graph as nodes connected by typed
``Needs`` edges. A ``BuildAuditor`` walker traverses the dependency
graph from the root, accumulating build minutes on each task.
Because the graph contains diamonds (a task reachable through
several parents) the walker carries a visited-set so every task is
audited exactly once even though traversal may reach it many times.
"""

node BuildTask {
    has name: str = "";
    has minutes: int = 0;
}

edge Needs {
    has weight: int = 1;
}

walker BuildAuditor {
    has visited: list[str] = [];
    has total_minutes: int = 0;
    has audited_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with BuildTask entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            self.total_minutes += here.minutes;
            self.audited_count += 1;
            print(f"[{self.audited_count}] auditing {here.name} (+{here.minutes} min, total={self.total_minutes})");
            visit [-->];
        } else {
            print(f"skip {here.name} (already audited via another path)");
            disengage;
        }
    }
}

with entry {
    # Diamond: C is depended on by both B and D, but should be counted once.
    c_lib = BuildTask(name="C-lib", minutes=10);

    a_root = BuildTask(name="A-root", minutes=5);
    b_mod = BuildTask(name="B-module", minutes=7);
    d_mod = BuildTask(name="D-module", minutes=3);
    e_mod = BuildTask(name="E-module", minutes=4);

    root ++> a_root;
    a_root +>:Needs:+> b_mod;
    a_root +>:Needs:+> d_mod;
    b_mod +>:Needs:+> c_lib;
    d_mod +>:Needs:+> c_lib;
    b_mod +>:Needs:+> e_mod;

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"\nFinal: audited {auditor.audited_count} tasks, total {auditor.total_minutes} build minutes");
}

"""Manifest-based VesEdge QC cleanup with safe typed-edge traversal."""

node OutputRoot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has root_path: str = "";
}

node QCManifest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has manifest_name: str = "vesedge_qc.json";
    has output_root: str = "";
    has provenance_valid: bool = True;
    has overwrite_requested: bool = False;
    has compatible: bool = True;

    def key() -> str {
        return self.manifest_name + "@" + self.output_root;
    }
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has output_root: str = "";
    has record_key: str = "";
    has managed: bool = False;
    has deleted: bool = False;

    def safe_for(root_path: str) -> bool {
        if self.path == "" {
            return False;
        }
        if self.path.startswith("/") {
            return False;
        }
        if self.path.find("..") >= 0 {
            return False;
        }
        if not self.path.startswith(root_path + "/") {
            return False;
        }
        return self.path.endswith(".npy")
            or self.path.endswith(".area_qc.csv")
            or self.path.endswith(".area_qc.png");
    }
}

edge Contains { }
edge RecordsArtifact { }
edge LocatedIn { }

walker ManifestValidator {
    has invalid_keys: list[str] = [];
    has seen_roots: list[str] = [];
    has seen_manifests: list[str] = [];
    has inspected: int = 0;
    has failures: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_root with OutputRoot entry {
        if here.root_path in self.seen_roots {
            print(f"ERROR cycle detected at output root {here.root_path}");
            disengage;
        } else {
            self.seen_roots.append(here.root_path);
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_manifest with QCManifest entry {
        key = here.key();

        if key in self.seen_manifests {
            print(f"ERROR manifest cycle detected for {key}");
            disengage;
        } else {
            self.seen_manifests.append(key);

            if not here.provenance_valid {
                self.failures += 1;
                self.invalid_keys.append(key);
                print(f"ERROR malformed provenance in {here.manifest_name}");
            }

            if here.manifest_name != "vesedge_qc.json" {
                self.failures += 1;
                self.invalid_keys.append(key);
                print(f"ERROR unexpected manifest name {here.manifest_name}");
            }

            visit [->:RecordsArtifact:->] else {
                print(f"ERROR no recorded artifacts in {key}");
            }
        }
    }

    can inspect_artifact with Artifact entry {
        self.inspected += 1;
        expected_key = "vesedge_qc.json@" + here.output_root;

        if not here.managed {
            self.failures += 1;
            self.invalid_keys.append(here.record_key);
            print(f"ERROR unowned artifact record {here.path}");
        }

        if here.record_key != expected_key {
            self.failures += 1;
            self.invalid_keys.append(here.record_key);
            print(f"ERROR artifact has invalid owner record {here.path}");
        }

        if not here.safe_for(here.output_root) {
            self.failures += 1;
            self.invalid_keys.append(here.record_key);
            print(f"ERROR unsafe artifact path rejected: {here.path}");
        }
    }

    can summarize with Root exit {
        print(f"validated {self.inspected} manifest artifacts with {self.failures} errors");
    }
}

walker ManifestCleaner {
    has invalid_keys: list[str] = [];
    has seen_roots: list[str] = [];
    has seen_manifests: list[str] = [];
    has removed: int = 0;
    has blocked: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can clean_root with OutputRoot entry {
        if here.root_path in self.seen_roots {
            print(f"cleanup stopped on cycle at {here.root_path}");
            disengage;
        } else {
            self.seen_roots.append(here.root_path);
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can clean_manifest with QCManifest entry {
        key = here.key();

        if key in self.seen_manifests {
            print(f"cleanup stopped on manifest cycle for {key}");
            disengage;
        } else {
            self.seen_manifests.append(key);

            if not here.overwrite_requested or here.compatible {
                print(f"cleanup skipped for compatible manifest {key}");
            } else {
                if key in self.invalid_keys {
                    self.blocked += 1;
                    print(f"cleanup refused before deletion for malformed {key}");
                } else {
                    visit [->:RecordsArtifact:->] else {
                        print(f"no managed artifacts to remove for {key}");
                    }
                }
            }
        }
    }

    can remove_artifact with Artifact entry {
        if here.managed and here.safe_for(here.output_root) {
            here.deleted = True;
            self.removed += 1;
            print(f"removed manifest-owned artifact {here.path}");
        } else {
            print(f"preserved unrecorded or unsafe artifact {here.path}");
        }
    }

    can summarize with Root exit {
        print(f"removed {self.removed} artifacts; blocked {self.blocked} destructive batches");
    }
}

with entry {
    good_root = OutputRoot(
        title="good output",
        root_path="out/good"
    );
    bad_root = OutputRoot(
        title="bad output",
        root_path="out/bad"
    );
    root +>:Contains:+> good_root;
    root +>:Contains:+> bad_root;

    good_manifest = QCManifest(
        title="valid QC batch",
        output_root="out/good",
        overwrite_requested=True,
        compatible=False
    );
    bad_manifest = QCManifest(
        title="malformed QC batch",
        output_root="out/bad",
        provenance_valid=False,
        overwrite_requested=True,
        compatible=False
    );
    good_root +>:Contains:+> good_manifest;
    bad_root +>:Contains:+> bad_manifest;

    good_key = "vesedge_qc.json@out/good";
    bad_key = "vesedge_qc.json@out/bad";

    managed_npy = Artifact(
        title="managed array",
        path="out/good/run.npy",
        output_root="out/good",
        record_key=good_key,
        managed=True
    );
    managed_csv = Artifact(
        title="nested managed CSV",
        path="out/good/nested/run.area_qc.csv",
        output_root="out/good",
        record_key=good_key,
        managed=True
    );
    managed_png = Artifact(
        title="nested managed plot",
        path="out/good/nested/run.area_qc.png",
        output_root="out/good",
        record_key=good_key,
        managed=True
    );
    good_manifest +>:RecordsArtifact:+> managed_npy;
    good_manifest +>:RecordsArtifact:+> managed_csv;
    good_manifest +>:RecordsArtifact:+> managed_png;

    unrelated_npy = Artifact(
        title="unrelated array",
        path="out/good/user.npy",
        output_root="out/good",
        managed=False
    );
    unrelated_csv = Artifact(
        title="unrelated CSV",
        path="out/good/user.area_qc.csv",
        output_root="out/good",
        managed=False
    );
    unrelated_png = Artifact(
        title="unrelated plot",
        path="out/good/nested/user.area_qc.png",
        output_root="out/good",
        managed=False
    );
    unrelated_txt = Artifact(
        title="nested user file",
        path="out/good/nested/notes.txt",
        output_root="out/good",
        managed=False
    );
    unrelated_npy +>:LocatedIn:+> good_root;
    unrelated_csv +>:LocatedIn:+> good_root;
    unrelated_png +>:LocatedIn:+> good_root;
    unrelated_txt +>:LocatedIn:+> good_root;

    traversal_attempt = Artifact(
        title="traversal attempt",
        path="out/bad/../secret.area_qc.csv",
        output_root="out/bad",
        record_key=bad_key,
        managed=True
    );
    unexpected_suffix = Artifact(
        title="unexpected suffix",
        path="out/bad/report.txt",
        output_root="out/bad",
        record_key=bad_key,
        managed=True
    );
    bad_manifest +>:RecordsArtifact:+> traversal_attempt;
    bad_manifest +>:RecordsArtifact:+> unexpected_suffix;

    validator = ManifestValidator();
    root spawn validator;

    cleaner = ManifestCleaner(invalid_keys=validator.invalid_keys);
    root spawn cleaner;

    print(f"managed nested CSV deleted: {managed_csv.deleted}");
    print(f"unrelated NPY preserved: {not unrelated_npy.deleted}");
    print(f"unrelated CSV preserved: {not unrelated_csv.deleted}");
    print(f"unrelated PNG preserved: {not unrelated_png.deleted}");
    print(f"unrelated nested file preserved: {not unrelated_txt.deleted}");
    print(f"traversal attempt deleted: {traversal_attempt.deleted}");
}

"""Goal orchestration graph with dependency traversal and cycle auditing."""

node Goal {
    has title: str = "";
    has active: bool = True;
    has archived: bool = False;
}

node Milestone {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node WorkItem {
    has title: str = "";
    has complete: bool = False;
    has evidence_count: int = 0;
    has seen: bool = False;
}

edge HasMilestone { }
edge HasTask { }
edge DependsOn {
    has reason: str = "";
}

walker DependencyAuditor {
    has depth: int = 0;
    has max_depth: int = 12;

    can start with Root entry {
        print("Auditing goal orchestration graph");
        visit [->:HasMilestone:->] else {
            disengage;
        }
    }

    can inspect_goal with Goal entry {
        print(f"Goal: {here.title}");
        if here.active {
            print("status: active");
        } else {
            print("status: historical");
        }
        visit [->:HasMilestone:->] else {
            disengage;
        }
    }

    can inspect_milestone with Milestone entry {
        print(f"Milestone: {here.title} ({here.year})");
        visit [->:HasTask:->] else {
            disengage;
        }
    }

    can inspect_task with WorkItem entry {
        self.depth += 1;

        if self.depth > self.max_depth {
            print(f"depth limit reached at {here.title}");
            disengage;
        } else {
            if here.seen {
                print(f"dependency cycle detected at {here.title}");
                disengage;
            } else {
                here.seen = True;
                print(f"Task: {here.title}");

                if here.complete {
                    if here.evidence_count == 0 {
                        print("invalid completion: evidence is required");
                    } else {
                        print(f"completed with {here.evidence_count} evidence items");
                    }
                } else {
                    print("pending");
                }

                visit [->:DependsOn:->] else {
                    disengage;
                }
            }
        }
    }
}

with entry {
    goal = Goal(title="Release 1 certification", active=True);
    milestone = Milestone(title="End-to-end workflow", year=2025);
    plan = WorkItem(title="Package the skill", complete=True, evidence_count=2);
    validate = WorkItem(title="Run structural validation");
