    root +>:HasMilestone:+> goal;
    goal +>:HasMilestone:+> milestone;
    milestone +>:HasTask:+> plan;
    milestone +>:HasTask:+> validate;
    milestone +>:HasTask:+> certify;

    plan +>:DependsOn(reason="validation must precede release"):+> validate;
    validate +>:DependsOn(reason="evidence is required for certification"):+> certify;
    certify +>:DependsOn(reason="cycle demonstrates explicit safety"):+> validate;

    root spawn DependencyAuditor();
}

"""Job worker cascade: model the A→B→C chain and walk it recursively.

The original raw-SQL cascade in cli/worker.py only touches direct parent_id
children, so a waiting grandchild of a cascade-failed child stays stuck forever.
This demo lifts the cascade into a walker over typed Parent edges, so
grandchildren (and great-grandchildren, etc.) are resolved by the same walk.
"""

node Job {
    has name: str = "";
    has state: str = "waiting";
    has retries: int = 0;
}

edge Parent {
    has order: int = 0;
}

walker Cascade {
    has failed_names: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 16;

    can start with Root entry {
        visit [-->];
    }

    can collapse with Job entry {
        if here.state == "waiting" {
            here.state = "failed";
            self.failed_names.append(here.name);
            print(f"  cascade -> failed {here.name} (depth {self.depth})");
        }
        if self.depth >= self.max_depth {
            visit [-->] else { disengage; }
            return;
        }
        self.depth += 1;
        visit [->:Parent:->];
        self.depth -= 1;
    }
}

walker Propagate {
    can start with Root entry {
        visit [-->];
    }

    can reap with Job entry {
        if here.state == "failed" {
            print(f"reaping failed job {here.name}");
        }
        visit [-->];
    }
}

with entry {
    a = Job(name="A", state="failed", retries=3);
    b = Job(name="B", state="failed", retries=3);
    c = Job(name="C", state="waiting");
    d = Job(name="D", state="waiting");

    root ++> a;
    a +>:Parent(order=0):+> b;
    b +>:Parent(order=1):+> c;
    b +>:Parent(order=2):+> d;

    print("Before cascade, states:");
    print(f"  A={a.state} B={b.state} C={c.state} D={d.state}");

    cascade = Cascade();
    root spawn cascade;
    print(f"Cascade failed names: {cascade.failed_names}");

    print("After cascade, states:");
    print(f"  A={a.state} B={b.state} C={c.state} D={d.state}");

    print("Running reaper to confirm grandchildren resolved:");
    root spawn Propagate();
}

"""Sandbox skill shadow-mount: model read-only vs read-write mounts for
agent self-uninstall. The original issue hand-rolls traversal over the
host/container path graph to decide which mounts must be writable so the
agent can delete its own shadow skills. Here that policy becomes typed
edges and a walker that walks the mount tree, marks the shadow skills
directory as writable, and cascades the invalidation of any skill that
relies on it."""

node Skill {
    has name: str = "";
    has available: bool = True;
}

node HostPath {
    has path: str = "";
}

node ContainerPath {
    has path: str = "";
    has read_only: bool = True;
}

# A persistent skill lives on the host at HostPath and is materialized into
# the sandbox at ContainerPath.
edge MaterializedAt {
    has host_path: str = "";
    has container_path: str = "";
}

# Marks a ContainerPath as part of the sandbox-skills shadow tree.
edge SandboxSkill {}

walker AuditMounts {
    has fixes: list[str] = [];
    has visited: list[ContainerPath] = [];

    can start with Root entry {
        visit [-->];
    }

    # Walk every container mount. If its path is the shadow-skills root,
    # flip read_only to False so the agent can delete its own skills.
    can audit with ContainerPath entry {
        self.visited.append(here);
        is_shadow = "sandbox-skills" in here.path;
        if is_shadow {
            here.read_only = False;
            self.fixes.append(f"made {here.path} writable for autonomous uninstall");
            visit [-->];
        } else {
            visit [-->];
        }
    }

    # When we land on a host path, report its bound shadow mount state.
    can inspect with HostPath entry {
        print(f"host source: {here.path}");
        visit [-->] else { disengage; }
    }

    # When we land on a skill, report whether it is still active.
    can validate with Skill entry {
        status = "ACTIVE" if here.available else "REMOVED";
        print(f"[{status}] skill={here.name}");
        visit [-->] else { disengage; }
    }
}

with entry {
    # The shadow root that the issue calls out: was ro, must become rw.
    shadow_root = ContainerPath(
        path="/workspace/.openclaw/sandbox-skills/skills",
        read_only=True
    );
    # A second, unrelated ro mount to prove we don't flip it.
    config_root = ContainerPath(path="/etc/openclaw", read_only=True);

    # Host sources for two skills; one is autonomous (workspace-private).
    ws_skills_src = HostPath(path="/workspace/skills");
    builtin_src = HostPath(path="/opt/openclaw/skills");

    # Two skill nodes, one workspace-private and one built-in.
    auto_skill = Skill(name="my-skill", available=True);
    builtin_skill = Skill(name="core-linter", available=True);

    # Wire the graph: root -> shadow_root -> auto_skill (typed SandboxSkill)
    # root -> config_root -> builtin_skill (typed MaterializedAt)
    # host sources attach to the shadow/config roots via MaterializedAt.
    root ++> shadow_root +>:SandboxSkill:+> auto_skill;
    root ++> config_root +>:MaterializedAt(
        host_path="/opt/openclaw/skills",
        container_path="/etc/openclaw"
    ):+> builtin_skill;
    ws_skills_src +>:MaterializedAt(
        host_path="/workspace/skills",
        container_path="/workspace/.openclaw/sandbox-skills/skills"
    ):+> shadow_root;
    builtin_src +>:MaterializedAt(
        host_path="/opt/openclaw/skills",
        container_path="/etc/openclaw"
    ):+> config_root;

    print("--- before audit ---");
    print(f"shadow mount read_only={shadow_root.read_only} path={shadow_root.path}");
    print(f"config mount read_only={config_root.read_only} path={config_root.path}");

    AuditMounts() spawn root;

    print("--- after audit ---");
    print(f"shadow mount read_only={shadow_root.read_only} path={shadow_root.path}");
    print(f"config mount read_only={config_root.read_only} path={config_root.path}");
    print(f"auto_skill available={auto_skill.available}");
}

"""Rustscript admission pipeline: replace hand-rolled stage queues and AST recursion with typed edges and walkers."""

node DiagTarget {
    has span_id: str = "";
    has depth: int = 0;

    def headline() -> str {
        return "";
    }
}

node SourceUnit {
    has path: str = "";
    has byte_size: int = 0;
    has token_count: int = 0;
}

node AdmitStage {
    has name: str = "";
    has order: int = 0;
    has ok: bool = False;
}

node AstNode(DiagTarget) {
    has syntax_kind: str = "";

    override def headline() -> str {
        return self.syntax_kind;
    }
}

node SyntaxError(DiagTarget) {
    has reason: str = "";

    override def headline() -> str {
        return f"ERROR:{self.reason}";
    }
}

edge Inspects { }
edge FeedsInto { has note: str = ""; }
edge ChildOf { }

walker PipelineRunner {
    can start with Root entry {
        visit [->:Inspects:->] else { disengage; };
    }

    can preflight with SourceUnit entry {
        print(
            f"preflight {here.path}: {here.byte_size}B, "
            f"{here.token_count} tokens"
        );
        visit [->:FeedsInto:->] else { disengage; };
    }

    can run_stage with AdmitStage entry {
        verdict = "accept" if here.ok else "reject";
        print(f"  [{here.order}] {here.name}: {verdict}");
        visit [->:FeedsInto:->] else { disengage; };
    }
}

walker SyntaxPreorder {
    has max_depth: int = 8;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:ChildOf:->] else { disengage; };
    }

    can walk with AstNode | SyntaxError entry {
        cyclic = False;
        for sid in self.seen {
            if sid == here.span_id {
                cyclic = True;
            }
        }
        if cyclic {
            print(f"cycle guard: {here.headline()} @{here.span_id}");
            disengage;
        }
        self.seen.append(here.span_id);
        if here.depth > self.max_depth {
            print(
                f"depth cap d={here.depth}: "
