"""Assembly call-target traversal: resolve external member references against
selected assembly participants using a typed catalog correspondence plan."""

node LibraryBodyIndex {
    has name: str = "";
    has descriptor: str = "";
    has is_active: bool = True;
}

node SelectedParticipant {
    has name: str = "";
    has is_available: bool = True;
    has is_ambiguous: bool = False;
    has is_inactive_shadow: bool = False;
}

node ExternalMemberRef {
    has member_name: str = "";
    has signature_kind: str = "declaring";
    has call_site_id: str = "";
}

node Definition {
    has name: str = "";
    has matches: bool = True;
}

node MissingMember {
    has reason: str = "member-missing";
}

node CorrespondencePlan {
    has is_frozen: bool = False;
    has requests: list[str] = [];
}

edge Retains {
    has role: str = "selected";
}

edge Targets {
    has kind: str = "call-target";
}

edge ResolvesTo {
    has outcome: str = "resolved-definition";
}

walker CallGraphProjection {
    has outcomes: list[str] = [];
    has plan_frozen: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can inspect_index with LibraryBodyIndex entry {
        print(f"Assembly index: {here.name} ({here.descriptor})");
        if not here.is_active {
            disengage;
        }
        visit [-->];
    }

    can select_participants with SelectedParticipant entry {
        if here.is_ambiguous or here.is_inactive_shadow {
            print(f"  skip {here.name}: ambiguous/shadow");
            visit [-->];
        }
        if not here.is_available {
            self.outcomes.append("candidate-unavailable");
            print(f"  unavailable: {here.name}");
            visit [-->];
        }
        visit [-->];
    }

    can plan_correspondence with CorrespondencePlan entry {
        if not here.is_frozen {
            self.plan_frozen = False;
            visit [-->];
        } else {
            self.plan_frozen = True;
            print(f"Plan frozen with {len(here.requests)} requests");
            visit [-->];
        }
    }

    can resolve_member_refs with ExternalMemberRef entry {
        if not self.plan_frozen {
            self.outcomes.append("correspondence-incomplete");
            print(f"  {here.member_name}: plan not frozen");
            visit [-->];
        }
        physical_site = here.call_site_id;
        print(f"  call-site {physical_site} -> {here.member_name}");
        visit [-->];
    }

    can collect_outcomes with Definition entry {
        self.outcomes.append("resolved-definition");
        print(f"  resolved: {here.name}");
        visit [-->];
    }

    can collect_missing with MissingMember entry {
        self.outcomes.append(here.reason);
        print(f"  outcome: {here.reason}");
        visit [-->];
    }
}

with entry {
    body_index = LibraryBodyIndex(
        name="App.Assembly",
        descriptor="app,v1.0",
        is_active=True
    );
    platform = SelectedParticipant(name="Platform");
    package = SelectedParticipant(name="Package");
    shadow = SelectedParticipant(
        name="Shadow",
        is_ambiguous=True
    );
    missing_platform = SelectedParticipant(
        name="EmptyPlatform",
        is_available=False
    );
    plan = CorrespondencePlan(
        is_frozen=True,
        requests=["declaring", "parameter", "return", "generic", "custom-modifier"]
    );
    member_ref = ExternalMemberRef(
        member_name="Helper.WriteLine",
        signature_kind="declaring",
        call_site_id="site-0x42"
    );
    defn = Definition(name="Helper.WriteLine", matches=True);
    missing = MissingMember(reason="member-missing");

    root +>:Retains(role="owner"):+> body_index;
    body_index +>:Retains(role="selected"):+> platform;
    body_index +>:Retains(role="selected"):+> package;
    body_index +>:Retains(role="selected"):+> shadow;
    body_index +>:Retains(role="selected"):+> missing_platform;
    body_index +>:Retains(role="manifest"):+> plan;
    body_index +>:Targets(kind="call-target"):+> member_ref;
    member_ref +>:ResolvesTo(outcome="resolved-definition"):+> defn;
    platform +>:ResolvesTo(outcome="member-missing"):+> missing;

    proj = CallGraphProjection();
    root spawn proj;
    print(f"Outcomes: {proj.outcomes}");
}

"""Bounded transitive authority revocation with cycle and incomplete evidence handling."""

node Origin {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has origin_id: str = "";
    has snapshot_id: str = "";
    has scope: str = "";
    has fence: int = 0;
    has epoch: int = 0;
    has revoked: bool = False;
}

node Grant {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has grant_id: str = "";
    has origin_id: str = "";
    has snapshot_id: str = "";
    has scope: str = "";
    has fence: int = 0;
    has epoch: int = 0;
    has revision: int = 0;
    has evidence_complete: bool = True;
    has current: bool = True;
    has restored: bool = True;
    has suppressed: bool = False;
    has depth: int = 0;
}

edge Contains {
    has snapshot_id: str = "";
}

edge Influences {
    has snapshot_id: str = "";
    has relation: str = "";
}

walker RevocationAuditor {
    has operation_id: str = "op-686";
    has snapshot_id: str = "snapshot-7";
    has scope: str = "production";
    has fence: int = 7;
    has epoch: int = 4;
    has max_nodes: int = 8;
    has max_edges: int = 16;
    has max_depth: int = 8;
    has max_work: int = 32;
    has visited: list[str] = [];
    has suppressed: list[str] = [];
    has blocked: list[str] = [];
    has frontier: list[str] = [];
    has omissions: list[str] = [];
    has visited_count: int = 0;
    has edge_count: int = 0;
    has work_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_origin with Origin entry {
        if here.revoked {
            if here.available and here.snapshot_id == self.snapshot_id and here.scope == self.scope and here.fence == self.fence and here.epoch == self.epoch {
                if self.edge_count >= self.max_edges or self.work_count >= self.max_work {
                    self.frontier.append("origin:" + here.origin_id);
                    self.blocked.append("origin:" + here.origin_id + ":budget-bound");
                } else {
                    self.edge_count += 1;
                    self.work_count += 1;
                    visit [->:Influences:->] else { disengage; }
                }
            } else {
                self.blocked.append("origin:" + here.origin_id + ":evidence-unavailable");
            }
        }
    }

    can inspect_grant with Grant entry {
        if here.grant_id in self.visited {
            cycle_mark = here.grant_id + ":cycle-seen";
            if cycle_mark not in self.omissions {
                self.omissions.append(cycle_mark);
            }
        } else {
            if self.visited_count >= self.max_nodes {
                self.frontier.append(here.grant_id);
                self.blocked.append(here.grant_id + ":node-bound");
            } elif here.depth > self.max_depth {
                self.frontier.append(here.grant_id);
                self.blocked.append(here.grant_id + ":depth-bound");
            } else {
                self.visited.append(here.grant_id);
                self.visited_count += 1;
                if not here.evidence_complete {
                    self.frontier.append(here.grant_id);
                    self.blocked.append(here.grant_id + ":incomplete-evidence");
                } elif not here.current {
                    self.frontier.append(here.grant_id);
                    self.blocked.append(here.grant_id + ":stale-revision");
                } elif here.snapshot_id != self.snapshot_id or here.origin_id == "" or here.scope != self.scope or here.fence != self.fence or here.epoch != self.epoch {
                    self.frontier.append(here.grant_id);
                    self.blocked.append(here.grant_id + ":identity-mismatch");
                } else {
                    here.suppressed = True;
                    here.restored = False;
                    self.suppressed.append(here.grant_id);
                    if self.edge_count >= self.max_edges or self.work_count >= self.max_work {
                        self.frontier.append(here.grant_id);
                        self.blocked.append(here.grant_id + ":budget-bound");
                    } else {
                        self.edge_count += 1;
                        self.work_count += 1;
                        visit [->:Influences:->] else { disengage; }
                    }
                }
            }
        }
    }

    can summarize with Root exit {
        print(f"{self.operation_id}: suppressed={self.suppressed}");
        print(f"blocked={self.blocked}, frontier={self.frontier}, omissions={self.omissions}");
        report self.suppressed;
    }
}

with entry {
    origin_a = Origin(title="Revoked origin", year=2024, origin_id="origin-A", snapshot_id="snapshot-7", scope="production", fence=7, epoch=4, revoked=True);
    origin_b = Origin(title="Unrelated origin", year=2024, origin_id="origin-B", snapshot_id="snapshot-7", scope="production", fence=7, epoch=4, revoked=False);

    grant_a = Grant(title="Root grant", year=2024, grant_id="grant-A", origin_id="origin-A", snapshot_id="snapshot-7", scope="production", fence=7, epoch=4, revision=10, depth=1);
    grant_b = Grant(title="Dependent grant", year=2024, grant_id="grant-B", origin_id="origin-A", snapshot_id="snapshot-7", scope="production", fence=7, epoch=4, revision=11, depth=2);
    grant_c = Grant(title="Transitive grant", year=2024, grant_id="grant-C", origin_id="origin-A", snapshot_id="snapshot-7", scope="production", fence=7, epoch=4, revision=12, depth=3);
    grant_unknown = Grant(title="Unknown evidence", year=2024, grant_id="grant-D", origin_id="origin-A", snapshot_id="snapshot-7", scope="production", fence=7, epoch=4, revision=13, evidence_complete=False, depth=2);
    grant_unrelated = Grant(title="Unrelated valid grant", year=2024, grant_id="grant-U", origin_id="origin-B", snapshot_id="snapshot-7", scope="production", fence=7, epoch=4, revision=20, depth=1);

    root +>:Contains(snapshot_id="snapshot-7"):+> origin_a;
    root +>:Contains(snapshot_id="snapshot-7"):+> origin_b;
    origin_a +>:Influences(snapshot_id="snapshot-7", relation="origin-grant"):+> grant_a;
    grant_a +>:Influences(snapshot_id="snapshot-7", relation="dependent"):+> grant_b;
    grant_b +>:Influences(snapshot_id="snapshot-7", relation="dependent"):+> grant_c;
    grant_c +>:Influences(snapshot_id="snapshot-7", relation="cycle"):+> grant_a;
    grant_a +>:Influences(snapshot_id="snapshot-7", relation="unknown-evidence"):+> grant_unknown;
    origin_b +>:Influences(snapshot_id="snapshot-7", relation="unrelated"):+> grant_unrelated;

    root spawn RevocationAuditor();
}

"""Streaming group export: model the constant-memory promise the issue describes.

The naive implementation hydrates every AuditFile's full ``raw_text`` payload
(treated here as a heavy blob) for every streamed chunk, even though the
serializer only ever reads the metadata columns. This demo walks the same
graph two ways:

  * ``NaiveExporter`` pulls every connected ``AuditFile`` node in one shot
    and reads both metadata and the heavy blob together — the OOM shape.
  * ``LeanExporter`` walks the same graph but only ever touches the
    metadata fields, mirroring the fix where ``raw_text`` is deferred and
    the heavy column is never materialized.

Both walkers still traverse the same typed edges (``BelongsToGroup`` and
``MentionedIn``) so the graph structure is preserved; what changes is
whether the heavy blob is hydrated during the walk.
"""

node Group {
    has name: str = "";
    has slug: str = "";
}

node AuditFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    # The heavy column that the streaming export hydrates by mistake.
    # In the real codebase this is a TextField up to 50 MB; we model it
    # as a string the walker must explicitly choose to read.
    has raw_text: str = "";
}

node AuditEvent {
    has label: str = "";
    # Additional heavy JSON blobs on events the issue also flags.
    has raw_event: str = "";
    has raw_kind: str = "";
    has raw_context: str = "";
}

edge BelongsToGroup {
    has role: str = "source";
}

edge MentionedIn {
    has role: str = "evidence";
}

# Naive walker: visits every AuditFile reachable from the group and
# reads BOTH metadata and the heavy blob on every node. This is the
# streaming-export shape: chunk_size=2000 fully materialized rows, each
# carrying raw_text, blowing the constant-memory promise.
walker NaiveExporter {
    can start with Root entry {
        visit [-->];
    }

    can ship with Group entry {
        print(f"[naive] group {here.name} ({here.slug})");
        visit [->:BelongsToGroup:->];
    }

    can serialize with AuditFile entry {
        # The serializer's documented contract only reads metadata, but
        # the queryset never deferred raw_text, so it is resident anyway.
        meta = f"{here.title} ({here.year}) available={here.available}";
        heavy = here.raw_text;
        print(f"[naive]   AuditFile meta={meta} heavy_len={len(heavy)}");
        visit [->:MentionedIn:->];
    }

    can note with AuditEvent entry {
        heavy = here.raw_event + here.raw_kind + here.raw_context;
        print(f"[naive]   AuditEvent {here.label} heavy_len={len(heavy)}");
    }
}

# Lean walker: traverses the exact same graph and typed edges, but never
# reads the heavy blob — the fix the issue recommends. Same walk, no
# OOM-shaped hydration.
walker LeanExporter {
    can start with Root entry {
        visit [-->];
    }

    can ship with Group entry {
        print(f"[lean] group {here.name} ({here.slug})");
        visit [->:BelongsToGroup:->];
    }

    can serialize with AuditFile entry {
        # Only metadata columns, the way agent_source_row() actually reads.
        meta = f"{here.title} ({here.year}) available={here.available}";
        print(f"[lean]   AuditFile meta={meta} heavy=DEFERRED");
        visit [->:MentionedIn:->];
    }

    can note with AuditEvent entry {
        print(f"[lean]   AuditEvent {here.label} heavy=DEFERRED");
    }
}

with entry {
    # Build a small group with a couple of AuditFiles and the evidence
    # events that the delivery_artifact section prefetches.
    g = Group(name="Investigations", slug="investigations");

    f1 = AuditFile(
        title="c2-pcap-2024-01.jsonl",
        year=2024,
        available=True,
        raw_text="x" * 5_000_000
    );
    f2 = AuditFile(
        title="edr-dump-2024-02.jsonl",
        year=2024,
        available=True,
        raw_text="y" * 5_000_000
    );

    e1 = AuditEvent(
        label="process.create",
        raw_event="a" * 200_000,
        raw_kind="b" * 200_000,
        raw_context="c" * 200_000
    );
    e2 = AuditEvent(
        label="network.dns",
        raw_event="d" * 200_000,
        raw_kind="e" * 200_000,
        raw_context="f" * 200_000
    );

    # Wire the graph the way the streaming export would: a group owns
    # audit files (the source section), and files are linked to the
    # evidence events the delivery_artifact section prefetches.
    root +>:BelongsToGroup:+> g;
    g +>:BelongsToGroup(role="source"):+> f1;
    g +>:BelongsToGroup(role="source"):+> f2;
    f1 +>:MentionedIn(role="evidence"):+> e1;
    f2 +>:MentionedIn(role="evidence"):+> e2;

    print("--- naive exporter (hydrates raw_text / raw_event / raw_kind / raw_context) ---");
    root spawn NaiveExporter();

    print("--- lean exporter (defers the heavy blobs) ---");
    root spawn LeanExporter();
}

"""Mutual friendships between houses with bidirectional buddy edges.

Models houses as graph nodes and connects pairs with buddy edges that
point both ways (created in a single statement). Two greeter walkers are
spawned, one per end of a buddy link, and each must reach the other
using only forward traversal. An explicit guard set prevents the
walkers from oscillating back and forth forever.
"""

node House {
    has name: str = "";
    has visited: set[str] = set();
}

edge Buddy {
    has since: int = 0;
}

walker Greeter {
    has house_name: str = "";
    has target: str = "";
    has reached: bool = False;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can travel with House entry {
        # Mark this house as seen so we never bounce back.
        here.visited.add(self.house_name);
        self.log.append(f"greeter from {self.house_name} at {here.name}");

        if here.name == self.target {
            self.reached = True;
            print(f"[{self.house_name}] reached buddy {self.target} -> {self.log}");
            disengage;
        }

        # Only walk buddy edges; skip houses already visited on this route.
        buddy = [here ->:Buddy:->];
        if buddy and buddy[0].name not in here.visited {
            visit buddy;
        } else {
            print(f"[{self.house_name}] no fresh buddy edge from {here.name}");
            disengage;
        }
    }
}

with entry {
    # Two houses connected by a buddy edge that points BOTH ways
    # in a single statement.
    alice = House(name="Alice");
    bob = House(name="Bob");
    alice +>:Buddy(since=2021):+> bob;
    bob +>:Buddy(since=2021):+> alice;
    root ++> alice ++> bob;

    # Spawn one greeter at each end of the buddy link.
    g_alice = Greeter(house_name="Alice", target="Bob");
    g_bob = Greeter(house_name="Bob", target="Alice");

    alice spawn g_alice;
    bob spawn g_bob;
}

"""Order auditor demonstrating skip vs. halt flavors of early return.

Invalid orders are skipped (audit continues); fraud-flagged orders halt
the entire walk immediately via ``disengage``.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Order audit begin");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged on '{here.title}' (${here.amount}) — disengaging");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] invalid order '{here.title}' — continuing");
            visit [-->];
            return;
        }
        print(f"[OK]   '{here.title}' amount=${here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(title="A-1001", amount=120.50, valid=True)
        ++> Order(title="A-1002", amount=0.00, valid=False)
        ++> Order(title="A-1003", amount=89.99, valid=True)
        ++> Order(title="A-1004", amount=9999.00, valid=True, fraud=True)
        ++> Order(title="A-1005", amount=45.00, valid=True);
    root spawn OrderAuditor();
}

"""Bug tracker: ticket nodes connected to a project, captured and inspected in one go."""

node Ticket {
