"""Order auditor: skip invalid orders and halt the walk on fraud flags."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has skipped: int = 0;

    can start with Root entry {
        print("Order audit started");
        visit [-->];
    }

    can review with Order entry {
        if here.fraud {
            print(f"[HALT] amount={here.amount} flagged for fraud — stopping audit");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] amount={here.amount} invalid — continuing");
                self.skipped += 1;
                visit [-->];
            } else {
                print(f"[AUDIT] amount={here.amount} valid — approved");
                self.audited += 1;
                visit [-->];
            }
        }
    }
}

with entry {
    root ++> Order(amount=120.0, valid=True, fraud=False)
        ++> Order(amount=45.0, valid=False, fraud=False)
