"""Build system cycle detector.

Modules list the modules they depend on. A circular dependency exists
when you can walk dependencies from a module back to itself. This
program builds a deliberately broken module graph and reports the
exact cycle path so a build system can refuse to rebuild.
"""

node Module {
    has name: str = "";
}

edge DependsOn {
    has reason: str = "import";
}

walker CycleHunter {
    has trail: list = [];
    has on_trail: set = set();
    has found: list = [];

    can start with Root entry {
        # Seed: visit every top-level module, then follow typed edges.
        visit [-->];
    }

    can descend with Module entry {
        # Cycle already reported - stop everything.
        if len(self.found) > 0 {
            disengage;
        }
        # Re-visit a node already on the current trail -> cycle found.
        if here.name in self.on_trail {
            cut = self.trail.index(here.name);
            cycle = self.trail[cut:] + [here.name];
            self.found = cycle;
            print(f"CYCLE DETECTED: {' -> '.join(self.found)}");
            disengage;
        }
        # Mark and descend into dependencies.
        self.on_trail.add(here.name);
        self.trail = self.trail + [here.name];
        # Step into every dependency in turn. Walker recurses one node
        # at a time; using [->:DependsOn:->] enqueues all and can loop.
        deps = [->:DependsOn:->];
        if len(deps) > 0 {
            # Pop one dep at a time so `can back` can clean up between visits.
            first = deps.pop(0);
            visit [first];
        } else {
            # Dead end: clean up trail and stop.
            self.trail = self.trail[:-1];
            self.on_trail.discard(here.name);
            disengage;
        }
    }

    can back with Module entry {
        # No-op: cleanup happens on dead-end path in `descend`.
        # Re-define without walking further to avoid repeated re-entry.
    }
}

with entry {
    app = Module(name="app");
    ui = Module(name="ui");
    core = Module(name="core");
    utils = Module(name="utils");
    net = Module(name="net");

    # Build the graph (parent links + typed dependency edges).
    root ++> app ++> ui ++> core ++> utils ++> net;
    app +>:DependsOn(reason="render"):+> ui;
    ui +>:DependsOn(reason="data"):+> core;
    core +>:DependsOn(reason="helpers"):+> utils;
    utils +>:DependsOn(reason="http"):+> net;
    # The deliberate cycle: net -> ui -> net.
    net +>:DependsOn(reason="events"):+> ui;

    print("=== CycleHunter ===");
    hunter = CycleHunter();
    root spawn hunter;
    if len(hunter.found) > 0 {
        print(f"Build aborted: cycle {' -> '.join(hunter.found)}");
    } else {
        print("No cycles found.");
    }
}

