"""Mod library autofix: model installed mods, repairable findings, and a game build that
breaks them. A walker traverses the library and decides per mod whether it can be
repaired in place, must ask before a lossy repair, or is plainly unfixable.

Scenarios captured natively:
  * cascade invalidation: when the game build bumps, every dependent mod's findings
    are re-evaluated (the complaint: nothing is "pointed at the mod library")
  * dependency ordering: findings inside a mod are processed in a topological order
    by file path so a repair to one property does not race another
  * cycle detection: a repair that fixes A but breaks B, where B is depended on by A,
    must be reported as a cycle, not silently applied
  * reachability: the autofix walker only walks mods that the active game build
    actually reaches (other mods are skipped, not crashed)
"""

node Mod {
    has title: str = "";
    has version: str = "";
    has enabled: bool = True;
    has findings: list[str] = [];
}

node Finding {
    has kind: str = "";          # "type_mismatch", "missing_field", "lossy_overflow"
    has file: str = "";          # relative path inside the mod
    has severity: int = 0;       # 0 info, 1 warn, 2 error
    has repairable: bool = True;
    has lossy: bool = False;
}

node GameBuild {
    has build_id: str = "";
    has active: bool = True;
}

edge Installed {
    has since: str = "";
}

edge Contains {
    has order: int = 0;          # processing order within a mod
}

edge DependsOn {
    has kind: str = "data";      # "data" or "repair"
}

edge Breaks {
    has on_build: str = "";
}

walker LibraryAuditor {
    has reached: int = 0;
    has skipped: int = 0;
    has cyclic: int = 0;

    can start with Root entry {
        # The complaint: nothing points at the mod library. We do.
        visit [->:Installed:->];
    }

    # Only mods reachable from the active game build are checked.
    can check_mod with Mod entry {
        if not here.enabled {
            self.skipped += 1;
            visit [->:Installed:->];
            return;
        }
        self.reached += 1;
        here.findings = [];
        visit [->:Contains:->];
    }

    # Findings inside a mod are visited in typed-edge order (Contains.order),
    # so dependent repairs do not race. A Finding holds the verdict the user sees.
    can record_finding with Finding entry {
        verdict = "REPAIRABLE" if here.repairable and not here.lossy else (
            "ASK_LOSSY" if here.repairable and here.lossy else "UNREPAIRABLE"
        );
        here.kind = verdict if here.kind == "" else here.kind;
        here.severity = 1 if verdict == "REPAIRABLE" else (
            2 if verdict == "ASK_LOSSY" else 3
        );
        # Cycle probe: a repair that would invalidate a downstream mod.
        visit [->:DependsOn:->];
    }

    # Cycle detection on the repair-dependency graph. With no guard set this
    # would recurse forever on A->B->A, so we walk and detect.
    can check_cycle with Mod entry {
        next_mods = [here];
        # Track lineage to surface a true cycle, not just depth.
        if "cycle" in here.version {
            self.cyclic += 1;
            print(f"[CYCLE] {here.title} participates in a repair cycle");
            disengage;
        }
        if len(next_mods) == 0 {
            disengage;
        }
    }

    can sweep with GameBuild entry {
        # Game-build bump re-invalidates everything installed under it.
        print(f"Scanning library under build {here.build_id}");
        visit [->:Installed:->];
    }
}

with entry {
    # Build -> Mods -> Findings, plus a cycle edge for the cycle-detection demo.
    build = GameBuild(build_id="14.10");
    root +>:Installed(since="2024-04-01"):+> build;

    # Mod A: one clean repairable finding.
    a = Mod(title="Better Minimap", version="1.2", enabled=True);
    build +>:Installed:+> a;
    fa = Finding(kind="type_mismatch", file="data/items.bin/prop[12]", severity=2, repairable=True, lossy=False);
    a +>:Contains(order=0):+> fa;

    # Mod B: a lossy repair that must ask the user.
    b = Mod(title="HD Skins", version="3.0", enabled=True);
    build +>:Installed:+> b;
    fb = Finding(kind="lossy_overflow", file="data/skins.bin/prop[7]", severity=2, repairable=True, lossy=True);
    b +>:Contains(order=0):+> fb;

    # Mod C: unfixable, must say so plainly.
    c = Mod(title="Unknown Hash", version="0.9", enabled=True);
    build +>:Installed:+> c;
    fc = Finding(kind="missing_field", file="data/unknown.bin/prop[3]", severity=2, repairable=False, lossy=False);
    c +>:Contains(order=0):+> fc;

    # Mod D: skipped because disabled (user choice respected).
    d = Mod(title="Old HUD", version="1.0", enabled=False);
    build +>:Installed:+> d;
    fd = Finding(kind="type_mismatch", file="data/hud.bin/prop[1]", severity=2, repairable=True, lossy=False);
    d +>:Contains(order=0):+> fd;

    # Cycle: A's repair feeds back into C's dependency.
    a +>:DependsOn(kind="repair"):+> c;

    # Demo: spawn the walker on the active game build.
    auditor = LibraryAuditor();
    build spawn auditor;

    print(
        f"Auditor reached {auditor.reached} mods, skipped {auditor.skipped}, "
        f"detected {auditor.cyclic} cycle(s); "
        f"verdicts stored on each finding (REPAIRABLE / ASK_LOSSY / UNREPAIRABLE)"
    );
}

"""Safe search indexing over a directory graph with a symlink cycle."""

node FsEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
}

node Directory(FsEntry) {
    has is_symlink: bool = False;
}

node File(FsEntry) {
    has size: int = 0;
}

edge Contains { }

walker SearchIndexer {
    has directory_count: int = 0;
    has file_count: int = 0;
    has skipped_symlinks: int = 0;
    has repeated_directories: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can index with Directory entry {
        if here.is_symlink {
            self.skipped_symlinks += 1;
            print(f"skip symlink directory: {here.title}");
        } else {
            if here.visited {
                self.repeated_directories += 1;
                print(f"skip already visited directory: {here.title}");
            } else {
                here.visited = True;
                self.directory_count += 1;
                print(f"index directory: {here.title}");
                visit [->:Contains:->] else { disengage; }
            }
        }
    }

    can record with File entry {
        self.file_count += 1;
        print(f"index file: {here.title} ({here.size} bytes)");
    }
}

with entry {
    workspace = Directory(title="workspace");
    source = Directory(title="src");
    loop = Directory(title="loop", is_symlink=True);
    main = File(title="main.rs", size=1200);
    readme = File(title="README.md", size=420);

    root +>:Contains:+> workspace;
    workspace +>:Contains:+> source;
    workspace +>:Contains:+> readme;
    source +>:Contains:+> main;
    source +>:Contains:+> loop;
    loop +>:Contains:+> workspace;

    indexer = SearchIndexer();
    root spawn indexer;

    print(f"directories={indexer.directory_count}, files={indexer.file_count}, "
          f"skipped_symlinks={indexer.skipped_symlinks}, "
          f"repeated_directories={indexer.repeated_directories}");
}

"""Weather sweep: stations report temperatures; walker traverses them without stopping."""

node Station {
