"""Hermes Mac-control execution context propagation.

Models the essential scenario from electricsheephq/evaos-desktop-bridge #320:
a verified broker-signed execution context must survive traversal from the
authenticated gateway ingress, across WebSocket handling, async dispatcher,
raw threading.Thread seams, and into a Mac-control tool call — without ever
being replaced by caller-supplied context.

Walker ContextPropagator enters the gateway, walks through every stage of
the request pipeline (ingress -> session -> dispatcher -> raw thread seam
-> tool executor), verifies the context at each typed boundary, and refuses
to forward anything that does not match the trusted, broker-issued payload.
A second walker ContextAuditor replays the same traversal asking only
whether the ambient context remained identical at every step.
"""

node GatewayIngress {
    has ingress_id: str = "";
    has pinned_verify_key: str = "broker-pinned-pubkey";
    has verified_context: str = "";
    has verified_tool_call_id: str = "";
    has trusted: bool = True;
}

node Session {
    has session_id: str = "";
    has ambient_context: str = "";
    has tool_call_id: str = "";
}

node Dispatcher {
    has dispatcher_name: str = "";
    has copy_context_applied: bool = True;
}

node RawThreadSeam {
    has thread_name: str = "";
    has inherited_context: bool = False;
    has bind_reset_applied: bool = False;
    has ambient_context: str = "";
}

node MacControlTool {
    has tool_name: str = "";
    has received_context: str = "";
    has received_tool_call_id: str = "";
    has is_mac_control: bool = True;
}

edge Authenticated {
    has verified_at: str = "";
}

edge SessionBound {
    has bound_at: str = "";
}

edge Dispatched {
    has dispatch_id: str = "";
}

edge RawThreadFork {
    has fork_reason: str = "";
}

edge ToolCall {
    has call_seq: int = 0;
}

walker ContextPropagator {
    has expected_context: str = "broker-ctx-MAC-CTRL-v1";
    has expected_tool_call_id: str = "tcid-7f3a";
    has failures: int = 0;

    can start with Root entry {
        print(f"[propagator] entering gateway with expected context={self.expected_context}");
        visit [-->];
    }

    can verify_ingress with GatewayIngress entry {
        ok = here.trusted
            and here.verified_context == self.expected_context
            and here.verified_tool_call_id == self.expected_tool_call_id;
        if not ok {
            self.failures += 1;
            print(f"[propagator] REJECT at ingress {here.ingress_id}: tampered/wrong payload");
            disengage;
        }
        print(f"[propagator] ingress {here.ingress_id} verified context OK");
        visit [->:Authenticated:->];
    }

    can propagate_session with Session entry {
        if here.ambient_context != self.expected_context
            or here.tool_call_id != self.expected_tool_call_id {
            self.failures += 1;
            print(f"[propagator] REJECT at session {here.session_id}: context mutated");
            disengage;
        }
        print(f"[propagator] session {here.session_id} carries verified context");
        visit [->:SessionBound:->];
    }

    can propagate_dispatcher with Dispatcher entry {
        if not here.copy_context_applied {
            self.failures += 1;
            print(f"[propagator] REJECT at dispatcher {here.dispatcher_name}: copy_context missing");
            disengage;
        }
        print(f"[propagator] dispatcher {here.dispatcher_name} applied copy_context");
        visit [->:Dispatched:->];
    }

    can bind_raw_thread with RawThreadSeam entry {
        if not here.bind_reset_applied {
            self.failures += 1;
            print(f"[propagator] REJECT at raw thread {here.thread_name}: explicit bind/reset missing");
            disengage;
        }
        if not here.inherited_context {
            self.failures += 1;
            print(f"[propagator] REJECT at raw thread {here.thread_name}: context lost across seam");
            disengage;
        }
        if here.ambient_context != self.expected_context {
            self.failures += 1;
            print(f"[propagator] REJECT at raw thread {here.thread_name}: wrong ambient context");
            disengage;
        }
        print(f"[propagator] raw thread {here.thread_name} bound + reset verified context");
        visit [->:RawThreadFork:->];
    }

    can forward_to_tool with MacControlTool entry {
        if not here.is_mac_control {
            self.failures += 1;
            print(f"[propagator] REJECT tool {here.tool_name}: not Mac-control");
            disengage;
        }
        if here.received_context != self.expected_context
            or here.received_tool_call_id != self.expected_tool_call_id {
            self.failures += 1;
            print(f"[propagator] REJECT tool {here.tool_name}: payload mismatch");
            disengage;
        }
        print(f"[propagator] forwarded verified context into tool {here.tool_name}");
    }
}

walker ContextAuditor {
    has expected_context: str = "broker-ctx-MAC-CTRL-v1";
    has expected_tool_call_id: str = "tcid-7f3a";
    has mismatched: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_session with Session entry {
        if here.ambient_context != self.expected_context {
            self.mismatched += 1;
        }
        visit [->:SessionBound:->];
    }

    can audit_dispatcher with Dispatcher entry {
        if not here.copy_context_applied {
            self.mismatched += 1;
        }
        visit [->:Dispatched:->];
    }

    can audit_raw with RawThreadSeam entry {
        if here.ambient_context != self.expected_context
            or not here.inherited_context {
            self.mismatched += 1;
        }
        visit [->:RawThreadFork:->];
    }

    can audit_tool with MacControlTool entry {
        if here.received_context != self.expected_context
            or here.received_tool_call_id != self.expected_tool_call_id {
            self.mismatched += 1;
        }
    }
}

with entry {
    gateway = GatewayIngress(
        ingress_id="gw-01",
        verified_context="broker-ctx-MAC-CTRL-v1",
        verified_tool_call_id="tcid-7f3a",
        trusted=True
    );
    s1 = Session(
        session_id="sess-A",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    s2 = Session(
        session_id="sess-B",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    disp = Dispatcher(dispatcher_name="ws-dispatcher", copy_context_applied=True);
    raw = RawThreadSeam(
        thread_name="agent-build-thread-1",
        inherited_context=True,
        bind_reset_applied=True,
        ambient_context="broker-ctx-MAC-CTRL-v1"
    );
    tool = MacControlTool(
        tool_name="open_app",
        received_context="broker-ctx-MAC-CTRL-v1",
        received_tool_call_id="tcid-7f3a",
        is_mac_control=True
    );

    gateway +>:Authenticated(verified_at="2024-01-01T00:00:00Z"):+> s1;
    s1 +>:SessionBound(bound_at="2024-01-01T00:00:01Z"):+> disp;
    disp +>:Dispatched(dispatch_id="d-9"):+> raw;
    raw +>:RawThreadFork(fork_reason="agent-build"):+> tool;

    root ++> gateway;

    root spawn ContextPropagator();
    root spawn ContextAuditor();
}

"""Guestbook walkers: HTTP body becomes walker fields, walker reports become the HTTP response.

Two public walkers exposed over `jac start`:
  - SignGuestbook: takes `name` and `message` fields; appends an entry.
  - ReadGuestbook: reads back the latest entries from a guestbook node.
The standalone demo wires a Guestbook node to root and spawns both walkers
so the same code is exercised without an HTTP transport.
"""

node Guestbook {
    has title: str = "Guestbook";
    has entries: list = [];
}

node Entry {
    has name: str = "";
    has message: str = "";
    has signed_at: str = "";
}

walker SignGuestbook {
    has name: str = "";
    has message: str = "";

    can start with Root entry {
        visit [-->];
    }

    can sign with Guestbook entry {
        stamp = f"{self.name} says: {self.message}";
        here.entries.append(stamp);
        new_entry = Entry(name=self.name, message=self.message, signed_at=stamp);
        here ++> new_entry;
        report {
            "status": "signed",
            "guestbook": here.title,
            "entry": stamp,
            "total": len(here.entries),
        };
        visit [-->] else { disengage; }
    }
}

walker ReadGuestbook {
    has limit: int = 5;

    can start with Root entry {
        visit [-->];
    }

    can read with Guestbook entry {
        window = here.entries[-self.limit:] if self.limit > 0 else here.entries;
        report {
            "guestbook": here.title,
            "count": len(window),
            "entries": window,
        };
        visit [-->] else { disengage; }
    }
}

with entry {
    book = Guestbook(title="Launch Party");
    root ++> book;

    root spawn SignGuestbook(name="Ada", message="Loved the demo!");
    root spawn SignGuestbook(name="Linus", message="Ship it.");
    root spawn SignGuestbook(name="Grace", message="Hello from the other side.");

    reader = ReadGuestbook(limit=10);
    root spawn reader;
    print(f"Guestbook '{book.title}' has {len(book.entries)} entries:");
    for line in book.entries {
        print(f"  - {line}");
    }
}

A maintainer on the project NathanZK/ChessEcho (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #180: Add Keychain-backed Copilot authentication for trusted-local workers

## Problem

The disposable Phase 1 canary in #176 reached real planner execution through the reviewed trusted-local provider, but the controlled worker process exited with `No authentication information found.` The provider correctly excluded ambient credentials, independently observed and finalized the failed result, and stopped at `PAUSED` without retry or recovery.

Subsequent source and IAM investigation established the actor boundary:

```text
UNTRUSTED WORKER
  -> dedicated local worktree
  -> local implementation and commit
  -> Copilot service authentication only
  -> no GitHub repository authority

TRUSTED RUNTIME
  -> independent validation
  -> exact validated SHA publication
  -> draft PR creation and reconciliation
  -> GitHub publication authority
```

A dedicated fine-grained PAT has now been provisioned outside the repository with account permission `Copilot Requests`, Public repositories access, and no repository, Issues, Pull Requests, Actions, or workflow mutation permission. This issue adds only the explicit trusted-host transport for that worker capability.

The central invariants are:

```text
Copilot authentication capability != GitHub repository authority
Worker != GitHub publication actor
```

## Required contract

### Explicit Keychain source

Add one deterministic macOS Keychain-backed credential source owned by the reviewed Phase 1 host/provider boundary.

The implementation must:

- use a fixed, documented ChessEcho-specific Keychain service name and account name;
- query only that exact service/account pair;
- accept only the expected Copilot worker credential type and bounded shape;
- be absent by default and fail before worker launch when unavailable;
- reject missing, malformed, unreadable, replaced, ambiguous, or wrong-identity sources;
- never search arbitrary Keychain entries;
- never fall back to the operator's `gh` authentication, `GH_TOKEN`, `GITHUB_TOKEN`, Copilot interactive store, `~/.config/gh`, `~/.copilot`, SSH, signing material, or other credential stores;
- use a narrow injectable Keychain lookup seam for tests without weakening production validation.

The Keychain secret is independently provisioned authority. Source ownership/type/access policy can prove handling but cannot by itself prove the complete fine-grained PAT permission set. Document the provisioning provenance and GitHub introspection limitation explicitly.

### Worker-only injection

The trusted provider must construct the worker environment explicitly. It may add only:

```text
COPILOT_GITHUB_TOKEN=<worker-only secret>
```

alongside the existing approved non-secret worker environment.

It must explicitly exclude:

- `GH_TOKEN`;
- `GITHUB_TOKEN`;
- trusted runtime/publication credentials;
- arbitrary ambient environment values;
- GitHub CLI credential state;
- SSH, askpass, signing, package-registry, or workflow-administration credentials.

Do not introduce generic environment-variable passthrough. The worker request, prompt, or candidate output must not select the credential source.

Authentication remains below the agent-agnostic workflow boundary:

```text
workflow
  -> agent-agnostic execution provider
  -> Copilot-specific authentication adapter
  -> Copilot CLI
```

Workflow authority and policy must not depend directly on `COPILOT_GITHUB_TOKEN`.

### Secret lifetime and persistence

The PAT value must exist only in trusted-host/provider memory for the worker launch lifetime. It must never appear in:

- prompts or candidate output;
- argv or command identity;
- process identity or attestations;
- provider/runtime results;
- evidence, authority, or workflow state;
- logs, exceptions, or error subjects;
- result-store artifacts;
- workspace files;
- Git objects or commits;
- issue or pull-request metadata.

If current execution facts serialize environment values, change them narrowly so they attest the approved non-secret environment and the presence/mode of the credential capability without serializing or hashing the secret value. Preserve all existing command, process, workspace, request, authority, provider, candidate, result, and control-plane bindings.

Clean up any ephemeral secret transport immediately after execution. Do not write a plaintext credential file or `.env` file.

## Provisioning contract

Document exact operator procedures for:

- creating the dedicated Keychain item without placing the PAT on process argv;
- fixed service/account identifiers;
- expected credential type;
- required Keychain access policy;
- replacing/rotating the item;
- deleting the item;
- revoking the PAT at GitHub;
- detecting absent or malformed credentials;
- auditing non-secret credential provenance, permission profile, repository selection, expiry, and revocation ownership.

Do not place the actual secret in source, documentation, workflow state, issue text, test output, or examples.

## Security model

The overall workflow needs GitHub publication authority, but the worker does not.

The worker produces candidate work and local commits. The trusted runtime independently validates the result, publishes the exact approved SHA, and creates/reconciles the draft PR. Giving publication credentials to the worker would bypass that trusted boundary and create a confused-deputy and privilege-escalation path.

This issue therefore grants only Copilot execution-service authentication. It does not grant repository read/write, branch mutation, PR/issue mutation, Actions/workflow permissions, administration, SSH, or signing authority.

This remains Phase 1 trusted-local execution. It does not add or claim Phase 2 hostile-process, same-UID credential, filesystem, network, VM/container, PID namespace, or multi-tenant isolation.

## Required tests

Add focused adversarial coverage proving:

- the exact approved Keychain service/account is queried;
- successful synthetic credential retrieval and worker-only injection;
- missing credential fails before worker launch;
- wrong service/account, malfo

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
