    root spawn DispatchAuditor();
}

"""Course recommendation graph: BFS over typed parent/child links with a visited set.

Models the issue's complaint about a hand-rolled BFS that loops on a cycle
because it forgot to mark the current node as seen. The lift replaces the
manual queue + visited-dict plumbing with a walker that walks typed `Prereq`
edges and carries its own memory (a ``has`` field acting as the visited
set). A cycle is constructed in the demo so the cycle-safety semantics
from the issue are observable.
"""

node Course {
    has title: str = "";
    has code: str = "";
    has available: bool = True;
}

edge Prereq {
    has note: str = "";
}

walker CourseSearch {
    has target: str = "";
    has visited: list[str] = [];
    has path: list[str] = [];

    can start with Root entry {
        print(f"Looking for course: {self.target}");
        visit [-->];
    }

    can search with Course entry {
        if here.code in self.visited {
            print(f"[skip cycle] already saw {here.code}");
            disengage;
        }
        self.visited.append(here.code);
        self.path.append(here.code);
        print(f"  visit {here.code} ({here.title})");
        if here.code == self.target {
            print(f"  found target: {here.code} via {self.path}");
            disengage;
        }
        if [->:Prereq:->] {
            visit [->:Prereq:->];
        } else {
            print(f"  dead end at {here.code}");
            disengage;
        }
    }
}

walker Invalidate {
    has visited: list[str] = [];

    can start with Root entry {
        print("Cascading invalidation over prereq tree");
        visit [-->];
    }

    can cascade with Course entry {
        if here.code in self.visited {
            disengage;
        }
        self.visited.append(here.code);
        here.available = False;
        print(f"  invalidated {here.code} ({here.title})");
        if [->:Prereq:->] {
            visit [->:Prereq:->];
        } else {
            disengage;
        }
    }
}

with entry {
    # Build a small course graph with a cycle: Intro <- Discrete <- Algorithms <- Intro
    intro = Course(title="Intro to CS", code="CS101");
    discrete = Course(title="Discrete Math", code="CS220");
    algorithms = Course(title="Algorithms", code="CS340");
    capstone = Course(title="Capstone", code="CS490");

    root ++> intro
        ++> discrete
        ++> algorithms
        ++> capstone;

    # Typed prereq edges (course A requires course B)
    intro   +>:Prereq(note="foundation"):+> discrete;
    discrete +>:Prereq(note="builds on"):+> algorithms;
    algorithms +>:Prereq(note="legacy typo"):+> intro;   # cycle back to intro

    # Run a search that would loop forever without the visited set
    seeker = CourseSearch(target="CS340");
    root spawn seeker;

    print("---");

    # Run a cascade invalidation across the prereq tree (cycle-safe too)
    inv = Invalidate();
    root spawn inv;
}

