        here.describe(amount);
        self.revenue = self.revenue + amount;
        visit [-->];
    }
}

with entry {
    root ++> Vehicle(label="Car", rate=2.50)
        ++> Vehicle(label="Truck", rate=2.50, tons=3.0)
        ++> Vehicle(label="Motorcycle", rate=1.00)
        ++> Vehicle(label="Truck", rate=2.50, tons=1.5);
    c = Collector();
    root spawn c;
    print(f"Gate G-4 total revenue: ${c.revenue:.2f}");
}

"""Deploy pipeline: pre-built venv/wheel cache invalidation across CI runs.

Models the essential scenario from joongsim/fitted issue #66: a CI pipeline
that produces a deploy cache keyed by the lockfile hash, a deploy job that
either consumes a matching cache or falls back to a slow install, and an
auditor walker that traverses the cache history to invalidate stale entries
when the lockfile changes.
"""

node DeployJob {
    has name: str = "";
    has lockfile_hash: str = "";
    has status: str = "pending";
}

node CacheEntry {
    has key: str = "";
    has lockfile_hash: str = "";
    has size_mb: float = 0.0;
    has built_at: str = "";
    has stale: bool = False;
}

node BuildStep {
    has label: str = "";
    has duration_s: int = 0;
}

edge Produced {
    has timestamp: str = "";
}

edge Invalidates { }

edge Step { }

walker CacheAuditor {
    has current_lock_hash: str = "";

    can start with Root entry {
        print(f"Auditing caches against lockfile hash {self.current_lock_hash}");
        visit [->:Produced:->];
    }

    can review with CacheEntry entry {
        is_match = here.lockfile_hash == self.current_lock_hash;
        verdict = "HIT" if is_match else "MISS";
        action = "reuse" if is_match else "rebuild";
        print(f"  cache[{here.key}] hash={here.lockfile_hash} -> {verdict} ({action})");
        visit [->:Invalidates:->];
    }

    can invalidate with CacheEntry entry {
        if not here.stale {
            here.stale = True;
            print(f"  ! invalidated stale cache {here.key} (lockfile drift)");
        }
        visit [->:Step:->];
    }

    can summarize with BuildStep entry {
        print(f"  step[{here.label}] took {here.duration_s}s");
        visit [-->];
    }
}

walker CacheAudit {
    has current_lock_hash: str = "";
    has hits: int = 0;
    has misses: int = 0;

    can start with Root entry {
        visit [->:Produced:->];
    }

    can tally with CacheEntry entry {
        if here.lockfile_hash == self.current_lock_hash {
            self.hits += 1;
        } else {
            self.misses += 1;
        }
        visit [->:Step:->];
    }

    can finish with BuildStep entry {
        print(f"Audit done: {self.hits} hit(s), {self.misses} miss(es)");
        visit [-->] else { disengage; }
    }
}

with entry {
    job = DeployJob(name="deploy-prod", lockfile_hash="abc123");
    root ++> job;

    fresh = CacheEntry(key="cache-v7", lockfile_hash="abc123", size_mb=312.0, built_at="2026-01-15T10:00Z");
    stale1 = CacheEntry(key="cache-v5", lockfile_hash="111111", size_mb=298.0, built_at="2026-01-10T10:00Z", stale=True);
    stale2 = CacheEntry(key="cache-v6", lockfile_hash="222222", size_mb=305.0, built_at="2026-01-12T10:00Z", stale=True);

    job +>:Produced(timestamp="2026-01-15"):+> fresh;
    job +>:Produced(timestamp="2026-01-10"):+> stale1;
    job +>:Produced(timestamp="2026-01-12"):+> stale2;

    fresh +>:Invalidates:+> stale1;
    stale2 +>:Invalidates:+> stale1;

    step_sync = BuildStep(label="uv sync (cold)", duration_s=180);
    step_cache = BuildStep(label="download+unpack cache", duration_s=12);
    fresh +>:Step:+> step_cache;
    stale1 +>:Step:+> step_sync;
    stale2 +>:Step:+> step_sync;

    print("== Walking the pipeline as an auditor (lockfile hash = abc123) ==");
    root spawn CacheAuditor(current_lock_hash="abc123");

    print("");
    print("== Walking the pipeline as an audit counter ==");
    root spawn CacheAudit(current_lock_hash="abc123");
}

"""Review tier routing: declare blast-radius paths so required review depth is schema, not judgment.

Models the gap in Issue #482 — review depth is currently tiered by prose judgment
("high-risk, concurrent-batch, or RC PRs"). This demo models the proposed
`review_tiers` seam: path patterns mapped to required review depth, consumed by
a walker that walks the changed paths and reports which review gates must fire.
"""

# A path-glob entry the consumer repo declares at its seam.
node PathPattern {
    has pattern: str = "";
    has tier: str = "standard";
    has rationale: str = "";
}

# A changed file on a PR, carrying its own blast radius classification.
node ChangedPath {
    has file_path: str = "";
    has risk_class: str = "normal";
}

# A collected finding: this gate is required for this changed path.
node Finding {
    has file_path: str = "";
    has gate_label: str = "";
    has tier: str = "";
}

edge DeclaredAt { }     # PathPattern declared on the repo seam.
edge Affects { }        # ChangedPath is touched by this PR.

walker TierRouter {
    has findings: list = [];

    can start with Root entry {
        # Walk declared patterns first, then route the changed paths.
        visit [->:DeclaredAt:->];
    }

    can index_pattern with PathPattern entry {
        visit [->:DeclaredAt:->];
    }

    # For each changed path, decide which review gate label is mandated
    # based on the matching pattern's tier. We model the glob match as a
    # substring check (a real impl would use a glob engine); the routing
    # semantics the issue cares about are preserved.
    can route with ChangedPath entry {
        declared = [->:DeclaredAt:->];
        for pat in declared {
            if pat.pattern != "" and pat.pattern in here.file_path {
                gate_label = (
                    "ADVERSARIAL+SECURITY+HUMAN" if pat.tier == "critical"
                    else "ADVERSARIAL+SECURITY" if pat.tier == "high"
                    else "ADVERSARIAL" if pat.tier == "standard"
                    else "LINT"
                );
                self.findings.append(
                    Finding(
                        file_path=here.file_path,
                        gate_label=gate_label,
                        tier=pat.tier
                    )
                );
            }
        }
        visit [->:Affects:->];
    }

    can summarize with Finding entry {
        visit [-->];
    }
}

with entry {
    # Declared blast-radius patterns at the repo seam. Absence of any
    # declaration preserves today's judgment-based behavior (opt-in).
    pay_pattern = PathPattern(pattern="payments/", tier="critical",
                              rationale="payments path -> critical blast radius");
    auth_pattern = PathPattern(pattern="auth/", tier="high",
                               rationale="auth path -> high blast radius");
    doc_pattern = PathPattern(pattern="docs/", tier="low",
                              rationale="docs path -> low blast radius");

    # The PR's changed paths with their derived risk classes.
    pr_touched = [
        ChangedPath(file_path="payments/charge.rb", risk_class="critical"),
        ChangedPath(file_path="auth/session.rb", risk_class="high"),
        ChangedPath(file_path="docs/README.md", risk_class="low"),
        ChangedPath(file_path="lib/util.rb", risk_class="normal"),
    ];

    # Wire the seam: root -> declared patterns (DeclaredAt) and
    # root -> changed paths (Affects).
    root +>:DeclaredAt:+> pay_pattern;
    root +>:DeclaredAt:+> auth_pattern;
    root +>:DeclaredAt:+> doc_pattern;
    root +>:Affects:+> pr_touched[0];
    root +>:Affects:+> pr_touched[1];
    root +>:Affects:+> pr_touched[2];
    root +>:Affects:+> pr_touched[3];

    # Spawn the router walker on root. It walks patterns, then routes
    # each changed path through the declared tiers, producing findings.
    router = TierRouter();
    root spawn router;

    # Single exit report from accumulated walker state.
    print(f"Review Completion Gate requires {len(router.findings)} mandated reviews:");
    for f in router.findings {
        print(f"  - [{f.tier.upper()}] {f.file_path} -> {f.gate_label}");
    }
    routed_paths = [f.file_path for f in router.findings];
    for p in pr_touched {
        if not (p.file_path in routed_paths) {
            print(f"  - [judgment] {p.file_path} -> no declared tier, defer to per-PR judgment");
        }
    }
}

"""Typhon profiler config ergonomics: modeled as a graph where enabling a leaf
flag without its ancestors is a silent no-op.

The 232-flag Typhon:Profiler:* tree resolves strictly parent-implies-children:
"Parent off -> all descendants off (regardless of their own keys)." Enabling a
leaf without its ancestors is a silent no-op -- no warning, no data, a
plausible-looking trace. The ConfigAuditor walker traverses every flag from
the root and reports which ones are actually live in the trace vs. which were
silently dropped because an ancestor on the path to root was disabled.
"""

# A flag node: a leaf or branch in the Profiler config tree.
node Flag {
    has name: str = "";
    has enabled: bool = False;
    has children: list = [];
    has is_root: bool = False;
}

# Typed edge from a parent flag to a child flag in the Profiler tree.
edge SubFlag { }

walker ConfigAuditor {
    has live_flags: list = [];
    has silently_dropped: list = [];

    can start with Root entry {
        # Begin by entering each top-level flag branch from the root.
        visit [->:SubFlag:->];
    }

    can audit with Flag entry {
        # Root catalog has no enablement; its descendants do.
        if here.is_root {
            visit [->:SubFlag:->];
        } elif here.enabled {
            # Seed: a flag is only live if no known-broken ancestor
            # silently dropped it (i.e. an ancestor was off but a leaf
            # was hand-enabled). If this flag itself is on the known-
            # broken list, treat it as dropped for the summary.
            self.live_flags.append(here.name);
            visit [->:SubFlag:->];
        } else {
            # This flag is OFF; every descendant is silently dropped.
            for child in here.children {
                self.silently_dropped.append(child);
            }
            visit [->:SubFlag:->];
        }
    }

    can summarize with Root entry {
        final_live: list = [];
        final_dropped: list = [];

        for n in self.live_flags {
            if n in self.silently_dropped {
                final_dropped.append(n);
            } else {
                final_live.append(n);
            }
        }

        print("LIVE FLAGS (actually emitted to trace):");
        for n in final_live {
            print(f"  + {n}");
        }
        print("");
        print("SILENTLY DROPPED (enabled but ancestor off):");
        for n in final_dropped {
            print(f"  ! {n}");
        }
    }
}

with entry {
    # Build a small slice of the flag catalog: a Profiler root with a
    # Runtime child and an AdaptiveWaiter child. The Runtime branch contains
    # ThreadScheduling (a real flag) and TieredCompilation (a leaf that the
    # July investigator enabled by hand, forgetting its Runtime parent).
    profiler = Flag(name="Profiler", is_root=True);
    runtime = Flag(name="Runtime", children=["TieredCompilation"]);
    sched = Flag(name="ThreadScheduling", enabled=True);
    tiered = Flag(name="TieredCompilation", enabled=True);
    adaptive = Flag(name="AdaptiveWaiter", enabled=False);
    yields = Flag(name="YieldOrSleep", enabled=True);

    root +>:SubFlag:+> profiler;
    profiler +>:SubFlag:+> runtime;
    runtime +>:SubFlag:+> sched;
    runtime +>:SubFlag:+> tiered;
    profiler +>:SubFlag:+> adaptive;
    adaptive +>:SubFlag:+> yields;

    auditor = ConfigAuditor();
    root spawn auditor;
}

