```jac
"""QORE-style universal market instrument coverage demo.

Models a few representative instrument archetypes (equity, fixed-income bond,
futures contract, FX spot) as nodes and walks the graph with a coverage walker
that performs the kind of recursive traversal the issue complains about
being hand-rolled in Python. Typed edges carry the semantic relationship
(IssuedBy, SettledIn, ReferencesRate). A cascade-invalidator walker
demonstrates graph-aware invalidation, and a cycle-detecting reachability
walker demonstrates the kind of dependency-walk that should never hang.
"""

node Issuer {
    has name: str = "";
    has jurisdiction: str = "";
}

node Exchange {
    has name: str = "";
    has venue_type: str = "";
}

node Benchmark {
    has name: str = "";
    has tenor: str = "";
}

# --- Core instrument archetypes -----------------------------------------

node Equity {
    has ticker: str = "";
    has ccy: str = "USD";
    has shares_outstanding: int = 0;
}

node Bond {
    has cusip: str = "";
    has face_value: float = 0.0;
    has coupon_rate: float = 0.0;
    has coupon_freq: int = 0;
    has maturity_year: int = 0;
    has rating: str = "";
}

node FuturesContract {
    has symbol: str = "";
    has contract_month: str = "";
    has multiplier: float = 1.0;
    has tick_value: float = 0.0;
    has underlying_symbol: str = "";
}

node FXSpot {
    has pair: str = "";
    has base_ccy: str = "";
    has quote_ccy: str = "";
    has pip_size: float = 0.0001;
}

# --- Typed edges that carry relationship meaning -----------------------

edge IssuedBy {
    has role: str = "primary";
}

edge SettledIn {
    has settlement: str = "T+2";
}

edge ReferencesRate {
    has index_role: str = "discount";
}

edge TradesOn {
    has session: str = "regular";
}

# --- Walker 1: recursive coverage audit --------------------------------

walker CoverageAuditor {
    has visited_ids: list = [];
    has instrument_count: int = 0;
    has edge_count: int = 0;

    can start with Root entry {
        print("[audit] starting coverage walk from root");
        visit [-->];
    }

    can audit_node with Equity | Bond | FuturesContract | FXSpot entry {
        self.instrument_count += 1;
        nid = here.ticker if isinstance(here, Equity) else (
            here.cusip if isinstance(here, Bond) else (
                here.symbol if isinstance(here, FuturesContract) else here.pair
            )
        );
        self.visited_ids.append(nid);
        print(f"[audit] instrument: {nid}");
        visit [-->];
    }

    can audit_rel with Issuer | Exchange | Benchmark entry {
        self.edge_count += 1;
        kind = "issuer" if isinstance(here, Issuer) else (
            "exchange" if isinstance(here, Exchange) else "benchmark"
        );
        print(f"[audit]   -> {kind}: {here.name}");
        visit [-->];
    }

    can finish with Root exit {
        print(f"[audit] total instruments={self.instrument_count} "
              f"edges traversed={self.edge_count}");
        print(f"[audit] visited order: {self.visited_ids}");
    }
}

# --- Walker 2: cascade invalidation ------------------------------------

walker CascadeInvalidator {
    has revoked: list = [];

    can start with Root entry {
        print("[invalidate] cascade-revoke starting");
        visit [-->];
    }

    can revoke with Equity | Bond | FuturesContract | FXSpot entry {
        nid = here.ticker if isinstance(here, Equity) else (
            here.cusip if isinstance(here, Bond) else (
                here.symbol if isinstance(here, FuturesContract) else here.pair
            )
        );
        self.revoked.append(nid);
        print(f"[invalidate] revoked {nid}");
        visit [-->];
    }

    can finish with Root exit {
        print(f"[invalidate] revoked {len(self.revoked)} instruments");
    }
}

# --- Walker 3: dependency reachability with cycle guard ----------------

walker DependencyReachability {
    has target_name: str = "UST10Y";
    has seen: list = [];
    has reachable: bool = False;

    can start with Root entry {
        print(f"[reach] searching for '{self.target_name}' via typed edges");
        visit [-->];
    }

    can walk_issue with Equity | Bond | FuturesContract | FXSpot entry {
        nid = here.ticker if isinstance(here, Equity) else (
            here.cusip if isinstance(here, Bond) else (
                here.symbol if isinstance(here, FuturesContract) else here.pair
            )
        );
        if nid in self.seen {
            visit [-->] else { disengage; }
        }
        self.seen.append(nid);
        if nid == self.target_name {
            self.reachable = True;
            print(f"[reach] FOUND target {nid}");
            disengage;
        }
        visit [-->] else { disengage; }
    }

    can walk_hub with Issuer | Exchange | Benchmark entry {
        visit [-->] else { disengage; }
    }

    can finish with Root exit {
        verdict = "REACHABLE" if self.reachable else "NOT FOUND";
        print(f"[reach] {verdict} after visiting {len(self.seen)} nodes "
              f"(cycle guard active)");
    }
}

# --- Demo wiring -------------------------------------------------------

with entry {
    # Reference hubs
    us_treasury = Issuer(name="US Treasury", jurisdiction="US");
    nyse = Exchange(name="NYSE", venue_type="equities");
    cme = Exchange(name="CME", venue_type="futures");
    ust10y = Benchmark(name="UST10Y", tenor="10Y");

    # Instruments
    aapl = Equity(ticker="AAPL", ccy="USD", shares_outstanding=15_500_000_000);
    ust_note = Bond(cusip="UST10Y", face_value=1000.0, coupon_rate=0.045,
                    coupon_freq=2, maturity_year=2034, rating="AAA");
    es_fut = FuturesContract(symbol="ES", contract_month="2026-09",
                             multiplier=50.0, tick_value=12.5,
                             underlying_symbol="SPX");
    eurusd = FXSpot(pair="EURUSD", base_ccy="EUR", quote_ccy="USD",
                    pip_size=0.0001);

    # Typed-edge graph: bond references the rate benchmark it depends on
    aapl +>:IssuedBy(role="primary"):+> us_treasury;
    aapl +>:TradesOn(session="regular"):+> nyse;
    ust_note +>:IssuedBy(role="sovereign"):+> us_treasury;
    ust_note +>:ReferencesRate(index_role="discount"):+> ust10y;
    es_fut +>:TradesOn(session="globex"):+> cme;
    eurusd +>:SettledIn(settlement="T+2"):+> nyse;

    # Build graph from root
    root ++> aapl ++> ust_note ++> es_fut ++> eurusd;
    root ++> us_treasury ++> nyse ++> cme ++> ust10y;

    # Run the coverage audit (recursive instrument walk)
    root spawn CoverageAuditor();

    # Run cascade invalidation (graph-aware revocation)
    root spawn CascadeInvalidator();

    # Run dependency reachability with explicit cycle guard
    root spawn DependencyReachability(target_name="UST10Y");
}
```

"""Hiking trail: a chain of plain waypoints from trailhead to summit."""

node Waypoint {
    has title: str = "";
    has elevation: int = 0;
}

walker Hiker {
    has stops: int = 0;
    has target: int = 3;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.stops += 1;
