"""Flight network: priced legs as edges, scout finds peak fare, legs normalize against it."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has route_label: str = "";

    def fare_fraction(of_max: float) -> float {
        if of_max <= 0.0 {
            return 0.0;
        }
        return self.price / of_max;
    }
}

walker Scout {
    has reports: list[float] = [];
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen.append(here.code);
        legs = [edge ->:FlightLeg:->];
        for leg in legs {
            self.reports.append(leg.price);
            report leg.price;
        }
        visit [-->];
    }
}

with entry {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord_n = Airport(code="ORD");
    sea = Airport(code="SEA");

    root ++> jfk;
    jfk +>:FlightLeg(price=520.0, route_label="JFK-LAX"):+> lax;
    lax +>:FlightLeg(price=310.0, route_label="LAX-ORD"):+> ord_n;
    ord_n +>:FlightLeg(price=275.0, route_label="ORD-JFK"):+> jfk;
    jfk +>:FlightLeg(price=189.0, route_label="JFK-SEA"):+> sea;

    scout = root spawn Scout();
    peak = max(scout.reports) if scout.reports else 0.0;

    for leg in [edge jfk ->:FlightLeg:-> lax]
        + [edge lax ->:FlightLeg:-> ord_n]
        + [edge ord_n ->:FlightLeg:-> jfk]
        + [edge jfk ->:FlightLeg:-> sea] {
        share = leg.fare_fraction(peak);
        print(f"{leg.route_label} (${leg.price}) -> {share:.2f} of peak ${peak}");
    }
}

"""Shopify Bulk Operations ingestion model.

Models the essential scenario from issue #126: a maintainer files a bulk
operation query, polls for completion (with cancellation and stale recovery),
streams the JSONL result, and converts each row into an immutable source
record while preserving deterministic hashes, provenance and resumption.
A walker traverses the pipeline nodes over typed edges, exercising the
hand-rolled machinery the issue complains about.
"""

# ---------- entity archetypes ----------

node BulkOperation {
    has op_id: str = "";
    has query: str = "";
    has status: str = "CREATED";   # CREATED | RUNNING | COMPLETED | FAILED | CANCELLED | STALE
    has submitted_at: str = "";
    has finished_at: str = "";
    has error: str = "";
}

node Catalog {
    has catalog_id: str = "";
    has product_count: int = 0;
    has cursor_page: int = 0;
    has use_bulk: bool = True;
}

node SourceRecord {
    has record_id: str = "";
    has sku: str = "";
    has title: str = "";
    has content_hash: str = "";
    has provenance: str = "";
    has canonical_id: str = "";
}

# Row -> SourceRecord conversion target (identity bucket for idempotency).
node ProductSink {
    has name: str = "canonical_products";
}

# ---------- typed edges ----------

edge SubmittedFor { has reason: str = ""; }
edge Produces { has row_count: int = 0; }
edge HashedTo { has algorithm: str = "sha256"; }
edge Resumes { has checkpoint: str = ""; }

# ---------- walker ----------

walker PipelineOperator {
    has completed_seen: list[str] = [];
    has bad_op_id: str = "";

    can start with Root entry {
        print("=== Shopify Bulk Operations pipeline starting ===");
        visit [-->];
    }

    can handle_op with BulkOperation entry {
        op = here;
        print(f"-- entered BulkOperation {op.op_id} status={op.status} submitted={op.submitted_at}");
        if op.status in ["FAILED", "CANCELLED", "STALE"] {
            print(f"  ! operator diagnostics: {op.error}");
            print("  ! aborting pipeline (partial extraction is not claimed complete)");
            self.bad_op_id = op.op_id;
            disengage;
        }
        if op.status == "COMPLETED" {
            self.completed_seen.append(op.op_id);
        }
        visit [->:Produces:->];
    }

    can inspect_catalog with Catalog entry {
        cat = here;
        path = "BULK" if cat.use_bulk else "CURSOR";
        print(f"-- entered Catalog id={cat.catalog_id} products={cat.product_count} path={path}");
        visit [-->];
    }

    can inspect_sink with ProductSink entry {
        sink = here;
        print(f"-- entered ProductSink '{sink.name}'; writing canonical products");
        visit [-->];
    }

    can finalize_record with SourceRecord entry {
        rec = here;
        print(f"  record sku={rec.sku} hash={rec.content_hash[:8]}.. prov={rec.provenance}");
        visit [-->];
    }

    can done with Root entry {
        print(f"=== pipeline complete; idempotent ops seen: {self.completed_seen}; bad_op={self.bad_op_id} ===");
    }
}

# ---------- demo wiring ----------

with entry {
    # 1. Submit a bulk query for a large catalog (10k products).
    big_op = BulkOperation(
        op_id="gid://shopify/BulkOperation/1001",
        query="{ products(first: 10000) { edges { node { id title sku variants { id } } } } }",
        status="RUNNING",
        submitted_at="2024-05-01T10:00:00Z"
    );

    # 2. A smaller catalog chooses cursor pagination instead.
    small_cat = Catalog(catalog_id="cat-small", product_count=120, use_bulk=False);

    # 3. A second bulk op has already completed earlier -- reprocessing must
    #    be idempotent (the walker tracks completion ids).
    prior_op = BulkOperation(
        op_id="gid://shopify/BulkOperation/0999",
        query="{ products(first: 500) { edges { node { id title } } } }",
        status="COMPLETED",
        submitted_at="2024-04-30T22:00:00Z",
        finished_at="2024-05-01T01:14:00Z"
    );

    # 4. A failed op carries sanitized diagnostics (no secrets).
    failed_op = BulkOperation(
        op_id="gid://shopify/BulkOperation/1002",
        query="{ products(first: 99999) { edges { node { id } } } }",
        status="FAILED",
        submitted_at="2024-05-01T11:00:00Z",
        finished_at="2024-05-01T11:00:05Z",
        error="QUERY_TOO_LARGE: reduce first:N below 10000"
    );

    # 5. The sink collects normalized, deterministic products.
    sink = ProductSink();

    # Build the graph: root -> catalogs/ops -> (Produces) -> records -> sink.
    # Typed edges carry meaning (Produces carries row_count, HashedTo carries
    # the algorithm, Resumes carries a checkpoint name).
    root ++> big_op;
    root ++> small_cat;
    root ++> prior_op;
    root ++> failed_op;

    big_op +>:Produces(row_count=10000):+> sink;
    prior_op +>:Produces(row_count=500):+> sink;
    failed_op +>:Produces(row_count=0):+> sink;

    # Sample source records produced by the streaming JSONL parse.
    r1 = SourceRecord(
        record_id="r-1", sku="SKU-A", title="Pilot Widget",
        content_hash="3f2c1a0b9e8d7c6b5a4f3e2d1c0b9a8f",
        provenance="bulk:1001", canonical_id="canon-001"
    );
    r2 = SourceRecord(
        record_id="r-2", sku="SKU-B", title="Pilot Gadget",
        content_hash="8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d",
        provenance="bulk:1001", canonical_id="canon-002"
    );
    r3 = SourceRecord(
        record_id="r-3", sku="SKU-C", title="Prior Widget",
        content_hash="1a2b3c4d5e6f7a8b9c0d1e2f3a4b5c6d",
        provenance="bulk:0999", canonical_id="canon-003"
    );

    sink +>:HashedTo:+> r1;
    sink +>:HashedTo:+> r2;
    sink +>:HashedTo:+> r3;
    r1 +>:Resumes(checkpoint="offset:0"):+> r2;
    r2 +>:Resumes(checkpoint="offset:1"):+> r3;

    # Spawn the operator; it walks catalogs, ops (typed Produces), then
    # records (typed Resumes), then back to the sink, surfacing diagnostics
    # for failures and tracking completed op ids for idempotency.
    root spawn PipelineOperator();
}

