    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has host_id: str = "";
    has host_name: str = "";
    has supported_target: bool = False;
    has supported_transport: bool = False;
    has action_constructible: bool = False;
    has return_constructible: bool = False;
    has transport_label: str = "";
}

node ReturnContract {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has assignment_id: str = "";
    has subject_id: str = "";
    has target: str = "";
    has scope: str = "";
    has stops: str = "";
    has mutation_baseline: str = "";
    has mutation_subject: str = "";
    has delivery_meaning: str = "";
    has integrity: str = "";
    has currentness: str = "";
    has return_id: str = "";
    has reentry_id: str = "";
    has changed_paths: list[str] = [];
    has concurrent_work_preserved: bool = False;
    has accepted: bool = False;
}

node Owner {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner_name: str = "";
    has admission_id: str = "";
    has proof_authority: bool = False;
    has completion_authority: bool = False;
}

edge AssignmentHost {
    has transport: str = "";
    has automatic: bool = False;
}

edge HostReturn {
    has action: str = "";
    has adapter: str = "";
}

edge ResultAdmission {
    has owner_kind: str = "";
}

edge ReentryLoop {
    has assignment_id: str = "";
}

walker CanonicalAudit {
    has seen_assignments: list[str] = [];

    can start with Root entry {
        print("canonical assignment lineage");
        visit [-->];
    }

    can inspect_assignment with Assignment entry {
        if here.assignment_id in self.seen_assignments {
            print(f"cycle guarded at assignment {here.assignment_id}");
            disengage;
        } else {
            self.seen_assignments.append(here.assignment_id);
            authority = "automatic" if here.automatic_authority else "manual";
            print(f"assignment {here.assignment_id}: {authority} authority, "
                  f"subject={here.subject_id}, target={here.target}");
            print(f"handoff carries scope={here.scope}, stops={here.stops}, "
                  f"baseline={here.mutation_baseline}, return={here.return_id}");
            visit [->:AssignmentHost:->] else { disengage; }
        }
    }

    can inspect_host with Host entry {
        ready = here.supported_target and here.supported_transport
            and here.action_constructible and here.return_constructible;
        readiness = "constructible" if ready else "blocked";
        print(f"host {here.host_name}: {readiness} current action/return path "
              f"for transport {here.transport_label}");
        visit [->:HostReturn:->] else { disengage; }
    }

    can inspect_return with ReturnContract entry {
        sealed = here.assignment_id != "" and here.subject_id != ""
            and here.target != "" and here.mutation_baseline != ""
            and here.integrity != "" and here.reentry_id != "";
        status = "sealed" if sealed else "incomplete";
        print(f"return {here.return_id}: {status}, "
              f"subject={here.mutation_subject}, paths={here.changed_paths}");
        print(f"currentness={here.currentness}, delivery={here.delivery_meaning}, "
              f"unrelated work preserved={here.concurrent_work_preserved}");
        visit [->:ResultAdmission:->] else { disengage; }
    }

    can inspect_owner with Owner entry {
        print(f"typed admission to {here.owner_name}: {here.admission_id}");
        print(f"proof authority={here.proof_authority}, "
              f"completion authority={here.completion_authority}");
        visit [->:ReentryLoop:->] else { disengage; }
    }
}

with entry {
    assignment = Assignment(
        title="Host-native delegation",
        year=2947,
