"""Native OSP model of an owned Git-provider run and dependency audit."""

node ProviderRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_key: str = "";
    has state: str = "planned";
}

node FixtureRepository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has repository_key: str = "";
    has branch: str = "main";
    has object_format: str = "sha1";
}

node Worktree {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has worktree_key: str = "";
    has path_label: str = "";
    has registered: bool = False;
}

node Operation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has operation_key: str = "";
    has state: str = "planned";
}

edge OwnsRepository { }
edge Materializes { }
edge Schedules { }
edge DependsOn { }

walker TopologyAuditor {
    can start with Root entry {
        print("auditing owned provider topology");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_run with ProviderRun entry {
        print(f"run {here.run_key}: {here.state}");
        visit [->:OwnsRepository:->] else {
            disengage;
        }
    }

    can inspect_repository with FixtureRepository entry {
        print(f"repository {here.repository_key} on {here.branch}");
        visit [->:Materializes:->] else {
            disengage;
        }
    }

    can inspect_worktree with Worktree entry {
        status = "registered" if here.registered else "unregistered";
        print(f"worktree {here.worktree_key}: {status}");
        visit [-->] else {
            disengage;
        }
    }
}

walker DependencyAuditor {
    has seen_operations: list[str] = [];

    can start with Root entry {
        print("auditing operation dependencies");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_run with ProviderRun entry {
        visit [->:Schedules:->] else {
            disengage;
        }
    }

    can inspect_operation with Operation entry {
        if here.operation_key in self.seen_operations {
            print(f"dependency cycle detected at {here.operation_key}");
            disengage;
        } else {
            self.seen_operations.append(here.operation_key);
            print(f"operation {here.operation_key}: {here.state}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

with entry {
    run = ProviderRun(
        title="isolated fixture run",
        run_key="run-913",
        state="owned"
    );
    repository = FixtureRepository(
        title="disposable git-provider repository",
        repository_key="repo-913",
        branch="main",
        object_format="sha1"
    );
    worktree = Worktree(
        title="materialized worktree",
        worktree_key="wt-913",
        path_label="owned-run-root/worktree",
        registered=True
    );
    plan = Operation(
        title="verify fixture topology",
        operation_key="op-plan",
        state="planned"
    );
    reconcile = Operation(
        title="reconcile uncertain mutation",
        operation_key="op-reconcile",
        state="reconciliation-required"
    );

    root ++> run;
    run +>:OwnsRepository:+> repository;
    repository +>:Materializes:+> worktree;
    run +>:Schedules:+> plan;
    plan +>:DependsOn:+> reconcile;
    reconcile +>:DependsOn:+> plan;

    root spawn TopologyAuditor();
    root spawn DependencyAuditor();
}

"""Native graph model for issue dependencies and dependency cycles."""

node Issue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has issue_id: int = 0;
    has landed: bool = False;
    has blocked: bool = False;
    has walk_state: int = 0;
}

node PlanningBrief {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has dependency_marker: str = "";
}

node DependencyGraph {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn {
    has why: str = "";
}

edge HasBrief { }
edge AuditLaunch { }
edge CycleLaunch { }

walker DependencyAuditor {
    can start with Root entry {
        print("Auditing declared dependencies");
        visit [->:AuditLaunch:->] else {
            disengage;
        }
    }

    can enter_graph with DependencyGraph entry {
        visit [-->];
    }

    can inspect_issue with Issue entry {
        if here.walk_state == 2 {
            print(f"Issue #{here.issue_id} already audited");
        } else {
            if here.walk_state == 1 {
                print(f"Cycle detected at issue #{here.issue_id}: {here.title}");
                disengage;
            } else {
                here.walk_state = 1;

                if here.blocked {
                    print(f"Issue #{here.issue_id} is blocked: {here.title}");
                } else {
                    print(f"Issue #{here.issue_id} is ready: {here.title}");
                }

                if here.landed {
                    print(f"Issue #{here.issue_id} has landed");
                } else {
                    print(f"Issue #{here.issue_id} has not landed");
                }

                visit [->:HasBrief:->] else {
                    print(f"Issue #{here.issue_id} has no planning brief");
                }

                visit [->:DependsOn:->] else {
                    print(f"Issue #{here.issue_id} has no dependencies");
                }

                here.walk_state = 2;
            }
        }
    }

    can inspect_brief with PlanningBrief entry {
        print(f"Planning Brief marker: {here.dependency_marker}");
    }
}

walker CycleDetector {
    can start with Root entry {
        print("Checking the dependency graph for cycles");
        visit [->:CycleLaunch:->] else {
            disengage;
        }
    }

    can enter_graph with DependencyGraph entry {
        visit [-->];
    }

    can inspect_issue with Issue entry {
        if here.walk_state == 1 {
            print(f"Cycle detected at issue #{here.issue_id}: {here.title}");
            disengage;
        } else {
            here.walk_state = 1;
            visit [->:DependsOn:->] else {
                here.walk_state = 2;
            }
        }
    }
}

with entry {
    contract = Issue(
        issue_id=53,
        title="Define the spec-skill contract",
        year=2024,
        available=True,
        landed=False
    );

    dependent = Issue(
        issue_id=54,
        title="Build the spec skill",
        year=2024,
        available=False,
        landed=False,
        blocked=True
    );

    brief = PlanningBrief(
        title="Dependency-aware planning brief",
        dependency_marker="<!-- agent:dependency --> Depends on: #53"
    );

    cycle_a = Issue(
        issue_id=60,
        title="Cycle participant A",
        year=2024,
        available=True
    );

    cycle_b = Issue(
        issue_id=61,
        title="Cycle participant B",
        year=2024,
        available=True
    );

    dependency_graph = DependencyGraph(
        title="Declared dependency path",
        year=2024
    );
    cycle_graph = DependencyGraph(
        title="Cycle probe path",
        year=2024
    );

    root +>:AuditLaunch:+> dependency_graph;
    dependency_graph ++> dependent;
    dependent +>:HasBrief:+> brief;
    dependent +>:DependsOn(why="The contract must land first"):+> contract;

    root +>:CycleLaunch:+> cycle_graph;
    cycle_graph ++> cycle_a;
    cycle_a +>:DependsOn(why="Mutual dependency"):+> cycle_b;
    cycle_b +>:DependsOn(why="Mutual dependency"):+> cycle_a;

    root spawn DependencyAuditor();
    root spawn CycleDetector();
}

