"""Wildlife park feeding rounds.

The kiosk greets every tour party regardless of type. Zookeepers feed each
animal its species-appropriate meal (meat for lions, seed for parrots,
standard feed otherwise). School groups simply watch the animals.
"""

node Lion {
    has name: str = "";

    def meal() -> str {
        return "meat";
    }
}

node Parrot {
    has name: str = "";

    def meal() -> str {
        return "seed";
    }
}

node Zebra {
    has name: str = "";

    def meal() -> str {
        return "standard feed";
    }
}

node Enclosure {
    has label: str = "";
}

# Each tour party is modeled as a walker. A shared base walker would force
# us to share every `has` field across every party type, which loses the
# per-type identity we want. So each party declares its own abilities.

walker Zookeeper {
    has rounds: int = 0;

    can start with Root entry {
        print("Kiosk: Welcome to the wildlife park!");
        visit [-->];
    }

    can walk_halls with Enclosure entry {
        visit [-->];
    }

    # Union trigger: the keeper feeds lions AND parrots AND zebras, but
    # not the school group itself. The shared `meal()` method is defined
    # on every animal node, so one ability covers all of them.
    can feed with Lion | Parrot | Zebra entry {
        food = here.meal();
        print(f"Zookeeper feeds {here.name} the {food}");
        self.rounds += 1;
    }
}

walker SchoolGroup {
    can start with Root entry {
        print("Kiosk: Welcome to the wildlife park!");
        visit [-->];
    }

    can walk_halls with Enclosure entry {
        visit [-->];
    }

    # School groups only watch animals, so the union trigger matches all
    # three animal types and just observes them.
    can observe with Lion | Parrot | Zebra entry {
        print(f"School group watches {here.name}");
    }
}

with entry {
    savanna = Enclosure(label="Savanna");
    aviary = Enclosure(label="Aviary");
    meadow = Enclosure(label="Meadow");

    root ++> savanna ++> aviary ++> meadow;
    savanna ++> Lion(name="Leo");
    aviary ++> Parrot(name="Polly");
    meadow ++> Zebra(name="Zara");

    print("=== Zookeeper rounds ===");
    zk = Zookeeper();
    root spawn zk;
    print(f"Zookeeper completed {zk.rounds} feedings");

    print("=== School group visit ===");
    root spawn SchoolGroup();
}

"""Hiking trail: chain plain waypoints from trailhead to summit with a counting hiker."""

node Trailhead {
    has label: str = "Trailhead";
}

node Waypoint {
    has marker: bool = True;
}

node Summit {
    has label: str = "Summit";
}

walker Hiker {
    has stop_number: int = 0;
    has expected_waypoints: int = 0;

    can start with Root entry {
        print("Setting out on the trail");
        visit [-->];
    }

    can arrive with Trailhead entry {
        print(f"Trail begins at {here.label}");
        visit [-->];
    }

    can checkpoint with Waypoint entry {
        self.stop_number += 1;
        print(f"Stop {self.stop_number}");
        visit [-->];
    }

    can finish with Summit entry {
        if self.stop_number >= self.expected_waypoints {
            print(
                f"Trail complete: passed {self.stop_number} waypoints "
                f"and reached {here.label}"
            );
        }
        disengage;
    }
}

with entry {
    trailhead = Trailhead();
    wp1 = Waypoint();
    wp2 = Waypoint();
    wp3 = Waypoint();
    summit = Summit();
    root ++> trailhead ++> wp1 ++> wp2 ++> wp3 ++> summit;
    root spawn Hiker(expected_waypoints=3);
}

"""Aggregate stats over a private todo graph into one report.

Counters accumulate during the walk and a single dict is reported at
Root exit; division by zero is guarded for accounts with no todos.
"""

node Todo {
    has title: str;
    has done: bool = False;
    has points: int = 1;
}

walker:priv add_todo {
    has title: str;
    has done: bool = False;

    can run with Root entry {
        here ++> Todo(title=self.title, done=self.done);
    }
}

walker:priv get_stats {
    has total: int = 0;
    has completed: int = 0;
    has effort_done: int = 0;
    has effort_total: int = 0;

    can count with Root entry {
        visit [-->];
    }

    can tally with Todo entry {
        self.total += 1;
        self.effort_total += here.points;
        if here.done {
            self.completed += 1;
            self.effort_done += here.points;
        }
    }

    can summarize with Root exit {
        report {
            "total": self.total,
            "completed": self.completed,
            "pending": self.total - self.completed,
            "completion_rate": (self.completed / self.total * 100) if self.total > 0 else 0.0,
            "points_burned": self.effort_done,
            "points_total": self.effort_total,
        };
    }
}

with entry {
    root spawn add_todo(title="set up CI", done=True);
    root spawn add_todo(title="write API docs", done=True);
    root spawn add_todo(title="onboard beta users");
    root spawn add_todo(title="price the tiers");

    stats = root spawn get_stats();
    print(stats.reports);
}

