        print(f"Depot: {here.name}");
        visit [-->];
    }

    can check_route with Route entry {
        label = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"  [{label}] {here.title} ({here.weight}t)");
        visit [-->];
    }
}

