"""Installer lifecycle demo with safe config preservation and independent cleanup."""

node HostConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has present: bool = False;
    has original_bytes: str = "";
    has backup_bytes: str = "";
    has normalized_bytes: str = "";
    has plugin_reference: bool = False;
}

node Plugin {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cleanup_authorized: bool = True;
}

node PluginFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has plugin_owned: bool = False;
    has removed: bool = False;
}

edge OwnsPlugin { }
edge OwnsFile { }

walker Installer {
    has cleaned_files: int = 0;
    has configs_seen: int = 0;

    can start with Root entry {
        print("installer traversal started");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with HostConfig entry {
        self.configs_seen += 1;
        if here.present {
            here.backup_bytes = here.original_bytes;
            here.normalized_bytes = "{\"pattern\":\"comma,}\",\"bracket\":\"comma,]\"}";
            here.plugin_reference = False;
            print(f"config {here.title}: preserved backup and removed plugin reference");
        } else {
            print(f"config {here.title}: absent, cleanup still runs");
        }
        visit [-->] else {
            disengage;
        }
    }

    can authorize with Plugin entry {
        if here.cleanup_authorized {
            print(f"plugin {here.title}: authorized cleanup");
            visit [->:OwnsFile:->] else {
                disengage;
            }
        } else {
            print(f"plugin {here.title}: cleanup not authorized");
            disengage;
        }
    }

    can remove with PluginFile entry {
        if here.plugin_owned {
            if here.removed {
                print(f"plugin file {here.title} already absent");
            } else {
                here.removed = True;
                self.cleaned_files += 1;
                print(f"removed plugin file {here.title}");
            }
        } else {
            print(f"kept unrelated file {here.title}");
        }
    }
}

with entry {
    existing = HostConfig(
        title="host-config",
        present=True,
        plugin_reference=True,
        original_bytes="{\"pattern\":\"comma,}\",\"bracket\":\"comma,]\",}"
    );
    absent = HostConfig(
        title="missing-host-config",
        present=False
    );

    active_plugin = Plugin(title="swarm-plugin", cleanup_authorized=True);
    orphaned_plugin = Plugin(title="orphaned-plugin", cleanup_authorized=True);

    active_cache = PluginFile(title="active-cache", plugin_owned=True);
    active_shared = PluginFile(title="shared-settings", plugin_owned=False);
    orphaned_cache = PluginFile(title="orphaned-cache", plugin_owned=True);

    root ++> existing;
    root ++> absent;

    existing +>:OwnsPlugin:+> active_plugin;
    absent +>:OwnsPlugin:+> orphaned_plugin;

    active_plugin +>:OwnsFile:+> active_cache;
    active_plugin +>:OwnsFile:+> active_shared;
    orphaned_plugin +>:OwnsFile:+> orphaned_cache;

    root spawn Installer();
}

