"""PWA metadata fetcher: model HTML/manifest/favicon sources as nodes and
walk them with a fetcher walker that gracefully handles partial failures.

The issue complained about hand-rolled dependency chains over fetched
metadata sources. Here the relationships become typed edges and a walker
traverses them, returning a typed Result that records partial success."""

# --- Result type ---------------------------------------------------------

obj FetchResult {
    has title: str = "";
    has manifest_url: str = "";
    has icon_url: str = "";
    has failures: list[str] = [];

    def is_complete() -> bool {
        return self.title != "" and self.manifest_url != "" and self.icon_url != "";
    }
}

# --- Source archetypes ---------------------------------------------------

node Page {
    has url: str = "";
    has title: str = "";
    has manifest_href: str = "";
    has favicon_href: str = "";
    has reachable: bool = True;
}

node Manifest {
    has url: str = "";
    has icon_candidates: list[str] = [];
    has reachable: bool = True;
}

node Icon {
    has url: str = "";
    has reachable: bool = True;
}

# --- Typed edges ---------------------------------------------------------

edge LinksTo { }
edge Declares { }

# --- Helpers -------------------------------------------------------------

def resolve_url(base: str, ref: str) -> str {
    if ref == "" {
        return "";
    }
    if ref.startswith("http://") or ref.startswith("https://") {
        return ref;
    }
    slash = base.rfind("/");
    root_dir = base if slash < 0 else base[:slash];
    if ref.startswith("/") {
        return root_dir + ref;
    }
    return root_dir + "/" + ref;
}

# --- Walker --------------------------------------------------------------

walker MetadataFetcher {
    has result: FetchResult = FetchResult();
    has base: str = "";

    can start with Root entry {
        visit [-->];
    }

    can fetch_page with Page entry {
        if not here.reachable {
            self.result.failures.append(f"page unreachable: {here.url}");
        } else {
            self.result.title = here.title;
            self.result.manifest_url = resolve_url(here.url, here.manifest_href);
            self.result.icon_url = resolve_url(here.url, here.favicon_href);
        }
        visit [->:LinksTo:->];
    }

    can fetch_manifest with Manifest entry {
        if not here.reachable {
            self.result.failures.append(f"manifest unreachable: {here.url}");
        } else {
            best = "";
            for candidate in here.icon_candidates {
                best = resolve_url(here.url, candidate);
            }
            if best != "" {
                self.result.icon_url = best;
            }
        }
        visit [->:Declares:->];
    }

    can fetch_icon with Icon entry {
        if here.reachable {
            self.result.icon_url = here.url;
        } else {
            self.result.failures.append(f"icon unreachable: {here.url}");
        }
    }
}

# --- Demo wiring ---------------------------------------------------------

with entry {
    page_node = Page(
        url="https://example.com/index.html",
        title="Example App",
        manifest_href="/manifest.json",
        favicon_href="/favicon.ico",
        reachable=True
    );

    manifest_node = Manifest(
        url="https://example.com/manifest.json",
        icon_candidates=["icons/icon-192.png", "icons/icon-512.png"],
        reachable=True
    );

    icon_192 = Icon(url="https://example.com/icons/icon-192.png", reachable=True);
    icon_512 = Icon(url="https://example.com/icons/icon-512.png", reachable=False);

    page_node +>:LinksTo:+> manifest_node;
    manifest_node +>:Declares:+> icon_192;
    manifest_node +>:Declares:+> icon_512;

    fetcher = MetadataFetcher(base=page_node.url);
    page_node spawn fetcher;

    r = fetcher.result;
    summary = "complete" if r.is_complete() else "partial";
    print(f"[{summary}] title='{r.title}' manifest='{r.manifest_url}' icon='{r.icon_url}'");
    if r.failures {
        print(f"failures: {r.failures}");
    }
}

"""RBAC impersonation-grant auditor.

Models a Kubernetes RBAC policy graph: Roles/ClusterRoles contain Rules,
and Rules grant a set of (verbs, resources, resourceNames) tuples. A
walker audits every rule and flags impersonation grants that are not
scoped via resourceNames -- the "unconstrained impersonation" footgun
described in the issue.

The traversal replaces the hand-rolled recursion over parent/child
roles that the project used previously: typed edges carry the
containment relationships and the walker walks them natively.
"""

# --- Core entity archetypes --------------------------------------------------

node Rule {
    has verbs: list[str] = [];
    has resources: list[str] = [];
    has resource_names: list[str] = [];
    has label: str = "";
}

node Role {
    has name: str = "";
}

node ClusterRole {
    has name: str = "";
}

node RoleBinding {
    has name: str = "";
}

# --- Typed edges: relationships carry meaning -------------------------------

# A Role/ClusterRole owns a rule.
edge OwnsRule { }

# A RoleBinding references a Role (subject of impersonation check).
edge BindsRole { }

# A RoleBinding references a ClusterRole (subject of impersonation check).
edge BindsClusterRole { }

# --- Auditor walker ---------------------------------------------------------

walker ImpersonationAuditor {
    has flagged: list[str] = [];
    has allowed: list[str] = [];

    can audit with Rule entry {
        verbs = here.verbs;
        resources = here.resources;
        names = here.resource_names;

        grants_impersonate = ("impersonate" in verbs) or ("*" in verbs);
        targets_user_resource = False;
        for r in resources {
            if r in ["users", "groups", "serviceaccounts", "userextras"] {
                targets_user_resource = True;
            }
            if r == "*" {
                targets_user_resource = True;
            }
        }

        if grants_impersonate and targets_user_resource {
            if len(names) == 0 {
                self.flagged.append(here.label);
                report f"FLAG  {here.label}: impersonate on {resources} with no resourceNames";
            } else {
                self.allowed.append(here.label);
                report f"OK    {here.label}: scoped to {names}";
            }
        } else {
            self.allowed.append(here.label);
            report f"skip  {here.label}: not an impersonation grant";
        }
        visit [-->] else { disengage; }
    }
}

# --- Walker that reaches rules from anywhere in the graph --------------------

walker PolicyScan {
    can start with Root entry {
        visit [-->];
    }

    can descend with Role | ClusterRole | RoleBinding entry {
        visit [->:OwnsRule:->];
    }
}

# --- Demo wiring -------------------------------------------------------------

with entry {
    # A role with three rules: dangerous, safe-scoped, and unrelated.
    dev_role = Role(name="dev");
    dev_rule_bad = Rule(
        verbs=["impersonate"],
        resources=["users"],
        resource_names=[],
        label="dev/impersonate-users-unscoped",
    );
    dev_rule_good = Rule(
        verbs=["impersonate"],
        resources=["users"],
        resource_names=["alice", "bob"],
        label="dev/impersonate-users-scoped",
    );
    dev_rule_unrelated = Rule(
        verbs=["get", "list"],
        resources=["pods"],
        resource_names=[],
        label="dev/read-pods",
    );
    dev_role +>:OwnsRule:+> dev_rule_bad;
    dev_role +>:OwnsRule:+> dev_rule_good;
    dev_role +>:OwnsRule:+> dev_rule_unrelated;

    # A ClusterRole with wildcard impersonation -- also a flag.
    admin_cr = ClusterRole(name="admin");
    admin_rule = Rule(
        verbs=["*"],
        resources=["*"],
        resource_names=[],
        label="admin/wildcard-all",
    );
    admin_cr +>:OwnsRule:+> admin_rule;

    # A ClusterRole whose impersonation grant is scoped -- not a flag.
    sre_cr = ClusterRole(name="sre");
    sre_rule = Rule(
        verbs=["impersonate"],
        resources=["serviceaccounts"],
        resource_names=["system:serviceaccount:ns:default"],
        label="sre/impersonate-sa-scoped",
    );
    sre_cr +>:OwnsRule:+> sre_rule;

    # Bindings -- they reference roles but contain no rules themselves.
    binding_a = RoleBinding(name="dev-binding");
    binding_b = RoleBinding(name="admin-binding");
    binding_a +>:BindsRole:+> dev_role;
    binding_b +>:BindsClusterRole:+> admin_cr;

    # Wire the demo graph: root -> bindings -> roles -> rules
    # plus a standalone sre cluster role for completeness.
    root ++> binding_a ++> dev_role;
    root ++> binding_b ++> admin_cr;
    root ++> sre_cr;

    # Spawn the scan walker to descend through roles/clusterroles
    # and reach every rule via typed OwnsRule edges.
    root spawn PolicyScan();

    print("---- impersonation audit summary ----");
}

