}

edge Contains { }
edge Evidence { }
edge Interprets { }
edge Informs { }

walker PlanningAuditor {
    has seen_ids: list[str] = [];
    has current_revision: int = 0;
    has invalidation_pending: bool = False;
    has hop_limit: int = 12;
    has hops: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_workout with Workout entry {
        if self.hops >= self.hop_limit {
            print("Traversal stopped at the explicit cycle/depth guard");
            disengage;
        }
        self.hops += 1;
        if here.record_id in self.seen_ids {
            print(f"Cycle guard ignored repeated record {here.record_id}");
            disengage;
        }
        self.seen_ids.append(here.record_id);
        print(f"Session {here.session_id} on {here.session_date}");
        print(f"RPE={here.rpe}, RIR={here.rir}, energy={here.energy_score}");
        print(f"Programming note: {here.programming_note}");
        visit [->:Evidence:->] else { disengage; }
    }

    can inspect_feedback with Feedback entry {
        if self.hops >= self.hop_limit {
            print("Traversal stopped at the explicit cycle/depth guard");
            disengage;
        }
        self.hops += 1;
        if here.record_id in self.seen_ids {
            print(f"Cycle guard ignored repeated record {here.record_id}");
            disengage;
        }
        self.seen_ids.append(here.record_id);
        self.current_revision = here.revision;
        print(f"Question v{here.question_version}: {here.question_text}");
        print(f"Answer {here.response_id}: {here.answer_text}");
        print(f"Native value: {here.native_value}");
        print(f"Timing={here.timing}, source={here.source_uri}, provenance={here.provenance}");
        print(f"Region={here.body_region}, laterality={here.laterality}, concern={here.concern_ref}");
        print(f"Pain evidence={here.pain_present}, energy={here.energy_score}");
        print("This is localized symptom evidence, not poor recovery.");
        print(f"Historical answer {here.prior_response_id}: {here.prior_answer_text}");
        if here.next_checkin_answered {
            print("A next-check-in answer exists.");
        } else {
            print("No next-morning answer is invented; the observation remains unknown.");
        }
        if here.legacy_untrusted {
            print("Legacy-untrusted data is excluded from the actionable summary.");
        }
        visit [->:Interprets:->] else { disengage; }
    }

    can inspect_interpretation with Interpretation entry {
        if self.hops >= self.hop_limit {
            print("Traversal stopped at the explicit cycle/depth guard");
            disengage;
        }
        self.hops += 1;
        if here.record_id in self.seen_ids {
            print(f"Cycle guard ignored repeated record {here.record_id}");
            disengage;
        }
        self.seen_ids.append(here.record_id);
        if here.based_on_revision != self.current_revision {
            self.invalidation_pending = True;
            here.superseded = True;
            here.actionable = False;
            print(f"Superseded interpretation: {here.summary}");
        } else {
            print(f"Actionable interpretation: {here.summary}");
        }
        visit [->:Informs:->] else { disengage; }
    }

    can inspect_recommendation with Recommendation entry {
        if self.hops >= self.hop_limit {
            print("Traversal stopped at the explicit cycle/depth guard");
            disengage;
        }
        self.hops += 1;
        if here.record_id in self.seen_ids {
            print(f"Cycle guard ignored repeated record {here.record_id}");
            disengage;
        }
        self.seen_ids.append(here.record_id);
        if self.invalidation_pending {
            here.cache_valid = False;
            here.disposition = "revise";
            here.audit_history = f"Invalidated after response revision {self.current_revision}";
            here.future_note = "Retain tib-bar instruction only if the toe flare is calm during ordinary walking/setup; ask a targeted tib-bar tolerance question.";
            here.template_default = "Keep the general pain-stop safeguard; do not retire the universal default from one-off tolerance.";
            print("Outdated recommendation cache invalidated.");
            print(f"Disposition: {here.disposition}");
            print(f"Future note: {here.future_note}");
            print(f"Template default: {here.template_default}");
            print(f"Audit: {here.audit_history}");
        } else {
            print(f"Recommendation remains valid: {here.future_note}");
        }
    }
}

