"""Financial QA knowledge-graph demo: KG-RAG vs vector-RAG, hop-stratified.

Models the scenario from Shah et al. (2024): a knowledge graph built from
10-K filings, traversed by hop count to answer multi-hop questions about
cross-subsidiary ownership and company comparisons. The walker explicitly
stratifies questions by hop count and reports where KG traversal pays off.
"""

node Company {
    has name: str = "";
    has ticker: str = "";
    has sector: str = "";
}

node Subsidiary {
    has name: str = "";
    has ownership_pct: float = 0.0;
}

node Question {
    has text: str = "";
    has hops: int = 0;
    has qtype: str = "";
}

edge Owns {
    has since: str = "";
    has filed_period: str = "";
}

edge Compares {
    has metric: str = "";
}

walker KgRag {
    has answered: int = 0;
    has by_hop: dict[int, int] = {};
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_questions with Question entry {
        q = here;
        self.visited = self.visited + [q.text];
        self.answered = self.answered + 1;
        bucket = self.by_hop.get(q.hops, 0);
        self.by_hop[q.hops] = bucket + 1;
        print(f"[KG-RAG qtype={q.qtype} hops={q.hops}] {q.text}");
        visit [-->];
    }

    can walk_owns with Company entry {
        print(f"  parent: {here.name} ({here.ticker})");
        visit [->:Owns:->];
    }

    can reach_subsidiary with Subsidiary entry {
        print(f"  -> subsidiary: {here.name} ({here.ownership_pct}%)");
    }

    can reach_compare with Company entry {
        visit [->:Compares:->];
    }
}

walker VectorRag {
    has answered: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan_questions with Question entry {
        self.answered = self.answered + 1;
        if here.hops == 1 {
            print(f"[Vector-RAG single-hop OK] {here.text}");
        } elif here.hops == 2 {
            print(f"[Vector-RAG struggles] {here.text}");
        } else {
            print(f"[Vector-RAG fails] {here.text}");
        }
        visit [-->];
    }
}

