    print(f"Gaps found: {auditor.gaps}");
}

"""RIPR TestEvidenceSummaryV1: model the bounded evidence graph that a
producer walks to assert relevance against a declared evidence purpose.

Entities are RIPR's typed facts (test, fixture, oracle, source) joined by
typed edges (selector/owner, fixture-of, oracle-of, limits). A walker
projects them onto a single bounded summary and detects what's missing.
"""

# ---- Node archetypes ---------------------------------------------------------

node Test {
    has name: str = "";
    has kind: str = "";          # "unit" | "integration" | "fixture" | "checker"
    has source_range: str = "";  # "tests.rs:42-58"
}

node Owner {
    has target: str = "";        # production target candidate
    has relation_reason: str = "";
    has confidence: float = 0.0;
}

node Oracle {
    has text: str = "";          # bounded oracle text or normalized shape
    has kind: str = "";          # "exact" | "variant" | "broad_err" | "snapshot" | "absence"
    has strength: str = "";      # "strong" | "weak"
}

node Limitation {
    has kind: str = "";          # "macro_opaque" | "dynamic_dispatch" | "name_only" | "stale_source" | ...
    has detail: str = "";
}

# ---- Typed edges -------------------------------------------------------------

edge Selects { }       # Root -> Test (test/fixture selector identity)
edge OwnerOf { has confidence: float = 0.0; }   # Test -> Owner
edge OracleOf { }      # Test -> Oracle
edge FixtureOf { }     # Test -> Fixture (uses)
edge LimitationOf { }  # Test -> Limitation

node Fixture {
    has path: str = "";
    has golden_identity: str = "";
}

# ---- Walker ------------------------------------------------------------------

walker EvidenceSummary {
    has purpose: str = "Error::Boundary variant";   # declared evidence purpose
    has summary_lines: list[str] = [];

    can start with Root entry {
        # Find the bounded test selector first.
        visit [-->];
    }

    can project with Test entry {
        self.summary_lines.append(f"TEST {here.kind}::{here.name} @ {here.source_range}");

        # Owners (relation reason + confidence)
        for owner in [->:OwnerOf:->] {
            self.summary_lines.append(
                f"  owner={owner.target} reason={owner.relation_reason} "
                f"conf={owner.confidence:.2f}"
            );
        }

        # Oracles: classify as exact vs broad.
        for oracle in [->:OracleOf:->] {
            label = "EXACT" if oracle.kind == "exact" or oracle.kind == "variant" else "BROAD";
            self.summary_lines.append(
                f"  oracle[{label}] kind={oracle.kind} strength={oracle.strength} :: {oracle.text}"
            );
        }

        # Fixtures.
        for fix in [->:FixtureOf:->] {
            self.summary_lines.append(
                f"  fixture={fix.path} golden={fix.golden_identity}"
            );
        }

        # Limitations: surfaced as negative evidence.
        for lim in [->:LimitationOf:->] {
            self.summary_lines.append(
                f"  LIMIT[{lim.kind}] {lim.detail}"
            );
        }

        # Negative/alternate evidence inferred from gap between oracles and purpose.
        has_exact_variant = False;
        for oracle in [->:OracleOf:->] {
            if oracle.kind == "exact" or oracle.kind == "variant" {
                has_exact_variant = True;
            }
        }
        if not has_exact_variant {
            self.summary_lines.append(
                "  MISSING: no exact/variant oracle (only broad assertions present)"
            );
        }
        if not [->:FixtureOf:->] {
            self.summary_lines.append("  MISSING: no fixture/golden observer");
        }

        # Purpose relevance verdict — the whole point of the producer.
        verdict = "RELEVANT" if has_exact_variant and [->:FixtureOf:->] else "PARTIAL";
        self.summary_lines.append(f"VERDICT vs purpose '{self.purpose}': {verdict}");

        # Don't fan out into owners/fixtures — projection terminates at Test.
        disengage;
    }
}

# ---- Demo wiring -------------------------------------------------------------

with entry {
    # The famous failure: rejects_boundary only asserts is_err(), never Error::Boundary.
    t = Test(
        name="rejects_boundary",
        kind="unit",
        source_range="tests/boundary.rs:42-58"
    );

    # Two owner candidates (relation by name proximity + one strong).
    t +>:OwnerOf(confidence=0.92):+> Owner(
        target="validate_boundary",
        relation_reason="name-token proximity",
        confidence=0.92
    );
    t +>:OwnerOf(confidence=0.30):+> Owner(
        target="format_error",
        relation_reason="unrelated neighbor",
        confidence=0.30
    );

    # Broad oracle only — no exact variant assertion.
    t +>:OracleOf:+> Oracle(
        text="assert!(result.is_err())",
        kind="broad_err",
        strength="weak"
    );

    # Static limitation: macro-generated dispatch hides the sink.
    t +>:LimitationOf:+> Limitation(
        kind="dynamic_dispatch",
        detail="called helper resolves through macro; sink family unknown"
    );

    # No FixtureOf edge — fixture observer is missing.
    # (deliberately absent so the MISSING line appears)

    root +>:Selects:+> t;

    producer = EvidenceSummary(purpose="Error::Boundary variant");
    root spawn producer;

    print("=== TestEvidenceSummaryV1 ===");
    for line in producer.summary_lines {
        print(line);
    }
}

"""Meta ownership guard for EnsureConversationMeta.

Models the bug from issue #1352: a second EnsureConversationMeta call with
a different repo path must NOT repoint the workspace ownership fields that
PreserveConversationMeta guards. The naive ON CONFLICT overwrite races on
workspace ownership. The fix applies CASE guards so existing ownership wins.
"""

node Workspace {
    has name: str = "";
    has owner: str = "";
    has repo: str = "";
    has branch: str = "";
    has initialized: bool = False;
}

node Conversation {
    has title: str = "";
    has summary: str = "";
    has linked_workspace: str = "";
}

edge Owns {
    has since: str = "";
}

edge References {
    has role: str = "primary";
}

walker EnsureConversationMeta {
    has incoming_repo: str = "";
    has incoming_branch: str = "";
    has log: dict = {};

    can start with Root entry {
        # Walk every conversation and ensure its meta, but only with
        # ownership-preserving semantics (the issue's acceptance criterion).
        visit [-->];
    }

    can preserve with Conversation entry {
        ws_name = here.linked_workspace;
        if ws_name == "" {
            # No linked workspace — nothing to preserve against.
            self.log[here.title] = "no-workspace-skip";
            disengage;
        }

        # The next hop is the owned Workspace (typed edge traversal).
        visit [here ->:Owns:->];
    }

    can apply_guards with Workspace entry {
        # CASE-guard semantics: existing ownership fields win on conflict.
        # The "second run with different repo path" must NOT repoint
        # workspace.name, workspace.owner, or workspace.branch.
        kept_name = here.name;

        # Simulate the second call arriving with a different repo/branch.
        would_repoint = False;
        if here.initialized and here.repo != "" and here.repo != self.incoming_repo {
            would_repoint = True;
        }
        if here.initialized and here.branch != "" and here.branch != self.incoming_branch {
            would_repoint = True;
        }

        if would_repoint {
            # Guard fires: keep existing ownership, only update non-ownership
            # bookkeeping. This is the PreserveConversationMeta contract.
            self.log[kept_name] = (
                f"preserved owner={here.owner} repo={here.repo} "
                f"branch={here.branch}; rejected incoming "
                f"repo={self.incoming_repo} branch={self.incoming_branch}"
            );
        } else {
            # First-time init or matching repo/branch: safe to take it.
            here.repo = self.incoming_repo;
            here.branch = self.incoming_branch;
            here.initialized = True;
            self.log[kept_name] = (
                f"initialized repo={here.repo} branch={here.branch}"
            );
        }
    }
}

walker Audit {
    has findings: list = [];

    can start with Root entry {
        visit [-->];
    }

    can list_convo with Conversation entry {
        self.findings.append(f"conversation={here.title} -> ws={here.linked_workspace}");
        visit [-->];
    }

    can list_ws with Workspace entry {
        self.findings.append(
            f"workspace={here.name} owner={here.owner} "
            f"repo={here.repo} branch={here.branch} init={here.initialized}"
        );
    }
}

with entry {
    # Two workspaces with distinct ownership already established.
    alpha = Workspace(
        name="alpha",
        owner="alice",
        repo="github.com/alice/core",
        branch="main",
        initialized=True,
    );
    beta = Workspace(
        name="beta",
        owner="bob",
        repo="github.com/bob/utils",
        branch="dev",
        initialized=True,
    );
    gamma = Workspace(
        name="gamma",
        owner="",
        repo="",
        branch="",
        initialized=False,
    );

    root ++> alpha;
    root ++> beta;
    root ++> gamma;

    convo1 = Conversation(title="design-review", linked_workspace="alpha");
    convo2 = Conversation(title="bug-triage", linked_workspace="beta");
    convo3 = Conversation(title="kickoff", linked_workspace="gamma");
