"""Approved Data View demo: bounded roles, source-owned collections, and availability-filtered fields.

Models the Phase 18 slice: one root subject (a donor statement), finite named roles
resolved via typed edges to source records, an immutable ordered collection of gifts
bounded by max items and overflow semantics, and an 'Available in documents' switch
that narrows which fields templates may touch. A walker assembles the Facts Package
the template engine will admit, respecting explicit cycle policy and dead-end handling.
"""

node ApprovedField {
    has semantic_id: str = "";
    has label: str = "";
    has available: bool = True;
}

node Donor {
    has name: str = "";

    def summary() -> str {
        return self.name;
    }
}

node Gift {
    has amount: float = 0.0;

    def summary() -> str {
        return f"${self.amount}";
    }
}

edge NamedRole {
    has role: str = "";
    has cardinality: str = "exactly_one";
}

edge GiftLine {
    has order_idx: int = 0;
}

walker FactsBuilder {
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can build with Donor entry {
        if here in self.visited {
            disengage;
        }
        self.visited.append(here);
        print(f"Facts root subject: donor {here.name}");
        visit [->:NamedRole:->];
    }

    can collect_role with ApprovedField entry {
        if not here.available {
            disengage;
        }
        print(f"  field {here.semantic_id} ({here.label}) available");
    }
}

with entry {
    donor = Donor(name="A. Generous");
    root ++> donor;

    donor +>:NamedRole(role="legal_recipient", cardinality="exactly_one"):+>
        ApprovedField(semantic_id="donor.full_name", label="Donor Full Name");

    donor +>:NamedRole(role="tribute_honoree", cardinality="zero_or_one"):+>
        ApprovedField(semantic_id="honoree.name", label="Honoree", available=False);

    gift1 = Gift(amount=100.0);
    gift2 = Gift(amount=250.0);
    gift3 = Gift(amount=75.0);

    donor +>:GiftLine(order_idx=0):+> gift1;
    donor +>:GiftLine(order_idx=1):+> gift2;
    donor +>:GiftLine(order_idx=2):+> gift3;

    root spawn FactsBuilder();
}

