"""Terminal attachment graph with safe nesting and explicit cycle detection."""

node Server {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has incarnation_id: str = "";
}

node Terminal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has server_incarnation_id: str = "";
    has terminal_id: str = "";
    has socket_name: str = "";

    def identity() -> str {
        return f"{self.server_incarnation_id}/{self.terminal_id}";
    }
}

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
    has name: str = "";
}

edge Hosts { }
edge Attaches { }
edge Displays {
    has hop: int = 0;
}
edge CycleStart { }
edge SelfStart { }
edge SafeStart { }

walker CycleGuard {
    has seen_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:CycleStart:->] else {
            disengage;
        }
    }

    can follow with Session entry {
        print(f"checking session {here.name}");
        visit [->:Attaches:->] else {
            disengage;
        }
    }

    can inspect with Terminal entry {
        identity = here.identity();
        if identity in self.seen_ids {
            self.cycle_found = True;
            print(f"REJECTED cyclic display at {identity}");
            disengage;
        } else {
            self.seen_ids = self.seen_ids + [identity];
            print(f"displaying {here.socket_name} on {identity}");
            visit [->:Displays:->] else {
                disengage;
            }
        }
    }
}

walker SelfViewGuard {
    has seen_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:SelfStart:->] else {
            disengage;
        }
    }

    can follow with Session entry {
        print(f"checking session {here.name}");
        visit [->:Attaches:->] else {
            disengage;
        }
    }

    can inspect with Terminal entry {
        identity = here.identity();
        if identity in self.seen_ids {
            self.cycle_found = True;
            print(f"REJECTED direct self-view at {identity}");
            disengage;
        } else {
            self.seen_ids = self.seen_ids + [identity];
            visit [->:Displays:->] else {
                disengage;
            }
        }
    }
}

walker SafePathAudit {
    has seen_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:SafeStart:->] else {
            disengage;
        }
    }

    can follow with Session entry {
        print(f"checking safe session {here.name}");
        visit [->:Attaches:->] else {
            disengage;
        }
    }

    can inspect with Terminal entry {
        identity = here.identity();
        if identity in self.seen_ids {
            self.cycle_found = True;
            print(f"REJECTED unexpected cycle at {identity}");
            disengage;
        } else {
            self.seen_ids = self.seen_ids + [identity];
            print(f"safe target {here.socket_name} on {identity}");
            visit [->:Displays:->] else {
                disengage;
            }
        }
    }
}

