"""TLAS BUILD-vs-UPDATE gate: ordered BLAS layout compare fails when draw-sort permutes."""

node DrawInstance {
    has entity_id: int = 0;
    has blas_address: int = 0;
    has sort_depth: float = 0.0;
    has in_raster: bool = True;
}

node DrawSequence {
    has frame_label: str = "";
}

node TlasCache {
    has cached_addresses: list[int] = [];
    has blas_map_generation: int = 0;
}

edge DrawOrder { }

walker OrderedLayoutGate {
    has cache_ref: TlasCache;
    has collected: list[int] = [];
    has decision: str = "BUILD";

    def addresses_match_ordered(cached: list[int], current: list[int]) -> bool {
        if len(cached) != len(current) {
            return False;
        }
        for i in range(len(cached)) {
            if cached[i] != current[i] {
                return False;
            }
        }
        return True;
    }

    def decide() {
        cached = self.cache_ref.cached_addresses;
        if len(cached) == 0 {
            self.decision = "BUILD";
        } elif self.addresses_match_ordered(cached, self.collected) {
            self.decision = "UPDATE";
        } else {
            self.decision = "BUILD";
        }
    }

    can head with DrawSequence entry {
        visit [->:DrawOrder:->] else { disengage; };
    }

    can collect with DrawInstance entry {
        self.collected.append(here.blas_address);
        visit [->:DrawOrder:->] else {
            self.decide();
            disengage;
        };
    }
}

walker StableLayoutGate {
    has cache_ref: TlasCache;
    has collected: list[int] = [];
    has decision: str = "BUILD";

    def sorted_copy(src: list[int]) -> list[int] {
        out: list[int] = [];
        for v in src {
            out.append(v);
        }
        out.sort();
        return out;
    }

    def addresses_match_stable(cached: list[int], current: list[int]) -> bool {
        if len(cached) != len(current) {
            return False;
        }
        a = self.sorted_copy(cached);
        b = self.sorted_copy(current);
        for i in range(len(a)) {
            if a[i] != b[i] {
                return False;
            }
        }
        return True;
    }

    def decide() {
        cached = self.cache_ref.cached_addresses;
        if len(cached) == 0 {
            self.decision = "BUILD";
        } elif self.addresses_match_stable(cached, self.collected) {
            self.decision = "UPDATE";
        } else {
            self.decision = "BUILD";
        }
    }

    can head with DrawSequence entry {
        visit [->:DrawOrder:->] else { disengage; };
    }

    can collect with DrawInstance entry {
        self.collected.append(here.blas_address);
        visit [->:DrawOrder:->] else {
            self.decide();
            disengage;
        };
    }
}

with entry {
    cache = TlasCache(blas_map_generation=1);
    root ++> cache;

    inst_a = DrawInstance(
        entity_id=10, blas_address=0xA100, sort_depth=12.5, in_raster=True
    );
    inst_b = DrawInstance(
        entity_id=20, blas_address=0xB200, sort_depth=8.3, in_raster=False
    );
    inst_c = DrawInstance(
        entity_id=30, blas_address=0xC300, sort_depth=15.1, in_raster=False
    );

    frame1 = DrawSequence(frame_label="frame-1-initial");
    root ++> frame1;
    frame1 +>:DrawOrder:+> inst_a;
    inst_a +>:DrawOrder:+> inst_b;
    inst_b +>:DrawOrder:+> inst_c;

    gate1 = OrderedLayoutGate(cache_ref=cache);
    frame1 spawn gate1;
    print(f"{frame1.frame_label}: ordered gate -> {gate1.decision}");
    cache.cached_addresses = gate1.collected;

    frame2 = DrawSequence(frame_label="frame-2-churned");
    root ++> frame2;
    frame2 +>:DrawOrder:+> inst_b;
    inst_b +>:DrawOrder:+> inst_a;
    inst_a +>:DrawOrder:+> inst_c;

    gate2 = OrderedLayoutGate(cache_ref=cache);
    frame2 spawn gate2;
    print(
        f"{frame2.frame_label}: ordered gate -> {gate2.decision} "
        f"(false BUILD: order changed, generation still {cache.blas_map_generation})"
    );

    stable = StableLayoutGate(cache_ref=cache);
    frame2 spawn stable;
    print(
        f"{frame2.frame_label}: stable multiset gate -> {stable.decision} "
        f"(cheap refit path restored)"
    );
}

"""Lab audit lineage — immutable source values vs versioned normalized data.

Models the core scenario from issue #7: verified (human-corrected)
transcriptions are immutable SourceValue records. Normalized Analyte and
Conversion records derive from them via typed edges and carry
mapping_version / conversion_version. A walker re-derives the full
normalized view deterministically from sources, so a mapping bug is
fixed by recomputation, not by re-OCR.
"""

node SourceValue {
    has analyte_label: str = "";
    has value_text: str = "";
    has value_num: float = 0.0;
    has unit: str = "";
    has reference_text: str = "";
    has page: int = 0;
}

node Analyte {
    has analyte_code: str = "";
    has mapping_version: str = "";
}

node Conversion {
    has from_unit: str = "";
    has to_unit: str = "";
    has factor: float = 1.0;
    has conversion_version: str = "";
}

node Quarantine {
    has reason: str = "";
}

edge Verified { has verifier: str = ""; }
edge MapsTo { }
edge Normalizes { has conversion_version: str = ""; }
edge Quarantined { has reason: str = ""; }

walker Derive {
    has mapping_version: str = "v1";
    has conversion_version: str = "v1";

    can start with Root entry {
        visit [-->];
    }

    can derive with SourceValue entry {
        if here.value_text == "" or here.analyte_label == "" {
            q = Quarantine(reason="unknown_analyte");
            here +>:Quarantined(reason="unknown_analyte"):+> q;
            print(f"QUARANTINED page {here.page}: empty value_text or analyte_label");
            disengage;
        }

        analyte = Analyte(
            analyte_code=here.analyte_label.upper(),
            mapping_version=self.mapping_version
        );
        here +>:MapsTo:+> analyte;

        conv = Conversion(
            from_unit=here.unit,
            to_unit=here.unit,
            factor=1.0,
            conversion_version=self.conversion_version
        );
        here +>:Normalizes(conversion_version=self.conversion_version):+> conv;

        print(
            f"derived page={here.page} source='{here.analyte_label}' "
            f"value={here.value_num} {here.unit} "
            f"-> code={analyte.analyte_code} "
            f"map={analyte.mapping_version} conv={conv.conversion_version}"
        );
        visit [-->];
    }
}

with entry {
    sv1 = SourceValue(
        analyte_label="Glucose",
        value_text="142",
        value_num=142.0,
        unit="mg/dL",
        reference_text="70-99",
        page=3
    );
    sv2 = SourceValue(
        analyte_label="HbA1c",
        value_text="5.8",
        value_num=5.8,
        unit="%",
        reference_text="<5.7",
        page=3
    );
    sv3 = SourceValue(
        analyte_label="",
        value_text="?",
        value_num=0.0,
        unit="pg/mL",
        reference_text="n/a",
        page=4
    );

    root ++> sv1 ++> sv2 ++> sv3;

    print("Deriving normalized view from immutable sources:");
    root spawn Derive(mapping_version="v1", conversion_version="v1");

    print("");
    print("Source fields are untouched; re-derive with a new mapping_version");
    print("to fix a conversion bug without re-OCR.");
}

"""Deletion Vector index recovery.

Models the Iceberg scan-planning recovery for a snapshot containing
multiple deletion vectors (DVs) that point at the same data file.
The walker mirrors the read-side ``DeleteFileIndex.Builder.build()``
post-pass: byte-identical duplicates are deduplicated, and genuinely
different DVs are unioned instead of being silently dropped. The
table never throws the ``Can't index multiple DVs`` ValidationException
once this recovery walker has indexed the snapshot.
"""

# --- Puffin blob: opaque payload carried by a deletion vector. ---
node PuffinBlob {
    has offset: int = 0;
    has size: int = 0;
    has location: str = "";
    has positions: list[int] = [];
}

# --- Deletion vector: a single Puffin blob keyed to one data file. ---
node DeletionVector {
    has dv_id: str = "";
    has referenced_data_file: str = "";
    has blob: PuffinBlob = PuffinBlob();
}

# --- Data file: the file whose rows are being deleted from. ---
node DataFile {
    has path: str = "";
    has record_count: int = 0;
}

# --- Snapshot: the live delete-manifest entries of one Iceberg snapshot. ---
node Snapshot {
    has snapshot_id: int = 0;
}

# Typed edges -- declared at module level so the visit/connect syntax compiles.
edge ManifestEntry {}     # Snapshot --holds--> DeletionVector | DataFile
edge Targets {}           # DeletionVector --targets--> DataFile
edge IndexedDeletes {}    # Snapshot --indexed--> DeletionVector (post-recovery)

walker IndexRecovery {
    # Per-data-file accumulator of candidate DVs seen in the manifest.
    has dv_by_path: dict[str, list[DeletionVector]] = {};
    # Final, deduplicated / merged DVs per data file.
    has indexed: dict[str, DeletionVector] = {};
    # Track which data files have been seen in this snapshot (one entry per file).
    has seen_files: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can enter_snapshot with Snapshot entry {
        # Clear walker state so a re-spawn is idempotent.
        self.dv_by_path = {};
        self.indexed = {};
        self.seen_files = {};
        visit [->:ManifestEntry:->];
    }

    can collect_dv with DeletionVector entry {
        target = here.referenced_data_file;
        bucket = self.dv_by_path.get(target, []);
        bucket.append(here);
        self.dv_by_path[target] = bucket;
        visit [-->];
    }

    can note_file with DataFile entry {
        self.seen_files[here.path] = True;
        visit [-->];
    }

    def finish_snapshot() -> None {
        # Post-pass: the equivalent of ``Builder.build()`` in Iceberg.
        # We cannot trigger this from a Snapshot exit ability in a way that
        # sees ``here`` reliably across spawn, so we run it directly below
        # after traversal completes; the walker report still carries state.
        for (path, candidates) in self.dv_by_path.items() {
            survivor = self.merge_or_dedup(candidates);
            self.indexed[path] = survivor;
            if len(candidates) > 1 {
                all_same = True;
                first_key = IndexRecovery.blob_key(candidates[0].blob);
                for dv in candidates[1:] {
                    if IndexRecovery.blob_key(dv.blob) != first_key {
                        all_same = False;
                        break;
                    }
                }
                verdict_label = "byte-identical duplicate" if all_same else "merged union";
                print(f"[WARN] {len(candidates)} DVs for {path} -> {verdict_label} ({survivor.blob.positions})");
            }
        }
        report self.indexed;
    }

    # ---- helpers (plain defs, not walker abilities) ----

    static def blob_key(b: PuffinBlob) -> str {
        return f"{b.location}|{b.offset}|{b.size}";
    }

    def merge_or_dedup(candidates: list[DeletionVector]) -> DeletionVector {
        # Case 1: single DV -- nothing to do.
        if len(candidates) == 1 {
            return candidates[0];
        }
        # Case 2: every DV is byte-identical -- keep the first, drop the rest.
        first_key = IndexRecovery.blob_key(candidates[0].blob);
        all_same = True;
        for dv in candidates[1:] {
            if IndexRecovery.blob_key(dv.blob) != first_key {
                all_same = False;
                break;
            }
        }
        if all_same {
            return candidates[0];
        }
        # Case 3: genuinely different DVs -- union the position bitmaps.
        merged: list[int] = [];
        for dv in candidates {
            for p in dv.blob.positions {
                if p not in merged {
                    merged.append(p);
                }
            }
        }
        merged.sort();
        survivor = DeletionVector(
            dv_id=f"merged({candidates[0].dv_id},{candidates[1].dv_id})",
            referenced_data_file=candidates[0].referenced_data_file,
            blob=PuffinBlob(
                offset=0,
                size=sum(d.blob.size for d in candidates),
                location=candidates[0].blob.location,
                positions=merged,
            ),
        );
        return survivor;
    }
}

with entry {
    # --- graph wiring ---------------------------------------------------
    snap = Snapshot(snapshot_id=42);
    root ++> snap;

    df = DataFile(path="s3://warehouse/data/part-00000.parquet", record_count=1000);

    # Manifest entry #1: a "real" DV that deletes rows [10, 20, 30].
    dv_real = DeletionVector(
        dv_id="dv-A",
        referenced_data_file=df.path,
        blob=PuffinBlob(offset=0, size=128, location="s3://warehouse/dv/dv-A.puffin", positions=[10, 20, 30]),
    );
    # Manifest entry #2: byte-identical duplicate (manifest-rewrite race).
    dv_dup = DeletionVector(
        dv_id="dv-A-copy",
        referenced_data_file=df.path,
        blob=PuffinBlob(offset=0, size=128, location="s3://warehouse/dv/dv-A.puffin", positions=[10, 20, 30]),
    );
    # Manifest entry #3: genuinely different DV that deletes [40, 50]
    # -- the spec violation that previously bricked the table.
    dv_other = DeletionVector(
        dv_id="dv-B",
        referenced_data_file=df.path,
        blob=PuffinBlob(offset=0, size=128, location="s3://warehouse/dv/dv-B.puffin", positions=[40, 50]),
    );
    snap +>:ManifestEntry:+> dv_real;
    snap +>:ManifestEntry:+> dv_dup;
    snap +>:ManifestEntry:+> dv_other;

    for d in [dv_real, dv_dup, dv_other] {
        d +>:Targets:+> df;
    }

    # --- run the recovery walker -----------------------------------
    print(f"Before recovery: snapshot {snap.snapshot_id} has 3 DV manifest entries for {df.path}");
    w = IndexRecovery();
    result = root spawn w;
    # Run the post-pass finalize step (mirrors Builder.build()'s final loop).
    w.finish_snapshot();
    print(f"After  recovery: {len(result.indexed)} DV indexed for {df.path}");
    final_dv = result.indexed[df.path];
    print(f"Final DV id={final_dv.dv_id} positions={final_dv.blob.positions} "
          f"(union of all DVs -- no deletes dropped)");
}

"""Activity feed as a graph: User and Post nodes with FOLLOWS/AUTHORED edges,
exercised by walkers that perform shortest-path, 2-hop recommendations, and
common-neighbor queries natively on typed edges."""

node User {
    has username: str = "";
    has joined: str = "";
}

node Post {
    has title: str = "";
    has body: str = "";
}

edge Follows {
    has since: str = "";
}

edge Authored {
    has at: str = "";
}

walker ShortestChain {
    has source_name: str = "";
    has target_name: str = "";
    has hops: int = 0;
    has path: list[str] = [];
    has visited: list[str] = [];
    has done: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can walk with User entry {
        if self.done {
            disengage;
        }
        already = False;
        for v in self.visited {
            if v == here.username {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited = self.visited + [here.username];
        if here.username == self.target_name {
            self.done = True;
            disengage;
        }
        self.path = self.path + [here.username];
        self.hops = self.hops + 1;
        visit [->:Follows:->] else { disengage; }
    }
}

walker RecommendFriends {
    has seed_name: str = "";
    has seen: list[str] = [];
    has picks: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can seed with User entry {
        if here.username != self.seed_name {
            visit [-->];
        }
        self.seen = self.seen + [here.username];
        visit [->:Follows:->];
    }

    can hop with User entry {
        already = False;
        for v in self.seen {
            if v == here.username {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen = self.seen + [here.username];
        visit [->:Follows:->];
    }

    can candidate with User entry {
        if (here.username != self.seed_name) {
            dup = False;
            for p in self.picks {
                if p == here.username {
                    dup = True;
                }
            }
            if not dup {
                self.picks = self.picks + [here.username];
            }
        }
    }
}

walker CommonNeighbors {
    has a_name: str = "";
    has b_name: str = "";
    has common: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can first with User entry {
        if here.username != self.a_name {
            visit [-->];
        }
        visit [->:Follows:->];
    }

    can second with User entry {
        if here.username != self.b_name {
            visit [-->];
        }
        visit [->:Follows:->];
    }

    can collect with User entry {
        if (here.username != self.a_name) and (here.username != self.b_name) {
            self.common = self.common + [here.username];
        }
    }
}

