    has owner: str = "";
    has removed_posts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick with User entry {
        if here.username != self.owner {
            visit [-->];
        }
        visit [->:Authored:->];
    }

    can collect_post with Post entry {
        self.removed_posts = self.removed_posts + [here.title];
        del here;
    }
}

