}

node Chart {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has time_basis: str = "";
    has day_boundary: str = "";
}

node RuleSet {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: str = "";
    has supported_range: str = "";
}

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has citation: str = "";
}

edge ContainsCase { }
edge HasChart { }
edge UsesRuleSet { has purpose: str = ""; }
edge CitesSource { has role: str = ""; }
edge DependsOn { has reason: str = ""; }

walker ProvenanceReview {
    has seen_titles: list[str] = [];
    has visited_count: int = 0;

    can start with Root entry {
        print("Reviewing local Taiyi cases");
        visit [->:ContainsCase:->] else { disengage; }
    }

    can inspect_case with Case entry {
        if here.title in self.seen_titles {
            print(f"Cycle guard stopped at case {here.title}");
            disengage;
        }
        self.seen_titles.append(here.title);
        self.visited_count += 1;
        print(f"Case: {here.title} [{here.civil_time} {here.time_zone}]");
        visit [->:HasChart:->] else { disengage; }
    }

    can inspect_chart with Chart entry {
        self.visited_count += 1;
        print(f"Chart: {here.title}, basis={here.time_basis}, boundary={here.day_boundary}");
        visit [->:UsesRuleSet:->] else { disengage; }
    }

    can inspect_rules with RuleSet entry {
        self.visited_count += 1;
        print(f"Rule set: {here.title} revision {here.revision}");
        print(f"Reference range: {here.supported_range}");
        visit [->:CitesSource:->] else { disengage; }
    }

    can inspect_source with Source entry {
        self.visited_count += 1;
        print(f"Source: {here.title} ({here.citation})");
        visit [-->] else { disengage; }
    }
}

walker DependencyAudit {
    has seen_rules: list[str] = [];

    can inspect with RuleSet entry {
        if here.title in self.seen_rules {
            print(f"Dependency cycle detected at {here.title}");
            disengage;
        }
        self.seen_rules.append(here.title);
        print(f"Checking dependency: {here.title}");
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
    case_one = Case(
        title="Winter question",
        year=2024,
