"""pnpm 11 deduped dependency collector: model the bug and the fix.

Models the essential scenario: a workspace where two projects share a
dependency graph that pnpm 11 emits as deduped stubs. The collector walker
demonstrates (a) the buggy visited-set pruning that drops subtrees, and
(b) the patched walker that re-walks children of already-visited nodes so
the fully-expanded subtree is never lost.
"""

node Project {
    has name: str = "";
    has is_app: bool = False;
}

node Pkg {
    has name: str = "";
    has version: str = "";
    has has_children: bool = False;
    has deduped: bool = False;
}

edge DependsOn { }

walker CollectBuggy {
    has collected: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_proj with Project entry {
        visit [->:DependsOn:->];
    }

    can collect with Pkg entry {
        id = f"{here.name}@{here.version}";
        if id in self.visited {
            # BUG: prunes the entire subtree when the first-visited
            # occurrence was a deduped stub with no children. The later
            # occurrence that carries the real expanded subtree is
            # never walked.
            return;
        }
        self.visited.append(id);
        self.collected.append(id);
        if here.has_children {
            visit [->:DependsOn:->];
        }
    }
}

walker CollectPatched {
    has collected: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_proj with Project entry {
        visit [->:DependsOn:->];
    }

    can collect with Pkg entry {
        id = f"{here.name}@{here.version}";
        if id in self.visited {
            # PATCH: re-walk this occurrence's children even though the
            # node itself is already visited, so the fully-expanded
            # subtree (which pnpm 11 may emit at a later occurrence) is
            # never lost. Still O(total nodes) because each JSON node is
            # structurally visited at most once.
            if here.has_children {
                visit [->:DependsOn:->];
            }
            return;
        }
        self.visited.append(id);
        self.collected.append(id);
        if here.has_children {
            visit [->:DependsOn:->];
        }
    }
}

with entry {
    web = Project(name="web");
    app = Project(name="app");

    # web's chain carries the only full expansion of mime-types.
    api = Pkg(name="api", version="1.0.0", has_children=True);
    trpc_server_stub = Pkg(name="@trpc/server", version="11.0.0", has_children=False, deduped=True);
    trpc_client = Pkg(name="@trpc/client", version="11.0.0", has_children=True);
    trpc_server_full = Pkg(name="@trpc/server", version="11.0.0", has_children=True);
    express = Pkg(name="express", version="4.0.0", has_children=True);
    accepts = Pkg(name="accepts", version="1.0.0", has_children=True);
    mime_types_full = Pkg(name="mime-types", version="2.1.35", has_children=True);
    mime_db = Pkg(name="mime-db", version="1.52.0", has_children=False);

    # app's direct dep is a deduped stub; the real mime-types lives only in web.
    app_mime_types_stub = Pkg(name="mime-types", version="2.1.35", has_children=False, deduped=True);

    root ++> web;
    root ++> app;
    web +>:DependsOn:+> api +>:DependsOn:+> trpc_server_stub;
    web +>:DependsOn:+> trpc_client +>:DependsOn:+> trpc_server_full +>:DependsOn:+> express +>:DependsOn:+> accepts +>:DependsOn:+> mime_types_full +>:DependsOn:+> mime_db;
    app +>:DependsOn:+> app_mime_types_stub;

    print("=== buggy collector (prunes on revisit) ===");
    buggy = CollectBuggy();
    root spawn buggy;
    print(f"collected: {buggy.collected}");
    has_mime_types = "mime-types@2.1.35" in buggy.collected;
    has_mime_db = "mime-db@1.52.0" in buggy.collected;
    print(f"mime-types@2.1.35 collected: {has_mime_types}");
    print(f"mime-db@1.52.0 collected: {has_mime_db}");

    print("");
    print("=== patched collector (re-walks children on revisit) ===");
    patched = CollectPatched();
    root spawn patched;
    print(f"collected: {patched.collected}");
    has_mime_types = "mime-types@2.1.35" in patched.collected;
    has_mime_db = "mime-db@1.52.0" in patched.collected;
    print(f"mime-types@2.1.35 collected: {has_mime_types}");
    print(f"mime-db@1.52.0 collected: {has_mime_db}");
}

