"""Maze escape with depth-first search.

The maze is a grid of cells joined by Corridor edges where walls leave
gaps. A runner walker explores depth-first by inserting next cells at the
front of its visit queue, marks dead ends as visited so they are never
re-entered, and reports the escape route when it steps onto the exit
cell.
"""

node Cell {
    has label: str;
    has is_exit: bool = False;
    has seen: bool = False;
}

edge Corridor: Cell --> Cell {}

walker MazeRunner {
    has path: list[str] = [];
    has explored: int = 0;

    can explore with Cell entry {
        if here.seen {
            skip;  # dead end or already-on-path cell
        }
        here.seen = True;
        self.explored += 1;
        self.path.append(here.label);

        if here.is_exit {
            route = " -> ".join(self.path);
            print(f"Escaped after exploring {self.explored} cells!");
            print(f"Path: {route}");
            disengage;
        }

        # Front-of-queue insertion => depth-first probing.
        visit : 0 : [->:Corridor:->];
    }
}

with entry {
    for stale in [root -->][?:Cell] {
        del stale;
    }

    # 4x4 grid; '#' cells are walls and simply have no corridors through.
    grid = {};
    labels = [
        ["A1", "A2", "#", "A4"],
        ["B1", "B2", "#", "B4"],
        ["C1", "C2", "C3", "C4"],
        ["D1", "#", "#", "D4"],
    ];
    for row in labels {
        for lab in row {
            if lab != "#" {
                grid[lab] = Cell(label=lab);
            }
        }
    }

    open_pairs = [
        ["A1", "A2"], ["A1", "B1"],
        ["A2", "B2"], ["B1", "C1"], ["B2", "C2"],
        ["A4", "B4"], ["B4", "C4"],
        ["C1", "D1"], ["C1", "C2"], ["C2", "C3"],
        ["C3", "C4"], ["C4", "D4"],
    ];
    start_cell = grid["A1"];
    exit_cell = grid["D4"];
    exit_cell.is_exit = True;

    # Corridors are two-way: an edge in each direction.
    for pair in open_pairs {
        cell_a = grid[pair[0]];
        cell_b = grid[pair[1]];
        cell_a +>: Corridor() :+> cell_b;
        cell_b +>: Corridor() :+> cell_a;
    }

    root ++> start_cell;
    start_cell spawn MazeRunner();
}

"""Reject workflow compensation references before execution."""

node Workflow {
    has title: str = "";
    has invalid_count: int = 0;
}

node Task {
    has task_id: str = "";
    has task_kind: str = "normal";
    has compensation_task: str = "";
}

node CompensationRef {
    has source_id: str = "";
    has target_id: str = "";
    has resolved: bool = False;
    has match_count: int = 0;
    has target_kind: str = "";
}

edge Boot { }
edge Contains { }
edge Compensation { }
edge ResolvesTo { }

walker Validator {
    has visited_ids: list[str] = [];
    has invalid_count: int = 0;
    has rejected: bool = False;

    can start with Root entry {
        visit [->:Boot:->] else { disengage; }
    }

    can inspect_workflow with Workflow entry {
        print(f"validating workflow {here.title}");
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_task with Task entry {
        if (here.task_id in self.visited_ids) {
            self.invalid_count += 1;
            self.rejected = True;
            print(f"cycle or duplicate task id: {here.task_id}");
        } else {
            self.visited_ids.append(here.task_id);
            if (here.compensation_task != "") {
                visit [->:Compensation:->] else {
                    self.invalid_count += 1;
                    self.rejected = True;
                    print(f"missing compensation reference {here.compensation_task}");
                    disengage;
                }
            }
        }
    }

    can inspect_reference with CompensationRef entry {
        if (here.resolved == False) {
            self.invalid_count += 1;
            self.rejected = True;
            print(f"unknown compensation task: {here.target_id}");
        } else {
            if (here.match_count != 1) {
                self.invalid_count += 1;
                self.rejected = True;
                print(f"ambiguous compensation task: {here.target_id}");
            }
            if (here.target_kind != "compensation") {
                self.invalid_count += 1;
                self.rejected = True;
                print(f"target is not a compensation task: {here.target_id}");
            }
            if (here.source_id == here.target_id) {
                self.invalid_count += 1;
                self.rejected = True;
                print(f"self-referential compensation: {here.source_id}");
            }
            visit [->:ResolvesTo:->] else { disengage; }
        }
    }
}

with entry {
    workflow = Workflow(title="payments");
    charge = Task(task_id="charge", compensation_task="refund");
    refund = Task(task_id="refund", task_kind="compensation");
    ship = Task(task_id="ship", compensation_task="missing");
    missing = CompensationRef(source_id="ship", target_id="missing");
    settle = Task(task_id="settle", compensation_task="audit");
    audit = Task(task_id="audit", task_kind="normal");
    wrong_ref = CompensationRef(
        source_id="settle",
        target_id="audit",
        resolved=True,
        match_count=1,
        target_kind="normal"
    );
    retry = Task(
        task_id="retry",
        task_kind="compensation",
        compensation_task="retry"
    );
    self_ref = CompensationRef(
        source_id="retry",
        target_id="retry",
        resolved=True,
        match_count=1,
        target_kind="compensation"
    );

    workflow +>:Contains:+> charge;
    workflow +>:Contains:+> ship;
    workflow +>:Contains:+> settle;
    workflow +>:Contains:+> retry;
    charge +>:Compensation:+> CompensationRef(
        source_id="charge",
        target_id="refund",
        resolved=True,
        match_count=1,
        target_kind="compensation"
    );
    ship +>:Compensation:+> missing;
    settle +>:Compensation:+> wrong_ref;
    retry +>:Compensation:+> self_ref;
    self_ref +>:ResolvesTo:+> retry;
    wrong_ref +>:ResolvesTo:+> audit;
    root +>:Boot:+> workflow;

    validator = Validator();
    root spawn validator;
    outcome = "BLOCKED" if validator.rejected else "READY";
    print(f"{outcome}: {validator.invalid_count} invalid compensation reference(s)");
}

