"""PR Quality Map impact analysis routing — Issue-channel model.

Models the core scenario from Issue #28: a PR's Quality Map impact analysis
must be routed through a dedicated GitHub Issue rather than the PR
conversation, so the bot returns the machine-readable schema instead of
a generic PR Review response. Nodes represent the PR, the dedicated
analysis Issue, the bot responses, and the requested SHAs. A walker
walks the Issue-threaded audit trail to verify routing invariants.
"""

node Repo {
    has name: str = "";
}

node PullRequest {
    has number: int = 0;
    has head_sha: str = "";
    has title: str = "";
    has gate_state: str = "pending";
    has status_sha: str = "";
    has last_decision: str = "";
    has merged: bool = False;
}

edge AnalysisIssue {
    has marker: str = "";
}

edge CodexRequest {
    has posted_sha: str = "";
}

node AnalysisThread {
    has issue_number: int = 0;
    has pr_number: int = 0;
    has marker: str = "";
    has request_count: int = 0;
}

node CodexResponse {
    has author: str = "";
    has schema: str = "";
    has response_sha: str = "";
    has decision: str = "";
    has trusted_marker: str = "";
}

edge PostedTo {
    has request_sha: str = "";
}

edge RepliedWith {
    has bot_login: str = "";
}

walker ImpactAuditor {
    has accepted: int = 0;
    has rejected: int = 0;
    has stale: int = 0;
    has generic_review: int = 0;
    has trusted_only: bool = True;

    can begin with Root entry {
        visit [-->];
    }

    can scan_repo with Repo entry {
        visit [-->];
    }

    can scan_pr with PullRequest entry {
        print(f"PR #{here.number} head={here.head_sha} gate={here.gate_state} decision={here.last_decision}");
        visit [-->];
    }

    can scan_thread with AnalysisThread entry {
        expected = f"<!-- quality-map-pr-impact-routing-fix smoke-pr:{here.pr_number} -->";
        if here.marker != expected {
            self.trusted_only = False;
            print(f"  THREAD marker mismatch: {here.marker}");
        } else {
            print(f"  THREAD #{here.issue_number} trusted marker ok; requests={here.request_count}");
        }
        visit [-->];
    }

    can scan_response with CodexResponse entry {
        trusted_marker = f"<!-- quality-map-pr-impact-routing-fix smoke-pr:";
        if here.author != "chatgpt-codex-connector[bot]" {
            self.rejected += 1;
            print(f"  REJECT non-bot author={here.author}");
        } elif here.schema == "Codex Review" {
            self.generic_review += 1;
            print(f"  REJECT generic Codex Review");
        } elif here.schema != "Quality Map" {
            self.rejected += 1;
            print(f"  REJECT unknown schema={here.schema}");
        } elif here.trusted_marker == "" {
            self.rejected += 1;
            print(f"  REJECT missing trusted marker");
        } else {
            self.accepted += 1;
            print(f"  ACCEPT decision={here.decision} sha={here.response_sha}");
        }
        visit [-->];
    }
}

