"""Braavo screen authoring: preview wireframe compositions and gate conversational model patches."""

node Product {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Screen {
    has title: str = "";
    has layout: str = "";
    has version: int = 0;
    has available: bool = True;
}

node Proposal {
    has title: str = "";
    has summary: str = "";
    has patch_layout: str = "";
    has target_version: int = 0;
    has accept: bool = False;
    has verdict: str = "pending";
    has year: int = 0;
    has available: bool = True;
}

edge Houses { }

edge PendingPatch { }

walker Compositor {
    can start with Root entry {
        visit [-->];
    }

    can preview_product with Product entry {
        label = "active" if here.available else "inactive";
        print(f"[{label}] product {here.title} ({here.year})");
        visit [->:Houses:->] else { disengage; }
    }

    can preview_screen with Screen entry {
        state = "live" if here.available else "hidden";
        print(f"  screen {here.title} [{state}] v{here.version} layout={here.layout}");
        visit [->:PendingPatch:->];
    }

    can preview_proposal with Proposal entry {
        print(f"    patch {here.title}: {here.summary} -> {here.patch_layout} "
              f"(target v{here.target_version}, verdict={here.verdict})");
    }
}

walker RevisionGate {
    has approved: int = 0;
    has rejected: int = 0;
    has stale: int = 0;
    has current_screen: Screen | None = None;

    can start with Root entry {
        visit [-->];
    }

    can scope_product with Product entry {
        visit [->:Houses:->] else { disengage; }
    }

    can review_screen with Screen entry {
        self.current_screen = here;
        visit [->:PendingPatch:->];
    }

    can decide with Proposal entry {
        screen = self.current_screen;
        if screen is None {
            disengage;
        }
        if here.verdict != "pending" {
            return;
        }
        if here.target_version != screen.version {
            here.verdict = "stale";
            self.stale += 1;
            print(f"STALE {here.title}: need v{here.target_version}, screen at v{screen.version}");
            return;
        }
        if here.accept {
            screen.layout = here.patch_layout;
            screen.version += 1;
            here.verdict = "approved";
            self.approved += 1;
            print(f"APPROVED {here.title}: layout={screen.layout} v{screen.version}");
        } else {
            here.verdict = "rejected";
            self.rejected += 1;
            print(f"REJECTED {here.title}: model unchanged layout={screen.layout}");
        }
    }
}

with entry {
    prod = Product(title="Procurement Portal", year=2026, available=True);
    root ++> prod;
    landing = Screen(title="Landing", layout="hero|cta", version=0, available=True);
    prod +>:Houses:+> landing;
    footer = Proposal(
        title="W-S2-b",
        summary="Add unreviewed footer block",
        patch_layout="hero|cta|footer",
        target_version=0,
        accept=False,
        year=2026,
    );
    widen = Proposal(
        title="W-S2-a",
        summary="Widen hero with gallery strip",
        patch_layout="hero|gallery|cta",
        target_version=0,
        accept=True,
        year=2026,
    );
    sidebar = Proposal(
        title="W-S2-c",
        summary="Sidebar from stale conversation",
        patch_layout="hero|sidebar|cta",
        target_version=0,
        accept=True,
        year=2026,
    );
    landing +>:PendingPatch:+> footer;
    landing +>:PendingPatch:+> widen;
    landing +>:PendingPatch:+> sidebar;

    print("--- before review ---");
    root spawn Compositor();

    gate = RevisionGate();
    root spawn gate;
    print(f"--- gate tallies: approved={gate.approved} rejected={gate.rejected} stale={gate.stale} ---");

    print("--- after review ---");
    root spawn Compositor();
}
