```jac
"""Recursive module resolution across a directory tree.

Models the Webpack/ts-loader scenario: a configured project walks upward
through ancestor 'shared' search roots, and at each level the first
matching component wins. A typed-edge walker performs the upward search,
marks drained roots, and reports any unresolved import.
"""

node Project {
    has name: str = "";
    has base_dir: str = "";
}

node SharedRoot {
    has directory_name: str = "";
    has drained: bool = False;
}

node Directory {
    has path: str = "";
}

node Module {
    has path: str = "";
    has resolved: bool = False;
}

node ImportRequest {
    has specifier: str = "";
    has status: str = "pending";
    has resolved_path: str = "";
}

# --- Edge archetypes --------------------------------------------------------

edge OwnedBy {}
edge SearchedAt {}
edge HostsModule {}
edge Requests {}

# --- The resolver walker ----------------------------------------------------

walker ResolveRequest {
    has trace: list[str] = [];
    has hit: str = "";

    can start with ImportRequest entry {
        print(f"[req] resolving '{here.specifier}' "
              f"(status={here.status})");
        if here.status != "pending" {
            return;
        }
        visit [->:Requests:->];
    }

    can find_project with Project entry {
        print(f"[req]   project: {here.name} ({here.base_dir})");
        visit [->:SearchedAt:->];
    }

    can probe_root with SharedRoot entry {
        if here.drained {
            visit [-->];
            return;
        }
        here.drained = True;
        self.trace.append(here.directory_name);
        print(f"[req]   climbing into shared root "
              f"'{here.directory_name}'");
        visit [->:HostsModule:->];
    }

    can scan_dir with Directory entry {
        print(f"[req]     scanning dir: {here.path}");
        visit [->:HostsModule:->];
    }

    can collect with Module entry {
        if self.hit == "" and here.resolved {
            self.hit = here.path;
            print(f"[req]       RESOLVED module {here.path}");
        } else {
            tag = "seen" if here.resolved else "skipped";
            print(f"[req]       module {here.path} -> {tag}");
        }
        visit [-->];
    }
}

with entry {
    # Build a tiny project graph: one Project owns several SharedRoots,
    # each SharedRoot hosts a Directory, each Directory hosts a Module.
    proj = Project(name="webapp", base_dir="/repo/apps/webapp");

    shared_components = SharedRoot(directory_name="shared/components");
    shared_utils = SharedRoot(directory_name="shared/utils");
    shared_legacy = SharedRoot(directory_name="shared/legacy", drained=True);

    dir_btn = Directory(path="/repo/apps/shared/components");
    dir_card = Directory(path="/repo/shared/components");
    dir_util = Directory(path="/repo/shared/utils");

    mod_btn = Module(path="/repo/apps/shared/components/Button.tsx",
                     resolved=True);
    mod_card = Module(path="/repo/shared/components/Card.tsx",
                      resolved=True);
    mod_util = Module(path="/repo/shared/utils/index.ts", resolved=True);
    mod_missing = Module(path="/repo/shared/components/Missing.tsx",
                         resolved=False);

    proj +>:OwnedBy:+> shared_components;
    proj +>:OwnedBy:+> shared_utils;
    proj +>:OwnedBy:+> shared_legacy;

    proj +>:SearchedAt:+> shared_components;
    proj +>:SearchedAt:+> shared_utils;
    proj +>:SearchedAt:+> shared_legacy;

    shared_components +>:HostsModule:+> dir_btn;
    shared_components +>:HostsModule:+> dir_card;
    shared_components +>:HostsModule:+> mod_missing;
    shared_utils +>:HostsModule:+> dir_util;

