    dir_card +>:HostsModule:+> mod_card;
    dir_util +>:HostsModule:+> mod_util;

    # The ImportRequest hangs off root and points back at the project.
    req = ImportRequest(specifier="components/Button", status="pending");
    root ++> req;
    req +>:Requests:+> proj;

