"""Contact tracing simulator: spread an outbreak wave by wave through a contact network."""

node Person {
    has name: str = "";
    has infected: bool = False;
    has wave: int = 0;
}

edge Contact {
    has day: int = 0;
}

walker Tracer {
    has current_wave: int = 0;
    has frontier: list[Person] = [];
    has visited: list[Person] = [];

    can start with Root entry {
        neighbors = [-->];
        if neighbors {
            patient_zero = neighbors[0];
            patient_zero.infected = True;
            patient_zero.wave = 1;
            self.current_wave = 1;
            self.frontier = [patient_zero];
            self.visited = [patient_zero];
            print(f"Wave 1: patient zero is {patient_zero.name}");
            self.spread_wave();
        }
    }

    def spread_wave() -> None {
        next_frontier: list[Person] = [];
        for person in self.frontier {
            for contact in [person->:Contact:->] {
                if not contact.infected and not self.was_visited(contact) {
                    contact.infected = True;
                    contact.wave = self.current_wave + 1;
                    next_frontier.append(contact);
                    self.visited.append(contact);
                    print(f"  -> {contact.name} exposed in wave {contact.wave}");
                }
            }
        }
        if next_frontier {
            self.current_wave += 1;
            self.frontier = next_frontier;
            self.spread_wave();
        } else {
            print(f"Outbreak contained after {self.current_wave} wave(s)");
        }
    }

    def was_visited(p: Person) -> bool {
        seen = False;
        for v in self.visited {
            if v == p {
                seen = True;
            }
        }
        return seen;
    }

    can record with Person entry {
        visit [-->];
    }
}

with entry {
    p0 = Person(name="Alice");
    bob = Person(name="Bob");
    carol = Person(name="Carol");
    dave = Person(name="Dave");
    eve = Person(name="Eve");
    frank = Person(name="Frank");
    grace = Person(name="Grace");

    root ++> p0;
    p0 +>:Contact(day=1):+> bob;
    p0 +>:Contact(day=1):+> carol;
    bob +>:Contact(day=2):+> dave;
    bob +>:Contact(day=2):+> eve;
    carol +>:Contact(day=2):+> frank;
    dave +>:Contact(day=3):+> grace;
    eve +>:Contact(day=3):+> grace;

    root spawn Tracer();
}

