"""Quiz grader walker: typed reports over Quiz nodes.

Demonstrates a walker whose accumulator is strictly typed to integers
(via ``report``), so accidental string scores cannot leak through the
grade report. Walks a small chain of Quiz nodes, prints each student's
score, and finally reports the class average.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has total: int = 0;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        print(f"{here.student}: {here.score}");
        self.total = self.total + here.score;
        self.count = self.count + 1;
        report here.score;
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=72)
        ++> Quiz(student="Carmen", score=95)
