    print(f"Class average: {average}");
}

"""Health-inspect a restaurant kitchen line.

Three stations (Grill, Fryer, ColdPrep) hang off root. An Inspector
walker visits each station and runs two checks at every stop:
  1. Temperature audit — flags stations above 40 C as a violation.
  2. Visit log — records every station visited, in order.
Both checks fire at each station via union triggers so no station
is skipped regardless of its type.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
    has safe_threshold: float = 40.0;

    def is_violation() -> bool {
        return self.celsius > self.safe_threshold;
    }
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker Inspector {
    has violations: list = [];
    has visit_log: list = [];

    can start with Root entry {
        visit [-->];
    }

    # Union trigger: fires for ANY station subtype at every stop.
    can audit_temp with Grill | Fryer | ColdPrep entry {
        if here.is_violation() {
            self.violations.append(here.name);
            print(f"[VIOLATION] {here.name} at {here.celsius} C (limit {here.safe_threshold} C)");
        } else {
            print(f"[OK] {here.name} at {here.celsius} C");
        }
    }

    # Second union trigger: visit log runs alongside the temp audit.
    can log_visit with Grill | Fryer | ColdPrep entry {
        self.visit_log.append(here.name);
        visit [-->];
    }
}

with entry {
    root ++> Grill(name="Grill", celsius=180.0)
        ++> Fryer(name="Fryer", celsius=170.0)
        ++> ColdPrep(name="ColdPrep", celsius=4.0);

    inspector = Inspector();
    root spawn inspector;

    print(f"\nVisited ({len(inspector.visit_log)} stations): {inspector.visit_log}");
    print(f"Violations ({len(inspector.violations)}): {inspector.violations}");
}

