"""Rental shop media audit: books, DVDs, and unclassified items on a shelf.

A single union ability on the ``Item`` base node counts every audit
encounter. Two specialized node types (Book, DVD) override the default
audit to report their own details; anything else falls through to the
base node's default handling.
"""

node Item {
    has title: str = "";
    has default_handled: bool = False;

    def audit_label() -> str {
        return f"unclassified item: {self.title}";
    }
}

node Book(Item) {
    has author: str = "";
    has year: int = 0;

    override def audit_label() -> str {
        return f"book: {self.title} by {self.author} ({self.year})";
    }
}

node DVD(Item) {
    has runtime_min: int = 0;

    override def audit_label() -> str {
        return f"dvd: {self.title} [{self.runtime_min} min]";
    }
}

walker Auditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Item entry {
        label = here.audit_label();
        if isinstance(here, Item) and not isinstance(here, Book) and not isinstance(here, DVD) {
            here.default_handled = True;
            self.defaulted += 1;
        }
        print(label);
        self.total += 1;
        visit [-->];
    }
}

with entry {
    shelf = root;
    shelf ++> Book(title="Dune", author="Frank Herbert", year=1965);
    shelf ++> DVD(title="Blade Runner", runtime_min=117);
    shelf ++> Book(title="Neuromancer", author="William Gibson", year=1984);
    shelf ++> Item(title="Archive Reel #042");
    shelf ++> DVD(title="Spirited Away", runtime_min=125);

    auditor = Auditor();
    root spawn auditor;

    print(f"audited {auditor.total} items, {auditor.defaulted} needed the default path");
}

