"""Persistent world storage demo with bounded traversal and explicit cycle safety."""

node StorageChest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has world_id: str = "";
    has integrity: int = 100;
    has destroyed: bool = False;
    has destruction_policy: str = "REJECT_UNTIL_EMPTY";
}

node Container {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has container_id: str = "";
    has capacity: int = 8;
    has occupied_slots: int = 0;
    has owner_id: str = "";
    has access_mode: str = "OWNER_OR_MEMBER";
}

node ItemStack {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stack_id: str = "";
    has stack_key: str = "";
    has quantity: int = 0;
}

node LogisticsRegion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has region_id: str = "";
    has region_name: str = "";
}

edge AuthorizedStorage { }
edge IndexedBy { }
edge OwnsContainer { }
edge ContainsItem {
    has slot: int = 0;
}

walker StorageAuditor {
    has actor_id: str = "player-local";
    has seen_ids: list[str] = [];
    has chest_count: int = 0;
    has item_count: int = 0;

    can start with Root entry {
        print("Auditing bounded local storage from the active region");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_region with LogisticsRegion entry {
        if (here.region_id in self.seen_ids) {
            print(f"cycle guard: region {here.region_id} already visited");
        } else {
            self.seen_ids.append(here.region_id);
            print(f"region index: {here.region_name}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_chest with StorageChest entry {
        if (here.world_id in self.seen_ids) {
            print(f"cycle guard: chest {here.world_id} already visited");
        } else {
            self.seen_ids.append(here.world_id);
            self.chest_count += 1;
            state = "destroyed" if here.destroyed else "active";
            print(f"chest {here.world_id}: {state}, policy={here.destruction_policy}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_container with Container entry {
        if (here.container_id in self.seen_ids) {
            print(f"cycle guard: container {here.container_id} already visited");
        } else {
            self.seen_ids.append(here.container_id);
            print(f"canonical container {here.container_id}: {here.occupied_slots}/{here.capacity} slots");
            print(f"access request by {self.actor_id}: {here.access_mode}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_item with ItemStack entry {
        if (here.stack_id in self.seen_ids) {
            print(f"cycle guard: item {here.stack_id} already visited");
        } else {
            self.seen_ids.append(here.stack_id);
            self.item_count += 1;
            print(f"item {here.stack_key} x{here.quantity}: canonical contents retained");
        }
    }
}

with entry {
    region = LogisticsRegion(
        title="Overworld home logistics",
        region_id="region-home",
        region_name="Home perimeter"
    );
    chest = StorageChest(
        title="Wooden Storage Chest",
        world_id="build-chest-01",
        integrity=100
    );
    container = Container(
        title="Chest canonical container",
        container_id="container-build-chest-01",
        capacity=8,
        occupied_slots=2
    );
    wood = ItemStack(
        title="Wood plank stack",
        stack_id="stack-wood-01",
        stack_key="wood_plank",
        quantity=24
    );
    stone = ItemStack(
        title="Stone stack",
        stack_id="stack-stone-01",
        stack_key="stone",
        quantity=12
    );

    root ++> region;
    region +>:AuthorizedStorage:+> chest;
    chest +>:IndexedBy:+> region;
    chest +>:OwnsContainer:+> container;
    container +>:ContainsItem(slot=1):+> wood;
    container +>:ContainsItem(slot=2):+> stone;

    root spawn StorageAuditor();
}

"""HCA schema override register: 12 deliberate divergences from CELLxGENE 7.0.0.

Models the override register as a graph of Override nodes connected to SchemaLayer
nodes, walked by a Reconciler walker that detects upstream divergence and reports
which inherited (un-overridden) fields silently follow the 7.0.0 baseline.
"""

node Override {
    has number: int = 0;
    has title: str = "";
    has layer: str = "";
    has commit: str = "";
    has issue: str = "";
    has direction: str = "";
}

node SchemaLayer {
    has name: str = "";
    has baseline_version: str = "7.0.0";
}

edge OverrideOf {
    has since: str = "";
}

edge InheritedFrom {
    has reason: str = "";
}

walker Reconciler {
    has visited: list[str] = [];
    has strict_count: int = 0;
    has relax_count: int = 0;
    has extend_count: int = 0;

    can start with Root entry {
        self.visited = [];
        visit [->:OverrideOf:->];
    }

    can audit with Override entry {
        if here.direction == "tighten" or here.direction == "invert (privacy)" {
            self.strict_count += 1;
        } elif here.direction == "relax" {
            self.relax_count += 1;
        } elif here.direction == "extend" {
            self.extend_count += 1;
        } else {
            # reject CXG relocation / ahead of upstream / superseded
            self.extend_count += 1;
        }
        here_title = here.title;
        self.visited.append(f"#{here.number} {here_title} ({here.direction})");
        visit [->:OverrideOf:->];
    }

    can sweep with SchemaLayer entry {
        next_label = f"layer={here.name} baseline={here.baseline_version}";
        self.visited.append(next_label);
        visit [-->] else {
            report {
                "traversal": self.visited,
                "tighten_or_invert": self.strict_count,
                "relax": self.relax_count,
                "extend_or_other": self.extend_count,
            };
            disengage;
        }
    }
}

walker CascadeAuditor {
    can start with Root entry {
        print("Reachable overrides + inherited baseline fields:");
        visit [->:OverrideOf:->];
    }

    can list_override with Override entry {
        print(f"  override #{here.number}: {here.title} -> {here.direction}");
        visit [->:OverrideOf:->];
    }

    can list_inherited with SchemaLayer entry {
        print(f"  inherited from {here.name} baseline {here.baseline_version}");
        visit [-->] else { disengage; }
    }
}

with entry {
    upstream = SchemaLayer(name="cellxgene_schema_7.0.0", baseline_version="7.0.0");
    hca = SchemaLayer(name="hca_validation_tools", baseline_version="1.0.0");

    root +>:OverrideOf(since="3dd9f6b"):+> Override(
        number=1, title="organism_ontology_term_id kept in obs",
        layer="yaml", commit="3dd9f6b", issue="none",
        direction="reject CXG relocation"
    );
    root +>:OverrideOf(since="2af5e2e"):+> Override(
        number=2, title="17 HCA Tier 1 obs fields added",
        layer="yaml", commit="2af5e2e", issue="#177",
        direction="extend"
    );
    root +>:OverrideOf(since="a47561e"):+> Override(
        number=3, title="Ensembl ID mismatches -> warnings",
        layer="code", commit="a47561e", issue="#167/#168",
        direction="relax severity"
    );
    root +>:OverrideOf(since="8df7bbe"):+> Override(
        number=10, title="library_id back to required",
        layer="yaml", commit="8df7bbe", issue="#298",
        direction="tighten"
    );
    root +>:OverrideOf(since="53c2fd8"):+> Override(
        number=12, title="self_reported_ethnicity forbidden",
        layer="yaml", commit="53c2fd8", issue="#370/#409",
        direction="invert (privacy)"
    );

    hca +>:InheritedFrom(reason="never overridden"):+> Override(
        number=0, title="tissue_type vocabulary + cell-line cascade",
        layer="default", commit="initial", issue="none",
        direction="adopt upstream"
    );
    hca +>:InheritedFrom(reason="never overridden"):+> Override(
        number=0, title="suspension_type assay list",
        layer="default", commit="initial", issue="none",
        direction="adopt upstream"
    );

    root ++> upstream;
    root ++> hca;

    root spawn Reconciler();
    print("---");
    root spawn CascadeAuditor();
}

"""Workflow retirement: model orphaned/authoritative workflows and reconcile authority.

Models a CI workflow catalog where each workflow has an inventory classification,
current callers/consumers, retirement reason, and historical evidence. A walker
walks the graph and reconciles authority by flagging workflows whose live
state contradicts their source-of-truth retirement status.
"""

node Workflow {
    has title: str = "";
    has classification: str = "";   # orphan | expired | obsolete | duplicate | authoritative | specialized
    has retirement_reason: str = "";
    has historical_evidence: str = "";
    has live_state: str = "";       # enabled | disabled | not_proven
    has reconciled: bool = False;
}

edge Calls {
    has consumer: str = "";
    has policy_ref: str = "";
}

edge ReplacedBy {
    has replacement: str = "";
}

walker Auditor {
    has visited: list[str] = [];
    has depth_limit: int = 10;
    has has_cycle: bool = False;

    can start with Root entry {
        self.visited = [];
        visit [-->] else { disengage; }
    }

    can audit with Workflow entry {
        # Explicit cycle guard — walkers do not dedupe automatically.
        if here.title in self.visited {
            self.has_cycle = True;
            print(f"[CYCLE] revisit of '{here.title}' — graph has a loop");
            disengage;
        }
        self.visited = self.visited + [here.title];

        # Reconcile source retirement classification against live state.
        if here.classification in ["orphan", "expired", "obsolete", "duplicate"] {
            if here.live_state == "enabled" {
                here.reconciled = False;
                print(f"[CONFLICT] '{here.title}' marked {here.classification} but still enabled live");
            } elif here.live_state == "not_proven" {
                here.reconciled = False;
                print(f"[UNCERTAIN] '{here.title}' {here.classification}, live state not_proven — must verify");
            } else {
                here.reconciled = True;
                print(f"[OK] '{here.title}' {here.classification} and disabled; evidence: {here.historical_evidence}");
            }
        } elif here.classification == "authoritative" {
            # Authoritative lanes must be untouched unless transition is reviewed.
            here.reconciled = True;
            print(f"[AUTH] '{here.title}' preserved as authoritative");
        } elif here.classification == "specialized" {
            # Specialized workflows are kept even when uncommon.
            here.reconciled = True;
            print(f"[KEEP] '{here.title}' specialized, uncommon but retained");
        }

        if len(self.visited) >= self.depth_limit {
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # Authoritative core lanes — preserved untouched.
    pr_main = Workflow(
        title="pr-main",
        classification="authoritative",
        retirement_reason="",
        historical_evidence="docs/canonical/pr-main.md",
        live_state="enabled",
    );
    nightly = Workflow(
        title="nightly",
        classification="authoritative",
        retirement_reason="",
        historical_evidence="docs/canonical/nightly.md",
        live_state="enabled",
    );
    publication = Workflow(
        title="publication",
        classification="authoritative",
        retirement_reason="",
