        live_state="enabled",
    );

    # Orphaned temporary workflow — expired, evidence preserved elsewhere.
    tmp_hotfix = Workflow(
        title="tmp-hotfix-2023",
        classification="expired",
        retirement_reason="temporary hotfix window closed",
        historical_evidence="archive/2023/tmp-hotfix-2023.tar",
        live_state="disabled",
    );

    # Obsolete reusable workflow — no active caller, evidence retained.
    legacy_release = Workflow(
        title="legacy-release-helper",
        classification="obsolete",
        retirement_reason="no active caller found in inventory",
        historical_evidence="archive/legacy/legacy-release-helper.log",
