    legacy_release +>:ReplacedBy(replacement="tmp-migration-2024"):+> no_evidence;
    no_evidence +>:ReplacedBy(replacement="legacy-release-helper"):+> legacy_release;

    root spawn Auditor(depth_limit=20);
