"""Trigger runtime demo with deterministic admission, deduplication, and causal loop prevention."""

node Record {
    has identity: str = "";
    has label: str = "";
}

node Trigger(Record) {
    has trigger_type: str = "manual";
    has source: str = "operator";
    has version: int = 1;
    has authenticated: bool = False;
    has enabled: bool = True;
}

node Mission(Record) {
    has state: str = "active";
    has budget_ok: bool = True;
}

node Occurrence(Record) {
    has dedupe_identity: str = "";
    has prefilter_reason: str = "";
    has eligible: bool = True;
    has admitted: bool = False;
    has model_calls: int = 0;
}

node Operation(Record) {
    has effect_state: str = "pending";
    has causal_depth: int = 0;
}

edge Activates { }
edge BoundTo { }
edge HasOccurrence { }
edge Requests { }
edge CausesTrigger { }

walker AdmissionAuditor {
    can start with Root entry {
        visit [-->];
    }

    can inspect_trigger with Trigger entry {
        if here.enabled == False {
            print(f"trigger {here.identity} blocked: disabled");
        } else {
            visit [->:BoundTo:->];
        }
    }

    can inspect_mission with Mission entry {
        if here.state != "active" {
            print(f"mission {here.identity} blocked: {here.state}");
        } else {
            visit [->:HasOccurrence:->];
        }
    }

    can inspect_occurrence with Occurrence entry {
        if here.eligible == False {
            print(f"occurrence {here.dedupe_identity} ignored: "
                  f"{here.prefilter_reason}; model_calls=0");
        } else {
            here.admitted = True;
            here.model_calls = 1;
            print(f"occurrence {here.dedupe_identity} admitted for execution");
        }
    }
}

walker CausalityGuard {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can follow_trigger with Trigger entry {
        if here.identity in self.seen {
            print(f"causal loop blocked at trigger {here.identity}");
            disengage;
        } else {
            self.seen.append(here.identity);
            if here.enabled == False {
                print(f"trigger {here.identity} blocked: disabled");
            } else {
                visit [->:BoundTo:->];
            }
        }
    }

    can follow_mission with Mission entry {
        if here.state != "active" {
            print(f"mission {here.identity} blocked: {here.state}");
        } else {
            visit [->:HasOccurrence:->];
        }
    }

    can follow_occurrence with Occurrence entry {
        if here.eligible {
            visit [->:Requests:->];
        }
    }

    can follow_operation with Operation entry {
        if here.identity in self.seen {
            print(f"causal loop blocked at operation {here.identity}");
            disengage;
        } else {
            self.seen.append(here.identity);
            visit [->:CausesTrigger:->];
        }
    }
}

with entry {
    trigger_a = Trigger(
        identity="trigger-A",
        label="manual intake",
        trigger_type="manual",
        source="operator",
        version=1,
        authenticated=True
    );
    trigger_b = Trigger(
        identity="trigger-B",
        label="webhook relay",
        trigger_type="webhook",
        source="signed-relay",
        version=1,
        authenticated=True
    );

    mission_a = Mission(
        identity="mission-A",
        label="watch intake",
        state="active",
        budget_ok=True
    );
    mission_b = Mission(
        identity="mission-B",
        label="reconcile relay",
        state="active",
        budget_ok=True
    );

    fresh = Occurrence(
        identity="occurrence-1",
        label="new delivery",
        dedupe_identity="delivery-42",
        prefilter_reason="changed",
        eligible=True
    );
    duplicate = Occurrence(
        identity="occurrence-2",
        label="replayed delivery",
        dedupe_identity="delivery-42",
        prefilter_reason="duplicate",
        eligible=False
    );
    relay = Occurrence(
        identity="occurrence-3",
        label="causal relay",
        dedupe_identity="delivery-43",
        prefilter_reason="changed",
        eligible=True
    );

    operation_a = Operation(
        identity="operation-A",
        label="create execution",
        effect_state="pending",
        causal_depth=1
    );
    operation_b = Operation(
        identity="operation-B",
