with entry {
    # Doc sections the maintainer proposed in the RFC.
    readme     = DocSection(title="README.md",        doc_kind="readme",  status="drafted",  display_name="README.md",     category="doc_section");
    spec       = DocSection(title="docs/spec.md",     doc_kind="spec",    status="planned",  display_name="docs/spec.md",  category="doc_section");
    roadmap    = DocSection(title="docs/roadmap.md",  doc_kind="roadmap", status="planned",  display_name="docs/roadmap.md", category="doc_section");
    hygiene    = DocSection(title="CODEOWNERS/.gitignore", doc_kind="hygiene", status="published", display_name="CODEOWNERS/.gitignore", category="doc_section");

    # Section statuses (separate nodes so the walker ability can hit them).
    s_drafted  = SectionStatus(label="drafted",   severity=2, display_name="drafted",   category="section_status");
    s_planned  = SectionStatus(label="planned",   severity=1, display_name="planned",   category="section_status");
    s_publish  = SectionStatus(label="published", severity=3, display_name="published", category="section_status");

    # Community-ranked features the RFC asks the community to prioritize.
    f_llm_judge   = Feature(name="LLM-as-judge", priority=9, planned=True,  display_name="LLM-as-judge", category="feature");
    f_compare     = Feature(name="compare",     priority=8, planned=True,  display_name="compare",      category="feature");
    f_report      = Feature(name="report",      priority=6, planned=True,  display_name="report",       category="feature");
    f_typer_cli   = Feature(name="typer CLI",   priority=5, planned=True,  display_name="typer CLI",    category="feature");
    f_plugins     = Feature(name="plugins",     priority=3, planned=False, display_name="plugins",      category="feature");

    # Wire the documentation dependency graph with typed edges. The
    # DependsOn edges encode "this doc can't be finalized until that one
    # exists" — the exact relationship the hand-rolled adjacency dict used
    # to model. README -> spec, spec -> roadmap, roadmap -> hygiene form a
    # chain; spec also depends on hygiene, so traversal naturally exercises
    # multi-parent reachability and (if reordered) cycle detection.
    root ++> readme ++> spec ++> roadmap ++> hygiene;
    spec +>:DependsOn(reason="spec references hygiene policy"):+> hygiene;
    readme  +>:Documents(section_kind="overview"):+> s_publish;
    spec    +>:Documents(section_kind="contract"):+> s_planned;
    roadmap +>:Documents(section_kind="milestones"):+> s_planned;

    # Features attached to the spec node via typed Targets edges.
    spec +>:Targets(audience="adopters"):+>     f_llm_judge;
    spec +>:Targets(audience="contributors"):+> f_compare;
    spec +>:Targets(audience="CI integrators"):+> f_report;
    spec +>:Targets(audience="adopters"):+>     f_typer_cli;
    spec +>:Targets(audience="contributors"):+> f_plugins;

    # Spawn the auditor on root — it will walk the chain and dispatch
    # to type-specific abilities for DocSection, SectionStatus, Feature.
    root spawn DocsAuditor(depth_cap=6);
    print("");
    root spawn PriorityRanker();
}

"""Stoichiometry-aware reaction I/O walker.

Models the essential scenario from issue #48: a reaction walker visits its
typed input/output edges, picks up the curated stoichiometric coefficient,
aggregates duplicate coefficients onto the same target node, and reports
the totals — replacing the hand-rolled `_resolve_vr_entities` machinery that
hardcoded every coefficient to 1.
"""

node Entity {
    has name: str = "";
    has has_curated_coef: bool = False;
}

node EntitySetMember {
    has name: str = "";
    has member_coef: int = 1;
}

node Reaction {
    has name: str = "";
}

edge InputEdge {
    has stoichiometry: int = 1;
    has curated: bool = False;
}

edge OutputEdge {
    has stoichiometry: int = 1;
    has curated: bool = False;
}

walker StoichiometryAuditor {
    has in_totals: dict = {};
    has out_totals: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can audit with Reaction entry {
        print(f"Reaction: {here.name}");
        self.in_totals = {};
        self.out_totals = {};
        visit [->:InputEdge:->];
    }

    can tally_inputs with Entity | EntitySetMember entry {
        if isinstance(here, EntitySetMember) {
            coef = here.member_coef;
        } elif here.has_curated_coef {
            coef = 2;
        } else {
            coef = 1;
        }
        key = here.name;
        prior = self.in_totals.get(key, 0);
        self.in_totals[key] = prior + coef;
    }

    can finish_inputs with Entity | EntitySetMember entry {
        visit [->:OutputEdge:->];
    }

    can tally_outputs with Entity | EntitySetMember entry {
        if isinstance(here, EntitySetMember) {
            coef = here.member_coef;
        } elif here.has_curated_coef {
            coef = 2;
        } else {
            coef = 1;
        }
        key = here.name;
        prior = self.out_totals.get(key, 0);
        self.out_totals[key] = prior + coef;
        print(f"  output coef {coef} to {here.name}; running total {self.out_totals[key]}");
        if len(self.in_totals) > 0 and len(self.out_totals) == len(self.in_totals) {
            print("  input totals:");
            for (k, v) in self.in_totals.items() {
                print(f"    {k}: {v}");
            }
            print("  output totals:");
            for (k, v) in self.out_totals.items() {
                print(f"    {k}: {v}");
            }
        }
    }
}

with entry {
    rxn = Reaction(name="R1");
    root ++> rxn;

    eA = Entity(name="A", has_curated_coef=True);
    eB = Entity(name="B", has_curated_coef=False);
    eC = Entity(name="C", has_curated_coef=True);
    mA1 = EntitySetMember(name="A#1", member_coef=2);
    mA2 = EntitySetMember(name="A#2", member_coef=2);

    rxn +>:InputEdge(stoichiometry=2, curated=True):+> eA;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> eB;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> mA1;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> mA2;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> eC;

    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> eB;

    auditor = StoichiometryAuditor();
    root spawn auditor;
}

"""Projection-aware cache invalidation: canonical query keys downgraded by confirmed txs and projection streams without cache-wide churn."""

node InvalidationTrigger {
    has kind: str = "";
    has downgrade_to: str = "reorged";
}

node ConfirmedTx(InvalidationTrigger) {
    has tx_hash: str = "";
}

node ProjectionEvent(InvalidationTrigger) {
    has stream: str = "";
    has affected_domain: str = "";
}

node QueryEntry {
    has domain: str = "";
    has cache_key: str = "";
    has freshness: str = "finalized";
}

edge Invalidates { }

edge DependsOn { }

walker CacheInvalidator {
    has seen_keys: list[str] = [];
    has downgrade_to: str = "reorged";
    has invalidated_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can on_trigger with ConfirmedTx | ProjectionEvent entry {
        self.downgrade_to = here.downgrade_to;
        print(f"[TRIGGER] {here.kind} targets downgrade to {self.downgrade_to}");
        visit [->:Invalidates:->] else { disengage; }
    }

    can invalidate with QueryEntry entry {
        key = f"{here.domain}:{here.cache_key}";
        if key in self.seen_keys {
            disengage;
        }
        self.seen_keys.append(key);
        prior = here.freshness;
        here.freshness = self.downgrade_to;
        self.invalidated_count += 1;
        print(f"[INVALIDATE] {key} {prior} to {here.freshness}");
        visit [<-:DependsOn:<-] else { disengage; }
    }
}

with entry {
    wallet = QueryEntry(domain="wallet", cache_key="0xabc", freshness="safe");
    claims = QueryEntry(domain="claims", cache_key="claim:1", freshness="finalized");
    evidence = QueryEntry(domain="evidence", cache_key="evid:42", freshness="finalized");
    reputation = QueryEntry(domain="reputation", cache_key="rep:7", freshness="finalized");

    claims +>:DependsOn:+> wallet;
    reputation +>:DependsOn:+> claims;

    reorg_tx = ConfirmedTx(
        tx_hash="0xdeadbeef",
        kind="confirmed_tx",
        downgrade_to="reorged",
    );
    projection = ProjectionEvent(
        stream="rounds",
        affected_domain="evidence",
        kind="projection",
        downgrade_to="observed",
    );

    reorg_tx +>:Invalidates:+> wallet;
    projection +>:Invalidates:+> evidence;

    root ++> reorg_tx ++> projection;

    auditor = CacheInvalidator();
    root spawn auditor;

    print(
        f"Targeted invalidation complete: {auditor.invalidated_count} entries touched, "
        f"wallet={wallet.freshness}, claims={claims.freshness}, "
        f"evidence={evidence.freshness}, reputation={reputation.freshness}"
    );
}

