"""Native OSP model of deterministic compiler fidelity cases and evidence."""

node Case {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has case_id: str = "";
    has subsystem: str = "";
    has valid_program: bool = True;
}

node Observation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner: str = "";
    has normalized_match: bool = True;
    has authoritative: bool = True;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has artifact_kind: str = "";
    has fingerprint: str = "";
    has bytes_match: bool = True;
    has structure_match: bool = True;
}

edge DependsOn {
    has reason: str = "";
}

edge ObservedBy {
    has channel: str = "";
}

edge Captures {
    has artifact_role: str = "";
}

walker DependencyAuditor {
    has seen: list[str] = [];

    can start with Root entry {
        print("Dependency audit started");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Case entry {
        if here.case_id in self.seen {
            print(f"cycle detected at case {here.case_id}");
            disengage;
        } else {
            self.seen.append(here.case_id);
            print(f"checking {here.case_id} in {here.subsystem}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

walker FidelityAuditor {
    can start with Root entry {
        print("Fidelity audit started");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_case with Case entry {
        print(f"case {here.case_id}: valid={here.valid_program}");
        visit [->:ObservedBy:->] else {
            disengage;
        }
    }

    can inspect_observation with Observation entry {
        print(f"owner={here.owner}, normalized_match={here.normalized_match}");
        visit [->:Captures:->] else {
            disengage;
        }
    }

    can inspect_artifact with Artifact entry {
        print(f"{here.artifact_kind}: bytes_match={here.bytes_match}, "
              f"structure_match={here.structure_match}");
    }
}

with entry {
    c1 = Case(
        title="valid preprocessing case",
        year=2026,
        case_id="C-001",
        subsystem="preprocessing"
    );
    c2 = Case(
        title="invalid diagnostics case",
        year=2026,
        case_id="C-002",
        subsystem="diagnostics",
        valid_program=False
    );
    c3 = Case(
        title="code generation case",
        year=2026,
        case_id="C-003",
        subsystem="codegen"
    );

    o1 = Observation(
        title="diagnostic comparison",
        year=2026,
        owner="diagnostics",
        normalized_match=False
    );
    o2 = Observation(
        title="artifact comparison",
        year=2026,
        owner="codegen"
    );

    a1 = Artifact(
        title="object output",
        year=2026,
        artifact_kind="object",
        fingerprint="obj-c003",
        bytes_match=False,
        structure_match=True
    );
    a2 = Artifact(
        title="preprocessed output",
