"""Property-read cost demo: model the issue where reading a property depends
on its position in the record, and walking a large expansion pays per-property
lookup cost. The walker aggregates three properties per node and reports total
work, exposing the redundancy the issue complains about."""

node Property {
    has name: str = "";
    has slot: int = 0;
    has value: float = 0.0;
}

edge PartOf {
    has ordinal: int = 0;
}

node Record {
    has label: str = "";
    has first: float = 0.0;
    has middle: float = 0.0;
    has last: float = 0.0;
}

walker Aggregator {
    has total_first: float = 0.0;
    has total_middle: float = 0.0;
    has total_last: float = 0.0;
    has per_node_lookups: int = 0;
    has per_node_bulk_reads: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can expand with Record entry {
        if here.label in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.label);
            f = here.first;
            m = here.middle;
            ln = here.last;
            self.total_first = self.total_first + f;
            self.total_middle = self.total_middle + m;
            self.total_last = self.total_last + ln;
            self.per_node_lookups = self.per_node_lookups + 3;
            self.per_node_bulk_reads = self.per_node_bulk_reads + 1;
            visit [-->];
        }
    }

    can drill with PartOf entry {
        visit [-->];
    }
}

walker SlotAuditor {
    has seen_slots: list[int] = [];
    has seen_records: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can step with Property entry {
        if here.slot not in self.seen_slots {
            self.seen_slots.append(here.slot);
        }
        visit [-->];
    }

    can step_rec with Record entry {
        if here.label not in self.seen_records {
            self.seen_records.append(here.label);
        }
        visit [-->];
    }
}

with entry {
    r1 = Record(label="r1", first=10.0, middle=20.0, last=30.0);
    r2 = Record(label="r2", first=1.5, middle=2.5, last=3.5);
    r3 = Record(label="r3", first=100.0, middle=200.0, last=300.0);

    p_first = Property(name="first", slot=0, value=0.0);
    p_mid = Property(name="middle", slot=4, value=0.0);
    p_last = Property(name="last", slot=7, value=0.0);

    r1 +>:PartOf(ordinal=0):+> p_first;
    r1 +>:PartOf(ordinal=4):+> p_mid;
    r1 +>:PartOf(ordinal=7):+> p_last;
    r2 +>:PartOf(ordinal=0):+> p_first;
    r2 +>:PartOf(ordinal=4):+> p_mid;
    r2 +>:PartOf(ordinal=7):+> p_last;
    r3 +>:PartOf(ordinal=0):+> p_first;
    r3 +>:PartOf(ordinal=4):+> p_mid;
    r3 +>:PartOf(ordinal=7):+> p_last;

    root ++> r1 ++> r2 ++> r3;

    agg = Aggregator();
    root spawn agg;
    print(
        f"bulk reads={agg.per_node_bulk_reads} per-node-lookups={agg.per_node_lookups} "
        f"first_total={agg.total_first} middle_total={agg.total_middle} last_total={agg.total_last}"
    );
    print(
        f"records-visited={agg.visited}"
    );

    auditor = SlotAuditor();
    root spawn auditor;
    print(
        f"slots-observed={auditor.seen_slots} records-observed={auditor.seen_records}"
    );
