"""Task dependency graph with memoization-style short-circuit traversal.

Models the pyinvoke/invoke #461 "advanced task dependencies / caching" use case:
a tree of tasks (some heavy, some cheap) connected by typed `Requires` edges.
A walker descends the dependency graph, but each task remembers whether its
result has already been "produced" — re-entering an already-completed task
short-circuits instead of re-running its body. This is the make-like behavior
the issue asks for: tasks declare what they need, run only as many times as
required, and skip work that has already been done.
"""

node Task {
    has title: str = "";
    has heavy: bool = False;
    has done: bool = False;
    has runs: int = 0;
}

edge Requires {
    has via: str = "pre";
}

walker Executor {
    can start with Root entry {
        visit [->:Requires:->];
    }

    can run_task with Task entry {
        if here.done {
            print(f"  [skip ] {here.title} (already done, runs={here.runs})");
            visit [->:Requires:->];
            return;
        }
        if here.heavy {
            print(f"  [heavy] {here.title} -- doing real work");
            here.runs = here.runs + 1;
        } else {
            print(f"  [light] {here.title} -- quick step");
            here.runs = here.runs + 1;
        }
        here.done = True;
        visit [->:Requires:->];
    }
}

with entry {
    # Build a small dependency tree. `deploy` requires `build_artifact`
    # requires `compile` and `fetch_secrets`. `compile` itself requires
    # `fetch_secrets` (shared subtree).
    fetch_secrets = Task(title="fetch_secrets", heavy=True);
    compile_t = Task(title="compile", heavy=True);
    build_artifact = Task(title="build_artifact", heavy=True);
    provision_db = Task(title="provision_db", heavy=True);
    deploy = Task(title="deploy", heavy=True);

    root +>:Requires(via="pre"):+> deploy;
    deploy +>:Requires:+> build_artifact;
    deploy +>:Requires:+> provision_db;
    build_artifact +>:Requires:+> compile_t;
    build_artifact +>:Requires:+> fetch_secrets;
    compile_t +>:Requires:+> fetch_secrets;
    provision_db +>:Requires:+> fetch_secrets;

    print("=== first execution pass ===");
    Executor() spawn deploy;

    print("=== second execution pass (everything should be skipped) ===");
    Executor() spawn deploy;

    print(f"final runs: "
          f"fetch_secrets={fetch_secrets.runs}, "
          f"compile={compile_t.runs}, "
          f"build_artifact={build_artifact.runs}, "
          f"provision_db={provision_db.runs}, "
          f"deploy={deploy.runs}");
}

"""Recursive repr over self-containing Containers.

Models pyochain-style containers where a Container may hold itself
directly or transitively. A walker descends the containment graph via a
typed `Holds` edge, tracking every node it has entered so it can stop
recursion cleanly and surface the cycle that the original repr would
have recursed on forever.
"""

node Container {
    has name: str = "";
    has payload: str = "";
    has visited: bool = False;
}

edge Holds {
    has order: int = 0;
}

walker ReprWalker {
    has indent: int = 0;
    has depth_limit: int = 16;
    has cycle_detected: bool = False;
    has self_ref_name: str = "";

    can start with Root entry {
        print("ReprWalker: descending containment graph");
        visit [->:Holds:->];
    }

    can render with Container entry {
        pad = "  " * self.indent;
        marker = " [SELF]" if here.payload == "self" else "";
        print(f"{pad}- {here.name}{marker}");
        if here.visited {
            self.cycle_detected = True;
            if here.payload == "self" {
                self.self_ref_name = here.name;
            }
            print(f"{pad}  (already entered, stopping recursion)");
            return;
        }
        if self.indent >= self.depth_limit {
            print(f"{pad}  (depth limit reached)");
            disengage;
        }
        here.visited = True;
        self.indent += 1;
        visit [->:Holds:->];
    }
}

with entry {
    outer = Container(name="outer", payload="box");
    inner = Container(name="inner", payload="crate");
    leaf = Container(name="leaf", payload="widget");
    recursive = Container(name="recursive", payload="self");

    root +>:Holds(order=0):+> outer;
    outer +>:Holds(order=1):+> inner;
    inner +>:Holds(order=2):+> leaf;
    inner +>:Holds(order=3):+> recursive;
    recursive +>:Holds(order=0):+> recursive;

    w = ReprWalker();
    root spawn w;

    print("");
    if w.cycle_detected {
        print(f"Cycle detected at '{w.self_ref_name}' "
              f"({w.indent} indents deep) -- repr would have recursed forever");
    } else {
        print("No cycle detected.");
    }
}

"""Per-issue routing pipeline: refresh gate, grounding, complexity routing,
and safe skip behavior for needs_attention.

Models the documentation issue's call order:
  1. live refresh of an issue
  2. read-only grounding against the source issue
  3. complexity-based routing (actionable vs already-resolved)
  4. safe skip semantics when needs_attention fires
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Issue {
    has title: str = "";
    has depth: int = 0;
    has status: str = "open";
    has evidence: str = "";
}

node Decision {
    has verdict: str = "";
    has fingerprint: str = "";
    has rationale: str = "";
}

# ---------------------------------------------------------------------------
# Typed edges
# ---------------------------------------------------------------------------

edge ParentOf { }
edge DependsOn { }
edge RoutedTo { }

# ---------------------------------------------------------------------------
# Walker: walks the routing pipeline across the issue graph.
# ---------------------------------------------------------------------------

walker IssueRouter {
    has decision: Decision = Decision();

    can start with Root entry {
        print(f"Router bound at root, decision verdict="
              f"{self.decision.verdict or '<unset>'}");
        visit [-->];
    }

    can refresh with Issue entry {
        print(f"[refresh] {here.title} (depth={here.depth}, "
              f"status={here.status})");
        visit [-->];
    }

    can ground with Issue entry {
        print(f"[ground] {here.title}: lineage and deps checked "
              f"(read-only)");
        visit [-->];
    }

    can route with Issue entry {
        if here.status == "resolved" {
            if here.evidence == "" {
                self.decision = Decision(
                    verdict="non_completion",
                    fingerprint="evidence-missing",
                    rationale="already-resolved requires fresh concrete "
                              "verification evidence"
                );
                print(f"[route] {here.title} -> non_completion "
                      f"(no concrete evidence)");
            } else {
                self.decision = Decision(
                    verdict="resolved",
                    fingerprint=here.evidence,
                    rationale="verified with concrete evidence"
                );
                print(f"[route] {here.title} -> resolved (verified)");
            }
        } elif here.depth <= 3 {
            self.decision = Decision(
                verdict="actionable",
                fingerprint=f"impl-depth-{here.depth}",
                rationale="0-3 implementation threshold"
            );
            print(f"[route] {here.title} -> actionable (depth {here.depth})");
        } else {
            self.decision = Decision(
                verdict="decompose",
                fingerprint=f"decomp-depth-{here.depth}",
                rationale="4-5 decomposition threshold"
            );
            print(f"[route] {here.title} -> decompose (depth {here.depth})");
        }
        visit [-->];
    }

    can finalize with Decision entry {
        print(f"[finalize] decision={here.verdict} "
              f"fingerprint={here.fingerprint}");
        print(f"[finalize] rationale: {here.rationale}");
    }
}

# ---------------------------------------------------------------------------
# Walker: safe-skip for needs_attention.
# ---------------------------------------------------------------------------

walker NeedsAttentionSkipper {
    has recorded_fingerprint: str = "";
    has source_closed: bool = False;
    has delivery_attempted: bool = False;

    can start with Root entry {
        print("[skipper] entering pipeline");
        visit [-->];
    }

    can skip_attention with Issue entry {
        self.recorded_fingerprint = f"fp-{here.title}-{here.status}";
        self.source_closed = False;
        self.delivery_attempted = False;

        print(f"[skip] {here.title}: recorded fingerprint="
              f"{self.recorded_fingerprint}; source stays open; "
              f"no lgtm, no delivery");
        disengage;
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    root_issue = Issue(
        title="issue-149-routing-documentation",
        depth=3,
        status="open"
    );

    parent_issue = Issue(
        title="issue-149-resolution-proof",
        depth=2,
        status="resolved",
        evidence="verified-by-tests-2024-Q4"
    );

    dep_issue = Issue(
        title="issue-149-safe-delivery",
        depth=2,
        status="resolved",
        evidence="delivery-receipt-2024-Q4"
    );

    child_low = Issue(
        title="issue-149-grounding-gate",
        depth=4,
        status="open"
    );

    child_high = Issue(
        title="issue-149-workflow-regressions",
        depth=5,
        status="open"
    );

    parent_issue +>:ParentOf:+> root_issue;
    root_issue +>:DependsOn:+> dep_issue;
    root_issue +>:ParentOf:+> child_low;
    root_issue +>:ParentOf:+> child_high;

    root spawn IssueRouter();
}

