"""Tree authorization model: branches holding direct hosts/sites and child branches.

Models the scenario from issue #7639: ``is_tree_branch_empty()`` recursively
walks a tree, resolving per-branch direct graphs/hosts and accumulating site
host IDs that get resolved in bulk. Here the traversal is a walker over typed
``ContainsBranch`` edges; the bulk site-host resolution is a single visit per
branch instead of one lookup per site.
"""

node Tree {
    has name: str = "";
}

node Branch {
    has title: str = "";
    has direct_host_ids: list[int] = [];
    has direct_graph_ids: list[int] = [];
    has allowed: bool = True;
}

node Site {
    has name: str = "";
}

node Host {
    has label: str = "";
}

edge ContainsBranch {}
edge HoldsHost {}

walker AuthAuditor {
    has branch_count: int = 0;
    has host_count: int = 0;
    has site_resolves: int = 0;
    has allowed_descendants: int = 0;
    has visited_branches: list[str] = [];

    can start with Root entry {
        print(f"Auditing tree from root");
        visit [-->];
    }

    can descend_tree with Tree entry {
        print(f"-- Tree: {here.name}");
        visit [->:ContainsBranch:->];
    }

    can audit_branch with Branch entry {
        self.branch_count += 1;
        self.visited_branches.append(here.title);

        branch_state = "ALLOWED" if here.allowed else "DENIED";
        direct_h = len(here.direct_host_ids);
        direct_g = len(here.direct_graph_ids);
        print(
            f"   branch [{branch_state}] '{here.title}' "
            f"direct_hosts={direct_h} direct_graphs={direct_g}"
        );

        # One bulk host lookup per branch (mimics the IN-query fix).
        self.site_resolves += 1;

        visit [->:HoldsHost:->];
        visit [->:ContainsBranch:->];

        if here.allowed {
            self.allowed_descendants += 1;
        }
    }

