"""Scoped-item write-set guard.

Issue #575 — enforce declared write-sets so a scoped item cannot silently
expand its blast radius. Models the host-side capability-denial posture:
each scoped item declares a write-set of file paths; the guard
refuses writes outside it deterministically; the harness still records
what actually changed.
"""

# A scoped work item: declares intent via a write-set of file paths.
node ScopedItem {
    has title: str = "";
    has declared_writes: list[str] = [];
    has attempted_writes: list[str] = [];
    has refused_writes: list[str] = [];
    has blocked: bool = False;
}

# A file the item wants to mutate.
node File {
    has path: str = "";
    has in_scope: bool = False;
}

# Typed edge: "this file is the target of an attempted write."
edge AttemptedOn { }

walker WriteGuard {
    has current_path: str = "";

    can begin with Root entry {
        visit [-->];
    }

    can audit with ScopedItem entry {
        # Two-phase mutation: collect every AttemptedOn target first,
        # then judge. Avoids mid-iteration mutation surprises.
        attempted = [];
        for f in [->:AttemptedOn:->] {
            attempted.append(f);
        }
        for f in attempted {
            self.current_path = f.path;
            declared = here.declared_writes;
            in_declared = False;
            for p in declared {
                if p == f.path {
                    in_declared = True;
                }
            }
            # Harness-managed paths are the recorded escape hatch.
            is_harness = False;
            if f.path.startswith("docs/decision-log/") {
                is_harness = True;
            }
            if f.path == "checkpoints" {
                is_harness = True;
            }
            if in_declared or is_harness {
                f.in_scope = True;
            } else {
                f.in_scope = False;
                here.refused_writes.append(f.path);
                print(f"refused write to {f.path}, not in declared write-set");
            }
        }
        if len(here.refused_writes) > 0 {
            here.blocked = True;
        }
        visit [-->];
    }
}

with entry {
    # The spec for #548: message-only change to two files. The
    # declaration is the prose write-set; the guard enforces it.
    item = ScopedItem(
        title="#548 message-only patch",
        declared_writes=["src/parser.ts", "src/format.ts"]
    );
    root ++> item;

    # Two permitted files.
    f1 = File(path="src/parser.ts", in_scope=True);
    f2 = File(path="src/format.ts", in_scope=True);
    item +>:AttemptedOn:+> f1;
    item +>:AttemptedOn:+> f2;

    # The prohibited work that blew both attempts: a brand-new probe
    # file plus modifications the ticket explicitly forbade.
    f3 = File(path="dependency-integrity.ts", in_scope=False);
    f4 = File(path="seat-isolation.ts", in_scope=False);
    f5 = File(path="worktree-deps.ts", in_scope=False);
    item +>:AttemptedOn:+> f3;
    item +>:AttemptedOn:+> f4;
    item +>:AttemptedOn:+> f5;

    # Harness-managed path: always permitted, the recorded escape hatch.
    f6 = File(path="docs/decision-log/548.md", in_scope=False);
    item +>:AttemptedOn:+> f6;

    item spawn WriteGuard();

    print(f"item.blocked = {item.blocked}");
    print(f"declared_writes = {item.declared_writes}");
    print(f"refused_writes = {item.refused_writes}");
}

"""Adaptive ETL planning demo with typed dataflow edges and guarded traversal."""

node PlanItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Source(PlanItem) {
    has placement: str = "";
    has predicate: str = "";
    has projection: str = "";
}

node Transform(PlanItem) {
    has operation: str = "";
    has placement: str = "";
    has fused: bool = False;
    has handoff: bool = False;
}

node Sink(PlanItem) {
    has placement: str = "";
    has published: bool = False;
}

edge Flow {
    has channel: str = "";
}

walker AdaptivePlanner {
    has hops: int = 0;
    has max_hops: int = 16;

    can begin with Root entry {
        print("adaptive planner: analyzing reachable pipeline");
        visit [->:Flow:->] else {
            disengage;
        }
    }

    can plan_source with Source entry {
        self.hops = self.hops + 1;
        if self.hops >= self.max_hops {
            print("cycle guard stopped source traversal");
            disengage;
        }
        if here.available {
            print(f"source-local pushdown at {here.title}: "
                  f"predicate={here.predicate}, projection={here.projection}");
            visit [->:Flow:->] else {
                disengage;
            }
        } else {
            print(f"unavailable source rejected: {here.title}");
            disengage;
        }
    }

    can plan_transform with Transform entry {
        self.hops = self.hops + 1;
        if self.hops >= self.max_hops {
            print("cycle guard stopped transform traversal");
            disengage;
        }
        decision = "fused same-placement work" if here.fused else "second-target transformation";
        print(f"{decision}: {here.operation} on {here.placement}");
        if here.handoff {
            print("one Arrow handoff scheduled before this stage");
        }
        visit [->:Flow:->] else {
            disengage;
        }
    }

    can publish_sink with Sink entry {
        self.hops = self.hops + 1;
        if self.hops >= self.max_hops {
            print("cycle guard stopped sink traversal");
            disengage;
        }
        here.published = True;
        print(f"sink publication complete: {here.title} on {here.placement}");
    }
}

with entry {
    source = Source(
        title="orders",
        placement="Polars",
        predicate="country == 'US'",
        projection="id,total"
    );
    filter = Transform(
        title="filtered orders",
        operation="filter + project",
        placement="Polars",
        fused=True
    );
    handoff = Transform(
        title="customer enrichment",
        operation="join customer labels",
        placement="Pandas",
        handoff=True
    );
    sink = Sink(
        title="published report",
        placement="warehouse"
    );

    root +>:Flow(channel="input"):+> source;
    source +>:Flow(channel="pushdown"):+> filter;
    filter +>:Flow(channel="Arrow"):+> handoff;
    handoff +>:Flow(channel="publication"):+> sink;

    root spawn AdaptivePlanner();
}

"""Tracing model: Activity spans, listeners, propagators, and exception records.

Models the ATYA-069 scenario: an Activity (span) holds tags, baggage, and a
parent link. Listeners attach to Activities to react to lifecycle events.
Propagation moves a trace context across a boundary via a Propagator.
Exception recording copies redacted text into a snapshot.

The walker `Auditor` traverses the parent chain from a span back to the root,
detects cycles in parent links (no built-in visited set in jac 0.36.1), and
reports whether the chain is well-formed, malformed (unknown format), or
contains redaction leaks.
"""

node Activity {
    has name: str = "";
    has trace_id: str = "";
    has parent_id: str = "";
    has has_listeners: bool = False;
    has tags_allocated: bool = False;
    has service_name: str = "";
    has exception_text: str = "";
    has redacted: bool = True;
}

node Listener {
    has kind: str = "noop";
}

node Propagator {
    has format: str = "w3c";
    has allow_w3c: bool = True;
    has bounded: bool = True;
}

edge Parent {
    has depth: int = 0;
}

edge Attached {
    has since: str = "";
}

walker Auditor {
    has start_id: str = "";
    has findings: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can audit with Activity entry {
        # Fast path: no listeners means we must NOT have allocated tags yet.
        if not here.has_listeners and here.tags_allocated {
            self.findings.append(f"LEAK: tags allocated on '{here.name}' without listener");
        }

        # Per-span service identity is supposed to be dropped — flag it.
        if here.service_name != "" {
            self.findings.append(f"PER-SPAN SERVICE: '{here.name}' carries '{here.service_name}'");
        }

        # Redaction check: exception text must be empty unless explicitly kept.
        if here.exception_text != "" and here.redacted {
            self.findings.append(f"REDACTED: '{here.name}' exception text was copied");
        }

        # Walk the parent chain via typed edge. Cycle-safe by guard set.
        visit [->:Parent:->];
    }

    can walk with Activity entry {
        # Detached node reached via typed edge — record and continue if
        # not yet visited. (No built-in dedupe, so we guard explicitly.)
        if here.trace_id in ["", "unknown"] {
            self.findings.append(f"MALFORMED: parent link is '{here.parent_id}'");
            disengage;
        }
        if here.name == self.start_id {
            # Back to the start — chain complete.
            disengage;
        }
        visit [->:Parent:->];
    }
}

walker PropagationCheck {
    can begin with Root entry {
        visit [-->];
    }

    can check with Activity entry {
        # Walk attached listeners — typed edge.
        visit [->:Attached:->];
    }

    can inspect with Listener entry {
        if here.kind == "noop" and here != None {
            # Listener present but inactive — still an attachment, fine.
        }
    }

    can examine with Propagator entry {
        if here.format == "w3c" and not here.allow_w3c {
            print(f"PROPAGATOR REJECTED: w3c disabled on {here.format}");
        }
        if here.format != "w3c" and here.bounded {
            print(f"PROPAGATOR OK: non-w3c '{here.format}' is bounded");
        }
    }
}

with entry {
    # Build a small activity graph: a -> b -> c -> d (parent chain).
    a = Activity(name="server.receive", trace_id="abc123");
    b = Activity(name="server.process", trace_id="abc123", parent_id="server.receive");
    c = Activity(name="db.query", trace_id="abc123", parent_id="server.process");
    d = Activity(name="client.send", trace_id="abc123", parent_id="server.receive");

    # Wire the parent chain with typed edges.
    b +>:Parent(depth=1):+> a;
    c +>:Parent(depth=2):+> b;
    d +>:Parent(depth=1):+> a;

    root ++> a ++> b ++> c ++> d;

    # Attach a listener to one activity; leave another listener-less
    # but with tags already allocated (the leak scenario).
    b +>:Attached(since="start"):+> Listener(kind="metrics");

    leak = Activity(name="leak.span", trace_id="", tags_allocated=True);
    root ++> leak;

    # A redacted-exception snapshot.
    err = Activity(name="err.span", trace_id="zz", exception_text="NullReferenceException at line 42");
    root ++> err;

    # A propagator with non-w3c bounded format.
    p = Propagator(format="b3", bounded=True);
    root ++> p;

    # Run the auditor on the leaf of the chain.
    auditor = Auditor(start_id="d");
    d spawn auditor;
    print("AUDIT REPORT:");
    for line in auditor.findings {
        print(f"  - {line}");
    }

    # Run the propagation check.
    checker = PropagationCheck();
    root spawn checker;
}

"""Cost-ceiling plan approval: model the missing assistant message append.

Models the issue where the final assistant message is lost because it is not
appended to the transcript before awaiting plan approval. A walker traverses
the plan transcript and proves that persistence order matters.
"""

node Message {
    has role: str = "";
    has content: str = "";
    has persisted: bool = False;
}

node PlanStep {
    has title: str = "";
    has est_cost: float = 0.0;
}

node Transcript {
    has name: str = "";
    has approved: bool = False;
    has over_budget: bool = False;
}

edge Follows {}
edge StepOf {}
edge OwnedBy {}

walker ApprovalWalk {
    has path: list = [];
    has transcript_seen: str = "";

    can start with Root entry {
        visit [->:OwnedBy:->];
    }

    can enter_transcript with Transcript entry {
        self.transcript_seen = here.name;
        print(f"Entering transcript: {here.name} (approved={here.approved})");
        # Walk the messages first (chronological), then the plan steps.
        visit [->:Follows:->];
    }

    can collect_message with Message entry {
        label = "PERSISTED" if here.persisted else "LOST";
        print(f"  msg[{here.role}] {label}: {here.content}");
        self.path.append((here.role, here.persisted));
        visit [-->];
    }

    can review_step with PlanStep entry {
        if here.est_cost > 500.0 {
            here.est_cost = 500.0;
            print(f"  cost-ceiling clamped step '{here.title}' to 500.0");
        }
        self.path.append(("step", here.title));
        visit [-->];
    }

    can finalize with Transcript exit {
        last_role = "";
        last_persisted = True;
        for item in self.path {
            last_role = item[0];
            last_persisted = item[1];
        }
        if last_role == "assistant" and not last_persisted {
            print("BUG: final assistant message was NEVER appended before approval");
        } else {
            print("OK: final assistant message persisted before approval");
        }
        report self.path;
    }
}

with entry {
    t = Transcript(name="session-1", over_budget=True);
    sys_msg = Message(role="system", content="You are a planner.", persisted=True);
    user_msg = Message(role="user", content="Plan a deploy", persisted=True);
    # The bug: this assistant message is generated but NOT persisted yet.
    asst_msg = Message(role="assistant", content="Plan ready for review", persisted=False);
    step_a = PlanStep(title="compute", est_cost=300.0);
    step_b = PlanStep(title="ship", est_cost=620.0);

    root +>:OwnedBy:+> t;
    t +>:Follows:+> sys_msg;
    t +>:Follows:+> user_msg;
    t +>:Follows:+> asst_msg;
    t +>:StepOf:+> step_a;
    t +>:StepOf:+> step_b;

    root spawn ApprovalWalk();
}

