    can collect_path with WdmWavelengthPath entry {
        if here not in self.paths {
            self.paths.append(here);
        }
        visit [->:RealizesCircuit:->];
    }

    can collect_circuit with WdmCircuit entry {
        if here not in self.circuits {
            self.circuits.append(here);
        }
    }
}

