"""Flight network: priced legs normalize against the peak fare a scout reports."""

node Airport {
    has code: str = "";
    has city: str = "";
}

edge FlightLeg {
    has price: float = 0.0;

    def fare_fraction(max_fare: float) -> float {
        if max_fare <= 0.0 {
            return 0.0;
        }
        return self.price / max_fare;
    }
}

walker Scout {
    has legs: list[FlightLeg] = [];
    has prices: list[float] = [];
    has max_fare: float = 0.0;
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can explore with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            report leg.price;
            self.legs.append(leg);
            self.prices.append(leg.price);
            if leg.price > self.max_fare {
                self.max_fare = leg.price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    jfk = Airport(code="JFK", city="New York");
    ord_ap = Airport(code="ORD", city="Chicago");
    lax = Airport(code="LAX", city="Los Angeles");

    root ++> jfk;
    jfk +>:FlightLeg(price=450.0):+> ord_ap;
    ord_ap +>:FlightLeg(price=320.0):+> lax;
    jfk +>:FlightLeg(price=890.0):+> lax;

    print("Scout collecting ticket prices across the network...");
    scout = Scout();
    root spawn scout;
    peak = scout.max_fare;
    print(f"Prices collected: {scout.prices}");
    print(f"Peak fare reported: ${peak:.0f}");

    print("Each leg as a fraction of the top fare:");
    for leg in scout.legs {
