"""Diamond dependency build graph: count total build minutes, auditing shared tasks only once."""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has audited: bool = False;
}

walker OrderAuditor {
    has total_minutes: int = 0;
    has audited_ids: list = [];

    can start with Root entry {
        print("Build audit starting...");
        visit [-->];
    }

    can audit with Task entry {
        already = here.title in self.audited_ids;
        if not already {
            self.audited_ids.append(here.title);
            here.audited = True;
            self.total_minutes = self.total_minutes + here.minutes;
            print(f"[+] Auditing {here.title} (+{here.minutes} min)");
        } else {
            print(f"[=] Skipping {here.title} (already audited)");
        }
        visit [-->];
    }
}

walker DiamondRunner {
    can start with Root entry {
        print("Walking diamond dependency graph...");
        auditor = OrderAuditor();
        here spawn auditor;
    }

    can traverse with Task entry {
        print(f"Reached {here.title} via path");
        visit [-->];
    }
}

with entry {
    # Diamond: SharedLib is depended on by both ModuleA and ModuleB,
    # which both feed into App. Multiple paths reach SharedLib and App,
    # but the auditor must count each exactly once.
    shared_lib = Task(title="SharedLib", minutes=10);
    mod_a = Task(title="ModuleA", minutes=25);
    mod_b = Task(title="ModuleB", minutes=30);
    app = Task(title="App", minutes=45);

    root ++> shared_lib
        ++> mod_a
        ++> mod_b
        ++> app;

    # Extra diamond through Utilities
    utils = Task(title="Utilities", minutes=15);
    ui = Task(title="UI", minutes=20);
    api = Task(title="API", minutes=35);

    mod_a ++> utils
        ++> ui;

    mod_b ++> utils
        ++> api;

    root spawn DiamondRunner();
}

