"""Native dependency-graph demo with typed edges and cycle detection."""

node Cell {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sheet: str = "Sheet1";
    has a1: str = "";
    has formula: str = "";
}

edge Contains {
    has scope: str = "formula";
}

edge DependsOn {
    has relationship: str = "precedent";
}

walker CycleScanner {
    has path: list[str] = [];
    has cycle_cells: list[str] = [];
    has max_nodes: int = 10;
    has truncated: bool = False;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Cell entry {
        if here.a1 in self.path {
            for cell_name in self.path {
                if len(self.cycle_cells) < self.max_nodes {
                    self.cycle_cells = self.cycle_cells + [cell_name];
                } else {
                    self.truncated = True;
                }
            }
            print(f"cycle detected at {here.sheet}!{here.a1}");
            disengage;
        }

        self.path = self.path + [here.a1];
        visit [->:DependsOn:->] else {
            disengage;
        }
