"""Source-only delivery handoff without requiring shared-target integration."""

node Plan {
    has title: str = "";
    has delivery_target_branch: str = "";
    has source_only: bool = True;
    has available: bool = True;
}

node Work {
    has title: str = "";
    has source_branch: str = "";
    has candidate_commit: str = "";
    has reviewed: bool = False;
    has integrated: bool = False;
    has available: bool = True;
}

node SourceHandoff {
    has title: str = "";
    has isolated_ref: str = "";
    has exact_commit: str = "";
    has reviewed: bool = False;
    has published: bool = False;
    has integrated: bool = False;
    has available: bool = True;
}

node IntegrationAuthority {
    has title: str = "";
    has owner: str = "";
    has integrated_commit: str = "";
    has reconciled: bool = False;
    has available: bool = True;
}

edge PlanWork { }
edge Publishes { }
edge AwaitsIntegration { }

walker DeliveryAuditor {
    has target_branch: str = "";
    has expected_commit: str = "";

    can start with Root entry {
        print("walking source-only delivery graph");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_plan with Plan entry {
        self.target_branch = here.delivery_target_branch;
        print(f"Plan: {here.title}");
        print(f"source-only mode: {here.source_only}");
        visit [->:PlanWork:->] else {
            disengage;
        }
    }

    can inspect_work with Work entry {
        self.expected_commit = here.candidate_commit;
        print(f"Work: {here.title}");
        print(f"reviewed candidate: {here.candidate_commit}");
        print(f"shared-target integration complete: {here.integrated}");
        visit [->:Publishes:->] else {
            disengage;
        }
    }

    can inspect_handoff with SourceHandoff entry {
        commit_matches = here.exact_commit == self.expected_commit;
        isolated = here.isolated_ref != self.target_branch;
        valid = commit_matches and isolated and here.reviewed and here.published and not here.integrated;

        if valid {
            print(f"source-only receipt accepted for {here.exact_commit}");
            print(f"isolated ref: {here.isolated_ref}");
        } else {
            print("source-only receipt rejected");
        }

        visit [->:AwaitsIntegration:->] else {
            disengage;
        }
    }

    can inspect_authority with IntegrationAuthority entry {
        exact_match = here.integrated_commit == self.expected_commit;

        if exact_match and here.reconciled {
            print(f"integration authority reconciled {here.integrated_commit}");
        } else {
            print("downstream integration is still pending");
        }

        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    plan = Plan(
        title="Kernel V2 isolated source delivery",
        delivery_target_branch="kernel-v2/architecture"
    );

    work = Work(
        title="WSL performance follow-through",
        source_branch="work-profile-and-remove-duplicate-exp",
        candidate_commit="d338b273b1d1fa0331cfd5baee5f72ebee6eac49",
        reviewed=True
    );

    receipt = SourceHandoff(
        title="Reviewed source-only handoff",
        isolated_ref="work-profile-and-remove-duplicate-exp",
        exact_commit="d338b273b1d1fa0331cfd5baee5f72ebee6eac49",
        reviewed=True,
        published=True
    );

    authority = IntegrationAuthority(
        title="Mac integration authority",
