        integrated_commit="d338b273b1d1fa0331cfd5baee5f72ebee6eac49",
        reconciled=True
    );

    root ++> plan;
    plan +>:PlanWork:+> work;
    work +>:Publishes:+> receipt;
    receipt +>:AwaitsIntegration:+> authority;

    root spawn DeliveryAuditor();
