"""SysML model: imports vs real elements.

The issue: import statements were modeled as full-blown Elements and got
embedded alongside real Parts/Requirements, polluting vector-search
resolution. The idiomatic fix: imports are NOT nodes at all — they live
as a list on the importing Package, so embedding/traversal code that
walks nodes never even sees them.
"""

node Package {
    has name: str = "";
    has doc: str | None = None;
    # Unresolved import paths — recorded but not modeled as nodes.
    # This matches the "unresolved, just recorded" framing in CLAUDE.md.
    has imports: list[str] = [];
}

node Element {
    has kind: str = "";
    has name: str = "";
    has qualified_name: str = "";
    has doc: str | None = None;
}

node PartDefinition(Element) {
    has kind: str = "PartDefinition";
}

node RequirementDefinition(Element) {
    has kind: str = "RequirementDefinition";
}

# Package CONTAINS its real elements.
edge Contains { }

# --- Text builders (the "embedding" surface in the original codebase) ---

def element_text(elem: Element) -> str {
    return f"{elem.kind} - {elem.name}";
}

def package_text(pkg: Package) -> str {
    # Imports intentionally excluded: they are not part of the search
    # index. An import path can collide with a real element name without
    # ever winning a vector-search match.
    return f"Package - {pkg.name}";
}

# --- The walker: index every real Element for resolution, skipping imports. ---

walker Indexer {
    has results: list[Element] = [];
    has query_token: str = "";

    can start with Root entry {
        visit [-->];
    }

    can descend with Package entry {
        visit [->:Contains:->];
    }

    can collect with PartDefinition | RequirementDefinition entry {
        self.results.append(here);
        # Do NOT visit further — leaves.
    }
}

# --- The resolver: pretend NL query, find the best matching Element. ---

def resolve_element(indexer: Indexer, token: str) -> Element | None {
    indexer.query_token = token;
    best: Element | None = None;
    best_score: int = -1;
    token_lc = token.lower();
    for cand in indexer.results {
        score = 0;
        if token_lc in cand.name.lower() {
            score = len(cand.name);
        }
        if score > best_score {
            best_score = score;
            best = cand;
        }
    }
    return best;
}

with entry {
    demo = Package(name="Demo", doc="root package");
    # The offending imports — recorded on the package, NOT as nodes.
    demo.imports.append("Utilities::Common");
    demo.imports.append("Utilities::*");

    widget = PartDefinition(
        name="Widget",
        qualified_name="Demo.Widget",
        doc="a reusable widget"
    );
    req = RequirementDefinition(
        name="Common",
        qualified_name="Demo.Common",
        doc="a real requirement whose name collides with the import"
    );

    root ++> demo;
    demo +>:Contains:+> widget;
    demo +>:Contains:+> req;

    # Index the graph: only real Elements land in the index.
    idx = Indexer();
    demo spawn idx;

    print(f"Indexed {len(idx.results)} elements (imports excluded):");
    for e in idx.results {
        print(f"  - {element_text(e)}  qn={e.qualified_name}");
    }
    print(f"Package-level imports (never indexed): {demo.imports}");

    # The repro query: "Common" must resolve to the real Requirement,
    # NOT to the `Import Utilities::Common` pseudo-element.
    hit = resolve_element(idx, "Common");
    if hit is not None {
        print(f"resolve_element('Common') -> {element_text(hit)}");
    } else {
        print("resolve_element('Common') -> None");
    }
}

