"""PDS triage round: model rows as nodes and walk them with a triage walker.

Demonstrates typed edges for parent/child relationships, traversal
across the live rows, and the three dispositions (CLOSED, PARKED,
OPEN) the issue requires every row to prove.
"""

node Row {
    has title: str = "";
    has owner: str = "";
    has disposition: str = "open";
    has reason: str = "";
    has reopen_trigger: str = "";
    has fixed_by_commit: str = "";
}

edge Parents { }

walker Triage {
    has visited: list[str] = [];
    has findings: list[str] = [];

    can start with Root entry {
        visit [->:Parents:->];
    }

    can audit with Row entry {
        rid = here.title;
        if rid in self.visited {
            disengage;
        }
        self.visited.append(rid);

        verdict = "UNKNOWN";
        if here.disposition == "CLOSED" and here.fixed_by_commit != "" {
            verdict = f"CLOSED ({here.fixed_by_commit})";
        } elif here.disposition == "PARKED"
            and here.reason != "" and here.reopen_trigger != "" {
            verdict = f"PARKED -> {here.reopen_trigger}";
        } elif here.disposition == "open" and here.owner != "" {
            verdict = f"OPEN (owner={here.owner})";
        }

        line = f"[{verdict}] {rid}: {here.reason}";
        self.findings.append(line);
        print(line);
        visit [->:Parents:->];
    }
}

with entry {
    # Buried exemplar park (template - DO NOT TOUCH)
    exemplar = Row(
        title="pds-bl-template-park",
        disposition="PARKED",
        reason="wave-22 / charter PDS-D332: blocker is X; not unblocked by Y; REACTIVATE Z",
        reopen_trigger="REACTIVATE when Z is merged"
    );

    # Recoverable boilerplate row
    boilerplate = Row(
