"""SpiceDB-style authorization graph: roles, permissions, and the traversal
that decides what a principal can see.

Models the two planes from the issue:
  Plane A — schema surface (type/field visibility) walked by `SchemaGate`.
  Plane B — per-row object access walked by `ObjectAccessAuditor`, which
  must respect cycle guards and a depth cap.
"""

node Principal {
    has name: str = "";
    has role_key: str = "";
}

node ResourceType {
    has name: str = "";
    has surface: str = "";
}

node Action {
    has name: str = "";
}

node ObjectInstance {
    has kind: str = "";
    has label: str = "";
}

# A principal holds a role.
edge HoldsRole {
    has granted_at: str = "";
}

# A role authorizes a (resource-type, action) pair — Plane A surface.
edge Authorizes {
    has via: str = "";
}

# A (resource-type, action) pair gates which ObjectInstance rows are visible — Plane B.
edge GrantsObjectAccess {
    has depth_cap: int = 3;
}

# An ObjectInstance links to its owner and to parent/child rows (the
# hand-rolled graph machinery the issue complains about).
edge OwnedBy {
    has since: str = "";
}

edge ParentOf {
    has weight: int = 1;
}

walker SchemaGate {
    has principal_name: str = "";
    has allowed: list[str] = [];

    can start with Root entry {
        visit [->:HoldsRole:->];
    }

    can collect_role with Principal entry {
        self.principal_name = here.name;
        visit [->:Authorizes:->];
    }

    can collect_surface with ResourceType entry {
        if here.surface != "" {
            self.allowed.append(here.surface);
        }
        visit [-->];
    }
}

walker ObjectAccessAuditor {
    has principal_name: str = "";
    has target_kind: str = "";
    has visited: list[str] = [];
    has reachable: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        visit [->:HoldsRole:->];
    }

    can bind_principal with Principal entry {
        self.principal_name = here.name;
        visit [->:Authorizes:->];
    }

    can pick_kind with ResourceType entry {
        self.target_kind = here.name;
        visit [->:GrantsObjectAccess:->];
    }

    can audit with ObjectInstance entry {
        # Cycle guard: walkers in jac 0.36 have no built-in dedupe on cyclic
        # edges. Without an explicit visited set the walk hangs on Owner→Row→Owner
        # loops (see probe_walker_cycle.jac).
        key = f"{here.kind}:{here.label}";
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);

        if here.kind == self.target_kind {
            self.reachable.append(here.label);
        }
        if self.depth >= 5 {
            disengage;
        }
        self.depth += 1;
        visit [->:ParentOf:->];
    }
}

with entry {
    # Principals
    alice = Principal(name="alice", role_key="editor");
    bob = Principal(name="bob", role_key="viewer");

    # Schema surface nodes
    task_type = ResourceType(name="Task", surface="Task");
    user_type = ResourceType(name="User", surface="User");
    delete_mut = ResourceType(name="deleteTask", surface="Mutation:deleteTask");

    # Object instances (the rows whose access the issue worries about)
    task_1 = ObjectInstance(kind="Task", label="t-1");
    task_2 = ObjectInstance(kind="Task", label="t-2");
    task_3 = ObjectInstance(kind="Task", label="t-3");
    user_alice = ObjectInstance(kind="User", label="alice-row");

    # Plane A: hold-role + authorize edges
    alice +>:HoldsRole(granted_at="2024-01-01"):+> ResourceType(name="editor-slot", surface="");
    bob   +>:HoldsRole(granted_at="2024-01-01"):+> ResourceType(name="viewer-slot", surface="");

    # editor can see Task + deleteTask mutation; viewer sees User only
    task_type     +>:Authorizes(via="role:editor"):+> delete_mut;
    alice +>:HoldsRole(granted_at="2024-01-01"):+> task_type;
    alice +>:HoldsRole(granted_at="2024-01-01"):+> delete_mut;
    bob   +>:HoldsRole(granted_at="2024-01-01"):+> user_type;

    # Plane B: object instances linked through owners + parent edges
    # (the hand-rolled graph the issue replaces)
    task_1 +>:OwnedBy(since="2024"):+> user_alice;
    task_2 +>:OwnedBy(since="2024"):+> user_alice;
    task_3 +>:OwnedBy(since="2024"):+> user_alice;
    user_alice +>:ParentOf(weight=1):+> task_1;
    task_1 +>:ParentOf(weight=1):+> task_2;
    task_2 +>:ParentOf(weight=1):+> task_3;
    # cycle that would hang an unguarded walker:
    task_3 +>:ParentOf(weight=1):+> user_alice;

    # Wire the demo graph onto root and spawn both walkers.
    root ++> alice ++> bob
        ++> task_type ++> user_type ++> delete_mut
        ++> task_1 ++> task_2 ++> task_3 ++> user_alice;

    gate = SchemaGate();
    root spawn gate;
    print(f"[Plane A] {gate.principal_name} may see surfaces: {gate.allowed}");

    auditor = ObjectAccessAuditor();
    root spawn auditor;
    print(f"[Plane B] {auditor.principal_name} reachable {auditor.target_kind} rows: {auditor.reachable}");
}

