"""A report preserves completed checks when one ontology lookup is unreachable."""

node ValidationReport {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reference_section: str = "";
    has term_section: str = "";
    has validation_state: str = "PENDING";
    has frontmatter: str = "";
    has recipe_exit_code: int = 0;
}

node TermCheck {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has curie: str = "";
    has reported_label: str = "";
    has canonical_label: str = "";
    has cache_hit: bool = False;
    has network_reachable: bool = True;
    has resolves: bool = True;
    has label_matches: bool = True;
    has max_attempts: int = 3;
    has attempts: int = 0;
    has retry_schedule: str = "1s, 2s, 4s";
    has outcome: str = "";
}

edge HasReport { }
edge ChecksTerm { }

walker ValidationAuditor {
    has resolved_count: int = 0;
    has unreachable_count: int = 0;
    has finding_count: int = 0;

    can begin with Root entry {
        visit [->:HasReport:->];
    }

    can inspect_report with ValidationReport entry {
        here.reference_section = "COMPLETE: references checked";
        here.term_section = "INCOMPLETE: term validation in progress";
        visit [->:ChecksTerm:->];
    }

    can finish_report with ValidationReport exit {
        if self.unreachable_count > 0 {
            here.validation_state = "INCOMPLETE";
            here.recipe_exit_code = 1;
            here.term_section = "INCOMPLETE: ontology service unreachable after bounded retries";
        } else {
            if self.finding_count > 0 {
                here.validation_state = "VALIDATED_WITH_FINDINGS";
            } else {
                here.validation_state = "VALIDATED";
            }
            here.recipe_exit_code = 0;
            here.term_section = "COMPLETE: all term checks finished";
        }

        here.frontmatter = f"resolved={self.resolved_count}, "
            f"unreachable={self.unreachable_count}, "
            f"findings={self.finding_count}";

        print(here.reference_section);
        print(here.term_section);
        print(f"{here.title}: {here.validation_state}");
        print(here.frontmatter);
    }

    can check_term with TermCheck entry {
        if here.cache_hit {
            here.attempts = 0;
            here.outcome = "resolved-from-cache";
            self.resolved_count += 1;
        } else {
            here.attempts = here.max_attempts;

            if here.network_reachable {
                if here.resolves {
                    if here.label_matches {
                        here.outcome = "resolved";
                        self.resolved_count += 1;
                    } else {
                        here.outcome = "resolved-but-label-mismatch";
                        self.finding_count += 1;
                    }
                } else {
                    here.outcome = "unresolved";
                    self.finding_count += 1;
                }
            } else {
                here.outcome = f"unreachable-after-{here.attempts}-attempts";
                self.unreachable_count += 1;
            }
        }

        print(f"{here.curie}: {here.outcome}");

        if here.curie != "MONDO:0012997" {
            visit [->:ChecksTerm:->];
        }
    }
}

with entry {
    validation_report = ValidationReport(
        title="SRD5A3-CDG research report",
        year=2025
    );

    timeout_term = TermCheck(
        title="Coloboma",
        curie="HP:0000589",
        reported_label="Coloboma",
        canonical_label="Coloboma",
        network_reachable=False,
        resolves=False
    );

    cached_term = TermCheck(
        title="Ataxia",
        curie="HP:0001251",
        reported_label="Ataxia",
        canonical_label="Ataxia",
        cache_hit=True
    );

    invented_term = TermCheck(
        title="SRD5A3-CDG",
        curie="MONDO:0012997",
        reported_label="congenital disorder of glycosylation, type Iq",
        canonical_label="cholestasis-pigmentary retinopathy-cleft palate syndrome",
        label_matches=False
    );

    root +>:HasReport:+> validation_report;
    validation_report +>:ChecksTerm:+> timeout_term;
    timeout_term +>:ChecksTerm:+> cached_term;
    cached_term +>:ChecksTerm:+> invented_term;

    root spawn ValidationAuditor();
}

"""Kitchen line health inspection: per-station temperature check + visit log.

A single Inspection walker carries both behaviors. At every station it
flags temperatures above 40 C as a violation AND logs the visit, so the
two checks co-occur at each node in a single traversal pass.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker Inspection {
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Station entry {
        # Check 1: flag any station above the 40 C safety threshold.
        if here.celsius > 40.0 {
            print(f"[VIOLATION] {here.name} is {here.celsius} C");
        } else {
            print(f"[OK] {here.name} is {here.celsius} C");
        }

        # Check 2: append every station visit to the walker's log.
        self.log.append(f"visited {here.name}");

        visit [-->];
    }
}

with entry {
