    print(f"Visit log: {inspector.log}");
}

"""Build-system dependency auditor: counts unique reachable tasks.

Diamonds (a task with two or more incoming paths) are common in real
build graphs — two modules both link the same shared library, two
optimization passes both depend on the same analysis phase, etc. A
naive traversal would double-count the shared task; this program models
each task as a node, each build-minute cost as a node field, and uses
a walker with an explicit visited-set so a task reachable by multiple
paths is audited exactly once. The visit-set is the domain rule, not
scaffolding, so it is preserved.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker Auditor {
    has visited: list[str] = [];
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if here.title not in self.visited {
            self.visited.append(here.title);
            self.total_minutes = self.total_minutes + here.minutes;
            print(f"[audit] {here.title} ({here.minutes} min)");
            visit [-->];
        } else {
            print(f"[skip] {here.title} already audited");
        }
    }
}

with entry {
    root ++> Task(title="compile-core", minutes=5)
        ++> Task(title="link-shared", minutes=3)
        ++> Task(title="compile-modA", minutes=4)
        ++> Task(title="compile-modB", minutes=4)
        ++> Task(title="package", minutes=2);

    # Diamond: both compile-modA and compile-modB depend on link-shared.
    # The walker would reach link-shared twice if we did not guard it,
    # which would double-count its 3 minutes.
    # Edges:
    #   compile-core -> link-shared
    #   compile-core -> compile-modA
    #   compile-core -> compile-modB
    #   link-shared -> package
    #   compile-modA -> package
    #   compile-modB -> package
    root spawn Auditor();
}

"""NIP-68 picture composition: bytes-only MIME derivation across all sources.

A private byte classifier sits inside the picture crate. It is the ONLY
authority that mints the closed ``m`` field on ``PictureImage``. Upload
descriptors, URL extensions, request headers, and caller strings are
never consulted as authority -- at most they are checked for consistency,
and disagreement is a typed refusal.

The walker ``MintedImage`` walks the graph from each composition source
(direct upload, BUD-05 transformed retrieval, in-memory fixture) through
the shared picture boundary, exercising the same byte-derived classifier
on each path. Mutating the source-side descriptor/header string cannot
change the derived ``m``.
"""

node VerifiedAsset {
    has source_label: str = "";
    has size: int = 0;
    has sha256: str = "";
    has sig0: int = 0;
    has sig1: int = 0;
    has sig2: int = 0;
    has sig3: int = 0;
}

node BlobDescriptor {
    has source_label: str = "";
    has claimed_mime: str = "";
}

node ClassifiedFormat {
    has source_label: str = "";
    has mime: str = "";
    has refusal: str = "";
}

node PictureImage {
    has source_label: str = "";
    has m: str = "";
    has descriptor_claimed: str = "";
}

node Refusal {
    has source_label: str = "";
    has reason: str = "";
}

edge VerifiedBy {
    has via: str = "";
}

edge WantsMime {
    has claimed: str = "";
}

edge Derives {
    has via: str = "";
}

edge RefusedBy {
    has why: str = "";
}

walker MintedImage {
    has path_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_asset with VerifiedAsset entry {
        self.path_log.append(
            f"asset[{here.source_label}] sig=({here.sig0:02x},{here.sig1:02x},{here.sig2:02x},{here.sig3:02x})"
        );
        visit [-->];
    }

    can inspect_descriptor with BlobDescriptor entry {
        self.path_log.append(
            f"descriptor[{here.source_label}] claim={here.claimed_mime}"
        );
        visit [-->];
    }

    can inspect_format with ClassifiedFormat entry {
        label = here.mime if here.mime != "" else "(none)";
        self.path_log.append(
            f"format[{here.source_label}] m={label} refusal={here.refusal}"
        );
        visit [-->];
    }

    can inspect_picture with PictureImage entry {
        label = here.m if here.m != "" else "(none)";
        self.path_log.append(
            f"picture[{here.source_label}] m={label} claimed={here.descriptor_claimed}"
        );
        visit [-->];
    }

