"""Migrate codex config: a guard walker that should NOT unconditionally rewrite
the v2 subagent cap.

Models the issue from code-yeongyu/lazycodex#130: the subagent-limit-guard
unconditionally overwrites ``[features.multi_agent_v2] max_concurrent_threads_per_session = 1000``
on every run, with no equivalent of the "hand-removed key stays removed" behavior
that the same guard already implements for the legacy ``agents.max_threads`` path.
"""

node ConfigFile {
    has path: str = "";
    has disabled: bool = False;
}

node ConfigSection {
    has section_name: str = "";
}

node ConfigKey {
    has key_name: str = "";
    has value: str = "";
    has user_overrode: bool = False;
    has hand_removed: bool = False;
}

edge BelongsTo {
    has order: int = 0;
}

edge HoldsKey {
}

walker MigrateSubagentLimits {
    has legacy_cap: str = "4";
    has v2_cap: str = "1000";
    has writes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can consider with ConfigFile entry {
        print(f"considering config file: {here.path} (disabled={here.disabled})");
        if here.disabled {
            print("  migration disabled by env, skipping");
            disengage;
        }
        visit [-->];
    }

    can inspect with ConfigSection entry {
        print(f"  section: [{here.section_name}]");
        visit [->:HoldsKey:->];
    }

    # The bug in v4.17.0: this ability unconditionally writes the v2 cap.
    # The walker models the offending traversal so we can see the side effect.
    can guard_subagent_cap with ConfigKey entry {
        section_name = "features.multi_agent_v2";
        if here.key_name == "max_concurrent_threads_per_session" {
            print(f"    v2 cap key found, current value = {here.value!r}");
        }
        if here.user_overrode {
            note = f"preserved user override on {here.key_name} = {here.value}";
            print(f"    {note}");
            self.writes.append(note);
        } elif here.hand_removed {
            note = f"hand-removed key {here.key_name} stays removed";
            print(f"    {note}");
            self.writes.append(note);
        } else {
            note = f"UNCONDITIONAL WRITE: {section_name} {here.key_name} = {self.v2_cap}";
            print(f"    {note}");
            self.writes.append(note);
        }
    }
}

with entry {
    # A small config graph: one file, two sections, several keys.
    cfg = ConfigFile(path="/home/user/.codex/config.toml", disabled=False);
    root ++> cfg;

    ma_section = ConfigSection(section_name="agents");
    v2_section = ConfigSection(section_name="features.multi_agent_v2");
    cfg +>:BelongsTo(order=1):+> ma_section;
    cfg +>:BelongsTo(order=2):+> v2_section;

    # Legacy cap: user has set a hand-tuned value, must be preserved.
    ma_section +>:HoldsKey:+> ConfigKey(
        key_name="max_threads",
        value="8",
        user_overrode=True,
        hand_removed=False
    );

    # V2 cap: user has DELETED this key to opt out — current code re-writes it.
    v2_section +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session",
        value="",
        user_overrode=False,
        hand_removed=True
    );

    # V2 cap on a different model: absent entirely, never written by user.
    v2_section +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session",
        value="",
        user_overrode=False,
        hand_removed=False
    );

    # Run the offending guard walker.
    guard = MigrateSubagentLimits();
    cfg spawn guard;

    print("\nmigration writes performed:");
    for w in guard.writes {
        print(f"  - {w}");
    }
}

"""Workflow execution hardening: dependency-ordered traversal, durable node claims with leases, and crash recovery for stuck side-effect nodes."""

node WorkflowNode {
    has title: str = "";
    has action: str = "";
    has year: int = 0;
    has available: bool = True;
    has completed: bool = False;
    has claim_status: str = "pending";
    has idempotency_key: str = "";
    has lease_expires_at: int = 0;
    has worker_id: str = "";
}

node WorkflowRun {
    has run_id: str = "";
    has clock: int = 0;
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }

walker LeaseSweeper {
    has clock: int = 0;
    has recovered: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with WorkflowRun entry {
        self.clock = here.clock;
        print(f"Sweeping stuck claims for {here.run_id} at t={self.clock}");
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can revive with WorkflowNode entry {
        if here.claim_status == "running" and here.lease_expires_at < self.clock {
            print(
                f"  RECOVER {here.title}: expired lease "
                f"(worker={here.worker_id}, key={here.idempotency_key})"
            );
            here.claim_status = "pending";
            here.worker_id = "";
            self.recovered += 1;
        }
        visit [->:DependsOn:->] else {
            visit [-->];
        };
    }
}

walker DependencyExecutor {
    has run_clock: int = 0;
    has executed: int = 0;
    has side_effects: int = 0;
    has skipped_stuck: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with WorkflowRun entry {
        self.run_clock = here.clock;
        print(f"Executing workflow {here.run_id} at t={self.run_clock}");
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can run_node with WorkflowNode entry {
        if here.claim_status == "running" {
            print(f"  BLOCKED {here.title}: claim still held (worker={here.worker_id})");
            self.skipped_stuck += 1;
            visit [->:DependsOn:->] else {
                visit [-->];
            };
        } else {
            if here.completed {
                print(f"  SKIP {here.title}: already done (key={here.idempotency_key})");
                visit [->:DependsOn:->] else {
                    visit [-->];
                };
            } else {
                is_side = (
                    here.action == "send_email"
                    or here.action == "post_reply"
                    or here.action == "send_dm"
                );
                here.claim_status = "running";
                here.worker_id = "worker-live";
                here.lease_expires_at = self.run_clock + 30;
                kind = "SIDE-EFFECT" if is_side else "pure";
                print(
                    f"  RUN [{kind}] {here.title} "
                    f"(action={here.action}, key={here.idempotency_key})"
                );
                here.claim_status = "completed";
                here.completed = True;
                self.executed += 1;
                if is_side {
                    self.side_effects += 1;
                }
                visit [->:DependsOn:->] else {
                    visit [-->];
                };
            }
        }
    }
}

walker CycleGuard {
    has stack: list[str] = [];
    has seen: list[str] = [];
    has found_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan with WorkflowRun entry {
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can probe with WorkflowNode entry {
        label = here.title;
        if label in self.stack {
            self.found_cycle = True;
            print(f"  CYCLE detected at node {label}");
            disengage;
        }
        if label not in self.seen {
            self.stack.append(label);
            visit [->:DependsOn:->] else {
                self.stack.pop();
            };
            self.seen.append(label);
        }
        visit [-->];
    }
}

with entry {
    run = WorkflowRun(run_id="exec-4113", clock=100);

    ingest = WorkflowNode(
        title="Ingest Data",
        action="ingest",
        idempotency_key="exec-4113:ingest"
    );
    validate = WorkflowNode(
        title="Validate Payload",
        action="validate",
        idempotency_key="exec-4113:validate"
    );
    send_email = WorkflowNode(
        title="Send Email",
        action="send_email",
        claim_status="running",
        lease_expires_at=50,
        worker_id="worker-crashed",
        idempotency_key="exec-4113:send_email"
    );
    post_reply = WorkflowNode(
        title="Post Reply",
        action="post_reply",
        idempotency_key="exec-4113:post_reply"
    );

    root ++> run;
    run +>:DependsOn:+> ingest;
    ingest +>:DependsOn:+> validate;
    validate +>:DependsOn:+> send_email;
    send_email +>:DependsOn:+> post_reply;

    print("=== Phase 1: recover crash-stuck running claims ===");
    sweeper = LeaseSweeper();
    root spawn sweeper;

    print("=== Phase 2: dependency-ordered node execution ===");
    executor = DependencyExecutor();
    root spawn executor;

    print("=== Phase 3: cycle guard (clean graph) ===");
    guard = CycleGuard();
    root spawn guard;

    cycle_status = "yes" if guard.found_cycle else "no";
    print(
        f"Summary: recovered={sweeper.recovered}, "
        f"executed={executor.executed}, "
        f"side_effects={executor.side_effects}, "
        f"cycle={cycle_status}"
    );
}

