"""Model a learned lexer DFA with typed graph edges, lazy token text, and cycle-safe walkers."""

node GraphEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has label: str = "";
}

node LexerMode(GraphEntity) {
    has mode_number: int = 0;
    has mode_name: str = "";
}

node DfaState(GraphEntity) {
    has state_number: int = 0;
    has accepting_rule: int = 0;
    has accepting_length: int = 0;
    has cached: bool = True;
}

node LexerToken(GraphEntity) {
    has source: str = "";
    has start_index: int = 0;
    has stop_index: int = 0;
    has text_loaded: bool = False;
    has token_kind: str = "";
}

edge Owns {
    has relation: str = "";
}

edge CachedTransition {
    has symbol: str = "";
    has cache_hit: bool = True;
}

edge Emits {
    has token_kind: str = "";
}

walker DfaCacheAuditor {
    has visited_states: list[int] = [];
    has cache_hits: int = 0;
    has cache_misses: int = 0;

    can begin with Root entry {
        print("DFA cache audit begins");
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect_mode with LexerMode entry {
        print(f"mode {here.mode_number}: {here.mode_name}");
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect_state with DfaState entry {
        if here.state_number in self.visited_states {
            print(f"cycle guard stopped at DFA state {here.state_number}");
            disengage;
        }

        self.visited_states.append(here.state_number);

        if here.cached {
            self.cache_hits += 1;
        } else {
            self.cache_misses += 1;
        }

        if here.accepting_rule > 0 {
            print(f"state {here.state_number} accepts rule "
                  f"{here.accepting_rule} at length {here.accepting_length}");
        } else {
            print(f"state {here.state_number} is non-accepting");
        }

        visit [->:CachedTransition:->] else {
            disengage;
        }
    }
}

walker TokenMaterializationAuditor {
    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_mode with LexerMode entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_state with DfaState entry {
        print(f"checking lazy token candidates from state {here.state_number}");
        visit [->:Emits:->] else {
            disengage;
        }
    }

    can inspect_token with LexerToken entry {
        print(f"lazy token {here.token_kind}: source indexes "
              f"{here.start_index}-{here.stop_index}, text loaded={here.text_loaded}");
    }
}

with entry {
    mode = LexerMode(
        title="default lexer mode",
        mode_number=0,
        mode_name="DEFAULT_MODE"
    );

    start = DfaState(
        title="DFA start",
        state_number=0,
        accepting_rule=0,
        accepting_length=0,
        cached=True
    );

    identifier = DfaState(
        title="identifier loop",
        state_number=1,
        accepting_rule=2,
        accepting_length=5,
        cached=True
    );

    end = DfaState(
        title="accepting endpoint",
        state_number=2,
        accepting_rule=3,
        accepting_length=1,
        cached=False
    );

    token = LexerToken(
        title="identifier token",
        source="alpha42",
        start_index=0,
        stop_index=6,
        text_loaded=False,
        token_kind="IDENTIFIER"
    );

    root +>:Owns(relation="lexer modes"):+> mode;
    mode +>:Owns(relation="mode start"):+> start;
    mode +>:Owns(relation="learned state"):+> identifier;
    mode +>:Owns(relation="accepting state"):+> end;

    start +>:CachedTransition(symbol="a-z", cache_hit=True):+> identifier;
    identifier +>:CachedTransition(symbol="a-z0-9", cache_hit=True):+> end;
    end +>:CachedTransition(symbol="a-z0-9", cache_hit=False):+> identifier;

    identifier +>:Emits(token_kind="IDENTIFIER"):+> token;
    end +>:Emits(token_kind="IDENTIFIER"):+> token;

    root spawn DfaCacheAuditor();
    root spawn TokenMaterializationAuditor();
}
