"""Rig dependency materialization before bench workloads.

Models the homeboy bench --rig contract: a Rig declares its dependency
materialization steps, a Workspace is the effective materialized directory,
and a Bench workload only runs after every declared output exists (or has
just been produced). A walker performs the materialization pass, skipping
satisfied outputs and recording structured outcomes; failure aborts before
the workload entrypoint is invoked.
"""

node Workspace {
    has path: str = "";
    has materialized: bool = False;
}

node Step {
    has name: str = "";
    has command: str = "";
    has output: str = "";
    has exists: bool = False;
    has outcome: str = "pending";
}

node Workload {
    has label: str = "";
    has runner: str = "local";
}

node Rig {
    has rig_id: str = "";
    has lab_paths: bool = False;
}

edge Declares {
    has order: int = 0;
}

edge Targets {
}

edge Runs {
}

walker Materialize {
    has failed: bool = False;
    has report_lines: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can pick_rig with Rig entry {
        print(f"rig {here.rig_id} declares {len([here-->])} step(s); "
              f"lab_runner_paths={here.lab_paths}");
        visit [->:Declares:->];
    }

    can run_step with Step entry {
        if here.exists {
            here.outcome = "skipped";
            self.report_lines.append(
                f"[skip] {here.name}: output already present at {here.output}"
            );
        } else {
            here.outcome = "ran";
            here.exists = True;
            self.report_lines.append(
                f"[run ] {here.name}: {here.command} -> {here.output}"
            );
        }
        visit [-->];
    }

    can check_outputs with Workspace entry {
        here.materialized = True;
        visit [->:Targets:->];
    }

    can gate_workload with Workload entry {
        if self.failed {
            here.runner = "aborted";
            print(f"[fail] workload {here.label} NOT started "
                  f"(workspace/setup remediation needed)");
            disengage;
        }
        print(f"[ok  ] workload {here.label} starting on {here.runner}");
        visit [-->];
    }
}

with entry {
    ws = Workspace(path="/tmp/homeboy/effective");
    rig = Rig(rig_id="homeboy-bench-rig", lab_paths=True);
    step_a = Step(name="npm-install", command="npm ci",
                  output="/tmp/homeboy/effective/node_modules/.package-lock.json",
                  exists=True);
    step_b = Step(name="composer-install", command="composer install",
                  output="/tmp/homeboy/effective/vendor/autoload.php",
                  exists=False);
    step_c = Step(name="blocks-engine-php", command="php blocks-engine.php",
                  output="/tmp/homeboy/effective/blocks-engine.pkg",
                  exists=False);
    bench = Workload(label="rig-bench", runner="local");

    root +>:Declares(order=0):+> rig;
    rig +>:Declares(order=1):+> step_a;
    rig +>:Declares(order=2):+> step_b;
    rig +>:Declares(order=3):+> step_c;
    rig +>:Targets:+> ws;
    ws +>:Runs:+> bench;

    m = Materialize();
    root spawn m;

    print("--- materialization report ---");
    for line in m.report_lines {
        print(line);
    }
    print("--- final state ---");
    print(f"workspace.materialized={ws.materialized}, "
          f"workload.runner={bench.runner}");
}
