"""Verified cache bytes remain authoritative for impact and oracle consumers."""

node VerifiedArchive {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has digest: str = "";
    has generation: int = 0;
    has verified_payload: str = "";
    has current_payload: str = "";
    has seen: bool = False;
}

node ArchiveConsumer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "";
    has expected_digest: str = "";
    has expected_generation: int = 0;
    has consumed_payload: str = "";
    has accepted: bool = False;
    has seen: bool = False;
}

edge Supplies {
    has purpose: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker IntegrityAudit {
    has verified_digest: str = "";
    has verified_generation: int = 0;
    has verified_payload: str = "";
    has accepted_count: int = 0;
    has rejected_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_archive with VerifiedArchive entry {
        if here.seen {
            print(f"cycle guard: {here.title}");
        } else {
            here.seen = True;
            self.verified_digest = here.digest;
            self.verified_generation = here.generation;
            self.verified_payload = here.verified_payload;

            print(f"verified {here.title} generation {here.generation}");
            if here.current_payload != here.verified_payload {
                print("cache path changed; staged verified payload remains authoritative");
            }

            visit [->:Supplies:->] else {
                disengage;
            }
        }
    }

    can inspect_consumer with ArchiveConsumer entry {
        if here.seen {
            print(f"cycle guard: {here.role}");
        } else {
            here.seen = True;
            here.accepted = False;

            if here.expected_digest == self.verified_digest {
                if here.expected_generation == self.verified_generation {
                    if here.consumed_payload == self.verified_payload {
                        here.accepted = True;
                    }
                }
            }

            status = "BOUND" if here.accepted else "REJECTED";
            print(f"{here.role}: {status} against verified generation "
                  f"{self.verified_generation}");

            if here.accepted {
                self.accepted_count += 1;
            } else {
                self.rejected_count += 1;
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

with entry {
    archive = VerifiedArchive(
        title="package-cache/archive",
        year=2024,
        digest="sha256:verified-v1",
        generation=1,
        verified_payload="archive-bytes-v1",
        current_payload="archive-bytes-v2"
    );

    impact = ArchiveConsumer(
        title="impact analysis",
        year=2024,
        role="commandf impact",
        expected_digest="sha256:verified-v1",
        expected_generation=1,
        consumed_payload="archive-bytes-v1"
    );

    oracle = ArchiveConsumer(
        title="oracle comparison",
        year=2024,
        role="commandf oracle",
        expected_digest="sha256:verified-v1",
        expected_generation=1,
        consumed_payload="archive-bytes-v1"
    );

    root ++> archive;
    archive +>:Supplies(purpose="impact"):+> impact;
    archive +>:Supplies(purpose="oracle"):+> oracle;
    impact +>:DependsOn(reason="verified archive"):+> archive;
    oracle +>:DependsOn(reason="private staged archive"):+> archive;

    root spawn IntegrityAudit();
}

