"""Software supply-chain audit: model a Maven project graph and walk the
dependency tree to find vulnerable artifacts (CVE-2026-22745 demo).

Entities: Project → Dependency → Artifact. Edges declare
'dependsOn' and 'fixes'. A walker audits transitive dependencies,
tracks visited coordinates (cycle policy, since jac walkers don't
dedupe automatically), and reports vulnerable artifacts with the
suggested fix version.
"""

node Project {
    has name: str = "";
    has group: str = "";
    has version: str = "";
}

node Dependency {
    has group: str = "";
    has artifact: str = "";
    has version: str = "";
    has vulnerable: bool = False;
    has cve: str = "";
    has suggested_fix: str = "";
}

edge DependsOn {
    has scope: str = "compile";
}

edge Fixes {
    has to_version: str = "";
}

walker Auditor {
    has visited: list[str] = [];
    has findings: list[tuple[str, str, str, str]] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_project with Project entry {
        print(f"Auditing project: {here.group}:{here.name}:{here.version}");
        visit [->:DependsOn:->];
    }

    can audit_dependency with Dependency entry {
        coord = f"{here.group}:{here.artifact}:{here.version}";
        if coord in self.visited {
            print(f"[cycle/skip] {coord}");
            visit [-->] else { disengage; }
        }
        self.visited.append(coord);

        if here.vulnerable {
            finding = (here.group, here.artifact, here.version, here.cve);
            self.findings.append(finding);
            print(
                f"[VULN] {here.group}:{here.artifact}:{here.version} "
                f"-- {here.cve} (fix -> {here.suggested_fix})"
            );
        } else {
            print(f"  ok  {coord}");
        }

        visit [->:DependsOn:->];
    }
}

walker ApplyFix {
    can start with Root entry {
        visit [-->];
    }

    can visit_project with Project entry {
        visit [->:DependsOn:->];
    }

    can visit_dep with Dependency entry {
        if here.vulnerable {
            print(
                f"Applying fix: {here.group}:{here.artifact} "
                f"{here.version} -> {here.suggested_fix}"
            );
            here.version = here.suggested_fix;
            here.vulnerable = False;
            here.cve = "";
        }
        visit [-->];
    }
}

