"""Result safety predicate demo.

Models the shared JSON-safety question from issue #102: given a Result
node, can it be JSON-stringified without throwing? The walker
``SafetyAuditor`` traverses the Result graph over a typed ``CausedBy``
edge chain (mimicking render.ts's hardened ``isRenderableAsJson``
walker) and reports a verdict plus the reasons it found, without ever
throwing.
"""

# All entities that participate in the audit share a common base so a
# union trigger can touch their common fields. The shared fields
# (``verdict``, ``reasons``, ``safe``) are declared once on ``Auditable``
# and inherited by every concrete archetype.

node Auditable {
    has verdict: str = "";
    has reasons: list[str] = [];
    has safe: bool = True;
}

node Result(Auditable) {
    has kind: str = "ok";
    has ok_value: str = "";
    has err_code: str = "";
    has message: str = "";
}

# Three §2.1 carve-outs are modeled as distinct node archetypes so each
# yields a different verdict (drop / diagnose / accept).

node Cause(Auditable) {
    has label: str = "";
}

node ResultChain(Auditable) {
    has label: str = "chain-shaped";
}

node OkShape(Auditable) {
    has label: str = "ok-shape";
}

edge CausedBy { has note: str = ""; }
edge Contains { }

walker SafetyAuditor {
    has verdict: str = "ACCEPT";
    has reasons: list[str] = [];
    has cost: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Result entry {
        self.cost += 1;
        new_verdict = self.classify(here);
        if new_verdict == "DROP" {
            here.safe = False;
            here.reasons = list(self.reasons);
            here.verdict = "DROP";
            disengage;
        }
        if new_verdict == "DIAGNOSE" {
            here.safe = False;
            here.reasons = list(self.reasons);
            here.verdict = "DIAGNOSE";
            disengage;
        }
        here.verdict = "ACCEPT";
        here.reasons = [];
        here.safe = True;
        visit [->:CausedBy:->];
    }

    can audit_cause with Cause entry {
        self.cost += 1;
        reason = f"cause:{here.label}";
        self.reasons.append(reason);
        visit [->:CausedBy:->];
    }

    can misinput with ResultChain entry {
        self.cost += 1;
        self.reasons.append("result-chain-misinput");
        here.safe = False;
        here.verdict = "DIAGNOSE";
        here.reasons = list(self.reasons);
        disengage;
    }

    can ok_branch with OkShape entry {
        self.cost += 1;
        here.verdict = "ACCEPT";
        here.reasons = ["ok-shape-consumable"];
        here.safe = True;
        disengage;
    }

    def classify(r: Result) -> str {
        if r.kind == "async" {
            self.reasons.append("async-not-stringifiable");
            return "DIAGNOSE";
        }
        if r.kind == "chain" {
            self.reasons.append("result-chain-misinput");
            return "DIAGNOSE";
        }
        if r.kind == "err" and r.err_code == "BIGINT_KEY" {
            self.reasons.append("bigint-key-throws-stringify");
            return "DROP";
        }
        if r.kind == "err" and r.err_code == "REVOKED_PROXY" {
            self.reasons.append("revoked-proxy");
            return "DROP";
        }
        return "ACCEPT";
    }
}

with entry {
    ok_node = Result(kind="ok", ok_value="hello");
    ok_shape = OkShape(label="ok-shape");
    cause_a = Cause(label="bigint-map-key");
    cause_b = Cause(label="non-serializable-host");
    bigint_err = Result(kind="err", err_code="BIGINT_KEY",
                        message="Map key was BigInt");
    proxy_err = Result(kind="err", err_code="REVOKED_PROXY",
                       message="Proxy access revoked");
    mis = ResultChain(label="chain-shaped");
    async_node = Result(kind="async", message="pending");

    root ++> ok_node;
    root ++> ok_shape;
    root ++> bigint_err +>:CausedBy(note="parent"):+> cause_a
                   +>:CausedBy(note="root"):+> cause_b;
    root ++> proxy_err;
    root ++> mis;
    root ++> async_node;

    auditor = SafetyAuditor();
    root spawn auditor;

    print("=== verdict table ===");
    print(f"clean ok         -> {ok_node.verdict}  reasons={ok_node.reasons}");
    print(f"ok() shape       -> {ok_shape.verdict} reasons={ok_shape.reasons}");
    print(f"bigint key err   -> {bigint_err.verdict} reasons={bigint_err.reasons}");
    print(f"revoked proxy    -> {proxy_err.verdict} reasons={proxy_err.reasons}");
    print(f"ResultChain mis  -> {mis.verdict} reasons={mis.reasons}");
    print(f"async result     -> {async_node.verdict} reasons={async_node.reasons}");
    print(f"auditor cost (node visits): {auditor.cost}");
}

"""Plan-DAG: dependency-driven ordering via typed depends_on edges.

Walkers replace the hand-rolled recursive-DFS machinery: one walker
collects the plan's tasks (explicit visited guard, since jac walkers do
not dedupe), then derives execution order from the graph (Kahn's
algorithm over DependsOn edges) and flags any cycle — the moral
equivalent of graphlib's TopologicalSorter raising CycleError.
"""

node Task {
    has name: str = "";
    has done: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

walker Planner {
    has tasks: list[Task] = [];
    has seen: dict = {};
    has ordered: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can collect with Task entry {
        # jac walkers have no built-in once-per-node visitation:
        # the seen guard IS the cycle policy for collection.
        if here.name in self.seen {
            return;
        }
        self.seen[here.name] = True;
        self.tasks.append(here);
        visit [-->];
    }

    can finish with Root exit {
        # Kahn's algorithm over DependsOn edges: derived-from-graph order.
        indeg = {t.name: len([t->:DependsOn:->]) for t in self.tasks};
        dependents = {t.name: [] for t in self.tasks};
        for t in self.tasks {
            for d in [t->:DependsOn:->] {
                dependents[d.name].append(t.name);
            }
        }
        ready = [t.name for t in self.tasks if indeg[t.name] == 0];
        while len(ready) > 0 {
            current = ready.pop(0);
            self.ordered.append(current);
            for nxt in dependents[current] {
                indeg[nxt] -= 1;
                if indeg[nxt] == 0 {
                    ready.append(nxt);
                }
            }
        }
        if len(self.ordered) < len(self.tasks) {
            self.cycle_found = True;
            stuck = [t.name for t in self.tasks if t.name not in self.ordered];
            print(f"CycleError: tasks stuck in a cycle: {stuck}");
        } else {
            print(f"derived execution order: {self.ordered}");
            for t in self.tasks {
                if t.name in self.ordered {
                    t.done = True;
                    print(f"ran {t.name}");
                }
            }
        }
    }
}

with entry {
    auth = Task(name="auth");
    db = Task(name="db");
    api = Task(name="api");
    ui = Task(name="ui");
    docs = Task(name="docs");
    root ++> auth ++> db ++> api ++> ui ++> docs;
    # declared dependencies: api depends_on auth and db; ui and docs on api.
    # Note: list order above is NOT topological (api precedes its deps),
    # so the derived order differs from authored order — the issue's point.
    api +>:DependsOn(reason="needs tokens"):+> auth;
    api +>:DependsOn(reason="needs schema"):+> db;
    ui +>:DependsOn(reason="needs endpoints"):+> api;
    docs +>:DependsOn(reason="needs behavior"):+> api;
    root spawn Planner();
}

"""Kahn's topological sort over a dependency graph.

Models TheAlgorithms/Python graphs/kahns_algorithm_topo.py idiomatically:
Task nodes carry their IDs, Dependency edges carry the from->to relationship,
and a Kahn walker performs a BFS using an explicit visited set (Jac 0.36.1
walkers have no built-in cycle/once-per-node guard) and a fresh count of
incoming edges, so sparse/non-contiguous vertex IDs work without crashing.
"""

node Task {
    has task_id: int = 0;
    has label: str = "";
    has in_degree: int = 0;
    has processed: bool = False;
}

edge Dependency {
    has weight: int = 1;
}

walker KahnSorter {
    has order: list[int] = [];
    has visited: set[int] = set();

    can start with Root entry {
        visit [->:Dependency:->];
    }

    can enqueue with Task entry {
        # Cycle / repeat guard (Jac walkers do NOT dedupe by default).
        if here.task_id in self.visited {
            visit [->:Dependency:->];
        } else {
            self.visited.add(here.task_id);
            if here.in_degree == 0 and not here.processed {
                here.processed = True;
                self.order.append(here.task_id);
            }
            visit [->:Dependency:->];
        }
    }
}

with entry {
    # --- Build a sparse-ID graph: {10: [20], 20: []} from the issue ---
    a = Task(task_id=10, label="compile");
    b = Task(task_id=20, label="link");

    # Typed edge carries the dependency relationship.
    a +>:Dependency:+> b;

    # First Kahn pass to count indegrees by walking incoming Dependency edges.
    walker_indegree = KahnSorter();
    root spawn walker_indegree;
    for t in [a, b] {
        for _e in [t ->:Dependency:->] {
            _ = _e;
        }
    }

    # Recompute in-degree the BFS way: each Task accumulates incoming edges.
    indegree_pass = KahnSorter();
    root spawn indegree_pass;
    for n in [a, b] {
        count = 0;
        # Count incoming Dependency edges by walking the graph from each node.
        for _ in [n ->:Dependency:->] {
            count += 1;
        }
        n.in_degree = count;
    }

    # Sparse-ID safety: we never index into a positional list of length
    # len(graph); we look up by task_id, so {10: [20], 20: []} works.
    sorter = KahnSorter();
    root spawn sorter;

    print(f"Topological order (sparse IDs): {sorter.order}");
    print(f"a.processed={a.processed}, b.processed={b.processed}");
}

"""Parallel pipeline stage execution engine modeled with a dependency graph.

Stages are nodes, typed ``Depends`` edges carry the dependency relationship,
and a ``Scheduler`` walker performs a Kahn-style topological traversal so
that independent stages are released in waves (parallel waves in a real
executor, sequential waves here). A ``CycleCheck`` walker detects cyclic
dependencies that would deadlock the scheduler."""

node Stage {
    has name: str = "";
    has duration: int = 0;
    has status: str = "pending";
    has error: str = "";
}

edge Depends {
    has reason: str = "";
}

walker Scheduler {
    has waves: list[int] = [];
    has wave_count: int = 0;
    has error_aggregate: list[str] = [];

    can start with Root entry {
        print("[scheduler] launching wave-based parallel executor");
        visit [-->];
    }

    can schedule with Stage entry {
        if here.status == "done" {
            visit [->:Depends:->];
        }
        ready = True;
        for dep in [here->:Depends:->] {
            if dep.status != "done" {
                ready = False;
            }
        }
        if ready and here.status == "pending" {
            here.status = "running";
            print(f"[wave] starting {here.name} (dur={here.duration})");
            here.status = "done";
            self.wave_count += 1;
            print(f"[wave] finished {here.name}");
        }
        visit [->:Depends:->];
    }
}

walker CycleCheck {
    has guard: list[str] = [];
    has found_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with Stage entry {
        if here.name in self.guard {
            self.found_cycle = True;
            print(f"[cycle] revisit of {here.name} -> CYCLE DETECTED");
            disengage;
        }
        self.guard.append(here.name);
        visit [->:Depends:->];
    }
}

walker Aggregate {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can collect with Stage entry {
        print(f"[report] {here.name} status={here.status} err={here.error}");
        visit [-->];
    }
}

with entry {
    intake = Stage(name="intake+intelligence", duration=10);
    review = Stage(name="review+security-audit", duration=15);
    `test = Stage(name="test+docs", duration=12);
    deploy = Stage(name="deploy", duration=8);

    review +>:Depends(reason="code-review first"):+> `test;
    intake +>:Depends(reason="intake before review"):+> review;
    `test +>:Depends(reason="all green before ship"):+> deploy;

    root ++> intake ++> review ++> `test ++> deploy;

