        self.seen.append(here.title);
        print(f"  inheriting grants from: {here.title} (level {here.level})");
        self.collected.extend(here.grants);
        visit [-->] else { disengage; }
    }

    def summary() -> str {
        unique: list[str] = [];
        for g in self.collected {
            if g not in unique {
                unique.append(g);
            }
        }
        return f"Role '{self.target_role}' resolves to {len(unique)} permissions: {unique}";
    }
}

