"""Collection subtree reparent and soft-delete cascade.

Models the core scenario from REQ-COLLECTIONS-020: collections form a tree
via materialized-path parent_id relationships, reparenting rewrites every
descendant's path in one sweep (rejecting cycles and depth > 10), and
soft-deleting a collection cascades ``deleted_at`` to the entire subtree
(via a ``path <@`` analog) before the trash window begins.
"""

node Collection {
    has title: str = "";
    has path: str = "";
    has depth: int = 0;
    has deleted_at: str = "";
}

edge Child {
    has order: int = 0;
}

walker Reparentor {
    has new_parent_path: str = "";
    has new_parent_depth: int = 0;
    has max_depth: int = 10;
    has failed_reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can descend with Collection entry {
        # Cycle guard: refusing to place a collection under its own subtree
        # is a tree-integrity invariant, not new product behavior.
        if here.path == self.new_parent_path
            or self.new_parent_path.startswith(here.path + "/") {
            self.failed_reason = "cycle: target is within subtree";
            disengage;
        }

        old_prefix = here.path;
        suffix = here.path[len(old_prefix):] if here.path.startswith(old_prefix) else "";
        new_prefix = self.new_parent_path;
        rewritten = new_prefix + suffix;

        # Depth cap: refuse any reparent that would exceed max_depth.
        candidate_depth = self.new_parent_depth + (here.depth - old_prefix.count("/") if old_prefix else 0);
        if candidate_depth > self.max_depth {
            self.failed_reason = "depth cap exceeded";
            disengage;
        }

        here.path = rewritten;
        here.depth = candidate_depth;
        print(f"repathed '{here.title}' -> {here.path} (depth {here.depth})");

        visit [->:Child:->];
    }
}

walker CascadeDelete {
    has tombstoned: list[str] = [];
    has marker: str = "";
    has days_in_trash: int = 30;

    can start with Root entry {
        visit [-->];
    }

    can sweep with Collection entry {
        # Materialized-path subtree select: every descendant's path
        # starts with here.path, so one sweep covers the whole subtree.
        if here.path.startswith(self.subtree_root_path) {
            here.deleted_at = self.marker;
            self.tombstoned.append(here.title);
            print(f"soft-deleted '{here.title}' at {here.path} -> tombstone {self.marker}");
        }
        visit [->:Child:->];
    }

    has subtree_root_path: str = "";
}

with entry {
    # Build a small collection tree: root -> A -> A1, A2; root -> B
    a = Collection(title="A", path="/A", depth=1);
    a1 = Collection(title="A1", path="/A/A1", depth=2);
    a2 = Collection(title="A2", path="/A/A2", depth=2);
    b = Collection(title="B", path="/B", depth=1);

    root ++> a;
    a +>:Child(order=1):+> a1;
    a +>:Child(order=2):+> a2;
    root ++> b;

    # 1) Reparent A1 from /A to /B -> path becomes /B/A1
    print("--- reparent /A/A1 under /B ---");
    root spawn Reparentor(new_parent_path="/B", new_parent_depth=1);

    # 2) Attempt a cycle: try to put /A under /A/A1 (its own descendant)
    print("\n--- attempt cycle: put /A under /A/A1 ---");
    re = Reparentor(new_parent_path="/A/A1", new_parent_depth=2);
    root spawn re;
    print(f"cycle attempt result: {re.failed_reason if re.failed_reason else 'allowed'}");

    # 3) Soft-delete cascade: delete /A, which tombstones /A, /A/A1, /A/A2
    print("\n--- soft-delete subtree rooted at /A ---");
    cascade = CascadeDelete(marker="2026-08-27T00:00:00Z", subtree_root_path="/A");
    root spawn cascade;
    print(f"tombstoned: {cascade.tombstoned}");
    print(f"held in trash for {cascade.days_in_trash} days before purge");
}

