    n0 = IncludeNode(segment="categories", depth=0);
    n1 = IncludeNode(segment="town", depth=1);
    n2 = IncludeNode(segment="country", depth=2);
    n3 = IncludeNode(segment="__proto__", depth=3);
    n4 = IncludeNode(segment="pp", depth=4);
    n5 = IncludeNode(segment="constructor", depth=5);
    n6 = IncludeNode(segment="prototype", depth=6);

    root +>:SegmentStep:+> n0;
    n0 +>:SegmentStep:+> n1;
    n1 +>:SegmentStep:+> n2;
    n2 +>:SegmentStep:+> n3;
    n3 +>:SegmentStep:+> n4;
    n4 +>:SegmentStep:+> n5;
    n5 +>:SegmentStep:+> n6;

    # A couple of resources reachable through the safe prefix.
    article = Resource(name="stuff", kind="article", attrs={"id": "1", "title": "Hello"});
    categories = Resource(name="categories", kind="relation", attrs={});
    town = Resource(name="town", kind="relation", attrs={});

    root +>:Includes:+> article;
    article +>:Includes:+> categories;
    categories +>:Includes:+> town;

    print("== Building include-name tree (safe mode) ==");
    builder = PathBuilder(max_depth=6);
    root spawn builder;

    print(f"\nblocked segments: {builder.blocked}");
    print(f"all segments accepted? {len(builder.blocked) == 0}");

    print("\n== PollutionProbe: re-walk to confirm rejection ==");
    probe = PollutionProbe();
    root spawn probe;
