"""Production readiness ledger: audit vertical dependencies and release gates before public release."""

node Project {
    has name: str = "";
    has ready_for_public: bool = False;
}

node Vertical {
    has title: str = "";
    has state: str = "UNVERIFIED";
    has blocks_release: bool = False;
}

node ReleaseGate {
    has title: str = "";
    has satisfied: bool = False;
    has required: bool = True;
}

edge Owns { }
edge DependsOn { }
edge Governs { }

walker ReadinessAuditor {
    has on_path: list[str] = [];
    has at_risk: bool = False;
    has verticals_checked: int = 0;
    has gates_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_project with Project entry {
        print(f"=== Baseline audit: {here.name} ===");
        print("Status: AT RISK — automated release gates are incomplete");
        visit [->:Owns:->];
        visit [->:Governs:->];
        verdict = "READY FOR PUBLIC" if not self.at_risk else "AT RISK";
        print(f"=== Verdict: {verdict} ({self.verticals_checked} verticals, {self.gates_checked} gates) ===");
    }

    can inspect_vertical with Vertical entry {
        if here.title in self.on_path {
            print(f"[CYCLE] dependency loop at vertical '{here.title}'");
            self.at_risk = True;
            disengage;
        }
        self.on_path.append(here.title);
        visit [->:DependsOn:->] else { }
        passed = here.state != "MISSING" and not here.blocks_release;
        label = "OK" if passed else "BLOCKED";
        if not passed {
            self.at_risk = True;
        }
        print(f"[{label}] {here.title}: {here.state}");
        self.verticals_checked += 1;
        self.on_path.pop();
        visit [-->];
    }

    can inspect_gate with ReleaseGate entry {
        gate_ok = here.satisfied or not here.required;
        label = "PASS" if gate_ok else "FAIL";
        if not gate_ok {
            self.at_risk = True;
        }
        print(f"[{label}] gate: {here.title}");
        self.gates_checked += 1;
        visit [-->];
    }
}

with entry {
    app = Project(name="Vahdam Marketing Automation");
    root ++> app;

    ci_cd = Vertical(title="CI/CD", state="MISSING", blocks_release=True);
    tests = Vertical(title="Tests & quality gates", state="MISSING", blocks_release=True);
    backend = Vertical(title="Backend & APIs", state="NOT EVIDENCED", blocks_release=True);
    frontend = Vertical(title="Frontend & responsive UX", state="UNVERIFIED", blocks_release=False);
    deploy = Vertical(title="Deployment", state="NOT EVIDENCED", blocks_release=True);

    app +>:Owns:+> ci_cd;
    app +>:Owns:+> tests;
    app +>:Owns:+> backend;
    app +>:Owns:+> frontend;
    app +>:Owns:+> deploy;

    deploy +>:DependsOn:+> ci_cd;
    deploy +>:DependsOn:+> tests;
    tests +>:DependsOn:+> backend;

    gate_ci = ReleaseGate(title="CI installs locked deps and runs lint/tests/build on every PR", satisfied=False, required=True);
    gate_journeys = ReleaseGate(title="Primary user journeys pass end to end", satisfied=False, required=True);
    gate_secrets = ReleaseGate(title="Environment variables documented without committed secrets", satisfied=True, required=True);

    app +>:Governs:+> gate_ci;
    app +>:Governs:+> gate_journeys;
    app +>:Governs:+> gate_secrets;

    root spawn ReadinessAuditor();
}

