"""Witness-based extension interface resolution over a small typed graph."""

node ReceiverType {
    has type_name: str = "";
    has contract_name: str = "";
    has nominal_match: bool = False;
}

node Witness {
    has witness_name: str = "";
    has valid: bool = True;
}

node Contract {
    has interface_name: str = "";
    has requires_witness: bool = True;
}

edge Candidate {
    has owner: str = "";
}

edge Implements {
    has method_count: int = 0;
}

walker WitnessResolver {
    has candidates_seen: int = 0;
    has resolved: bool = False;

    can begin with Root entry {
        print("Resolving extension interfaces");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with ReceiverType entry {
        if here.nominal_match {
            print(f"{here.type_name} satisfies {here.contract_name} nominally");
            disengage;
        } else {
            print(f"{here.type_name} needs a witness for {here.contract_name}");
            visit [->:Candidate:->] else {
                disengage;
            }
        }
    }

    can inspect_witness with Witness entry {
        self.candidates_seen += 1;
        if here.valid {
            print(f"Candidate witness: {here.witness_name}");
            visit [->:Implements:->] else {
                disengage;
            }
        } else {
            print(f"Rejected invalid witness: {here.witness_name}");
            disengage;
        }
    }

    can confirm with Contract entry {
        self.resolved = True;
        print(f"Resolved contract: {here.interface_name}");
    }
}

with entry {
    extension_receiver = ReceiverType(
        type_name="List<int>",
        contract_name="IDeepEqual<List<int>>"
    );
    nominal_receiver = ReceiverType(
        type_name="string",
        contract_name="IComparable<string>",
        nominal_match=True
    );
    witness = Witness(
        witness_name="ListDeepEqualityWitness",
        valid=True
    );
    contract = Contract(
        interface_name="IDeepEqual<List<int>>",
        requires_witness=True
    );

    root ++> extension_receiver;
    root ++> nominal_receiver;
    extension_receiver +>:Candidate(owner="DeepEqualityExtensions"):+> witness;
    witness +>:Implements(method_count=1):+> contract;

    root spawn WitnessResolver();
}

