        status="fork-fixed"
    );
    issue8 = Issue(
        issue_id=8,
        title="vacuous gate suppresses failing subcommand",
        status="fork-fixed"
    );

    poller_reg = PortableRegression(
        script="test/regressions/poller_atomic.jac",
        bad_sha="99e19320",
        fixed_sha="6f562e55"
    );
    errno_debt = ExtractionDebt(
        reason="portable matrix row not yet extracted",
        issue_tag="#99"
    );
    meta_debt = ExtractionDebt(
        reason="meta-issue portable extraction in flight",
        issue_tag="#53"
    );

    poll_reserve = PhaseStep(phase="reserve", label="fd-7");
    poll_register = PhaseStep(phase="register", label="fd-7");
    poll_commit = PhaseStep(
        phase="commit",
        label="fd-7",
        observation_valid=False
    );

    root ++> pack;
    pack +>:PackTracks:+> gate_class;
    pack +>:PackTracks:+> split_class;

    gate_class +>:Classifies:+> issue53;
