"""NeuroHarness Issue #11: ticket dependency ordering and harness control workflows."""

node HarnessTicket {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ticket_id: int = 0;
    has complete: bool = False;
}

node HarnessAction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has duration_ms: int = 0;
}

node ControlStrategy {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has strategy_name: str = "";
    has success: bool = False;
    has ttv_ms: int = 0;
    has action_count: int = 0;
}

edge DependsOn { }
edge Precedes { }
edge RunsWith { }

walker DependencyAuditor {
    has order: list[str] = [];
    has seen: list[int] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with HarnessTicket entry {
        if here.ticket_id in self.seen {
            self.cycle_found = True;
            print(f"[CYCLE] ticket #{here.ticket_id} revisited");
            disengage;
        }
        self.seen.append(here.ticket_id);
        if not here.complete {
            self.order.append(f"#{here.ticket_id}:{here.title}");
        }
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker WorkflowRunner {
    has strategy_label: str = "";
    has elapsed_ms: int = 0;
    has steps_taken: int = 0;
    has verified: bool = False;
    has strategy_node: ControlStrategy | None = None;

    can launch with ControlStrategy entry {
        if not here.available {
            disengage;
        }
        self.strategy_label = here.strategy_name;
        self.strategy_node = here;
        print(f"[{self.strategy_label}] starting harness workflow");
        visit [->:RunsWith:->];
    }

    can execute with HarnessAction entry {
        if not here.available {
            print(f"  skip {here.kind} (unavailable)");
            visit [->:Precedes:->] else {
                disengage;
            }
        } else {
            self.elapsed_ms += here.duration_ms;
            self.steps_taken += 1;
            print(f"  {here.kind} (+{here.duration_ms}ms)");
            if here.kind == "VERIFY" {
                self.verified = True;
            }
            visit [->:Precedes:->] else {
                if self.strategy_node is not None {
                    self.strategy_node.ttv_ms = self.elapsed_ms;
                    self.strategy_node.action_count = self.steps_taken;
                    self.strategy_node.success = self.verified;
                }
                outcome = "PASS" if self.verified else "FAIL";
                print(
                    f"[{self.strategy_label}] {outcome} "
                    f"ttv={self.elapsed_ms}ms actions={self.steps_taken}"
                );
                disengage;
            }
        }
    }
}

walker ExperimentComparator {
    has results: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can score with ControlStrategy entry {
        label = (
            f"{here.strategy_name}:ttv={here.ttv_ms}:actions={here.action_count}"
        );
        verdict = "verified" if here.success else "failed";
        row = f"{label}:{verdict}";
        self.results.append(row);
        print(f"[METRIC] {row}");
        visit [-->];
    }
}

with entry {
    t12 = HarnessTicket(ticket_id=12, title="Benchmark split", year=2026);
    t13 = HarnessTicket(ticket_id=13, title="Reasoner seam", year=2026);
    t14 = HarnessTicket(ticket_id=14, title="Static workflow", year=2026);
    t15 = HarnessTicket(ticket_id=15, title="Learned phi", year=2026);
    t16 = HarnessTicket(ticket_id=16, title="LLM control", year=2026);
    t17 = HarnessTicket(ticket_id=17, title="Three-way experiment", year=2026);

    t12 +>:DependsOn:+> t13;
    t13 +>:DependsOn:+> t14;
    t13 +>:DependsOn:+> t15;
    t13 +>:DependsOn:+> t16;
    t14 +>:DependsOn:+> t17;
    t15 +>:DependsOn:+> t17;
    t16 +>:DependsOn:+> t17;

    discover = HarnessAction(kind="DISCOVER", duration_ms=40);
    `test = HarnessAction(kind="TEST", duration_ms=60);
    read = HarnessAction(kind="READ", duration_ms=30);
    think = HarnessAction(kind="THINK", duration_ms=120);
    verify = HarnessAction(kind="VERIFY", duration_ms=80);
    stop = HarnessAction(kind="STOP", duration_ms=5);

    discover +>:Precedes:+> `test;
    `test +>:Precedes:+> read;
    read +>:Precedes:+> think;
    think +>:Precedes:+> verify;
    verify +>:Precedes:+> stop;

    static_wf = ControlStrategy(strategy_name="static", title="Static Skill workflow");
    learned_wf = ControlStrategy(strategy_name="learned", title="Learned phi policy");
    llm_wf = ControlStrategy(strategy_name="llm", title="LLM-centric control");

    root ++> t12;
    root ++> discover;
    root ++> static_wf ++> learned_wf ++> llm_wf;

    static_wf +>:RunsWith:+> discover;
    learned_wf +>:RunsWith:+> discover;
    llm_wf +>:RunsWith:+> discover;

    print("=== Ticket dependency audit ===");
    root spawn DependencyAuditor();

    print("=== Static workflow run ===");
