"""Test-coverage audit walker: find declared-but-untested props on a login form.

Models the essential scenario from issue #95: declared props on form parts that
no test passes a non-default value for. The audit walks the form parts via
typed edges, classifies each declared prop as dead or exercised, and emits a
single summary report. Mirrors the issue's own fix-it criterion: each fix is
demonstrated by breaking the guard and showing the failure first.
"""

node FormPart {
    has part_name: str = "";
    has kind: str = "";

    # Declared props as (name, default) pairs.
    has declared: list[tuple[str, str]] = [];

    # Props actually exercised by tests, as (name, value) pairs.
    has exercised: list[tuple[str, str]] = [];

    # Filled in by the auditor; the walker writes dead props here.
    has dead_props: list[str] = [];

    def declared_names() -> list[str] {
        names: list[str] = [];
        for (n, _d) in self.declared {
            names.append(n);
        }
        return names;
    }

    def is_exercised(prop_name: str) -> bool {
        for (n, _v) in self.exercised {
            if n == prop_name {
                return True;
            }
        }
        return False;
    }
}

edge PartOf { }

walker CoverageAuditor {
    has audit_log: list[tuple[str, list[str]]] = [];
    has total_dead: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with FormPart entry {
        dead: list[str] = [];
        for pname in here.declared_names() {
            if not here.is_exercised(pname) {
                dead.append(pname);
            }
        }
        here.dead_props = dead;
        self.total_dead = self.total_dead + len(dead);
        self.audit_log.append((here.part_name, dead));
        visit [-->];
