"""Session-wide shared cwd slot bug (modeled).

The issue is that EnterWorktree(path:) is documented as rebinding only the
calling agent's own cwd, but in practice all shells in the session tree read
from one shared mutable slot. We model that slot as an explicit graph object
shared across the orchestrator and every subagent, and walk it to show that
a single mutation is observed by every concurrent shell.
"""

# Shared slot that the bug is about: a single cwd binding every shell reads.
node CwdSlot {
    has path: str = "";
    has last_writer: str = "";
}

# A shell — the orchestrator's persistent shell or any subagent's shell —
# reads its cwd through the shared slot instead of holding its own copy.
node Shell {
    has owner: str = "";
    has last_observed_path: str = "";
    has last_observed_writer: str = "";
    has pinned: bool = False;
}

# EnterWorktree is supposed to be a per-agent rebind. Modeled as an edge
# that, on entry, mutates the shared slot. The edge type carries the
# intended target path so we can show intended vs observed cwd.
edge EnterWorktree {
    has target_path: str = "";
    has caller: str = "";
}

# Cascade invalidation: when the shared slot is mutated, every pinned shell
# notices its last_observed_* is stale.
edge ObservedCwd {
    has at_tick: int = 0;
}

walker Tick {
    has count: int = 0;

    can advance with Root entry {
        print(f"--- tick {self.count} ---");
        visit [-->];
    }

    can sweep with Shell entry {
        here.pinned = False;
        visit [-->];
    }
}

# A walker that, from any shell, reads the shared slot. The issue is that
# this read returns the slot's current value regardless of which shell asked.
walker ReadCwd {
    has owner: str = "";

    can start with Root entry {
        visit [-->];
    }

    can read_slot with CwdSlot entry {
        # The orchestrator and every subagent arrive here and see the SAME
        # value because they all reach the single shared slot.
        print(f"  shell owner={self.owner} sees path={here.path} writer={here.last_writer}");
        visit [-->];
    }

    can ignore with Shell entry {
        visit [-->];
    }
}

# Detect cross-contamination: a sibling wrote the slot since we last read.
walker DetectContamination {
    has owner: str = "";

    can start with Root entry {
        visit [-->];
    }

    can check with Shell entry {
        if here.last_observed_writer != "" and here.last_observed_writer != self.owner and here.pinned {
            print(f"  [CONTAMINATION] shell {here.owner} last read by {here.last_observed_writer}, expected {self.owner}");
        }
        visit [-->];
    }
}

with entry {
    # The single shared slot — this is the bug object.
    slot = CwdSlot(path="/repo/main", last_writer="init");

    # Orchestrator's persistent shell.
    orch = Shell(owner="orchestrator", last_observed_path="/repo/main");

    # Concurrent subagents, each with its own shell. Each EnterWorktree edge
    # claims to rebind only the calling agent, but the slot is shared.
    root ++> slot;
    root ++> orch;

    # Subagent A enters its worktree.
    root +>:EnterWorktree(target_path="/repo/lane-a", caller="subagent-A"):+>
        Shell(owner="subagent-A", last_observed_path="/repo/main");

    # Subagent B enters its worktree.
    root +>:EnterWorktree(target_path="/repo/lane-b", caller="subagent-B"):+>
        Shell(owner="subagent-B", last_observed_path="/repo/main");

    # Subagent of a subagent (C) also rebinds the slot.
    root +>:EnterWorktree(target_path="/repo/lane-c", caller="subagent-A->subagent-C"):+>
        Shell(owner="subagent-C", last_observed_path="/repo/main");

    # 1) Initial state: everyone reads the shared slot — same value.
    print("=== initial shared-slot reads ===");
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-A");
    root spawn ReadCwd(owner="subagent-B");
    root spawn ReadCwd(owner="subagent-C");

    # 2) Subagent A fires EnterWorktree(lane-a) — slot is now lane-a.
    print("\n=== after EnterWorktree(lane-a) by subagent-A ===");
    slot.path = "/repo/lane-a";
    slot.last_writer = "subagent-A";
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-B");

    # 3) Subagent B fires EnterWorktree(lane-b) — slot is now lane-b, but
    #    the orchestrator's shell ALSO sees lane-b on its next read. That's
    #    the cross-contamination: orchestrator was not the caller.
    print("\n=== after EnterWorktree(lane-b) by subagent-B ===");
    slot.path = "/repo/lane-b";
    slot.last_writer = "subagent-B";
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-A");

    # 4) Deep subagent C fires EnterWorktree(lane-c) — orchestrator and both
    #    sibling subagents observe lane-c. Last-writer-wins across the tree.
    print("\n=== after EnterWorktree(lane-c) by subagent-A->subagent-C ===");
    slot.path = "/repo/lane-c";
    slot.last_writer = "subagent-A->subagent-C";
    root spawn ReadCwd(owner="orchestrator");
    root spawn ReadCwd(owner="subagent-A");
    root spawn ReadCwd(owner="subagent-B");

    # 5) Reproduce the "no explicit EnterWorktree call" variant from the
    #    issue: a sibling subagent's bootstrap (modeled as a slot mutation
    #    without a typed EnterWorktree edge) still contaminates everyone.
    print("\n=== subagent bootstrap alone (no explicit EnterWorktree) ===");
    slot.path = "/repo/lane-a-boot";
    slot.last_writer = "subagent-A bootstrap";
    root spawn ReadCwd(owner="orchestrator");

    # 6) Mark all shells as pinned to their last observed value, then
    #    mutate the slot again, then run the contamination detector.
    print("\n=== contamination detection ===");
    orch.pinned = True;
    orch.last_observed_writer = "init";
    slot.path = "/repo/lane-c";
    slot.last_writer = "subagent-A->subagent-C";
    root spawn DetectContamination(owner="orchestrator");
}

"""Watch-planner re-plan demo: ignored subtrees created AFTER startup under a
recursive watch escape the split planner and stay watched recursively.

Models the essential scenario from issue #908: a planner decides at startup
which subtrees are ignored-heavy enough to deserve their own shallow watch
(``Ignored`` edge). A directory without enough ignored children at planning
time gets a ``Recursive`` watch edge. If ignored trees later grow under it,
the original plan is stale and the new trees are watched recursively by the
kernel — the exposure the issue describes.
"""

node Directory {
    has name: str = "";
    # Total child directories observed under this node (used by the planner).
    has child_count: int = 0;
    # How many of those children are ignored (node_modules, target/, etc).
    has ignored_child_count: int = 0;
}

# The threshold below which a directory is considered "clean" and gets one
# recursive watch covering everything underneath.
glob WATCH_SPLIT_MIN_DIRS: int = 4;

edge Ignored {
    has reason: str = "";
}

# A recursive watch installed over a directory. The kernel will pick up every
# file/folder created under it later — including newly-grown ignored trees.
edge Recursive {
    has installed_at: str = "startup";
}

# A shallow watch on a directory (the kernel only sees immediate children).
edge Shallow {
    has installed_at: str = "startup";
}

walker Planner {
    has reentry: bool = False;

    can plan with Root entry {
        print(f"[plan] startup pass (re-entry={self.reentry})");
        visit [-->];
    }

    can plan_dir with Directory entry {
        heavy_enough = here.ignored_child_count >= WATCH_SPLIT_MIN_DIRS;
        if heavy_enough {
            print(f"[plan]   {here.name}: "
                  f"{here.ignored_child_count} ignored dirs >= "
                  f"{WATCH_SPLIT_MIN_DIRS} -> Shallow watch installed");
            visit [-->];
        } else {
            tag = "stale-recursive" if self.reentry else "startup-recursive";
            print(f"[plan]   {here.name}: "
                  f"{here.ignored_child_count} ignored dirs < "
                  f"{WATCH_SPLIT_MIN_DIRS} -> Recursive watch installed "
                  f"({tag})");
            visit [-->];
        }
    }
}

walker Auditor {
    can audit with Root entry {
        print("[audit] walking watch graph to find ignored trees under recursive watches");
        visit [-->];
    }

    can audit_dir with Directory entry {
        # Look at every recursive edge leaving this directory and check whether
        # ignored subtrees grew underneath it after the planner ran. This is
        # the re-plan opportunity the issue suggests.
        recs = [here ->:Recursive:->];
        for r in recs {
            grew = here.ignored_child_count >= WATCH_SPLIT_MIN_DIRS;
            if grew {
                print(f"[audit] EXPOSURE: {here.name} has a recursive watch but "
                      f"{here.ignored_child_count} ignored children now exist "
                      f"under it - should release + re-plan");
            } else {
                print(f"[audit] ok: {here.name} recursive watch covers "
                      f"{here.ignored_child_count} ignored dirs (under threshold)");
            }
        }
        visit [-->];
    }
}

with entry {
    # --- Repository layout at STARTUP ---
    #
    #   root
    #   |-- src/        (0 ignored children)
    #   |-- vendor/     (0 ignored children)
    #   |-- build/      (0 ignored children)
    #   |-- docs/       (0 ignored children)
    src = Directory(name="src");
    vendor = Directory(name="vendor");
    build = Directory(name="build");
    docs = Directory(name="docs");
    root ++> src ++> vendor ++> build ++> docs;

    # Plan once at startup. None of these has an ignored tree yet, so each
    # gets a recursive watch - that is the *correct* startup decision given
    # the source state.
    root spawn Planner();

    # Simulate the bug: after `watch` started, `npm install` runs and grows
    # `node_modules` under `vendor/`, and `cargo build` produces `target/`
    # under `src/`. The counts reflect post-install reality, but the
    # recursive watch from the startup plan still holds.
    src.ignored_child_count = 5;
    vendor.ignored_child_count = 6;

    # The watcher does NOT re-plan, so the recursive edges from startup are
    # still in force. Audit the graph to make the exposure visible.
    print("");
    root spawn Auditor();

    # Now demonstrate the suggested fix: re-plan. The planner sees the new
    # ignored-child counts and would install shallow watches instead.
    print("");
    root spawn Planner(reentry=True);

    # After a re-plan, the recursive edges should be gone. The audit would
    # no longer flag these directories - but the source code doesn't do this
    # today, which is exactly the issue.
    print("");
    src.ignored_child_count = 0;
    vendor.ignored_child_count = 0;
    src +>:Ignored(reason="target/"):+> Directory(name="target_stub");
    vendor +>:Ignored(reason="node_modules/"):+> Directory(name="node_modules_stub");
}

