"""ML model governance graph: MLflow registry, ECOA bias audit, SHAP retention,
and annual external model risk review for BPFS models (Spec §12.6).

Walks a model through governance: owner + lineage → bias audit gate →
SHAP retention → external review sign-off. A failing bias audit blocks
promotion (CI gate). Demonstrates typed-edge relationships and walker-based
governance traversal across the model artifacts.
"""

node Model {
    has name: str = "";
    has use_case: str = "";
    has promoted: bool = False;
    has retired: bool = False;
}

node Owner {
    has team: str = "";
    has signed_off: bool = False;
}

node BiasAudit {
    has quarter: str = "";
    has four_fifths_pass: bool = False;
    has parity_pass: bool = False;
    has blocked_promotion: bool = False;
}

node ShapRetention {
    has retention_years: int = 0;
    has retained: bool = False;
}

node ExternalReview {
    has year: int = 0;
    has approved: bool = False;
}

edge Owns {}
edge HasAudit {}
edge HasShap {}
edge HasReview {}

walker Governor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Model entry {
        if here.retired {
            print(f"[SKIP] {here.name} is retired; skipping governance walk");
            return;
        }
        owner = [->:Owns:->][0] if [->:Owns:->] else None;
        audit = [->:HasAudit:->][0] if [->:HasAudit:->] else None;
        shap = [->:HasShap:->][0] if [->:HasShap:->] else None;
        review = [->:HasReview:->][0] if [->:HasReview:->] else None;

        owner_ok = owner is not None and owner.signed_off;
        audit_ok = audit is not None and audit.four_fifths_pass and audit.parity_pass and not audit.blocked_promotion;
        shap_ok = shap is not None and shap.retained and shap.retention_years >= 7;
        review_ok = review is not None and review.approved;

        if audit_ok and shap_ok and review_ok and owner_ok {
            here.promoted = True;
            print(f"[PROMOTE] {here.name} ({here.use_case}) cleared governance");
        } elif audit is not None and not audit_ok {
            here.promoted = False;
            print(f"[BLOCKED] {here.name}: bias audit failed (4/5={audit.four_fifths_pass}, parity={audit.parity_pass}, blocked={audit.blocked_promotion})");
        } else {
            here.promoted = False;
            print(f"[HOLD] {here.name}: owner={owner_ok}, audit={audit_ok}, shap={shap_ok}, review={review_ok}");
        }

        visit [-->];
    }

    can check_owner with Owner entry {
        status = "signed" if here.signed_off else "unsigned";
        print(f"  owner[{status}]: {here.team}");
        visit [-->];
    }

    can check_audit with BiasAudit entry {
        status = "PASS" if (here.four_fifths_pass and here.parity_pass and not here.blocked_promotion) else "FAIL";
        print(f"  audit[{status}] Q{here.quarter} 4/5={here.four_fifths_pass} parity={here.parity_pass}");
        visit [-->];
    }

    can check_shap with ShapRetention entry {
        status = "OK" if (here.retained and here.retention_years >= 7) else "INSUFFICIENT";
        print(f"  shap[{status}] retained={here.retained} years={here.retention_years}");
        visit [-->];
    }

    can check_review with ExternalReview entry {
        status = "approved" if here.approved else "pending";
        print(f"  external[{status}] year={here.year}");
        visit [-->];
    }
}

with entry {
    bpfs = Model(name="BPFS", use_case="lender-ready credit scoring");
    root ++> bpfs;
    bpfs +>:Owns:+> Owner(team="Risk ML", signed_off=True);
    bpfs +>:HasAudit:+> BiasAudit(quarter="Q3-2025", four_fifths_pass=False, parity_pass=True, blocked_promotion=True);
    bpfs +>:HasShap:+> ShapRetention(retention_years=7, retained=True);
    bpfs +>:HasReview:+> ExternalReview(year=2025, approved=True);

    churn = Model(name="ChurnClassifier", use_case="retention marketing");
    root ++> churn;
    churn +>:Owns:+> Owner(team="Growth ML", signed_off=True);
    churn +>:HasAudit:+> BiasAudit(quarter="Q3-2025", four_fifths_pass=True, parity_pass=True, blocked_promotion=False);
    churn +>:HasShap:+> ShapRetention(retention_years=5, retained=True);
    churn +>:HasReview:+> ExternalReview(year=2024, approved=True);

    fraud = Model(name="FraudDetector", use_case="transactional fraud");
    root ++> fraud;
    fraud +>:Owns:+> Owner(team="Fraud ML", signed_off=False);
    fraud +>:HasAudit:+> BiasAudit(quarter="Q3-2025", four_fifths_pass=True, parity_pass=True, blocked_promotion=False);
    fraud +>:HasShap:+> ShapRetention(retention_years=7, retained=True);
    fraud +>:HasReview:+> ExternalReview(year=2025, approved=True);

    print("=== Governance audit pass ===");
    root spawn Governor();

    print("\n=== Retired-model gate ===");
    bpfs.retired = True;
    root spawn Governor();
}

