"""BigQuery job credential scoping: model the silent admin-credential loss.

Walks a job graph from owner → job → script → referenced env vars, evaluates
each env var's required scope against the owner's role tier, and reports the
silently-empty admin credentials that break member-owned jobs.
"""

node Owner {
    has name: str = "";
    has role: str = "member";      # member | power_user | admin
}

node Job {
    has title: str = "";
    has status: str = "scheduled"; # scheduled | running | failed | stale_killed
    has minutes_stale: int = 0;
}

node Script {
    has body: str = "";
}

node Credential {
    has env_var: str = "";
    has scope: str = "member";     # member | power_user | admin
}

edge Owns { }
edge Runs { }
edge References { }
edge Requires { }

walker CredentialAuditor {
    has failures: list[str] = [];
    has tier_map: dict[str, int] = {"member": 0, "power_user": 1, "admin": 2};

    can start with Root entry {
        visit [-->];
    }

    can audit_owner with Owner entry {
        visit [->:Owns:->];
    }

    can audit_job with Job entry {
        visit [->:Runs:->];
    }

    can audit_script with Script entry {
        visit [->:References:->];
    }

    can audit_credential with Credential entry {
        # Walk back to the owner of the job that referenced this credential.
        # The walker doesn't natively reverse, so we re-derive via `here`'s
        # context: every credential is only reached through Owner→Owns→Job→
        # Runs→Script→References→Credential on this demo graph.
        needed = self.tier_map[here.scope] if here.scope in self.tier_map else 0;
        # The owner is whichever Owner spawned this walker (we mirror it).
        owner_level = self.tier_map[self.owner_role] if self.owner_role in self.tier_map else 0;
        if owner_level < needed {
            note = (f"SILENT FAIL: job owner (role={self.owner_role}) "
                    f"cannot access {here.env_var} (scope={here.scope})");
            self.failures.append(note);
        }
        visit [-->] else { disengage; }
    }

    has owner_role: str = "member";
}

with entry {
    # Two demo owners: an admin and a member — same script reference graph.
    admin_owner = Owner(name="Admin Root", role="admin");
    member_owner = Owner(name="Nuria Verdejo", role="member");

    # A member-owned daily job that depends on an admin-scoped credential.
    nuria_job = Job(title="nuria-daily-prospect-list", status="stale_killed", minutes_stale=200);
    prospect_script = Script(body="echo $GOOGLE_SA_KEY_B64 | base64 -d > /tmp/sa.json; gcloud auth activate-service-account --key-file=/tmp/sa.json");

    # An admin-scoped warehouse service-account credential.
    sa_cred = Credential(env_var="GOOGLE_SA_KEY_B64", scope="admin");

    # Wire the dependency chain: owner OWNS job, job RUNS script, script
    # REFERENCES the credential, and the credential REQUIRES admin scope.
    admin_owner ++> Job(title="admin-warehouse-backup") ++> prospect_script;
    member_owner +>:Owns:+> nuria_job;
    nuria_job +>:Runs:+> prospect_script;
    prospect_script +>:References:+> sa_cred;
    sa_cred +>:Requires:+> Credential(env_var="BQ_PROJECT_ID", scope="member");

    # Run the auditor on the member owner: it should report the silent failure.
    member_audit = CredentialAuditor(owner_role="member");
    member_owner spawn member_audit;
    print(f"[member audit] failures observed: {len(member_audit.failures)}");
    for note in member_audit.failures {
        print(f"  - {note}");
    }

    # Same graph, same script, but an admin owner — the credential resolves.
    admin_audit = CredentialAuditor(owner_role="admin");
    admin_owner spawn admin_audit;
    print(f"[admin audit] failures observed: {len(admin_audit.failures)}");
}

