"""Operational incident rehearsal with typed dependencies and cycle detection."""

node OperationalNode {
    has name: str = "";
    has healthy: bool = True;
}

node Service(OperationalNode) {
    has readiness_reason: str = "";
    has available: bool = True;
}

node AlertRule(OperationalNode) {
    has severity: str = "";
    has firing: bool = False;
}

node Runbook(OperationalNode) {
    has owner: str = "";
    has verified: bool = False;
}

node Incident(OperationalNode) {
    has revocation_preserved: bool = True;
    has evidence_safe: bool = True;
}

edge DependsOn {
    has reason: str = "";
}

walker IncidentRehearsal {
    has seen: list[str] = [];
    has cycle_detected: bool = False;
    has steps: int = 0;
    has max_steps: int = 12;

    can start with Root entry {
        print("Starting disposable security incident rehearsal");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect with Service | AlertRule | Runbook | Incident entry {
        if self.steps >= self.max_steps {
            print("Rehearsal stopped at dependency depth limit");
            self.cycle_detected = True;
            disengage;
        } else {
            already_seen = here.name in self.seen;
            if already_seen {
                print(f"Cycle detected at {here.name}; rehearsal halted safely");
                self.cycle_detected = True;
                disengage;
            } else {
                self.seen.append(here.name);
                self.steps += 1;
                print(f"Checking {here.name}; healthy={here.healthy}");
                visit [->:DependsOn:->] else {
                    print(f"Completed dependency checks for {here.name}");
                }
            }
        }
    }
}

