"""Channel Performance: cascade-invalidate downstream channel reports when a branch's source order data is corrected.

Models the canonical Task 5.6 scenario: recommendations are computed per
(channel x branch) as derived nodes that depend on upstream Order nodes.
When a source order is corrected (availability flipped, total cents
changed), every downstream report depending on it must be invalidated
and recomputed -- a cascade walk along typed DependsOn relationships with
a guard set so cycles cannot hang the walker.
"""

node Branch {
    has name: str = "";
    has city: str = "";
}

node Order {
    has order_id: str = "";
    has channel: str = "dine-in";
    has total_cents: int = 0;
    has is_valid: bool = True;
}

node ChannelReport {
    has channel: str = "";
    has branch_name: str = "";
    has revenue_cents: int = 0;
    has order_count: int = 0;
    has is_stale: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

walker CascadeInvalidator {
    has source_order: str = "";
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Branch entry {
        visit [-->];
    }

    can invalidate with Order entry {
        if here.order_id == self.source_order {
            here.is_valid = False;
            self.invalidated.append("order:" + here.order_id);
        }
        visit [->:DependsOn:->];
    }

    can mark_stale with ChannelReport entry {
        if not here.is_stale {
            here.is_stale = True;
            self.invalidated.append(here.channel + "@" + here.branch_name);
        }
        visit [-->];
    }
}

with entry {
    downtown = Branch(name="downtown", city="Dubai");
    marina = Branch(name="marina", city="Dubai");
    root ++> downtown ++> marina;

    o1 = Order(order_id="O-1001", channel="dine-in", total_cents=12500);
    o2 = Order(order_id="O-1002", channel="delivery", total_cents=8800);
    o3 = Order(order_id="O-1003", channel="dine-in", total_cents=4200);
    root ++> o1 ++> o2 ++> o3;

    dine_in_report = ChannelReport(
        channel="dine-in", branch_name="downtown",
        revenue_cents=12500, order_count=1
    );
    delivery_report = ChannelReport(
        channel="delivery", branch_name="downtown",
        revenue_cents=8800, order_count=1
    );
    dine_in_marina = ChannelReport(
        channel="dine-in", branch_name="marina",
        revenue_cents=4200, order_count=1
    );
    root ++> dine_in_report ++> delivery_report ++> dine_in_marina;

    dine_in_report +>:DependsOn(weight=1):+> o1;
    delivery_report +>:DependsOn(weight=1):+> o2;
    dine_in_marina +>:DependsOn(weight=1):+> o3;
    dine_in_report +>:DependsOn(weight=1):+> o3;

    inv = CascadeInvalidator(source_order="O-1003");
    root spawn inv;

    print("Invalidated by cascade:");
    for label in inv.invalidated {
        print(f"  - {label}");
    }
}

"""Dynamic Team Manager: scout, draft, evaluate, rotate.

Models a roster of agent candidates, scouts who draft them into teams,
and a walker that traverses the hierarchy to evaluate, prune, and clone
underperformers — replacing the hand-rolled recursion from the issue
with native typed-edge traversal.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Agent {
    has name: str = "";
    has role: str = "";
    has skill: int = 50;
    has scope: str = "";
}

node Team {
    has name: str = "";
    has tier: str = "mid";
    has budget: int = 1000;
}

node Scout {
    has name: str = "";
}

node Bid {
    has amount: int = 0;
    has on_job: str = "";
}

# ---------------------------------------------------------------------------
# Typed edges (every referenced edge type is declared here)
# ---------------------------------------------------------------------------

edge Scouted {
    has since: str = "";
}

edge DraftedTo {
    has draft_round: int = 0;
}

edge ReportsTo {
    has tenure: int = 0;
}

edge Spectates {
    has stake: int = 0;
}

edge BidOn {
}

# ---------------------------------------------------------------------------
# Walkers
# ---------------------------------------------------------------------------

walker RosterBuilder {
    can start with Root entry {
        print("Seeding roster of candidates...");
        visit [-->];
    }

    can gather with Agent entry {
        label = "star" if here.skill >= 80 else "bench";
        print(f"  candidate [{label}]: {here.name} ({here.role}) skill={here.skill}");
        visit [-->];
    }
}

walker ScoutEvaluator {
    has cycles_seen: list[str] = [];
    has pruned: list[str] = [];
    has cloned: list[str] = [];

    can start with Root entry {
        print("\nScout walking hierarchy...");
        visit [-->];
    }

    can scout with Scout entry {
        print(f"Scout {here.name} is walking the tree...");
        visit [-->];
    }

    can audit with Team entry {
        # Bottom tier: prune; Top tier: clone; Mid: evaluate.
        if here.tier == "bottom" {
            for child in [->:DraftedTo:->] {
                self.pruned.append(child.name);
            }
            print(f"PRUNE bottom team {here.name}: {len(self.pruned)} agent(s) cut");
        } elif here.tier == "top" {
            for child in [->:DraftedTo:->] {
                if child.name not in self.cloned {
                    self.cloned.append(child.name + "*");
                }
            }
            print(f"CLONE top team {here.name}: {len(self.cloned)} clone(s) drafted");
        } else {
            count = 0;
            for _child in [->:DraftedTo:->] {
                count += 1;
            }
            print(f"EVALUATE mid team {here.name}: {count} agent(s) under review");
        }
        visit [-->];
    }

    can tag with Agent entry {
        guard_key = here.name + "@" + here.role;
        if guard_key in self.cycles_seen {
            disengage;
        }
        self.cycles_seen.append(guard_key);
        verdict = "keep" if here.skill >= 60 else "review";
        print(f"  agent {here.name} ({verdict})");
        visit [-->];
    }
}

walker Reachability {
    has reachable: list[str] = [];

    can start with Root entry {
        print("\nReachability from root:");
        visit [-->];
    }

    can collect with Team entry {
        self.reachable.append(here.name);
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Build candidate roster (Agent nodes).
    ada = Agent(name="Ada", role="Engineer", skill=85, scope="ML");
    linus = Agent(name="Linus", role="Engineer", skill=95, scope="Kernels");
    grace = Agent(name="Grace", role="Researcher", skill=80, scope="Compilers");
    dennis = Agent(name="Dennis", role="Engineer", skill=55, scope="Scripting");
    newbie = Agent(name="Newbie", role="Rookie", skill=30, scope="None");

    # Teams at three tiers.
    top = Team(name="SQuAD-Alpha", tier="top", budget=5000);
    mid = Team(name="SQuAD-Beta", tier="mid", budget=2500);
    bottom = Team(name="SQuAD-Gamma", tier="bottom", budget=500);

    # Scouts that walk the hierarchy.
    head_scout = Scout(name="MoneyBall");
    asst_scout = Scout(name="Rookie-Scout");

    # A betting bid on a job.
    bid1 = Bid(amount=250, on_job="refactor-cli");

    # Wire typed edges: Scout scouted Agents, Scouts report to teams,
    # teams drafted agents, spectator (a scout) bets on a job.
    root ++> ada ++> linus ++> grace ++> dennis ++> newbie;
    root ++> top ++> mid ++> bottom;
    root ++> head_scout ++> asst_scout;
    root ++> bid1;

    head_scout +>:Scouted(since="2024-Q1"):+> ada;
    head_scout +>:Scouted(since="2024-Q1"):+> linus;
    head_scout +>:Scouted(since="2024-Q1"):+> grace;
    asst_scout +>:Scouted(since="2024-Q2"):+> dennis;
    asst_scout +>:Scouted(since="2024-Q2"):+> newbie;

    head_scout +>:ReportsTo(tenure=5):+> top;
    asst_scout +>:ReportsTo(tenure=1):+> mid;

    top +>:DraftedTo(draft_round=1):+> ada;
    top +>:DraftedTo(draft_round=1):+> linus;
    mid +>:DraftedTo(draft_round=2):+> grace;
    mid +>:DraftedTo(draft_round=3):+> dennis;
    bottom +>:DraftedTo(draft_round=4):+> newbie;

    head_scout +>:Spectates(stake=100):+> bid1;
