"""Hierarchical capability catalog — US-005-01-01.

Models a tiered capability tree with CRUD-style walkers and a single-node
reorder constraint (BD-11: drag-drop bulk reorder is blocked). The catalog
is a tree of Capability nodes connected by typed `ParentOf` edges; a
`CatalogAuditor` walker traverses the tree to verify reachability and a
`CapabilityCascade` walker removes a node along with its descendants.
"""

node Capability {
    has title: str = "";
    has description: str = "";
    has sort_order: int = 0;
    has available: bool = True;
}

edge ParentOf {
    has ordering: int = 0;
}

walker CatalogAuditor {
    can start with Root entry {
        print("Auditing capability catalog from root...");
        visit [->:ParentOf:->];
    }

    can descend with Capability entry {
        status = "ACTIVE" if here.available else "DISABLED";
        print(f"  [auditor] {here.title} (order={here.sort_order}) -> {status}");
        visit [->:ParentOf:->];
    }
}

walker CapabilityCascade {
    has target_title: str = "";
    has removed_count: int = 0;

    can start with Root entry {
        print(f"Cascade delete requested for '{self.target_title}'");
        visit [->:ParentOf:->];
    }

    can sweep with Capability entry {
        if here.title == self.target_title {
            print(f"  [cascade] found '{here.title}' -> removing with descendants");
            self.removed_count += 1;
            del here;
            disengage;
        }
        visit [->:ParentOf:->];
    }
}

