"""Project materialization: skills stored as nodes, linked into a project graph, and a
walker that cascades the managed .gitignore block across the materialized tree.

Models the essential scenario from issue #12: in a project scope, only the manifest
is committed; materialized skill directories are tracked via a managed block and
reproduced by sync. The walker simulates the sync by traversing the project tree
along typed edges and printing the managed block it would write.
"""

# ---- Entities ----------------------------------------------------------------

node Project {
    has name: str = "";
    has store_root: str = "";
    has manifest_committed: bool = True;
}

node Skill {
    has name: str = "";
    has has_local_source: bool = False;
    has ignore: bool = True;
}

node HoldoutTarget {
    has tool: str = "";
    has project_dir: str = "";
}

# ---- Relationships (typed edges) -------------------------------------------

edge HasSkill {
    has placed_at: str = "";
}

edge HoldoutFor {
    has project_anchor: str = "";
}

# ---- Walker: writes the managed gitignore block by traversing the project ---

walker ManagedBlockWriter {
    has project_root: str = "";
    has lines: list[str] = [];
    has done: bool = False;
    has block_emitted: bool = False;

    can begin with Root entry {
        visit [-->];
    }

    can walk_project with Project entry {
        self.project_root = here.store_root;
        # Cascade invalidation: a project whose manifest isn't committed
        # cannot have a managed block — disengage early.
        if not here.manifest_committed {
            print(f"[abort] project '{here.name}': manifest not committed; managed block not written");
            disengage;
        }
        print(f"# gent:begin — managed by gent; do not edit between markers");
        visit [->:HasSkill:->];
    }

    can emit_skill_line with Skill entry {
        line = f".agents/skills/{here.name}/";
        self.lines.append(line);
        print(line);
        if here.has_local_source {
            print(f"# {here.name} has in-repo source — only its materialized copy is ignored");
        }
        # Walk to any holdout target links off this skill (none expected here,
        # but the typed edge exists for the project-level case).
        visit [->:HoldoutFor:->];
    }

    can emit_holdout_line with HoldoutTarget entry {
        line = f"{here.project_dir}/";
        self.lines.append(line);
        print(line);
    }
}

# ---- Reachability walker (cycle-safe) ---------------------------------------

walker ReachabilityChecker {
    has visited: list[str] = [];
    has target: str = "";
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can traverse with Project entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        print(f"reached project: {here.name}");
        visit [->:HasSkill:->];
    }

    can check_skill with Skill entry {
        print(f"  contains skill: {here.name}");
        if here.name == self.target {
            print(f"[found] target skill '{self.target}' is reachable");
            self.found = True;
            disengage;
        }
    }
}

# ---- Demonstration ----------------------------------------------------------

with entry {
    # Project scope: storeRoot, plus two holdout tools (claude-code, droid).
    proj = Project(
        name="gent-demo",
        store_root="/repo/.agents/skills",
        manifest_committed=True
    );

    claude = HoldoutTarget(tool="claude-code", project_dir=".claude/skills");
    droid = HoldoutTarget(tool="droid", project_dir=".factory/skills");

    s_review = Skill(name="review-pr", has_local_source=False);
    s_lint = Skill(name="lint-md", has_local_source=True);
    s_release = Skill(name="release-notes", has_local_source=False);

    # Project -> skills (typed edges: HasSkill carries placement path).
    proj +>:HasSkill(placed_at="/repo/.agents/skills/review-pr/"):+> s_review;
    proj +>:HasSkill(placed_at="/repo/.agents/skills/lint-md/"):+> s_lint;
    proj +>:HasSkill(placed_at="/repo/.agents/skills/release-notes/"):+> s_release;

    # Holdout tools hang off the project root via HoldoutFor edges.
    proj +>:HoldoutFor(project_anchor="/repo"):+> claude;
    proj +>:HoldoutFor(project_anchor="/repo"):+> droid;

    root ++> proj;

    # Demo 1: managed block writer walks the project graph.
    print("=== Managed .gitignore block (sync simulation) ===");
    root spawn ManagedBlockWriter();
    print(f"# gent:end");

    # Demo 2: reachability check with cycle-safe guard.
    print("\n=== Reachability check ===");
    checker = ReachabilityChecker(target="release-notes");
    root spawn checker;
}

