"""Water pipeline tracer: walk a pipe graph from the intake, log each segment,
note dead-end valves gracefully, and summarize the full route."""

node Valve {
    has name: str = "";
    has pressure: float = 0.0;
    has capped: bool = False;
}

edge Pipe {
    has diameter: str = "";
    has length_m: float = 0.0;
}

walker Tracer {
    has route: list[str] = [];
    has dead_ends: list[str] = [];
    has depth_limit: int = 25;
    has depth: int = 0;

    can start with Root entry {
        self.route = [];
        self.dead_ends = [];
        self.depth = 0;
        visit [-->];
    }

    can trace with Valve entry {
        segment = f"{here.name} (P={here.pressure:.1f})";
        self.route.append(segment);
        self.depth += 1;

        if self.depth >= self.depth_limit {
            print(f"[DEPTH-LIMIT] bail out at {here.name}");
            self.dead_ends.append(here.name);
            return;
        }

        if here.capped {
            print(f"[DEAD-END] capped valve: {here.name}");
            self.dead_ends.append(here.name);
            return;
        }

        next_nodes = [->:Pipe:->];
        if not next_nodes {
            print(f"[DEAD-END] no outgoing pipe from {here.name}");
            self.dead_ends.append(here.name);
            return;
        }

        print(f"[FLOW] {here.name} -> {len(next_nodes)} pipe(s) downstream");
        visit next_nodes else {
            print(f"[DEAD-END] traverse failed at {here.name}");
            self.dead_ends.append(here.name);
            disengage;
        };
    }

    can summarize with Root exit {
        print("");
        print("=== PIPELINE TRACE SUMMARY ===");
        if not self.route {
            print("No valves reached from intake.");
        } else {
            step = 0;
            for label in self.route {
                print(f"  {step}: {label}");
                step += 1;
            }
        }
        print(f"Total valves visited: {len(self.route)}");
        print(f"Dead ends encountered: {len(self.dead_ends)}");
        for name in self.dead_ends {
            print(f"  - {name}");
        }
    }
}

with entry {
    intake = Valve(name="Intake-A", pressure=120.0);
    junction_b = Valve(name="Junction-B", pressure=110.0);
    junction_c = Valve(name="Junction-C", pressure=105.0);
    capped_d = Valve(name="Cap-D", pressure=0.0, capped=True);
    service_e = Valve(name="Service-E", pressure=95.0);
    stub_f = Valve(name="Stub-F", pressure=0.0, capped=True);

    root +>:Pipe(diameter="24in", length_m=10.0):+> intake;
    intake +>:Pipe(diameter="18in", length_m=30.0):+> junction_b;
    intake +>:Pipe(diameter="18in", length_m=25.0):+> junction_c;
    junction_b +>:Pipe(diameter="12in", length_m=15.0):+> capped_d;
    junction_b +>:Pipe(diameter="12in", length_m=40.0):+> service_e;
    junction_c +>:Pipe(diameter="10in", length_m=8.0):+> stub_f;

    root spawn Tracer(depth_limit=25);
}

"""Structural invariant checkers (BST ordering, heap property, linked-list acyclicity).

Models data-structure invariants as graph archetypes: BST nodes connected by
``BSTEdge``, heap slots connected by ``HeapEdge``, and linked-list nodes
connected by ``NextEdge``. Walker(s) traverse each structure and report
violations through a shared ``InvariantResult`` counterexample format.
"""

node TreeNode {
    has value: int = 0;
    has lo: int = 0;
    has hi: int = 0;
}

node HeapNode {
    has value: int = 0;
    has parent_value: int = 0;
    has is_root: bool = False;
}

node ListNode {
    has value: int = 0;
}

edge BSTEdge { }
edge HeapEdge { }
edge NextEdge { }

node InvariantResult {
    has name: str = "";
    has passed: bool = True;
    has counterexample: str = "";
}

walker BSTChecker {
    can start with Root entry {
        visit [->:BSTEdge:->];
    }

    can check with TreeNode entry {
        ok_lo = here.value >= here.lo;
        ok_hi = here.value <= here.hi;
        if not ok_lo or not ok_hi {
            msg = (
                f"BST violation at value={here.value}: "
                f"expected {here.lo} <= v <= {here.hi}"
            );
            print(f"[BST] FAIL :: {msg}");
            result = InvariantResult(name="bst_ordering", passed=False, counterexample=msg);
            disengage;
        } else {
            print(f"[BST] ok :: value={here.value} in [{here.lo},{here.hi}]");
            visit [->:BSTEdge:->];
        }
    }
}

walker HeapChecker {
    can start with Root entry {
        visit [->:HeapEdge:->];
    }

    can check with HeapNode entry {
        if here.is_root {
            print(f"[HEAP] ok :: root value={here.value}");
            visit [->:HeapEdge:->];
        } else {
            if here.parent_value <= here.value {
                print(
                    f"[HEAP] ok :: parent={here.parent_value} <= "
                    f"child={here.value}"
                );
                visit [->:HeapEdge:->];
            } else {
                msg = (
                    f"Heap violation: parent={here.parent_value} "
                    f"> child={here.value}"
                );
                print(f"[HEAP] FAIL :: {msg}");
                result = InvariantResult(name="heap_property", passed=False, counterexample=msg);
                disengage;
            }
        }
    }
}

walker CycleChecker {
    has seen: list[int] = [];

    can start with Root entry {
        visit [->:NextEdge:->];
    }

    can check with ListNode entry {
        marker = here.value;
        already = False;
        for s in self.seen {
            if s == marker {
                already = True;
            }
        }
        if already {
            msg = f"Cycle detected revisiting node value={marker}";
            print(f"[LIST] FAIL :: {msg}");
            result = InvariantResult(name="acyclicity", passed=False, counterexample=msg);
            disengage;
        } else {
            self.seen.append(marker);
            print(f"[LIST] ok :: visited value={marker}");
            visit [->:NextEdge:->];
        }
    }
}

with entry {
    # --- BST demo: one bad insert that breaks ordering ---
    n1 = TreeNode(value=10, lo=-1000, hi=1000);
    n2 = TreeNode(value=5, lo=-1000, hi=10);
    n3 = TreeNode(value=20, lo=10, hi=1000);
    n4 = TreeNode(value=2, lo=-1000, hi=10);
    n5 = TreeNode(value=8, lo=-1000, hi=4);
    root +>:BSTEdge:+> n1;
    n1 +>:BSTEdge:+> n2;
    n1 +>:BSTEdge:+> n3;
    n2 +>:BSTEdge:+> n4;
    n2 +>:BSTEdge:+> n5;
    print("--- BST check ---");
    root spawn BSTChecker();

    # --- Heap demo: one bad sift ---
    h1 = HeapNode(value=1, is_root=True);
    h2 = HeapNode(value=3, parent_value=1);
    h3 = HeapNode(value=2, parent_value=1);
    h4 = HeapNode(value=10, parent_value=3);
    root +>:HeapEdge:+> h1;
    h1 +>:HeapEdge:+> h2;
    h1 +>:HeapEdge:+> h3;
    h2 +>:HeapEdge:+> h4;
    print("--- Heap check ---");
    root spawn HeapChecker();

    # --- Linked list acyclicity demo: introduce a cycle ---
    l1 = ListNode(value=100);
    l2 = ListNode(value=200);
    l3 = ListNode(value=300);
    l4 = ListNode(value=400);
    root +>:NextEdge:+> l1;
    l1 +>:NextEdge:+> l2;
    l2 +>:NextEdge:+> l3;
    l3 +>:NextEdge:+> l4;
    l4 +>:NextEdge:+> l2;
    print("--- Cycle check ---");
    root spawn CycleChecker();
}

"""Collaborative markdown disposal with a captured activity handle."""

node Circuit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has circuit_id: str = "";
}

node CollaborativeMarkdownView {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has captured_handle: bool = False;
}

node ServiceScope {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has disposed: bool = False;
}

node KernelActivity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has released: bool = False;
}

edge ContainsView { }
edge UsesScope { }
edge ProvidesActivity { }

walker DisposalAuditor {
    has captured_handle: bool = False;
    has scope_disposed: bool = False;

    can begin with Root entry {
        print("Circuit teardown begins");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_circuit with Circuit entry {
        print(f"Inspecting circuit {here.circuit_id}");
        visit [->:ContainsView:->] else {
            disengage;
        }
    }

    can inspect_view with CollaborativeMarkdownView entry {
        self.captured_handle = here.captured_handle;
        print(f"View captured handle: {self.captured_handle}");
        visit [->:UsesScope:->] else {
            disengage;
        }
    }

    can inspect_scope with ServiceScope entry {
        self.scope_disposed = here.disposed;
        if self.scope_disposed {
            print("Ambient circuit scope is already disposed");
        } else {
            print("Ambient circuit scope is still alive");
        }
        visit [->:ProvidesActivity:->] else {
            disengage;
        }
    }

    can release_activity with KernelActivity entry {
        if self.captured_handle {
            if here.released {
                print(f"Activity {here.title} was already released");
            } else {
                here.released = True;
                print(f"Released captured activity {here.title}");
            }
        } else {
            print("No captured handle; disposal skips ambient resolution");
        }
    }
}

with entry {
    circuit = Circuit(circuit_id="circuit-3556");
    view = CollaborativeMarkdownView(
        title="Collaborative Markdown",
        captured_handle=True
    );
    scope = ServiceScope(title="Circuit DI scope", disposed=True);
    activity = KernelActivity(title="Markdown kernel activity");

    root ++> circuit;
    circuit +>:ContainsView:+> view;
    view +>:UsesScope:+> scope;
    scope +>:ProvidesActivity:+> activity;

    root spawn DisposalAuditor();

    print(f"Final activity released: {activity.released}");
}

