"""Native control-plane demo with dependency traversal and exact-head audit gating."""

node WorkItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "READY";
    has head_sha: str = "";
    has ci_head_sha: str = "";
    has audit_head_sha: str = "";
    has audit_verdict: str = "";
    has in_path: bool = False;

    def merge_eligible() -> bool {
        return self.available
            and self.state == "AUDIT"
            and self.ci_head_sha == self.head_sha
            and self.audit_head_sha == self.head_sha
            and (
                self.audit_verdict == "PASS"
                or self.audit_verdict == "PASS_WITH_NOTES"
            );
    }
}

node Agent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn {
    has reason: str = "";
}

edge OwnedBy {
    has role: str = "";
}

walker ReleaseTrain {
    has inspected: int = 0;

    can begin with Root entry {
        print("event-driven release train started");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with WorkItem entry {
        if here.in_path {
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            here.in_path = True;
            self.inspected += 1;
            print(f"checking dependencies for {here.title}");
            visit [->:DependsOn:->] else {
                print(f"{here.title} has no remaining dependencies");
            }
        }
    }

    can finalize with WorkItem exit {
        if here.merge_eligible() {
            here.state = "MERGE_READY";
            print(f"{here.title}: exact-head audit passed; MERGE_READY");
        } else {
            print(f"{here.title}: merge blocked by stale or missing evidence");
        }
        here.in_path = False;
    }

    can inspect_agent with Agent entry {
        print(f"owner available: {here.title}");
    }
}

with entry {
    owner = Agent(title="NUSA Evolve", year=2025, available=True);

    implementation = WorkItem(
        title="Implement control-plane transition",
        year=2025,
        state="IMPLEMENTING",
        head_sha="sha-impl"
    );

    audit = WorkItem(
        title="Independent exact-head audit",
        year=2025,
        state="AUDIT",
        head_sha="sha-audit",
        ci_head_sha="sha-audit",
        audit_head_sha="sha-audit",
        audit_verdict="PASS"
    );

    release = WorkItem(
        title="Release merge candidate",
        year=2025,
        state="AUDIT",
        head_sha="sha-release",
        ci_head_sha="sha-release",
        audit_head_sha="sha-release",
        audit_verdict="PASS_WITH_NOTES"
    );

    stale = WorkItem(
        title="Stale audit candidate",
        year=2025,
        state="AUDIT",
        head_sha="sha-new",
        ci_head_sha="sha-new",
        audit_head_sha="sha-old",
        audit_verdict="PASS"
    );

    root ++> release;
    root ++> stale;
    root ++> owner;

    release +>:OwnedBy(role="release owner"):+> owner;
    release +>:DependsOn(reason="audit before merge"):+> audit;
    audit +>:DependsOn(reason="implementation before audit"):+> implementation;

    root spawn ReleaseTrain();
}

