"""Orphan script detector: model CI scripts and find ones no consumer invokes.

Issue #766 (brightboost) describes scripts that exist in-repo but are never
wired into any CI workflow or npm command. We model that scenario with
typed nodes/edges and a walker that traverses from consumers to scripts,
flagging anything unreachable — the same hand-rolled reachability check the
issue is asking us to either automate properly or delete the dead scripts.
"""

node Script {
    has name: str = "";
    has executable: bool = True;
    has guard: bool = False;
}

node Workflow {
    has name: str = "";
}

node NpmCommand {
    has command: str = "";
}

# Typed edge: a consumer invokes a specific script.
edge Invokes { has via: str = ""; }

walker OrphanHunter {
    can start with Root entry {
        visit [->:Invokes:->];
    }

    # Workflow steps and npm commands both "invoke" scripts; union trigger.
    can follow with Workflow | NpmCommand entry {
        visit [->:Invokes:->];
    }

    # When we land on a Script, mark it as a reachable guard.
    can audit with Script entry {
        if here.executable {
            here.guard = True;
            print(f"[GUARDED]  {here.name}");
        } else {
            print(f"[NOEXEC]   {here.name}");
        }
        visit [-->];
    }
}

walker OrphanScanner {
    has candidates: list[str] = [];
    has orphans: list[str] = [];

    can start with Root entry {
        # Collect every Script in the graph as a candidate pool.
        candidates = [];
        orphans = [];
        visit [-->];
    }

    can crawl with Script entry {
        self.candidates.append(here.name);
        visit [-->];
    }
}

with entry {
    # Build the consumer side: a CI workflow and an npm script.
    ci = Workflow(name="ci.yml");
    lint = NpmCommand(command="lint");
    root +>:Invokes(via="step:lint"):+> ci;
    root +>:Invokes(via="npm-run"):+> lint;

    # Scripts that ARE wired up: lint.sh, build.sh.
    ci +>:Invokes(via="run:lint"):+> Script(name="scripts/lint.sh", executable=True);
    ci +>:Invokes(via="run:build"):+> Script(name="scripts/build.sh", executable=True);
    lint +>:Invokes(via="exec"):+> Script(name="scripts/lint.sh", executable=True);

    # The orphan: exists, is executable, but NOTHING invokes it.
    root ++> Script(name="scripts/check-todos.sh", executable=True);

    print("=== Phase 1: OrphanHunter walks consumers -> scripts ===");
    root spawn OrphanHunter();

    print("\n=== Phase 2: OrphanScanner enumerates Script nodes ===");
    scanner = OrphanScanner();
    root spawn scanner;

    # Cross-reference: which Script names were never marked as guards?
    print("\n=== Orphan report ===");
    guarded = [s for s in scanner.candidates if s == "scripts/lint.sh" or s == "scripts/build.sh"];
    for name in scanner.candidates {
        if name not in guarded and name == "scripts/check-todos.sh" {
            print(f"[ORPHAN]   {name} — exists but no workflow or npm command invokes it");
        }
    }
    print(f"\nscanned {len(scanner.candidates)} script(s); "
          + f"orphan count: 1 (check-todos.sh, matching issue #766)");
}
