"""Failure-isolated recording and publication traversal demo."""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has account_id: str = "";
    has recorder_state: str = "idle";
    has data_generation: int = 0;
}

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
    has active: bool = True;
    has durable_ack: bool = False;
}

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "error";
    has observed_generation: int = 0;
}

node Lane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has lane_name: str = "";
    has complete: bool = False;
}

edge Owns { }
edge HasSession { }
edge Publishes { }
edge HasLane { }

walker RecorderAudit {
    has committed_sessions: int = 0;

    can start with Root entry {
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect_account with Account entry {
        print(f"recorder {here.account_id}: {here.recorder_state}, generation={here.data_generation}");
        visit [->:HasSession:->] else {
            disengage;
        }
    }

    can inspect_session with Session entry {
        if here.active && here.durable_ack {
            self.committed_sessions += 1;
            print(f"session {here.session_id}: durable ack confirmed");
        } else {
            print(f"session {here.session_id}: retained for retry");
        }
    }
}

walker PublicationAudit {
    has failed_lanes: int = 0;

    can start with Root entry {
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect_account with Account entry {
        visit [->:Publishes:->] else {
            disengage;
        }
    }

    can inspect_snapshot with Snapshot entry {
        print(f"snapshot generation={here.observed_generation}, state={here.state}");
        visit [->:HasLane:->] else {
            disengage;
        }
    }

    can inspect_lane with Lane entry {
        if here.complete {
            print(f"lane {here.lane_name}: complete");
        } else {
            self.failed_lanes += 1;
            print(f"lane {here.lane_name}: failed; snapshot stays error");
        }
    }
}

with entry {
    account = Account(
        account_id="acct-01",
        recorder_state="active",
        data_generation=42
    );

    committed = Session(
        session_id="session-01",
        title="active source",
        durable_ack=True
    );

    pending = Session(
        session_id="session-02",
        title="pending retry",
        durable_ack=False
    );

    snapshot = Snapshot(
        title="latest complete root",
        state="error",
        observed_generation=41
    );

    quota = Lane(
        lane_name="quota",
        complete=True
    );

    thread = Lane(
        lane_name="thread",
        available=False,
        complete=False
    );

    root +>:Owns:+> account;
    account +>:HasSession:+> committed;
    account +>:HasSession:+> pending;
    account +>:Publishes:+> snapshot;
    snapshot +>:HasLane:+> quota;
    snapshot +>:HasLane:+> thread;

    root spawn RecorderAudit();
    root spawn PublicationAudit();
}

"""Discussion reply tree: nested comments modeled as nodes connected by a
typed ReplyTo edge, walked by a walker which reproduces the depth-first
descent that the original recursive ingestion did.

The Kaggle ingestion in nvidia-kaggle hand-rolled a recursion over
`comments[].replies[]` and flattened the tree into a list of
`DiscussionComment` objects, losing parent/child links. Here the
hierarchy is the graph itself: each reply carries a typed `ReplyTo`
edge back to its parent, and a walker descends that edge, tracking
depth so the tree can be reconstructed.
"""

node Comment {
    has body: str = "";
    has author: str = "";
    has depth: int = 0;
}

edge ReplyTo {
    has ordinal: int = 0;
}

node DiscussionTopic {
    has title: str = "";
}

walker IngestReplies {
    has total: int = 0;
    has max_depth: int = 0;
    has nested_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can ingest with DiscussionTopic entry {
        visit [->:ReplyTo:->];
    }

    can record with Comment entry {
        self.total += 1;
        label = "top-level" if here.depth == 0 else "reply";
        if here.depth > 0 {
            self.nested_count += 1;
        }
        if here.depth > self.max_depth {
            self.max_depth = here.depth;
        }
        print(
            f"  [depth={here.depth}] {label} by {here.author}: "
            f"{here.body}"
        );
        visit [->:ReplyTo:->];
    }
}

with entry {
    topic = DiscussionTopic(title="Home Credit Default Risk #60061");
    root ++> topic;

    top = Comment(body="Has anyone tried blending XGBoost with LightGBM?",
                  author="alice",
                  depth=0);
    topic +>:ReplyTo(ordinal=0):+> top;

    r1 = Comment(body="Yes, blend weights 0.6 / 0.4 worked best.",
                 author="bob",
                 depth=1);
    top +>:ReplyTo(ordinal=0):+> r1;

    r1a = Comment(body="Did you tune per-fold or global?",
                  author="carol",
                  depth=2);
    r1 +>:ReplyTo(ordinal=0):+> r1a;

    r1b = Comment(body="Global, with a small grid over [0.3, 0.7].",
                  author="bob",
                  depth=2);
    r1 +>:ReplyTo(ordinal=1):+> r1b;

    r2 = Comment(body="Stacking beat blending for me by ~0.002 AUC.",
                 author="dave",
                 depth=1);
    top +>:ReplyTo(ordinal=1):+> r2;

    r2a = Comment(body="What meta-learner did you use?",
                  author="eve",
                  depth=2);
    r2 +>:ReplyTo(ordinal=0):+> r2a;

    Ingester = IngestReplies();
    topic spawn Ingester;

    print(
        f"Total comments: {Ingester.total}, "
        f"replies: {Ingester.nested_count}, "
        f"max depth: {Ingester.max_depth}"
    );
}

