"""Warehouse robot route planner.

Each cell carries a movement directive: either roll forward along the
floor (``ROLL``) or climb up to the mezzanine (``CLIMB``). The robot
walker enters at the entry cell, obeys the directive of every cell it
stands on, and logs the path of cell titles it traversed. Each cell
records its own visit log on entry, and a strict cap on steps prevents
an infinite loop if the plan accidentally loops back on itself.
"""

node Cell {
    has title: str = "";
    has directive: str = "ROLL";
    has log: list[str] = [];
}

walker Robot {
    has path: list[str] = [];
    has step_limit: int = 16;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can move with Cell entry {
        here.log.append(here.title);
        self.path.append(here.title);
        if len(self.path) >= self.step_limit {
            disengage;
        }
        if here.directive == "ROLL" {
            visit [-->] else {
                disengage;
            }
        } elif here.directive == "CLIMB" {
            visit [<--] else {
                disengage;
            }
        } else {
            disengage;
        }
    }
}

with entry {
    entry_cell = Cell(title="A1-loading", directive="ROLL");
    bay_2 = Cell(title="B2-bay", directive="ROLL");
    bay_3 = Cell(title="C3-bay", directive="CLIMB");
    mezzanine = Cell(title="M-mezzanine", directive="CLIMB");

    root ++> entry_cell ++> bay_2 ++> bay_3 ++> mezzanine;

    robot = Robot();
    root spawn robot;

    print("Robot path:", robot.path);
    print("Cell A1-loading log:", entry_cell.log);
    print("Cell B2-bay log:", bay_2.log);
    print("Cell C3-bay log:", bay_3.log);
    print("Cell M-mezzanine log:", mezzanine.log);
