    print(final.reports);
}

"""ADWF Foundation traceability graph: walk Owner-Intent -> Requirement -> Decision
and prove every requirement is grounded in a live decision and a live intent,
mirroring the fail-closed semantics the programme demands.

Entities are node archetypes; the durable links between them are typed edges;
a walker performs the cascade verification that the issue's hand-rolled
machinery used to do with parent_id recursion and id-keyed registries.
"""

node Intent {
    has title: str = "";
    has status: str = "DRAFT";
}

node Requirement {
    has title: str = "";
    has priority: int = 0;
    has verified: bool = False;
}

node Decision {
    has title: str = "";
    has rationale: str = "";
    has adopted: bool = False;
}

edge Drives {
    has weight: int = 1;
}

edge Satisfies {
    has confidence: float = 1.0;
}

edge Invalidates {
    has reason: str = "";
}

walker TraceAuditor {
    has findings: list[str] = [];
    has visited: list[str] = [];
    has broken: bool = False;

    can start with Root entry {
        print("ADWF Foundation trace audit begins");
        visit [-->];
    }

    can audit_intent with Intent entry {
        tag = f"I[{here.title}/{here.status}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        self.findings.append(f"intent '{here.title}' status={here.status}");
        if here.status != "LIVE" {
            self.broken = True;
            self.findings.append(f"  -> intent '{here.title}' is not LIVE");
        }
        visit [->:Drives:->] else { disengage; }
    }

    can audit_requirement with Requirement entry {
        tag = f"R[{here.title}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        line = f"requirement '{here.title}' pri={here.priority} verified={here.verified}";
        self.findings.append(line);
        if not here.verified {
            self.broken = True;
            self.findings.append(f"  -> requirement '{here.title}' not verified");
        }
        visit [->:Satisfies:->] else { disengage; }
    }

    can audit_decision with Decision entry {
        tag = f"D[{here.title}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        self.findings.append(f"decision '{here.title}' adopted={here.adopted}");
        if not here.adopted {
            self.broken = True;
            self.findings.append(f"  -> decision '{here.title}' not adopted");
        }
        visit [->:Invalidates:->] else { disengage; }
    }
}

with entry {
    i_lifecycle = Intent(title="ConsumerLifecycle", status="LIVE");
    i_trace = Intent(title="DecisionTraceability", status="LIVE");
    i_stale = Intent(title="StaleDiscovery", status="DRAFT");

    r_lifecycle = Requirement(title="RecoverOrDetach", priority=1, verified=True);
    r_evidence = Requirement(title="RealConsumerEvidence", priority=2, verified=True);
    r_trace = Requirement(title="GraphAppendOnly", priority=1, verified=True);
    r_unverified = Requirement(title="AdversarialAudit", priority=0, verified=False);

    d_merge = Decision(title="AdoptFailClosed", rationale="no live evidence -> no claim", adopted=True);
    d_skip = Decision(title="SkipAdversarialGate", rationale="premature", adopted=False);
    d_invalidate = Decision(title="InvalidateStaleDiscovery", rationale="superseded by v1.8", adopted=True);

    root ++> i_lifecycle
        ++> i_trace
        ++> i_stale
        ++> r_lifecycle
        ++> r_evidence
        ++> r_trace
        ++> r_unverified
        ++> d_merge
        ++> d_skip
        ++> d_invalidate;

    i_lifecycle +>:Drives(weight=3):+> r_lifecycle;
    i_lifecycle +>:Drives(weight=2):+> r_evidence;
    i_trace +>:Drives(weight=4):+> r_trace;
    i_stale +>:Drives(weight=1):+> r_unverified;

    r_lifecycle +>:Satisfies(confidence=0.95):+> d_merge;
    r_evidence +>:Satisfies(confidence=0.80):+> d_merge;
    r_trace +>:Satisfies(confidence=0.90):+> d_merge;
    r_unverified +>:Satisfies(confidence=0.10):+> d_skip;

    d_merge +>:Invalidates(reason="dethroned by later audit policy"):+> d_skip;
    d_merge +>:Invalidates(reason="stale draft, no owner intent LIVE"):+> d_invalidate;

    auditor = TraceAuditor();
    root spawn auditor;

    print("--- trace report ---");
    for line in auditor.findings {
        print(line);
    }
    print("--- summary ---");
    verdict = "FAIL_CLOSED" if auditor.broken else "PASS";
    print(f"trace audit verdict: {verdict}");
    print(f"nodes inspected: {len(auditor.visited)}");
}

"""Build dependency graph: audit total build minutes, counting each task once even when diamonds cause multiple visits."""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

walker BuildAuditor {
    has audited: dict[str, bool] = {};
    has total: int = 0;
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        key = here.title;
        if self.audited.get(key, False) {
            visit [-->];
            disengage;
        }
        self.audited[key] = True;
        self.order.append(key);
        self.total += here.minutes;
        print(f"+{here.minutes}min -> {here.title} (running total {self.total}min)");
        visit [-->];
    }
}

with entry {
    # Diamond: utils is needed by both compile and pack, which both feed into ship.
    utils = Task(title="compile_utils", minutes=5);
    compile = Task(title="compile_src", minutes=20);
    pack = Task(title="pack_artifacts", minutes=10);
    ship = Task(title="ship_release", minutes=3);

    # The graph topology is the diamond itself:
    # root -> utils, utils -> compile, utils -> pack, compile -> ship, pack -> ship.
    root ++> utils;
    utils ++> compile;
    utils ++> pack;
    compile ++> ship;
    pack ++> ship;

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"\nAudit order: {auditor.order}");
    print(f"Total build minutes (each task counted once): {auditor.total}min");
}

"""Aurora release intelligence: invalidate dependent state and stop on cycles."""

node CacheEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cache_key: str = "";
    has fresh: bool = True;
}

node ContextSnapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has snapshot_key: str = "";
    has stale: bool = False;
    has conflicting_facts: bool = False;
}

node TemplateVersion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: int = 0;
    has active: bool = True;
    has rollback_target: str = "";
}

node RouterPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has route_name: str = "";
    has enabled: bool = True;
    has rollback_ready: bool = True;
}

edge DependsOn {
    has reason: str = "";
}

walker InvalidationSweep {
    has invalidated: int = 0;
    has seen_keys: list[str] = [];

    can start with Root entry {
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect_cache with CacheEntry entry {
        if here.cache_key in self.seen_keys {
            print(f"cycle detected at cache {here.cache_key}");
            disengage;
        }
        self.seen_keys.append(here.cache_key);
        here.fresh = False;
        here.available = False;
        self.invalidated = self.invalidated + 1;
        print(f"cache {here.cache_key} invalidated");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect_context with ContextSnapshot entry {
        if here.snapshot_key in self.seen_keys {
            print(f"cycle detected at context {here.snapshot_key}");
            disengage;
        }
        self.seen_keys.append(here.snapshot_key);
        here.stale = True;
        here.available = False;
        self.invalidated = self.invalidated + 1;
        if here.conflicting_facts {
            print(f"conflicting facts rejected for {here.snapshot_key}");
        }
        print(f"context {here.snapshot_key} marked stale");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect_template with TemplateVersion entry {
        if f"{here.version}" in self.seen_keys {
            print(f"cycle detected at template {here.version}");
            disengage;
        }
        self.seen_keys.append(f"{here.version}");
        here.active = False;
        here.available = False;
        self.invalidated = self.invalidated + 1;
        print(f"template v{here.version} rolled back to {here.rollback_target}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect_router with RouterPlan entry {
        if here.route_name in self.seen_keys {
            print(f"cycle detected at router {here.route_name}");
            disengage;
        }
        self.seen_keys.append(here.route_name);
        here.enabled = False;
        here.available = False;
        self.invalidated = self.invalidated + 1;
        print(f"router {here.route_name} disabled; safe fallback retained");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

with entry {
    cache = CacheEntry(title="response cache", cache_key="cache:answer");
    context = ContextSnapshot(
        title="release context",
        snapshot_key="ctx:42",
        conflicting_facts=True
    );
    template = TemplateVersion(
        title="prompt template",
        version=7,
        rollback_target="v6"
    );
    router = RouterPlan(
        title="adaptive router",
        route_name="router:adaptive"
    );

    root +>:DependsOn(reason="release inputs"):+> cache;
    cache +>:DependsOn(reason="cache depends on context"):+> context;
    context +>:DependsOn(reason="context selects template"):+> template;
    template +>:DependsOn(reason="template selects router"):+> router;
    router +>:DependsOn(reason="fault-injection cycle"):+> cache;

    root spawn InvalidationSweep();
}

"""Duplicate file detector: recursively scan directories, group files by content hash, and report savings."""

node Directory {
    has name: str = "";
    has path: str = "";
    has ignored: bool = False;
}

node File {
    has path: str = "";
    has content_hash: str = "";
    has size_bytes: int = 0;
}

edge Contains { }

walker DuplicateScanner {
    has files_scanned: int = 0;
    has savings_bytes: int = 0;
    has paths: list[str] = [];
    has hashes: list[str] = [];
    has sizes: list[int] = [];

    can start with Root entry {
        print("Scanning directory tree for duplicate content...");
        visit [->:Contains:->] else { disengage; };
    }

    can walk_directory with Directory entry {
        if here.ignored {
            print(f"Skipping ignored directory: {here.path}");
        } else {
            visit [->:Contains:->] else { disengage; };
        }
    }

    can hash_file with File entry {
        self.files_scanned += 1;
        self.paths.append(here.path);
        self.hashes.append(here.content_hash);
        self.sizes.append(here.size_bytes);
    }

    def finish_scan() {
        print(f"Scanning {self.files_scanned} files...");
        print("");
        group_num = 0;
        for (i, hash_a) in enumerate(self.hashes) {
            seen_before = False;
            for j in range(i) {
                if self.hashes[j] == hash_a {
                    seen_before = True;
                }
            }
            if seen_before {
                continue;
            }
            match_count = 0;
            for hash_b in self.hashes {
                if hash_a == hash_b {
                    match_count += 1;
                }
            }
            if match_count > 1 {
                group_num += 1;
                print(f"Duplicate Group #{group_num}");
                print("------------------");
                for (j, hash_b) in enumerate(self.hashes) {
                    if hash_a == hash_b {
                        print(self.paths[j]);
                    }
                }
                print("");
                extra_bytes = 0;
                keeper_size = 0;
                for (j, hash_b) in enumerate(self.hashes) {
                    if hash_a == hash_b {
                        extra_bytes += self.sizes[j];
                        if keeper_size == 0 {
                            keeper_size = self.sizes[j];
                        }
                    }
                }
                self.savings_bytes += extra_bytes - keeper_size;
            }
        }
        savings_mb = self.savings_bytes / (1024.0 * 1024.0);
        print(f"Potential storage savings: {savings_mb} MB");
        print("");
        print("Scan completed successfully.");
    }
}

with entry {
    project = Directory(name="project", path=".");
    assets = Directory(name="assets", path="assets");
    backup = Directory(name="backup", path="backup");
    data_dir = Directory(name="data", path="data");
    archive = Directory(name="archive", path="archive");
    src_dir = Directory(name="src", path="src");
    modules = Directory(name="node_modules", path="node_modules", ignored=True);

    logo_assets = File(path="assets/logo.png", content_hash="sha256:logo", size_bytes=524288);
    logo_backup = File(path="backup/logo.png", content_hash="sha256:logo", size_bytes=524288);
