"""VTX2.3 first Substrait -> SQLGlot -> governed PostgreSQL projection.

Models the bounded pipeline as a graph: a typed Substrait Plan recipe
with a DVT sidecar holds semantic authority; a Substrait-to-SQLGlot
mapper walks the recipe in dependency order and emits SQLGlot AST
nodes; a PostgreSQL dialect generator renders governed target SQL.
Diagnostics flag unsupported capabilities and mapping failures.
"""

edge HasRel {
    has rel_kind: str = "READ";
}

edge HasExpr {
    has expr_kind: str = "FIELD";
}

edge DependsOn {
    has field_name: str = "";
}

# ---------------------------------------------------------------------------
# Typed Substrait recipe (semantic authority). A ProjectRel carries
# expressions that depend on fields from a ReadRel. Cycle policy:
# project SQL is built bottom-up by the mapper walker.
# ---------------------------------------------------------------------------
node ReadRel {
    has table_name: str = "";
    has admitted: bool = True;
}

node FieldRef {
    has field_name: str = "";
}

node ProjectRel {
    has output_name: str = "";
    has expression: str = "";
    has admitted: bool = True;
}

# ---------------------------------------------------------------------------
# SQLGlot AST as target rendering representation (syntax only, no semantics).
# ---------------------------------------------------------------------------
node SqlGlotExpr {
    has sql_kind: str = "";
    has sql_text: str = "";
}

# ---------------------------------------------------------------------------
# Projection result: governed PostgreSQL SQL rendered from the SQLGlot AST.
# ---------------------------------------------------------------------------
node GovernedSql {
    has dialect: str = "postgresql";
    has body: str = "";
    has diagnostics: list[str] = [];
}

# ---------------------------------------------------------------------------
# Mapper walker: traverses the typed Substrait recipe and emits SQLGlot
# expressions in dependency order. Cycles are prevented by an explicit
# visited set on the walker (walker has-fields are observable state).
# ---------------------------------------------------------------------------
walker SubstraitToSqlGlot {
    has rendered: list[str] = [];
    has visited: list[str] = [];
    has diagnostics: list[str] = [];

    can start with Root entry {
        visit [->:HasRel:->];
    }

    can scan with ReadRel entry {
        if not here.admitted {
            self.rendered.append("-- unsupported ReadRel; skipping");
            self.diagnostics.append("unsupported ReadRel capability");
            disengage;
        }
        self.rendered.append(f"FROM {here.table_name}");
        visit [-->];
    }

    can resolve with FieldRef entry {
        self.rendered.append(here.field_name);
        disengage;
    }

    can project with ProjectRel entry {
        if not here.admitted {
            self.rendered.append(f"-- unadmitted projection {here.output_name}");
            self.diagnostics.append(f"unadmitted projection {here.output_name}");
            disengage;
        }
        marker = f"expr::{here.output_name}";
        if marker in self.visited {
            disengage;
        }
        self.visited.append(marker);
        visit [->:DependsOn:->];
        self.rendered.append(f"{here.output_name} := {here.expression}");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Renderer walker: walks the SQLGlot AST in source order and emits
# governed PostgreSQL. The dialect generator treats SQLGlot as the
# authoritative target rendering layer.
# ---------------------------------------------------------------------------
walker SqlGlotToPostgres {
    has lines: list[str] = [];
    has errors: list[str] = [];

    can start with Root entry {
        visit [->:HasExpr:->];
    }

    can emit with SqlGlotExpr entry {
        if here.sql_kind == "SELECT_STMT" {
            self.lines.append(here.sql_text);
        } elif here.sql_kind == "PROJECTION" {
            self.lines.append("  " + here.sql_text);
        } elif here.sql_kind == "FROM_CLAUSE" {
            self.lines.append(here.sql_text);
        }
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Recipe graph for the #2598 fixture:
#   ReadRel(customers)
#     -> ProjectRel(customer_name = upper(trim(field(name))))
#     -> ProjectRel(email        = field(email))
#     -> ProjectRel(country      = field(country))
# Each projection depends on its source FieldRef via DependsOn edges.
# ---------------------------------------------------------------------------
with entry {
    read = ReadRel(table_name="customers");

    f_name = FieldRef(field_name="name");
    f_email = FieldRef(field_name="email");
    f_country = FieldRef(field_name="country");

    p_name = ProjectRel(
        output_name="customer_name",
        expression="upper(trim(name))"
    );
    p_email = ProjectRel(
        output_name="email",
        expression="email"
    );
    p_country = ProjectRel(
        output_name="country",
        expression="country"
    );

    root ++> read;
    read +>:HasRel:+> p_name;
    read +>:HasRel:+> p_email;
    read +>:HasRel:+> p_country;
    p_name +>:DependsOn(field_name="name"):+> f_name;
    p_email +>:DependsOn(field_name="email"):+> f_email;
    p_country +>:DependsOn(field_name="country"):+> f_country;

    mapper = SubstraitToSqlGlot();
    read spawn mapper;

    sql_select = SqlGlotExpr(
        sql_kind="SELECT_STMT",
        sql_text="SELECT"
    );
    sql_from = SqlGlotExpr(
        sql_kind="FROM_CLAUSE",
        sql_text="FROM customers"
    );
    sql_proj1 = SqlGlotExpr(
        sql_kind="PROJECTION",
        sql_text="upper(trim(name)) AS customer_name,"
    );
    sql_proj2 = SqlGlotExpr(
        sql_kind="PROJECTION",
        sql_text="email AS email,"
    );
    sql_proj3 = SqlGlotExpr(
        sql_kind="PROJECTION",
        sql_text="country AS country"
    );

    root +>:HasExpr:+> sql_select;
    sql_select +>:HasExpr:+> sql_proj1;
    sql_select +>:HasExpr:+> sql_proj2;
    sql_select +>:HasExpr:+> sql_proj3;
    sql_select +>:HasExpr:+> sql_from;

    renderer = SqlGlotToPostgres();
    root spawn renderer;

    rendered_lines = renderer.lines;
    governed = GovernedSql(
        dialect="postgresql",
        body="\n".join(rendered_lines),
        diagnostics=mapper.diagnostics
    );

    print(f"--- governed PostgreSQL ({governed.dialect}) ---");
    print(governed.body);
    print("--- diagnostics ---");
    for d in governed.diagnostics {
        print(d);
    }
}

"""Package dependency identity resolution.

Models SwiftPM's module dependency identity problem: a dependency can
be referenced by an explicit name, a derived name (from a URL path),
or a registry identity depending on flags. A walker traverses the
dependency graph and resolves the canonical identity per dependency,
then flags ambiguous / conflicting identities.
"""

# Core entity archetypes --------------------------------------------------------

node Package {
    has url: str = "";
    has explicit_name: str = "";
    has registry_identity: str = "";
}

node Target {
    has name: str = "";
}

# Resolution policy captured as a flag bundle, attached to root.
node ResolverConfig {
    has use_registry_identity_for_scm: bool = False;
    has allow_name_override: bool = True;
}

# Typed edges -- the relationship carries meaning -------------------------------

edge DependsOn { }    # Target -> Package
edge Owns { }         # Package -> Target
edge ConfiguredBy { } # Root -> ResolverConfig

# Walker: resolve identities and report conflicts -------------------------------

walker IdentityResolver {
    has ambiguous: list = [];
    has resolved_count: int = 0;
    has config: ResolverConfig | None = None;

    can start with Root entry {
        visit [->:ConfiguredBy:->];
        visit [->:Owns:->];
    }

    can pick_config with ResolverConfig entry {
        self.config = here;
        visit [-->];
    }

    can walk_targets with Target entry {
        visit [->:DependsOn:->];
    }

    can resolve with Package entry {
        # Derive a name from URL path components when no explicit name is set.
        derived_name = here.url.rstrip("/").split("/")[-1].removesuffix(".git")
            if here.url else "";

        explicit = here.explicit_name;
        registry = here.registry_identity;
        derived = derived_name;

        # Apply flag-driven resolution policy.
        cfg = self.config;
        chosen = "";
        if cfg is not None and cfg.use_registry_identity_for_scm and registry {
            chosen = registry;
        } elif cfg is not None and cfg.allow_name_override and explicit {
            chosen = explicit;
        } else {
            chosen = derived;
        }

        # Detect ambiguity: more than one non-empty identity source.
        sources_list = [explicit, registry, derived];
        non_empty = [s for s in sources_list if s];
        distinct = list(set(non_empty));
        if len(distinct) > 1 {
            self.ambiguous.append(chosen);
        }
        self.resolved_count += 1;
        print(f"resolved: {chosen}  (explicit={explicit!r}, "
              f"registry={registry!r}, derived={derived!r})");
    }
}

# Walker: cascade invalidation when a Package node is "removed" ----------------
# Demonstrates the reachability / cascade-delete pattern that the issue
# complains about being hand-rolled across many computed-property helpers.

walker InvalidatePackage {
    has doomed_url: str = "";

    can start with Root entry {
        visit [->:Owns:->];
    }

    can find_targets with Target entry {
        visit [->:DependsOn:->];
    }

    can check_package with Package entry {
        if here.url == self.doomed_url {
            here.registry_identity = "";
            here.explicit_name = "";
            print(f"invalidated package at {here.url}");
            disengage;
        }
        visit [-->];
    }
}

# Demonstration ----------------------------------------------------------------

with entry {
    cfg = ResolverConfig(
        use_registry_identity_for_scm=True,
        allow_name_override=True
    );
    root +>:ConfiguredBy:+> cfg;

    # Two packages with overlapping but non-identical identity sources.
    pkg_a = Package(
        url="https://example.com/awesome.git",
        explicit_name="AwesomeLib",
        registry_identity="awesome.registry"
    );
    pkg_b = Package(
        url="https://example.com/utilities.git",
        explicit_name="",
        registry_identity="utilities.registry"
    );
    pkg_c = Package(
        url="https://example.com/legacy.git",
        explicit_name="Legacy",
        registry_identity=""
    );

    app_core = Target(name="AppCore");
    app_cli = Target(name="AppCLI");
    root +>:Owns:+> app_core;
    root +>:Owns:+> app_cli;

    app_core +>:DependsOn:+> pkg_a;
    app_core +>:DependsOn:+> pkg_b;
    app_cli +>:DependsOn:+> pkg_c;

    print("=== IdentityResolver walk ===");
    resolver = IdentityResolver(config=cfg);
    root spawn resolver;
    print(f"resolved={resolver.resolved_count}, "
          f"ambiguous={resolver.ambiguous}");

    print("=== InvalidatePackage walk (doomed_url=legacy) ===");
    inv = InvalidatePackage(doomed_url="https://example.com/legacy.git");
    root spawn inv;

    print("=== IdentityResolver walk after invalidation ===");
    resolver2 = IdentityResolver(config=cfg);
    root spawn resolver2;
    print(f"resolved={resolver2.resolved_count}, "
          f"ambiguous={resolver2.ambiguous}");
}

