"""Kitchen line health inspection.

Three stations (grill, fryer, cold prep) are visited by two walkers at once.
``Inspector`` flags any station whose temperature reading is above 40 C as a
violation, and ``Logger`` records every station visit. Both walkers traverse
the line in parallel so every station gets both checks.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Grill(Station) {
    has name: str = "grill";
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Fryer(Station) {
    has name: str = "fryer";
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node ColdPrep(Station) {
    has name: str = "cold prep";
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

walker Inspector {
    has violations: list[str] = [];

    can start with Root entry {
        print("Inspector beginning kitchen walkthrough");
        visit [-->];
    }

    can inspect with Station entry {
        if here.is_violation() {
            self.violations.append(f"{here.name} @ {here.temperature} C");
            print(f"[VIOLATION] {here.name} reading {here.temperature} C exceeds 40 C");
        } else {
            print(f"[OK] {here.name} reading {here.temperature} C");
        }
        visit [-->] else { disengage; }
    }
}

walker Logger {
    has log: list[str] = [];

    can start with Root entry {
        print("Logger beginning kitchen walkthrough");
        visit [-->];
    }

    can record with Station entry {
        self.log.append(here.name);
        print(f"[LOG] visited {here.name}");
        visit [-->] else { disengage; }
    }
}

with entry {
    grill = Grill(name="grill", temperature=180.0);
    fryer = Fryer(name="fryer", temperature=165.0);
    cold = ColdPrep(name="cold prep", temperature=4.0);
    root ++> grill ++> fryer ++> cold;

    inspector = Inspector();
    root spawn inspector;
    logger = Logger();
    root spawn logger;

    print(f"Violations flagged: {inspector.violations}");
    print(f"Visit log: {logger.log}");
}

