"""Coverage-evidence sandbox: stale hash-lock and invalid pnpm flag cascade blocks approval."""

edge PipelineStage {
    has order: int = 0;
}

edge Reviews {
}

node PullRequest {
    has repo: str = "";
    has number: int = 0;
    has head_sha: str = "";
}

node Sandbox {
    has job_name: str = "";
    has decision: str = "PENDING";
    has failure_count: int = 0;
}

node PythonEnv {
    has hash_locked: bool = True;
    has stale_lock: bool = False;
    has missing_asyncpg: bool = False;
    has missing_psycopg2: bool = False;
    has status: str = "OK";
}

node PnpmEnv {
    has frozen_lockfile: bool = True;
    has trust_lockfile_flag: bool = False;
    has install_ok: bool = True;
    has status: str = "OK";
}

node EvidenceCheck {
    has title: str = "";
    has domain: str = "";
    has status: str = "PENDING";
    has detail: str = "";
}

walker CoverageEvidenceRunner {
    has failure_count: int = 0;
    has install_blocked: bool = False;
    has job_opened: bool = False;

    can start with Root entry {
        print("Measure test and docstring evidence");
        visit [-->];
    }

    can review_pr with PullRequest entry {
        print(
            f"LineageWeave PR #{here.number} @ {here.head_sha[:8]} "
            f"({here.repo})"
        );
        visit [->:Reviews:->] else { visit [-->]; };
    }

    can open_job with Sandbox entry {
        if self.job_opened {
            decision_label = "FAIL" if self.failure_count > 0 else "PASS";
            here.decision = decision_label;
            here.failure_count = self.failure_count;
            approval_msg = (
                "REQUEST_CHANGES"
                if self.failure_count > 0
                else "APPROVE"
            );
            print(f"Coverage Decision: {here.decision}");
            print(f"Failure count: {here.failure_count}");
            print(f"OpenCode: {approval_msg}");
            disengage;
        }
        self.job_opened = True;
        print(f"Sandbox job: {here.job_name}");
        visit [->:PipelineStage:->] else { disengage; };
    }

    can run_python_install with PythonEnv entry {
        if here.stale_lock {
            here.status = "FAIL";
            self.failure_count += 1;
            print(
                "FAIL: Python test collection — "
                "39/39 test files fail to import"
            );
            if here.missing_asyncpg {
                print("  ModuleNotFoundError: No module named 'asyncpg'");
            }
            if here.missing_psycopg2 {
                print("  ModuleNotFoundError: No module named 'psycopg2'");
            }
        } else {
            here.status = "PASS";
            print("PASS: Python hash-pinned requirements satisfied");
        }
        visit [->:PipelineStage:->] else { disengage; };
    }

    can run_pnpm_install with PnpmEnv entry {
        if here.trust_lockfile_flag {
            here.status = "FAIL";
            here.install_ok = False;
            self.install_blocked = True;
            self.failure_count += 1;
            print("FAIL: Unknown option: 'trust-lockfile'");
        } else {
            here.status = "PASS";
            print("PASS: pnpm install --frozen-lockfile succeeded");
        }
        visit [->:PipelineStage:->] else { disengage; };
    }

    can measure with EvidenceCheck entry {
        if self.install_blocked and here.domain == "js" {
            here.status = "FAIL";
            self.failure_count += 1;
            here.detail = "cascading upstream install failure";
            print(f"FAIL: {here.title} — {here.detail}");
        } else {
            here.status = "PASS";
            print(f"PASS: {here.title}");
        }
        visit [->:PipelineStage:->] else { disengage; };
    }
}

with entry {
    pr = PullRequest(
        repo="LineageWeave",
        number=417,
        head_sha="91b7e1cd914442e61e322620f194d1ba9da48567",
    );
    sandbox = Sandbox(job_name="coverage-evidence");
    py_env = PythonEnv(
        hash_locked=True,
        stale_lock=True,
        missing_asyncpg=True,
        missing_psycopg2=True,
    );
    pnpm_env = PnpmEnv(frozen_lockfile=True, trust_lockfile_flag=True);
    js_coverage = EvidenceCheck(
        title="JS/TS test coverage",
        domain="js",
    );
    js_threshold = EvidenceCheck(
        title="JS/TS coverage threshold",
        domain="js",
    );

    root ++> pr;
    pr +>:Reviews:+> sandbox;
    sandbox +>:PipelineStage(order=1):+> py_env;
    py_env +>:PipelineStage(order=2):+> pnpm_env;
    pnpm_env +>:PipelineStage(order=3):+> js_coverage;
    js_coverage +>:PipelineStage(order=4):+> js_threshold;
    js_threshold +>:PipelineStage(order=5):+> sandbox;

    root spawn CoverageEvidenceRunner();
}
