"""Order auditor: invalid orders are skipped, fraud orders halt the walk.

Demonstrates the two flavors of early return used together:
- A guard ``return`` from the ability skips the current order without
  aborting traversal of later ones (the walker simply does not ``visit``
  forward from it).
- ``disengage`` halts the walker immediately so no further orders
  are visited.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;

    can start with Root entry {
        print("Starting order audit...");
        visit [-->] else { disengage; }
    }

    can review with Order entry {
        # Fraud: halt the entire walk right here.
        if here.fraud {
            print(f"[HALT] fraud flagged on '{here.title}' -- audit aborted");
            disengage;
        }

        # Invalid: skip this order, but keep walking later ones.
        if not here.valid {
            print(f"[SKIP] '{here.title}' is invalid -- continuing audit");
            visit [-->] else { disengage; };
            return;
        }

        # Valid order: record it and keep walking.
        self.audited += 1;
        print(f"[OK]   '{here.title}' amount={here.amount:.2f} audited=#{self.audited}");
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Order(title="ORD-001", amount=120.50)
        ++> Order(title="ORD-002", amount=75.00, valid=False)
        ++> Order(title="ORD-003", amount=300.00)
        ++> Order(title="ORD-004", amount=45.25)
        ++> Order(title="ORD-005", amount=999.99, fraud=True)
        ++> Order(title="ORD-006", amount=60.00);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"Audit complete. Orders reviewed: {auditor.audited}");
}

"""Airflow ECS instance: model OOM cross-contamination across co-resident tasks.

The instance has a small fixed RAM budget (~3.7GiB usable). Four ECS tasks
(scheduler, triggerer, dag-processor, api-server) each reserve a cgroup
memory limit, summing to ~2.5GiB. When any task spikes past its limit the
kernel hard-kills it. Without swap, that pressure spills across to
unrelated tasks on the same host. A sweeper walker audits every task's
blast-radius and flags the ones that would OOM-kill the whole instance
if they breached their slice.
"""

node Task {
    has name: str = "";
    has memory_mib: int = 0;
    has oom_kills: int = 0;
}

node Instance {
    has name: str = "";
    has usable_mib: int = 0;
    has reserved_mib: int = 0;
    has swap_mib: int = 0;
}

edge HostedOn { }
edge Blast { has severity: int = 0; }

walker PressureSweep {
    can start with Root entry {
        visit [->:HostedOn:->];
    }

    can scan_instance with Instance entry {
        slack = here.usable_mib - here.reserved_mib;
        mode = "degraded (swap absorbs)" if here.swap_mib > 0 else "hard-killed";
        print(f"[{here.name}] usable={here.usable_mib}MiB reserved={here.reserved_mib}MiB "
              f"slack={slack}MiB swap={here.swap_mib}MiB -> {mode}");
        visit [->:HostedOn:->];
    }

    def blast_sum() -> int {
        total = 0;
        for (_, e) in [->:Blast:->] {
            total = total + e.severity;
        }
        return total;
    }

    can scan_task with Task entry {
        total = self.blast_sum();
        risk = "HIGH" if total > 3 else "ok";
        print(f"  task {here.name} mem={here.memory_mib}MiB oom_kills={here.oom_kills} blast_sum={total} risk={risk}");
        visit [->:Blast:->];
    }
}

with entry {
    inst = Instance(name="t3.medium", usable_mib=3700, reserved_mib=2500, swap_mib=0);

    scheduler = Task(name="scheduler", memory_mib=900, oom_kills=5);
    triggerer = Task(name="triggerer", memory_mib=400, oom_kills=0);
    dag_proc = Task(name="dag-processor", memory_mib=500, oom_kills=0);
    api = Task(name="api-server", memory_mib=700, oom_kills=3);

    inst +>:HostedOn:+> scheduler;
    inst +>:HostedOn:+> triggerer;
    inst +>:HostedOn:+> dag_proc;
    inst +>:HostedOn:+> api;

    scheduler +>:Blast(severity=2):+> api;
    scheduler +>:Blast(severity=1):+> triggerer;
    api +>:Blast(severity=1):+> dag_proc;

    print("=== baseline: no swap, hard-kill cascades across tasks ===");
    root spawn PressureSweep();

    print("\n=== after adding 4GiB swap: spike degrades to swapping, not kill ===");
    inst.swap_mib = 4096;
    root spawn PressureSweep();
}

"""Source-aware release pipeline with typed dependencies and guarded traversal."""

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_id: str = "";
    has approved: bool = False;
    has license_name: str = "";
}

node LockedInput {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has input_hash: str = "";
    has source_date: str = "";
    has locked: bool = False;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has payload_hash: str = "";
    has deterministic: bool = False;
    has synthetic: bool = False;
    has secret_leaked: bool = False;
}

node Release {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has release_id: str = "";
    has published: bool = False;
    has last_known_good: bool = False;
    has payload_hash: str = "";
}

edge SourceInput {
    has ordinal: int = 0;
}

edge InputArtifact {
    has transform: str = "";
}

edge ArtifactRelease {
    has partition: str = "";
}

walker PipelineAuditor {
    has steps: int = 0;
    has max_steps: int = 12;

    can inspect_record with Source | LockedInput | Artifact | Release entry {
        print(f"record {here.title} ({here.year})");
    }

    can start with Root entry {
        print("auditing locked inputs and published artifacts");
        self.steps += 1;
        visit [-->] else {
            disengage;
        }
    }

    can inspect_source with Source entry {
        self.steps += 1;
        if here.approved {
            print(f"source {here.source_id} approved under {here.license_name}");
        } else {
            print(f"source {here.source_id} rejected");
        }
        if self.steps >= self.max_steps {
            print("cycle guard: traversal depth limit reached");
            disengage;
        } else {
            visit [->:SourceInput:->] else {
                disengage;
            }
        }
    }

    can inspect_input with LockedInput entry {
        self.steps += 1;
        if here.locked {
            print(f"locked input {here.input_hash} dated {here.source_date}");
        } else {
            print(f"refresh failed for {here.title}; existing release remains untouched");
        }
        if self.steps >= self.max_steps {
            print("cycle guard: traversal depth limit reached");
            disengage;
        } else {
            visit [->:InputArtifact:->] else {
                disengage;
            }
        }
    }

    can inspect_artifact with Artifact entry {
        self.steps += 1;
        if here.deterministic {
            if here.synthetic {
                print(f"artifact {here.title} rejected: synthetic record");
            } else {
                if here.secret_leaked {
                    print(f"artifact {here.title} rejected: secret detected");
                } else {
                    print(f"artifact {here.payload_hash} is deterministic and valid");
                }
            }
        } else {
            print(f"artifact {here.title} rejected: nondeterministic transformation");
        }
        if self.steps >= self.max_steps {
            print("cycle guard: traversal depth limit reached");
            disengage;
        } else {
            visit [->:ArtifactRelease:->] else {
                disengage;
            }
        }
    }

    can inspect_release with Release entry {
        self.steps += 1;
        if here.last_known_good {
            print(f"published release {here.release_id} is last-known-good");
        } else {
            print(f"candidate release {here.release_id} was not published");
        }
        disengage;
    }
}

with entry {
    source = Source(
        title="OpenStreetMap",
        year=2025,
