"""Cbranch-style repository graph with guarded commit-history auditing."""

node Repository {
    has name: str = "";
    has busy: bool = False;
}

node Branch {
    has name: str = "";
    has current: bool = False;
    has protected: bool = False;
    has enabled: bool = True;
}

node Commit {
    has hash: str = "";
    has message: str = "";
    has author: str = "";
    has archived: bool = False;
}

node Tag {
    has name: str = "";
    has protected: bool = False;
    has enabled: bool = True;
}

edge Contains {
    has role: str = "";
}

edge PointsTo {
    has reason: str = "";
}

edge Parent {
    has ordinal: int = 0;
}

walker HistoryAuditor {
    has seen_hashes: list[str] = [];
    has commit_count: int = 0;
    has reference_count: int = 0;
    has revisit_count: int = 0;
    has cycle_guard_triggered: bool = False;
    has blocked: bool = False;

    can start with Root entry {
        print("Auditing cbranch repository graph");
        visit [-->] else {
            disengage;
        }
    }

    can audit_repository with Repository entry {
        print(f"Repository: {here.name}");
        if here.busy {
            self.blocked = True;
            print("Repository is busy; audit blocked");
            disengage;
        } else {
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can audit_reference with Branch | Tag entry {
        self.reference_count += 1;
        print(f"Reference discovered: {here}");
        visit [->:PointsTo:->] else {
            disengage;
        }
    }

    can audit_commit with Commit entry {
        if here.hash in self.seen_hashes {
            self.revisit_count += 1;
            self.cycle_guard_triggered = True;
            print(f"Cycle guard stopped revisit of {here.hash}");
        } else {
            self.seen_hashes.append(here.hash);
            self.commit_count += 1;
            print(f"Commit: {here.hash} - {here.message}");
            visit [->:Parent:->] else {
                disengage;
            }
        }
    }
}

with entry {
    repository = Repository(name="cbranch", busy=False);
    main = Branch(name="main", current=True, protected=True);
    feature = Branch(name="feature/context-menu");
    tag = Tag(name="v1.0");

    first = Commit(hash="a1", message="Initial UI", author="Ada");
    second = Commit(hash="b2", message="Add revision rows", author="Bea");
    tip = Commit(hash="c3", message="Add right-click actions", author="Cal");
    feature_tip = Commit(hash="d4", message="Add branch actions", author="Dee");

    root +>:Contains(role="repository"):+> repository;
    repository +>:Contains(role="branch"):+> main;
    repository +>:Contains(role="branch"):+> feature;
    repository +>:Contains(role="tag"):+> tag;

    main +>:PointsTo(reason="branch tip"):+> tip;
    feature +>:PointsTo(reason="branch tip"):+> feature_tip;
    tag +>:PointsTo(reason="tag target"):+> tip;

    tip +>:Parent(ordinal=1):+> second;
    second +>:Parent(ordinal=1):+> first;
    first +>:Parent(ordinal=1):+> second;
    feature_tip +>:Parent(ordinal=1):+> tip;

    root spawn HistoryAuditor();
}

