"""Task difficulty as shortest reachable program length.

Models the wandering-light issue: a task is a start state, an end state,
and a sampled ordered sequence of function calls.  The difficulty of a
task is the length of the SHORTEST ordered subsequence of the sampled
program that still connects start -> end under the available functions.
Sampled length and verified shortest length are tracked separately, so a
maintainer can compare them.

Walkers:
  * ``ShortestPath`` performs BFS from the start state over the
    ``Applies`` typed edge, tracks visited states (cycle policy from
    source: explicit guard set), and reports the shortest distance to
    the end state.
  * ``CycleHunter`` revisits states along the sampled program and flags
    any no-op or cycle step (issue diagnostics: "revisit a state" and
    "contain a no-op step").
"""

node State {
    has label: str = "";
    has reachable: bool = True;
}

# A typed edge meaning "function f transforms source into target".
edge Applies {
    has func_name: str = "";
}

# A typed edge meaning "this sampled step lives at position idx in a program".
edge Step {
    has idx: int = 0;
    has func_name: str = "";
}

walker ShortestPath {
    has target: str = "";
    has max_depth: int = 64;
    has distance: int = -1;
    has seen: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can search with State entry {
        # Cycle policy (probe-verified: walkers have no built-in dedupe).
        if here.label in self.seen {
            disengage;
        }
        self.seen.append(here.label);

        if here.label == self.target {
            if self.distance == -1 or self.seen.__len__() - 1 < self.distance {
                self.distance = self.seen.__len__() - 1;
            }
            disengage;
        }

        if self.seen.__len__() - 1 >= self.max_depth {
            disengage;
        }

        visit [->:Applies:->];
    }
}

walker CycleHunter {
    has target: str = "";
    has revists: list[int] = [];
    has no_ops: list[int] = [];
    has visited_labels: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can audit with State entry {
        # Detect no-op: a function from a state to itself.
        neighbors = [->:Applies:->];
        if len(neighbors) == 0 {
            self.no_ops.append(0);
        }
        # Detect revisits.
        if here.label in self.visited_labels {
            self.revists.append(0);
        }
        self.visited_labels.append(here.label);
        visit [->:Step:->];
    }
}

with entry {
    # --- Build a small state graph ---
    # States: S0 -> S1 -> S2 -> S3 (the chain).
    s0 = State(label="S0");
    s1 = State(label="S1");
    s2 = State(label="S2");
    s3 = State(label="S3");
    root ++> s0;
    s0 +>:Applies(func_name="inc"):+> s1;
    s1 +>:Applies(func_name="double"):+> s2;
    s2 +>:Applies(func_name="inc"):+> s3;

    # --- Demo 1: shortest path from S0 to S3 ---
    sp = ShortestPath(target="S3", max_depth=10);
    s0 spawn sp;
    print(f"[ShortestPath] S0 -> S3 verified distance: {sp.distance}");

    # --- Demo 2: a sampled program that contains a no-op (S1 -> S1)
    # and a revisit (S2 appears twice).  The verified difficulty
    # drops to 3 (the shortest chain S0->S1->S2->S3) while the
    # sampled length stays 5.
    # Chain the sampled program as typed Step edges off s0.
    step_a = State(label="S0");
    step_b = State(label="S1");
    step_c = State(label="S1");
    step_d = State(label="S2");
    step_e = State(label="S3");
    s0 +>:Step(idx=0, func_name="inc"):+> step_a;
    s0 +>:Step(idx=1, func_name="inc"):+> step_b;
    s0 +>:Step(idx=2, func_name="inc"):+> step_c;
    s0 +>:Step(idx=3, func_name="double"):+> step_d;
    s0 +>:Step(idx=4, func_name="inc"):+> step_e;

    sampled_length = 5;
    sp2 = ShortestPath(target="S3", max_depth=10);
    s0 spawn sp2;
    verified_length = sp2.distance if sp2.distance >= 0 else 0;
    print(
        f"[VerifyDifficulty] sampled_length={sampled_length}, "
        f"verified_length={verified_length}"
    );

    # --- Demo 3: cycle hunter flags the no-op step.
    ch = CycleHunter(target="S3");
    s0 spawn ch;
    print(
        f"[CycleHunter] revists={ch.revists}, no_ops={ch.no_ops}"
    );
}

"""Watch invalidation gap: declared dependency manifest changes outside the
imported module graph.

Models the Phase-A failure mode of ``smc watch``: a cheap fingerprint is
built only over the source ``Imports`` edges actually walked, while declared
``Depends`` relationships carry their own governing manifests. A declared
dependency's manifest can therefore change without the watch fingerprint
moving, and the declared-dependency cache is never reset.

We model:

  Module            -- a source module (the import graph)
  DeclaredDep       -- a declared dependency of an entry package
  EntryPackage      -- the watched package
  Manifest          -- a governing manifest content blob (typed field)

Edges carry the relationship type:

  Imports    -- source-import edge walked by the fingerprint
  Depends    -- declared-dependency edge (NOT walked by the fingerprint)
  GovernedBy -- module -> its nearest governing manifest

The ``CheapFingerprint`` walker mirrors the narrow behavior: it follows
``Imports`` + ``GovernedBy`` and only touches manifests reachable that way.
A dependent manifest change outside the imported graph is invisible to it.

The ``DeclaredAudit`` walker mirrors the broader behavior: it follows the
declared ``Depends`` edge type and folds every transitively declared
manifest, exposing the trust/provenance gap.
"""

node Module {
    has name: str = "";
    has source: str = "";
}

node DeclaredDep {
    has name: str = "";
    has kind: str = "runtime";
}

node EntryPackage {
    has name: str = "";
}

node Manifest {
    has owner: str = "";
    has content: str = "";
}

# Source-import edge: walked by the cheap fingerprint.
edge Imports {
    has line: int = 0;
}

# Declared-dependency edge: NOT walked by the cheap fingerprint (gap).
edge Depends {
    has kind: str = "runtime";
}

# Module / dependency -> its nearest governing manifest.
edge GovernedBy { }


# -- Cheap fingerprint walker (the narrow, buggy signal) ---------------------
walker CheapFingerprint {
    has visited: list[str] = [];
    has manifests_seen: list[str] = [];
    has fp: str = "";

    can start with Root entry {
        visit [->:Imports:->];
    }

    can walk_imports with Module entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            self.fp = self.fp + f"M[{here.name}]";
            visit [->:GovernedBy:->];
            visit [->:Imports:->];
        } else {
            disengage;
        }
    }

    can fold_manifest with Manifest entry {
        self.manifests_seen.append(here.owner);
        self.fp = self.fp + f"G[{here.owner}={here.content}]";
    }
}


# -- Declared-audit walker (the broader trust/provenance surface) ------------
walker DeclaredAudit {
    has visited: list[str] = [];
    has declared_seen: list[str] = [];
    has surface: str = "";

    can start with Root entry {
        visit [->:Depends:->];
    }

    can walk_declared with DeclaredDep | Module entry {
        key = f"D[{here.name}]" if isinstance(here, DeclaredDep) else f"M[{here.name}]";
        if key not in self.visited {
            self.visited.append(key);
            self.declared_seen.append(here.name);
            self.surface = self.surface + key + " ";
            visit [->:GovernedBy:->];
            visit [->:Depends:->];
        } else {
            disengage;
        }
    }

    can fold_manifest with Manifest entry {
        self.surface = self.surface + f"G[{here.owner}={here.content}] ";
    }
}


# -- A single walker that runs BOTH passes and reports the gap ---------------
walker WatchInvalidator {
    has fp: str = "";
    has admitted_cache: str = "VALID";

    can start with Root entry {
        cheap = CheapFingerprint();
        root spawn cheap;
        self.fp = cheap.fp;

        audit = DeclaredAudit();
        root spawn audit;
        declared_surface = audit.declared_seen;

        cheap_owners = cheap.manifests_seen;
        missing: list[str] = [];
        for owner in declared_surface {
            if owner not in cheap_owners {
                missing.append(owner);
            }
        }

        if len(missing) > 0 {
            self.admitted_cache = "STALE";
            print(f"[GAP] cheap fp={self.fp!r} unchanged; "
                  f"declared manifests not folded: {missing}; "
                  f"admission cache left {self.admitted_cache}");
        } else {
            print(f"[OK] cheap fp={self.fp!r} covers all declared "
                  f"manifests ({cheap_owners})");
        }
        disengage;
    }
}


# -- Demo wiring -------------------------------------------------------------
with entry {
    entry_manifest = Manifest(owner="entry", content="entry-v1");

    m_app = Module(name="app", source="use core; use util;");
    m_core = Module(name="core", source="fn core() {}");
    m_util = Module(name="util", source="fn util() {}");

    dep_logger = DeclaredDep(name="logger", kind="runtime");
    dep_logger_manifest = Manifest(owner="logger", content="logger-v1");

    root +>:GovernedBy:+> entry_manifest;
    root ++> EntryPackage(name="svc");
    root +>:Imports(line=1):+> m_app;
    m_app +>:Imports(line=2):+> m_core;
    m_app +>:Imports(line=3):+> m_util;
    m_app +>:GovernedBy:+> Manifest(owner="app", content="app-v1");
    m_core +>:GovernedBy:+> Manifest(owner="core", content="core-v1");
    m_util +>:GovernedBy:+> Manifest(owner="util", content="util-v1");

    root +>:Depends(kind="runtime"):+> dep_logger;
    dep_logger +>:GovernedBy:+> dep_logger_manifest;

    dep_logger_manifest.content = "logger-v2";

    print("=== cheap fingerprint pass ===");
    cheap = CheapFingerprint();
    root spawn cheap;
    print(f"cheap fp folds {len(cheap.manifests_seen)} manifests: "
          f"{cheap.manifests_seen}");
    print(f"cheap fp = {cheap.fp!r}");

    print("=== declared-audit pass ===");
    audit = DeclaredAudit();
    root spawn audit;
    print(f"declared surface: {audit.declared_seen}");
    print(f"audit surface: {audit.surface!r}");

    print("=== combined invalidation view ===");
    root spawn WatchInvalidator();
}

