"""Maze solver: walk a depth-first path from entrance to exit through a grid of open cells.

The maze is modeled as a graph: walls are implicit (no edge), open cells are
``Cell`` nodes, and adjacency between cells is expressed as typed ``Open`` edges
on a unit grid. A ``Pathfinder`` walker drives depth-first traversal from the
entrance, recording the route on its ``trail`` field, and reports the path when
it reaches the exit.
"""

node Cell {
    has row: int = 0;
    has col: int = 0;
    has is_exit: bool = False;
}

edge Open {
    has direction: str = "";
}

walker Pathfinder {
    has trail: list[str] = [];
    has found: bool = False;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can probe with Cell entry {
        # Record this cell, depth-first.
        coord = f"({here.row},{here.col})";
        self.trail.append(coord);
        self.seen.append(coord);

        # Reached the exit — emit the route and stop.
        if here.is_exit {
            self.found = True;
            print("Path to exit:");
            for step in self.trail {
                print(f"  {step}");
            }
            disengage;
        }

        # Depth-first: push deeper before backing up. Only walk cells we
        # haven't visited yet (cycle guard) and that aren't the exit yet.
        deeper = [here ->:Open:->];
        for n in deeper {
            ntag = f"({n.row},{n.col})";
            if ntag not in self.seen and not self.found {
                visit n;
            }
        }
    }
}

with entry {
    # Build a 4x4 maze of open cells. The layout below leaves a few
    # walls (no edge between neighbors) so the solver has to navigate.
    c00 = Cell(row=0, col=0);
    c01 = Cell(row=0, col=1);
    c02 = Cell(row=0, col=2);
    c03 = Cell(row=0, col=3, is_exit=True);

    c10 = Cell(row=1, col=0);
    c11 = Cell(row=1, col=1);
    c12 = Cell(row=1, col=2);
    c13 = Cell(row=1, col=3);

    c20 = Cell(row=2, col=0);
    c21 = Cell(row=2, col=1);
    c22 = Cell(row=2, col=2);
    c23 = Cell(row=2, col=3);

    c30 = Cell(row=3, col=0);
    c31 = Cell(row=3, col=1);
    c32 = Cell(row=3, col=2);
    c33 = Cell(row=3, col=3);

    # Row 0: open across (entrance at 00, exit at 03).
    c00 +>:Open(direction="E"):+> c01;
    c01 +>:Open(direction="E"):+> c02;
    c02 +>:Open(direction="E"):+> c03;

    # Drop down on the left and a corridor along the middle.
    c00 +>:Open(direction="S"):+> c10;
    c10 +>:Open(direction="S"):+> c20;
    c20 +>:Open(direction="E"):+> c21;
    c21 +>:Open(direction="E"):+> c22;
    c22 +>:Open(direction="N"):+> c12;
    c12 +>:Open(direction="E"):+> c13;
    c13 +>:Open(direction="S"):+> c23;
    c23 +>:Open(direction="W"):+> c22;

    # Right column up to the exit.
    c03 +>:Open(direction="S"):+> c13;

    # A few extra open cells (dead ends) to make DFS meaningful.
    c10 +>:Open(direction="E"):+> c11;
    c11 +>:Open(direction="E"):+> c12;
    c20 +>:Open(direction="S"):+> c30;
    c30 +>:Open(direction="E"):+> c31;
    c31 +>:Open(direction="E"):+> c32;
    c32 +>:Open(direction="N"):+> c22;

    # Hang the whole maze off root and spawn the solver at the entrance.
    root ++> c00;
    root spawn Pathfinder();
}

"""Safely audit VEST-like formula data with guarded denominators and linear traversal."""

node Profile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has axis_flux: float = 0.0;
    has boundary_flux: float = 0.0;
    has volume_total: float = 0.0;
    has weighted_total: float = 0.0;
    has central_value: float = 0.0;
    has rho_numerator: float = 0.0;
    has rho_denominator: float = 0.0;
    has normalized_boundary: float = 0.0;
    has normalization_valid: bool = True;
    has volume_average: float = 0.0;
    has volume_average_valid: bool = True;
    has peaking_factor: float = 0.0;
    has peaking_valid: bool = True;
    has rho_n: float = 0.0;
    has rho_valid: bool = True;
}

node Sample {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has psi_n: float = 0.0;
    has qpsi_n: float = 0.0;
}

edge HasSample { }
edge NextSample { }

walker FormulaAuditor {
    has previous_psi: float = 0.0;
    has previous_qpsi: float = 0.0;
    has cumulative_integral: float = 0.0;
    has sample_count: int = 0;
    has steps: int = 0;
    has max_steps: int = 64;
    has seen_titles: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Profile entry {
        normalization_denominator = here.boundary_flux - here.axis_flux;
        if normalization_denominator == 0.0 {
            here.normalization_valid = False;
            here.normalized_boundary = 0.0;
            print(f"[WARN] {here.title}: normalization denominator vanished");
        } else {
            here.normalization_valid = True;
            here.normalized_boundary =
                (here.boundary_flux - here.axis_flux)
                / normalization_denominator;
            print(f"{here.title}: normalized boundary = "
                  f"{here.normalized_boundary}");
        }

        if here.volume_total == 0.0 {
            here.volume_average_valid = False;
            here.volume_average = 0.0;
            here.peaking_valid = False;
            here.peaking_factor = 0.0;
            print(f"[WARN] {here.title}: volume denominator vanished");
            print(f"[WARN] {here.title}: peaking-factor denominator unavailable");
        } else {
            here.volume_average = here.weighted_total / here.volume_total;
            here.volume_average_valid = True;
            if here.volume_average == 0.0 {
                here.peaking_valid = False;
                here.peaking_factor = 0.0;
                print(f"[WARN] {here.title}: peaking-factor denominator vanished");
            } else {
                here.peaking_valid = True;
                here.peaking_factor =
                    here.central_value / here.volume_average;
                print(f"{here.title}: peaking factor = "
                      f"{here.peaking_factor}");
            }
        }

        if here.rho_denominator == 0.0 {
            here.rho_valid = False;
            here.rho_n = 0.0;
            print(f"[WARN] {here.title}: rhoN denominator vanished");
        } else {
            rho_ratio = here.rho_numerator / here.rho_denominator;
            if rho_ratio < 0.0 {
                here.rho_valid = False;
                here.rho_n = 0.0;
                print(f"[WARN] {here.title}: rhoN ratio is negative");
            } else {
                here.rho_valid = True;
                here.rho_n = rho_ratio ** 0.5;
                print(f"{here.title}: rhoN = {here.rho_n}");
            }
        }

        self.previous_psi = 0.0;
        self.previous_qpsi = 0.0;
        self.cumulative_integral = 0.0;
        self.sample_count = 0;
        self.steps = 0;
        self.seen_titles = [];
        visit [->:HasSample:->] else { disengage; }
    }

    can integrate with Sample entry {
        if here.title in self.seen_titles {
            print(f"[WARN] cycle detected at sample {here.title}; walk stopped");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.steps += 1;

            if self.steps > self.max_steps {
                print(f"[WARN] sample walk exceeded {self.max_steps} steps");
                disengage;
            } else {
                if self.sample_count > 0 {
                    trapezoid =
                        (here.psi_n - self.previous_psi)
                        * (here.qpsi_n + self.previous_qpsi)
                        / 2.0;
                    self.cumulative_integral += trapezoid;
                }

                self.previous_psi = here.psi_n;
                self.previous_qpsi = here.qpsi_n;
                self.sample_count += 1;

                print(f"sample {here.title}: cumulative integral = "
                      f"{self.cumulative_integral}");
                visit [->:NextSample:->] else {
                    print(f"{here.title}: cumulative integration complete");
                    disengage;
                }
            }
        }
    }
}

with entry {
    profile = Profile(
        title="degenerate VEST slice",
        year=2024,
        axis_flux=2.0,
        boundary_flux=2.0,
        volume_total=0.0,
        weighted_total=0.0,
        central_value=1.0,
        rho_numerator=-1.0,
        rho_denominator=0.0
    );

    first = Sample(title="psi-0", year=0, psi_n=0.0, qpsi_n=2.0);
    middle = Sample(title="psi-1", year=1, psi_n=0.5, qpsi_n=3.0);
    last = Sample(title="psi-2", year=2, psi_n=1.0, qpsi_n=4.0);

    root ++> profile;
    profile +>:HasSample:+> first;
    first +>:NextSample:+> middle;
    middle +>:NextSample:+> last;
    last +>:NextSample:+> first;

    root spawn FormulaAuditor();
}

