"""GlucoPilot H6 — ADR evidence collection for graph traversal cost.

Models the recurring complaint that hand-rolled recursive graph walks
(parent_id chains, cascade invalidation, dependency ordering) get
re-implemented whenever the data shape shifts.  The demo measures,
in pure-Jac terms, how a walker pays for the traversal:

  * `Measurement` node carries the metric the issue requires
    (volume, depth, latency, maintenance burden, demand).
  * `Signals` are raw observed values attached via a typed edge.
  * `EvidenceWalker` walks the chain once to accumulate the metrics
    and reports a single exit verdict: "stay relational" vs
    "trigger graph DB review".

Cycle policy is explicit (the source recursion would loop forever on
a cyclic parent chain, just like `visit [-->]` on a cycle) — a guard
set bounds the walk.
"""

node Measurement {
    has title: str = "";
    has value: float = 0.0;
    has threshold: float = 0.0;
}

node Verdict {
    has label: str = "";
    has rationale: str = "";
}

edge Signal {
    has weight: float = 1.0;
}

edge DependsOn {
    has order: int = 0;
}

walker EvidenceWalker {
    has budget: int = 64;
    has depth_seen: int = 0;
    has volume_total: float = 0.0;
    has demand_total: float = 0.0;
    has triggers: int = 0;
    has verdict_label: str = "stay-relational";
    has verdict_rationale: str = "";
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can accumulate with Measurement entry {
        if here.title in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.title);
        }
        self.volume_total += here.value;
        if here.title == "demand" {
            self.demand_total += here.value;
        }
        if here.value > here.threshold {
            self.triggers += 1;
        }
        if here.title == "depth" and here.value > self.depth_seen {
            self.depth_seen = int(here.value);
        }
        visit [-->];
    }

    can finalize with Verdict entry {
        label = "review-graph-db" if self.triggers >= 3 else "stay-relational";
        reason = (
            f"triggers={self.triggers} volume={self.volume_total} "
            f"depth={self.depth_seen} demand={self.demand_total}"
        );
        here.label = label;
        here.rationale = reason;
        self.verdict_label = label;
        self.verdict_rationale = reason;
    }
}

with entry {
    # Five measurements the ADR must cite, threshold = the bar at
    # which the metric becomes a "trigger" for re-evaluating the
    # storage layer.
    m_vol   = Measurement(title="volume",   value=128.0, threshold=100.0);
    m_depth = Measurement(title="depth",    value=5.0,   threshold=6.0);
    m_lat   = Measurement(title="latency",  value=42.0,  threshold=50.0);
    m_maint = Measurement(title="maintenance", value=180.0, threshold=150.0);
    m_demand= Measurement(title="demand",   value=12.0,  threshold=10.0);

    # A verdict sink the walker writes into at the end of the chain.
    v = Verdict();

    # Chain the measurements through typed `DependsOn` edges so the
    # walker has a non-trivial path to walk.  Typed `Signal` edges
    # carry the weight between parent and child so the relationship
    # has meaning, not just adjacency.
    root +>:DependsOn(order=1):+> m_vol
          +>:DependsOn(order=2):+> m_depth
          +>:DependsOn(order=3):+> m_lat
          +>:DependsOn(order=4):+> m_maint
          +>:DependsOn(order=5):+> m_demand
          +>:DependsOn(order=6):+> v;

    # Add a weighted signal edge so the typed-edge machinery is real.
    m_vol +>:Signal(weight=2.5):+> m_depth;

    auditor = EvidenceWalker(budget=64);
    root spawn auditor;

    print(f"verdict={auditor.verdict_label}");
    print(f"rationale={auditor.verdict_rationale}");
    print(f"stored={v.label} :: {v.rationale}");
}

