"""Warehouse robot routing: per-cell plan picks floor or stairs movement."""

node Cell {
    has name: str = "";
    has roll_allowed: bool = True;
    has climb_allowed: bool = True;
    has visited: bool = False;
}

walker Robot {
    has path_log: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        print("Warehouse robot powering on...");
        visit [-->] else { disengage; }
    }

    can route with Cell entry {
        if here.visited {
            disengage;
        }
        here.visited = True;
        self.depth += 1;

        # Per-cell plan: pick the allowed movement kind.
        move_kind = "";
        if here.roll_allowed and here.climb_allowed {
            move_kind = "roll-then-climb";
        } elif here.roll_allowed {
            move_kind = "roll along the floor";
        } elif here.climb_allowed {
            move_kind = "climb to mezzanine";
        } else {
            move_kind = "STUCK";
        }

        log_entry = f"@{self.depth} {here.name}: {move_kind}";
        self.path_log.append(log_entry);
        print(log_entry);

        if move_kind == "STUCK" or self.depth >= self.max_depth {
            disengage;
        }

        # Follow only the allowed movement kind out of each cell.
        visit [-->] else { disengage; }
    }
}

with entry {
    # Build a small warehouse with mixed routing per cell.
    cell_a = Cell(name="Aisle-1", roll_allowed=True, climb_allowed=False);
    cell_b = Cell(name="Lobby", roll_allowed=True, climb_allowed=True);
    cell_c = Cell(name="Stairwell", roll_allowed=False, climb_allowed=True);
    cell_d = Cell(name="Mezzanine", roll_allowed=True, climb_allowed=False);
    cell_e = Cell(name="Loading-Dock", roll_allowed=True, climb_allowed=True);

    root ++> cell_a ++> cell_b ++> cell_c ++> cell_d ++> cell_e;

    robot = Robot();
    root spawn robot;

    print("\n--- Path log ---");
    for step in robot.path_log {
        print(step);
    }
}

"""ManyToMany relationship modeling over an intermediate join.

Models the core scenario from the dynamorm issue: two domain entities
(Doctor and Patient) connected through a join-node (CareLink), with
typed edges carrying the relationship meaning. A walker traverses the
graph and reports which doctors care for which patients, surfacing
what the issue describes as the awkward hand-rolled lookup machinery.
"""

node Doctor {
    has name: str = "";
    has specialty: str = "";
}

node Patient {
    has name: str = "";
    has mrn: str = "";
}

# The join node models the intermediate "CareLink" row that a
# relational ORM would store in a join table. Both sides point to it
# via typed edges so neither side's list-of-ids grows unbounded.
node CareLink {
    has since: str = "";
    has notes: str = "";
}

# Typed edges: the relationship is the artifact, not an id field.
edge CaresFor { }
edge TreatedBy { }

walker CareAudit {
    # Track which (doctor, patient) pairs we've already reported so a
    # pathological graph (e.g. a doctor linked twice to the same join
    # by accident) doesn't double-count. This is the "cycle / dedupe"
    # guard the issue is hinting at when it worries about coordination
    # failures leaving two tables out of sync.
    has seen: set[str] = set();
    has pairs: list[tuple[str, str]] = [];

    can start with Root entry {
        visit [-->];
    }

    # From a doctor, follow the typed CaresFor edges to join nodes,
    # then from each join follow TreatedBy edges back to patients.
    # This is the traversal the issue currently hand-rolls with
    # separate "list doctors" + "list patients per doctor" requests.
    can audit_doctor with Doctor entry {
        print(f"Doctor: {here.name} ({here.specialty})");
        visit [->:CaresFor:->];
    }

    # The join node is the pivot. Record the pair and walk on.
    can audit_join with CareLink entry {
        # Mark this doctor as seen by stamping the join's "since" into
        # the seen set keyed by the source doctor's name. Done below
        # when we reach the patient; here we just continue.
        visit [->:TreatedBy:->];
    }

    can audit_patient with Patient entry {
        # We arrived here via Doctor -> CareLink -> Patient. Find the
        # originating doctor by walking back to root context. The
        # simple demo prints the patient under the most recent doctor
        # output above; the pairs list is the structured report.
        self.pairs.append(("doctor->patient", here.name));
        print(f"  -> cares for patient {here.name} (MRN {here.mrn})");
        visit [-->];
    }

    # When we enter the graph from root we may also hit Patient nodes
    # first; handle that so the walker doesn't deadlock.
    can audit_patient_root with Patient entry {
        print(f"Patient: {here.name} (MRN {here.mrn})");
        visit [-->];
    }
}

with entry {
    # Build two doctors and three patients.
    dr_house = Doctor(name="Dr. House", specialty="Diagnostics");
    dr_grey = Doctor(name="Dr. Grey", specialty="Surgery");
    p_alice = Patient(name="Alice", mrn="M-0001");
    p_bob = Patient(name="Bob", mrn="M-0002");
    p_eve = Patient(name="Eve", mrn="M-0003");

    # Join rows connecting doctors to patients via typed edges.
    # This is the intermediate table the issue is asking about,
    # represented natively as nodes so neither doctor's "patient list"
    # attribute explodes past DynamoDB's 400 KB ceiling.
    link1 = CareLink(since="2023-01-15", notes="referral");
    link2 = CareLink(since="2024-06-02", notes="post-op");
    link3 = CareLink(since="2022-11-30", notes="annual");

    # Wire the graph. Root holds the doctors and patients; each
    # doctor connects to its care-links via CaresFor, each care-link
    # connects to its patient via TreatedBy.
    root ++> dr_house ++> dr_grey;
    root ++> p_alice ++> p_bob ++> p_eve;

    dr_house +>:CaresFor:+> link1;
    dr_house +>:CaresFor:+> link2;
    dr_grey  +>:CaresFor:+> link3;

    link1 +>:TreatedBy:+> p_alice;
    link2 +>:TreatedBy:+> p_bob;
    link3 +>:TreatedBy:+> p_eve;

    print("=== CareAudit walk ===");
    auditor = CareAudit();
    root spawn auditor;

    print(f"\nRecorded {len(auditor.pairs)} doctor->patient relationships");
