"""Tiny dungeon crawler: chain of room nodes, one holds the treasure.

The hunter walks the chain room by room, counting rooms seen, and
terminates the entire search the instant it steps into the vault —
rooms past the vault are never visited."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can search with Room entry {
        self.rooms_seen += 1;
        if here.has_treasure {
            print(f"Found treasure in {here.name} after {self.rooms_seen} rooms!");
