"""Session query: live-preferred indexed search over session transcripts.

Models the essential scenario from the chroxy issue #7309 — a linear
substring scan over conversation content is replaced with a typed-edge
walk over Session -> Turn relationships, with a live-preferred read so
a turn just appended is findable without waiting for an index rebuild.
"""

node Session {
    has title: str = "";
    has project: str = "";
    has provider: str = "";
    has started_at: int = 0;
}

node Turn {
    has role: str = "";
    has content: str = "";
    has at: int = 0;
}

edge OwnedBy { }
edge ForkOf { }
edge NextTurn { }

walker Indexer {
    has indexed: list = [];

    can start with Root entry {
        visit [->:OwnedBy:->];
    }

    can index_session with Session entry {
        self.indexed.append(("SESSION", here.title));
        visit [->:ForkOf:->];
        visit [->:NextTurn:->];
    }

    can index_turn with Turn entry {
        self.indexed.append(("TURN", here.role, here.content));
        visit [->:NextTurn:->];
    }
}

walker Query {
    has needle: str = "";
    has role_filter: str = "";
    has hits: list = [];

    can start with Root entry {
        visit [->:OwnedBy:->];
    }

    can scan_session with Session entry {
        visit [->:NextTurn:->];
    }

    can scan_turn with Turn entry {
        live_match = here.content.lower().find(self.needle.lower()) >= 0
            if here.content and self.needle else False;
        role_ok = (self.role_filter == "") or (here.role == self.role_filter);
        if live_match and role_ok {
            self.hits.append((here.role, here.content));
        }
        visit [->:NextTurn:->];
    }
}

walker LiveAppend {
    can append with Session entry {
        new_turn = Turn(role="user", content="just appended", at=9999);
        here +>:NextTurn:+> new_turn;
        print(f"appended live turn to {here.title}");
    }
}

with entry {
    main = Session(title="main", project="alpha", provider="openai", started_at=1);
    forked = Session(title="fork-A", project="alpha", provider="openai", started_at=2);
    root +>:OwnedBy:+> main;
    root +>:OwnedBy:+> forked;
    main +>:ForkOf:+> forked;

    t1 = Turn(role="user", content="search the corpus fast", at=10);
    t2 = Turn(role="assistant", content="use FTS5", at=11);
    t3 = Turn(role="user", content="needle in haystack", at=12);
    t4 = Turn(role="assistant", content="found the needle", at=13);
    main +>:NextTurn:+> t1 +>:NextTurn:+> t2 +>:NextTurn:+> t3 +>:NextTurn:+> t4;

    f1 = Turn(role="user", content="forked thread starts here", at=20);
    f2 = Turn(role="assistant", content="forked reply with needle", at=21);
    forked +>:NextTurn:+> f1 +>:NextTurn:+> f2;

    idx = Indexer();
    root spawn idx;
    print(f"indexed entries: {len(idx.indexed)}");

    q = Query(needle="needle", role_filter="");
    root spawn q;
    print(f"query hits before append: {q.hits}");

    main spawn LiveAppend();

    q2 = Query(needle="needle", role_filter="");
    root spawn q2;
    print(f"query hits after live append: {q2.hits}");
}

"""Runtime operations graph with settings, services, providers, and cycle guards."""

node RuntimeSetting {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has enabled: bool = True;
    has timeout_seconds: int = 30;
}

node Service {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has endpoint: str = "";
    has role: str = "";
    has maintenance: bool = False;
}

node Provider {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has fallback_model: str = "";
}

edge Configures {
    has key: str = "";
}

edge UsesProvider {
    has role: str = "";
}

edge FallsBackTo {
    has priority: int = 0;
}

walker OperationsAuditor {
    has depth: int = 0;
    has max_depth: int = 4;
    has blocked_requests: int = 0;
    has unhealthy_providers: int = 0;

    can start with Root entry {
        print("Operations audit started");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_setting with RuntimeSetting entry {
        setting_state = "enabled" if here.enabled else "disabled";
        print(f"setting {here.key}: {setting_state}, timeout={here.timeout_seconds}s");
        if self.depth < self.max_depth {
            self.depth = self.depth + 1;
            visit [->:Configures:->] else {
                disengage;
            }
        } else {
            print("depth limit reached while reading settings");
            disengage;
        }
    }

    can inspect_service with Service entry {
        service_state = "maintenance" if here.maintenance else "ready";
        print(f"service {here.title}: {service_state} at {here.endpoint}");
        if here.available == False {
            self.blocked_requests = self.blocked_requests + 1;
        }
        if self.depth < self.max_depth {
            self.depth = self.depth + 1;
            visit [->:UsesProvider:->] else {
                disengage;
            }
        } else {
            print("depth limit reached while checking service providers");
            disengage;
        }
    }

    can inspect_provider with Provider entry {
        provider_state = "UP" if here.available else "DOWN";
        print(f"provider {here.title}: {provider_state}, fallback={here.fallback_model}");
        if here.available == False {
            self.unhealthy_providers = self.unhealthy_providers + 1;
        }
        if self.depth < self.max_depth {
            self.depth = self.depth + 1;
            visit [->:FallsBackTo:->] else {
                print(f"provider {here.title} has no further fallback");
                disengage;
            }
        } else {
            print(f"cycle/depth guard stopped at provider {here.title}");
            disengage;
        }
    }
}

with entry {
    setting = RuntimeSetting(
        title="Runtime settings",
        key="provider_timeout",
        enabled=True,
        timeout_seconds=12
    );
    service = Service(
        title="Answer API",
        endpoint="/api/query",
        role="thinking",
        maintenance=False
    );
    primary = Provider(
        title="Primary LLM",
        kind="instant",
        fallback_model="backup-small",
        available=False
    );
    backup = Provider(
        title="Backup LLM",
        kind="instant",
        fallback_model="primary-model",
        available=True
    );

    root ++> setting;
    setting +>:Configures(key="provider_timeout"):+> service;
    service +>:UsesProvider(role="thinking"):+> primary;
    primary +>:FallsBackTo(priority=1):+> backup;
    backup +>:FallsBackTo(priority=2):+> primary;

    root spawn OperationsAuditor(max_depth=4);
}

"""Resolved workflow specs for canonicalized recipe input paths.

Models the WP-Codebox issue #1697: declared recipe mount paths
(``/wp-codebox-vendor``, ``/home/wpcom/public_html``) must be
canonicalized to runtime paths under ``/tmp/wp-codebox-inputs/...`` by a
single authoritative resolver before any runtime command executes.
The walker performs the resolver traversal and flags any executable arg
that still references a canonicalized declared mount target.
"""

# --- Entities ---------------------------------------------------------

node Recipe {
    has name: str = "";
    has declared_mounts: list[str] = [];
}

node ResolvedSpec {
    has original_args: dict[str, str] = {};
    has resolved_args: dict[str, str] = {};
    has has_unresolved: bool = False;
}

node RuntimeStep {
    has cmd: str = "";
    has args: dict[str, str] = {};
}

# --- Relationships (typed edges) --------------------------------------

edge OwnsMount {
    has declared_path: str = "";
}

edge ProducesSpec {
    has resolution_status: str = "ok";
}

edge ExecutesSpec { }

# --- Walker: the resolver ---------------------------------------------

walker ResolveWorkflow {
    has canonical_root: str = "/tmp/wp-codebox-inputs";

    # The walker accumulates one exit report.
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [->:OwnsMount:->];
    }

    # Walk every recipe the project owns.
    can catalog with Recipe entry {
        print(f"[recipe] {here.name} declared mounts: {here.declared_mounts}");
        visit [->:OwnsMount:->];
    }

    # Each declared mount produces a resolved spec node (one-shot).
    can resolve with Mount entry {
        canonical = f"{self.canonical_root}/{here.declared_path.strip('/')}";
        # Pretend the runtime cmd line still references the declared path
        # (the bug from #1696). The resolver catches it.
        original = {
            "cwd": here.declared_path,
            "autoload-file": f"{here.declared_path}/vendor/autoload.php",
        };
        resolved = {
            "cwd": canonical,
            "autoload-file": f"{canonical}/vendor/autoload.php",
        };
        # Two-phase mutation: build the spec node first, then attach it.
        spec = ResolvedSpec(
            original_args=original,
            resolved_args=resolved,
            has_unresolved=False,
        );
        # Guard: if any executable arg still references a canonicalized
        # declared target, the spec is flagged.
        for (key, value) in original.items() {
            if here.declared_path in value and "wp-codebox-inputs" not in value {
                spec.has_unresolved = True;
            }
        }
        status = "FAIL" if spec.has_unresolved else "OK";
        here +>:ProducesSpec(resolution_status=status):+> spec;
        # Run the runtime step once the spec is in place.
        here +>:ExecutesSpec:+> RuntimeStep(
            cmd="wordpress.phpunit",
            args=resolved,
        );
        self.report_lines.append(
            f"[resolve] {here.declared_path} -> {canonical} [{status}]"
        );
    }

    can audit with ResolvedSpec entry {
        if here.has_unresolved {
            print(f"[guard] UNRESOLVED canonical mount target in executable args: {here.original_args}");
        } else {
            print(f"[audit] resolved cleanly: {here.resolved_args}");
        }
        visit [-->];
    }

    can run with RuntimeStep entry {
        print(f"[runtime] exec {here.cmd} {here.args}");
        visit [-->];
    }

    can finish with Root entry {
        # Single exit report.
        print("--- resolver report ---");
        for line in self.report_lines {
            print(line);
        }
        print("--- end report ---");
    }
}

# --- Demonstration wiring -------------------------------------

# Mount archetype declared so typed edges resolve; carries declared path.
node Mount {
    has declared_path: str = "";
}

with entry {
    # Two recipes, each owning their declared mounts.
    vendor_recipe = Recipe(
        name="wp-codebox-vendor",
        declared_mounts=["/wp-codebox-vendor"],
    );
    public_recipe = Recipe(
        name="wpcom-public-html",
        declared_mounts=["/home/wpcom/public_html"],
    );
    root ++> vendor_recipe;
    root ++> public_recipe;

    # Wire declared mounts as typed OwnsMount edges off each recipe.
    vendor_recipe +>:OwnsMount(declared_path="/wp-codebox-vendor"):+> Mount(declared_path="/wp-codebox-vendor");
    public_recipe +>:OwnsMount(declared_path="/home/wpcom/public_html"):+> Mount(declared_path="/home/wpcom/public_html");

    # Spawn the resolver walker from the root.
    root spawn ResolveWorkflow();
}

