"""Recursively validate schema versions in nested exception payloads."""

node VersionedValue {
    has schema_version: int = 1;
    has path: str = "root";
    has depth: int = 0;
    has seen: bool = False;
}

node ExceptionPayload(VersionedValue) {
    has message: str = "";
}

node ExceptionGroup(VersionedValue) {
    has label: str = "";
}

edge Cause { }
edge Context { }
edge Group { }
edge Member {
    has index: int = 0;
}

walker VersionValidator {
    has minimum_version: int = 1;
    has maximum_version: int = 2;
    has max_depth: int = 4;
    has max_nodes: int = 32;
    has checked_count: int = 0;
    has issue_count: int = 0;
    has first_issue: str = "";

    can begin with Root entry {
        visit [-->];
    }

    can inspect with ExceptionPayload | ExceptionGroup entry {
        if here.seen {
            print(f"cycle detected at {here.path}");
            disengage;
        }

        here.seen = True;
        self.checked_count += 1;

        if self.checked_count > self.max_nodes {
            print(f"validation stopped: node limit {self.max_nodes} reached");
            disengage;
        }

        if here.depth > self.max_depth {
            print(f"validation stopped: depth limit {self.max_depth} reached at {here.path}");
            disengage;
        }

        if here.schema_version < self.minimum_version or here.schema_version > self.maximum_version {
            detail = f"{here.path}: unsupported schema version {here.schema_version}";
            self.issue_count += 1;

            if self.first_issue == "" {
                self.first_issue = detail;
            }

            print(f"INVALID {detail}");
        } else {
            print(f"valid {here.path}: schema version {here.schema_version}");
        }

        visit [-->];
    }

    can summarize with Root exit {
        if self.issue_count == 0 {
            print(f"validation passed for {self.checked_count} payload values");
        } else {
            print(f"validation found {self.issue_count} unsupported versions");
            print(f"first unsupported version: {self.first_issue}");
        }
    }
}

with entry {
    failing_root = ExceptionPayload(
        message="root",
        path="root",
        depth=0,
        schema_version=1
    );
    cause = ExceptionPayload(
        message="cause",
        path="cause",
        depth=1,
        schema_version=999
    );
    deep_cause = ExceptionPayload(
        message="deep cause",
        path="cause.cause",
        depth=2,
        schema_version=0
    );
    context = ExceptionPayload(
        message="context",
        path="context",
        depth=1,
        schema_version=2
    );
    deep_context = ExceptionPayload(
        message="deep context",
        path="context.context",
        depth=2,
        schema_version=999
    );
    group = ExceptionGroup(
        label="group",
        path="exceptions",
        depth=1,
        schema_version=1
    );
    member0 = ExceptionPayload(
        message="member zero",
        path="exceptions[0]",
        depth=2,
        schema_version=999
    );
    member0_cause = ExceptionPayload(
        message="member cause",
        path="exceptions[0].cause",
        depth=3,
        schema_version=0
    );
    member1 = ExceptionPayload(
        message="member one",
        path="exceptions[1]",
        depth=2,
        schema_version=1
    );

    supported_root = ExceptionPayload(
        message="supported root",
        path="supported",
        depth=0,
        schema_version=1
    );
    supported_cause = ExceptionPayload(
        message="supported cause",
        path="supported.cause",
        depth=1,
        schema_version=1
    );
    supported_group = ExceptionGroup(
        label="supported group",
        path="supported.exceptions",
        depth=1,
        schema_version=2
    );
    supported_member = ExceptionPayload(
        message="supported member",
        path="supported.exceptions[0]",
        depth=2,
        schema_version=1
    );

    root ++> failing_root;
    root ++> supported_root;

    failing_root +>:Cause:+> cause;
    cause +>:Cause:+> deep_cause;
    failing_root +>:Context:+> context;
    context +>:Context:+> deep_context;
    failing_root +>:Group:+> group;
