    supported_root +>:Cause:+> supported_cause;
    supported_root +>:Group:+> supported_group;
    supported_group +>:Member(index=0):+> supported_member;

    validator = VersionValidator(
        minimum_version=1,
        maximum_version=2,
        max_depth=4,
        max_nodes=32
    );
    root spawn validator;
}

