"""Per-TS top-up: re-run one tilt-series without recomputing the whole job.

Models the crboost_server issue where a tilt-series that fails one stage
(alignment) is silently dropped from downstream manifests, and only a
targeted re-run can bring it back. Two central entities:

  - JobNode: a stage in the pipeline (alignment, ctf, ...).
  - TiltSeries: a per-tilt-series record with status.

The job's `results.ok` set is the *emitted manifest* — downstream jobs
derive their inputs from it. A TS in `failed` is no longer a candidate;
the only way it returns to the chain is via a targeted top-up run on the
failing job. The walker below reproduces that flow.
"""

node TiltSeries {
    has name: str = "";
    has status: str = "pending";   # ok | failed | missing
}

node JobNode {
    has job_type: str = "";
    has exit_status: str = "SUCCESS";   # SUCCESS | FAILED
    has ok: list[str] = [];             # emitted manifest
    has failed: list[str] = [];         # failed but recorded
    has missing: list[str] = [];        # absent from manifest
}

edge RunsOn { has order: int = 0; }
edge Emits { }

walker TopUp {
    has target_ts: str = "";
    has recovered: bool = False;
    has visited_jobs: list[str] = [];

    can start with Root entry {
        print(f"=== Top-up requested for TS '{self.target_ts}' ===");
        visit [-->];
    }

    can plan with JobNode entry {
        self.visited_jobs.append(here.job_type);
        print(f"  visiting job '{here.job_type}' "
              f"(exit={here.exit_status}, "
              f"ok={here.ok}, failed={here.failed})");

        # Policy from drivers/ts_alignment.py: only a *total* wipeout
        # (nothing aligned) is fatal. Partial success is normal.
        if here.ok == [] and here.failed != [] {
            print(f"    FATAL: total wipeout at '{here.job_type}'; "
                  f"cannot top-up");
            disengage;
        }

        # Targeted re-run only fires when the TS is in `failed` here
        # — i.e. it was emitted as failing-but-recorded by this stage.
        # If it was silently dropped (not even in `failed`), the only
        # way to surface it is via this walker's pre-pass that re-runs
        # the upstream stage that still knows the TS name.
        if self.target_ts in here.failed {
            print(f"    [TOP-UP] re-aligning '{self.target_ts}' "
                  f"in job '{here.job_type}'");
            here.failed = [n for n in here.failed if n != self.target_ts];
            here.ok = here.ok + [self.target_ts];
            self.recovered = True;
            disengage;
        }

        # Dead-end: nothing left to follow for this branch.
        visit [->:RunsOn:->] else {
            disengage;
        }
    }
}

walker AuditManifest {
    has seen_ts: list[str] = [];

    can start with Root entry {
        print("=== Auditing emitted manifests ===");
        visit [-->];
    }

    can read with JobNode entry {
        print(f"  job '{here.job_type}' emits: {here.ok}");
        for ts_name in here.ok {
            self.seen_ts.append(ts_name);
        }
        visit [-->];
    }
}

with entry {
    # Build the chain: alignment (job004-like) -> ctf (job005-like).
    alignment = JobNode(
        job_type="tsAlignment",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4",
            "Position_1_5", "Position_1_6"],
        failed=["Position_1_3"],   # failed but recorded
        missing=[]
    );
    ctf = JobNode(
        job_type="tsCtf",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4",
            "Position_1_5", "Position_1_6"],
        failed=[],
        missing=[]   # Position_1_3 absent — silently dropped
    );

    root +>:RunsOn(order=1):+> alignment;
    alignment +>:RunsOn(order=2):+> ctf;

    # First, show the gap: Position_1_3 is missing from ctf's manifest.
    AuditManifest() spawn root;

    # Now perform the targeted top-up: re-run only Position_1_3.
    topup = TopUp(target_ts="Position_1_3");
    topup spawn root;

    print(f"recovered={topup.recovered}, "
          f"visited={topup.visited_jobs}");
    print(f"alignment.ok now = {alignment.ok}");
    print(f"ctf.ok still    = {ctf.ok}  (top-up must propagate downstream)");
}

"""Sparse-array backend contract: validate CSR/CSC inputs, audit backends, and reject silent densification."""

node PipelineStage {
    has name: str = "";

    def kind() -> str {
        return "stage";
    }
}

node SparseMatrix {
    has label: str = "";
    has format: str = "csr";
    has device: str = "cpu";
    has values_finite: bool = True;
    has canonical: bool = True;

    def format_ok() -> bool {
        return self.format == "csr" or self.format == "csc";
    }

    def valid_buffers() -> bool {
        return self.values_finite and self.canonical;
    }
}

node Backend(PipelineStage) {
    has version: str = "1.0";
    has accepts_csr: bool = True;
    has accepts_csc: bool = True;

    override def kind() -> str {
        return "backend";
    }
}

node Estimator(PipelineStage) {
    has sparse_capable: bool = False;

    override def kind() -> str {
        return "estimator";
    }
}

edge HostedOn {
    has validated: bool = False;
}

edge FitsWith {
    has approved: bool = False;
}

walker ContractAuditor {
    has rejections: int = 0;
    has approvals: int = 0;
    has active_label: str = "";
    has active_format: str = "";
    has active_device: str = "";

    can start with Root entry {
        print("=== Sparse contract audit v1.0 ===");
        visit [-->];
        print(f"=== Audit complete: {self.approvals} approved, {self.rejections} rejected ===");
    }

    can inspect with SparseMatrix entry {
        if not here.format_ok() {
            print(f"[REJECT] {here.label}: format '{here.format}' outside contract (CSR/CSC only)");
            self.rejections += 1;
            disengage;
        }
        if not here.valid_buffers() {
            detail = "non-finite values" if not here.values_finite else "non-canonical indices";
            print(f"[REJECT] {here.label}: {detail}");
            self.rejections += 1;
            disengage;
        }
        self.active_label = here.label;
        self.active_format = here.format;
        self.active_device = here.device;
        print(f"[CHECK] {here.label} ({here.format}, {here.device})");
        visit [->:HostedOn:->] else {
            print(f"[REJECT] {here.label}: no backend host — cannot proceed");
            self.rejections += 1;
            disengage;
        };
    }

    can announce with Backend | Estimator entry {
        print(f"  -> {here.kind()}: {here.name}");
    }

    can audit_backend with Backend entry {
        fmt_ok = here.accepts_csr if self.active_format == "csr" else here.accepts_csc;
        if not fmt_ok {
            print(f"[REJECT] {here.name} cannot host {self.active_format} without explicit conversion");
            self.rejections += 1;
            disengage;
        }
        if self.active_device == "cuda" and here.name == "SciPy" {
            print(f"[REJECT] {self.active_label}: cross-device CPU fallback blocked under device=cuda");
            self.rejections += 1;
            disengage;
        }
        if self.active_device == "cpu" and here.name == "CuPy" {
            print(f"[REJECT] {here.name}: no implicit GPU path for CPU-resident sparse data");
            self.rejections += 1;
            disengage;
        }
        print(f"[OK] {here.name} v{here.version} hosts {self.active_format} on {self.active_device}");
        visit [->:FitsWith:->] else {
            print(f"[REJECT] no estimator linked for {self.active_label} on {here.name}");
            self.rejections += 1;
            disengage;
        };
    }

    can verify_estimator with Estimator entry {
        if not here.sparse_capable {
            print(f"[REJECT] {here.name}: sparse input unsupported — silent densification forbidden");
            self.rejections += 1;
            disengage;
        }
        print(f"[APPROVED] {here.name} may fit {self.active_label} without densification");
        self.approvals += 1;
        disengage;
    }
}

walker CompatibilityReporter {
    has traced: int = 0;

    can begin with Estimator entry {
        if not here.sparse_capable {
            disengage;
        }
        print(f"[COMPAT] tracing sparse path for {here.name}");
        visit [<--] else {
            print(f"[COMPAT] {here.name}: no backend link");
            disengage;
        };
    }

    can trace_backend with Backend entry {
        print(f"  backend hop: {here.name} v{here.version}");
        visit [<--] else {
            print(f"  backend {here.name}: no sparse matrix attached");
            disengage;
        };
    }

    can trace_matrix with SparseMatrix entry {
        guard = "dense estimate blocked" if here.format_ok() else "format rejected";
        print(f"  matrix hop: {here.label} ({here.format}, {here.device}) — {guard}");
        self.traced += 1;
        disengage;
    }
}

with entry {
    scipy_ridge = Backend(name="SciPy", version="1.11", accepts_csr=True, accepts_csc=True);
    scipy_ols = Backend(name="SciPy", version="1.11", accepts_csr=True, accepts_csc=True);
    cupy_gpu = Backend(name="CuPy", version="12.0", accepts_csr=True, accepts_csc=True);
    torch_cpu = Backend(name="Torch", version="2.1", accepts_csr=True, accepts_csc=False);

    ridge = Estimator(name="Ridge", sparse_capable=True);
    lasso = Estimator(name="Lasso", sparse_capable=True);
    ols = Estimator(name="LinearRegression", sparse_capable=False);

    x_train = SparseMatrix(label="X_train", format="csr", device="cpu", canonical=True);
    x_fold = SparseMatrix(label="X_fold", format="csc", device="cuda", canonical=True);
    x_coo = SparseMatrix(label="X_coo", format="coo", device="cpu");
    x_ols = SparseMatrix(label="X_ols", format="csr", device="cpu", canonical=True);
    x_torch = SparseMatrix(label="X_torch", format="csc", device="cpu", canonical=True);

    root ++> x_train;
    x_train +>:HostedOn(validated=True):+> scipy_ridge;
    scipy_ridge +>:FitsWith:+> ridge;

    root ++> x_fold;
    x_fold +>:HostedOn(validated=True):+> cupy_gpu;
    cupy_gpu +>:FitsWith:+> lasso;

    root ++> x_coo;

    root ++> x_ols;
    x_ols +>:HostedOn:+> scipy_ols;
    scipy_ols +>:FitsWith:+> ols;

    root ++> x_torch;
    x_torch +>:HostedOn:+> torch_cpu;
    torch_cpu +>:FitsWith:+> ridge;

    root spawn ContractAuditor();
    ridge spawn CompatibilityReporter();
    lasso spawn CompatibilityReporter();
}

"""Eidetic engine lib suite SIGSEGV: doctor-render tests stall on deep async index-job stacks."""

node EEArtifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has crate_name: str = "eidetic-engine";
    has release_tag: str = "";
    has thread_stack_kb: int = 2048;
}

node LibTest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has module_path: str = "";
    has is_doctor_render: bool = False;
}

node AsyncRoutine {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has symbol: str = "";
    has depth: int = 0;
}

edge Runs { }
edge Spawns { }
edge TailCalls { }

walker LibSuiteAuditor {
    has stack_ceiling: int = 6;
    has passed: int = 0;
    has stall_count: int = 0;
    has segfault: bool = False;
    has frames_walked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can load_crate with EEArtifact entry {
        self.stack_ceiling = here.thread_stack_kb // 340;
        print(
            f"crate={here.crate_name} tag={here.release_tag} "
            f"thread_stack_kb={here.thread_stack_kb} ceiling={self.stack_ceiling}"
        );
        visit [->:Runs:->] else { disengage; }
    }

    can run_test with LibTest entry {
        if here.is_doctor_render {
            self.stall_count += 1;
            print(f"STALL {here.module_path}::{here.title}");
            visit [->:Spawns:->] else { visit [->:Runs:->] else { disengage; } }
        } else {
            if here.available {
                self.passed += 1;
                print(f"ok {here.module_path}::{here.title}");
            }
            visit [->:Runs:->] else { disengage; }
        }
    }

    can unwind_async with AsyncRoutine entry {
        self.frames_walked += 1;
        print(f"  frame depth={here.depth} {here.symbol}");
        if here.depth >= self.stack_ceiling {
            self.segfault = True;
            print(
                f"SIGSEGV signal=11 depth={here.depth} "
                f"ceiling={self.stack_ceiling} frames={self.frames_walked}"
            );
            disengage;
        }
        visit [->:TailCalls:->] else { disengage; }
    }
}

