"""Decommission an orphaned self-hosted CI runner.

Models the krolik cleanup from issue #32: a host node, a systemd unit,
and an actions-runner install. A walker walks the host -> unit -> runner
chain and decommissions the runner (deregister + directory delete) before
disabling and stopping the unit. Cycle policy is explicit: we track
visited hosts in a guard set so the walker cannot loop on a mis-wired
host graph.
"""

node Host {
    has hostname: str = "";
    has is_self_hosted: bool = True;
    has runner_dirs: list[str] = [];
    has units: list[str] = [];

    # Default no-op deprecation hooks; concrete hosts override.
    def decommission_unit(unit_name: str) -> None {
        return None;
    }

    def deregister_runner(dir_path: str) -> None {
        return None;
    }

    def delete_runner_dir(dir_path: str) -> None {
        return None;
    }
}

node LinuxHost(Host) {
    # Linux hosts can disable/stop systemd units.
    override def decommission_unit(unit_name: str) -> None {
        return None;
    }
}

# A systemd unit file; the runner depends on it being active.
node SystemdUnit {
    has unit_name: str = "";
    has enabled: bool = False;
    has active: bool = False;
}

# An actions-runner installation directory (config.sh + runner binaries).
node RunnerInstall {
    has install_path: str = "";
    has registered: bool = True;
}

# Typed edge: "this runner install is supervised by this systemd unit".
edge SupervisedBy {
    has since: str = "";
}

# Typed edge: "this unit lives on this host".
edge LivesOn {
    has since: str = "";
}

# Walker that walks host -> unit -> runner and tears the runner down,
# then disables the unit. Cycle-safe via an explicit guard set.
walker Decommissioner {
    has visited_hosts: set[str] = set();
    has decommissioned: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # A host may own multiple units. Visit each one (typed edge).
    can at_host with Host entry {
        # Cycle policy: if we've seen this host, skip — never loop.
        if here.hostname in self.visited_hosts {
            disengage;
        }
        self.visited_hosts.add(here.hostname);

        # Only self-hosted runners are candidates for cleanup.
        if not here.is_self_hosted {
            visit [<--];
        }

        visit [->:LivesOn:->];
    }

    # At a unit, tear down everything that depends on it, then disable it.
    can at_unit with SystemdUnit entry {
        # Cascade: walk to runners supervised by this unit first.
        visit [->:SupervisedBy:->];
    }

    # At a runner install: deregister, then delete the directory.
    can at_runner with RunnerInstall entry {
        # Find the host we're operating on by walking back to Root,
        # then ask it to deregister + delete the install dir.
        # We do the host work via a typed traversal back through
        # LivesOn edges. For demo purposes we just record and act:
        if here.registered {
            here.registered = False;
            self.decommissioned.append(here.install_path);
            print(f"  deregistered runner at {here.install_path}");
        }
        # Mark the directory as removed (no real fs ops in demo).
        print(f"  deleted install directory {here.install_path}");
    }

    # After cascading through runners, disable/stop the unit itself.
    can teardown_unit with SystemdUnit exit {
        if here.enabled {
            here.enabled = False;
            here.active = False;
            print(f"disabled --now {here.unit_name}");
        }
        visit [<--];
    }
}

with entry {
    # Build the graph: krolik -> unit -> runner install.
    krolik = LinuxHost(hostname="krolik", is_self_hosted=True);

    unit = SystemdUnit(
        unit_name="actions-runner-landing-kit.service",
        enabled=True,
        active=False
    );

    runner = RunnerInstall(
        install_path="~/actions-runner-landing-kit",
        registered=True
    );

    # Typed-edge wiring (relationship carries meaning).
    krolik +>:LivesOn(since="2024-01-15"):+> unit;
    unit +>:SupervisedBy(since="2024-01-15"):+> runner;

    # A second host wired into the graph to exercise the cycle guard.
    ci_host = Host(hostname="ci-vm-02", is_self_hosted=False);
    orphan_unit = SystemdUnit(
        unit_name="actions-runner-orphan.service",
        enabled=False,
        active=False
    );
    ci_host ++> orphan_unit;

    root ++> krolik ++> ci_host;

    print("Before decommission:");
    print(f"  krolik hosts unit '{unit.unit_name}' "
          f"(enabled={unit.enabled}, active={unit.active})");
    print(f"  runner at '{runner.install_path}' "
          f"(registered={runner.registered})");

    # Spawn the walker on root and let it cascade.
    root spawn Decommissioner();

    print("After decommission:");
    print(f"  krolik hosts unit '{unit.unit_name}' "
          f"(enabled={unit.enabled}, active={unit.active})");
    print(f"  runner at '{runner.install_path}' "
          f"(registered={runner.registered})");
}

