"""Adaptive renderer qualification graph with released contracts and cycle-safe scheduling."""

node Contract {
    has key: str = "";
    has released: bool = False;

    def limit() -> int {
        return 0;
    }
}

node CameraContract(Contract) {
    has motion_ceiling: int = 0;

    override def limit() -> int {
        return self.motion_ceiling;
    }
}

node PerformanceContract(Contract) {
    has pixel_ceiling: int = 0;

    override def limit() -> int {
        return self.pixel_ceiling;
    }
}

node PixelSchedule {
    has requested_pixels: int = 0;
    has fixed_budget_mib: int = 0;
    has adaptive_cap_mib: int = 128;
    has adaptive_enabled: bool = False;
    has effective_ceiling: int = 0;
    has history_invalidated: bool = False;
    has mode: str = "fixed";
}

node RenderScene {
    has name: str = "";
    has history_valid: bool = True;
}

edge SceneContract { }
edge ContractFlow { has relation: str = ""; }

walker AdaptiveScheduler {
    has seen: list[str] = [];
    has effective_ceiling: int = 2147483647;
    has contracts_ready: bool = True;
    has history_invalidated: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can qualify_scene with RenderScene entry {
        print(f"qualifying scene: {here.name}");
        if here.history_valid == False {
            self.history_invalidated = True;
        }
        visit [->:SceneContract:->] else { disengage; }
    }

    can consume_contract with CameraContract | PerformanceContract entry {
        if here.key in self.seen {
            print(f"cycle detected at contract {here.key}; stopping walk");
            disengage;
        }
        self.seen = self.seen + [here.key];
        if here.released {
            contract_limit = here.limit();
            if contract_limit < self.effective_ceiling {
                self.effective_ceiling = contract_limit;
            }
            print(f"consumed released contract {here.key}: ceiling {contract_limit}");
        }
        else {
            self.contracts_ready = False;
            self.history_invalidated = True;
            print(f"ignored unreleased contract {here.key}; history invalidated");
        }
        visit [->:ContractFlow:->] else { disengage; }
    }

    can schedule with PixelSchedule entry {
        here.history_invalidated = self.history_invalidated;
        if here.adaptive_enabled && self.contracts_ready {
            chosen_ceiling = self.effective_ceiling;
            if chosen_ceiling > here.adaptive_cap_mib {
                chosen_ceiling = here.adaptive_cap_mib;
            }
            if chosen_ceiling > here.requested_pixels {
                chosen_ceiling = here.requested_pixels;
            }
            here.effective_ceiling = chosen_ceiling;
            here.mode = "adaptive";
            print(f"adaptive schedule: {chosen_ceiling} MiB ceiling, history invalidated={here.history_invalidated}");
        }
        else {
            here.effective_ceiling = here.fixed_budget_mib;
            here.mode = "fixed";
            print(f"fixed schedule: {here.fixed_budget_mib} MiB, adaptive resources absent");
        }
        visit [->:ContractFlow:->] else { disengage; }
    }
}

with entry {
    scene = RenderScene(name="warehouse", history_valid=True);
    camera = CameraContract(key="camera-release-24", released=True, motion_ceiling=96);
    performance = PerformanceContract(key="performance-release-24", released=True, pixel_ceiling=160);
    schedule = PixelSchedule(requested_pixels=200, fixed_budget_mib=64, adaptive_enabled=True);

    root ++> scene;
    scene +>:SceneContract:+> camera;
    camera +>:ContractFlow(relation="camera before performance"):+> performance;
    performance +>:ContractFlow(relation="performance before scheduling"):+> schedule;
    schedule +>:ContractFlow(relation="qualification cycle probe"):+> camera;

    root spawn AdaptiveScheduler();
}

