"""Cyclic graph traversal: cycle-safe walker that mirrors the issue's repro.

Models the essential scenario from jac issue #8562: ``visit [-->]`` on a
graph with a cycle must NOT hang. We declare a tiny graph of two nodes
with a back-edge, then spawn a walker that keeps an explicit visited
set on the walker itself so each node is reported at most once. A
second walker that ``disengage``s on the first revisit demonstrates the
opt-in revisit policy.
"""

node Site {
    has tag: str = "";
    has alive: bool = True;
}

edge Link {
    has weight: int = 1;
}

walker CyclicVisitor {
    has visited: list[str] = [];

    can start with Root entry {
        print(f"begin traversal from root; visited starts as {self.visited}");
        visit [-->];
    }

    can scan with Site entry {
        if here.tag in self.visited {
            print(f"cycle guard fired: {here.tag} already seen, disengaging");
            disengage;
        }
        self.visited.append(here.tag);
        print(f"visiting site {here.tag} (alive={here.alive})");
        visit [-->] else {
            print("frontier empty; traversal ends cleanly");
            disengage;
        }
    }
}

walker CascadeInvalidator {
    has invalidated: list[str] = [];

    can start with Root entry {
        print("cascade invalidation begins");
        visit [-->];
    }

    can invalidate with Site entry {
        if not here.alive {
            print(f"{here.tag} already dead, disengage");
            disengage;
        }
        here.alive = False;
        self.invalidated.append(here.tag);
        print(f"invalidated site {here.tag}");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    a = Site(tag="A");
    b = Site(tag="B");
    root ++> a +>:Link(weight=1):+> b;
    b +>:Link(weight=2):+> a;

    print("--- CyclicVisitor on A<->B cycle ---");
    CyclicVisitor() spawn root;

    print("--- CascadeInvalidator on same cycle ---");
    c = Site(tag="C");
    d = Site(tag="D");
    root ++> c +>:Link:+> d;
    d +>:Link:+> c;
    CascadeInvalidator() spawn root;
}

