"""osu! stable issue #1370: Application.Idle handler direct self-recursion until stack overflow."""

node Application {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has file_version: str = "1.3.3.7";
    has build_stream: str = "Stable40";
}

node MessageLoop {
    has title: str = "ThreadContext";
    has year: int = 0;
    has available: bool = True;
    has frame_sync: str = "Unlimited";
    has pump_count: int = 0;
}

node IdleHandler {
    has title: str = "Application.Idle";
    has year: int = 0;
    has available: bool = True;
    has handler_addr: str = "zxfD3mJTKEx8P";
    has call_depth: int = 0;
    has crashed: bool = False;
}

edge RunsLoop { }
edge DispatchesIdle { }
edge SelfRecurses { }

walker IdleStorm {
    has stack_frames: int = 0;
    has stack_limit: int = 14;
    has overflowed: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can boot with Application entry {
        visit [->:RunsLoop:->] else {
            disengage;
        };
    }

    can pump with MessageLoop entry {
        here.pump_count += 1;
        visit [->:DispatchesIdle:->] else {
            disengage;
        };
    }

    can on_idle with IdleHandler entry {
        self.stack_frames += 1;
        here.call_depth += 1;
        if self.stack_frames >= self.stack_limit {
            here.crashed = True;
            self.overflowed = True;
            print(f"STATUS_STACK_OVERFLOW (0xc00000fd) at {here.handler_addr} "
                  f"after {self.stack_frames} identical frames");
            disengage;
        }
        print(f"Application.Idle -> {here.handler_addr} depth={here.call_depth}");
        visit [->:SelfRecurses:->] else {
            disengage;
        };
    }
}

with entry {
    app = Application(
        title="osu!",
        file_version="1.3.3.7",
        build_stream="Stable40"
    );
    loop = MessageLoop(title="RunMessageLoop", frame_sync="Unlimited");
    idle = IdleHandler(title="Idle", handler_addr="zxfD3mJTKEx8P");

    root ++> app;
    app +>:RunsLoop:+> loop;
    loop +>:DispatchesIdle:+> idle;
    idle +>:SelfRecurses:+> idle;

    storm = IdleStorm(stack_limit=12);
    root spawn storm;

    if storm.overflowed {
        print(f"Crash reproduced: {idle.call_depth} self-recursion frames on main UI thread");
    } else {
        print(f"Idle pump completed without overflow after {idle.call_depth} frames");
    }
}

