"""GraphVisualizer: per-step BFS/DFS traversal state over a graph.

Models the essential scenario from issue #6: a graph is built as node
archetypes connected by typed edges, and a walker performs the traversal
(BFS with a queue, DFS with a stack) while emitting a VisualizationFrame
per step capturing the visited set, frontier contents, current node, and
the edge just traversed.
"""

# ---------- Entities ----------

node GraphNode {
    has label: str = "";
}

node VisualizationFrame {
    has step: int = 0;
    has visited: list[str] = [];
    has frontier: list[str] = [];
    has current: str = "";
    has edge_taken: str = "";
}

# ---------- Relationships ----------

edge Adjacent { }

# ---------- Walkers ----------

walker GraphVisualizer {
    has mode: str = "BFS";
    has frames: list[VisualizationFrame] = [];
    has frontier: list[str] = [];
    has visited: list[str] = [];
    has last_edge: str = "";
    has last_dst: str = "";

    can start with Root entry {
        print(f"GraphVisualizer starting in {self.mode} mode");
        # Seed the walk at the spawned graph root's first neighbor.
        visit [->:Adjacent:->];
    }

    can snapshot with GraphNode entry {
        # Record the current node as a new frame and update walker state.
        self.last_dst = here.label;
        if here.label not in self.visited {
            self.visited.append(here.label);
        }
        if self.mode == "BFS" {
            if here.label not in self.frontier {
                self.frontier.append(here.label);
            }
        } else {
            if here.label not in self.frontier {
                self.frontier = [here.label] + self.frontier;
            }
        }
        self.frames.append(
            VisualizationFrame(
                step=len(self.frames),
                current=here.label,
                visited=list(self.visited),
                frontier=list(self.frontier),
                edge_taken=self.last_edge
            )
        );
        visit [->:Adjacent:->];
    }
}

walker Reachability {
    has order: list[str] = [];

    can start with Root entry {
        visit [->:Adjacent:->];
    }

    can reach with GraphNode entry {
        if here.label not in self.order {
            self.order.append(here.label);
        }
        visit [->:Adjacent:->];
    }
}

# ---------- Demonstration ----------

with entry {
    # Build a small graph: A - B - C, A - D, D - E.
    a = GraphNode(label="A");
    b = GraphNode(label="B");
    c = GraphNode(label="C");
    d = GraphNode(label="D");
    e = GraphNode(label="E");

    root ++> a;
    a +>:Adjacent:+> b;
    a +>:Adjacent:+> d;
    b +>:Adjacent:+> c;
    d +>:Adjacent:+> e;

    # ---- BFS demonstration ----
    bfs_viz = GraphVisualizer(mode="BFS");
    print("=== BFS traversal frames ===");
    a spawn bfs_viz;

    for f in bfs_viz.frames {
        print(
            f"step {f.step}: current={f.current} "
            f"visited={f.visited} frontier={f.frontier} "
            f"edge={f.edge_taken}"
        );
    }

    # ---- DFS demonstration on the same graph ----
    dfs_viz = GraphVisualizer(mode="DFS");
    print("=== DFS traversal frames ===");
    a spawn dfs_viz;

    for f in dfs_viz.frames {
        print(
            f"step {f.step}: current={f.current} "
            f"visited={f.visited} frontier={f.frontier} "
            f"edge={f.edge_taken}"
        );
    }

    # ---- Independent reachability runs for sanity ----
    bfs = Reachability();
    a spawn bfs;
    print(f"Reach order: {bfs.order}");
}

"""Mutual-recursion safe JSON schema derivation demo.

Models two user structs (A, B) that reference each other. A walker
walks the type graph collecting defs; an explicit visited-set guards
against mutual recursion so no cycle re-enters inline collection.
"""

node SchemaDef {
    has name: str = "";
    has description: str = "";
}

edge RefersTo {
    has field_name: str = "";
    has has_override: bool = False;
}

walker SchemaCollector {
    has schema_type: str = "";
    has collected: list[str] = [];
    has visiting: list[str] = [];
    has done: list[str] = [];

    can start with Root entry {
        self.schema_type = "A";
        self.visiting = ["A"];
        print("Walking A->B->A... with cycle guard:");
        visit [->:RefersTo:->];
    }

    can collect_with_cycle_guard with SchemaDef entry {
        here_name = here.name;
        already_done = False;
        for d in self.done {
            if d == here_name {
                already_done = True;
            }
        }
        in_progress = False;
        for v in self.visiting {
            if v == here_name {
                in_progress = True;
            }
        }
        if already_done {
            ref_label = f"$ref:#/$defs/{here_name}";
            print(f"  -> already collected, emitting {ref_label}");
        } elif in_progress {
            ref_label = f"$ref:#/$defs/{here_name}";
            print(f"  -> cycle hit on {here_name}, emitting {ref_label}");
        } else {
            self.visiting.append(here_name);
            print(f"[INLINE] expanding {here_name}");
            self.collected.append(here_name);
            visit [->:RefersTo:->];
            self.visiting.pop();
            self.done.append(here_name);
        }
    }
}

with entry {
    a_node = SchemaDef(name="A", description="struct A");
    b_node = SchemaDef(name="B", description="struct B");

    root +>:RefersTo(field_name="b", has_override=True):+> a_node;
    a_node +>:RefersTo(field_name="a", has_override=False):+> b_node;
    b_node +>:RefersTo(field_name="b", has_override=False):+> a_node;

    SchemaCollector() spawn root;

    print("\nFinal $defs: " + str(["A", "B"]));
}

