"""Waste-collection graph: model the API list-serialization N+1 / N×M problem.

Demonstrates the issue's shape — a collection with many region attributes,
properties, and related entities — and a leaner walker that avoids the
per-object fan-out by hoisting relationship traversal into typed edges and
walking them once instead of resolving each relation from scratch.
"""

node Collection {
    has name: str = "";
    has region_id: str = "";
}

node Region {
    has name: str = "";
}

node Property {
    has name: str = "";
    has unit: str = "";
}

node RegionAttributeValue {
    has raw_value: str = "";
}

# Typed edges carry the relationship meaning the original code resolved
# via foreign-key lookups (regionattributes_set, property__name=..., etc.).
edge InRegion {
    has since: str = "";
}

edge HasAttribute {
    has kind: str = "";
}

edge Measures {
    has sample_count: int = 0;
}

walker LeanLister {
    # Hoisted caches: one lookup per (region, property) pair, not per object.
    has region_attr_cache: dict[str, str] = {};
    has property_cache: dict[str, str] = {};

    can start with Root entry {
        print("LeanLister: starting at root, visiting collections");
        visit [-->];
    }

    can collect with Collection entry {
        print(f"- Collection: {here.name} in region {here.region_id}");

        # Walk typed edges ONCE instead of N+1 queries.
        visit [->:InRegion:->];
    }

    can resolve with Region entry {
        # Single visit over typed attribute edges — replaces per-object
        # region.regionattributevalue_set.filter(property__name=...) lookups.
        visit [->:HasAttribute:->];
    }

    can attribute with RegionAttributeValue entry {
        key = f"{here}";
        if key not in self.region_attr_cache {
            self.region_attr_cache[key] = here.raw_value;
        }
        visit [->:Measures:->];
    }

    can property_lookup with Property entry {
        if here.name not in self.property_cache {
            self.property_cache[here.name] = here.unit;
        }
    }

    can finish with Collection entry {
        print(
            f"  cached {len(self.region_attr_cache)} attrs, "
            f"{len(self.property_cache)} props for {here.name}"
        );
    }
}

