"""Capability-gated CI mutation services modeled with typed graph traversal."""

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has repository_key: str = "";
}

node Pipeline {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pipeline_id: str = "";
    has repository_key: str = "";
    has supports_retry: bool = False;
}

node Job {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has job_id: str = "";
    has pipeline_id: str = "";
    has supports_cancel: bool = False;
}

node MutationRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has operation: str = "";
    has session_repository: str = "";
    has target_repository: str = "";
    has session_pipeline_id: str = "";
    has target_pipeline_id: str = "";
    has target_job_id: str = "";
    has capability_granted: bool = False;
    has identity_valid: bool = False;
    has supports_retry: bool = False;
    has supports_cancel: bool = False;
    has remote_result: str = "SUCCESS";
    has outcome: str = "PENDING";
}

edge Contains {
    has relation: str = "contains";
}

edge Requests {
    has relation: str = "requests";
}

walker MutationAuditor {
    has steps: int = 0;
    has max_steps: int = 20;
    has accepted: int = 0;
    has rejected: int = 0;
    has unknown: int = 0;

    can start with Root entry {
        print("Auditing capability-gated CI mutations");
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_repository with Repository entry {
        print(f"Repository {here.repository_key}: {here.title}");
        if self.steps < self.max_steps {
            self.steps += 1;
            visit [->:Contains:->] else { disengage; }
        } else {
            disengage;
        }
    }

    can inspect_pipeline with Pipeline entry {
        print(f"Pipeline {here.pipeline_id}: retry={here.supports_retry}");
        if self.steps < self.max_steps {
            self.steps += 1;
            visit [->:Contains:->] else { disengage; }
        } else {
            disengage;
        }
    }

    can inspect_job with Job entry {
        print(f"Job {here.job_id}: cancel={here.supports_cancel}");
        if self.steps < self.max_steps {
            self.steps += 1;
            visit [->:Requests:->] else { disengage; }
        } else {
            disengage;
        }
    }

    can inspect_mutation with MutationRequest entry {
        valid_request = here.identity_valid;

        if here.session_repository != here.target_repository {
            valid_request = False;
        }
        if here.session_pipeline_id != here.target_pipeline_id {
            valid_request = False;
        }
        if here.operation == "retry" {
            if here.supports_retry == False {
                valid_request = False;
            }
        }
        if here.operation == "cancel" {
            if here.supports_cancel == False {
                valid_request = False;
            }
        }

        if valid_request {
            if here.capability_granted {
                if here.remote_result == "TIMEOUT" {
                    here.outcome = "UNKNOWN_OUTCOME";
                    self.unknown += 1;
                    print(f"{here.operation} {here.target_job_id}: UNKNOWN_OUTCOME");
                } else {
                    here.outcome = "ACCEPTED";
                    self.accepted += 1;
                    print(f"{here.operation} {here.target_job_id}: ACCEPTED");
                }
            } else {
                here.outcome = "DENIED_CAPABILITY";
                self.rejected += 1;
                print(f"{here.operation} {here.target_job_id}: DENIED_CAPABILITY");
            }
        } else {
            here.outcome = "STALE_OR_UNSUPPORTED";
            self.rejected += 1;
            print(f"{here.operation} {here.target_job_id}: STALE_OR_UNSUPPORTED");
        }
    }
}

