    has confidence: float = 0.0;
}

edge Implements {
    has relation: str = "";
}

edge References {
    has reason: str = "";
}

edge CyclesTo {
    has note: str = "";
}

walker ReachabilityAudit {
    has seen: list[str] = [];
    has reached: int = 0;

    can start with Root entry {
        print("Starting semantic reachability audit");
        visit [-->] else {
