"""Operator-safe redaction graph: centralized scrub policy walked by an auditor.

Models the core scenario from issue #324 - a single recursive scrub engine
with forbidden field/value matching, snapshot capture, and cycle detection -
exercised across nested values via walker traversal. Each boundary node
exposes a ``label`` field on the shared ``Boundary`` base so a union trigger
can read it safely.
"""

# --- Shared boundary base (gives the union trigger a common field) ---------

node Boundary {
    has label: str = "";
}

# --- Value archetypes --------------------------------------------------------

node ScalarValue {
    has kind: str = "string";
    has raw: str = "";
}

node ListValue {
    has label: str = "";
}

node MapValue {
    has label: str = "";
}

# --- Boundary wrappers (all inherit the shared ``label`` field) --------------

node OperatorLog(Boundary) {
    has sink_name: str = "";
}

node AuditPayload(Boundary) {
    has consumer: str = "";
}

node PublicErrorWrapper(Boundary) {
    has classification: str = "";
}

node SSEPayload(Boundary) {
    has channel: str = "";
}

# --- Typed edges (relationship carries meaning) ------------------------------

edge Contains { }

edge DeliveredTo { }

# --- The scrub policy --------------------------------------------------------

node RedactionPolicy {
    has name: str = "OperatorPolicy";
    has forbidden_fields: list[str] = [
        "password", "secret", "token", "api_key",
        "authorization", "cookie", "credentials", "embedding", "prompt",
    ];
    has max_bytes: int = 1024;
    has snapshot_count: int = 0;
    has redaction_count: int = 0;
    has cycle_count: int = 0;

    def scrub_text(text: str) -> str {
        if text == "" {
            return text;
        }
        lower = text.lower();
        if "bearer " in lower or "sk-" in lower {
            self.redaction_count += 1;
            return "[REDACTED-TOKEN]";
        }
        return text;
    }

    def scrub_value(value: str, field: str) -> str {
        lower_field = field.lower();
        for forbidden in self.forbidden_fields {
            if forbidden in lower_field {
                self.redaction_count += 1;
                return "[FORBIDDEN-FIELD]";
            }
        }
        return self.scrub_text(value);
    }

    def snapshot(value: str) -> dict[str, str | int] {
        self.snapshot_count += 1;
        result: dict[str, str | int] = {};
        raw_bytes = len(value);
        if raw_bytes <= self.max_bytes {
            result["value"] = value;
            result["truncated"] = 0;
        } else {
            preview = value[:self.max_bytes];
            result["value"] = preview;
            result["truncated"] = 1;
            result["original_bytes"] = raw_bytes;
        }
        return result;
    }
}

# --- Walkers -----------------------------------------------------------------

walker ScrubAuditor {
    has path: list[str] = [];
    has findings: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_policy with RedactionPolicy entry {
        self.findings.append(
            f"policy={here.name} forbidden={len(here.forbidden_fields)} "
            f"snapshots={here.snapshot_count} redactions={here.redaction_count}"
        );
        visit [-->];
    }

    # Union trigger: only touches ``label`` (declared on the Boundary base).
    can traverse_boundary with OperatorLog | AuditPayload | PublicErrorWrapper | SSEPayload entry {
        self.findings.append(f"boundary={here.label}");
        visit [-->];
    }

    can recurse with MapValue | ListValue entry {
        container_label = here.label;
        cycle_hit = False;
        for v in self.visited {
            if v == container_label {
                cycle_hit = True;
                break;
            }
        }
        if cycle_hit {
            self.findings.append(f"cycle-detected={container_label}");
            disengage;
        }
        self.visited.append(container_label);
        self.path.append(container_label);
        visit [-->];
    }

    can read_scalar with ScalarValue entry {
        self.findings.append(
            f"scalar kind={here.kind} raw_len={len(here.raw)}"
        );
        if self.path {
            path_str = "/".join(self.path);
            self.findings.append(f"  path={path_str}");
        }
        visit [-->];
    }
}

with entry {
    # Build the redaction policy graph.
    policy = RedactionPolicy(
        name="OperatorPolicy",
        forbidden_fields=[
            "password", "secret", "token", "api_key",
            "authorization", "cookie", "credentials", "embedding", "prompt",
        ],
        max_bytes=128,
    );

    # Wire boundaries as children of the policy. Each fills the shared
    # ``label`` field so the union ability can read it uniformly.
    log = OperatorLog(sink_name="stdout", label="OperatorLog/stdout");
    audit = AuditPayload(consumer="audit-svc", label="AuditPayload/audit-svc");
    puberr = PublicErrorWrapper(classification="public-safe", label="PublicError/public-safe");
    sse = SSEPayload(channel="events", label="SSE/events");
    root +>:DeliveredTo:+> policy;
    policy ++> log;
    policy ++> audit;
    policy ++> puberr;
    policy ++> sse;

    # Nested value tree (map -> list -> scalars).
    config_map = MapValue(label="config");
    creds_map = MapValue(label="credentials");
    history_list = ListValue(label="history");
    scalar_token = ScalarValue(kind="string", raw="Bearer eyJhbGciOiJIUzI1NiJ9.payload.sig");
    scalar_safe = ScalarValue(kind="string", raw="hello world");
    scalar_pwd_field = ScalarValue(kind="string", raw="hunter2");
    scalar_big = ScalarValue(kind="string", raw="x" * 300);

    config_map +>:Contains:+> creds_map;
    config_map +>:Contains:+> history_list;
    creds_map +>:Contains:+> scalar_pwd_field;
    history_list +>:Contains:+> scalar_token;
    history_list +>:Contains:+> scalar_safe;
    config_map +>:Contains:+> scalar_big;

    # Attach the value tree to multiple boundaries to show the recursive
    # scrub path runs once against the same nested structure.
    log +>:Contains:+> config_map;
    audit +>:Contains:+> config_map;
    puberr +>:Contains:+> config_map;
    sse +>:Contains:+> config_map;

    # Spawn the auditor from root so it can see the whole topology.
    auditor = ScrubAuditor();
    root spawn auditor;

    # Drain findings.
    print("AUDIT REPORT");
    for f in auditor.findings {
        print(f);
    }
}

