    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has address: str = "";
    has fil_balance: float = 0.0;
}

edge Contains { }

edge DependsOn {
    has reason: str = "";
}

edge Offers {
    has token: str = "";
    has maximum: float = 0.0;
}

edge Protects {
    has purpose: str = "";
}

walker DependencyAuditor {
    has seen_titles: list[str] = [];
    has visited_count: int = 0;

    can start with Root entry {
        print("Dependency audit started");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_task with FundingTask entry {
        if here.title in self.seen_titles {
            print(f"Cycle detected at {here.title}; stopping this path");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.visited_count += 1;
            print(f"Dependency step {self.visited_count}: {here.title}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

walker SourceSelector {
    has selected_source: str = "";

    can start with Root entry {
        print("Balance-aware source selection started");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_task with FundingTask entry {
        if here.available {
            visit [->:Offers:->] else {
                disengage;
            }
        } else {
            print(f"Unavailable funding task: {here.title}");
            disengage;
        }
