    can inspect_source with FundingSource entry {
        if here.available and here.balance > 0.0 {
            self.selected_source = here.title;
            print(f"Selected {here.title} with {here.balance} units on {here.network}");
            visit [->:Protects:->] else {
                disengage;
            }
        } else {
            print(f"Rejected source: {here.title}");
            disengage;
        }
    }

    can inspect_wallet with AccountWallet entry {
        print(f"Destination wallet {here.address} has {here.fil_balance} FIL");
    }
}

