"""CR3 metadata fallback and lens correction demo."""

node Photo {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has container_name: str = "";
}

node ExifData {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has make: str = "";
    has model: str = "";
    has lens_model: str = "";
    has focal_length_mm: float = 0.0;
    has reader: str = "exifread";
}

node LensProfile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has profile_id: str = "";
    has correction_applied: bool = False;
}

edge HasExif {
    has reader_name: str = "";
}

edge MatchesLens {
    has confidence: float = 0.0;
}

walker ExifAuditor {
    has depth: int = 0;
    has max_depth: int = 5;
    has fallback_used: bool = False;

    can start with Root entry {
        print("Inspecting the CR3 processing graph");
        visit [-->] else { disengage; }
    }

    can inspect_photo with Photo entry {
        print(f"container: {here.container_name}");
        if self.depth >= self.max_depth {
            print("depth guard stopped traversal");
            disengage;
        }
        self.depth += 1;
        visit [->:HasExif:->] else { disengage; }
    }

    can inspect_exif with ExifData entry {
        if here.make == "" and here.model == "" {
            print("exifread returned no tags; using the soft exiftool fallback");
            here.make = "Canon";
            here.model = "Canon EOS R50";
            here.lens_model = "RF-S18-45mm F4-6.3 IS STM";
            here.focal_length_mm = 45.0;
            here.reader = "exiftool fallback";
            self.fallback_used = True;
        }
        print(f"EXIF: {here.make} {here.model}, {here.lens_model}, {here.focal_length_mm}mm");
        if self.depth >= self.max_depth {
            print("depth guard stopped traversal");
            disengage;
        }
        self.depth += 1;
        visit [->:MatchesLens:->] else { disengage; }
    }

    can correct_lens with LensProfile entry {
        if here.available and self.fallback_used {
            here.correction_applied = True;
            print(f"lensfun correction enabled with {here.profile_id}");
        } else {
            print("lensfun correction remains disabled");
        }
    }
}

