Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

"""Dancer2 LSP conformance tracker: walk the route DSL graph to confirm
activation shapes, route declarations, hook wiring, and named-route
references resolve cleanly through typed edges.

The issue complains that hand-rolled machinery (string-keyed route maps,
manual recursion over app fixtures) obscures whether an ordinary Dancer2
application receives correct routes, DSL completion, handler context, and
named-route navigation. This demo lifts that machinery into native Jac:
Dancer2 apps and their routes/hooks/refs become nodes, the relationship
between them becomes typed edges, and a walker traverses the admitted
cells with an explicit cycle policy.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

# A Dancer2 application fixture. `appname` is literal (not dynamic) for the
# supported cells; `dsl_default` records whether the bare `get`/`post`/...
# keywords are admitted at the global scope, and `dsl_handler_only` records
# which keywords may only appear inside a route handler.
node DancerApp {
    has appname: str = "";
    has dsl_default: bool = True;
    has dsl_handler_only: bool = True;
    has supported_version: bool = True;
    has core_only: bool = False;
    has missing_module: bool = False;
}

# A route declaration. Method + pattern are literal; `is_named` flags
# routes with a name so named-route references can be followed; `arity`
# captures the 2/3/4-arg form; `route_kind` discriminates plain / regex /
# any / splat.
node Route {
    has method: str = "";
    has pattern: str = "";
    has route_kind: str = "plain";
    has arity: int = 2;
    has is_named: bool = False;
    has route_name: str = "";
}

# A hook declaration. `hook_kind` selects canonical vs alias vs inline vs
# dynamic/plugin boundary.
node Hook {
    has hook_name: str = "";
    has hook_kind: str = "canonical";
}

# A reference to a named route. `ref_kind` discriminates literal reference
# vs dynamic/incomplete. `safe_for_rename` records whether the LSP may
# safely rename this occurrence.
node RouteRef {
    has target_name: str = "";
    has ref_kind: str = "literal";
    has safe_for_rename: bool = True;
}

# ---------------------------------------------------------------------------
# Typed edges (relationship carries meaning, so each gets an archetype)
# ---------------------------------------------------------------------------

edge DeclaresRoute {}
edge DeclaresHook {}
edge ReferencesRoute {}
edge RunsUnder {}

# ---------------------------------------------------------------------------
# Walker: walks one DancerApp, enumerates its declared routes, follows
# references, and reports lifecycle / support-claim receipts.
# ---------------------------------------------------------------------------

walker ConformanceAuditor {
    # Cycle policy: explicit visited set — walks are over typed DeclaresRoute
    # / ReferencesRoute edges, and a misbehaving fixture that loops a route
    # back onto its own app must not hang the traversal.
    has visited: list[str] = [];
    has route_count: int = 0;
    has ref_count: int = 0;
    has hook_count: int = 0;
    has rejections: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with DancerApp entry {
        # Negative control: unsupported version, missing module, or
        # Dancer2::Core-only usage are out of scope for support claims.
        if not here.supported_version {
            self.rejections.append(f"app {here.appname}: unsupported version");
            disengage;
        }
        if here.missing_module {
            self.rejections.append(f"app {here.appname}: missing Dancer2");
            disengage;
        }
        if here.core_only {
            self.rejections.append(f"app {here.appname}: Dancer2::Core only");
            disengage;
        }
        print(f"auditing Dancer2 app '{here.appname}'");
        visit [->:DeclaresRoute:->];
        visit [->:DeclaresHook:->];
        visit [->:ReferencesRoute:->];
    }

    can tally_route with Route entry {
        self.route_count += 1;
        label = "named" if here.is_named else "anon";
        print(f"  route[{label}] {here.method} {here.pattern} (arity={here.arity}, kind={here.route_kind})");
    }

    can tally_hook with Hook entry {
        self.hook_count += 1;
        print(f"  hook[{here.hook_kind}] {here.hook_name}");
    }

    can follow_ref with RouteRef entry {
        # Cycle guard: track visited ref target names so a ref graph that
        # loops back to itself does not hang the auditor.
        tag = here.target_name + ":" + here.ref_kind;
        if tag in self.visited {
            return;
        }
        self.visited.append(tag);
        self.ref_count += 1;
        verdict = "rename-safe" if here.safe_for_rename else "refused";
        print(f"  ref -> {here.target_name} [{here.ref_kind}, {verdict}]");
    }
}

# ---------------------------------------------------------------------------
# Walker: refuses to audit when the fixture is dynamic-only (a negative
# control: dynamic appname, dynamic route pattern, etc.) — mirrors the
# issue's requirement that the harness assert the intended fallback,
# not merely print "skipped".
# ---------------------------------------------------------------------------

walker RefusalProbe {
    has reason: str = "";

    can probe with DancerApp entry {
        if here.appname == "" {
            self.reason = "dynamic appname";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        if here.core_only {
            self.reason = "Dancer2::Core only";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        if here.missing_module {
            self.reason = "missing Dancer2 module";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        if not here.supported_version {
            self.reason = "unsupported Dancer2 version";
            print(f"REFUSAL: {self.reason}");
            disengage;
        }
        print(f"ACCEPTED: app '{here.appname}' cleared all negative controls");
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Positive fixture: a representative Dancer2 app with literal appname,
    # the full method set, named + regex + any routes, a canonical hook,
    # and a literal named-route reference.
    pos_app = DancerApp(appname="HelloWorld");
    pos_app +>:DeclaresRoute:+> Route(method="get", pattern="/hello", arity=2);
    pos_app +>:DeclaresRoute:+> Route(method="post", pattern="/submit", arity=3);
    pos_app +>:DeclaresRoute:+> Route(method="any", pattern="/any", arity=2, route_kind="any");
    pos_app +>:DeclaresRoute:+> Route(method="get", pattern=r"^/items/(\d+)$", route_kind="regex");
    pos_app +>:DeclaresRoute:+> Route(method="get", pattern="/named", is_named=True, route_name="show_named");
    pos_app +>:DeclaresHook:+> Hook(hook_name="before_request", hook_kind="canonical");
    pos_app +>:DeclaresHook:+> Hook(hook_name="init", hook_kind="alias");
    pos_app +>:ReferencesRoute:+> RouteRef(target_name="show_named", ref_kind="literal", safe_for_rename=True);
    pos_app +>:ReferencesRoute:+> RouteRef(target_name="dyn_target", ref_kind="dynamic", safe_for_rename=False);

    # Negative fixture: dynamic appname — the RefusalProbe must reject it.
    neg_dynamic = DancerApp(appname="", dsl_default=True);
    neg_dynamic +>:DeclaresRoute:+> Route(method="get", pattern="/x");

    # Negative fixture: missing Dancer2 module — both walkers must reject.
    neg_missing = DancerApp(appname="Broken", missing_module=True);

    # Negative fixture: unsupported version.
    neg_version = DancerApp(appname="OldApp", supported_version=False);

    root +>:RunsUnder:+> pos_app;
    root +>:RunsUnder:+> neg_dynamic;
    root +>:RunsUnder:+> neg_missing;
    root +>:RunsUnder:+> neg_version;

    auditor = ConformanceAuditor();
    root spawn auditor;

    print("--- refusal probes ---");
    pos_app spawn RefusalProbe();
    neg_dynamic spawn RefusalProbe();
    neg_missing spawn RefusalProbe();
    neg_version spawn RefusalProbe();

    print(f"summary: routes={auditor.route_count}, hooks={auditor.hook_count}, refs={auditor.ref_count}, rejections={auditor.rejections}");
}

"""Sandbox runaway Bash chain — a self-replicating subprocess process tree.

Models the Codex App Linux sandbox scenario: a single ``ShellInvocation``
spawns a ``BashProcess`` that re-executes itself with the same command
line. Each bash writes its parent pointer to a child via a typed
``Spawned`` edge, forming a linear chain. A ``Sandbox`` walker enforces a
descendant-process cap (the safeguard the issue requests) and reports
the runaway with a single exit summary.
"""

node ShellInvocation {
    has command: str = "";
    has env_stripped: bool = False;
    has expected_output: str = "";
}

node BashProcess {
    has pid: int = 0;
    has cmdline: str = "";
    has depth: int = 0;
    has exited_normally: bool = False;
}

node CgroupScope {
    has scope_path: str = "";
    has pids_max: int = 0;
    has current_tasks: int = 0;
    has frozen: bool = False;
}

edge Spawned {
    has at_depth: int = 0;
}

edge RanIn {
    has start_ts: int = 0;
}

walker Sandbox {
    has cap: int = 16;
    has runaway_detected: bool = False;
    has chain_length: int = 0;
    has summary: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can audit_invocation with ShellInvocation entry {
        print(f"[INVOKE] cmd={here.command!r} stripped={here.env_stripped}");
        visit [->:RanIn:->];
    }

    can audit_scope with CgroupScope entry {
        print(
            f"[SCOPE] {here.scope_path} tasks={here.current_tasks}/"
            f"{here.pids_max} frozen={here.frozen}"
        );
        if here.frozen {
            self.runaway_detected = True;
            self.summary["frozen_scope"] = here.scope_path;
        }
        if here.current_tasks >= self.cap {
            self.runaway_detected = True;
            self.summary["over_cap_scope"] = here.scope_path;
        }
        visit [->:Spawned:->];
    }

    can audit_process with BashProcess entry {
        self.chain_length += 1;
        status = "OK" if here.exited_normally else "RUNAWAY";
        print(
            f"[BASH:{status}] pid={here.pid} depth={here.depth} "
            f"cmd={here.cmdline!r}"
        );
        if not here.exited_normally {
            self.runaway_detected = True;
        }
        if here.depth >= self.cap {
            disengage;
        }
        visit [->:Spawned:->];
    }
}

with entry {
    invocation = ShellInvocation(
        command="render_hostname",
        env_stripped=True,
        expected_output="foo-service.example.com",
    );
    scope = CgroupScope(
        scope_path="/user.slice/.../app-org.chromium.Chromium-1.scope",
        pids_max=32,
        current_tasks=6144,
        frozen=True,
    );
    head = BashProcess(
        pid=1001,
        cmdline="bash -c 'render_hostname'",
        depth=0,
        exited_normally=False,
    );

    invocation +>:RanIn(start_ts=1):+> scope;
    scope +>:Spawned(at_depth=0):+> head;
    head +>:Spawned(at_depth=1):+> BashProcess(
        pid=1002, cmdline="bash -c 'render_hostname'", depth=1,
        exited_normally=False,
    );
    head +>:Spawned(at_depth=2):+> BashProcess(
        pid=1003, cmdline="bash -c 'render_hostname'", depth=2,
        exited_normally=False,
    );
    head +>:Spawned(at_depth=3):+> BashProcess(
        pid=1004, cmdline="bash -c 'render_hostname'", depth=3,
        exited_normally=False,
    );

    root ++> invocation;

    guard = Sandbox(cap=8);
    root spawn guard;
    print(
        f"chain_length={guard.chain_length} "
        f"runaway_detected={guard.runaway_detected} summary={guard.summary}"
    );
}

"""Cross-chain correlation pipeline: event-time walker that detects multi-hop
wash cycles across Stellar, EVM, and Solana chains with reorg-safe invalidation.

Models a tiny slice of Ledgerlens-core's correlation pipeline as an OSP graph:
canonical events are nodes, asset/wallet links are typed edges, and a walker
walks the event-time windowed frontier to detect wash cycles and retract
reorged events.
"""

node CanonicalEvent {
    has chain: str = "";
    has block_or_ledger: str = "";
    has event_time_ms: int = 0;
    has tx_id: str = "";
    has asset: str = "";
    has amount: float = 0.0;
    has finality: str = "pending";
    has retracted: bool = False;
}

node Wallet {
    has address: str = "";
    has chain: str = "";
}

node Asset {
    has symbol: str = "";
    has decimals: int = 0;
}

edge BelongsTo {
    has confidence: float = 1.0;
    has evidence: str = "";
}

edge BridgeLink {
    has bridge: str = "";
    has confidence: float = 1.0;
    has evidence: str = "";
}

walker Correlation {
    has horizon_ms: int = 6000;
    has cycles_found: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can correlate with CanonicalEvent entry {
        if here.retracted {
            return;
        }
        seen = False;
        for vid in self.visited {
            if vid == here.tx_id {
                seen = True;
            }
        }
        if seen {
            return;
        }
        self.visited.append(here.tx_id);
        if here.event_time_ms > self.horizon_ms {
            return;
        }
        print(f"[event] chain={here.chain} asset={here.asset} "
              f"amount={here.amount} finality={here.finality}");
        if here.asset == "USDC" {
            self.cycles_found += 1;
            print(f"     [CYCLE] wash-cycle candidate on {here.asset} "
                  f"({here.tx_id})");
        }
    }

    can follow_wallet with Wallet entry {
        print(f"  -> wallet {here.address} on {here.chain}");
    }

    can scan_asset with Asset entry {
        print(f"  :: asset {here.symbol} (decimals={here.decimals})");
    }
}

walker Reorg {
    has invalidations: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can retract with CanonicalEvent entry {
        if here.chain == "EVM" and here.finality == "pending" {
            here.retracted = True;
            print(f"[reorg] retracting {here.chain}/{here.tx_id} "
                  f"at block {here.block_or_ledger}");
            self.invalidations += 1;
        }
    }
}

with entry {
    usdc = Asset(symbol="USDC", decimals=6);
    weth = Asset(symbol="WETH", decimals=18);

    stellar_wallet = Wallet(address="GABC...", chain="stellar");
    evm_wallet = Wallet(address="0xDEAD", chain="evm");
    solana_wallet = Wallet(address="So1..", chain="solana");

    e1 = CanonicalEvent(
        chain="Stellar", block_or_ledger="L1234",
