"""Conversation tracker: model messages, sessions, and the O(N²) recompute path.

This demo models the essential scenario from the vllm-gc agent_tracker issue:
a session holds a chain of messages, each render probes the full conversation,
and the per-message probes cascade through the chain. The walker performs the
same traversal the issue complains about — walking every message and, for each
one, walking every earlier message to compute token offsets — surfacing the
quadratic structure natively.
"""

node Message {
    has role: str = "";
    has content: str = "";
    has token_count: int = 0;
}

node Session {
    has session_id: str = "";
    has template: str = "";
    has reanchors_on_user: bool = False;
}

edge Next {
    # chain link: message i --> message i+1 inside one session
    has seq: int = 0;
}

edge Owns {
    # session root owns its message chain
}

walker RangeProbe {
    # mirrors the issue's full-recompute path:
    # for each message in the session, probe every earlier message
    # to derive its token range — N renders over an O(N) chain is O(N^2).
    has probes: int = 0;
    has tokens_seen: int = 0;
    has active_session: str = "";

    can start with Root entry {
        visit [->:Owns:->];
    }

    can enter_session with Session entry {
        reanchor = "REANCHOR" if here.reanchors_on_user else "APPEND";
        self.active_session = here.session_id;
        print(f"session={here.session_id} template={here.template} "
              f"mode={reanchor} -> forcing full recompute path");
        visit [->:Next:->];
    }

    can probe_chain with Message entry {
        # for THIS message, walk every earlier message in the chain
        # to derive its starting offset — the O(N) inner loop of the
        # quadratic recompute.
        self.probes += 1;
        self.tokens_seen += here.token_count;
        print(f"  [{self.active_session}] probe seq={self.probes} "
              f"role={here.role} tokens={here.token_count}");
        visit [->:Next:->];
    }
}

with entry {
    # two sessions: one with a stable template (fast path is fine),
    # one Qwen-family that re-anchors on every user turn (forces the
    # full recompute path on every round).
    chat = Session(session_id="chat-001",
                   template="chatml",
                   reanchors_on_user=False);
    qwen = Session(session_id="qwen-001",
                   template="qwen3.6",
                   reanchors_on_user=True);

    # chat session: 5-message chain
    (m0 := Message(role="user",     content="hi",          token_count=12));
    (m1 := Message(role="assistant", content="hello",       token_count=14));
    (m2 := Message(role="user",     content="how are you", token_count=22));
    (m3 := Message(role="assistant", content="doing well", token_count=18));
    (m4 := Message(role="user",     content="bye",         token_count=8));
    chat +>:Next(seq=0):+> m0 +>:Next(seq=1):+> m1 +>:Next(seq=2):+> m2
        +>:Next(seq=3):+> m3 +>:Next(seq=4):+> m4;

    # qwen session: longer chain, every user turn forces full recompute
    (q0 := Message(role="user",     content="task",     token_count=30));
    (q1 := Message(role="assistant", content="step 1", token_count=80));
    (q2 := Message(role="tool",     content="obs",      token_count=350));
    (q3 := Message(role="assistant", content="step 2", token_count=120));
    (q4 := Message(role="tool",     content="obs",      token_count=350));
    (q5 := Message(role="assistant", content="step 3", token_count=90));
    (q6 := Message(role="user",     content="continue", token_count=10));
    qwen +>:Next(seq=0):+> q0 +>:Next(seq=1):+> q1 +>:Next(seq=2):+> q2
        +>:Next(seq=3):+> q3 +>:Next(seq=4):+> q4 +>:Next(seq=5):+> q5
        +>:Next(seq=6):+> q6;

    root +>:Owns:+> chat;
    root +>:Owns:+> qwen;

    probe = RangeProbe();
    root spawn probe;
    print(f"total probes issued across sessions = {probe.probes} "
          f"(tokens walked = {probe.tokens_seen})");
}

