"""Server layer dependency demo: model one-way server layer dependencies as a typed graph.

Entities are server layers (Domain, Persistence, Parsing, Contracts). Edges model
the allowed import direction: 'Allowed' edges point from a layer to a layer it may
import; 'Forbidden' edges mark reverse (back-import) relationships that should
never appear. The DependencyAuditor walker performs a depth-limited traversal
following Allowed edges, detects cross-folder cycles via a guard set, and reports
any Forbidden back-edges observed while walking — the whole-server layer-direction
check the issue calls for.
"""

node Layer {
    has name: str = "";
    has depth_cap: int = 5;
}

edge Allowed {
    has reason: str = "";
}

edge Forbidden {
    has reason: str = "";
}

walker DependencyAuditor {
    has path: list[str] = [];
    has depth: int = 0;
    has seen: list[str] = [];
    has cycles: list[str] = [];
    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Layer entry {
        self.path.append(here.name);
        self.seen.append(here.name);
        self.depth += 1;

        if self.depth > here.depth_cap {
            label = "DEPTH_CAP";
            print(f"[{label}] stopping at {here.name} (depth={self.depth})");
            self.cycles.append(here.name);
            visit [->:Allowed:->] else { disengage; }
        }

        bad_neighbours = [here ->:Forbidden:->];
        for n in bad_neighbours {
            record = f"{here.name} -> {n.name} (forbidden: {n.name})";
            self.violations.append(record);
            print(f"[VIOLATION] {record}");
        }

        visit [->:Allowed:->] else { disengage; }
    }
}

walker CascadeInvalidator {
    has invalid_prefix: str = "domain";

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Layer entry {
        if here.name.startswith(self.invalid_prefix) {
            print(f"[INVALIDATE] purging {here.name} and downstream");
        }
        visit [->:Allowed:->] else { disengage; }
    }
}

with entry {
    domain = Layer(name="domain", depth_cap=5);
    parsing = Layer(name="parsing");
    persistence = Layer(name="persistence");
    contracts = Layer(name="contracts");
    errors = Layer(name="errors");

    root ++> domain ++> parsing ++> errors;
    root ++> domain ++> persistence ++> errors;
    root ++> domain ++> contracts ++> errors;

    domain +>:Allowed(reason="uses parsers"):+> parsing;
    domain +>:Allowed(reason="uses repos"):+> persistence;
    domain +>:Allowed(reason="uses contracts"):+> contracts;
    parsing +>:Allowed(reason="raises"):+> errors;
    persistence +>:Allowed(reason="raises"):+> errors;
    contracts +>:Allowed(reason="raises"):+> errors;

    persistence +>:Forbidden(reason="should not import domain logic"):+> domain;
    contracts +>:Forbidden(reason="should not import domain logic"):+> domain;

    auditor = DependencyAuditor();
    root spawn auditor;
    print(f"detected {auditor.cycles.__len__()} depth-cap events, "
          f"{auditor.violations.__len__()} forbidden back-imports");

    invalidator = CascadeInvalidator(invalid_prefix="domain");
    root spawn invalidator;
}

"""Quiz grader walker with strictly typed integer reports.

The grader walks a small chain of Quiz nodes, collects each student's
score as an integer, and reports the class average. Reports are typed
``list[int]`` and ``int`` so a stray string score becomes a type error.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.scores.append(here.score);
        visit [-->];
    }

    def report_scores -> list[int] {
        return self.scores;
    }

    def report_average -> int {
        total = 0;
        for s in self.scores {
            total = total + s;
        }
        avg = total // len(self.scores) if len(self.scores) > 0 else 0;
        return avg;
    }
}

with entry {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Ben", score=78)
        ++> Quiz(student="Cleo", score=85)
        ++> Quiz(student="Dee", score=64);

    grader = Grader();
    root spawn grader;

    collected: list[int] = grader.report_scores();
    print(f"Collected scores: {collected}");
    print(f"Class average: {grader.report_average()}");
}

"""Build-system cycle detector.

Modules list the modules they depend on. A walker follows dependencies
across typed ``DependsOn`` edges and reports any module that revisits
itself, printing the exact cycle path that triggered the bug.
"""

node Module {
    has name: str = "";
    has depends_on: list[str] = [];
}

edge DependsOn {
    has target_name: str = "";
}

walker CycleHunter {
    has path: list[Module] = [];
    has names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can hunt with Module entry {
        # Cycle guard: explicit, because walkers don't dedupe.
        if here.name in self.names {
            cycle_start = self.names.index(here.name);
            cycle_names = self.names[cycle_start:] + [here.name];
            print("CYCLE DETECTED: " + " -> ".join(cycle_names));
            disengage;
        }

        self.path = self.path + [here];
        self.names = self.names + [here.name];

        # Find outgoing DependsOn edges by target name.
        outgoing = [e for e in [->:DependsOn:->] if True];
        next_edges = [here->:DependsOn:->];
        if not next_edges {
            disengage;
        }

        next_node = next_edges[0];
        print(f"  {self.names[-1]} depends on {next_node.name}");
        visit next_node;
    }
}

with entry {
    # Deliberately broken graph:
    #   app -> utils -> core -> utils (cycle: utils -> core -> utils)
    app = Module(name="app");
    utils = Module(name="utils");
    core = Module(name="core");
    ui = Module(name="ui");
    db = Module(name="db");

    root ++> app;
    root ++> ui;
    root ++> db;

    app +>:DependsOn(target_name="utils"):+> utils;
    utils +>:DependsOn(target_name="core"):+> core;
    core +>:DependsOn(target_name="utils"):+> utils;
    ui +>:DependsOn(target_name="app"):+> app;
    db +>:DependsOn(target_name="core"):+> core;

    print("=== Scanning app and its dependencies ===");
    root spawn CycleHunter();
}

