"""Overflow-aware dashboard traversal for runs and queued jobs."""

node Dashboard {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_limit: int = 3;
    has job_limit: int = 2;
}

node Run {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "run";
    has profile: str = "";
    has status: str = "";
}

node QueueJob {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "job";
    has profile: str = "";
    has task: str = "";
}

edge HasDashboard { }

edge ContainsRecord {
    has lane: str = "";
}

walker DashboardAudit {
    has show_all: bool = False;
    has run_limit: int = 0;
    has job_limit: int = 0;
    has run_total: int = 0;
    has job_total: int = 0;
    has run_displayed: int = 0;
    has job_displayed: int = 0;
    has run_omitted: int = 0;
    has job_omitted: int = 0;

    can start with Root entry {
        visit [->:HasDashboard:->] else { disengage; }
    }

    can inspect_dashboard with Dashboard entry {
        self.run_limit = here.run_limit;
        self.job_limit = here.job_limit;
        visit [-->] else { disengage; }
    }

    can inspect with Run | QueueJob entry {
        if here.kind == "run" {
            self.run_total += 1;
            if self.show_all {
                self.run_displayed += 1;
                print(f"RUN {here.title}");
            } else {
                if self.run_displayed < self.run_limit {
                    self.run_displayed += 1;
                    print(f"RUN {here.title}");
                } else {
                    self.run_omitted += 1;
                }
            }
        } else {
            self.job_total += 1;
            if self.show_all {
                self.job_displayed += 1;
                print(f"JOB {here.title}");
            } else {
                if self.job_displayed < self.job_limit {
                    self.job_displayed += 1;
                    print(f"JOB {here.title}");
                } else {
                    self.job_omitted += 1;
                }
            }
        }
    }

    can summarize with Root exit {
        print(f"Runs displayed={self.run_displayed}, total={self.run_total}, omitted={self.run_omitted}");
        print(f"Jobs displayed={self.job_displayed}, total={self.job_total}, omitted={self.job_omitted}");
    }
}

