"""Data Governance control plane: catalog/lineage/access with typed edges and walkers.

Models the essential Iceberg-Trino-Ranger governance scenario natively:
  - Identities (LDAP/Keycloak users) link to Ranger policies via typed edges.
  - Catalogs/tables carry typed lineage edges with freshness/evidence.
  - PII classification drives column masking on data access.
  - A walker audits authorization decisions across the graph, recursing
    through the parent/child lineage chain (the recursion the issue
    complains about being hand-rolled in Python).
  - A cascade-invalidation walker demonstrates dependency-ordered
    propagation the way a stale-snapshot invalidator would.
"""

# ----------------------------------------------------------------------
# Edge archetypes (typed — the relationship carries meaning / payload).
# ----------------------------------------------------------------------

edge IdentityMapping {
    # LDAP/Keycloak group -> Ranger role binding; has correlation id.
    has correlation_id: str = "";
}

edge LineageEdge {
    # Source -> downstream dataset lineage with provenance payload.
    has source: str = "";
    has query_job: str = "";
    has confidence: float = 1.0;
    has freshness_ts: int = 0;
    has evidence: str = "";
}

edge PolicyBinding {
    # Policy -> applied resource binding.
    has correlation_id: str = "";
}

# ----------------------------------------------------------------------
# Base node for resources that carry identity-style fields shared by
# Dataset and PIIColumn, so a union ability can read them safely.
# ----------------------------------------------------------------------

node GovernedResource {
    has resource_label: str = "";
}

# ----------------------------------------------------------------------
# Node archetypes.
# ----------------------------------------------------------------------

node Identity {
    has display_name: str = "";
    has group: str = "";
    has auth_id: str = "";
}

node RangerPolicy {
    has policy_name: str = "";
    has decision: str = "deny";
    has classification: str = "";
    has version: int = 1;
    has is_stale: bool = False;
}

node Dataset(GovernedResource) {
    has ns: str = "";
    has table_name: str = "";
    has snapshot_id: int = 0;
}

node PIIColumn(GovernedResource) {
    has column_name: str = "";
    has classification: str = "PII";
    has mask_required: bool = True;
}

# ----------------------------------------------------------------------
# Walker: walks identity -> policies -> datasets -> lineage chain.
# Performs the recursion the issue flags as hand-rolled Python.
# Carries an explicit visited-set (jac 0.36.1 walkers don't dedupe).
# ----------------------------------------------------------------------

walker GovernanceAuditor {
    has auditor_name: str = "audit-1";
    has decisions: list = [];
    has visited_ids: list = [];

    can start with Root entry {
        print(f"=== Governance audit by {self.auditor_name} ===");
        visit [-->];
    }

    can audit_identity with Identity entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        print(f"identity {here.display_name} (group={here.group}, "
              f"auth_id={here.auth_id})");
        self.decisions.append(f"IDENTITY:{here.auth_id}");
        visit [->:IdentityMapping:->] else { disengage; }
    }

    can audit_policy with RangerPolicy entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        stale_tag = "STALE" if here.is_stale else "FRESH";
        verdict = f"POLICY:{here.policy_name}={here.decision} "
                  f"(class={here.classification}, v{here.version}, {stale_tag})";
        print(f"  policy {verdict}");
        self.decisions.append(verdict);
        if here.is_stale and here.decision == "allow" {
            print("    !! stale policy -> refusing auto-allow");
            self.decisions.append(f"REFUSED:{here.policy_name}");
            disengage;
        }
        visit [-->];
    }

    can audit_resource with Dataset | PIIColumn entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        print(f"    resource {here.resource_label}");
        self.decisions.append(f"RESOURCE:{here.resource_label}");
        visit [->:LineageEdge:->] else { disengage; }
    }
}

# ----------------------------------------------------------------------
# Walker: dependency-ordered cascade invalidation. Walks a Dataset and
# recursively invalidates downstream lineage when the snapshot is stale.
# ----------------------------------------------------------------------

walker LineageInvalidator {
    has invalidated_count: int = 0;
    has visited_ids: list = [];

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Dataset entry {
        marker = id(here);
        if marker in self.visited_ids {
            visit [-->];
            disengage;
        }
        self.visited_ids.append(marker);
        here.snapshot_id = 0;
        self.invalidated_count += 1;
        print(f"invalidated dataset {here.ns}.{here.table_name}");
        visit [->:LineageEdge:->] else { disengage; }
    }
}

# ----------------------------------------------------------------------
# Demonstration graph.
# ----------------------------------------------------------------------

with entry {
    alice = Identity(display_name="Alice", group="analysts", auth_id="alice@corp");
    bob = Identity(display_name="Bob", group="interns", auth_id="bob@corp");
    svc = Identity(display_name="ETL-Bot", group="services", auth_id="svc-etl");

    p_allow = RangerPolicy(policy_name="analyst-read",
                           decision="allow", classification="internal",
                           version=3);
    p_mask = RangerPolicy(policy_name="pii-mask",
                          decision="mask", classification="PII", version=2);
    p_stale = RangerPolicy(policy_name="legacy-allow",
                           decision="allow", classification="public",
                           version=1, is_stale=True);

    orders = Dataset(ns="sales", table_name="orders", snapshot_id=42,
                     resource_label="sales.orders");
    enriched = Dataset(ns="sales", table_name="orders_enriched",
                       snapshot_id=7, resource_label="sales.orders_enriched");
    pii_col = PIIColumn(column_name="email", classification="PII",
                        mask_required=True, resource_label="sales.orders.email");

    root ++> alice ++> bob ++> svc;
    root +>:IdentityMapping(correlation_id="corr-001"):+> p_allow;
    root +>:IdentityMapping(correlation_id="corr-002"):+> p_mask;
    root +>:IdentityMapping(correlation_id="corr-003"):+> p_stale;
    alice +>:IdentityMapping(correlation_id="bind-a"):+> p_allow;
    bob +>:IdentityMapping(correlation_id="bind-b"):+> p_mask;
    svc +>:IdentityMapping(correlation_id="bind-s"):+> p_allow;

    p_allow +>:PolicyBinding(correlation_id="pb-1"):+> orders;
    p_mask +>:PolicyBinding(correlation_id="pb-2"):+> pii_col;

    orders +>:LineageEdge(source="sales.orders",
                          query_job="trino-job-9001",
                          confidence=0.95,
                          freshness_ts=1715000000,
                          evidence="trino-event-log"):+> enriched;

    root ++> orders ++> enriched ++> pii_col;

    print("--- run auditor ---");
    auditor = GovernanceAuditor(auditor_name="audit-batch-42");
    root spawn auditor;
    print(f"decisions recorded: {auditor.decisions}");

    print("--- run cascade invalidator ---");
    invalidator = LineageInvalidator();
    root spawn invalidator;
    print(f"invalidated datasets: {invalidator.invalidated_count}");
}

