"""Research analytics evidence graph with typed dependencies and cycle detection."""

node SourceRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has work_version: str = "";
    has sha: str = "";
}

node EvidenceRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has condition: str = "";
    has uncertainty: str = "";
}

node ResearchCandidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has level: str = "HYPOTHESIS";
    has transfer_risk: str = "";
}

node AnalyticsChange {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has action: str = "PILOT";
    has owner_reviewed: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

walker DependencyAudit {
    has visited_titles: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with AnalyticsChange | ResearchCandidate | EvidenceRecord | SourceRecord entry {
        if here.title in self.visited_titles {
            self.cycle_detected = True;
            print(f"cycle detected at {here.title}");
            disengage;
        }

        self.visited_titles.append(here.title);
        print(f"record: {here.title} ({here.year})");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

with entry {
    source = SourceRecord(
        title="Structured Data Analysis Study",
        year=2025,
        work_version="P1-v1",
        sha="abc123"
    );

    evidence = EvidenceRecord(
        title="Executable analytics improves reproducibility",
        year=2025,
        condition="tabular data with validated schema",
        uncertainty="benchmark transfer remains limited"
    );

    candidate = ResearchCandidate(
        title="Separate deterministic calculation from interpretation",
        year=2025,
        level="HYPOTHESIS",
        transfer_risk="medium"
    );

    change = AnalyticsChange(
        title="Analytics execution-control pilot",
        year=2025,
        action="PILOT",
        owner_reviewed=False
    );

    root ++> change;
    change +>:DependsOn(reason="candidate requires an owner-reviewed pilot"):+> candidate;
    candidate +>:DependsOn(reason="claim requires retained evidence"):+> evidence;
    evidence +>:DependsOn(reason="evidence must remain source-bound"):+> source;
    source +>:DependsOn(reason="cycle guard demonstration"):+> change;

    root spawn DependencyAudit();
}

"""Bounded callable-summary composition with cycle detection and invalidation."""

node Routine {
    has name: str = "";
    has version: int = 0;
    has current: bool = True;
    has summary: str = "";
    has invalidated: bool = False;
}

node CallSite {
    has name: str = "";
    has context: str = "scalar";
    has observed_version: int = 0;
    has callee_version: int = 0;
    has depth: int = 0;
    has exact: bool = True;
    has bounded: bool = True;
}

edge Owns {
    has ordinal: int = 0;
}

edge Calls {
    has context: str = "";
}

edge Invalidates {
    has reason: str = "";
}

walker SemanticComposer {
    has max_depth: int = 2;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Routine entry {
        if (here.name in self.seen) {
            print(f"cycle guard stopped at {here.name}");
        } else {
            self.seen.append(here.name);
            print(f"summary {here.name} v{here.version}: {here.summary}");
            visit [->:Owns:->] else {
                disengage;
            }
        }
    }

    can apply with CallSite entry {
        if (here.depth > self.max_depth) {
            here.bounded = False;
            here.exact = False;
            print(f"bounded refusal at {here.name}");
            disengage;
        } else {
            if (here.observed_version == here.callee_version) {
                here.exact = True;
                print(f"exact {here.context} result at {here.name}");
            } else {
                here.exact = False;
                print(f"stale callee fact at {here.name}; caller needs refresh");
            }
            visit [->:Calls:->] else {
                disengage;
            }
        }
    }
}

walker InvalidationAuditor {
    has seen: list[str] = [];

    can invalidate with Routine entry {
        if (here.name in self.seen) {
            print(f"invalidation cycle guard stopped at {here.name}");
        } else {
            self.seen.append(here.name);
            here.invalidated = True;
            print(f"invalidated {here.name} and its composed facts");
            visit [->:Invalidates:->] else {
                disengage;
            }
        }
    }
}

with entry {
    main = Routine(
        name="main",
        version=1,
        summary="returns scalar; reads argument place"
    );
    helper = Routine(
        name="helper",
        version=2,
        summary="returns scalar; may throw"
    );

    main_to_helper = CallSite(
        name="main -> helper",
        context="scalar",
        observed_version=1,
        callee_version=2,
        depth=1
    );
    helper_to_main = CallSite(
        name="helper -> main",
        context="scalar",
        observed_version=1,
        callee_version=1,
        depth=2
    );

    root ++> main;
    main +>:Owns(ordinal=1):+> main_to_helper;
    main_to_helper +>:Calls(context="scalar"):+> helper;
    helper +>:Owns(ordinal=1):+> helper_to_main;
    helper_to_main +>:Calls(context="scalar"):+> main;

    helper +>:Invalidates(reason="callee version changed"):+> main;

    root spawn SemanticComposer(max_depth=2);
    helper spawn InvalidationAuditor();
}

"""Warehouse stock take: shelves are nodes holding SKUs and counts.

A counter walker sweeps every shelf, reports each shelf quantity,
then prints per-item counts, the grand total, and the smallest shelf.
"""

node Shelf {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total: int = 0;
    has smallest: int = -1;
    has per_item: dict[str, int] = {};

    can start with Root entry {
        visit [-->];
    }

    can count with Shelf entry {
        print(f"Shelf {here.sku}: {here.quantity} units");
        self.total = self.total + here.quantity;
        if self.smallest == -1 or here.quantity < self.smallest {
            self.smallest = here.quantity;
        }
        existing = self.per_item.get(here.sku, 0);
        self.per_item[here.sku] = existing + here.quantity;
        visit [-->];
    }
}

with entry {
    root ++> Shelf(sku="A-001", quantity=12)
        ++> Shelf(sku="B-014", quantity=7)
        ++> Shelf(sku="C-220", quantity=3)
        ++> Shelf(sku="A-001", quantity=5);

    counter = Counter();
    root spawn counter;

    print("Per-item totals:");
    for (sku, qty) in counter.per_item.items() {
        print(f"  {sku}: {qty}");
    }
    print(f"Total units in warehouse: {counter.total}");
    print(f"Smallest shelf count: {counter.smallest}");
}

"""Organization-scoped report cache invalidation with bounded report ranges."""

node Organization {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

node Sale {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has amount: float = 0.0;
    has sale_day: str = "";
    has mutated: bool = False;
}

node ReportCache {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cache_scope: str = "";
    has range_days: int = 0;
    has stale_after_days: int = 0;
}

edge Contains {
    has organization_scope: str = "";
}

edge Invalidates {
    has dependency_kind: str = "";
    has organization_scope: str = "";
}

walker CacheInvalidator {
    has max_range_days: int = 31;
    has invalidated_count: int = 0;
    has seen_titles: list[str] = [];

    can start with Root entry {
        print("Starting report dependency walk");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_organization with Organization entry {
        if here.title in self.seen_titles {
            print(f"Cycle guard stopped at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            print(f"Inspecting organization scope: {here.slug}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_sale with Sale entry {
        if here.title in self.seen_titles {
            print(f"Cycle guard stopped at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            if here.mutated {
                print(f"Mutation detected for {here.title}");
                visit [->:Invalidates:->] else {
                    disengage;
                }
            } else {
                print(f"No mutation detected for {here.title}");
                disengage;
            }
        }
    }

    can invalidate_cache with ReportCache entry {
        if here.title in self.seen_titles {
            print(f"Cycle guard stopped at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            if here.range_days > self.max_range_days {
                print(f"Skipped {here.title}: range exceeds bound");
            } else {
                if here.cache_scope == "organization" {
                    if here.available {
                        here.available = False;
                        self.invalidated_count += 1;
                        print(f"Invalidated {here.title}");
                    } else {
                        print(f"Cache {here.title} was already invalid");
                    }
                } else {
                    print(f"Skipped {here.title}: unsupported cache scope");
                }
            }
        }
    }
}

with entry {
    organization = Organization(
        title="MeperDonas",
        year=2024,
        slug="tenant-meperdonas"
    );

    sale = Sale(
        title="sale-124",
        year=2024,
        amount=125.50,
        sale_day="2024-06-12",
        mutated=True
    );

    financial_cache = ReportCache(
        title="financial:2024-06",
        year=2024,
        cache_scope="organization",
        range_days=30,
        stale_after_days=5
    );

    dashboard_cache = ReportCache(
        title="dashboard:2024-06",
        year=2024,
        cache_scope="organization",
        range_days=7,
        stale_after_days=2
    );

    organization +>:Contains(organization_scope="tenant-meperdonas"):+> sale;
    sale +>:Invalidates(
        dependency_kind="sales",
        organization_scope="tenant-meperdonas"
    ):+> financial_cache;
    sale +>:Invalidates(
        dependency_kind="sales",
        organization_scope="tenant-meperdonas"
    ):+> dashboard_cache;

    root ++> organization;
    root spawn CacheInvalidator(max_range_days=31);
}

"""Pet-or-People social graph: a walker recommends adult-human friends only.

Profiles may be human (with an age) or pet (no age concept). The walker
visits every profile reachable from each person through the ``Friends``
edge, counts the raw neighbour total, then filters out pet nodes and
minors (age < 18), reporting the surviving adult-human suggestions.
"""

node Profile {
    has name: str = "";
    has age: int = 0;
    has species: str = "human";

    def is_human() -> bool {
        return self.species == "human";
    }

    def is_adult() -> bool {
        return self.is_human() and self.age >= 18;
    }

    def is_eligible_friend() -> bool {
        return self.is_adult();
    }
}

edge Friends {
    has years_known: int = 0;
}

walker Recommender {
    has raw_count: int = 0;
    has eligible_count: int = 0;
    has person_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can recommend with Profile entry {
        if not here.is_human() {
            return;
        }
        self.person_name = here.name;
        self.raw_count = 0;
        self.eligible_count = 0;
        for n in [->:Friends:->] {
            self.raw_count += 1;
            if n.is_eligible_friend() {
                self.eligible_count += 1;
            }
        }
        print(
            f"{self.person_name}: raw neighbours={self.raw_count}, "
            f"adult-human suggestions={self.eligible_count}"
        );
    }
}

with entry {
    alice = Profile(name="Alice", age=30);
    bob = Profile(name="Bob", age=25);
    carol = Profile(name="Carol", age=17);
    rex = Profile(name="Rex", species="pet");
    whiskers = Profile(name="Whiskers", species="pet");

    alice +>:Friends(years_known=5):+> bob;
    alice +>:Friends(years_known=3):+> carol;
    alice +>:Friends(years_known=7):+> rex;
    alice +>:Friends(years_known=2):+> whiskers;

    bob +>:Friends(years_known=10):+> alice;
    bob +>:Friends(years_known=1):+> rex;

    root ++> alice ++> bob;
    root ++> carol;
    root ++> rex;
    root ++> whiskers;

    root spawn Recommender();
}

"""Order auditor demonstrating both early-return flavors side by side.

Walk a chain of Order nodes. Each order is either:
  - valid   -> audited (printed and traversal continues),
  - invalid -> skipped (printed and traversal continues),
  - flagged for fraud -> halts the walk immediately with disengage.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has flagged_fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Beginning order audit...");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        if here.flagged_fraud {
            print(f"[HALT] Fraud flag on '{here.title}' (${here.amount:.2f}) — stopping walk");
            disengage;
        }

        action = "SKIPPED" if not here.valid else "AUDITED";
        print(f"[{action}] '{here.title}' amount=${here.amount:.2f}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Order(title="PO-1001", amount=250.00, valid=True)
        ++> Order(title="PO-1002", amount=89.50, valid=False)
        ++> Order(title="PO-1003", amount=1200.00, valid=True, flagged_fraud=True)
        ++> Order(title="PO-1004", amount=42.00, valid=True);

    root spawn OrderAuditor();
}

"""Lakehouse pipeline decoupling demo.

Models the tension described in Lakehouse_Plumber issue #212: a single
``pipeline:`` value on every flowgroup collapses the generated output into
one flat folder and one bundle resource file, destroying the source-side
medallion organization. We model flowgroups, their layer membership, and
the pipeline grouping as a graph, then walk it with a walker that exposes
the original-code pain (a fan-in at Gold without an execution boundary).
"""

node FlowGroup {
    has title: str = "";
    has layer: str = "";
    has pipeline: str = "";
}

node Pipeline {
    has pipeline_name: str = "";
    has is_dlt_boundary: bool = True;
}

node OutputTable {
    has table_name: str = "";
}

edge LivesIn {
    has folder: str = "";
}

edge Feeds {
    has cardinality: str = "";
}

edge BundledAs {
    has resource_file: str = "";
}

walker Plumber {
    has visited: list[str] = [];

    can start with Root entry {
        print("Plumber walking the repo -> generated layout");
        visit [-->];
    }

    can inspect_flowgroup with FlowGroup entry {
        layer_folder = f"pipelines/{here.layer}/{here.title}.yaml";
        generated_file = f"generated/dev/{here.pipeline}/{here.title}.py";
        bundle_file = f"resources/lhp/{here.pipeline}.pipeline.yml";
        print(
            f"[FG] {here.title}  layer={here.layer}  pipeline={here.pipeline}\n"
            f"     source : {layer_folder}\n"
            f"     gen    : {generated_file}\n"
            f"     bundle : {bundle_file}"
        );
        self.visited.append(here.title);
        visit [-->];
    }

    can inspect_pipeline with Pipeline entry {
        n_groups = 0;
        for fg in [-->] {
            if isinstance(fg, FlowGroup) {
                n_groups = n_groups + 1;
            }
        }
        kind = "DLT" if here.is_dlt_boundary else "logical";
        print(f"[PIPELINE] {here.pipeline_name}  ({kind}, {n_groups} flowgroups)");
        visit [-->];
    }

    can inspect_output with OutputTable entry {
        print(f"[TABLE] {here.table_name}");
    }
}

walker CascadeInvalidator {
    can start with Root entry {
        print("\nCascadeInvalidator: invalidating downstream of a slow Bronze flow");
        visit [-->];
    }

    can fanin with OutputTable entry {
        print(f"  fan-in surface : {here.table_name}");
        visit [-->];
    }
}

with entry {
    bronze_a = FlowGroup(title="parts_bronze_a", layer="01_bronze", pipeline="all");
    bronze_b = FlowGroup(title="parts_bronze_b", layer="01_bronze", pipeline="all");
    silver_a = FlowGroup(title="parts_silver_a", layer="02_silver", pipeline="all");
    silver_b = FlowGroup(title="parts_silver_b", layer="02_silver", pipeline="all");
    gold_join = FlowGroup(title="parts_gold", layer="03_gold", pipeline="all");

    end_to_end = Pipeline(pipeline_name="all", is_dlt_boundary=True);

    table_silver_a = OutputTable(table_name="silver.a_clean");
    table_silver_b = OutputTable(table_name="silver.b_clean");
    table_gold = OutputTable(table_name="gold.ab_join");

    root ++> bronze_a ++> silver_a;
    root ++> bronze_b ++> silver_b;
    root ++> silver_a ++> gold_join;
    root ++> silver_b ++> gold_join;

    bronze_a +>:LivesIn(folder="pipelines/01_FIRST_LAYER"):+> end_to_end;
    bronze_b +>:LivesIn(folder="pipelines/01_FIRST_LAYER"):+> end_to_end;
    silver_a +>:LivesIn(folder="pipelines/02_SECOND_LAYER"):+> end_to_end;
    silver_b +>:LivesIn(folder="pipelines/02_SECOND_LAYER"):+> end_to_end;
    gold_join +>:LivesIn(folder="pipelines/03_GOLD"):+> end_to_end;

    bronze_a +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    bronze_b +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    silver_a +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    silver_b +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    gold_join +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;

    silver_a +>:Feeds(cardinality="1:1"):+> table_silver_a;
    silver_b +>:Feeds(cardinality="1:1"):+> table_silver_b;
    table_silver_a +>:Feeds(cardinality="N:1"):+> table_gold;
    table_silver_b +>:Feeds(cardinality="N:1"):+> table_gold;

