"""ZipHelper-style guard: refuse to clobber a destination directory before writing.

Models the issue scenario — a destination check that is type-blind and silently
deletes a whole tree — as a native Jac graph. A `FileNode` is either a file or
a directory, and the `safe_write` walker descends to the proposed destination,
refuses if it is one (or lives inside one), and otherwise proceeds.
"""

node FileNode {
    has name: str = "";
    has kind: str = "file";   # "file" or "directory"
}

edge Contains { }              # parent directory -> child file/directory
edge WritesTo { }              # source archive -> destination path

walker SafeWrite {
    has destination_is_dir: bool = False;
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can descend with FileNode entry {
        if here.kind == "directory" {
            self.destination_is_dir = True;
            self.blocked = True;
            print(f"REFUSED: destination '{here.name}' is a directory — would recursively delete its contents");
            disengage;
        }
        visit [-->];
    }
}

# Same walker, reverse direction: walk parent links and refuse if any is a dir.
walker CheckAncestors {
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can ascend with FileNode entry {
        if here.kind == "directory" {
            self.blocked = True;
            print(f"REFUSED: an ancestor '{here.name}' is a directory");
            disengage;
        }
        visit [<--];
    }
}

# Demonstrates the bad case: destination already exists as a directory.
# Demonstrates the good case: destination does not exist, write proceeds.
walker ZipHelper {
    has src: str = "";
    has dest_name: str = "";
    has wrote: bool = False;

    can start with Root entry {
        # Pick the archive source (a file) and its destination candidate.
        archive = FileNode(name=self.src, kind="file");
        root +>:WritesTo:+> (dest := FileNode(name=self.dest_name, kind="file"));
        root ++> archive;

        # First: descend into destination to see if it is itself a directory.
        here_safe = False;
        for d in [-->] {
            if d.name == self.dest_name {
                probe = SafeWrite();
                probe spawn d;
                if not probe.blocked {
                    here_safe = True;
                }
                break;
            }
        }

        # Also walk parents of the destination — refuse if any is a directory.
        if here_safe {
            for d in [-->] {
                if d.name == self.dest_name {
                    up = CheckAncestors();
                    up spawn d;
                    if up.blocked {
                        here_safe = False;
                    }
                    break;
                }
            }
        }

        if here_safe {
            self.wrote = True;
            print(f"WROTE zip '{self.src}' -> '{self.dest_name}' (file path is clear)");
        } else {
            print(f"ABORTED: refused to write '{self.src}' over '{self.dest_name}'");
        }
    }
}

with entry {
    # Build a small tree: an existing directory that holds a couple of files.
    existing_dir = FileNode(name="out", kind="directory");
    kept_a = FileNode(name="keep-me.txt", kind="file");
    kept_b = FileNode(name="also-keep.txt", kind="file");
    root ++> existing_dir ++> kept_a;
    existing_dir ++> kept_b;

    # Case A: destination points AT the directory — must refuse.
    print("--- Case A: destination is an existing directory ---");
    root spawn ZipHelper(src="payload.zip", dest_name="out");

    # Case B: destination is a brand-new file path inside a directory ancestor.
    # Walking ancestors still hits the directory, so it must also refuse.
    print("--- Case B: destination is a new file inside an existing directory ---");
    nested_target = FileNode(name="fresh.txt", kind="file");
    existing_dir ++> nested_target;
    root spawn ZipHelper(src="payload.zip", dest_name="fresh.txt");

    # Case C: destination is a new file with no directory ancestor — proceeds.
    print("--- Case C: destination is a brand-new file path ---");
    root spawn ZipHelper(src="payload.zip", dest_name="brand-new.zip");
}

"""Native graph model of download cancellation ownership races."""

node Manga {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Chapter {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "QUEUED";
    has generation: int = 0;
    has cancel_requested: bool = False;
    has active: bool = False;
    has pages_written: int = 0;

    def request_cancel() {
        self.cancel_requested = True;
    }

    def cancel_if_requested() -> bool {
        if self.cancel_requested {
            self.state = "CANCELLED";
            self.active = False;
            self.generation += 1;
            return True;
        }
        return False;
    }

    def claim_queued() -> bool {
        if self.state == "QUEUED" and not self.cancel_requested {
            self.state = "RUNNING";
            self.active = True;
            self.generation += 1;
            return True;
        }
        return False;
    }

    def accept_page(worker_generation: int) -> bool {
        if self.state == "RUNNING" and self.active and not self.cancel_requested and self.generation == worker_generation {
            self.pages_written += 1;
            return True;
        }
        return False;
    }

    def publish_success(worker_generation: int) -> bool {
        if self.state == "RUNNING" and self.active and not self.cancel_requested and self.generation == worker_generation {
            self.state = "SUCCESS";
            self.active = False;
            return True;
        }
        return False;
    }
}

node DownloadWorker {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has worker_name: str = "";
}

edge Contains {
    has chapter_number: int = 0;
}

edge Owns {
    has generation: int = 0;
}

edge WorkerRoot { }

walker CancellationSweep {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_manga with Manga entry {
        visit [->:Contains:->] else { disengage; }
    }

    can cancel_requested_chapter with Chapter entry {
        if here.cancel_requested {
            changed = here.cancel_if_requested();
            print(f"cancel sweep: {here.title} -> {here.state} (changed={changed})");
        }
    }
}

walker WorkerDrain {
    has worker_generation: int = 0;

    can start with Root entry {
        visit [->:WorkerRoot:->] else { disengage; }
    }

    can follow_ownership with DownloadWorker entry {
        print(f"worker {here.worker_name} follows its ownership edge");
        visit [->:Owns:->] else { disengage; }
    }

    can enforce_ownership with Chapter entry {
        claimed = here.claim_queued();
        if claimed {
            self.worker_generation = here.generation;
            before_cancel = here.accept_page(self.worker_generation);
            here.request_cancel();
            cancelled = here.cancel_if_requested();
            after_cancel = here.accept_page(self.worker_generation);
            completed = here.publish_success(self.worker_generation);
            print(f"worker race: {here.title} claimed={claimed}, page_before_cancel={before_cancel}, cancelled={cancelled}, page_after_cancel={after_cancel}, success={completed}, state={here.state}");
        } else {
            print(f"worker race: {here.title} claim rejected, state={here.state}");
        }
    }
}

with entry {
    manga = Manga(title="Kira Manga", year=2025);
    queued = Chapter(title="queued-cancel-before-claim", year=2025);
    queued.request_cancel();
    active = Chapter(title="active-cancel-after-claim", year=2025);
    worker = DownloadWorker(title="worker", worker_name="W-1");

    root ++> manga;
    manga +>:Contains(chapter_number=1):+> queued;
    manga +>:Contains(chapter_number=2):+> active;
    root +>:WorkerRoot:+> worker;
    worker +>:Owns(generation=0):+> queued;
    worker +>:Owns(generation=0):+> active;

    root spawn CancellationSweep();
    root spawn WorkerDrain();
}

