"""RiskAssessor demo: model endpoints, systems, and a blast-radius walker
that walks the target graph to count unique affected assets.

The original bug: target extraction took the last URL segment, so two
distinct systems performing the same operation type (e.g. EthernetInterfaces)
collapsed to a single "target". The walker below instead walks typed edges
from each impacted Endpoint to the distinct System it belongs to, so the
unique-asset count reflects real physical asset identity.
"""

node Endpoint {
    has url: str = "";
    has operation: str = "";
}

node System {
    has system_id: str = "";
}

edge Exposes {
    has note: str = "";
}

node Workflow {
    has name: str = "";
    has blast_multiplier: float = 1.0;
    has unique_targets: int = 0;
}

edge Touches {
}

walker BlastAuditor {
    has seen: list[str] = [];
    has unique_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Workflow entry {
        self.seen = [];
        self.unique_count = 0;
        visit [-->];
    }

    can tally with Endpoint entry {
        visit [->:Exposes:->];
    }

    can count with System entry {
        sys_id = here.system_id;
        if sys_id not in self.seen {
            self.seen.append(sys_id);
            self.unique_count += 1;
        }
    }
}

with entry {
    sys_a = System(system_id="System.Embedded.1");
    sys_b = System(system_id="System.Embedded.2");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.2/EthernetInterfaces",
        operation="EthernetInterfaces",
    );

    wf = Workflow(name="PatchEthernet");

    root ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    ep_a +>:Exposes(note="binding"):+> sys_a;
    ep_b +>:Exposes(note="binding"):+> sys_b;

    root spawn BlastAuditor();
    auditor2 = BlastAuditor();
    wf spawn auditor2;

    wf.unique_targets = auditor2.unique_count;
    wf.blast_multiplier = 1.0 + 0.5 * auditor2.unique_count;

    print(
        f"workflow={wf.name} unique_assets={wf.unique_targets} "
        f"blast_multiplier={wf.blast_multiplier}"
    );
    print(f"seen asset ids: {auditor2.seen}");
}

"""Wayfinder control plane: bounded recursive delegation, local skill dispatch, and evidence-gated task promotion."""

edge IssuesContract {
    has contract_id: str = "";
}

edge EndowedWith { }

edge BindsTask { }

node Controller {
    has name: str = "";
}

node Agent {
    has name: str = "";
    has depth: int = 0;
    has max_depth: int = 3;
    has status: str = "idle";
}

node Skill {
    has title: str = "";
    has risk: str = "low";
    has available: bool = True;
}

node Task {
    has goal: str = "";
    has required_skill: str = "";
    has attested: bool = False;
    has promoted: bool = False;
}

walker Wayfinder {
    has seen: list[str] = [];

    can start with Root entry {
        print("=== Wayfinder: skill-aware fleet dispatch ===");
        visit [-->];
    }

    can orient with Controller entry {
        print(f"Controller [{here.name}] scanning delegation tree");
        visit [->:IssuesContract:->] else { disengage; };
    }

    can delegate with Agent entry {
        if here.name in self.seen {
            print(f"[CYCLE] blocked re-entry to agent {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        if here.depth >= here.max_depth {
            print(f"[DEPTH] {here.name} at budget {here.max_depth}, stopping branch");
            disengage;
        }
        status_label = "ACTIVE" if here.status == "active" else "IDLE";
        print(f"[{status_label}] {here.name} depth={here.depth}");
        visit [->:EndowedWith:->];
        visit [->:IssuesContract:->] else { disengage; };
    }

    can match_skill with Skill entry {
        avail = "OK" if here.available else "OUT";
        print(f"  local skill [{avail}] {here.title} (risk={here.risk})");
    }
}

walker EvidenceArbiter {
    has promotions: int = 0;

    can start with Root entry {
        print("=== EvidenceArbiter: promote only verified results ===");
        visit [-->];
    }

    can scan with Controller entry {
        visit [->:BindsTask:->] else { disengage; };
    }

    can judge with Task entry {
        if here.attested {
            here.promoted = True;
            self.promotions += 1;
            verdict = "PROMOTED";
            label = "fresh attestation";
        } else {
            verdict = "HELD";
            label = "stale cache / no attestation";
        }
        print(f"[{verdict}] {here.goal} ({label})");
    }
}

with entry {
    ctrl = Controller(name="Primary");
    root ++> ctrl;

    lead = Agent(name="lead-1", status="active", depth=0);
    worker = Agent(name="worker-2", depth=1);
    specialist = Agent(name="spec-3", depth=2);

    ctrl +>:IssuesContract(contract_id="DC-100"):+> lead;
    lead +>:IssuesContract(contract_id="DC-101"):+> worker;
    worker +>:IssuesContract(contract_id="DC-102"):+> specialist;
    specialist +>:IssuesContract(contract_id="DC-cycle"):+> lead;

    review = Skill(title="code-review", risk="low");
    dispatch = Skill(title="local-dispatch", risk="low");
    lead +>:EndowedWith:+> review;
    worker +>:EndowedWith:+> dispatch;

    verified_job = Task(
        goal="assistance.local-dispatch PR review",
        required_skill="code-review",
        attested=True,
    );
    held_job = Task(
        goal="unverified refactor",
        required_skill="refactor",
        attested=False,
    );
    ctrl +>:BindsTask:+> verified_job;
    ctrl +>:BindsTask:+> held_job;

    root spawn Wayfinder();
    arbiter = EvidenceArbiter();
    root spawn arbiter;
    print(f"EvidenceArbiter promoted {arbiter.promotions} task(s)");
}

