"""Weather sweep: stations are nodes, a walker visits each and reports the temperature."""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[tuple[str, float]] = [];
    has min_temp: float = 0.0;
    has max_temp: float = 0.0;
    has first: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        self.readings.append((here.location, here.celsius));
        if self.first {
            self.min_temp = here.celsius;
            self.max_temp = here.celsius;
            self.first = False;
        } else {
            if here.celsius < self.min_temp {
                self.min_temp = here.celsius;
            }
            if here.celsius > self.max_temp {
                self.max_temp = here.celsius;
            }
        }
        print(f"[{here.location}] {here.celsius}°C");
        visit [-->];
    }
}

with entry {
    root ++> Station(location="North Ridge", celsius=12.4)
        ++> Station(location="River Valley", celsius=18.9)
        ++> Station(location="Coastal Pier", celsius=15.2)
        ++> Station(location="Desert Mesa", celsius=31.7)
        ++> Station(location="Alpine Peak", celsius=-3.5);

    sweep = WeatherSweep();
    root spawn sweep;

    print("--- Sweep Summary ---");
    for (loc, temp) in sweep.readings {
        print(f"{loc}: {temp}°C");
    }
    print(f"Min: {sweep.min_temp}°C across {len(sweep.readings)} stations");
    print(f"Max: {sweep.max_temp}°C across {len(sweep.readings)} stations");
}

"""Scene-graph incremental invalidation.

Models the pygfx/pygfx issue #1298 scenario: a scene is built once but
rendered many times. The naive approach re-walks the whole tree on every
render. The incremental approach maintains derived state on mutation
and reuses it on render. Both are demonstrated.
"""

# --- Entity archetypes ----------------------------------------------------

node Group {
    has name: str = "";
    has group_order: int = 0;
}

node Renderable {
    has name: str = "";
    has visible: bool = True;
}

node Light {
    has name: str = "";
    has light_type: str = "point";
}

# --- Typed edges (relationship carries meaning) ---------------------------

edge Child {
    has order: int = 0;
}

# --- Walker: naive full traversal (the costly path the issue complains about)

walker NaiveFlatten {
    has renderables: list = [];
    has lights: list = [];
    has group_orders: dict = {};
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk with Group entry {
        if here.group_order != 0 {
            self.group_orders[here.name] = here.group_order;
        }
        self.depth += 1;
        visit [->:Child:->];
        self.depth -= 1;
    }

    can gather_renderable with Renderable entry {
        if here.visible {
            self.renderables.append(here.name);
        }
        visit [->:Child:->];
    }

    can gather_light with Light entry {
        self.lights.append((here.name, here.light_type));
        visit [->:Child:->];
    }
}

# --- Walker: incremental invalidation marker -------------------------------

walker MarkDirty {
    can start with Root entry {
        visit [-->];
    }

    can mark_group with Group entry {
        print(f"  invalidating subtree rooted at Group '{here.name}'");
        visit [->:Child:->];
    }

    can mark_renderable with Renderable entry {
        print(f"  invalidating renderable '{here.name}'");
        visit [->:Child:->];
    }

    can mark_light with Light entry {
        print(f"  invalidating light '{here.name}'");
        visit [->:Child:->];
    }
}

# --- Helpers ---------------------------------------------------------------

def render_frame(label: str, w: NaiveFlatten) -> None {
    print(f"--- frame ({label}) ---");
    print(f"  renderables: {w.renderables}");
    print(f"  lights:      {w.lights}");
    print(f"  group_order: {w.group_orders}");
}

# --- Demo ------------------------------------------------------------------

with entry {
    # Build a deep nested scene graph with a couple of lights.
    g1 = Group(name="root_group", group_order=1);
    g2 = Group(name="rig", group_order=2);
    g3 = Group(name="mesh_bucket", group_order=3);
    g4 = Group(name="deep_leaf", group_order=0);

    r1 = Renderable(name="cube");
    r2 = Renderable(name="line_strip");
    r3 = Renderable(name="points");
    r4 = Renderable(name="hidden_helper", visible=False);
    l1 = Light(name="key_light", light_type="directional");
    l2 = Light(name="fill_light", light_type="ambient");

    root ++> g1;
    g1 +>:Child(order=0):+> g2;
    g2 +>:Child(order=0):+> g3;
    g3 +>:Child(order=0):+> g4;
    g4 +>:Child(order=0):+> r1;
    g3 +>:Child(order=1):+> r2;
    g2 +>:Child(order=1):+> r3;
    g2 +>:Child(order=2):+> r4;
    g1 +>:Child(order=1):+> l1;
    g1 +>:Child(order=2):+> l2;

    # The naive path: walk the entire scene to flatten it.
    print("Approach A: full scene walk per render (the issue's hot path)");
    naive = NaiveFlatten();
    root spawn naive;
    render_frame("naive walk", naive);

    # The incremental path: mutate the scene, then only invalidate the
    # touched subtree instead of re-walking everything.
    print("\nApproach B: incremental invalidation on mutation");
    print("Mutating visibility of 'cube' and group_order of 'rig':");
    r1.visible = False;
    g2.group_order = 5;
    invalidator = MarkDirty();
    root spawn invalidator;
}

"""Continuation tokens bound to repository root, snapshot, scope, normalized request,
ordering, and resume position. A continuation reused after any binding change must
be rejected with a typed outcome; a valid continuation resumes deterministically.
"""

# --- Edge archetypes -------------------------------------------------------

edge OwnsSnapshot {
    has snapshot_id: str = "";
}

edge HoldsScope {
    has scope: str = "";
}

edge HoldsRequest {
    has normalized_query: str = "";
}

edge HoldsOrdering {
    has ordering: str = "";
}

# --- Node archetypes -------------------------------------------------------

node RepositoryRoot {
    has root_id: str = "";
}

node Snapshot {
    has snapshot_id: str = "";
}

node QueryScope {
    has scope: str = "";
}

node NormalizedRequest {
    has normalized_query: str = "";
}

node Ordering {
    has ordering: str = "";
}

node ContinuationToken {
    # The opaque public surface: a single-use resume handle.
    has token_id: str = "";
    has resume_position: int = 0;
    # Whether this token has already been consumed.
    has consumed: bool = False;
    # Whether this token has been declared stale.
    has stale: bool = False;
}

# --- Walker: validates and resumes a continuation --------------------------

walker ContinuationAudit {
    # The bindings the caller claims for this resume attempt.
    has claim_root_id: str = "";
    has claim_snapshot_id: str = "";
    has claim_scope: str = "";
    has claim_query: str = "";
    has claim_ordering: str = "";
    has claim_resume_position: int = -1;

    # Result captured during the walk.
    has outcome: str = "";
    has rows_resumed: int = 0;

    can start with Root entry {
        # Walk into the repository root via the owning typed edge.
        visit [->:OwnsSnapshot:->];
    }

    can bind_root with RepositoryRoot entry {
        if here.root_id != self.claim_root_id {
            self.outcome = "REJECTED_ROOT";
            disengage;
        }
        visit [->:OwnsSnapshot:->];
    }

    can bind_snapshot with Snapshot entry {
        if here.snapshot_id != self.claim_snapshot_id {
            self.outcome = "REJECTED_SNAPSHOT";
            disengage;
        }
        visit [->:HoldsScope:->];
    }

    can bind_scope with QueryScope entry {
        if here.scope != self.claim_scope {
            self.outcome = "REJECTED_SCOPE";
            disengage;
        }
        visit [->:HoldsRequest:->];
    }

    can bind_request with NormalizedRequest entry {
        if here.normalized_query != self.claim_query {
            self.outcome = "REJECTED_QUERY";
            disengage;
        }
        visit [->:HoldsOrdering:->];
    }

    can bind_ordering with Ordering entry {
        if here.ordering != self.claim_ordering {
            self.outcome = "REJECTED_ORDERING";
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can bind_token with ContinuationToken entry {
        # A consumed or stale token cannot be reused.
        if here.consumed {
            self.outcome = "REJECTED_CONSUMED";
            disengage;
        }
        if here.stale {
            self.outcome = "REJECTED_STALE";
            disengage;
        }
        if here.resume_position != self.claim_resume_position {
            self.outcome = "REJECTED_POSITION";
            disengage;
        }
        # Mark the token consumed on a successful resume.
        here.consumed = True;
        self.rows_resumed = here.resume_position;
        self.outcome = "RESUMED";
        disengage;
    }
}

# --- Walker: simulates a truncation result and surfaces its non-terminality -

walker TruncationProbe {
    has page_size: int = 0;
    has total_known: int = 0;
    has terminal_appearance: bool = False;

    can start with Root entry {
        # Truncation must never be reported as a terminal completeness signal.
        if self.page_size < self.total_known {
            self.terminal_appearance = False;
        } else {
            self.terminal_appearance = True;
        }
        visit [-->] else { disengage; };
    }
}

# --- Demonstration graph ---------------------------------------------------

with entry {
    # A repository owns a snapshot, which holds a scope, request, and ordering,
    # and finally the continuation token that resumes a paginated traversal.
    repo = RepositoryRoot(root_id="repo-7");
    snap = Snapshot(snapshot_id="snap-2024-11-01");
    scope = QueryScope(scope="public_symbols");
    req = NormalizedRequest(normalized_query="name:continuation AND kind:edge");
    order = Ordering(ordering="alpha:asc");
    tok = ContinuationToken(token_id="ct-1", resume_position=40);

    repo +>:OwnsSnapshot(snapshot_id="snap-2024-11-01"):+> snap;
    snap +>:HoldsScope(scope="public_symbols"):+> scope;
    scope +>:HoldsRequest(normalized_query="name:continuation AND kind:edge"):+> req;
    req +>:HoldsOrdering(ordering="alpha:asc"):+> order;
    order +>:HoldsOrdering:+> tok;

    # 1. Valid resume: every binding matches and the token is fresh.
    audit = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn audit;
    print(f"valid resume -> {audit.outcome}, rows={audit.rows_resumed}");

    # 2. Reused after snapshot change -> typed rejection.
    bad = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-02",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn bad;
    print(f"changed snapshot -> {bad.outcome}");

    # 3. Reused after query normalization -> typed rejection.
    bad_q = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation",
        claim_ordering="alpha:asc",
        claim_resume_position=40
    );
    repo spawn bad_q;
    print(f"changed query -> {bad_q.outcome}");

    # 4. Reused after resume position drift -> typed rejection.
    bad_p = ContinuationAudit(
        claim_root_id="repo-7",
        claim_snapshot_id="snap-2024-11-01",
        claim_scope="public_symbols",
        claim_query="name:continuation AND kind:edge",
        claim_ordering="alpha:asc",
        claim_resume_position=80
    );
    repo spawn bad_p;
    print(f"drifted position -> {bad_p.outcome}");

    # 5. Truncation is non-terminal by construction.
    probe = TruncationProbe(page_size=50, total_known=137);
    root spawn probe;
    flag_label = "TERMINAL" if probe.terminal_appearance else "TRUNCATED";
    print(f"truncation flag -> {flag_label}");
}

"""Game account moderation sweep.

Three archetypes in play:
  * ``Account``  - the base node carrying a reputation score and a flag for
                    whether the account holds moderator privileges.
  * ``Member``   - a regular player account.
  * ``Admin``    - a staff account whose reputation is boosted on audit.

Three walkers:
  * ``OrderAuditor`` walks the account chain from the lobby, auditing every
                    account it lands on. Member accounts are reported at
                    face value, Admin accounts have their reputation bumped
                    by +5 before the report.
  * ``Greeter``     is a welcome-desk bot. It visits every account node and
                    prints a greeting regardless of account subtype.

Typed edges are used so the audit chain is explicit (``OwnedBy``) and the
welcome desk can use a union trigger to greet Members and Admins with one
ability.
"""

node Account {
    has owner: str = "";
    has reputation: int = 0;
    has is_admin: bool = False;
}

node Member(Account) {}

node Admin(Account) {}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: beginning moderation sweep");
        visit [-->];
    }

    can sweep with Member entry {
        final_rep = here.reputation;
        label = "Member";
        print(f"[AUDIT] {label} {here.owner} -> reputation {final_rep}");
        visit [-->];
    }

    can audit with Admin entry {
        final_rep = here.reputation + 5;
        label = "Admin";
        print(f"[AUDIT] {label} {here.owner} -> reputation {final_rep}");
        visit [-->];
    }
}

walker Greeter {
    has desk_name: str = "Welcome Desk";

    can start with Root entry {
        print(f"{self.desk_name}: greeting all visitors");
        visit [-->];
    }

    can greet with Member entry {
        print(f"{self.desk_name}: hello, {here.owner}!");
        visit [-->];
    }

    can welcome with Admin entry {
        print(f"{self.desk_name}: hello, {here.owner}!");
        visit [-->];
    }
}

with entry {
    lobby = root;

    alice = Member(owner="Alice", reputation=42);
    bob = Admin(owner="Bob", reputation=80);
    carol = Member(owner="Carol", reputation=15);
    dave = Admin(owner="Dave", reputation=60);

    lobby ++> alice;
    lobby ++> bob;
    lobby ++> carol;
    lobby ++> dave;

    print("=== Moderation sweep ===");
    root spawn OrderAuditor();

    print("=== Welcome desk pass ===");
    root spawn Greeter(desk_name="Front Desk");
