"""Nika Core Product Factory: model ProductProjects and their dependency
graph, then audit them with a walker that classifies PR/pipeline state and
detects cycles in the PF dependency wave."""

# ----------------------------------------------------------------------
# Node archetypes: the durable entities on the dashboard.
# ----------------------------------------------------------------------

node ProductProject {
    has title: str = "";
    has head_sha: str = "";
    has gate_status: str = "PENDING";  # RED / GREEN-BUT-STALE / MERGE-READY / BLOCKED
    has core_evidence: bool = False;
    has m12_evidence: bool = False;
    has integrated: bool = False;
}

node ScheduledSlot {
    has task_id: str = "";
    has minute_of_hour: int = 0;
}

edge DependsOn {
    has wave: str = "PF";  # which dependency wave this edge belongs to
}

# ----------------------------------------------------------------------
# Walker: classify the PF wave and detect cycles via an explicit guard set
# (jac 0.36.1 walkers have no built-in dedupe on cyclic graphs). Each
# invocation is depth-bounded so the cyclic graph cannot run forever.
# ----------------------------------------------------------------------

walker PFAuditor {
    has max_steps: int = 12;
    has steps: int = 0;

    can start with Root entry {
        print("PF WAVE AUDIT — classifying dependency wave ...");
        visit [-->];
    }

    can classify with ProductProject entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            print("  [HALT] step budget exhausted (cycle-safe)");
            disengage;
        }
        if here.integrated {
            status = "INTEGRATED";
        } elif here.core_evidence and here.m12_evidence {
            status = "MERGE-READY";
        } else {
            status = here.gate_status;
        }
        head_short = here.head_sha[:8] if here.head_sha else "--------";
        print(f"  [PP] {here.title} @ {head_short} -> {status}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can classify_slot with ScheduledSlot entry {
        print(f"  [SLOT] {here.task_id} scheduled at minute :{here.minute_of_hour:02d}");
        visit [-->];
    }
}

# ----------------------------------------------------------------------
# Demo wiring.
# ----------------------------------------------------------------------

with entry {
    # Five durable ProductProjects in the dependency wave.
    pf1 = ProductProject(
        title="PF1-ProductProject",
        head_sha="a973b82e096f642f",
        gate_status="GREEN-BUT-STALE",
        core_evidence=True,
        m12_evidence=True,
    );
    pf2 = ProductProject(
        title="PF2-DynamicTeamComposer",
        head_sha="5f84e4c3380b0834",
        gate_status="MERGE-READY",
        core_evidence=True,
        m12_evidence=True,
        integrated=True,
    );
    pf3 = ProductProject(
        title="PF3-ExecutionNode",
        head_sha="0000000000000000",
        gate_status="RED",
        core_evidence=False,
        m12_evidence=False,
    );
    pf4 = ProductProject(
        title="PF4-IntegrationGatekeeper",
        head_sha="1111111111111111",
        gate_status="BLOCKED",
    );
    pf5 = ProductProject(
        title="PF5-CommandPresentation",
        head_sha="2222222222222222",
        gate_status="MERGE-READY",
        core_evidence=True,
        m12_evidence=True,
    );

    # Dependency wave (PF1 -> PF2 -> PF3 -> PF4 -> PF5). PF5 also depends
    # back on PF1 so the cycle guard has real work to do.
    pf1 +>:DependsOn(wave="PF"):+> pf2;
    pf2 +>:DependsOn(wave="PF"):+> pf3;
    pf3 +>:DependsOn(wave="PF"):+> pf4;
    pf4 +>:DependsOn(wave="PF"):+> pf5;
    pf5 +>:DependsOn(wave="PF"):+> pf1;

    # Scheduled slots with the staggered minute-of-hour values from the issue.
    slot1 = ScheduledSlot(task_id="PF1", minute_of_hour=5);
    slot2 = ScheduledSlot(task_id="PF2", minute_of_hour=17);
    slot3 = ScheduledSlot(task_id="PF3", minute_of_hour=29);
    slot4 = ScheduledSlot(task_id="PF4", minute_of_hour=41);
    slot5 = ScheduledSlot(task_id="PF5", minute_of_hour=53);

    # Mount the wave and the schedule under root.
    root ++> pf1 ++> slot1;
    root ++> pf2 ++> slot2;
    root ++> pf3 ++> slot3;
    root ++> pf4 ++> slot4;
    root ++> pf5 ++> slot5;

    # Run the auditor.
    root spawn PFAuditor();
}

"""TB-IR vs v1 whole-record-read parity for nested struct fields."""

node Inner {
    has a: int = 0;
}

node Outer {
    has r: int = 0;
}

node RecordDef {
    has name: str = "";
}

edge NestedField { }
edge DependsOn { }

walker FieldChainResolve {
    has depth: int = 0;
    has leaf_a: int = 0;
    has ok: bool = False;

    can resolve with Outer entry {
        self.depth = 1;
        visit [->:NestedField:->] else { disengage; };
    }

    can at_inner with Inner entry {
        self.depth = 2;
        self.leaf_a = here.a;
        self.ok = True;
        print(f"field chain: o.inner.a={self.leaf_a} depth={self.depth}");
        disengage;
    }
}

walker V1LetBind {
    has copied_a: int = 0;
    has ok: bool = False;

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can whole_read with Inner entry {
        self.copied_a = here.a;
        self.ok = True;
        print(f"v1: let d : Inner = o.inner -> d.a={self.copied_a} PASSED");
        disengage;
    }
}

walker TbirLetBind {
    has ok: bool = False;
    has reason: str = "";

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can reject_bind with Inner entry {
        self.ok = False;
        self.reason = "TB-IR rejects let d : Inner = o.inner";
        print(f"tbir: let d : Inner = o.inner -> REJECTED ({self.reason})");
        disengage;
    }
}

walker FieldCopyRead {
    has captured_a: int = 0;

    can from_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can take with Inner entry {
        self.captured_a = here.a;
        print(f"field read: o.inner.a={self.captured_a}");
        disengage;
    }
}

walker FieldCopyWrite {
    has source_a: int = 0;
    has done: bool = False;

    can into_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can paste with Inner entry {
        here.a = self.source_a;
        self.done = True;
        print(f"field write: p.inner = o.inner -> p.inner.a={here.a}");
        disengage;
    }
}

walker EmitOrder {
    has ordered: bool = False;

    can walk with RecordDef entry {
        if here.name == "Outer" {
            visit [->:DependsOn:->] else { disengage; };
        } elif here.name == "Inner" {
            self.ordered = True;
            print(f"emit order: Inner before Outer -> ordered={self.ordered}");
            disengage;
        } else {
            disengage;
        }
    }
}

with entry {
    inner_def = RecordDef(name="Inner");
    outer_def = RecordDef(name="Outer");
    root ++> inner_def;
    root ++> outer_def;
    outer_def +>:DependsOn:+> inner_def;

    src_inner = Inner(a=5);
    o = Outer(r=7);
    root ++> o;
    o +>:NestedField:+> src_inner;

    dst_inner = Inner(a=0);
    p = Outer(r=0);
    root ++> p;
    p +>:NestedField:+> dst_inner;

    chain = FieldChainResolve();
    o spawn chain;

    v1 = V1LetBind();
    o spawn v1;

    tbir = TbirLetBind();
    o spawn tbir;

    reader = FieldCopyRead();
    o spawn reader;
    writer = FieldCopyWrite(source_a=reader.captured_a);
    p spawn writer;

    emit = EmitOrder();
    outer_def spawn emit;

    parity_gap = v1.ok and not tbir.ok;
    print(f"parity gap v1 ok={v1.ok} tbir ok={tbir.ok} gap={parity_gap}");
    print(f"field-copy path works dst_a={dst_inner.a} writer done={writer.done}");
}

