"""Dependency audit walker: traverse the dependency graph and flag vulnerable packages.

Models the scenario from issue #9 — a hand-rolled dependency walker that
recursively visits each package's transitive dependencies, accumulates
vulnerability findings, and reports packages that should be patched or
migrated off. Uses typed edges for the depends-on relationship and a
walker with an explicit visited-set (Jac 0.36.1 has no built-in cycle
guard) to traverse without infinite loops on circular dependencies.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has available: bool = True;
}

# A package may pull in known advisories. Multiple findings per package.
node Advisory {
    has cve: str = "";
    has severity: str = "low";
    has title: str = "";
}

# Typed edge: the source package depends on the target package.
edge DependsOn {
    has kind: str = "runtime";
}

# Typed edge: a package ships a particular advisory finding.
edge HasAdvisory {
}

walker DependencyAuditor {
    # Cycle guard: jac 0.36.1 walkers do not dedupe nodes on cycles.
    has visited: list[str] = [];
    # Accumulated findings, reported at the end.
    has findings: list[dict] = [];

    can start with Root entry {
        print("Starting dependency audit from root");
        visit [-->];
    }

    # One ability per node type — keeps field access type-safe.
    can audit_pkg with Package entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        status = "OK" if here.available else "BLOCKED";
        print(f"[pkg] {here.name}@{here.version} -> {status}");
        visit [->:DependsOn:->];
    }

    can audit_adv with Advisory entry {
        if here.cve in self.visited {
            disengage;
        }
        self.visited.append(here.cve);
        finding = {
            "cve": here.cve,
            "severity": here.severity,
            "title": here.title,
        };
        self.findings.append(finding);
        print(f"[adv] {here.cve} ({here.severity}) {here.title}");
        visit [->:HasAdvisory:->];
    }
}

walker Patcher {
    has visited: list[str] = [];

    can start with Root entry {
        print("Patching vulnerable transitives");
        visit [-->];
    }

    can patch with Package entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);

        # CRA 5.0.1 is unmaintained: mark it as blocked and walk up its
        # dependency edges to mark transitively-vulnerable packages.
        if here.name == "react-scripts" {
            here.available = False;
            print(f"blocked {here.name}@{here.version} (deprecated toolchain)");
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    # The frontend root package.
    frontend = Package(name="frontend", version="0.0.1", available=True);
    root ++> frontend;

    # CRA 5.0.1 — the pinned, unmaintained toolchain.
    cra = Package(name="react-scripts", version="5.0.1", available=True);
    frontend +>:DependsOn(kind="dev"):+> cra;

    # Known vulnerable transitives from issue #9.
    nth_check = Package(name="nth-check", version="1.8.5", available=True);
    postcss = Package(name="postcss", version="8.4.16", available=True);
    wds = Package(name="webpack-dev-server", version="4.15.1", available=True);
    cra +>:DependsOn:+> nth_check;
    cra +>:DependsOn:+> postcss;
    cra +>:DependsOn:+> wds;

    # Advisories attached to those packages.
    cra +>:HasAdvisory:+> Advisory(
        cve="GHSA-rp65-9cf3-cjxr", severity="high",
        title="nth-check ReDoS via svgo"
    );
    cra +>:HasAdvisory:+> Advisory(
        cve="GHSA-7fh5-64p2-3v2j", severity="medium",
        title="postcss line-return parsing"
    );
    cra +>:HasAdvisory:+> Advisory(
        cve="GHSA-9jgg-88mc-972h", severity="high",
        title="webpack-dev-server source exfiltration"
    );

    # Introduce a cycle to prove the visited-set is doing real work.
    nth_check +>:DependsOn(kind="peer"):+> cra;

    auditor = DependencyAuditor();
    root spawn auditor;
    patcher = Patcher();
    root spawn patcher;

    critical_count = 0;
    for f in auditor.findings {
        if f["severity"] == "high" {
            critical_count += 1;
        }
    }
    print(
        f"audit complete: {len(auditor.findings)} advisories, "
        f"{critical_count} high-severity, "
        f"{len(auditor.visited)} nodes visited"
    );
}
