"""Person-following agentic blueprint: model a robot's person-tracker as
a graph of detections, tracks, and lost persons; cascade-invalidate when
a transport dies so stale tracks don't linger."""

node Frame {
    has frame_id: int = 0;
    has captured_at: str = "";
}

node Detection {
    has class_name: str = "";
    has confidence: float = 0.0;
    has bbox_area: float = 0.0;
}

node Track {
    has track_id: int = 0;
    has status: str = "active";
    has lost_frames: int = 0;
}

node Person {
    has person_name: str = "";
    has last_seen: str = "";
}

# A detection came out of a frame.
edge FromFrame { }

# A detection was associated to a track (the tracker's hypothesis).
edge AssociatedTo { has score: float = 0.0; }

# A track represents a person over time.
edge Represents { }

# A transport (camera/broker) that the blueprint relies on.
node Transport {
    has transport_name: str = "";
    has alive: bool = True;
}

# A blueprint depends on a transport to function.
edge DependsOn { }

walker Tracker {
    has max_lost_frames: int = 3;
    has invalidated: list[int] = [];

    can start with Root entry {
        print(f"Tracker starting (max_lost={self.max_lost_frames})");
        visit [->:DependsOn:->];
    }

    # Check each transport. If it died, cascade-invalidate every track
    # that depended on it (simulating: the broker is down, the SAM2
    # extension was broken, so all person tracks must be dropped).
    can audit with Transport entry {
        if not here.alive {
            print(f"transport '{here.transport_name}' is DOWN -> invalidating dependent tracks");
            visit [-->];
        } else {
            print(f"transport '{here.transport_name}' healthy");
            visit [-->];
        }
    }

    # A dead transport's dependents are tracks; invalidate them.
    can kill_tracks with Track entry {
        if here.status == "active" {
            here.status = "invalidated";
            self.invalidated.append(here.track_id);
            print(f"  track #{here.track_id} invalidated");
        }
        visit [-->];
    }
}

# A separate walker verifies which persons still have a live track.
# This mirrors the "did we lose the person?" check from the issue.
walker PersonAuditor {
    has reachable: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_person with Person entry {
        # walk: person -> Represents -> Track
        visit [->:Represents:->];
    }

    # Once we know the track, see whether any of its detections are
    # still attached. If none, the person was "lost" after the
    # transport died (the tracker couldn't keep up).
    can tally with Track entry {
        track_status = here.status;
        status = "REACHABLE" if track_status == "active" else "LOST";
        label = "reachable" if track_status == "active" else "lost";
        if track_status == "active" {
            self.reachable.append("reachable");
        }
        print(f"person via track #{here.track_id}: {status} ({label})");
        visit [-->];
    }
}

with entry {
    # Two transports: one alive (the working camera), one dead
    # (the broker that the default.env bug silenced).
    cam = Transport(transport_name="realsense");
    broker = Transport(transport_name="broker", alive=False);
    root +>:DependsOn:+> cam;
    root +>:DependsOn:+> broker;

    # A person and an active track that the broken broker used to feed.
    alice = Person(person_name="alice", last_seen="t=0");
    bob = Person(person_name="bob", last_seen="t=1");
    root ++> alice ++> bob;

    t1 = Track(track_id=1, status="active");
    t2 = Track(track_id=2, status="active");
    t3 = Track(track_id=3, status="active");
    alice +>:Represents:+> t1;
    bob   +>:Represents:+> t2;

    # t3 is reachable via a healthy transport; t1/t2 were broker-fed.
    cam    +>:DependsOn:+> t3;

    # Detections associated to tracks with scores.
    d1 = Detection(class_name="person", confidence=0.91, bbox_area=0.21);
    d2 = Detection(class_name="person", confidence=0.83, bbox_area=0.18);
    t1 +>:AssociatedTo(score=0.91):+> d1;
    t2 +>:AssociatedTo(score=0.83):+> d2;

    f1 = Frame(frame_id=1001, captured_at="t=0.0");
    f2 = Frame(frame_id=1002, captured_at="t=0.5");
    d1 +>:FromFrame:+> f1;
    d2 +>:FromFrame:+> f2;

    # Keep a reference so we can read its accumulated state after spawn.
    tracker = Tracker(max_lost_frames=3);
    print("--- cascade-invalidate run ---");
    root spawn tracker;
    print(f"invalidated track ids: {tracker.invalidated}");

    auditor = PersonAuditor();
    print("--- reachability audit ---");
    root spawn auditor;
    print(f"reachable count: {len(auditor.reachable)}");
}
