"""RBAC audit event infrastructure modeled as a graph: posture/policy nodes
carry typed payloads, ingestion sync events track success/error, and a
disconnected-cluster walker queues events and replays them when the cluster
returns. A cycle hunter traverses the ingestion connector dependency graph
to detect circular triggers."""

# ---------- Entity archetypes ----------

node AuditEvent {
    has event_id: str = "";
    has event_type: str = "";
    has actor: str = "";
    has timestamp: str = "";
}

node PostureChangeEvent(AuditEvent) {
    has before: str = "";
    has after: str = "";
}

node PolicyCrudEvent(AuditEvent) {
    has policy_id: str = "";
    has action: str = "";
}

node IngestionSyncEvent(AuditEvent) {
    has connector: str = "";
    has asset_count: int = 0;
    has success: bool = True;
    has error: str = "";
}

node QueuedEvent {
    has event_type: str = "";
    has payload: str = "";
}

# ---------- Edge archetypes ----------

edge EmittedBy { }
edge Triggered { }
edge QueuedIn { }
edge ReplayedTo { }

# ---------- Walker: Auditor traverses the audit log chain ----------

walker Auditor {
    has seen: list[str] = [];
    has duplicates: int = 0;
    has dedupe: dict[str, int] = {};

    can start with Root entry {
        print("Auditor starting at root; expecting AuditEvent chain");
        visit [-->];
    }

    can audit with AuditEvent entry {
        if here.event_id in self.dedupe {
            self.duplicates += 1;
            print(f"  [DUP] {here.event_type} id={here.event_id} already logged");
            visit [-->];
            return;
        }
        self.dedupe[here.event_id] = 1;
        self.seen.append(here.event_type);
        status = "FAIL" if here.event_type.startswith("sync-error") else "OK";
        print(f"  [{status}] {here.event_type} actor={here.actor} t={here.timestamp}");
        visit [-->];
    }
}

# ---------- Walker: Disconnected cluster -- queue then replay ----------

walker DisconnectedReplayer {
    has queued: list[QueuedEvent] = [];
    has replayed: int = 0;
    has dropped_on_full: int = 0;
    has queue_capacity: int = 5;
    has max_hops: int = 50;

    can start with Root entry {
        print(f"Cluster OFFLINE -> local queue capacity={self.queue_capacity}");
        visit [->:QueuedIn:->];
    }

    can collect with QueuedEvent entry {
        if len(self.queued) >= self.queue_capacity {
            self.dropped_on_full += 1;
            print(f"  [DROP] queue full, evicting {here.event_type}");
            visit [-->];
            return;
        }
        self.queued.append(here);
        self.replayed += 1;
        print(f"  [ENQ] {here.event_type} payload={here.payload}");
        visit [-->];
    }
}

# ---------- Walker: Cycle detection across ingestion connectors ----------

walker CycleHunter {
    has path: list[str] = [];
    has cycles: list[str] = [];
    has max_steps: int = 10;
    has steps: int = 0;

    can start with Root entry {
        print("CycleHunter traversing ingestion connector graph");
        visit [-->];
    }

    can probe with IngestionSyncEvent entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            print("  [STOP] step cap reached");
            disengage;
        }
        if here.connector in self.path {
            cycle_label = " -> ".join(self.path) + " -> " + here.connector;
            self.cycles.append(cycle_label);
            print(f"  [CYCLE] back to {here.connector}");
            disengage;
        }
        self.path.append(here.connector);
        print(f"  [VISIT] {here.connector} (path len={len(self.path)})");
        visit [->:Triggered:->] else { disengage; }
    }
}

# ---------- Demonstration wiring ----------

with entry {
    # Build a small audit log chain on root.
    root ++> PostureChangeEvent(
        event_id="evt-001", event_type="posture-changed",
        actor="alice", timestamp="2025-01-01T00:00:00Z",
        before="open", after="restricted"
