    has immutable: bool = True;
    has origin_revision: int = 0;
    has action: str = "";
    has status: str = "";
    has same_workspace: bool = True;
}

node TopologyNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has marked: bool = False;
}

edge Head {
    has expected_revision: int = 0;
}

edge History { }

edge Next {
    has sequence: int = 0;
}

edge Snapshot {
    has purpose: str = "";
}

edge Origin {
    has reason: str = "";
}

edge Child {
    has order: int = 0;
}

walker HistoryAuditor {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_workspace with Workspace entry {
        print(f"history for {here.name}");
        visit [->:History:->] else { disengage; }
    }

    can inspect_revision with Revision entry {
        print(f"revision {here.revision_no}: {here.action}, immutable={here.immutable}");
        visit [->:Next:->] else { disengage; }
    }
}

walker TopologyAuditor {
    has cycle_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_workspace with Workspace entry {
        head_result = "CAS accepted"
            if here.current_head == here.expected_head + 1
            else "CAS conflict";
        print(f"{here.name}: {head_result}, current head={here.current_head}");
        visit [->:Head:->] else { disengage; }
    }

    can inspect_revision with Revision entry {
        print(f"carrying topology from fresh revision {here.revision_no}");
        visit [->:Snapshot:->] else { disengage; }
    }

    can inspect_topology with TopologyNode entry {
        if here.marked {
