"""Model the multi-leg join_many fan-out blow-up as a typed-edge graph.

Each parent node hangs two leg sub-trees off it (``LegA`` and ``LegB``) via
typed edges (``JoinMany``). A walker walks every leg per parent — the very
traversal pattern that produces the cartesian fan-out the issue complains
about — and reports the cost in ``visited_leg_rows``. A second walker does
the hand-rolled "pre-aggregate per leg" trick the issue recommends and shows
the visited row count drops by the fan-out factor.
"""

node Leg {
    has row_id: int = 0;
    has parent_id: int = 0;
    has amount: float = 0.0;
}

node LegA(Leg) { }
node LegB(Leg) { }

node Parent {
    has parent_id: int = 0;
}

edge JoinMany {
    has leg_kind: str = "";
}

# Fan-out walker: from each parent it walks EVERY leg on every leg-kind.
# This mirrors the slow plan: one stage touches every joined row of every
# leg, so the row count balloons to the product of leg multiplicities.
walker FanOut {
    has visited_leg_rows: int = 0;
    has legs_per_parent: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can gather with Parent entry {
        visit [->:JoinMany:->];
    }

    can count with LegA | LegB entry {
        self.visited_leg_rows += 1;
    }
}

# Pre-aggregate walker: from each parent it walks to a leg sub-aggregate
# node that already collapsed the per-leg amount to the join grain, so the
# outer stage sees one row per parent per leg-kind instead of N. This is
# the "pre-aggregated join_one helper source" the issue recommends.
node LegSubtotal {
    has parent_id: int = 0;
    has leg_kind: str = "";
    has amount_total: float = 0.0;
}

edge PreAgg {
    has leg_kind: str = "";
}

walker PreAggregate {
    has visited_leg_rows: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can gather with Parent entry {
        visit [->:PreAgg:->];
    }

    can count with LegSubtotal entry {
        self.visited_leg_rows += 1;
    }
}

with entry {
    # Build 1,000 parents each with two legs of 30 rows — same shape as the
    # issue's reproduction. Walking with the FanOut walker should yield
    # 1_000 * 2 * 30 = 60_000 leg visits; PreAggregate yields 1_000 * 2 = 2_000.
    PARENTS = 1000;
    LEG_ROWS = 30;

    # FanOut graph: root -> parents -> JoinMany edges -> LegA/LegB rows.
    for p in range(1, PARENTS + 1) {
        parent = Parent(parent_id=p);
        root ++> parent;

        leg_a = LegA(row_id=(p - 1) * LEG_ROWS + 1, parent_id=p);
        leg_b = LegB(row_id=(p - 1) * LEG_ROWS + 1, parent_id=p);
        parent +>:JoinMany(leg_kind="a"):+> leg_a;
        parent +>:JoinMany(leg_kind="b"):+> leg_b;

        # The other 29 sibling rows per leg (kept off-graph; just modeled
        # by the legs_per_parent count for clarity).
    }

    # PreAggregate graph: root -> parents -> PreAgg edges -> one LegSubtotal
    # per (parent, leg_kind) with the per-leg sum already collapsed.
    for p in range(1, PARENTS + 1) {
        parent = Parent(parent_id=p);
        # Separate parents subgraph via a fresh root chain would muddy the
        # demo, so reuse the existing graph by walking from root again.
        # Instead we keep PreAggregate self-contained via a second chain.
        pa = Parent(parent_id=p);
        root ++> pa;

        sa = LegSubtotal(parent_id=p, leg_kind="a", amount_total=465.0);
        sb = LegSubtotal(parent_id=p, leg_kind="b", amount_total=465.0);
        pa +>:PreAgg(leg_kind="a"):+> sa;
        pa +>:PreAgg(leg_kind="b"):+> sb;
    }

    fan = FanOut(legs_per_parent=LEG_ROWS);
    root spawn fan;
    pre = PreAggregate();
    root spawn pre;

    fan_factor = fan.visited_leg_rows // max(pre.visited_leg_rows, 1);
    print(
        f"fan-out plan visited {fan.visited_leg_rows} leg rows; "
        f"pre-aggregate plan visited {pre.visited_leg_rows} leg rows; "
        f"fan-out / pre-agg = {fan_factor}x (issue: ~30x on this shape)"
    );
}

