"""LIRE (Local Incremental Rebalancing) for vector index clusters.

Models the essential scenario from apache/hudi issue #19500: after Tier-1
vector compaction, local cluster geometry drifts and must be rebalanced.
LIRE evaluates ClusterStats triggers, splits oversized clusters via local
balanced 2-means, merges undersized ones into surviving centroids, and
publishes replacement centroids/postings/tombstones in one MDT delta
commit.  Cache identity is keyed by index partition + generation + pinned
MDT instant; no centroid epoch is persisted.
"""

node Cluster {
    has cluster_id: str = "";
    has centroid: list[float] = [0.0, 0.0];
    has size: int = 0;
    has residual_budget: int = 64;
}

node Vector {
    has vector_id: str = "";
    has coords: list[float] = [0.0, 0.0];
}

node Replacement {
    has replacement_id: str = "";
    has source_id: str = "";
    has centroid: list[float] = [0.0, 0.0];
}

node Tombstone {
    has victim_id: str = "";
    has reason: str = "";
}

node ClusterStats {
    has split_threshold: int = 0;
    has merge_threshold: int = 0;
    has skew: float = 0.0;
    has mismatches: int = 0;
}

node IndexPartition {
    has partition_name: str = "";
    has generation: int = 0;
    has pinned_instant: str = "";
}

edge TouchedByMaintenance { has op: str = ""; }
edge Owns { }
edge ReplacedBy { }
edge Surfaces { }

walker LireRebalancer {
    has op_label: str = "maintenance";
    has visited: list[str] = [];
    has rebalances: int = 0;
    has splits: int = 0;
    has merges: int = 0;
    has mismatch_count: int = 0;

    can start with Root entry {
        print("== LIRE rebalance pass ==");
        visit [-->];
    }

    can inspect_partition with IndexPartition entry {
        print(
            f"partition={here.partition_name} gen={here.generation} "
            f"pinned={here.pinned_instant}"
        );
        visit [-->];
    }

    can collect_stats with ClusterStats entry {
        here.skew = 1.7;
        here.split_threshold = 8;
        here.merge_threshold = 2;
        print(
            f"ClusterStats skew={here.skew} "
            f"split>={here.split_threshold} merge<{here.merge_threshold}"
        );
        visit [-->];
    }

    can consider_cluster with Cluster entry {
        if here.cluster_id in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.cluster_id);

        if here.size >= 8 {
            self.splits += 1;
            self.rebalances += 1;
            tag = "SPLIT";
        } elif here.size <= 2 and here.size > 0 {
            self.merges += 1;
            self.rebalances += 1;
            tag = "MERGE";
        } else {
            tag = "KEEP";
        }
        print(f"cluster={here.cluster_id} size={here.size} -> {tag}");
        visit [-->];
    }

    can observe_replacement with Replacement entry {
        here.centroid = [-3.0, -3.0];
        print(
            f"  replacement={here.replacement_id} "
            f"src={here.source_id} centroid={here.centroid}"
        );
        visit [-->];
    }

    can observe_tombstone with Tombstone entry {
        print(
            f"  tombstone victim={here.victim_id} reason={here.reason}"
        );
        visit [-->];
    }
}

walker MismatchObserver {
    has tally: dict[str, int] = {};

    can start with Root entry {
        visit [-->];
    }

    can inspect_stats with ClusterStats entry {
        here.mismatches = 4;
        self.tally["mismatches"] = here.mismatches;
        print(
            f"coarse-routing mismatches={here.mismatches} "
            f"-> trigger rebuild"
        );
    }
}

with entry {
    part = IndexPartition(
        partition_name="vec-part-0", generation=3, pinned_instant="mdt-20240501"
    );
    stats = ClusterStats();
    big = Cluster(cluster_id="C-big", size=11, centroid=[9.0, 9.0]);
    mid = Cluster(cluster_id="C-mid", size=5, centroid=[0.0, 0.0]);
    small = Cluster(
        cluster_id="C-small", size=1, centroid=[7.0, -2.0]
    );

    rep_big = Replacement(
        replacement_id="C-big-A", source_id="C-big", centroid=[9.0, 9.0]
    );
    rep_big_b = Replacement(
        replacement_id="C-big-B", source_id="C-big", centroid=[10.0, 10.0]
    );
    tomb_big = Tombstone(victim_id="C-big", reason="split-replaced");

    rep_small = Replacement(
        replacement_id="C-mid-merge", source_id="C-small",
        centroid=[0.0, 0.0]
    );
    tomb_small = Tombstone(victim_id="C-small", reason="merge-absorbed");

    root +>:TouchedByMaintenance(op="compaction"):+> part;
    part +>:Surfaces:+> stats;
    part +>:Owns:+> big;
    part +>:Owns:+> mid;
    part +>:Owns:+> small;

    big +>:ReplacedBy:+> rep_big;
    big +>:ReplacedBy:+> rep_big_b;
    rep_big +>:Surfaces:+> tomb_big;
    rep_big_b +>:Surfaces:+> tomb_big;

    small +>:ReplacedBy:+> rep_small;
    rep_small +>:Surfaces:+> tomb_small;

    rebalancer = LireRebalancer();
    root spawn rebalancer;
    print(
        f"rebalances={rebalancer.rebalances} "
        f"splits={rebalancer.splits} merges={rebalancer.merges}"
    );

    observer = MismatchObserver();
    root spawn observer;
    print(f"mismatch_tally={observer.tally}");
}

"""Invitation acceptance: pending → accepted transition at edge tier.

Models a playlist owner who issues an invitation to a recipient, and a
recipient walker that observes the invitation, attempts to accept it, and
walks the relation graph. Mirrors the issue's local-update / wait-for-edge
scenario where a transaction is allocated, local acceptance is admitted,
but the edge-tier settlement is the contested step.
"""

node User {
    has user_id: str = "";
    has role: str = "member";
}

node Playlist {
    has title: str = "";
    has owner_id: str = "";
}

node Invitation {
    has inv_id: str = "";
    has subject: str = "";
    has role: str = "listener";
    has status: str = "pending";
    has tx_id: str = "";
}

edge Owns {}
edge PendingInvite {}
edge AcceptedInvite {}

walker Recipient {
    has session_user: str = "";
    has receipt_deadline: int = 10;
    has current_status: str = "pending";
    has edge_settled: bool = False;

    def start -> None {
        self.session_user = "alice";
    }

    def observe(inv: Invitation) -> str {
        return inv.status;
    }

    def attempt_accept(inv: Invitation) -> str {
        # Old-state guard: subject matches and status is pending.
        if inv.subject == self.session_user and inv.status == "pending" {
            # Self-EXISTS over pre-update snapshot keeps the row pending in
            # the new-state predicate while the adjacent predicate accepts it.
            # Contradiction surfaces as no edge-tier settlement.
            new_status = "accepted";
            inv.status = new_status;
            inv.tx_id = "tx-1907";
            self.current_status = new_status;
            self.edge_settled = False;
            return new_status;
        }
        return inv.status;
    }

    def wait_for_edge() -> bool {
        # Bounded receipt deadline; no mutation error, just never settles.
        self.edge_settled = False;
        return self.edge_settled;
    }

    can begin with Root entry {
        visit [-->];
    }

    can look with Playlist entry {
        visit [->:PendingInvite:->];
    }

    can decide with Invitation entry {
        before = self.observe(here);
        after = self.attempt_accept(here);
        settled = self.wait_for_edge();
        print(
            f"invitation {here.inv_id}: {before} -> {after} "
            f"(tx={here.tx_id}, settled={settled})"
        );
        visit [-->];
    }
}

with entry {
    owner = User(user_id="bob", role="owner");
    recipient = User(user_id="alice", role="member");
    pl = Playlist(title="Late Night Jazz", owner_id="bob");
    inv = Invitation(
