"""Hosted review workflow status mismatch: model the workflow→parser status contract.

The hosted review workflow writes ``status: "timeout"`` when the ``timeout``
command returns rc 124/137, but the control-plane job result parser only
accepts ``timed_out``. The mismatch causes the control plane to reject the
callback payload as ``invalid review result status "timeout"``. This demo
models the canonical statuses, the workflow emitter, and a status auditor
walker that traverses the emitted artifacts to verify the contract.
"""

# ---- Canonical statuses (control-plane vocabulary) ------------------------
node Approved { has reviewer: str = ""; }
node ChangesRequested { has reviewer: str = ""; }
node Failed { has reason: str = ""; }
node TimedOut { has after_seconds: int = 0; }
node Unparseable { has raw: str = ""; }

# Anything not matching a canonical status collapses to this.
node Unknown { has raw: str = ""; }

# ---- Workflow artifact nodes ----------------------------------------------
node Workflow {
    has name: str = "";
}

node ResultFile {
    has path: str = "/tmp/herd-review-command-result.json";
    has payload: str = "";
}

node ReportStep {
    has allow_list: str = "";
}

# ---- Typed edges: who produced what ---------------------------------------
edge Emits {
    has at: str = "";
}

edge ParsedBy {
    has at: str = "";
}

# ---- Walker: traverse a workflow and audit its emitted statuses -----------
walker Auditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Workflow entry {
        print(f"Auditing workflow: {here.name}");
        visit [->:Emits:->];
    }

    can inspect_result with ResultFile entry {
        # Naively extract the ``status`` value from the JSON payload.
        payload = here.payload;
        start = payload.find('"status":"') + len('"status":"');
        end = payload.find('"', start);
        status_value = payload[start:end] if start >= len('"status":"') else "";
        verdict = "ok" if status_value == "timed_out" else "MISMATCH";
        self.findings.append(f"{here.path} -> {status_value} ({verdict})");
        print(f"  result file {here.path}: status={status_value} [{verdict}]");
        visit [->:ParsedBy:->];
    }

    can inspect_parser with ReportStep entry {
        # Verify the report step's shell ``case`` allow-list mentions timed_out.
        allow = here.allow_list;
        ok = ("timed_out" in allow) and ("timeout" not in allow or "timeout" in allow and "timed_out" in allow);
        verdict = "ok" if ok else "MISMATCH";
        self.findings.append(f"report allow-list -> '{allow}' ({verdict})");
        print(f"  report allow-list: '{allow}' [{verdict}]");
    }
}

with entry {
    # Build a workflow that emits the BROKEN payload (``timeout`` instead of
    # ``timed_out``) and an allow-list that still admits ``timeout``.
    broken_wf = Workflow(name="herd-review (pre-fix)");
    bad_result = ResultFile(
        payload='{"status":"timeout","summary":"Herd Review timed out after 900s"}'
    );
    bad_report = ReportStep(
        allow_list="approved|changes_requested|failed|timeout|unparseable"
    );
    broken_wf +>:Emits(at="workflow_step"):+> bad_result;
    broken_wf +>:Emits(at="workflow_step"):+> bad_report;
    bad_result +>:ParsedBy(at="controlplane"):+> bad_report;

    # Build a workflow that emits the CORRECT payload and allow-list.
    fixed_wf = Workflow(name="herd-review (post-fix)");
    good_result = ResultFile(
        payload='{"status":"timed_out","summary":"Herd Review timed out after 900s"}'
    );
    good_report = ReportStep(
        allow_list="approved|changes_requested|failed|timed_out|unparseable"
    );
    fixed_wf +>:Emits(at="workflow_step"):+> good_result;
    fixed_wf +>:Emits(at="workflow_step"):+> good_report;
    good_result +>:ParsedBy(at="controlplane"):+> good_report;

    root ++> broken_wf ++> fixed_wf;

    auditor = Auditor();
    root spawn auditor;

    print("\n--- audit summary ---");
    for finding in auditor.findings {
        print(finding);
    }
}

"""License audit walker.

Models a package's dependency graph and walks it to flag any transitive
dependency whose declared license is outside an allowlist.  Mirrors the
hand-rolled traversal that a license-audit CI job would otherwise have
to perform against a registry of declared licenses.
"""

node Package {
    has name: str = "";
    has version: str = "0.0.0";
    has license: str = "";
}

# A typed edge declares "this package depends on that one".
# Keeping the relationship on a typed edge lets the walker traverse
# the graph with `visit [->:DependsOn:->]` instead of a hand-rolled
# recursion through an id-keyed adjacency map.
edge DependsOn { }

# The walker carries the policy state: the allowlist it is auditing
# against, plus the findings it has collected so far.  `self.flagged`
# is the single exit `report`-style accumulator the walker exposes.
walker LicenseAuditor {
    has allowed: list[str] = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"];
    has flagged: list[tuple[str, str, str]] = [];
    # (root_name, dep_name, license) triples found to be non-compliant

    # Guard against cycles: a package can be reached from multiple
    # parents, and the source graph may have cycles.  We track every
    # package we have already visited and skip them on revisit.
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        # Mark this package as audited so a cycle back to it is a no-op.
        self.visited.append(here.name);

        # If this package's declared license is not on the allowlist,
        # record a finding.  The root name (the project being shipped)
        # is whatever node we entered from; in this demo we attribute
        # every finding to the demo's root project name "DateExt".
        verdict = "OK" if here.license in self.allowed else "FLAG";
        if verdict == "FLAG" {
            self.flagged.append(("DateExt", here.name, here.license));
        }
        print(f"[{verdict}] {here.name}@{here.version} -- {here.license}");

        # Forward traversal: walk only DependsOn edges so we don't
        # follow unrelated links.  Guard against revisiting.
        for child in [->:DependsOn:->] {
            if child.name not in self.visited {
                visit child;
            }
        }
    }
}

with entry {
    # Build a small dependency graph for a fictional MIT-licensed
    # datetime library.  Most deps are MIT/BSD/Apache, but two
    # transitive deps sneak in with copyleft / business-source
    # licenses -- exactly the procurement risk the issue describes.
    dateext = root ++> Package(name="DateExt", version="1.0.0", license="MIT");

    timezone = Package(name="TimeZoneDB", version="2.3.1", license="MIT");
    isochrono = Package(name="IsoChrono", version="0.9.0", license="Apache-2.0");
    legacycal = Package(name="LegacyCal", version="1.4.0", license="GPL-3.0");
    copyleft_helper = Package(name="CopyleftHelper", version="0.1.2", license="AGPL-3.0");
    bizcal = Package(name="BizCal", version="2024.07", license="BUSL-1.1");
    legacycalcore = Package(name="LegacyCalCore", version="0.5.0", license="BSD-3-Clause");

    dateext +>:DependsOn:+> timezone;
    dateext +>:DependsOn:+> isochrono;
    dateext +>:DependsOn:+> legacycal;

    # IsoChrono pulls in a copyleft helper transitively.
    isochrono +>:DependsOn:+> copyleft_helper;

    # TimeZoneDB pulls in a business-source package -- another no-go.
    timezone +>:DependsOn:+> bizcal;

    # A cycle: LegacyCal -> LegacyCalCore -> LegacyCal.  The walker's
    # `visited` list ensures we don't loop forever auditing it.
    legacycal +>:DependsOn:+> legacycalcore;
    legacycalcore +>:DependsOn:+> legacycal;

    auditor = LicenseAuditor();
    root spawn auditor;

    print("");
    print(f"Allowlist: {auditor.allowed}");
    print(f"Flagged transitive deps: {auditor.flagged}");
}

