"""Normalize elimination pass: model the Mu-under-Cut redex as a graph and walk it.

Three node archetypes stand in for the Lean surface terms: a Producer (the
left side of a redex, holding a `Mu`-binder), a Cut statement (the redex
site), and a Consumer (the continuation downstream of the cut). The typed
edge `Rewritten` carries the substitution that a normalization step applies;
walking `Rewritten` from root to leaves reproduces the substitution-rewritten
recursion that blocks the Tier-2 termination proof (recursion is on the
*output* of the substitution, not on a structural sub-term of the input).
A second walker proves that after the elimination pass no `Mu`-under-`Cut`
redex remains reachable — the "no residual redex" invariant the issue
asks for.
"""

node Term {
    has label: str = "";
    has mu_count: int = 0;
    has eliminated: bool = False;
    has forwarded: bool = False;
}

node Producer {
    has label: str = "";
    has mu_count: int = 0;
}

node Cut {
    has label: str = "";
    has eliminated: bool = False;
}

node Consumer {
    has label: str = "";
}

node LabelJoin {
    has label: str = "";
    has forwarded: bool = False;
}

edge Rewritten {
    has kind: str = "";
    has swapped_uniq: int = 0;
}

walker NormalizePass {
    has visited: list[str] = [];
    has redex_found: bool = False;

    can start with Root entry {
        visit [->:Rewritten:->];
    }

    can normalize with Producer entry {
        self.visited.append(here.label);
        if here.mu_count > 0 {
            self.redex_found = True;
            print(f"[normalize] walking redex rooted at {here.label}");
        }
        visit [->:Rewritten:->];
    }

    can normalize_cut with Cut entry {
        self.visited.append(here.label);
        if not here.eliminated {
            print(f"[normalize] cut {here.label} still pending");
        }
        visit [->:Rewritten:->];
    }

    can normalize_consumer with Consumer entry {
        self.visited.append(here.label);
        visit [->:Rewritten:->];
    }

    can normalize_join with LabelJoin entry {
        self.visited.append(here.label);
        visit [->:Rewritten:->];
    }
}

walker ResidualCheck {
    has bad_sites: list[str] = [];

    can start with Root entry {
        visit [->:Rewritten:->];
    }

    can audit with Producer entry {
        if here.mu_count > 0 {
            self.bad_sites.append(here.label);
        }
        visit [->:Rewritten:->];
    }

    can audit_cut with Cut entry {
        if not here.eliminated {
            print(f"[residual] cut {here.label} not eliminated");
        }
        visit [->:Rewritten:->];
    }

    can audit_label with LabelJoin entry {
        if here.forwarded {
            print(f"[residual] label-join {here.label} still forwarding");
        }
        visit [->:Rewritten:->];
    }

    can audit_consumer with Consumer entry {
        visit [->:Rewritten:->];
    }
}

with entry {
    p_mu = Producer(label="p_mu", mu_count=2);
    cut_a = Cut(label="mu/cut#A");
    cut_b = Cut(label="mu/cut#B", eliminated=True);
    consumer = Consumer(label="downstream");
    label_join = LabelJoin(label="LJ");

    root +>:Rewritten(kind="subst", swapped_uniq=7):+> p_mu;
    p_mu +>:Rewritten(kind="cut-open"):+> cut_a;
    cut_a +>:Rewritten(kind="forward"):+> consumer;
    consumer +>:Rewritten(kind="join"):+> label_join;
    label_join +>:Rewritten(kind="tail"):+> cut_b;

    print("--- NormalizePass ---");
    pass_walker = NormalizePass();
    root spawn pass_walker;

    print("--- ResidualCheck ---");
    auditor = ResidualCheck();
    root spawn auditor;
    if len(auditor.bad_sites) == 0 {
        print("no residual Mu-under-Cut redex reachable");
    } else {
        print(f"residual producers: {auditor.bad_sites}");
    }
}

