"""GraphRAG result-attribution vs audited-evidence reconciliation.

Models the core scenario from issue #1136:
- Two search modes (local hop, global semantic) each yield hits that are
  mapped to communities. Local search advertises hop-radius exploration
  but actually filters one community's members; global search advertises
  semantic community formation but actually ranks pre-formed communities.
- Hits carry result attribution (entity, community, relevance) -- NOT
  evidence/provenance. The wire field is `attributions` (breaking rename
  from `sources`); an ADR-059 stub records that audited evidence is
  reserved for a future implementation.
- Optional `relationships` are induced explicit edges among already-
  returned entities and are NOT supplied to answer synthesis.
- Community summaries may be cached, but answer synthesis is per-query
  (the "first query is slowest" claim is unsupported).

Walker `Reconciler` walks the typed response graph and emits one exit
report distinguishing what the code actually does from what the docs
claim, plus the single breaking wire rename.
"""

# ---------- Node archetypes ----------

node Entity {
    has name: str = "";
    has kind: str = "";
}

node Community {
    has name: str = "";
    has summary: str = "";
    has summary_cached: bool = True;
}

# Hits are produced by the two search modes and mapped to a community.
node Hit {
    has entity_ref: str = "";
    has community_ref: str = "";
    has relevance: float = 0.0;
}

# The local/global response itself: typed result attribution only.
node Response {
    has mode: str = "";
    has answer: str = "";
    has answer_from_llm: bool = False;
    has llm_degraded: bool = False;
    has template_floor: bool = True;

    def claim_cached_first_query_honest() -> bool {
        return False;
    }
}

# ADR-059 stub: audited evidence/provenance retrieval is reserved,
# NOT implemented by this code path.
node AuditedEvidence {
    has status: str = "reserved-for-ADR-059";
}

# Induced explicit edges among already-returned entities. Optional
# returned context only; not synthesis prompt input, not traversal.
node RelationshipHint {
    has from_entity: str = "";
    has to_entity: str = "";
}

# ---------- Typed edges ----------

# An entity BELONGS TO a community (community membership).
edge BelongsTo { }

# A hit ATTRIBUTES to an entity + a community. Wire spelling: attributions.
edge AttributedTo { }

# The response CONTAINS its hits, its optional induced relationships,
# and (in the future) audited evidence -- but the latter is NOT this path.
edge ContainsHit { }
edge ContainsRelationship { }
edge ContainsEvidence { }

# ---------- Walkers ----------

walker Reconciler {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can triage with Response entry {
        self.findings.append(
            f"[wire] field='attributions' (renamed from 'sources'); "
            f"mode={here.mode}; answer_from_llm={here.answer_from_llm}; "
            f"template_floor={here.template_floor}; "
            f"cached_first_query_honest={here.claim_cached_first_query_honest()}"
        );
        if here.mode == "local" {
            visit [->:ContainsHit:->];
        } else {
            visit [->:ContainsHit:->];
        }
    }

    can audit_hit with Hit entry {
        note = "";
        if here.entity_ref == "" {
            note = " (empty entity_ref -- would fail ADR-059 evidence check)";
        }
        self.findings.append(
            f"[attribution] entity={here.entity_ref} "
            f"community={here.community_ref} "
            f"relevance={here.relevance:.3f}{note}"
        );
        visit [->:AttributedTo:->];
    }

    can audit_relationship with RelationshipHint entry {
        self.findings.append(
            f"[context-only] {here.from_entity} -[hint]-> {here.to_entity} "
            f"(not used by answer synthesis)"
        );
    }

    can audit_community with Community entry {
        cached = "cached" if here.summary_cached else "fresh";
        self.findings.append(
            f"[community] {here.name} summary={cached}; "
            f"but answer synthesis runs per query -- "
            f"'first query is slowest because summaries are cached' is UNSUPPORTED"
        );
        visit [->:BelongsTo:->];
    }

    can reserve_evidence with AuditedEvidence entry {
        self.findings.append(
            f"[evidence] status={here.status} -- "
            f"wire/type name MUST keep callers from mistaking "
            f"attributions for ADR-059 provenance"
        );
        disengage;
    }
}

# ---------- Demo wiring ----------

with entry {
    c_ai = Community(name="AI Agents", summary="agents & tools");
    c_kg = Community(name="Knowledge Graphs", summary="graph stores");

    e_agent = Entity(name="agent-1", kind="agent");
    e_tool  = Entity(name="tool-1",  kind="tool");
    e_kg    = Entity(name="kg-1",    kind="graph");

    e_agent +>:BelongsTo:+> c_ai;
    e_tool  +>:BelongsTo:+> c_ai;
    e_kg    +>:BelongsTo:+> c_kg;

    local = Response(
        mode="local",
        answer="template: members of AI Agents matching 'agent'",
        answer_from_llm=False,
        llm_degraded=False,
        template_floor=True
    );
    h_local_1 = Hit(entity_ref="agent-1", community_ref="AI Agents", relevance=0.91);
