    acme = Organization(name="Acme Corp", tenant_id="T-001");

    settings = Settings(allow_archive=True, max_categories=100);
    acme +>:Owns(created_on="2024-01-01"):+> settings;

    cat_invoices = Category(title="Invoices", active=True);
    cat_contracts = Category(title="Contracts", active=True);
