"""Subtree authority: a parent key can act on any account in its subtree.

Models the aios issue natively — accounts are nodes connected by typed
``HasChild`` edges, an actor's subtree is discovered by a walker that
descends through children, and an ``Authority`` walker enforces the
invariant: an actor may act on a target iff the target is the actor
itself or lies in the actor's subtree. An archived account in the chain
breaks subtree authority at that node.
"""

node Account {
    has account_id: str = "";
    has label: str = "";
    has archived: bool = False;
}

edge HasChild {
    has created_on: str = "";
}

walker SubtreeCollector {
    has actor_id: str = "";
    has descendants: list[str] = [];
    has _seen: list[str] = [];

    can start with Root entry {
        visit [->:HasChild:->];
    }

    can descend with Account entry {
        if here.archived {
            # Archived node: subtree authority breaks here.
            disengage;
        }
        if here.account_id == self.actor_id {
            visit [->:HasChild:->];
            return;
        }
        if here.account_id in self._seen {
            # Cycle guard — explicit per jac 0.36.1 semantics.
            disengage;
        }
        self._seen.append(here.account_id);
        self.descendants.append(here.account_id);
        visit [->:HasChild:->];
    }
}

walker Authority {
    has actor: Account | None = None;
    has target_id: str = "";
    has allowed: bool = False;
    has reason: str = "";

    can start with Account entry {
        if here.archived {
            self.allowed = False;
            self.reason = "actor archived";
            disengage;
        }
        if here.account_id == self.target_id {
            self.allowed = True;
            self.reason = "self";
            disengage;
        }
        # Walk every account reachable through HasChild from the actor.
        collector = SubtreeCollector(actor_id=here.account_id);
        here spawn collector;
        if self.target_id in collector.descendants {
            self.allowed = True;
            self.reason = "descendant";
        } else {
            self.allowed = False;
            self.reason = "not in subtree";
        }
        if self.allowed {
            print(
                f"GRANT  actor={here.account_id} target={self.target_id} "
                f"reason={self.reason}"
            );
        } else {
            print(
                f"DENY   actor={here.account_id} target={self.target_id} "
                f"reason={self.reason}"
            );
        }
    }
}

with entry {
    # Build a small account tree:
    #       root
    #      /    \
    #   alpha   beta
    #   /   \     \
    # alpha1 alpha2 beta1
    root_acct = Account(account_id="root", label="Root");
    alpha = Account(account_id="alpha", label="Alpha");
    beta = Account(account_id="beta", label="Beta");
    alpha1 = Account(account_id="alpha1", label="Alpha-1");
    alpha2 = Account(account_id="alpha2", label="Alpha-2");
