    archived = Account(account_id="archived", label="Archived", archived=True);

    root_acct +>:HasChild(created_on="2025-01-01"):+> alpha;
    root_acct +>:HasChild(created_on="2025-01-01"):+> beta;
    alpha +>:HasChild(created_on="2025-02-01"):+> alpha1;
    alpha +>:HasChild(created_on="2025-02-01"):+> alpha2;
    beta +>:HasChild(created_on="2025-02-01"):+> beta1;
