    print("--- Bot passes through (desk greets any walker) ---");
    root spawn Bot(serial="B-7");
}

"""Coordination handoff integrity demo.

Models JINGO's charter as a typed graph: Tasks carry status, Agents own
them, Handoffs carry reviewer routing, Dependencies gate readiness. A
walker audits every task's handoff packet for completeness and reports
HOLD or PASS per task, traversing the dependency tree.
"""

node Task {
    has title: str = "";
    has status: str = "ASSIGNED";
    has reviewer: str = "";
    has source: str = "";
    has result_evidence: bool = False;
    has authority: str = "";
    has current_status_recorded: bool = False;
}

node Agent {
    has name: str = "";
    has role: str = "";
}

node HandoffPacket {
    has task_ref: str = "";
    has authority: bool = False;
    has source: bool = False;
    has status: bool = False;
    has locks: bool = False;
    has reviewer: bool = False;
    has expected_output: bool = False;
}

edge AssignedTo { has since: str = ""; }
edge DependsOn { }
edge HandoffFrom { }

walker HandoffAuditor {
    has tasks_seen: list[str] = [];
    has holds: list[str] = [];
    has passes: list[str] = [];
    has conflicts: list[str] = [];

    can start with Root entry {
        visit [->:AssignedTo:->];
    }

    can audit_task with Task entry {
        if here.title in self.tasks_seen {
            visit [->:DependsOn:->];
        } else {
            self.tasks_seen.append(here.title);
            packet = [->:HandoffFrom:->][0];
            complete = (
                packet.authority and packet.source and packet.status
                and packet.locks and packet.reviewer
                and packet.expected_output
            );
            result_ready = (here.status == "RESULT_READY");
            running_reported = (here.status == "RUNNING");
            if not complete {
                self.holds.append(here.title);
                print(f"[HOLD] {here.title}: handoff packet incomplete");
            } elif result_ready and not here.result_evidence {
                self.conflicts.append(here.title);
                print(f"[CONFLICT] {here.title}: RESULT_READY without evidence");
            } elif running_reported and not here.result_evidence and here.current_status_recorded {
                self.conflicts.append(here.title);
                print(f"[CONFLICT] {here.title}: RUNNING claimed without execution evidence");
            } else {
                self.passes.append(here.title);
                print(f"[PASS] {here.title}: handoff complete, status={here.status}");
            }
            visit [->:DependsOn:->];
        }
    }
}

with entry {
    owner = Agent(name="OWNER", role="OWNER");
    jingo = Agent(name="JINGO", role="COORDINATOR");
    salvador = Agent(name="SALVADOR", role="DOMAIN");
    django = Agent(name="DJANGO", role="REVIEWER");

    t1 = Task(
        title="Draft concept brief",
        status="RUNNING",
        reviewer="DJANGO",
        source="approved-spec-v1",
        authority="STUDIO_AGENT",
        current_status_recorded=True
    );
    p1 = HandoffPacket(
        task_ref="Draft concept brief",
        authority=True,
        source=True,
        status=True,
        locks=True,
        reviewer=True,
        expected_output=True
    );

    t2 = Task(
        title="Visual mock",
        status="ASSIGNED",
        reviewer="DJANGO",
        source="approved-spec-v1",
        authority="DOMAIN_AGENT"
    );
    p2 = HandoffPacket(
        task_ref="Visual mock",
        authority=True,
        source=True,
        status=True,
        locks=True,
        reviewer=True,
        expected_output=True
    );

    t3 = Task(
        title="Final render",
        status="RESULT_READY",
        reviewer="DJANGO",
        source="approved-spec-v1",
        authority="DOMAIN_AGENT",
        result_evidence=False
    );
    p3 = HandoffPacket(
        task_ref="Final render",
        authority=True,
        source=True,
        status=True,
        locks=True,
        reviewer=True,
        expected_output=True
    );

    root +>:AssignedTo(since="Mon"):+> t1;
    root +>:AssignedTo:+> t2;
    root +>:AssignedTo:+> t3;

    t1 +>:DependsOn:+> t2;
    t2 +>:DependsOn:+> t3;

    t1 +>:HandoffFrom:+> p1;
    t2 +>:HandoffFrom:+> p2;
    t3 +>:HandoffFrom:+> p3;

    jingo +>:AssignedTo(since="Day1"):+> salvador;
    jingo +>:AssignedTo:+> django;

    auditor = HandoffAuditor();
    root spawn auditor;

    print(f"\nAudit summary:");
    print(f"  PASS: {auditor.passes}");
    print(f"  HOLD: {auditor.holds}");
    print(f"  CONFLICT: {auditor.conflicts}");
}

