"""Jenkins folder security blocks: model the multi-block drop bug and its fix.

The Terraform provider declared ``security`` as a SetNestedBlock with no size
validator, then read only element 0 — silently dropping additional blocks,
half-applying permissions, and breaking apply-time state consistency.

This demo models the same shape natively: each configured ``security`` block
is its own SecurityBlock node, connected to its Folder by a typed ``HasBlock``
edge. A walker that mimics the buggy write path drops everything past the
first block; a validating walker enforces the "exactly one block" contract
up front so apply never sees a mismatch.
"""

node Folder {
    has name: str = "";
}

node SecurityBlock {
    has inheritance_strategy: str = "";
    has permissions: list[str] = [];
}

edge HasBlock {
    has ordinal: int = 0;
}

# ---------------------------------------------------------------------------
# Buggy writer: mirrors the provider's `blocks[0]` read path. Anything past
# the first security block on the folder is silently dropped — exactly the
# behavior the issue is filing against.
# ---------------------------------------------------------------------------
walker BuggyWriter {
    has rendered_count: int = 0;
    has rendered_permissions: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can write with Folder entry {
        # Visit the typed-edge children, but only take the first one.
        blocks = [here ->:HasBlock:->];
        if not blocks {
            visit [-->];
            disengage;
        }
        first = blocks[0];
        self.rendered_count = 1;
        self.rendered_permissions = first.permissions;
        # Note: no traversal of siblings, no diagnostic — the bug.
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Validating writer: enforces the "at most one security block" contract up
# front, the way the suggested fix proposes. Apply never sees a mismatched
# block count, so Jenkins state and Terraform state agree.
# ---------------------------------------------------------------------------
walker ValidatingWriter {
    has accepted: bool = False;
    has rendered_count: int = 0;
    has rendered_permissions: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can validate with Folder entry {
        blocks = [here ->:HasBlock:->];
        if len(blocks) > 1 {
            print(
                f"[REJECT] folder {here.name} declares "
                f"{len(blocks)} security blocks; only one is allowed"
            );
            visit [-->];
            disengage;
        }
        self.accepted = True;
        if len(blocks) == 1 {
            first = blocks[0];
            self.rendered_count = 1;
            self.rendered_permissions = first.permissions;
        }
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Counter walker: just counts security blocks attached to a folder, to make
# the "plan said 2, apply wrote 1" mismatch visible.
# ---------------------------------------------------------------------------
walker BlockCounter {
    has block_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can count with Folder entry {
        self.block_count = len([here ->:HasBlock:->]);
        visit [-->];
    }
}

with entry {
    # A folder with TWO security blocks — the configuration that triggers the bug.
    example = Folder(name="example");
    devs = SecurityBlock(
        inheritance_strategy="InheritParentStrategy",
        permissions=["hudson.model.Item.Read:devs"],
    );
    ci = SecurityBlock(
        inheritance_strategy="NonInheritingStrategy",
        permissions=["hudson.model.Item.Build:ci"],
    );
    example +>:HasBlock(ordinal=0):+> devs;
    example +>:HasBlock(ordinal=1):+> ci;
    root ++> example;

    # How many blocks does the folder declare?
    counter = BlockCounter();
    root spawn counter;
    print(f"plan sees {counter.block_count} security block(s) on folder "
          f"{example.name}");

    # Run the buggy writer: only the first block's permissions survive.
    buggy = BuggyWriter();
    root spawn buggy;
    print(f"[BUG] applied {buggy.rendered_count} block(s); "
          f"permissions written to Jenkins: {buggy.rendered_permissions}");
    print(f"[BUG] drift: plan had {counter.block_count} block(s), "
          f"state has {buggy.rendered_count} -> "
          f"\"Provider produced inconsistent result after apply\"");

    # Now run the validating writer on the same graph: the second block is
    # rejected up front, so apply and plan agree.
    validator = ValidatingWriter();
    root spawn validator;
    if validator.accepted {
        print(f"[FIX] accepted {validator.rendered_count} block(s); "
              f"permissions: {validator.rendered_permissions}");
    } else {
        print("[FIX] configuration rejected before Jenkins was touched");
    }

    # A folder with exactly one block — the contract — still applies cleanly
    # under the validating writer.
    clean = Folder(name="clean");
    single = SecurityBlock(
        inheritance_strategy="InheritParentStrategy",
        permissions=["hudson.model.Item.Read:devs"],
    );
    clean +>:HasBlock(ordinal=0):+> single;
    root ++> clean;

    counter2 = BlockCounter();
    root spawn counter2;
    print(f"plan sees {counter2.block_count} security block(s) on folder "
          f"{clean.name}");

    validator2 = ValidatingWriter();
    root spawn validator2;
    if validator2.accepted {
        print(f"[FIX] accepted {validator2.rendered_count} block(s); "
              f"permissions: {validator2.rendered_permissions}");
    }
}

"""CI workflow composition as a typed graph.

Models the core scenario from issue #283: reusable CI workflows compose
primitive jobs, and a ReusableWorkflowCaller product repo reaches them
through a typed invocation edge. A ReusableAuditor walker validates the
library: every public reusable must be reachable from root, must declare
its execution backend (organization, github-hosted, or both), and must
not contain cyclic self-references that would deadlock the build graph.
The contract mirrors the issue: one library, many thin product callers,
no hand-rolled recursion.
"""

node Job {
    has title: str = "";
    has expensive: bool = False;
}

node Workflow {
    has name: str = "";
    has backend: str = "organization";
    has dual_backend: bool = False;
}

edge Invokes {
    has order: int = 0;
}

walker ReusableAuditor {
    has visited: list[str] = [];
    has reachable: list[Workflow] = [];
    has cycles_found: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_workflow with Workflow entry {
        if here.name in self.visited {
            self.cycles_found += 1;
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here);
        if here.backend not in ["organization", "github-hosted"] and not here.dual_backend {
            print(f"[REJECT] {here.name} has undeclared backend '{here.backend}'");
        } else {
            label = "DUAL" if here.dual_backend else here.backend.upper();
            print(f"[OK] {here.name} backend={label}");
        }
        visit [->:Invokes:->];
    }

    can audit_job with Job entry {
        marker = "HEAVY" if here.expensive else "light";
        print(f"  job[{marker}] {here.title}");
        visit [->:Invokes:->];
    }
}

walker ProductCaller {
    has product_name: str = "";

    can start with Root entry {
        print(f"product '{self.product_name}' resolves reusable library");
        visit [-->];
    }

    can consume with Workflow entry {
        print(f"  {self.product_name} -> {here.name}");
    }
}

with entry {
    node_validation = Workflow(name="reusable-node.yml", dual_backend=True);
    job_lint = Job(title="lint", expensive=False);
    job_test = Job(title="test", expensive=True);
    job_package = Job(title="package", expensive=True);

    node_release = Workflow(name="reusable-native-image-chart.yml", backend="github-hosted");
    job_build = Job(title="build-image", expensive=True);
    job_chart = Job(title="chart-publish", expensive=False);

    root +>:Invokes(order=1):+> node_validation;
    node_validation +>:Invokes(order=1):+> job_lint;
    node_validation +>:Invokes(order=2):+> job_test;
    node_validation +>:Invokes(order=3):+> job_package;

    root +>:Invokes(order=2):+> node_release;
    node_release +>:Invokes(order=1):+> job_build;
    node_release +>:Invokes(order=2):+> job_chart;

    print("=== Auditing library ===");
    auditor = ReusableAuditor();
    root spawn auditor;
    print(f"reachable workflows: {len(auditor.reachable)}");
    print(f"cycles detected: {auditor.cycles_found}");

    print("\n=== Product caller resolves library ===");
    root spawn ProductCaller(product_name="checkout-svc");
    root spawn ProductCaller(product_name="billing-svc");
}

