    has count: int = 0;
    has goal: int = 3;

    can start with Root entry {
        print("Hiker begins the ascent from the trailhead");
        visit [-->] else { disengage; }
    }

    can walk with Waypoint entry {
        self.count += 1;
        print(f"Stop #{self.count}");
        if self.count >= self.goal {
