"""Shirube V4 D1 activation: guard rollout with feature flag, kill switch, canary, and fleet read-back.

Models the guarded fleet rollout described in issue #887. A walker audits
authorization, persists durable claim/invocation state, exercises idempotent
effect ports keyed by invocation_key, then validates the canary before
promoting the registered five-target fleet.
"""

# ---- Edge archetypes: each relationship carries meaning ------------------

edge Authorizes {
    has comment_id: str = "";
}

edge Deploys {
    has since: str = "";
    has is_canary: bool = False;
}

edge Persists {
    has invocation_key: str = "";
    has idempotent: bool = True;
}

edge RoutesTo {
    has effect_port: str = "";
    has ack_received: bool = False;
}

# ---- Node archetypes -----------------------------------------------------

node Authorization {
    has owner: str = "";
    has comment_id: str = "";
    has valid: bool = False;
}

node Adapter {
    has name: str = "";
    has feature_flag: bool = False;
    has kill_switch: bool = False;
    has canary_allowlist: list[str] = [];
    has import_count: int = 0;
}

node Invocation {
    has invocation_key: str = "";
    has target: str = "";
    has receipt: str = "";
    has effect_delivered: bool = False;
    has idempotent: bool = True;
}

node FleetTarget {
    has repo: str = "";
    has activated: bool = False;
    has read_back_ok: bool = False;
}

# ---- Walker: the audit + rollout pipeline -------------------------------

walker ShirubeActivation {
    has live_canary_proven: bool = False;
    has fleet_count: int = 0;

    can begin with Root entry {
        print("=== Shirube V4 D1 guarded rollout ===");
        visit [->:Authorizes:->];
    }

    can validate_auth with Authorization entry {
        verdict = "AUTHORIZED" if here.valid else "REJECTED";
        print(f"  auth[{here.owner}@{here.comment_id}] = {verdict}");
        if not here.valid {
            self.live_canary_proven = False;
            disengage;
        }
        visit [->:Deploys:->];
    }

    can activate_adapter with Adapter entry {
        import_ok = here.feature_flag and not here.kill_switch
            and len(here.canary_allowlist) > 0;
        verdict = "ARMED" if import_ok else "BLOCKED";
        print(f"  adapter[{here.name}] flag={here.feature_flag} "
            f"kill={here.kill_switch} canary={here.canary_allowlist} -> {verdict}");
        if not import_ok {
            disengage;
        }
        visit [->:Persists:->];
    }

    can deliver_effect with Invocation entry {
        # Idempotency rule: same invocation_key yields one effect, one receipt.
        here.effect_delivered = here.idempotent;
        here.receipt = f"rcpt-{here.invocation_key}" if here.effect_delivered else "";
        print(f"  effect[{here.invocation_key} -> {here.target}] "
            f"delivered={here.effect_delivered} receipt={here.receipt}");
        visit [->:RoutesTo:->];
    }

    can read_back_target with FleetTarget entry {
        # Read-back happens through the RoutesTo edge into the target.
        if here.repo != "__canary_link__" and here.activated {
            here.read_back_ok = True;
        }
        print(f"  target[{here.repo}] activated={here.activated} "
            f"read_back={here.read_back_ok}");
        visit [-->];
    }

    can finalize with Root exit {
        print("=== rollout summary ===");
        print(f"  canary_proven={self.live_canary_proven} "
            f"fleet_activated={self.fleet_count}");
    }
}

# ---- Demonstration graph ------------------------------------------------

with entry {
    # The single authorization source (owner activation comment).
    auth_ok = Authorization(owner="aun", comment_id="5031428257", valid=True);
    auth_bad = Authorization(owner="unknown", comment_id="0", valid=False);

    # The D1 adapter with default-off flag, kill switch armed, canary set.
    adapter = Adapter(
        name="shirube-v4-d1",
        feature_flag=True,
        kill_switch=False,
        canary_allowlist=["agent-comms-mcp"]
    );

    # Canary invocation: one durable key, one target.
    canary_inv = Invocation(
        invocation_key="inv-canary-001",
        target="agent-comms-mcp",
        receipt="",
        effect_delivered=False,
        idempotent=True
    );

    # One target node per registered fleet repository.
    fleet = [
        FleetTarget(repo="agent-comms-mcp"),
        FleetTarget(repo="agent-memory"),
        FleetTarget(repo="aun-platform"),
        FleetTarget(repo="kodama"),
        FleetTarget(repo="misell"),
    ];

    # Wire the audited path: auth -> adapter -> invocation -> fleet targets.
    root +>:Authorizes(comment_id="5031428257"):+> auth_ok;
    auth_ok +>:Authorizes:+> auth_bad;

    auth_ok +>:Deploys(since="2025-W47", is_canary=False):+> adapter;

    adapter +>:Persists(invocation_key="inv-canary-001"):+> canary_inv;

    targets_root = FleetTarget(repo="__canary_link__");
    canary_inv +>:RoutesTo(effect_port="internal_reply"):+> targets_root;
    targets_root +>:RoutesTo:+> fleet[0];
