"""OOXML package walker: traverse story parts via relationships.

SourceRight's `read_manuscript_text` opens only `word/document.xml`, so
footnotes, endnotes, headers, comments and other OOXML story parts are
silently dropped during reconciliation. The proper fix is to follow the
package's own relationship graph instead of assuming fixed part names.

This demo models the OOXML package as a graph of `Part` nodes connected
by typed `Relationship` edges, then a `Reconciler` walker walks the
package graph over those relationships — the exact traversal that the
issue says is missing from the hand-rolled machinery.
"""

# --- Entity archetypes ----------------------------------------------------

node Part {
    has part_name: str = "";
    has content_kind: str = "";   # "document" | "footnote" | "endnote" | "header" | "comment"
    has raw_text: str = "";
    has omissions: list[str] = [];
}

edge Relationship {
    has rel_type: str = "";       # e.g. "footnotes", "endnotes", "comments", "headers"
}

# A callout reference: a run inside one part that points to a note in another.
edge Callout {
    has note_id: str = "";
}

# --- Walkers --------------------------------------------------------------

# Follow the OOXML relationship graph from the main document part out to
# every story part it transitively references. Replaces the hand-rolled
# "only read word/document.xml" logic.
walker Reconciler {
    has visited_ids: list[str] = [];
    has omissions: list[str] = [];
    has source_format: str = "docx";
    has guard: set[str] = set();

    can start with Root entry {
        self.source_format = "docx";
        # Visit every package-part node hanging off the root — mirrors
        # "open the .docx and look at its top-level parts."
        visit [-->];
    }

    can open_part with Part entry {
        # Cycle policy: walkers in jac 0.36.1 have no built-in
        # once-per-node visitation, so guard explicitly against loops.
        if here.part_name in self.guard {
            visit [-->];
            return;
        }
        self.guard.add(here.part_name);
        self.visited_ids.append(here.part_name);

        if here.content_kind == "document" {
            print(f"[{self.source_format}] opened main story: {here.part_name}");
        } else {
            print(f"  -> followed rel into {here.content_kind}: {here.part_name}");
        }

        # Aggregate omissions from every non-document part we reach,
        # exactly the diagnostic the issue asks for.
        if here.omissions {
            for o in here.omissions {
                self.omissions.append(o);
            }
        }

        # From any part, follow Relationship edges to other parts the
        # package actually links to. Plain --> catches sibling parts.
        visit [-->];
        visit [->:Relationship:->];
    }
}

# Diagnostic walker: emit a `docx.story_parts_omitted` style warning for
# any package whose `omissions` list is non-empty. This is the fallback
# the issue asks for when full coverage is deferred.
walker DiagnosticsAuditor {
    has flagged: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Part entry {
        if here.omissions {
            label = "docx.story_parts_omitted";
            self.flagged.append(label);
            print(f"[WARN] {label} on {here.part_name}: {here.omissions}");
        }
        visit [-->];
    }
}

# --- Demo wiring ----------------------------------------------------------

with entry {
    # Build a tiny OOXML package by hand:
    #   word/document.xml  --(footnotes)-->  word/footnotes.xml
    #                       --(endnotes)-->   word/endnotes.xml
    #                       --(comments)-->   word/comments.xml
    # Each non-document part carries an `omissions` list naming what
    # we did NOT reconcile (tracked changes, fields, hyperlinks, ...).
    doc = Part(
        part_name="word/document.xml",
        content_kind="document",
        raw_text="Body text with citation [1] and superscript note.",
    );
    footnotes = Part(
        part_name="word/footnotes.xml",
        content_kind="footnote",
        raw_text="1. First footnote body.",
        omissions=["tracked-changes", "fields"],
    );
    endnotes = Part(
        part_name="word/endnotes.xml",
        content_kind="endnote",
        raw_text="i. First endnote body.",
        omissions=["hyperlinks"],
    );
    comments = Part(
        part_name="word/comments.xml",
        content_kind="comment",
        raw_text="Reviewer: tighten this paragraph.",
        omissions=[],
    );

    # The package graph: root holds the main document, which holds the
    # story parts via typed Relationship edges.
    root ++> doc;

    doc +>:Relationship(rel_type="footnotes"):+> footnotes;
    doc +>:Relationship(rel_type="endnotes"):+> endnotes;
    doc +>:Relationship(rel_type="comments"):+> comments;

    # Run the reconciler over the package.
    r = root spawn Reconciler();

    # Run the diagnostic auditor to surface the omission list.
    root spawn DiagnosticsAuditor();

    print("Reconciler visited parts:");
    for p in r.visited_ids {
        print(f"  {p}");
    }
    print("Reconciler accumulated omissions:");
    for o in r.omissions {
        print(f"  {o}");
    }
}

"""Order auditor demonstrating both flavors of early return.

Invalid orders are skipped (the walk continues to the next order),
while fraud-flagged orders halt the whole walk immediately via
``disengage;``. A line is printed per order showing which action fired.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;

    can start with Root entry {
        print("Audit begin");
        visit [-->];
    }

    can audit with Order entry {
        self.audited += 1;

        if here.fraud {
            print(f"[HALT-FRAUD] {here.label} amount={here.amount} -> disengaging");
            disengage;
        }

        if not here.valid {
            print(f"[SKIP-INVALID] {here.label} amount={here.amount}");
            visit [-->];
            return;
        }

        print(f"[AUDIT-OK] {here.label} amount={here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="O-1001", amount=120.50)
        ++> Order(label="O-1002", amount=0.00, valid=False)
        ++> Order(label="O-1003", amount=9999.99, fraud=True)
        ++> Order(label="O-1004", amount=42.00);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"audited count (fraud case truncated): {auditor.audited}");

    # Second run, no fraud anywhere, to show the skip-then-continue flow.
    auditor2 = OrderAuditor();
    root ++> Order(label="O-2001", amount=15.00)
        ++> Order(label="O-2002", amount=0.00, valid=False)
        ++> Order(label="O-2003", amount=77.77)
        ++> Order(label="O-2004", amount=33.33);
    root spawn auditor2;
    print(f"audited count (clean run): {auditor2.audited}");
}

"""M12 canonical IR consolidation: dependency-ordered wave gates, legacy reachability inventory, and ProcessIR compile pipeline."""

node IntegrationSpecV1 {
    has title: str = "";
    has pipeline_locked: bool = True;
    has validated: bool = False;
}

node ProcessAuthoringUnitV1 {
    has unit_id: str = "";
    has capability_gated: bool = True;
    has validated: bool = False;
}

node ProcessIR {
    has fingerprint: str = "";
    has attested: bool = False;
    has level_one: bool = False;
    has level_two: bool = False;
}

node LegacySlice {
    has issue_num: int = 0;
    has slice_name: str = "";
    has transferred: bool = False;
    has blocking_findings: int = 0;
}

edge DependsOn {
    has required: bool = True;
}

edge AuthoringRoot {
    has role: str = "root";
}

edge CompilesTo {
    has stage: str = "";
}

edge LegacyTransfer {
    has parity_oracle: bool = True;
}

walker WaveGateAuditor {
    has seen: list[int] = [];
    has wave_cleared: bool = True;
    has audit_order: list[int] = [];

    can start with Root entry {
        print("M12 wave gate: dependency-ordered slice audit");
        visit [-->];
    }

    can audit with LegacySlice entry {
        if here.issue_num in self.seen {
            print(f"[CYCLE] blocking revisit of #{here.issue_num}");
            disengage;
        }
        self.seen.append(here.issue_num);
        if here.blocking_findings > 0 {
            self.wave_cleared = False;
            verdict = "BLOCKING";
        } elif not here.transferred {
            verdict = "TRANSFER";
        } else {
            verdict = "OK";
        }
        print(f"[{verdict}] #{here.issue_num} {here.slice_name}");
        self.audit_order.append(here.issue_num);
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker CanonicalCompiler {
    has plan_fingerprint: str = "";

    can start with Root entry {
        print("Canonical compile: IntegrationSpecV1 + ProcessAuthoringUnitV1 -> ProcessIR");
        visit [->:AuthoringRoot:->] else { disengage; };
    }

    can on_spec with IntegrationSpecV1 entry {
        lock_state = "locked" if here.pipeline_locked else "VIOLATION";
        print(f"[SPEC] {here.title} pipeline {lock_state}");
        visit [->:AuthoringRoot:->];
        visit [->:CompilesTo:->] else { disengage; };
    }

    can on_unit with ProcessAuthoringUnitV1 entry {
        gate_label = "gated" if here.capability_gated else "ungated";
        print(f"[UNIT] {here.unit_id} ({gate_label})");
        visit [->:CompilesTo:->] else { disengage; };
    }

    can materialize with ProcessIR entry {
        here.level_one = True;
        here.level_two = True;
