    has seen_titles: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can begin with Change entry {
        if here.changed {
            print(f"changed producer: {here.title}");
            visit [->:Selects:->] else {
                disengage;
            }
        } else {
            disengage;
        }
