            if here.selected {
                print(f"selected {here.title}: current={here.current}, useful={here.useful_work}");
            } else {
                print(f"dependency {here.title}: not selected");
            }
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

