    has entry_count: int = 0;

    can start with Root entry {
        print("Starting local session storage audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspectStore with SessionStore entry {
        print(f"Storage path: {here.expanded_path}");
        if self.hops >= self.max_hops {
            print("Traversal limit reached at storage root");
            disengage;
        }
        self.hops += 1;
        visit [->:RegistersServer:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspectServer with McpServer entry {
        print(f"Server: {here.name} ({here.version})");
        if self.hops >= self.max_hops {
            print("Traversal limit reached at server");
            disengage;
        }
        self.hops += 1;
        visit [->:HostsSession:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspectSession with McpSession entry {
        self.session_count += 1;
        status = "valid" if here.available else "invalidated";
        print(f"Session {here.session_id}: {status}, tags={here.tags}");

        if self.hops >= self.max_hops {
            print(f"Traversal limit reached at session {here.session_id}");
            disengage;
        }
        self.hops += 1;
        visit [->:ContainsEntry:->] else {
            disengage;
        }
        self.hops -= 1;
    }

    can inspectEntry with SessionEntry entry {
        self.entry_count += 1;
        print(f"  entry {here.sequence}: {here.kind} -> {here.payload}");
    }
}

with entry {
    store = SessionStore(expanded_path="~/.mcp-studio/sessions/");

    server = McpServer(
        name="demo-server",
        version="1.0.0"
    );

    first = McpSession(
        session_id="sess-001",
        server_name="demo-server",
        file_name="sess-001.json",
        tags="regression,inspector",
        started_at=20250101
    );

    second = McpSession(
        session_id="sess-002",
        server_name="demo-server",
        file_name="sess-002.json",
        tags="failed-replay",
        started_at=20250102,
        available=False
    );

    first_request = SessionEntry(
