"""Gallery security console: log every visitor and record inspections by curators.

A generic Visitor walker logs each room it enters. A Curator walker does
the same generic logging but additionally records an official inspection
under the curator's name and increments a per-curator inspection count.

To avoid repeated traversal logic, both walkers share a base ``Person``
walker whose ``start`` ability hands off to the room-typing logic. Each
subclass overrides the ``enter`` ability with its own semantics. Both
walkers use ``visit [-->] else { disengage; }`` so the walker terminates
cleanly once rooms are exhausted.
"""

node Room {
    has name: str = "";
    has log: list[str] = [];
    has inspections: list[str] = [];
}

walker Person {
    has name: str = "";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can enter with Room entry {
        here.log.append(f"visitor: {self.name}");
        print(f"{self.name} entered {here.name} (logged)");
        visit [-->] else { disengage; }
    }
}

walker Tourist(Person) {
    # Inherits Person's abilities; tourist behavior is identical to the
    # generic logging behavior of Person, so no override needed.
}

walker Curator(Person) {
    has inspections_done: int = 0;

    can enter with Room entry {
        here.log.append(f"visitor: {self.name}");
        here.inspections.append(self.name);
        self.inspections_done += 1;
        print(
            f"{self.name} entered {here.name} "
            f"(logged + inspection #{self.inspections_done})"
        );
        visit [-->] else { disengage; }
    }
}

with entry {
    rotunda = Room(name="Rotunda");
    east_wing = Room(name="East Wing");
    root ++> rotunda ++> east_wing;

    alice = Tourist(name="Alice");
    dr_bao = Curator(name="Dr. Bao");

    root spawn alice;
    root spawn dr_bao;

    print(
        f"\nSummary: tourist logged entries only; curator "
        f"{dr_bao.name} recorded {dr_bao.inspections_done} "
        f"official inspection(s)."
    );
    print(f"Rotunda log: {rotunda.log}");
    print(f"Rotunda inspections: {rotunda.inspections}");
    print(f"East Wing log: {east_wing.log}");
    print(f"East Wing inspections: {east_wing.inspections}");
}

