"""Pet-aware friend recommender: walk a social graph and suggest only adult humans.

Profiles form a social graph; some profiles belong to pets rather than people.
A walker spawns at each human adult, inspects its raw neighbours, applies a
species + age filter, and prints how many neighbours each human saw and how
many of them were eligible friend suggestions.
"""

node Profile {
    has name: str = "";
    has species: str = "human";
    has age: int = 0;
}

walker Recommender {
    can start with Root entry {
        visit [-->];
    }

    can suggest with Profile entry {
        if here.species != "human" or here.age < 18 {
            # Pet profiles and minors never originate a recommendation.
            visit [-->];
            disengage;
        }
        raw_count = 0;
        kept_count = 0;
        for nbr in [-->] {
            raw_count += 1;
            if nbr.species == "human" and nbr.age >= 18 {
                kept_count += 1;
                print(f"  suggest {nbr.name} (human, {nbr.age}) to {here.name}");
            } else {
                reason = "pet" if nbr.species != "human" else "minor";
                print(f"  skip {nbr.name} ({reason}) for {here.name}");
            }
        }
        print(f"{here.name} saw {raw_count} raw neighbour(s), "
              f"{kept_count} survived filters");
        visit [-->];
    }
}

with entry {
    alice = Profile(name="Alice", age=30);
    bob = Profile(name="Bob", age=25);
    carol = Profile(name="Carol", age=17);
    dave = Profile(name="Dave", age=40);
    whiskers = Profile(name="Whiskers", species="cat", age=3);
    rex = Profile(name="Rex", species="dog", age=5);

    alice ++> bob;
    alice ++> carol;
    alice ++> whiskers;
    alice ++> rex;

    bob ++> dave;
    bob ++> whiskers;

    dave ++> alice;
    dave ++> rex;

    carol ++> bob;

    whiskers ++> alice;
    rex ++> bob;

    root ++> alice ++> bob ++> carol;
    root ++> dave;
    root ++> whiskers ++> rex;

    root spawn Recommender();
}

"""Delivery dispatch check: each route must carry between 2 and 8 tonnes inclusive to qualify."""

node Route {
    has destination: str = "";
    has cargo_tonnes: float = 0.0;
}

node Depot {
    has name: str = "";
    has dispatch_ready: bool = False;
}

edge Leg {
    has leg_id: str = "";
}

walker Dispatcher {
    has visited_nodes: list = [];

    can start with Root entry {
        self.visited_nodes = [];
        visit [-->];
    }

    can audit with Depot entry {
        self.visited_nodes.append(here);
        here.dispatch_ready = True;
        for child in [->:Leg:->] {
            visit child;
        }
    }

    can check with Route entry {
        qualifies = here.cargo_tonnes >= 2.0 and here.cargo_tonnes <= 8.0;
        verdict = "QUALIFIES" if qualifies else "REJECTED";
        print(f"[{verdict}] {here.destination}: {here.cargo_tonnes}t");
        if not qualifies {
            parent_depot = [<--];
            if parent_depot {
                parent_depot[0].dispatch_ready = False;
            }
        }
    }
}

with entry {
    north = Depot(name="North Depot");
    south = Depot(name="South Depot");
    root ++> north ++> south;

    north +>:Leg(leg_id="N-1"):+> Route(destination="Riverside", cargo_tonnes=5.5);
    north +>:Leg(leg_id="N-2"):+> Route(destination="Hilltop", cargo_tonnes=1.5);
    north +>:Leg(leg_id="N-3"):+> Route(destination="Lakeside", cargo_tonnes=8.0);

    south +>:Leg(leg_id="S-1"):+> Route(destination="Meadowfield", cargo_tonnes=3.0);
    south +>:Leg(leg_id="S-2"):+> Route(destination="Quarry", cargo_tonnes=9.5);
    south +>:Leg(leg_id="S-3"):+> Route(destination="Pinegrove", cargo_tonnes=2.0);

    root spawn Dispatcher();

    print(f"North Depot dispatch ready: {north.dispatch_ready}");
    print(f"South Depot dispatch ready: {south.dispatch_ready}");
}

"""Dependency lookup with epoch-based cycle detection.

Models the nanvix dlfcn scenario: a lookup walker traverses a graph of
libraries connected by typed dependency edges. Instead of allocating a
per-call visited set (the hand-rolled BTreeSet machinery), the walker
relies on a global epoch counter stamped onto each dependency node via
its `last_visited_epoch` field — graph coloring, native-style.
"""

# ----- Entity archetypes -----

node DlNode {
    has name: str = "";
    has last_visited_epoch: int = 0;
    has bound: bool = False;
}

node Library {
    has name: str = "";
}

# A typed edge: "this DlNode depends on that Library" (and, transitively,
# all of its DlNodes). Carries no payload beyond the relationship.
edge DependsOn { }

# ----- Walker -----

walker Lookup {
    # Global epoch counter — incremented at the start of every lookup.
    # Lives on the walker instance so each spawned walker has its own
    # coloring run, exactly like the per-call atomic in the issue.
    has epoch: int = 0;
    # Bound libraries accumulated during the traversal.
    has bound_order: list[str] = [];

    can begin with Root entry {
        # Bump the global epoch for this lookup. This is the analog of
        # `CURRENT_EPOCH.fetch_add(1, Relaxed)` in the proposal.
        self.epoch = Lookup.next_epoch();
        visit [-->];
    }

    can follow_lib with Library entry {
        print(f"  entering library {here.name}");
        # Now descend into every DlNode attached via DependsOn.
        visit [->:DependsOn:->];
    }

    can color_and_bind with DlNode entry {
        # Graph-coloring check: if this node already carries the current
        # epoch, we are revisiting it on a cycle — skip without locking.
        if here.last_visited_epoch == self.epoch {
            print(f"  skip {here.name}: already colored this epoch (cycle)");
            return;
        }
        # Stamp the node with the current epoch — the "color" for this
        # round. Then do the bind work that the issue's lookup performs.
        here.last_visited_epoch = self.epoch;
        here.bound = True;
        self.bound_order.append(here.name);
        print(f"  bound {here.name}");
        visit [-->];
    }

    # Shared, monotonically increasing epoch source across all walkers.
    static has _clock: int = 0;

    static def next_epoch() -> int {
        Lookup._clock = Lookup._clock + 1;
        return Lookup._clock;
    }
}

# ----- Demo wiring -----

with entry {
    # Build a small library graph with a cycle, the bug that motivated
    # the original BTreeSet fix and the proposed coloring scheme.
    lib_a = Library(name="lib_a");
    lib_b = Library(name="lib_b");
    lib_c = Library(name="lib_c");

    # Dependency nodes hang off each library via typed DependsOn edges.
    # The same node may be reached from multiple libraries — the cycle.
    a1 = DlNode(name="a1");
    a2 = DlNode(name="a2");
    b1 = DlNode(name="b1");
    c1 = DlNode(name="c1");
    shared = DlNode(name="shared");   # creates the cycle a1 -> b1 -> shared -> a2 -> shared

    root ++> lib_a;
    root ++> lib_b;
    root ++> lib_c;

    lib_a +>:DependsOn:+> a1;
    a1 +>:DependsOn:+> b1;
    lib_b +>:DependsOn:+> b1;
    b1 +>:DependsOn:+> shared;
    shared +>:DependsOn:+> a2;
    lib_a +>:DependsOn:+> a2;
    a2 +>:DependsOn:+> shared;        # back-edge forming the cycle
    lib_c +>:DependsOn:+> c1;

    print("=== first lookup (epoch 1) ===");
    lk1 = Lookup();
    root spawn lk1;
    print(f"bound order: {lk1.bound_order}");
    # The shared node must be bound exactly once even though it is
    # reachable on two distinct paths — coloring guarantees that.

    print("=== second lookup (epoch 2) ===");
    lk2 = Lookup();
    root spawn lk2;
    print(f"bound order: {lk2.bound_order}");
}

