"""Hiking trail: a chain of plain waypoints between trailhead and summit.

The waypoints are anonymous nodes (no fields needed) — what matters is the
chain itself. A hiker walker traverses the chain, counts each waypoint,
prints a stop line at each one, and finishes with a completion line once
it has passed enough waypoints.
"""

node Waypoint {
    has marker: int = 0;
}

walker Hiker {
    has stops_made: int = 0;
    has target_stops: int = 5;

    can start with Root entry {
        print("Hiker begins the ascent from the trailhead");
        visit [-->] else { disengage; }
    }

    can trek with Waypoint entry {
        self.stops_made += 1;
        print(f"Stop #{self.stops_made}: passed waypoint {here.marker}");
        if self.stops_made >= self.target_stops {
            print(f"Trail complete after {self.stops_made} waypoints!");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # Build a chain of waypoints from the trailhead up to the summit.
    root ++> Waypoint(marker=1)
        ++> Waypoint(marker=2)
        ++> Waypoint(marker=3)
        ++> Waypoint(marker=4)
        ++> Waypoint(marker=5)
        ++> Waypoint(marker=6)
        ++> Waypoint(marker=7);

    # Target 5 stops so the hiker disengages before reaching the summit.
    Hiker(target_stops=5) spawn root;
}

"""XGC partitioned extrusion with local planes, offsets, and endpoint connectivity."""

node XGCPartition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has total_planes: int = 0;
    has owned_planes: int = 0;
    has plane_start_id: int = 0;
    has delta_phi: float = 0.0;
    has plane_offset: float = 0.0;
    has periodic: bool = False;
}

node ExtrudePlane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has local_index: int = 0;
    has global_index: int = 0;
}

node ExtrudePoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has point_id: str = "";
    has local_plane: int = 0;
    has global_plane: int = 0;
    has role: str = "";
    has expected_incident: int = 0;
}

node ExtrudeCell {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cell_id: str = "";
    has cell_plane: int = 0;
    has global_plane: int = 0;
}

edge ContainsPartition { }

edge OwnsPlane {
    has local_order: int = 0;
}

edge HasPoint { }

edge IncidentCell {
    has contribution: str = "";
}

walker ExtrudeAudit {
    has delta_phi: float = 0.0;
    has plane_offset: float = 0.0;
    has periodic: bool = False;

    can start with Root entry {
        visit [->:ContainsPartition:->];
    }

    can inspect_partition with XGCPartition entry {
        self.delta_phi = here.delta_phi;
        self.plane_offset = here.plane_offset;
        self.periodic = here.periodic;
        print(f"partition total={here.total_planes} owned={here.owned_planes} start={here.plane_start_id}");
        visit [->:OwnsPlane:->];
    }

    can inspect_plane with ExtrudePlane entry {
        phi = (here.global_index + self.plane_offset) * self.delta_phi;
        print(f"plane local={here.local_index} global={here.global_index} phi={phi}");
        visit [->:HasPoint:->];
    }

    can inspect_point with ExtrudePoint entry {
        rule = "wraps" if self.periodic else "stops at endpoint";
        phi = (here.global_plane + self.plane_offset) * self.delta_phi;
        print(f"point {here.point_id} role={here.role} phi={phi} expected={here.expected_incident} rule={rule}");
        visit [->:IncidentCell:->];
    }

    can inspect_cell with ExtrudeCell entry {
        phi = (here.global_plane + self.plane_offset) * self.delta_phi;
        print(f"cell {here.cell_id} plane={here.cell_plane} phi={phi}");
        visit [-->] else { disengage; }
    }
}

with entry {
    partition = XGCPartition(
        title="partition-1",
        total_planes=8,
        owned_planes=3,
        plane_start_id=4,
        delta_phi=0.25,
        plane_offset=0.5,
        periodic=False
    );
    root +>:ContainsPartition:+> partition;

    first_plane = ExtrudePlane(local_index=0, global_index=4);
    middle_plane = ExtrudePlane(local_index=1, global_index=5);
    last_plane = ExtrudePlane(local_index=2, global_index=6);

    partition +>:OwnsPlane(local_order=0):+> first_plane;
    partition +>:OwnsPlane(local_order=1):+> middle_plane;
    partition +>:OwnsPlane(local_order=2):+> last_plane;

    first_point = ExtrudePoint(
        point_id="P0",
        local_plane=0,
        global_plane=4,
        role="first",
        expected_incident=1
    );
    middle_point = ExtrudePoint(
        point_id="P1",
        local_plane=1,
        global_plane=5,
        role="interior",
        expected_incident=2
    );
    last_point = ExtrudePoint(
        point_id="P2",
        local_plane=2,
        global_plane=6,
        role="last",
        expected_incident=1
    );

    first_plane +>:HasPoint:+> first_point;
    middle_plane +>:HasPoint:+> middle_point;
    last_plane +>:HasPoint:+> last_point;

    first_cell = ExtrudeCell(cell_id="C0", cell_plane=0, global_plane=4);
    last_cell = ExtrudeCell(cell_id="C1", cell_plane=1, global_plane=5);

    first_point +>:IncidentCell(contribution="forward"):+> first_cell;
    middle_point +>:IncidentCell(contribution="backward"):+> first_cell;
    middle_point +>:IncidentCell(contribution="forward"):+> last_cell;
    last_point +>:IncidentCell(contribution="backward"):+> last_cell;

    root spawn ExtrudeAudit();
}

"""Industrial sensor patrol.

One monitor ability handles two sensor kinds through a union trigger
(``with TemperatureSensor | SmokeSensor entry``); because both kinds
inherit their reporting interface from the Sensor base, the union-typed
``here`` can be polled without knowing which concrete kind fired.
"""

node Sensor {
    has unit_id: str;

    def is_alert() -> bool {
        return False;
    }

    def reading() -> str {
        return f"{self.unit_id}";
    }
}

node TemperatureSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }

    override def reading() -> str {
        return f"{self.unit_id}: temperature {self.celsius} C";
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }

    override def reading() -> str {
        return f"{self.unit_id}: smoke {self.ppm} ppm";
    }
}

node Zone {
    has zone_id: str;
}

walker SafetyMonitor {
    has alerts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can patrol with Zone entry {
        print(f"sweeping zone {here.zone_id}");
        visit [-->];
    }

    # Union trigger: this single ability runs for BOTH sensor kinds.
    can inspect with TemperatureSensor | SmokeSensor entry {
        if here.is_alert() {
            self.alerts.append(here.reading());
            print(f"[ALERT] {here.reading()}");
        } else {
            print(f"nominal: {here.reading()}");
        }
    }
}

with entry {
    zone_a = Zone(zone_id="A");
