"""Order auditor: skip invalid orders and halt immediately on fraud."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Order audit walk starting");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged, amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order, amount={here.amount}");
                visit [-->] else { disengage; }
            } else {
                print(f"[AUDIT] approved, amount={here.amount}");
                visit [-->] else { disengage; }
            }
        }
    }
}

with entry {
    root ++> Order(amount=100, valid=True, fraud=False)
        ++> Order(amount=50, valid=False, fraud=False)
        ++> Order(amount=999, valid=True, fraud=True)
        ++> Order(amount=200, valid=True, fraud=False);
    root spawn OrderAuditor();
}

"""Blocks Engine Markdown parser ownership demo.

Models the Automattic/blocks-engine scenario where Markdown conversion is
hoisted out of an external dependency (CommonMark) and into a Blocks
Engine-owned parser. The demo builds a small document graph, walks it to
detect duplicate reference definitions, colliding generated slugs, and
quadratic inline runs, then performs a bounded cascade invalidation when
the owned parser takes over from the external adapter.
"""

node MarkdownDocument {
    has title: str = "";
    has bytes: str = "";
}

node ReferenceDef {
    has label: str = "";
    has url: str = "";
    has title: str = "";
}

node Heading {
    has text: str = "";
    has level: int = 0;
    has slug: str = "";
}

node InlineSpan {
    has kind: str = "";
    has run: str = "";
    has repeats: int = 0;
}

node ParsedBlock {
    has kind: str = "";
    has ordinal: int = 0;
}

edge Contains { has order: int = 0; }

walker MarkdownAuditor {
    has seen_labels: list[str] = [];
    has seen_slugs: list[str] = [];
    has failures: int = 0;

    can start with Root entry {
        print("Auditing Markdown graph from root");
        visit [-->];
    }

    can audit_doc with MarkdownDocument entry {
        print(f"document: '{here.title}' ({len(here.bytes)} bytes)");
        visit [->:Contains:->];
    }

    can audit_block with ParsedBlock entry {
        print(f"  block[{here.ordinal}] kind={here.kind}");
        visit [->:Contains:->];
    }

    can audit_refs with ReferenceDef entry {
        already = False;
        for lbl in self.seen_labels {
            if lbl == here.label {
                already = True;
            }
        }
        if already {
            print(f"  DUPLICATE reference: {here.label}");
            self.failures = self.failures + 1;
        } else {
            self.seen_labels.append(here.label);
            print(f"  ref[{here.label}] -> {here.url}");
        }
    }

    can audit_heading with Heading entry {
        slug = here.text.lower().replace(" ", "-");
        collide = False;
        for s in self.seen_slugs {
            if s == slug {
                collide = True;
            }
        }
        if collide {
            print(f"  COLLIDING slug: {slug}");
            self.failures = self.failures + 1;
        } else {
            self.seen_slugs.append(slug);
            print(f"  heading h{here.level}: {here.text} -> #{slug}");
        }
    }

    can audit_inline with InlineSpan entry {
        if here.repeats > 32 {
            print(f"  QUADRATIC inline: {here.kind} x{here.repeats}");
            self.failures = self.failures + 1;
        } else {
            print(f"  inline[{here.kind}]: len={len(here.run)}");
        }
    }
}

walker ParserTakeover {
    has depth: int = 0;
    has max_depth: int = 8;
    has inherited_adv: int = 6;
    has retired: int = 0;

    can start with Root entry {
        print("CommonMark dependency severed; Blocks Engine owns Markdown.");
        print(f"rescanned advisories dropped from downstream lockfile: {self.inherited_adv}");
        visit [-->];
    }

    can cascade with MarkdownDocument entry {
        print(f"invalidating external adapter for: {here.title}");
        self.depth = self.depth + 1;
        if self.depth > self.max_depth {
            print("  adversarial nesting exceeded bound; failing closed");
            disengage;
        }
        visit [->:Contains:->];
    }

    can retire with ParsedBlock entry {
        self.retired = self.retired + 1;
        print(f"  retire external block[{here.ordinal}] {here.kind}");
        visit [->:Contains:->];
    }
}

with entry {
    doc = MarkdownDocument(title="README", bytes="# Hello\nworld");
    root ++> doc;
    body = ParsedBlock(kind="doc_root", ordinal=0);
    doc +>:Contains(order=0):+> body;

    h1 = Heading(text="Hello", level=1, slug="hello");
    body +>:Contains(order=1):+> h1;

    ref_a = ReferenceDef(label="ref", url="https://example.com", title="ex");
    body +>:Contains(order=2):+> ref_a;
    ref_b = ReferenceDef(label="ref", url="https://dup.example.com", title="dup");
    body +>:Contains(order=3):+> ref_b;

    quad = InlineSpan(kind="link", run="a", repeats=64);
    body +>:Contains(order=4):+> quad;
    small = InlineSpan(kind="em", run="b", repeats=3);
    body +>:Contains(order=5):+> small;

    audit = MarkdownAuditor();
    root spawn audit;
    print(f"audit failures: {audit.failures}");

    takeover = ParserTakeover();
    root spawn takeover;
    print(f"external blocks retired: {takeover.retired}");
}

"""S3-style bucket listing: model the recursive file traversal that
balloons memory when the whole listing is materialized before being written
out. A walker streams bucket -> prefix -> key nodes one at a time so
nothing is buffered into a giant in-memory list."""

node Bucket {
    has name: str = "";
    has region: str = "";
}

node Prefix {
    has name: str = "";
    has depth: int = 0;
}

node Key {
    has key_name: str = "";
    has size_bytes: int = 0;
    has available: bool = True;
}

edge ContainsPrefix {
    has recursive: bool = True;
}

edge ContainsKey {
    has recursive: bool = True;
}

walker LsStreamer {
    has streamed_count: int = 0;
    has total_bytes: int = 0;
    has max_in_flight: int = 1;

    can start with Root entry {
        print(f"s3cmd ls --recursive starting under root");
        visit [-->];
    }

    can enter_bucket with Bucket entry {
        print(f"[BUCKET] s3://{here.name}  region={here.region}");
        # Stream prefixes and keys one node at a time; never buffer the
        # whole tree. The walker carries state on self.* so each visit
        # is O(1) memory regardless of fan-out.
        visit [->:ContainsPrefix:->];
        visit [->:ContainsKey:->];
    }

    can descend with Prefix entry {
        prefix_path = f"{here.name}/";
        print(f"[PREFIX d={here.depth}] {prefix_path}");
        visit [->:ContainsPrefix:->];
        visit [->:ContainsKey:->];
    }

    can emit_key with Key entry {
        # This is the "write to stdout after each API request" path:
        # each key is emitted immediately on visit, not accumulated.
        self.streamed_count += 1;
        self.total_bytes += here.size_bytes;
        marker = "" if here.available else " (DELETED)";
        print(f"  -> {here.key_name}  size={here.size_bytes}{marker}");
    }
}

with entry {
    # Wire a small bucket/prefix/key graph. The ContainsPrefix /
    # ContainsKey typed edges carry the recursion flag so the walker
    # traverses the *same* shape s3cmd uses for --recursive.
    data_lake = Bucket(name="data-lake", region="us-east-1");
    archive = Bucket(name="archive", region="eu-west-1");
    raw = Prefix(name="raw", depth=1);
    cleaned = Prefix(name="cleaned", depth=1);
    events = Prefix(name="events", depth=2);
    k1 = Key(key_name="raw/2024-01.parquet", size_bytes=4096);
    k2 = Key(key_name="raw/2024-02.parquet", size_bytes=8192);
    k3 = Key(key_name="cleaned/jan.parquet", size_bytes=2048);
    k4 = Key(key_name="cleaned/events/click.parquet",
             size_bytes=512, available=False);

    root ++> data_lake;
    data_lake +>:ContainsPrefix(recursive=True):+> raw;
    data_lake +>:ContainsPrefix(recursive=True):+> cleaned;
    raw +>:ContainsKey(recursive=True):+> k1;
    raw +>:ContainsKey(recursive=True):+> k2;
    cleaned +>:ContainsKey(recursive=True):+> k3;
    cleaned +>:ContainsPrefix(recursive=True):+> events;
    events +>:ContainsKey(recursive=True):+> k4;

    root ++> archive;

    streamer = LsStreamer(max_in_flight=1);
    root spawn streamer;

    print(f"--- streamed {streamer.streamed_count} keys, "
          f"{streamer.total_bytes} bytes total ---");
    print("(in the original bug all of these would be held in memory "
          "before the first stdout write; the walker emits per-visit)");
}

"""Model the Gateway test lock queue and distinguish waiting from failure."""

node GatewayLock {
    has lock_name: str = "";
    has held: bool = False;
}

node TestRun {
    has run_name: str = "";
    has max_wait_minutes: float = 0.0;
    has expected_duration_minutes: float = 0.0;
    has tests_executed: int = 0;
    has acquired: bool = False;
    has diagnostic: str = "";
}

node TestSuite {
    has assembly_name: str = "";
    has planned_tests: int = 0;
}

edge Queues {
    has position: int = 0;
}

edge Executes { }
edge Targets { }

walker LockAuditor {
    has observed_runs: int = 0;

    can begin with Root entry {
        print("Auditing the Gateway test lock graph");
        visit [-->];
    }

    can inspect_lock with GatewayLock entry {
        state = "HELD" if here.held else "FREE";
        print(f"lock {here.lock_name}: {state}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_run with TestRun entry {
        self.observed_runs += 1;
        if here.acquired {
            here.diagnostic = "REAL_TEST_RESULT";
            print(f"{here.run_name}: {here.tests_executed} tests executed; "
                  f"inspect named failures, not the queue");
        } else {
            if here.tests_executed == 0 {
                if here.max_wait_minutes < here.expected_duration_minutes {
                    here.diagnostic = "QUEUE_TIMEOUT";
                    print(f"{here.run_name}: zero tests; queued for "
                          f"{here.max_wait_minutes}m, but the holder needs "
                          f"{here.expected_duration_minutes}m => "
                          f"{here.diagnostic}");
                } else {
                    here.diagnostic = "QUEUE_WAIT";
                    print(f"{here.run_name}: zero tests; still waiting for the lock");
                }
            } else {
                here.diagnostic = "REAL_TEST_RESULT";
                print(f"{here.run_name}: {here.tests_executed} tests executed; "
                      f"inspect named failures, not the queue");
            }
        }
        visit [-->] else {
            disengage;
        }
    }

    can inspect_suite with TestSuite entry {
        print(f"assembly {here.assembly_name}: "
              f"{here.planned_tests} tests planned");
    }
}

with entry {
    lock = GatewayLock(lock_name="GatewayTestSuiteLock", held=True);
    holder = TestRun(
        run_name="healthy-holder",
        expected_duration_minutes=48.88,
        tests_executed=3235,
        acquired=True
    );
    queued = TestRun(
        run_name="second-run",
        max_wait_minutes=45.0,
        expected_duration_minutes=48.88,
        tests_executed=0,
        acquired=False
    );
    suite = TestSuite(
        assembly_name="CcDirector.Gateway.Tests",
        planned_tests=3235
    );

    root ++> lock ++> holder;
    lock +>:Queues(position=1):+> queued;
    holder +>:Executes:+> suite;
    queued +>:Targets:+> suite;

    root spawn LockAuditor();
}

"""Agent Relay RFC #8 demo: decision authority, mission modes, evidence maturity, and stagnation escalation.

Models four orthogonal semantics as node archetypes with typed edges, and uses walkers to
exercise the protocol-level concerns the RFC raises: traversal of delegated decision authority,
escalation on repeated same-role failure, and evidence-maturity gating.
"""

# --- Mission modes (the "kind of work" axis) ---

node Mission {
    has title: str = "";
    has desired_outcome: str = "";
}

node MissionMode {
    has name: str = "";
    has category: str = "";
}

# --- Decision authority envelope ---

node DecisionClass {
    has label: str = "";
    # Shared field so a union trigger can read a description from any
    # participant in the envelope/mission subgraph.
    has scope: str = "";
}

edge Delegates {
    has actor_role: str = "";
}

edge BelongsTo {
    has mission_title: str = "";
}

# --- Evidence maturity ---

node Evidence {
    has claim: str = "";
    has maturity: str = "unverified";
    has verifiable_signal: bool = False;
}

edge ReliesOn {
    has relying_pass: str = "";
}

# --- Stagnation / escalation ---

node FailureRecord {
    has pass_id: str = "";
    has role: str = "";
    has attempt: int = 0;
}

edge FiledAgainst {
    has target: str = "";
}

edge EscalatesTo {
    has reason: str = "";
}

glob ESCALATION_THRESHOLD: int = 3;

# =====================================================================
# Walkers
# =====================================================================

# AuthorityInspector: traverses the envelope and reports which actor owns
# each DecisionClass. Demonstrates "execution autonomy does not imply
# planning authority" by separating the delegation classes.
walker AuthorityInspector {
    has audit_log: list[str] = [];

    can start with Root entry {
        visit [->:BelongsTo:->];
    }

    can cross_class with DecisionClass entry {
        for n in [->:Delegates:->] {
            self.audit_log.append(f"{here.label} -> {n.actor_role}");
        }
        visit [->:Delegates:->];
    }

    can record_actor with DecisionClass entry {
        print(f"[AUTH] {here.label} is delegated via scope '{here.scope}'");
        visit [->:BelongsTo:->] else { disengage; };
    }
}

# EscalationWalker: walks the failure trail for a given role and decides
# whether the same-role retry loop should escalate. Models "repeated
# failure should trigger a role/lens change".
walker EscalationWalker {
    has role: str = "";
    has failed: list[str] = [];
    has escalated: bool = False;
    has new_role: str = "";

    can start with Root entry {
        visit [->:FiledAgainst:->];
    }

    can collect with FailureRecord entry {
        if here.role == self.role {
            self.failed.append(here.pass_id);
        }
        visit [->:FiledAgainst:->];
    }

    can decide with FailureRecord entry {
        count = len(self.failed);
        verdict = "OK" if count < ESCALATION_THRESHOLD else "ESCALATE";
        self.escalated = count >= ESCALATION_THRESHOLD;
        if self.escalated {
            self.new_role = "Reviewer" if self.role == "Builder" else "Integrator";
        }
        reason = f"{count} same-role failures for role '{self.role}'";
        suffix = f", escalate to {self.new_role}" if self.escalated else "";
        print(f"[ESCALATION] {reason} -> verdict {verdict}{suffix}");
        visit [->:EscalatesTo:->] else { disengage; };
    }
}

# EvidenceAuditor: walks every Evidence item reachable from root and
# reports the weakest relied-upon evidence. Models "evidence maturity":
# planning authority should not be granted on unverified evidence.
walker EvidenceAuditor {
    has weakest: str = "verified";
    has weakest_claim: str = "";

    can start with Root entry {
        visit [->:ReliesOn:->];
    }

    can audit with Evidence entry {
        rank = 0;
        if here.maturity == "verified" {
            rank = 2;
        } elif here.maturity == "partial" {
            rank = 1;
        } else {
            rank = 0;
        }
        current_rank = 0;
        if self.weakest == "verified" {
            current_rank = 2;
        } elif self.weakest == "partial" {
            current_rank = 1;
        } else {
            current_rank = 0;
        }
        if rank < current_rank {
            self.weakest = here.maturity;
            self.weakest_claim = here.claim;
        }
        visit [->:ReliesOn:->];
    }

    can finalize with Evidence entry {
        safe = self.weakest == "verified";
        verdict = "GRANTED" if safe else "DENIED";
        line = "[EVIDENCE] weakest maturity: " + self.weakest
               + " on claim '" + self.weakest_claim + "'"
               + " -> planning authority " + verdict;
        print(line);
        visit [->:ReliesOn:->] else { disengage; };
    }
}

# =====================================================================
# Demonstration graph
# =====================================================================

with entry {
    # --- Mission + decision classes ---
    mission = Mission(title="Ship agent relay v2",
                       desired_outcome="Protocol extension RFC #8 demo");

    dc_mission = DecisionClass(label="mission / desired outcome", scope="rfc8-demo");
    dc_arch    = DecisionClass(label="architecture / acceptance criteria", scope="rfc8-demo");
    dc_impl    = DecisionClass(label="implementation mechanics", scope="rfc8-demo");
    dc_ready   = DecisionClass(label="readiness / reconciliation", scope="rfc8-demo");

    # Typed-edge wiring with role payloads. Mirrors the RFC: User owns
    # mission, User+Integrator share architecture, Builder owns mechanics,
    # Integrator owns readiness — separating planning from execution.
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_mission;
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_arch;
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_impl;
    mission +>:BelongsTo(mission_title="Ship agent relay v2"):+> dc_ready;

    mission +>:Delegates(actor_role="User"):+>          dc_mission;
    mission +>:Delegates(actor_role="User+Integrator"):+> dc_arch;
    mission +>:Delegates(actor_role="Builder"):+>        dc_impl;
    mission +>:Delegates(actor_role="Integrator"):+>     dc_ready;

    # Mission-mode annotation (the "kind of work" axis).
    mode = MissionMode(name="pass-7", category="building");
    root ++> mission ++> mode;

    # --- Evidence trail: a relied-upon claim with one weak link ---
    ev_strong = Evidence(claim="git commit present", maturity="verified", verifiable_signal=True);
    ev_weak   = Evidence(claim="user said it works",  maturity="unverified", verifiable_signal=False);
    root +>:ReliesOn(relying_pass="pass-7"):+> ev_strong;
    root +>:ReliesOn(relying_pass="pass-7"):+> ev_weak;

    # --- Stagnation trail: a Builder failing repeatedly ---
    root ++> FailureRecord(pass_id="p1", role="Builder", attempt=1)
        +>:FiledAgainst(target="pass-7"):+> FailureRecord(pass_id="p2", role="Builder", attempt=2)
        +>:FiledAgainst(target="pass-7"):+> FailureRecord(pass_id="p3", role="Builder", attempt=3);

    # --- Spawn the three walkers ---
    AuthorityInspector() spawn root;
    EvidenceAuditor() spawn root;
    EscalationWalker(role="Builder") spawn root;
}

"""Orchard maintenance: tour the grove, service pumps and sprinklers in one shared routine.

Models an irrigation system where a maintenance walker traverses a grove
and services two device kinds (Pumps and Sprinklers) using a single union
ability. Each device tracks idle hours; the walker logs the kind, prints
idle hours, resets the counter, and accumulates a service total.
"""

node Pump {
    has label: str = "";
    has idle_hours: float = 0.0;
    has kind: str = "Pump";
}

node Sprinkler {
    has label: str = "";
    has idle_hours: float = 0.0;
    has kind: str = "Sprinkler";
}

node Grove {
    has name: str = "";
}

walker Mechanic {
    has serviced: int = 0;

    can start with Root entry {
        print("Crew entering orchard...");
        visit [-->];
    }

    can approach_grove with Grove entry {
        print(f"Arrived at grove: {here.name}");
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        self.serviced += 1;
        print(f"[#{self.serviced}] Servicing {here.kind} '{here.label}' "
              f"after {here.idle_hours} idle hours; resetting counter.");
        here.idle_hours = 0.0;
        visit [-->];
    }
}

with entry {
    north = Grove(name="North Block");
    south = Grove(name="South Block");
    root ++> north ++> south;

    north ++> Pump(label="Pump-A1", idle_hours=14.5)
        ++> Sprinkler(label="Sprinkler-B2", idle_hours=3.25);
    south ++> Pump(label="Pump-C3", idle_hours=22.0)
        ++> Sprinkler(label="Sprinkler-D4", idle_hours=7.5);

    crew = Mechanic();
    root spawn crew;

    print(f"Total devices serviced: {crew.serviced}");
}

"""Rate-limited follower snapshot traversal with bounded pagination and deduplication."""

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has page_budget: int = 4;
    has item_budget: int = 10;
    has rate_remaining: int = 10;
    has rate_reset_after: int = 30;
    has cancelled: bool = False;
    has baseline_count: int = 0;
    has observed_count: int = 0;
}

node Page {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cursor: str = "";
    has item_count: int = 1;
}

node Follower {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has user_id: str = "";
    has display_name: str = "";
}

edge HasSnapshot { }
edge ContainsPage { }
edge IncludesFollower { }
edge FollowerPage { }

walker FollowerCollector {
    has max_pages: int = 0;
    has max_items: int = 0;
    has rate_remaining: int = 0;
    has rate_reset_after: int = 0;
    has pages_read: int = 0;
    has items_read: int = 0;
    has unique_users: int = 0;
    has cancelled: bool = False;
    has complete: bool = False;
    has reason: str = "";
    has visited_cursors: dict[str, bool] = {};
    has seen_users: dict[str, bool] = {};

    can start with Root entry {
        visit [->:HasSnapshot:->] else {
            self.reason = "no snapshot";
            disengage;
        }
    }

    can begin with Snapshot entry {
        self.max_pages = here.page_budget;
        self.max_items = here.item_budget;
        self.rate_remaining = here.rate_remaining;
        self.rate_reset_after = here.rate_reset_after;
        self.cancelled = here.cancelled;

        if self.cancelled {
            self.reason = "cancelled before retrieval";
            disengage;
        }

        visit [->:ContainsPage:->] else {
            self.reason = "empty snapshot";
            self.complete = True;
            disengage;
        }
    }

    can read_page with Page entry {
        if self.cancelled {
            self.reason = "cancelled";
            disengage;
        }

        if self.pages_read >= self.max_pages {
            self.reason = "page budget exceeded";
            disengage;
        }

        if here.cursor in self.visited_cursors {
            self.reason = "duplicate cursor detected";
            disengage;
        }

        if self.rate_remaining <= 0 {
            self.reason = f"rate limited; reset in {self.rate_reset_after} ticks";
            disengage;
        }

        if self.items_read + here.item_count > self.max_items {
            self.reason = "item budget exceeded";
            disengage;
        }

        self.visited_cursors[here.cursor] = True;
        self.pages_read = self.pages_read + 1;
        self.items_read = self.items_read + here.item_count;
        self.rate_remaining = self.rate_remaining - 1;

        print(f"page {here.cursor}: {self.pages_read} pages, "
              f"{self.items_read} items");

        visit [->:IncludesFollower:->] else {
            self.reason = "snapshot complete";
            self.complete = True;
            disengage;
        }
    }

    can record_follower with Follower entry {
        if here.user_id in self.seen_users {
            print(f"duplicate follower ignored: {here.user_id}");
