"""Desktop dependency graph: model vulnerable crates, traverse paths, and
flag advisory reachability through a typed dependency walker.

The issue (cryptnetworks/NexaChat #210) describes a graph of direct and
transitive Rust dependencies where a medium-severity advisory on `glib`
0.18.5 is reachable through the Tauri -> gtk -> glib path, and several
unmaintained crate chains must be inventoried.  This demo lifts the
"parent_id"-style dependency walk to native Jac: Crates are nodes, the
relationship `depends on` is a typed edge, and an auditor walker walks
the graph accumulating advisory findings.
"""

node Crate {
    has name: str = "";
    has version: str = "";
    has vulnerable: bool = False;
    has unmaintained: bool = False;
}

edge DependsOn {
    has dep_kind: str = "transitive";
}

walker Auditor {
    has findings: list = [];
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Crate entry {
        # Cycle / re-visit guard: walkers in Jac 0.36.1 do not dedupe
        # automatically, so we enforce single-entry per crate name.
        already = False;
        for v in self.visited {
            if v == here.name {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited.append(here.name);

        if here.vulnerable {
            note = f"VULN {here.name}@{here.version} reachable";
            self.findings.append(note);
            print(note);
        }
        if here.unmaintained {
            note = f"UNMAINTAINED {here.name}@{here.version} reachable";
            self.findings.append(note);
            print(note);
        }

        visit [->:DependsOn:->];
    }
}

walker ReachabilityProbe {
    has target: str = "glib";
    has found: bool = False;
    has path: list = [];

    can start with Root entry {
        visit [-->];
    }

    can probe with Crate entry {
        if here.name == self.target {
            self.found = True;
            self.path.append(here.name);
            disengage;
        }
        visit [->:DependsOn:->];
    }
}

with entry {
    # Build the desktop crate graph.  Tauri is the root of the
    # desktop binary's native dependency tree.
    tauri = Crate(name="nexa-desktop", version="2.11.5");
    gtk = Crate(name="gtk", version="0.18.2", unmaintained=True);
    glib = Crate(
        name="glib",
        version="0.18.5",
        vulnerable=True,
    );
    gtk_fixed = Crate(name="gtk", version="0.20.0");
    glib_fixed = Crate(name="glib", version="0.20.0");
    tauri_runtime = Crate(name="tauri-runtime-wry", version="2.11.5");
    wry = Crate(name="wry", version="2.11.5");
    tao = Crate(name="tao", version="2.11.5");
    webkit2gtk = Crate(name="webkit2gtk", version="2.11.5", unmaintained=True);
    tauri_utils = Crate(name="tauri-utils", version="2.11.5");
    urlpattern = Crate(name="urlpattern", version="0.3.0", unmaintained=True);
    unic = Crate(name="unic", version="1.4.0", unmaintained=True);
    proc_macro_error = Crate(name="proc-macro-error", version="1.0.0", unmaintained=True);

    # Wire the graph: root -> desktop, then typed `DependsOn` edges
    # for every direct or transitive pull-in.
    root ++> tauri;
    tauri +>:DependsOn(dep_kind="direct"):+> gtk;
    gtk +>:DependsOn:+> glib;
    tauri +>:DependsOn:+> tauri_runtime;
    tauri_runtime +>:DependsOn:+> wry;
    wry +>:DependsOn:+> tao;
    tao +>:DependsOn:+> webkit2gtk;
    tauri +>:DependsOn:+> tauri_utils;
    tauri_utils +>:DependsOn:+> urlpattern;
    urlpattern +>:DependsOn:+> unic;
    tauri +>:DependsOn:+> proc_macro_error;

    # Reachable from the upgraded gtk (0.20.0) which pulls glib 0.20.0.
    root ++> gtk_fixed;
    gtk_fixed +>:DependsOn:+> glib_fixed;

    print("== reachability probe for glib ==");
    probe = ReachabilityProbe(target="glib");
    root spawn probe;
    print(f"glib reachable from desktop root: {probe.found}");

    print("== full audit walk ==");
    auditor = Auditor();
    root spawn auditor;
    print(f"auditor findings: {auditor.findings}");
}

A maintainer on the project pathosDev/actor-ts (TypeScript) filed this issue about hand-rolled graph machinery causing pain:

Issue #946: [Bug] `encodeRefs`/`decodeRefs` never remove from their `WeakSet`, so it is visited-detection rather than cycle-detection and every repeated object in a cross-node message body arrives as `null`

## Problem

`encodeRefs` and `decodeRefs` walk the message body with a `WeakSet` that is added to on first visit and never removed. That is visited-detection, not cycle-detection: it cannot tell "this object is an ancestor of itself" from "this object appears twice in a tree". The second occurrence of any shared object is replaced with `null`.

Sharing an object across two fields of a message is not an exotic pattern — it is what you get from `const user = …; ref.tell({ author: user, reviewer: user })`, from a list built by `items.map(() => sameDefaults)`, from a lookup table referenced from several entries, or from any normalised in-memory graph. `encodeRefs` runs on every cross-node send (`Cluster._sendEnvelope` is the single chokepoint) and `decodeRefs` on every receive, so the corruption applies to every remote `tell`, every sharded entity message, every pub-sub publication and every singleton delivery. There is no error, no warning, and no way for the receiver to notice: it gets a well-formed object with a `null` where a value should be.

Correct cycle detection removes the node from the set when its subtree is done — an *ancestor* path set, not a visited set. That is a one-line change on each walker and preserves the existing protection against genuine cycles.

## Evidence

```ts
src/cluster/RefCodec.ts:134-147
function walk(value: unknown, encodeRef: RefEncoder, seen: WeakSet<object>): unknown {
  if (value === null || value === undefined) return value;
  if (typeof value !== 'object') return value;
  if (value instanceof ActorRef) return encodeRef(value);
  // Types JSON already handles (or silently lossy): leave alone.
  if (value instanceof Date) return value;
  if (value instanceof Uint8Array) return value;

  if (seen.has(value as object)) return null;  // break cycles
  seen.add(value as object);

  if (Array.isArray(value)) {
    return value.map((v) => walk(v, encodeRef, seen));
  }
```

```ts
src/cluster/RefCodec.ts:166-178
function walkDecode(value: unknown, cluster: Cluster, seen: WeakSet<object>): unknown {
  if (value === null || value === undefined) return value;
  if (typeof value !== 'object') return value;

  if (isWireActorRef(value)) return decodeSingleRef(value, cluster);
  if (value instanceof Date || value instanceof Uint8Array) return value;

  if (seen.has(value as object)) return null;
  seen.add(value as object);

  if (Array.isArray(value)) {
    return value.map((v) => walkDecode(v, cluster, seen));
  }
```

Neither walker ever calls `seen.delete`. The comment on `:142` says "break cycles"; the code breaks repetition.

## Proposal

Make `seen` an ancestor set rather than a visited set — add before recursing, delete after:

```
seen.add(value as object);
const out = /* … recurse … */;
seen.delete(value as object);
return out;
```

That keeps the cycle guard exact (a value is only in `seen` while it is on the current path) and lets a DAG round-trip. The `Map`/`Set` and object branches need the same treatment, and both walkers do.

Worth deciding explicitly while the walkers are open: whether a *true* cycle should still become `null` silently, or should throw. Today a cycle and a shared reference produce the same output, so a user cannot distinguish "you sent a cycle" from "the codec dropped your data". Once they are distinguishable, a cycle is a programming error worth reporting.

Note this is a *fidelity* fix, not a *sharing* fix: the wire format is JSON, so the receiver gets two structurally equal objects rather than one shared object. That matches `JSON.parse(JSON.stringify(x))` and is the documented expectation for cross-node messages; silently substituting `null` is not.

#247 asks for the `instanceof` chains in this file to become `match()` — same file, unrelated concern; the walkers are the dispatch-free part.

## Acceptance sketch

- [ ] `encodeRefs({ a: shared, b: shared })` produces both values, not `{ a: {…}, b: null }`.
- [ ] The same holds for repeated entries in arrays, `Map` valu

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

"""RefCodec demo: ancestor-path cycle detection (issue #946) over a message-body graph.

Shared objects are visited as many times as they appear; only true cycles
(a node on its own ancestry path) are broken to null — add-before-recurse,
delete-after, so `seen` is an ancestor set, not a visited set.
"""

node Body {
    has kind: str = "value";   # "value" | "array" | "map" | "ref"
    has text: str = "";        # payload for scalar values
    has null_broken: bool = False;  # set when a cycle was cut here
}

edge Item { }   # container -> child element

edge CyclesTo { }  # back-edge forming a true cycle

walker Encoder {
    has seen: list = [];        # stack of current-path nodes (ancestor set)
    has out: list = [];

    def on_path(n: Body) -> bool {
        for a in self.seen {
            if a is n { return True; }
        }
        return False;
    }

    def encode(n: Body) -> str {
        if n is None { return "null"; }
        if n.kind == "ref" or n.kind == "value" {
            leaf = f"{n.kind}({n.text})";
            return leaf;
        }
        if self.on_path(n) {
            n.null_broken = True;
            return "null  # cycle broken";
        }
        self.seen.append(n);
        parts = [];
        for k in [n -->] {
            parts.append(self.encode(k));
        }
        self.seen.pop();
        opener = "[" if n.kind == "array" else "{";
        closer = "]" if n.kind == "array" else "}";
        return f"{opener}{', '.join(parts)}{closer}";
    }

    can start with Root entry {
        visit [-->];
    }

    can with Body entry {
        self.out.append(self.encode(here));
        visit [-->] else { disengage; }
    }
}

with entry {
    shared = Body(kind="value", text="user");
    msg = Body(kind="map");
    msg +>:Item:+> Body(kind="value", text="author=");
    msg +>:Item:+> shared;      # shared object appearing twice — must survive
    msg +>:Item:+> shared;
    arr = Body(kind="array");
    arr +>:Item:+> shared;      # third appearance in a tree — still fine
    msg +>:Item:+> arr;

    cyclic = Body(kind="map");
    inner = Body(kind="map");
    cyclic +>:Item:+> inner;
    inner +>:CyclesTo:+> cyclic;   # genuine cycle — must be cut

    root ++> msg ++> cyclic;
    enc = root spawn Encoder();
    for enc_line in enc.out {
        print(enc_line);
    }
    print(f"nodes cut by cycle guard: "
          f"{sum(1 for b in [root -->] if b.null_broken)}");
}

