"""Trip planner that shortlists only top-rated attractions.

A city graph mixes Station, Hotel and Attraction nodes. From each
station the planner looks one hop out, keeps just attraction nodes,
and then narrows further to those rated 4 stars or higher.
"""

node Station {
    has name: str;
}

node Hotel {
    has name: str;
}

node Attraction {
    has name: str;
    has rating: float;
}

edge Walk {}

walker Planner {
    has itinerary: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Station entry {
        # One hop reaches hotels and attractions alike; keep attractions only
        sights = [->:Walk:->][?:Attraction];

        # Attribute filter: top-rated sights only
        best = [->:Walk:->][?rating >= 4.0];

        for a in best {
            self.itinerary.append(f"{a.name} ({a.rating} stars, reachable from {here.name})");
        }

        # The type filter alone sees everything attraction-shaped
        print(f"Near {here.name}: {len(sights)} attraction(s), {len(best)} top-rated");
        visit [-->];
    }

    can finish with Root exit {
        print("-- Itinerary --");
        for stop in self.itinerary {
            print(stop);
        }
    }
}

with entry {
    central = Station(name="Central");
    riverside = Station(name="Riverside");

    grand = Hotel(name="Grand Hotel");
    museum = Attraction(name="City Museum", rating=4.7);
    park = Attraction(name="Riverside Park", rating=3.9);
    tower = Attraction(name="Old Tower", rating=4.5);

    central +>: Walk() :+> grand;
    central +>: Walk() :+> museum;
    riverside +>: Walk() :+> park;
    riverside +>: Walk() :+> tower;

    root ++> central ++> riverside;
    root spawn Planner();
}

"""Model an out-of-tree BotNexus extension build seam with typed graph traversal."""

node Repository {
    has requested_root: str = "";
    has resolved_root: str = "/home/demo/.botnexus/BotNexus";
    has root_valid: bool = False;
    has live_deployment_mutated: bool = False;
}

node Extension {
    has name: str = "";
    has source_reference: bool = True;
    has built: bool = False;
}

node BuildArtifact {
    has name: str = "";
    has staged: bool = False;
    has copy_local_lock_file_assemblies: bool = True;
    has transitive_dependencies: int = 0;
    has live_deployment_mutated: bool = False;
}

edge RegisteredExtension { }
edge DependsOn {
    has order: int = 0;
}
edge Produces { }

walker BuildPlanner {
    has seen: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can resolve with Repository entry {
        print(f"resolved BotNexusRepoRoot={here.resolved_root}");
        if here.requested_root == "" {
            print(f"missing BotNexusRepoRoot; resolved path: {here.resolved_root}");
        }
        visit [->:RegisteredExtension:->] else {
            disengage;
        }
    }

    can order with Extension entry {
        if here.name in self.seen {
            self.cycle_detected = True;
            print(f"dependency cycle detected at {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        if here.source_reference {
            print(f"{here.name}: source-reference template");
        } else {
            print(f"{here.name}: binary-reference template");
        }
        visit [->:DependsOn:->] else {
            print(f"{here.name}: dependency order complete");
        }
    }
}

walker StagingAuditor {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Repository entry {
        visit [->:RegisteredExtension:->] else {
            disengage;
        }
    }

    can stage with Extension entry {
        print(f"checking staged output for {here.name}");
        visit [->:Produces:->] else {
            print(f"{here.name}: no staged artifact");
        }
    }

    can verify with BuildArtifact entry {
        if here.staged {
            if here.copy_local_lock_file_assemblies {
                if here.transitive_dependencies > 0 {
                    if here.live_deployment_mutated == False {
                        print(f"{here.name}: staged with transitive dependencies; live deployment untouched");
                    }
                }
            }
        }
    }
}

with entry {
    repository = Repository(
        requested_root="",
        resolved_root="/home/demo/.botnexus/BotNexus",
        root_valid=False,
        live_deployment_mutated=False
    );

    source_extension = Extension(
        name="WeatherExtension",
        source_reference=True,
        built=True
    );
    binary_extension = Extension(
        name="MetricsExtension",
        source_reference=False,
        built=True
    );

    source_artifact = BuildArtifact(
        name="WeatherExtension-stage",
        staged=True,
        copy_local_lock_file_assemblies=True,
        transitive_dependencies=3,
        live_deployment_mutated=False
    );
    binary_artifact = BuildArtifact(
        name="MetricsExtension-stage",
        staged=True,
        copy_local_lock_file_assemblies=True,
        transitive_dependencies=2,
        live_deployment_mutated=False
    );

    root ++> repository;
    repository +>:RegisteredExtension:+> source_extension;
    repository +>:RegisteredExtension:+> binary_extension;

    source_extension +>:DependsOn(order=1):+> binary_extension;
    binary_extension +>:DependsOn(order=2):+> source_extension;

    source_extension +>:Produces:+> source_artifact;
    binary_extension +>:Produces:+> binary_artifact;

    root spawn BuildPlanner();
    root spawn StagingAuditor();
