node Room {
    has name: str = "";
    has required_level: int = 0;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_entered: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk with Room entry {
        if here.required_level <= self.clearance {
            self.rooms_entered += 1;
            print(f"{self.name} GRANTED entry to {here.name} "
                  f"(needs {here.required_level})");
            visit [-->];
        } else {
            print(f"{self.name} DENIED entry to {here.name} "
                  f"(needs {here.required_level}, has {self.clearance})");
            disengage;
        }
    }
}

