    print(f"-> {junior.name} reached {junior.rooms_entered} rooms");

    senior = Technician(name="Senior", clearance=3);
    root spawn senior;
    print(f"-> {senior.name} reached {senior.rooms_entered} rooms");

    contractor = Technician(name="Contractor", clearance=1);
    root spawn contractor;
    print(f"-> {contractor.name} reached {contractor.rooms_entered} rooms");
