"""Resolve bounded package-script indirection without executing scripts."""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has manifest: str = "package.json";
}

node Workflow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Script {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has command: str = "";
    has local_target: str = "";
    has dynamic: bool = False;
}

edge HasWorkflow { }

edge Invokes {
    has kind: str = "local-script";
}

walker ScriptResolver {
    has max_hops: int = 8;
    has steps: int = 0;
    has tests_observed: int = 0;
    has unknown_count: int = 0;
    has cycle_count: int = 0;
    has missing_count: int = 0;
    has seen_titles: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_package with Package entry {
        visit [->:HasWorkflow:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        visit [->:Invokes:->] else {
            self.unknown_count += 1;
        }
    }

    can resolve_script with Script entry {
        if self.steps >= self.max_hops {
            self.unknown_count += 1;
        } elif here.title in self.seen_titles {
            self.cycle_count += 1;
            print(f"cycle stopped at {here.title}");
        } else {
            self.seen_titles.append(here.title);
            self.steps += 1;

            if here.command == "npm test"
                or here.command == "node --test"
                or here.command == "pytest" {
                self.tests_observed += 1;
                print(f"test command observed: {here.command}");
            } elif here.dynamic {
                self.unknown_count += 1;
                print(f"ambiguous script remains unknown: {here.title}");
            } elif here.local_target != "" {
                visit [->:Invokes:->] else {
                    self.missing_count += 1;
                    self.unknown_count += 1;
                    print(f"missing script target: {here.local_target}");
                }
            } else {
                self.unknown_count += 1;
                print(f"unrecognized command remains unknown: {here.command}");
            }
        }
    }
}

with entry {
    package = Package(title="ForkWise", year=2024);

    quality = Workflow(title="Quality CI");
    package +>:HasWorkflow:+> quality;

    validate = Script(
        title="validate",
        command="npm run validate",
        local_target="test"
    );
    quality +>:Invokes(kind="workflow-script"):+> validate;

    test_script = Script(title="test", command="npm test");
    validate +>:Invokes:+> test_script;

    audit = Workflow(title="Audit CI");
    package +>:HasWorkflow:+> audit;

    dynamic_script = Script(
        title="dynamic",
        command="npm run $TARGET",
        dynamic=True
    );
    audit +>:Invokes:+> dynamic_script;

    cycle_a = Script(
        title="cycle-a",
        command="npm run cycle-b",
        local_target="cycle-b"
    );
    cycle_b = Script(
        title="cycle-b",
        command="npm run cycle-a",
        local_target="cycle-a"
    );
    cycle_a +>:Invokes:+> cycle_b;
    cycle_b +>:Invokes:+> cycle_a;

    cycle_workflow = Workflow(title="Cycle CI");
    package +>:HasWorkflow:+> cycle_workflow;
    cycle_workflow +>:Invokes:+> cycle_a;

    root ++> package;
    root spawn ScriptResolver();

    print("bounded inert script resolution complete");
}

"""Borrowed Sun: rolling mirror allocation, orbital failure cascade, and conflicting evidence resolution."""

node Mirror {
    has name: str = "";
    has capacity: int = 100;
    has failed: bool = False;
    has in_repair: bool = False;
}

node Habitat {
    has name: str = "";
    has need: int = 0;
    has contract_strength: int = 0;
    has legitimacy: int = 0;
    has precedent_pct: int = 0;
    has allocated: int = 0;
}

node Evidence {
    has subject: str = "";
    has tier: int = 0;
    has provenance: str = "";
    has claim: str = "";
}

edge OrbitalLink { }

edge Concerns { }

walker EvidenceInvestigator {
    has target_subject: str = "deferred_maintenance";
    has best_tier: int = 0;
    has best_provenance: str = "";
    has best_claim: str = "";

    can start with Root entry {
        print("=== Evidence trail: conflicting authentic records ===");
        visit [-->];
    }

    can weigh with Evidence entry {
        if here.subject == self.target_subject {
            print(f"  [tier {here.tier}] {here.provenance}: {here.claim}");
            sensor_wins = here.provenance == "sensor";
            incumbent_sensor = self.best_provenance == "sensor";
            if here.tier > self.best_tier {
                self.best_tier = here.tier;
                self.best_provenance = here.provenance;
                self.best_claim = here.claim;
            } elif here.tier == self.best_tier and sensor_wins and not incumbent_sensor {
                self.best_provenance = here.provenance;
                self.best_claim = here.claim;
            }
        }
        visit [-->];
    }

    can stop with Mirror | Habitat entry {
        disengage;
    }
}

walker AllocationSteward {
    has round: int = 1;
    has total_capacity: int = 0;
    has weight_sum: int = 125;
    has override_authority: bool = False;
    has capacity_reported: bool = False;

    can start with Root entry {
        if self.override_authority {
            self.weight_sum = 16;
            print(f"=== Round {self.round}: emergency override allocation ===");
        } else {
            self.weight_sum = 125;
            print(f"=== Round {self.round}: consent-path allocation ===");
        }
        visit [-->];
    }

    can passthrough with Evidence entry {
        visit [-->];
    }

    can survey with Mirror entry {
        if here.failed and not here.in_repair {
            effective = 0;
            print(f"  [FAIL] {here.name} offline (-{here.capacity} capacity)");
        } elif here.in_repair {
            effective = here.capacity // 2;
            print(f"  [REPAIR] {here.name} partial recovery ({effective})");
        } else {
            effective = here.capacity;
            print(f"  [OK] {here.name} contributing {effective}");
        }
        self.total_capacity += effective;
        visit [-->];
    }

    can allocate with Habitat entry {
        if not self.capacity_reported {
            print(f"  Network capacity: {self.total_capacity}");
            self.capacity_reported = True;
        }
        if self.override_authority {
            weight = here.contract_strength;
            mode = "OVERRIDE";
        } else {
            weight = here.need + here.precedent_pct;
            mode = "CONSENT";
        }
        share = (weight * self.total_capacity) // self.weight_sum;
        here.allocated = share;
        if share >= here.need {
            status = "met";
        } else {
            status = "SHORT";
        }
        print(
            f"  [{mode}] {here.name}: {share}/{here.need} ({status}) "
            f"— cites {here.precedent_pct}% precedent"
        );
        visit [--> ] else {
            if self.override_authority {
                print("  Compliance degrading: habitats draining buffers, blocking repair berth");
            } else {
                print("  Negotiation complete; allocations stand until next capacity shift");
            }
            disengage;
        };
    }
}

walker FailureCascade {
    can start with Root entry {
        print("=== Failure cascade along orbital mirror ring ===");
