"""Murmur FluidAudio engine graph with dependency and runtime audits."""

node Engine {
    has title: str = "";
    has state: str = "starting";
}

node Model {
    has title: str = "";
    has prepared: bool = False;
}

node AudioSession {
    has title: str = "";
    has microphone_ready: bool = False;
    has muted: bool = True;
    has accepted_tail_ms: int = 0;
}

edge Requires {
    has reason: str = "";
}

edge RunsSession {
    has mode: str = "";
}

walker DependencyAudit {
    has visited_titles: list[str] = [];
    has cycle_detected: bool = False;
    has depth: int = 0;

    can start with Root entry {
        print("Starting dependency audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_engine with Engine entry {
        if here.title in self.visited_titles {
            self.cycle_detected = True;
            print(f"Dependency cycle detected at {here.title}");
            disengage;
        } else {
            self.visited_titles.append(here.title);
            self.depth += 1;
            print(f"Engine dependency: {here.title}");
            visit [->:Requires:->] else {
                disengage;
            }
        }
    }

    can inspect_model with Model entry {
        if here.title in self.visited_titles {
            self.cycle_detected = True;
            print(f"Dependency cycle detected at {here.title}");
            disengage;
        } else {
            self.visited_titles.append(here.title);
            self.depth += 1;
            print(f"Model dependency: {here.title}");
            visit [->:Requires:->] else {
                disengage;
            }
        }
    }
}

walker RuntimeAudit {
    has sessions_seen: int = 0;
    has found_unmuted_session: bool = False;

    can start with Root entry {
        print("Starting runtime audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_engine with Engine entry {
        print(f"Runtime engine: {here.title} ({here.state})");
        visit [->:RunsSession:->] else {
            disengage;
        }
    }

    can inspect_session with AudioSession entry {
        self.sessions_seen += 1;
        if here.muted == False {
            self.found_unmuted_session = True;
        }
        print(
            f"Session {here.title}: ready={here.microphone_ready}, "
            f"muted={here.muted}, tail={here.accepted_tail_ms}ms"
        );
    }
}

with entry {
    engine = Engine(title="Murmur Apple Silicon", state="ready");
    encoder = Model(title="Speech Encoder", prepared=True);
    decoder = Model(title="Speech Decoder", prepared=True);
    session = AudioSession(
        title="Bluetooth microphone",
        microphone_ready=True,
        muted=True,
        accepted_tail_ms=180
    );

    root ++> engine;
    engine +>:Requires(reason="streaming encoder"):+> encoder;
    encoder +>:Requires(reason="decoder preparation"):+> decoder;
    decoder +>:Requires(reason="cycle probe"):+> encoder;
    engine +>:RunsSession(mode="source-level half duplex"):+> session;

    root spawn DependencyAudit();
    root spawn RuntimeAudit();
}

