node Vehicle {
    has kind: str = "";
    has axles: int = 0;
    has weight_tons: float = 0.0;
}

walker TollCollector {
    has revenue: float = 0.0;
    has cars: int = 0;
    has trucks: int = 0;
    has bikes: int = 0;

    can open_lane with Root entry {
        print("Gate G-4 opening for the sweep...");
        visit [-->];
    }

    can collect with Vehicle entry {
        fare = 0.0;
        label = here.kind;
        if here.kind == "car" {
            fare = 2.50;
            self.cars += 1;
        } elif here.kind == "truck" {
            fare = 2.50 + 0.50 * here.weight_tons;
            self.trucks += 1;
        } elif here.kind == "motorcycle" {
            fare = 1.00;
            self.bikes += 1;
        }
        self.revenue += fare;
