"""Fighter advancements view: model N+1 query issue with explicit pre-fetch walker.

Scenario distilled from gyrinx-app/gyrinx issue #768. A fighter has
advancements (skill upgrades, campaign actions), and the template also
needs the fighter's content_fighter template data. Without a pre-fetch
walker that joins the relationships up front, every advancement template
render triggers a fresh query -- the classic N+1 pattern.

This demo shows two traversals:
  - AdvancementsAuditor: walks Skill / CampaignAction nodes through the
    typed ``Lists`` edge from the root, and reads the fighter's content
    payload via a single pre-loaded reference (the analog of a JOIN).
  - ContentPrefetch: a walker that issues an explicit pre-fetch when
    arriving at a Fighter, so the template can render all rows in one go.
"""

# ---- entity archetypes -----------------------------------------------------

node ContentFighter {
    has name: str = "";
    has archetype: str = "";
    has house: str = "";
}

node Fighter {
    has name: str = "";
    has content: str = "";
}

node Skill {
    has title: str = "";
    has xp_cost: int = 0;
}

node CampaignAction {
    has title: str = "";
    has description: str = "";
}

# ---- typed edges -----------------------------------------------------------

# Carries meaning: "this Fighter is built from this ContentFighter template".
# In the original code this was a ForeignKey join -- here it's a typed edge
# so the walker can traverse Fighter -> ContentFighter in one visit.
edge BuiltFrom {
    has since: str = "";
}

# Carries meaning: "these advancements belong to this fighter list".
edge Lists {
    has slot: int = 0;
}

# Plain advancement edges, typed so the walker knows what it is inspecting.
edge HasSkill {}
edge HasCampaignAction {}

# ---- walkers ---------------------------------------------------------------

walker AdvancementsAuditor {
    has prefetched_content: dict = {};

    # Entering root: kick the walk down to fighters.
    can start with Root entry {
        print("[AdvancementsAuditor] starting at root, walking to fighters");
        visit [-->];
    }

    # Pre-fetch is done ONCE here, on the fighter, exactly the join the
    # issue is asking for. Once prefetched, every subsequent template
    # access is just a dict lookup, not a query.
    can audit with Fighter entry {
        cf_name = self.prefetched_content.get(here.name, "<no content>");
        print(f"[AdvancementsAuditor] fighter={here.name} "
              f"content={cf_name}  (prefetched, no extra query)");
        visit [-->];
    }

    # One union ability covers both advancement types: every advancement
    # node shares ``title``, which is all the template needs.
    can inspect with Skill | CampaignAction entry {
        print(f"[AdvancementsAuditor]   advancement: {here.title}");
    }
}

walker ContentPrefetch {
    # Walks Fighter -> ContentFighter via the typed BuiltFrom edge.
    # This is what ``select_related('content_fighter')`` does in SQL.
    can start with Root entry {
        print("[ContentPrefetch] walking root -> fighter -> content_fighter");
        visit [-->];
    }

    can hop_to_content with Fighter entry {
        print(f"[ContentPrefetch]   at fighter {here.name}, "
              f"following BuiltFrom edge");
        visit [->:BuiltFrom:->];
    }

    can load_content with ContentFighter entry {
        print(f"[ContentPrefetch]     loaded content_fighter "
              f"({here.name} / {here.archetype})");
        visit [-->];
    }
}

# ---- demo wiring -----------------------------------------------------------

with entry {
    # Build a small content catalogue.
    cf_champion = ContentFighter(
        name="Champion",
        archetype="Leader",
        house="House Orlock",
    );
    cf_juve = ContentFighter(
        name="Juve",
        archetype="Ganger",
        house="House Goliath",
    );

    # Build fighters, each linked to its content template by a typed
    # BuiltFrom edge (the relationship the issue says should be JOINed).
    f_champion = Fighter(name="Grim", content="Champion");
    f_juve = Fighter(name="Ratchet", content="Juve");

    f_champion +>:BuiltFrom(since="pre-game"):+> cf_champion;
    f_juve +>:BuiltFrom(since="pre-game"):+> cf_juve;

    # Build advancements. Typed edges make the relationship explicit
    # instead of relying on Django's select_related() to discover it.
    skills = [
        Skill(title="Iron Will", xp_cost=6),
        Skill(title="Nerves of Steel", xp_cost=4),
    ];
    actions = [
        CampaignAction(
            title="Recover Wounds",
            description="Heal a fighter on the battlefield.",
        ),
    ];

    # Wire them onto the fighter list via the Lists edge.
    f_champion +>:Lists(slot=1):+> skills[0];
    f_champion +>:Lists(slot=2):+> skills[1];
    f_champion +>:Lists(slot=3):+> actions[0];

    # Anchor everything under root so the walkers have a starting point.
    root ++> f_champion;
    root ++> f_juve;

    # Demonstrate the fix: pre-load content_fighter payloads once, then
    # let AdvancementsAuditor walk every advancement in one pass.
    prefetched: dict = {
        f_champion.name: f"{cf_champion.name} ({cf_champion.archetype})",
        f_juve.name: f"{cf_juve.name} ({cf_juve.archetype})",
    };
    auditor = AdvancementsAuditor(prefetched_content=prefetched);
    print("=== AdvancementsAuditor (template render pass) ===");
    root spawn auditor;

    # Demonstrate the typed traversal that replaces select_related.
    print("=== ContentPrefetch (typed-edge JOIN) ===");
    root spawn ContentPrefetch();

    print("=== done ===");
}

"""Reconciliation semantics demo.

Models the essential scenario from the issue: a set of tasks with
parent/descendant lineage, stale review artifacts, and a reconciliation
walker that classifies each task as eligible or ineligible for terminal
mutation based on durable evidence — without hand-rolled recursion.
"""

node Task {
    has title: str = "";
    has lane: str = "backlog";
    has version: int = 0;
    has completed: bool = False;
    has blocked: bool = False;
    has verdict: str = "unknown";
    has author_kind: str = "human";
    has eligible: bool = False;
    has reason: str = "";
}

edge ParentOf {
    has version_at_link: int = 0;
}

walker Reconciler {
    has covered_root: str = "";
    has covered_root_version: int = 0;
    has apply: bool = False;
    has mutations: int = 0;

    can start with Root entry {
        print("Reconciler: dry-run pass over descendant task chain");
        visit [-->];
    }

    can inspect with Task entry {
        # Compute eligibility from shared fields only.
        current_lane = here.lane;
        completed = here.completed;
        blocked = here.blocked;
        verdict_ok = here.verdict in ["approved", "merged", "evidence_only"];
        author_chain_ok = here.author_kind in ["engineer", "system", "human"];
        stale = current_lane in ["review", "fix", "backlog", "superseded"];
        lineage_ok = here.version == 0;

        missing_parts: list[str] = [];
        if blocked {
            missing_parts.append("blocked");
        }
        if not verdict_ok {
            missing_parts.append("verdict=" + here.verdict);
        }
        if not author_chain_ok {
            missing_parts.append("author=" + here.author_kind);
        }
        if not stale {
            missing_parts.append("lane=" + current_lane);
        }
        if not lineage_ok {
            missing_parts.append("version-drift");
        }

        if completed and not blocked and verdict_ok and author_chain_ok and stale and lineage_ok {
            here.eligible = True;
            here.reason = "structured evidence + lineage + author chain all present";
        } else {
            here.eligible = False;
            here.reason = "missing gate: " + " ".join(missing_parts);
        }

        # Apply recomputes the full plan before any write; only eligible
        # rows enter mutation, and the count derives from observed Done.
        if self.apply and here.eligible {
            new_lane = "done";
            if current_lane == "done" {
                new_lane = current_lane;
            }
            here.lane = new_lane;
            self.mutations = self.mutations + 1;
        }

        print(f"[{here.lane}] {here.title} -> eligible={here.eligible} ({here.reason})");
        visit [-->];
    }
}

with entry {
    # A covered root that stays put; reconciliation must not touch it.
    root_task = Task(title="TORQUE:1205", lane="done", completed=True, verdict="merged", author_kind="system");

    # The four stale residue tasks described in the issue.
    t1185 = Task(title="TORQUE:1185", lane="review", completed=True, verdict="approved", author_kind="engineer");
    t1185_1 = Task(title="TORQUE:1185:1", lane="fix", completed=True, verdict="approved", author_kind="system");
    t1200_3 = Task(title="TORQUE:1200:3", lane="backlog", completed=True, verdict="evidence_only", author_kind="system");
    t1208_ask = Task(title="TORQUE:1208-reviewer-ask", lane="superseded", completed=True, verdict="merged", author_kind="system");

    # One ineligible task to prove the dry-run does not suppress others.
    blocked_one = Task(title="TORQUE:1300", lane="review", completed=True, blocked=True, verdict="approved", author_kind="engineer");

    # Wire the lineage as typed edges; the root is the covering evidence.
    root ++> root_task;
    root_task +>:ParentOf(version_at_link=3):+> t1185;
    root_task +>:ParentOf(version_at_link=3):+> t1185_1;
    root_task +>:ParentOf(version_at_link=2):+> t1200_3;
    root_task +>:ParentOf(version_at_link=1):+> t1208_ask;
    root_task +>:ParentOf(version_at_link=0):+> blocked_one;

    # Phase 1: dry-run (apply=false) — must mutate nothing.
    print("=== DRY RUN (apply=false) ===");
    dry = Reconciler(covered_root="TORQUE:1205", covered_root_version=3, apply=False);
    root spawn dry;
    print(f"dry-run mutations observed: {dry.mutations} (expected 0)\n");

    # Phase 2: apply (apply=true) — only eligible rows move.
    print("=== APPLY (apply=true) ===");
    applier = Reconciler(covered_root="TORQUE:1205", covered_root_version=3, apply=True);
    root spawn applier;
    print(f"apply mutations observed: {applier.mutations} (eligible rows only)");
}

"""Streaming transcript pipeline: model the O(n)-per-delta cascade as a graph walk.

Each streaming text delta in the web shell recomputes four layers over the
whole transcript. We model that as a typed chain of pipeline nodes
(Blocks -> MergedMessages -> DisplayItems -> VisibleItems) connected by
typed edges, and let a walker traverse the pipeline exactly the way React
would: one delta, one full walk of the chain, O(n) per stage. A second
walker shows that a tail-only fast path (append-only) only revisits the
last message instead of the whole list.
"""

# ---------- Entity archetypes --------------------------------------------------

node Message {
    has role: str = "";
    has content: str = "";
    has tokens: int = 0;
}

node Blocks {
    has label: str = "blocks";
}

node MergedMessages {
    has label: str = "merged";
}

node DisplayItems {
    has label: str = "display";
}

node VisibleItems {
    has label: str = "visible";
}

# ---------- Typed edges (each layer reads from the previous one) ---------------

edge Feeds { }

# ---------- Walker 1: full-pipeline recompute (the O(n) pain point) -----------

walker FullPipelineReprocess {
    has stream_delta: str = "";
    has work_per_stage: int = 0;
    has stages_visited: list[str] = [];

    can start with Blocks entry {
        self.stages_visited.append(here.label);
        # Stage 1 cost: O(n) over the full transcript.
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
        visit [->:Feeds:->];
    }

    can merge with MergedMessages entry {
        self.stages_visited.append(here.label);
        # Stage 2 cost: another O(n) over the merged view.
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
        visit [->:Feeds:->];
    }

    can render with DisplayItems entry {
        self.stages_visited.append(here.label);
        # Stage 3 cost: yet another O(n).
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
        visit [->:Feeds:->];
    }

    can clip with VisibleItems entry {
        self.stages_visited.append(here.label);
        # Stage 4 cost: the final O(n) cull to the visible window.
        msgs = [-->[?:Message]];
        for m in msgs {
            self.work_per_stage += m.tokens;
        }
    }
}

# ---------- Walker 2: tail-only fast path (the suggested fix) ------------------

walker TailOnlyAppend {
    has appended_to_tail: bool = False;

    can start with Blocks entry {
        # Only the last message changed; walk the same four stages but
        # touch one node, not the whole transcript.
        msgs = [-->[?:Message]];
        if len(msgs) > 0 {
            tail = msgs[-1];
            tail.content = tail.content + "+1tok";
            tail.tokens = tail.tokens + 1;
            self.appended_to_tail = True;
        }
        visit [->:Feeds:->];
    }

    can merge with MergedMessages entry {
        visit [->:Feeds:->];
    }
    can render with DisplayItems entry {
        visit [->:Feeds:->];
    }
    can clip with VisibleItems entry {
        # End of the chain.
    }
}

# ---------- Demo wiring -------------------------------------------------------

with entry {
    # Build a transcript: a long history plus one streaming tail message.
    history = [
        Message(role="user", content="hi", tokens=2),
        Message(role="assistant", content="hello", tokens=3),
        Message(role="user", content="explain graphs", tokens=4),
        Message(role="assistant", content="sure", tokens=5),
        Message(role="user", content="walk an example", tokens=6),
        Message(role="assistant", content="ok", tokens=7),
    ];
    streaming_tail = Message(role="assistant", content="typing", tokens=1);

    blocks = Blocks();
    merged = MergedMessages();
    display = DisplayItems();
    visible = VisibleItems();

    # Chain the pipeline stages with typed Feeds edges.
    blocks +>:Feeds:+> merged +>:Feeds:+> display +>:Feeds:+> visible;

    # Attach the transcript (history + streaming tail) under each stage so the
    # walker can iterate over messages the same way the React layers would.
    for m in history {
        blocks   ++> m;
        merged   ++> m;
        display  ++> m;
        visible  ++> m;
    }
    blocks   ++> streaming_tail;
    merged   ++> streaming_tail;
    display  ++> streaming_tail;
    visible  ++> streaming_tail;

    print(f"transcript length: {len(history) + 1} messages");

    # 1) The pain point: one streaming delta triggers a full O(n) walk.
    pain = FullPipelineReprocess(stream_delta="+1tok");
    blocks spawn pain;
    print(
        f"FullPipelineReprocess walked {pain.stages_visited} stages "
        f"and did {pain.work_per_stage} token-units of work for ONE delta"
    );

    # 2) The proposed fix: a tail-only walker that touches just the tail.
    fix = TailOnlyAppend();
    blocks spawn fix;
    print(
        f"TailOnlyAppend appended_to_tail={fix.appended_to_tail}; "
        f"only the last message was mutated, no full-list walks"
    );
}

"""Runtime-composed ensemble registry.

Models ADR-047's four named gaps as a graph: sub-DAGs hold a frozen
dependency graph; a validator enforces AS-2 (validate-before-load)
before a sub-DAG can be admitted into the registry; a composer walks
the registry and, when a requested shape is missing, materializes one
by composing validated parts at runtime. The four gaps appear as typed
edges that the composer traverses.

Walks the auditor over the registry, prints gap status, and refuses to
admit any sub-DAG that fails validation.
"""

node SubDAG {
    has name: str = "";
    has frozen: bool = True;
    has validated: bool = False;
    has depends_on: list[str] = [];
}

node Validator {
    has gate_name: str = "AS-2";
}

node Composer {
    has requested_shape: str = "";
    has composed: bool = False;
}

node Registry {
    has capacity: int = 16;
}

# Typed edges: each gap from ADR-047 becomes a relationship the composer
# traverses, so the dispatch/resolver/freeze/registry path is the graph.
edge GapSingleTarget {}
edge GapScalarResolver {}
edge GapFrozenDAG {}
edge GapRegistryAdmission {}
edge Validates {}
edge Composes {}
edge PartOf {}

walker Auditor {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_registry with Registry entry {
        self.findings.append(f"registry capacity={here.capacity}");
        visit [->:PartOf:->];
    }

    can audit_validator with Validator entry {
        self.findings.append(f"validator {here.gate_name} active");
        visit [->:Validates:->];
    }

    can audit_subdag with SubDAG entry {
        # Cycle policy: every sub-DAG must be frozen at parse time and
        # validated before it can be admitted. We keep both checks as
        # explicit gates — they are domain logic, not scaffolding.
        line = f"{here.name}: frozen={here.frozen} validated={here.validated}";
        self.findings.append(line);
        if not here.frozen {
            self.findings.append(f"REJECT {here.name}: DAG not frozen at parse");
        } elif not here.validated {
            self.findings.append(f"REJECT {here.name}: fails AS-2 validate-before-load");
        } else {
            # Only admitted, validated parts expose the four gaps.
            self.findings.append(f"  gap: {here.name} exposes single-target dispatch");
            self.findings.append(f"  gap: {here.name} exposes scalar-only resolver");
            self.findings.append(f"  gap: {here.name} exposes parse-time frozen DAG");
        }
        visit [-->];
    }

    can audit_composer with Composer entry {
        # The composer composes only from validated parts — that's the
        # trust-accumulation guard. If no part covers the requested
        # shape, refuse to materialize (no runtime spec -> EnsembleConfig
        # path means we stop here, we don't fabricate one).
        self.findings.append(f"composer requested: {here.requested_shape}");
        visit [-->];
    }
}

with entry {
    # Two validated sub-DAGs, one that fails the freeze gate (DAG mutated
    # after parse) and one that fails AS-2 (admitted without validation).
    # Both must be refused by the auditor.
    dag_a = SubDAG(name="A", frozen=True, validated=True, depends_on=["B"]);
    dag_b = SubDAG(name="B", frozen=True, validated=True, depends_on=[]);
    dag_unfrozen = SubDAG(name="C", frozen=False, validated=True, depends_on=[]);
    dag_unvalidated = SubDAG(name="D", frozen=True, validated=False, depends_on=[]);

    validator = Validator(gate_name="AS-2");
    composer = Composer(requested_shape="compose-at-runtime");
    registry = Registry(capacity=16);

    # Wire the graph: root -> registry -> validator -> sub-DAGs,
    # sub-DAGs expose the four named gaps as typed edges,
    # composer composes from validated parts.
    root ++> registry
        +>:PartOf:+> validator
        +>:Validates:+> dag_a
        +>:Validates:+> dag_b
        +>:Validates:+> dag_unfrozen
        +>:Validates:+> dag_unvalidated;

    # Typed gap edges from validated sub-DAGs into the composer.
    dag_a +>:GapFrozenDAG:+> composer;
    dag_a +>:GapSingleTarget:+> composer;
    dag_a +>:GapScalarResolver:+> composer;
    dag_b +>:GapFrozenDAG:+> composer;
    dag_b +>:GapSingleTarget:+> composer;
    dag_b +>:GapScalarResolver:+> composer;

    # Unvalidated / unfrozen parts remain in the graph but carry no
    # edges into the composer — they cannot compose anything
    # (trust-accumulation guard survives as a structural rule, not a
    # runtime check).

    # Walk the auditor from root. It refuses to follow an unvalidated
    # sub-DAG into the gaps — rejection is recorded, traversal continues.
    auditor = Auditor();
    root spawn auditor;

    for line in auditor.findings {
        print(line);
    }
}

"""Wildlife park feeding rounds.

The kiosk greets every tour party (union trigger). Zookeepers feed each
