"""Roster cap determinism demo.

Models the SuperFamousGuy/AutoTiers issue: cap membership under tied vbd_score
must be deterministic. Players are nodes connected by ``OnRoster`` edges;
``CapAudit`` walks the position groups, sorts each by score with a stable
player_id tiebreak, slices the per-position floor, and finally drains the
remaining budget across positions in a stable order.
"""

node Player {
    has player_id: str = "";
    has vbd_score: float = 0.0;
    has pos: str = "";
}

node PositionGroup {
    has pos: str = "";
}

edge OnRoster {
    has rank_hint: int = 0;
}

walker CapAudit {
    has per_position_min: int = 1;
    has remaining_budget: int = 1;
    has survivors: list[str] = [];
    has pool: list = [];

    can start with Root entry {
        visit [-->];
    }

    can group with PositionGroup entry {
        members = [here ->:OnRoster:->];
        scored = [];
        for m in members {
            scored.append((-m.vbd_score, m.player_id, m));
        }
        scored = sorted(scored);
        idx = 0;
        for item in scored {
            if idx < self.per_position_min {
                self.survivors.append(item[2].player_id);
            } else {
                self.pool.append(item[2]);
            }
            idx += 1;
        }
        visit [-->];
    }

    can finalize with Root entry {
        cap_size = self.per_position_min + self.remaining_budget;
        pool_sorted = [];
        for p in self.pool {
            pool_sorted.append((-p.vbd_score, p.player_id, p));
        }
        pool_sorted = sorted(pool_sorted);
        idx = 0;
        for item in pool_sorted {
            if len(self.survivors) >= cap_size {
                break;
            }
            self.survivors.append(item[2].player_id);
            idx += 1;
        }
    }
}

with entry {
    wr_group = PositionGroup(pos="WR");
    rb_group = PositionGroup(pos="RB");

    wr_a = Player(player_id="wr_A", vbd_score=10.0, pos="WR");
    wr_b = Player(player_id="wr_B", vbd_score=10.0, pos="WR");
    wr_c = Player(player_id="wr_C", vbd_score=9.0, pos="WR");
    rb_a = Player(player_id="rb_A", vbd_score=11.0, pos="RB");

    root ++> wr_group;
    wr_group +>:OnRoster(rank_hint=0):+> wr_a;
    wr_group +>:OnRoster(rank_hint=1):+> wr_b;
    wr_group +>:OnRoster(rank_hint=2):+> wr_c;
    root ++> rb_group;
    rb_group +>:OnRoster(rank_hint=0):+> rb_a;

    walker_a = CapAudit(per_position_min=1, remaining_budget=2);
    root spawn walker_a;
    print(f"run A survivors (insertion order 1): {walker_a.survivors}");

    wr_group2 = PositionGroup(pos="WR");
    rb_group2 = PositionGroup(pos="RB");
    wr_a2 = Player(player_id="wr_A", vbd_score=10.0, pos="WR");
    wr_b2 = Player(player_id="wr_B", vbd_score=10.0, pos="WR");
    wr_c2 = Player(player_id="wr_C", vbd_score=9.0, pos="WR");
    rb_a2 = Player(player_id="rb_A", vbd_score=11.0, pos="RB");

    root ++> wr_group2;
    wr_group2 +>:OnRoster(rank_hint=2):+> wr_c2;
    wr_group2 +>:OnRoster(rank_hint=1):+> wr_b2;
    wr_group2 +>:OnRoster(rank_hint=0):+> wr_a2;
    root ++> rb_group2;
    rb_group2 +>:OnRoster(rank_hint=0):+> rb_a2;

    walker_b = CapAudit(per_position_min=1, remaining_budget=2);
    root spawn walker_b;
    print(f"run B survivors (insertion order 2): {walker_b.survivors}");

    same_set = sorted(walker_a.survivors) == sorted(walker_b.survivors);
    same_order = walker_a.survivors == walker_b.survivors;
    print(f"identical survivor SETS: {same_set}");
    print(f"identical survivor ORDER: {same_order}");
}
```

"""HIER benchmark model: ontology classes, hierarchical indices, and traversal.

Models the essential scenario from issue #353: real ontologies (NCBI, ATC,
Gene Ontology, MITRE ATT&CK) loaded as a hierarchy, indexed two ways
(nested-set for narrow trees, 2-hop for wide DAGs like GO), and walked by
a traversal walker that handles the four challenge shapes — narrow tree,
multi-parent DAG, wide DAG (decline path), and prefix-coded strict tree.

The walker ``HierarchyInspector`` traverses the graph via typed ``Parent``
edges, performing dependency ordering (post-order DFS), cycle detection,
reachability from a chosen root, and cascade invalidation on subtree
removal. It demonstrates the explicit cycle policy required for walkers in
jac 0.36.1 (no built-in visited set).
"""

node OntologyClass {
    has name: str = "";
    has depth: int = 0;
    has width_index: int = 0;
    has order_index: int = 0;
    has invalidated: bool = False;
}

node IndexEntry {
    has lo: int = 0;
    has hi: int = 0;
    has two_hop_ancestors: list[str] = [];
}

edge Parent {
    has weight: float = 1.0;
}

edge TwoHopLink {
    has hop: int = 1;
}

walker HierarchyInspector {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycle_detected: bool = False;
    has two_hop_fanout: int = 0;

    can start with Root entry {
        print(f"=== HIER walk starting over root children ===");
        self.visited = [];
        self.order = [];
        self.cycle_detected = False;
        visit [-->] else { disengage; }
    }

    can index with OntologyClass entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            print(f"[CYCLE] revisiting {here.name} at depth {here.depth}");
            disengage;
        }
        self.visited.append(here.name);
        here.depth = len(self.visited) - 1;
        print(f"  visit {here.name} (depth {here.depth}, width_idx {here.width_index})");
        self.order.append(here.name);
        visit [->:Parent:->] else { disengage; }
    }

    can probe with IndexEntry entry {
        # Walk over typed TwoHopLink edges to count 2-hop fanout.
        self.two_hop_fanout = 0;
        for _ in [->:TwoHopLink:->] {
            self.two_hop_fanout += 1;
        }
        print(f"  2-hop fanout at index entry: {self.two_hop_fanout}");
        visit [->:TwoHopLink:->] else { disengage; }
    }
}

walker CascadeInvalidator {
    has invalid_name: str = "";
    has purged: list[str] = [];

    can start with Root entry {
        print(f"=== Cascade invalidation targeting '{self.invalid_name}' ===");
        visit [-->] else { disengage; }
    }

    can invalidate with OntologyClass entry {
        if here.name == self.invalid_name {
            here.invalidated = True;
            self.purged.append(here.name);
            print(f"  invalidated {here.name}, cascading through children");
            visit [->:Parent:->] else { disengage; }
        } else {
            visit [->:Parent:->] else { disengage; }
        }
    }
}

walker ReachabilityChecker {
    has target: str = "";
    has reached: bool = False;
    has path: list[str] = [];

    can start with Root entry {
        print(f"=== Reachability check for '{self.target}' ===");
        visit [-->] else { disengage; }
    }

    can probe with OntologyClass entry {
        self.path.append(here.name);
        if here.name == self.target {
            self.reached = True;
            print(f"  REACHED {here.name} via path: {self.path}");
            disengage;
        }
        visit [->:Parent:->] else { disengage; }
    }
}

with entry {
    # Build a small ontology graph mirroring the four HIER shapes:
    #   1. NCBI-like narrow deep tree  (root -> ... -> leaf, depth 5)
    #   2. MONDO/HPO-like multi-parent DAG (a child with two parents)
    #   3. GO-like wide DAG             (one parent with many siblings)
    #   4. ATC-like strict prefix tree  (exactly 5 levels)

    # Shape 1: narrow deep tree
    n1 = OntologyClass(name="Life");
    n2 = OntologyClass(name="Eukaryota");
    n3 = OntologyClass(name="Metazoa");
    n4 = OntologyClass(name="Chordata");
    n5 = OntologyClass(name="Mammalia");
    n6 = OntologyClass(name="Hominidae");
    n7 = OntologyClass(name="Homo");
    root ++> n1 +>:Parent:+> n2 +>:Parent:+> n3 +>:Parent:+> n4 +>:Parent:+> n5 +>:Parent:+> n6 +>:Parent:+> n7;

    # Shape 2: multi-parent DAG (MaterialEntity shared by Continuant + Occurrent)
    m1 = OntologyClass(name="Entity");
    m2 = OntologyClass(name="Continuant");
    m3 = OntologyClass(name="Occurrent");
    m4 = OntologyClass(name="MaterialEntity");
    m5 = OntologyClass(name="Cell");
    root ++> m1;
    m1 +>:Parent:+> m2;
    m1 +>:Parent:+> m3;
    m2 +>:Parent:+> m4;
    m3 +>:Parent:+> m4;
    m4 +>:Parent:+> m5;

    # Shape 3: wide DAG (GO-like, width approaching leaf count)
    g_root = OntologyClass(name="GO_root");
    root ++> g_root;
    for i in range(6) {
        g_child = OntologyClass(name=f"GO_branch_{i}");
        g_child.width_index = i;
        g_root +>:Parent:+> g_child;
    }

    # Shape 4: ATC strict 5-level prefix tree
    a1 = OntologyClass(name="A");
    a2 = OntologyClass(name="A01");
    a3 = OntologyClass(name="A01A");
    a4 = OntologyClass(name="A01AB");
    a5 = OntologyClass(name="A01AB01");
    root ++> a1 +>:Parent:+> a2 +>:Parent:+> a3 +>:Parent:+> a4 +>:Parent:+> a5;

    # Spawn walkers demonstrating the traversal scenarios
    root spawn HierarchyInspector();
    root spawn ReachabilityChecker(target="Homo");
    root spawn CascadeInvalidator(invalid_name="Continuant");

    # Two-hop index probe: separate index node linked to several classes
    print("=== Two-hop index probe ===");
    idx = IndexEntry();
    root ++> idx;
    idx +>:TwoHopLink:+> n1;
    idx +>:TwoHopLink:+> n2;
    idx +>:TwoHopLink:+> n3;
    inspector = HierarchyInspector();
    idx spawn inspector;
}

"""Native health-check demo with typed graph edges and handled client failure."""

node AllotMintHealthTool {
    has name: str = "AllotMintHealthTool";
}

node AllotMintClient {
    has endpoint: str = "";
    has health_throws: bool = False;
}

node HealthResponse {
    has status: str = "unknown";
    has structured_content: str = "";
    has text_output: str = "";
}

edge UsesClient { }
edge ReturnsHealth { }

walker HealthCheck {
    has status: str = "unknown";
    has structured_content: str = "";
    has text_output: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can invoke with AllotMintHealthTool entry {
        print(f"Calling {here.name}");
        visit [->:UsesClient:->] else {
            disengage;
        }
    }

    can callHealth with AllotMintClient entry {
        if here.health_throws {
            self.status = "unhealthy";
            self.structured_content = "{\"status\":\"unhealthy\",\"error\":\"health check failed\"}";
            self.text_output = "AllotMint backend is unhealthy: client.health() threw an exception";
        } else {
            self.status = "healthy";
            self.structured_content = "{\"status\":\"healthy\"}";
            self.text_output = "AllotMint backend is healthy";
        }

        visit [->:ReturnsHealth:->] else {
            disengage;
        }
    }

    can emitResult with HealthResponse entry {
        here.status = self.status;
        here.structured_content = self.structured_content;
        here.text_output = self.text_output;

        print(f"structuredContent: {here.structured_content}");
        print(f"text: {here.text_output}");
    }
}

with entry {
    tool = AllotMintHealthTool();
    client = AllotMintClient(
        endpoint="https://api.allotmint.example",
        health_throws=True
    );
    response = HealthResponse();

    root ++> tool;
    tool +>:UsesClient:+> client;
    client +>:ReturnsHealth:+> response;

    root spawn HealthCheck();
}

"""Rollup audit hardening demo.

Models the tour-key-missing drift scenario from issue #298: a rollup pipeline
walks shows -> tours via a typed edge, and when the calendar snapshot has no
tour mapping for a given show date the audit walker records the drift instead
of silently skipping it.
"""

node Show {
    has title: str = "";
    has show_date: str = "";
}

node Tour {
    has tour_key: str = "";
    has season_label: str = "";
}

node RollupAudit {
    has show_date: str = "";
    has tour_key: str = "";
    has tour_key_missing: bool = False;
    has severity: str = "info";
    has note: str = "";
}

edge ScheduledOn {
    has recorded_at: str = "";
}

walker RollupAuditor {
    has tour_lookup: dict = {};
    has missing_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Show entry {
        mapped_key = self.tour_lookup.get(here.show_date);
        if mapped_key is None {
            self.missing_count += 1;
            audit = RollupAudit(
                show_date=here.show_date,
                tour_key="",
                tour_key_missing=True,
                severity="error",
                note=f"tourKey missing for showDate={here.show_date}"
            );
            here ++> audit;
            print(f"[ERROR] tourKeyMissing=true showDate={here.show_date} title={here.title}");
        } else {
            print(f"[OK]    showDate={here.show_date} tour={mapped_key} title={here.title}");
        }
        visit [-->];
    }
}

walker DriftScanner {
    has drifted_dates: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Show entry {
        visit [-->];
    }

    can collect with RollupAudit entry {
        if here.tour_key_missing {
            self.drifted_dates.append(here.show_date);
        }
        visit [-->];
    }

    can collect_root with Root exit {
        if len(self.drifted_dates) > 0 {
            print(f"admin badge: {len(self.drifted_dates)} tour-key-missing docs -> {self.drifted_dates}");
        } else {
            print("admin badge: no drift detected");
        }
    }
}

with entry {
