"""Pedigree collapse predictor: incomplete-relation traversal with heuristic scoring.

Models a small family tree where some relation links (parents, spouses, siblings)
are missing, and a walker scans incomplete generational boundaries to rank the
highest-probability pedigree-collapse candidates. The traversal walks parents
up the ancestry and records each person node, accumulating a composite score
from geographic clustering, surname clustering, temporal recency, and record
density. Domain cycle policy: a guard set prevents infinite loops on cyclic
graphs (jac 0.36.1 walkers do not auto-dedupe), and a depth cap mirrors the
``max_depth`` parameter from the original service.
"""

node Place {
    has name: str = "";
    has neighbors: list[str] = [];

    def is_near(other: Place) -> bool {
        if other.name == self.name {
            return True;
        }
        for n in self.neighbors {
            if n == other.name {
                return True;
            }
        }
        return False;
    }
}

node Person {
    has given: str = "";
    has surname: str = "";
    has birth_year: int = 0;
    has occupation: str = "";
    has citations: int = 0;
    has birth_place: Place | None = None;
    has birth_place_inferred: bool = False;
    has missing_relations: list[str] = [];
    has score: float = 0.0;
}

edge ParentLink {
    has role: str = "parent";
}

edge SpouseLink { }

edge SiblingLink { }

walker CollapsePredictor {
    has tree_id: int = 1;
    has max_depth: int = 6;
    has limit: int = 10;
    has seen: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        self.seen = [];
        visit [-->];
    }

    can scan with Person entry {
        key = f"{here.given}|{here.surname}|{here.birth_year}";
        for s in self.seen {
            if s == key {
                visit [-->];
                return;
            }
        }
        self.seen = self.seen + [key];

        if self.depth > self.max_depth {
            visit [-->];
            return;
        }

        s_loc = self.location_score(here);
        s_sur = self.surname_score(here);
        s_tmp = self.temporal_score(here);
        s_rec = self.record_density_score(here);
        composite = s_loc + s_sur + s_tmp + s_rec;
        here.score = composite;

        for rel in here.missing_relations {
            kind = rel;
            label = "incomplete";
            print(
                f"[{label}] person={here.given} {here.surname} "
                f"missing={kind} score={composite:.2f} "
                f"(loc={s_loc:.2f} sur={s_sur:.2f} "
                f"tmp={s_tmp:.2f} rec={s_rec:.2f})"
            );
        }

        self.depth = self.depth + 1;
        visit [->:ParentLink:->];
        visit [->:SiblingLink:->];
    }

    def location_score(p: Person) -> float {
        if p.birth_place is None {
            return 0.0;
        }
        if p.birth_place_inferred {
            return 0.05;
        }
        return 0.25;
    }

    def surname_score(p: Person) -> float {
        score = 0.1;
        if p.surname == "Schmidt" or p.surname == "Mueller" {
            score = 0.2;
        }
        return score;
    }

    def temporal_score(p: Person) -> float {
        if p.birth_year >= 1850 {
            return 0.25;
        }
        if p.birth_year >= 1750 {
            return 0.15;
        }
        return 0.0;
    }

    def record_density_score(p: Person) -> float {
        score = 0.0;
        if p.occupation != "" {
            score = score + 0.05;
        }
        if p.citations >= 2 {
            score = score + 0.05;
        }
        return score;
    }
}

with entry {
    rural_a = Place(name="Dorf A", neighbors=["Dorf B"]);
    rural_b = Place(name="Dorf B", neighbors=["Dorf A"]);
    city = Place(name="Stadt X", neighbors=[]);

    p1 = Person(
        given="Anna", surname="Schmidt", birth_year=1820,
        occupation="farmer", citations=3, birth_place=rural_a,
        missing_relations=["mother", "spouse"]
    );
    p2 = Person(
        given="Hans", surname="Schmidt", birth_year=1818,
        occupation="farmer", citations=2, birth_place=rural_a,
        missing_relations=["father"]
    );
    p3 = Person(
        given="Greta", surname="Mueller", birth_year=1780,
        occupation="", citations=0, birth_place=rural_b,
        missing_relations=["father", "siblings"]
    );
    p4 = Person(
        given="Klaus", surname="Schmidt", birth_year=1775,
        occupation="miller", citations=1, birth_place=rural_b,
        birth_place_inferred=True,
        missing_relations=["mother"]
    );
    p5 = Person(
        given="Eva", surname="Weber", birth_year=1700,
        occupation="", citations=0, birth_place=city,
        missing_relations=["parents"]
    );

    root ++> p1;
    p1 +>:ParentLink:+> p2;
    p1 +>:SpouseLink:+> p3;
    p2 +>:ParentLink:+> p4;
    p3 +>:SiblingLink:+> p4;
    p4 +>:ParentLink:+> p5;

    root spawn CollapsePredictor(tree_id=1, max_depth=6, limit=10);
}

"""Blast-radius CI: model a corpus of repositories, run vulture twice over them
(baseline vs PR), and diff the findings via a walker that traverses the
typed corpus → repo → finding graph.

The hand-rolled machinery this replaces:
  * id-keyed dicts of repos and findings,
  * recursive walks over a corpus → repos tree to gather findings,
  * set arithmetic on finding hashes to compute appeared / disappeared /
    changed / unanalyzed sets (the "blast radius").
Idiomatic Jac lifts the corpus → repos → findings hierarchy into typed edges
and lets a walker perform the diff in a single typed traversal, preserving
the diff semantics as the report payload on the walker.
"""

# ---------- entity archetypes ----------

node Finding {
    has file_path: str = "";
    has line: int = 0;
    has kind: str = "";
    has message: str = "";
    has confidence: float = 0.0;

    def fingerprint() -> str {
        return f"{self.file_path}:{self.line}:{self.kind}";
    }
}

node Repo {
    has name: str = "";
    has commit_pin: str = "";
}

node Corpus {
    has label: str = "";
}

# ---------- relationship archetypes ----------

edge ContainsRepo { }     # Corpus → Repo
edge HasFinding { }      # Repo → Finding

# ---------- walker: performs the blast-radius diff ----------

walker BlastRadius {
    has findings: list = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Corpus entry {
        visit [->:ContainsRepo:->];
    }

    can gather with Repo entry {
        visit [->:HasFinding:->];
    }

    can record with Finding entry {
        self.findings.append(here.fingerprint());
    }
}

# ---------- demo graph + traversal ----------

with entry {
    corpus = Corpus(label="vulture-corpus");

    # Baseline repo set: skynet is clean, redundant_utils has a real finding.
    repo_a = Repo(name="skynet", commit_pin="v0.4");
    repo_b = Repo(name="redundant_utils", commit_pin="v0.4");

    # PR repo set: skynet unchanged; redundant_utils gains a new finding
    # and loses the old one (the exact regression-then-fix scenario).
    repo_c = Repo(name="redundant_utils", commit_pin="pr-431");

    corpus +>:ContainsRepo:+> repo_a;
    corpus +>:ContainsRepo:+> repo_b;
    corpus +>:ContainsRepo:+> repo_c;

    repo_a +>:HasFinding:+> Finding(
        file_path="skynet/agent.py", line=42, kind="unused",
        message="variable 'foo' is unused", confidence=0.9
    );

    repo_b +>:HasFinding:+> Finding(
        file_path="redundant_utils/helpers.py", line=17, kind="unused-attr",
        message="attribute 'bar' is unused", confidence=0.85
    );

    repo_c +>:HasFinding:+> Finding(
        file_path="redundant_utils/helpers.py", line=93, kind="unused-import",
        message="import 'baz' is unused", confidence=0.95
    );

    walker_baseline = BlastRadius();
    walker_pr = BlastRadius();
    corpus spawn walker_baseline;
    corpus spawn walker_pr;

    print(f"baseline findings gathered: {walker_baseline.findings}");
    print(f"pr findings gathered:       {walker_pr.findings}");

    # Compute the diff off the typed walker's accumulated state and report.
    base_set: list = [];
    for f in walker_baseline.findings {
        already = False;
        for g in base_set {
            if g == f {
                already = True;
                break;
            }
        }
        if not already {
            base_set.append(f);
        }
    }
    pr_set: list = [];
    for f in walker_pr.findings {
        already = False;
        for g in pr_set {
            if g == f {
                already = True;
                break;
            }
        }
        if not already {
            pr_set.append(f);
        }
    }

    appeared: list = [];
    for f in pr_set {
        in_base = False;
        for g in base_set {
            if g == f {
                in_base = True;
                break;
            }
        }
        if not in_base {
            appeared.append(f);
        }
    }
    disappeared: list = [];
    for f in base_set {
        in_pr = False;
        for g in pr_set {
            if g == f {
                in_pr = True;
                break;
            }
        }
        if not in_pr {
            disappeared.append(f);
        }
    }

    print(f"appeared:    {appeared}");
    print(f"disappeared: {disappeared}");
}

"""Policy-gated browser escape-hatch audit with scoped Playwright and CDP capabilities."""

node ControlPlane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has policy_name: str = "";
}

node Workspace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has scope_tier: str = "none";
    has raw_playwright_enabled: bool = False;
    has raw_cdp_enabled: bool = False;
    has kill_switch: bool = False;
}

node BrowserSession {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
    has browser_name: str = "";
}

node BrowserPage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has page_id: str = "";
    has active: bool = True;
}

edge Contains {
    has label: str = "";
}

edge Owns {
    has label: str = "";
}

walker RawPolicyAuditor {
    has raw_allowed: bool = False;
    has cdp_allowed: bool = False;
    has steps: int = 0;
    has max_steps: int = 10;

    can start with Root entry {
        self.steps += 1;
        print("Auditing scoped browser escape-hatch policy");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_control with ControlPlane entry {
        self.steps += 1;
        print(f"Policy: {here.policy_name}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_workspace with Workspace entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            print("Traversal stopped at the safety depth limit");
            disengage;
        } else {
            if here.kill_switch {
                self.raw_allowed = False;
                self.cdp_allowed = False;
                print("Kill switch active: expert capabilities denied");
            } else {
                self.raw_allowed = here.raw_playwright_enabled;
                self.cdp_allowed = here.raw_cdp_enabled;
                print(f"Workspace scope: {here.scope_tier}");
            }
            visit [->:Owns:->] else {
                disengage;
            }
        }
    }

    can inspect_session with BrowserSession entry {
        self.steps += 1;
        if self.raw_allowed {
            print(f"Raw Playwright allowed for session {here.session_id}");
        } else {
            print(f"Raw Playwright denied for session {here.session_id}");
        }
        if self.cdp_allowed {
            if here.browser_name == "chromium" {
                print("Scoped CDP inspection allowed for Chromium");
            } else {
                print("CDP denied: browser is not Chromium");
            }
        } else {
            print("CDP denied: capability scope is absent");
        }
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect_page with BrowserPage entry {
        self.steps += 1;
        if here.active {
            print(f"Audited active page {here.page_id} as expert output");
        } else {
            print(f"Page {here.page_id} is inactive; execution denied");
        }
        visit [->:Owns:->] else {
            disengage;
        }
    }
}

with entry {
    control = ControlPlane(
        policy_name="admin-scoped expert browser policy"
    );
    workspace = Workspace(
        scope_tier="debug-expert",
        raw_playwright_enabled=True,
        raw_cdp_enabled=True,
        kill_switch=False
    );
    session = BrowserSession(
        session_id="session-7",
        browser_name="chromium"
    );
    page = BrowserPage(
        page_id="page-42",
        active=True
    );

    root +>:Contains(label="policy-root"):+> control;
    control +>:Contains(label="authorized-workspace"):+> workspace;
    workspace +>:Owns(label="explicit-session"):+> session;
    session +>:Owns(label="explicit-page"):+> page;

    root spawn RawPolicyAuditor();
}

"""Native agent recurrence: propagate execution evidence into a CLI receipt."""

node NativeAgent {
    has agent_name: str = "";
    has engine: str = "";
}

node ExecutionRun {
    has run_id: str = "";
    has configured_depth: int = 0;
    has engine: str = "";
}

node RecurrentStep {
    has step_id: str = "";
    has depth: int = 0;
    has completed: bool = False;
    has stop_boundary: str = "";
}

node NativeReceipt {
    has engine: str = "";
    has configured_depth: int = 0;
    has completed_depth: int = 0;
    has stop_boundary: str = "";
    has cycle_detected: bool = False;
}

edge Runs { }
edge Starts { }
edge Continues { }
edge Emits { }

walker EvidencePropagator {
    has engine: str = "";
    has configured_depth: int = 0;
    has completed_depth: int = 0;
    has stop_boundary: str = "";
    has visited_ids: list[str] = [];
    has cycle_detected: bool = False;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_agent with NativeAgent entry {
        self.engine = here.engine;
        visit [-->] else { disengage; }
    }

    can inspect_run with ExecutionRun entry {
        self.engine = here.engine;
        self.configured_depth = here.configured_depth;
        visit [-->] else { disengage; }
    }

    can inspect_step with RecurrentStep entry {
        if here.step_id in self.visited_ids {
            self.cycle_detected = True;
            print(f"cycle guarded at {here.step_id}");
            skip;
        }

        self.visited_ids.append(here.step_id);
        if here.completed {
            if here.depth > self.completed_depth {
                self.completed_depth = here.depth;
            }
        }
        if here.stop_boundary != "" {
            self.stop_boundary = here.stop_boundary;
        }
        visit [-->] else { disengage; }
    }

    can finalize with NativeReceipt entry {
        here.engine = self.engine;
        here.configured_depth = self.configured_depth;
        here.completed_depth = self.completed_depth;
        here.stop_boundary = self.stop_boundary;
        here.cycle_detected = self.cycle_detected;
        print(f"{{\"engine\":\"{here.engine}\", \"configured_depth\":{here.configured_depth}, \"completed_depth\":{here.completed_depth}, \"stop_boundary\":\"{here.stop_boundary}\", \"cycle_detected\":{here.cycle_detected}}}");
    }
}

with entry {
    agent = NativeAgent(agent_name="leaf", engine="fak-native");
