"""VfW codec registry integrity walker.

Models the essential scenario from the Lagarith/VirtualDub2 issue: a host
application (VirtualDub2 build 2.5.3.1197) interacts with the system-wide
Video for Windows driver registry for both 32-bit and 64-bit codecs.
A buggy installer/launch path overwrites the global drivers32 mappings
and breaks every other VfW consumer.

The graph below models that scenario natively:
  - ``RegistryView`` nodes represent the two registry views (32-bit WOW6432Node
    and 64-bit native) plus a third party-app registry view to model collateral
    damage on MSI Afterburner / classic VirtualDub.
  - ``VfWCodec`` nodes represent installed codecs (Lagarith, x264vfw, etc.).
  - The typed ``MapsTo`` edge carries the FOURCC four-character code that
    binds a driver path under a specific registry view.
  - ``HostsBuild`` edges connect the VirtualDub2 build node to the registry
    view it should not touch.
  - ``DependsOn`` edges let the walker trace transitive dependencies
    (e.g. MeGUI -> AVISource -> Lagarith).

A walker ``CodecAuditor`` walks the registry view, records each codec, then
walks the dependency edges to report every consumer that would break if a
codec is wiped. A second walker ``HostInstaller`` demonstrates the buggy
behavior: it traverses a registry view and deletes every ``MapsTo`` edge
hosted there -- exactly the kind of cascade that wipes vidc.lags globally.
"""

node RegistryView {
    has view_name: str = "";
    has architecture: str = "";
}

node VfWCodec {
    has codec_name: str = "";
    has fourcc: str = "";
    has driver_path: str = "";
    has available: bool = True;
}

node HostBuild {
    has build_label: str = "";
    has version: str = "";
}

node AppConsumer {
    has app_name: str = "";
    has role: str = "";
}

edge MapsTo {
    has fourcc_code: str = "";
    has driver_path: str = "";
}

edge HostsBuild { }

edge DependsOn { }

walker CodecAuditor {
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can survey with RegistryView entry {
        self.report_lines.append(f"[AUDIT] {here.view_name} ({here.architecture})");
        visit [->:MapsTo:->];
    }

    can record with VfWCodec entry {
        status = "OK" if here.available else "MISSING";
        self.report_lines.append(
            f"  [{status}] fourcc={here.fourcc} name={here.codec_name}"
        );
        visit [->:DependsOn:->];
    }

    can impact with AppConsumer entry {
        self.report_lines.append(
            f"  -> breaks {here.app_name} ({here.role}) via Lagarith dependency"
        );
    }
}

walker HostInstaller {
    has build_label: str = "";
    has removed: list[str] = [];
    has visited_views: list[str] = [];

    can start with Root entry {
        visit [->:HostsBuild:->];
    }

    can target with HostBuild entry {
        visit [-->];
    }

    can wipe with RegistryView entry {
        self.visited_views.append(here.view_name);
        # The buggy behavior: traverse every codec mapping hosted under this
        # registry view and disconnect it. This is the cascade that nukes
        # vidc.lags globally for both 32-bit and 64-bit VfW consumers.
        kids = [->:MapsTo:->];
        for n in kids {
            here del ->:MapsTo:-> n;
            n.available = False;
            self.removed.append(n.fourcc);
        }
    }
}

with entry {
    # Two system-wide registry views (the ones the issue names) plus a third
    # party-app registry view that demonstrates collateral damage.
    sys32 = RegistryView(
        view_name="HKLM\\SOFTWARE\\WOW6432Node\\Microsoft\\Windows NT\\CurrentVersion\\Drivers32",
        architecture="32-bit",
    );
    sys64 = RegistryView(
        view_name="HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Drivers32",
        architecture="64-bit",
    );
    thirdparty = RegistryView(
        view_name="MSI Afterburner\\VfW",
        architecture="32-bit",
    );

    # Codecs installed system-wide (the ones that must survive).
    lagarith = VfWCodec(
        codec_name="Lagarith Lossless Codec",
        fourcc="LAGS",
        driver_path="C:\\Windows\\SysWOW64\\lagarith.dll",
    );
    lagarith64 = VfWCodec(
        codec_name="Lagarith Lossless Codec (x64)",
        fourcc="LAGS",
        driver_path="C:\\Windows\\System32\\lagarith64.dll",
    );
    x264vfw = VfWCodec(
        codec_name="x264vfw",
        fourcc="H264",
        driver_path="C:\\Windows\\System32\\x264vfw64.dll",
    );

    # Apps that depend on Lagarith being present.
    megui = AppConsumer(app_name="MeGUI", role="encoder via AviSynth AVISource()");
    afterburner = AppConsumer(app_name="MSI Afterburner", role="video capture");
    classic_vdub = AppConsumer(app_name="VirtualDub 1.x", role="legacy editor");

    # Wire the registry views onto root.
    root ++> sys32;
    root ++> sys64;
    root ++> thirdparty;

    # Bind each codec to the registry view it lives under, via typed edges
    # that carry the FOURCC and driver path -- exactly the registry payload
    # the issue says gets wiped.
    sys32 +>:MapsTo(fourcc_code="vidc.LAGS", driver_path=lagarith.driver_path):+> lagarith;
    sys64 +>:MapsTo(fourcc_code="vidc.LAGS", driver_path=lagarith64.driver_path):+> lagarith64;
    thirdparty +>:MapsTo(fourcc_code="vidc.H264", driver_path=x264vfw.driver_path):+> x264vfw;

    # Codec -> consumer dependencies.
    lagarith +>:DependsOn:+> megui;
    lagarith +>:DependsOn:+> afterburner;
    lagarith64 +>:DependsOn:+> megui;
    lagarith64 +>:DependsOn:+> classic_vdub;

    # Host build -> registry views it should not touch.
    vd2 = HostBuild(build_label="VirtualDub2", version="2.5.3.1197");
    root ++> vd2;
    vd2 +>:HostsBuild:+> sys32;
    vd2 +>:HostsBuild:+> sys64;

    # -------- Phase 1: audit the registry before the buggy build touches it.
    print("=== Phase 1: CodecAuditor walks the registry ===");
    auditor = CodecAuditor();
    root spawn auditor;
    for line in auditor.report_lines {
        print(line);
    }

    # -------- Phase 2: the buggy installer cascade-deletes every mapping.
    print("\n=== Phase 2: HostInstaller (buggy VirtualDub2 2.5.3.1197) ===");
    installer = HostInstaller(build_label="VirtualDub2");
    root spawn installer;
    print(f"installer scanned views: {installer.visited_views}");
    print(f"install mappings removed (fourcc codes): {installer.removed}");
    print(
        f"lagarith available now? {lagarith.available}; "
        f"lagarith64 available now? {lagarith64.available}; "
        f"x264vfw available now? {x264vfw.available}"
    );

    # -------- Phase 3: re-audit. Lagarith is gone from both system views,
    # so every dependent app is now broken.
    print("\n=== Phase 3: CodecAuditor re-audit after the buggy install ===");
    auditor2 = CodecAuditor();
    root spawn auditor2;
    for line in auditor2.report_lines {
        print(line);
    }
}

"""Plugin cache recovery: only finalized materializations count as installed."""

node Agent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has agent_id: str = "";
    has plugin_enabled: bool = False;
}

node Plugin {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has plugin_id: str = "";
}

node CacheInstall {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has plugin_id: str = "";
    has finalized: bool = False;
    has staging: bool = False;
    has materialized: bool = False;
}

edge AssignedPlugin {
    has selected: bool = False;
}

edge CacheCandidate { }

walker InstallAuditor {
    has seen_plugins: list[str] = [];
    has seen_paths: list[str] = [];
    has valid_plugins: list[str] = [];
    has retryable_plugins: int = 0;

    can start with Root entry {
        print("Walking agent assignments and cache candidates");
        visit [-->] else { disengage; }
    }

    can inspect_agent with Agent entry {
        if here.plugin_enabled {
            print(f"Agent {here.agent_id} has an enabled plugin binding");
        } else {
            print(f"Agent {here.agent_id} has no enabled plugin binding");
        }
        visit [->:AssignedPlugin:->] else { disengage; }
    }

    can inspect_plugin with Plugin entry {
        if here.plugin_id in self.seen_plugins {
            print(f"Cycle guard: plugin {here.plugin_id} was already visited");
            disengage;
        } else {
            self.seen_plugins = self.seen_plugins + [here.plugin_id];
            print(f"Checking installed state for {here.plugin_id}");
            visit [->:CacheCandidate:->] else {
                print("No cache candidates; retry is allowed");
            }
        }
    }

    can inspect_cache with CacheInstall entry {
        if here.path in self.seen_paths {
            print(f"Cycle guard: cache path {here.path} was already visited");
            disengage;
        } else {
            self.seen_paths = self.seen_paths + [here.path];
            if here.staging {
                print(f"Ignoring staging directory {here.path}");
            } elif here.finalized && here.materialized && here.available {
                self.valid_plugins = self.valid_plugins + [here.plugin_id];
                print(f"Usable finalized install: {here.path}");
            } else {
                print(f"Ignoring incomplete install: {here.path}");
            }
        }
    }

    can summarize with exit {
        for plugin_id in self.seen_plugins {
            if plugin_id in self.valid_plugins {
                print(f"INSTALLED: {plugin_id}; retry remains available after failed updates");
            } else {
                self.retryable_plugins = self.retryable_plugins + 1;
                print(f"RETRY: {plugin_id}; no usable finalized install exists");
            }
        }
        print(f"Discovery complete: {self.retryable_plugins} plugin(s) can retry");
    }
}

with entry {
    failed = Plugin(title="Broken Formatter", year=2024, plugin_id="formatter");
    empty_parent = CacheInstall(
        title="formatter",
        path="cache/marketplace/formatter",
        plugin_id="formatter",
        available=False
    );
    failed_tmp = CacheInstall(
        title="formatter",
        path="cache/marketplace/formatter/.tmp-1700",
        plugin_id="formatter",
        staging=True,
        materialized=False,
        available=False
    );
    failed +>:CacheCandidate:+> empty_parent;
    failed +>:CacheCandidate:+> failed_tmp;

    healthy = Plugin(title="Search Tools", year=2023, plugin_id="search");
    prior_version = CacheInstall(
        title="search",
        year=1,
        path="cache/marketplace/search/v1",
        plugin_id="search",
        finalized=True,
        materialized=True
    );
    update_tmp = CacheInstall(
        title="search",
        path="cache/marketplace/search/.tmp-1701",
        plugin_id="search",
        staging=True,
        materialized=False,
        available=False
    );
    healthy +>:CacheCandidate:+> prior_version;
    healthy +>:CacheCandidate:+> update_tmp;

    recovery_agent = Agent(
        title="Recovery Agent",
        year=2024,
        agent_id="agent-recovery",
        plugin_enabled=False
    );
    stable_agent = Agent(
        title="Stable Agent",
        year=2024,
        agent_id="agent-stable",
        plugin_enabled=True
    );

    root ++> recovery_agent;
    root ++> stable_agent;
    recovery_agent +>:AssignedPlugin(selected=False):+> failed;
    stable_agent +>:AssignedPlugin(selected=True):+> healthy;

    root spawn InstallAuditor();
}

"""Factory patrol: one monitoring routine handles both temperature and smoke sensors, printing readings and summarizing alerts."""

node Sensor {
    has label: str = "";
    def is_alert() -> bool;
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;
    def is_alert() -> bool;
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;
    def is_alert() -> bool;
}

node Zone {
    has zone_name: str = "";
}

walker Patrol {
    has alert_count: int = 0;

    can start with Root entry {
        print("=== Beginning factory patrol ===");
        visit [-->];
    }

    can sweep with Zone entry {
        print(f"--- Sweeping zone: {here.zone_name} ---");
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        if here.is_alert() {
            print(f"[ALERT] {here.label}: reading exceeds threshold");
            self.alert_count += 1;
        } else {
            print(f"nominal: {here.label} reading within range");
        }
    }
}

impl Sensor.is_alert() -> bool {
    return False;
}

impl TempSensor.is_alert() -> bool {
    return self.celsius > 75.0;
}

impl SmokeSensor.is_alert() -> bool {
    return self.ppm > 50.0;
}

with entry {
    zone_a = Zone(zone_name="Assembly");
    zone_b = Zone(zone_name="Packaging");
    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="Temp-A1", celsius=82.3);
    zone_a ++> SmokeSensor(label="Smoke-A1", ppm=22.0);
    zone_b ++> TempSensor(label="Temp-B1", celsius=68.5);
    zone_b ++> SmokeSensor(label="Smoke-B1", ppm=63.7);

    patroller = Patrol();
    root spawn patroller;

    print("=== Patrol complete ===");
    print(f"Total alerts recorded: {patroller.alert_count}");
}

"""Hierarchical category tree: adjacency list lifted to typed edges.

Models an electronics-store category hierarchy where each category has a
single parent (except the root) and zero or more children. Demonstrates
native Jac traversal of the parent/child graph using typed edges and a
walker that walks descendants, plus a cascade-style detach walker.
"""

node Category {
    has name: str = "";
    has available: bool = True;
}

edge ChildOf {
    has depth: int = 0;
}

walker DescendantPrinter {
    can start with Root entry {
        visit [-->];
    }

    can step with Category entry {
        print(f"- {here.name}");
        visit [-->];
    }
}

walker SubtreeDisconnector {
    has target: str = "";
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan with Category entry {
        if here.name == self.target {
            self.found = True;
            print(f"Detaching subtree rooted at: {here.name}");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    electronics = Category(name="ELECTRONICS");
    tvs = Category(name="TELEVISIONS");
    tube = Category(name="TUBE");
    lcd = Category(name="LCD");
    plasma = Category(name="PLASMA");
    portable = Category(name="PORTABLE ELECTRONICS");
    mp3 = Category(name="MP3 PLAYERS");
    flash = Category(name="FLASH");
    cd = Category(name="CD PLAYERS");
    radios = Category(name="2 WAY RADIOS");

    root +>:ChildOf:+> electronics;
    electronics +>:ChildOf:+> tvs;
    tvs +>:ChildOf:+> tube;
    tvs +>:ChildOf:+> lcd;
    tvs +>:ChildOf:+> plasma;
    electronics +>:ChildOf:+> portable;
    portable +>:ChildOf:+> mp3;
    mp3 +>:ChildOf:+> flash;
    portable +>:ChildOf:+> cd;
    portable +>:ChildOf:+> radios;

    print("=== Full category tree (parent-child) ===");
    root spawn DescendantPrinter();

    print("\n=== Detach PORTABLE ELECTRONICS subtree ===");
    root spawn SubtreeDisconnector(target="PORTABLE ELECTRONICS");
}

A maintainer on the project luceat-lux-vestra/MarkFlow (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #155: task(build): converge renderer dependencies, toolchain, JCEF packaging and settings after editor purge

## Parent / dependencies

- Leap Epic: #52
- Quality Track: #84
- State Track: #83
- Inventory: #141
- Renderer extraction/runtime decision: #144
- Renderer consumers: #148/#149
- Browser-editor purge: #154

## Purpose

After the editor migration/purge establishes actual retained consumers, reduce build/runtime/settings dependencies to the smallest target set.

Do not pre-delete TypeScript/Vite/JCEF merely because the editor is native; do not retain them merely because the old editor used them. Honor #144's renderer-runtime decision and then converge packaging to that proven target.

## Dependency decisions

Re-evaluate by actual consumer:

- `@milkdown/crepe` — expected DELETE after #154;
- `@codemirror/*` — expected DELETE after #154;
- `mermaid 11.17.2` — RETAIN unless #144/renderer ADR separately replaces it;
- `katex ^0.18.4` + required assets — RETAIN unless separately replaced by renderer ADR;
- TypeScript/Vite/Node build — RETAIN only to the extent the #144-selected renderer runtime requires them;
- `com.intellij.modules.jcef` — IntelliJ 2026.2 supplies this as a separately bundled supported plugin; native editing must not depend on it, and required/optional/eliminated packaging status follows #144's selected isolated renderer adapter;
- `com.intellij.mermaid` — may be required/optional only if #144 identifies a maintained public contract with real product value. Do not add or retain it merely to call internal/private JCEF preview/export implementation;
- JCEF transport probe/startup wiring — delete editor-envelope proof; retain/create only renderer-specific runtime evidence if JCEF remains;
- any GraalJS/Node/Javet/QuickJS/browserless-DOM dependency — retain only if #144 selected it with explicit package-size/platform/process/native-binary evidence.

## Build structure

- native editor/core packaging must be separable from backend-specific renderer implementation;
- if JCEF is optional in the selected target, JCEF-specific extension registrations/classes must be isolated behind optional plugin/module descriptor boundaries so MarkFlow core can load without linking those classes;
- if a renderer plugin dependency is required by product choice, document why loss of that dependency justifies preventing full plugin load rather than degrading only rich rendering;
- renderer build artifacts must be isolated from deleted editor pages/bundles;
- plugin build should not compile/package dead editor frontend assets;
- build inputs/outputs/cacheability remain deterministic;
- CI triggers/evidence paths follow the retained target responsibilities;
- #68 Node and #72 TypeScript are reconciled against the resulting renderer toolchain rather than historical `webview/` existence.

## Settings convergence

- preserve/migrate active Mermaid/KaTeX/theme/font product settings;
- remove `idleEvictAfterMs` and browser pool/prewarm/retry/debounce settings when no consumer remains;
- replace browser runtime payload/revision notification plumbing with typed native presentation/renderer invalidation;
- resolve `previewOnlyByDefault` native meaning explicitly;
- retain `DiagramSecurityLevel` only if #82 approved a safe renderer-visible policy;
- removed persisted keys fail safely and stop being written.

## Evidence

- clean dependency/build graph;
- no deleted editor asset in packaged plugin;
- renderer success/error/settings tests remain green;
- native source editing remains green when the selected renderer backend is unavailable/disabled according to #144's dependency model;
- if JCEF is optional, actual plugin-load/startup/native-edit evidence with `com.intellij.modules.jcef` disabled or absent from the runtime plugin set — registry-only `JBCefApp.isSupported=false` evidence is insufficient for this packaging claim;
- retained JCEF renderer, if any, has production runtime evidence;
- retained `com.intellij.mermaid` dependency, if any, uses only maintained/public API and passes Plugin Verifier across the supported IDE matrix;
- non-JCEF renderer dependencies, if any, have supported OS/architecture/package/process evidence;
- persisted-settings migration/invalid-value tests;
- Plugin Verifier / supported IDE matrix;
- build/release workflows reference no removed mechanism.

## Non-goals

- no product capability deletion;
- no renderer-engine rewrite unless separately approved;
- no performance optimization without measurement;
- no forced optionalization of a renderer dependency if #144 explicitly proves a required dependency is the better product contract.

## Completion

The repository/toolchain/settings describe only the native editor plus actual retained renderer infrastructure; no editor-era dependency survives without a consumer, and the packaging behavior matches the renderer dependency contract proven by #144.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

"""Native dependency graph demo with invalidation and cycle detection."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has invalidated: bool = False;
}

node EditorCore(Artifact) {
    has mode: str = "native";
}

node Renderer(Artifact) {
    has runtime: str = "isolated";
}

node BuildTool(Artifact) {
    has command: str = "";
}

edge DependsOn {
    has required: bool = True;
}

walker DependencyAudit {
    has seen: list[str] = [];
    has inspected: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Artifact entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}");
            disengage;
        }

        self.seen.append(here.title);
        self.inspected += 1;

        if here.available {
            print(f"available: {here.title}");
        } else {
            here.invalidated = True;
            print(f"invalidated: {here.title}");
        }

        visit [->:DependsOn:->] else {
            print(f"leaf dependency: {here.title}");
            disengage;
        }
    }
}

with entry {
    editor = EditorCore(
        title="Native editor",
        mode="source editing"
    );
    renderer = Renderer(
        title="Mermaid renderer",
        runtime="optional isolated backend",
        available=False
    );
    toolchain = BuildTool(
        title="Renderer toolchain",
        command="mermaid-build"
    );

    editor +>:DependsOn(required=True):+> renderer;
    renderer +>:DependsOn(required=False):+> toolchain;
    toolchain +>:DependsOn(required=False):+> renderer;

    root ++> editor;
    root spawn DependencyAudit();
}

"""Hiking trail: chain plain waypoints from trailhead to summit and walk it with a hiker."""

node Waypoint;

walker Hiker {
