"""LayerFS durability audit with typed dependencies and explicit cycle detection."""

node Store {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has durable: bool = False;
}

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has acknowledged: bool = False;
}

node Blob {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has bytes_count: int = 0;
}

edge Publishes {
    has sequence: int = 0;
}

edge DependsOn {
    has required: bool = True;
}

walker DurabilityAudit {
    has seen: set[str] = set();

    can start with Root entry {
        print("Starting durable publication audit");
        visit [-->] else { disengage; }
    }

    can audit_store with Store entry {
        if here.durable {
            print(f"Store {here.title} uses durable publication");
        } else {
            print(f"Store {here.title} is visibility-only");
        }
        visit [->:Publishes:->] else { disengage; }
    }

    can audit_snapshot with Snapshot entry {
        if here.acknowledged {
            print(f"Acknowledged snapshot: {here.title}");
        } else {
            print(f"Unacknowledged snapshot: {here.title}");
        }
        visit [->:DependsOn:->] else { disengage; }
    }

    can audit_blob with Blob entry {
        if here.title in self.seen {
            print(f"Dependency cycle detected at {here.title}");
            disengage;
        } else {
            self.seen.add(here.title);
            if here.available {
                print(f"Verified dependency {here.title} ({here.bytes_count} bytes)");
            } else {
                print(f"Missing dependency {here.title}");
            }
            visit [->:DependsOn:->] else { disengage; }
        }
    }
}

with entry {
    store = Store(title="local-layerfs", year=2024, durable=True);
    snapshot = Snapshot(
        title="commit-42",
        year=2024,
        acknowledged=True
    );
    manifest = Blob(
