"""Tetragon execve_map cascade failure model.

Models the chain described in cilium/tetragon issue #4883: a partial
procfs snapshot drops ancestors from execve_map, so the hereditary
``parent must already be in execve_map`` invariant permanently excludes
descendants. Downstream process_kprobe events then fall back to a
probe-only path that emits empty fields.

Four node archetypes model the entities, two typed edges capture the
relationships, and a walker performs the same parent-walk + cascade
invalidation the BPF code does.
"""

node ProcEntry {
    has pid: int = 0;
    has binary: str = "";
    has exec_id: str = "";
    has flags: str = "";
    has pod: str = "";
    has in_execve_map: bool = False;
    has probed: bool = False;
}

node Snapshot {
    has source: str = "";
    has filled: int = 0;
    has total: int = 0;
}

node KernelInvariant {
    has name: str = "";
    has description: str = "";
}

walker CascadeLoss {
    has dropped_count: int = 0;
    has neutralised: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can seed with Snapshot entry {
        print(f"[seed] {here.source}: {here.filled}/{here.total} filled");
        visit [-->];
    }

    can enforce with KernelInvariant entry {
        print(f"[invariant] {here.name} -> {here.description}");
        visit [-->];
    }

    can walk_and_emit with ProcEntry entry {
        if not here.probed {
            visit [-->];
            return;
        }
        if here.in_execve_map {
            label = "FULL";
        } else {
            label = "EMPTY";
        }
        line = f"[kprobe] pid={here.pid} {label} binary='{here.binary}' "
               f"exec_id='{here.exec_id}' flags='{here.flags}' pod='{here.pod}'";
        print(line);
        self.log.append(line);
        if label == "EMPTY" {
            self.neutralised += 1;
        }
        visit [-->];
    }
}

with entry {
    inv = KernelInvariant(
        name="hereditary",
        description="child joins execve_map only if parent already present"
    );
    snap_good = Snapshot(source="GKE-COS", filled=486, total=486);
    snap_bad = Snapshot(source="DockerDesktop-LinuxKit", filled=39, total=95);

    a = ProcEntry(pid=1001, binary="/usr/bin/systemd", exec_id="e1",
                  flags="EXEC", pod="kube-system/tetragon", in_execve_map=True);
    b = ProcEntry(pid=1002, binary="/usr/bin/containerd-shim", exec_id="e2",
                  flags="EXEC", pod="kube-system/kube-proxy", in_execve_map=True);
    c = ProcEntry(pid=1003, binary="/usr/bin/kubelet", exec_id="e3",
                  flags="EXEC", pod="kube-system/kubelet", in_execve_map=True);
    d = ProcEntry(pid=1004, binary="/usr/bin/crio", exec_id="e4",
                  flags="EXEC", pod="kube-system/crio", in_execve_map=False);
    e = ProcEntry(pid=1005, binary="/usr/bin/bash", exec_id="e5",
                  flags="EXEC", pod="default/app", in_execve_map=False);
    f = ProcEntry(pid=1006, binary="/usr/bin/app", exec_id="e6",
