"""Recursive call stack visualization: model factorial recursion as a graph
of CallFrame nodes linked by Caller edges, then walk it to render both the
call tree and the active stack at any replay step.
"""

node CallFrame {
    has call_id: int = 0;
    has parent_id: int = -1;
    has depth: int = 0;
    has func_name: str = "";
    has args: str = "";
    has locals_state: str = "";
    has status: str = "active";
    has return_value: int = 0;
}

edge Caller {
    has spawn_order: int = 0;
}

walker RenderRecursion {
    has step: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        print("=== Call tree ===");
        visit [-->];
    }

    can visit_frames with CallFrame entry {
        indent = "";
        d = 0;
        while d < here.depth {
            indent = indent + "  ";
            d = d + 1;
        }
        if here.depth > self.max_depth {
            indent = indent + "  ..";
        }
        ret = "";
        if here.status == "returned" {
            ret = " -> " + str(here.return_value);
        }
        line = indent + "- " + here.func_name + "(" + here.args + ") [id=" + str(here.call_id) + "]" + ret;
        print(line);
        visit [-->];
    }
}

walker ShowActiveStack {
    has step: int = 0;
    has frames: list = [];

    can start with Root entry {
        print("=== Active stack at step " + str(self.step) + " ===");
        visit [-->];
    }

    can collect_frame with CallFrame entry {
        self.frames.append(here);
        visit [-->];
    }
}

walker StepReplayer {
    has step: int = 0;
    has visited_ids: list[int] = [];

    can start with Root entry {
        print("--- Replay position: step " + str(self.step) + " ---");
        visit [-->];
    }

    can replay with CallFrame entry {
        already = False;
        for vid in self.visited_ids {
            if vid == here.call_id {
                already = True;
            }
        }
        if not already {
            self.visited_ids.append(here.call_id);
            marker = ">> ACTIVE";
            if here.status != "active" {
                marker = "   done -> " + str(here.return_value);
            }
            line = "  step " + str(self.step) + ": id=" + str(here.call_id) + " depth=" + str(here.depth) + " " + here.func_name + "(" + here.args + ") " + marker;
            print(line);
            self.step = self.step + 1;
        }
        visit [-->];
    }
}

with entry {
    f1 = CallFrame(call_id=1, parent_id=0, depth=0, func_name="factorial", args="n=4");
    f2 = CallFrame(call_id=2, parent_id=1, depth=1, func_name="factorial", args="n=3");
    f3 = CallFrame(call_id=3, parent_id=2, depth=2, func_name="factorial", args="n=2");
    f4 = CallFrame(call_id=4, parent_id=3, depth=3, func_name="factorial", args="n=1",
                   locals_state="res=1", status="returned", return_value=1);
    f3_rolled = CallFrame(call_id=3, parent_id=2, depth=2, func_name="factorial", args="n=2",
