    f2_rolled = CallFrame(call_id=2, parent_id=1, depth=1, func_name="factorial", args="n=3",
                          locals_state="res=6", status="returned", return_value=6);
    f1_rolled = CallFrame(call_id=1, parent_id=0, depth=0, func_name="factorial", args="n=4",
                          locals_state="res=24", status="returned", return_value=24);

    root +>:Caller(spawn_order=1):+> f1;
    f1 +>:Caller(spawn_order=2):+> f2;
    f2 +>:Caller(spawn_order=3):+> f3;
    f3 +>:Caller(spawn_order=4):+> f4;
    f4 +>:Caller(spawn_order=5):+> f3_rolled;
    f3_rolled +>:Caller(spawn_order=6):+> f2_rolled;
    f2_rolled +>:Caller(spawn_order=7):+> f1_rolled;

    print("=== Call tree ===");
    root spawn RenderRecursion(step=3);
    print("");
    root spawn StepReplayer();
}

"""Study-design audit with typed graph traversal, leakage detection, and cycle guards."""

node Cohort {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cohort_key: str = "";
    has design_definition: str = "";
    has observed_auc: float = 0.0;
}

node DesignVariable {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has variable_key: str = "";
    has raw_column: str = "";
    has block: str = "";
    has primary: bool = False;
    has leaks_label: bool = False;
}

edge Contains {
}

edge UsesDesign {
    has role: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker DesignAudit {
    can start with Root entry {
        print("Declared design audit");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_cohort with Cohort entry {
        print(f"Cohort: {here.cohort_key}");
        print(f"Primary definition: {here.design_definition}");
        visit [->:UsesDesign:->] else {
            disengage;
        }
    }

    can inspect_variable with DesignVariable entry {
        label = "primary" if here.primary else "sensitivity";
        if here.leaks_label {
            print(f"[INVALID] {here.raw_column} is label-leaking ({label} block)");
        } else {
            print(f"[OK] {here.raw_column} is {label} ({here.block})");
        }
    }
}

walker DependencyGuard {
    has seen_keys: list[str] = [];
    has hops: int = 0;
    has max_hops: int = 12;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can enter_cohort with Cohort entry {
        visit [->:UsesDesign:->] else {
            disengage;
        }
    }

    can follow_dependencies with DesignVariable entry {
        if here.variable_key in self.seen_keys {
            print(f"[CYCLE] dependency revisit at {here.variable_key}");
            disengage;
        } else {
            self.seen_keys.append(here.variable_key);
            self.hops += 1;
            if self.hops >= self.max_hops {
                print("[GUARD] dependency depth limit reached");
                disengage;
            } else {
                visit [->:DependsOn:->] else {
                    print(f"[LEAF] {here.variable_key} has no further dependencies");
                    disengage;
                }
            }
        }
    }
}

with entry {
    cohort = Cohort(
        title="SLE CD4 cohort",
        year=2026,
        cohort_key="SLE_GSE174188_CD4",
        design_definition="collection and technical variables",
        observed_auc=0.81
    );

    batch = DesignVariable(
        title="Batch",
        variable_key="batch",
        raw_column="batch__study",
        block="collection",
        primary=True
    );

    assay = DesignVariable(
        title="Assay",
        variable_key="assay",
        raw_column="assay",
        block="collection",
        primary=True
    );

    case_control = DesignVariable(
        title="Case-control metadata",
        variable_key="case_control",
        raw_column="case_control",
        block="sample quality",
        leaks_label=True
    );

    root +>:Contains:+> cohort;
    cohort +>:UsesDesign(role="primary collection design"):+> batch;
    cohort +>:UsesDesign(role="primary collection design"):+> assay;
    cohort +>:UsesDesign(role="sensitivity metadata"):+> case_control;

    batch +>:DependsOn(reason="stratification key"):+> assay;
    assay +>:DependsOn(reason="stale dependency"):+> batch;
    case_control +>:DependsOn(reason="must not enter the design matrix"):+> batch;

    root spawn DesignAudit();
    root spawn DependencyGuard();
}

"""Build performance audit: model crates, features, and duplicate versions as a graph.

Walk the dependency graph to surface the slowest compilation units and the
duplicate-version offenders — the traversal pattern the issue reporter
hand-rolled with adjacency maps and recursive walks.
"""

node Crate {
    has name: str = "";
    has total_time_s: float = 0.0;
    has frontend_s: float = 0.0;
    has codegen_s: float = 0.0;
    has dirty: bool = True;
}

node FeatureSet {
    has name: str = "";
    has backend: str = "";
}

node BuildScript {
    has name: str = "";
    has c_compile_s: float = 0.0;
}

edge DependsOn { has via_kind: str = ""; }
edge CompilesWith { has role: str = ""; }
edge DuplicateVersionOf { has reason: str = ""; }

walker BuildAuditor {
    has slow_threshold: float = 20.0;
    has slow: list = [];
    has dupes: list = [];

    can start with Root entry {
        print("=== Build Performance Audit (2026-07-20) ===");
        visit [-->];
    }

    can sweep with Crate | FeatureSet | BuildScript entry {
        visit [-->];
    }

    can rank with Crate entry {
        verdict = "SLOW" if here.total_time_s >= self.slow_threshold else "ok";
        if here.total_time_s >= self.slow_threshold {
            self.slow.append([here.name, here.total_time_s, verdict]);
            print(f"[{verdict}] {here.name}: {here.total_time_s:.1f}s");
        }
        visit [->:DependsOn:->];
    }

    can version_seed with Crate entry {
        self.dupes.append([here.name, 1]);
        visit [->:DuplicateVersionOf:->] else {
            disengage;
        }
    }

    can version_count with Crate entry {
        last = self.dupes[-1];
        last[1] = last[1] + 1;
        visit [->:DuplicateVersionOf:->];
    }
}

walker CascadeDelete {
    can start with Root entry {
        visit [-->];
    }

    can drop with Crate entry {
        victim = here;
        print(f"pruning {victim.name} ({victim.total_time_s:.1f}s)");
        del victim;
        visit [-->];
    }
}

with entry {
    aws_lc_sys = Crate(name="aws-lc-sys", total_time_s=85.7, frontend_s=0.0, codegen_s=85.7);
    libgit2_sys = BuildScript(name="libgit2-sys", c_compile_s=71.9);
    syn_v2 = Crate(name="syn", total_time_s=28.1, frontend_s=4.0, codegen_s=24.1);
    rustls = Crate(name="rustls", total_time_s=23.4, frontend_s=3.7, codegen_s=19.7);
    rustls_ring = FeatureSet(name="rustls-ring", backend="ring");
    rustls_aws = FeatureSet(name="rustls-aws-lc", backend="aws-lc-rs");
    jsonschema = Crate(name="jsonschema", total_time_s=22.7, frontend_s=2.8, codegen_s=19.9);

    jsonschema +>:DependsOn(via_kind="reqwest"):+> rustls;
    rustls +>:CompilesWith(role="backend"):+> rustls_ring;
    rustls +>:CompilesWith(role="backend"):+> rustls_aws;
    rustls_aws +>:DependsOn:+> aws_lc_sys;

    libgit2_sys +>:DependsOn(via_kind="https"):+> rustls;

    getrandom_v2 = Crate(name="getrandom-0.2", total_time_s=0.5);
    getrandom_v3 = Crate(name="getrandom-0.3", total_time_s=0.5);
    getrandom_v4 = Crate(name="getrandom-0.4", total_time_s=0.5);
    getrandom_v2 +>:DuplicateVersionOf(reason="legacy crate"):+> getrandom_v3;
    getrandom_v3 +>:DuplicateVersionOf(reason="new major"):+> getrandom_v4;

    root ++> aws_lc_sys ++> libgit2_sys ++> syn_v2 ++> rustls ++> rustls_ring ++> rustls_aws ++> jsonschema ++> getrandom_v2 ++> getrandom_v3 ++> getrandom_v4;

    auditor = BuildAuditor(slow_threshold=20.0);
    root spawn auditor;

    print("");
