"""Depot dispatch checker.

Each delivery route from a depot carries a cargo weight in tonnes. A
truck may only be dispatched when its load is at least 2 tonnes and at
most 8 tonnes on the same leg. A walker visits every depot and reports
which routes qualify for dispatch.
"""

node Route {
    has name: str = "";
    has weight: float = 0.0;
}

edge Delivers {
    has leg_label: str = "";
}

node Depot {
    has depot_name: str = "";

    def qualifies(r: Route) -> bool {
        return r.weight >= 2.0 and r.weight <= 8.0;
    }
}

walker DispatchAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Depot entry {
        print(f"Depot: {here.depot_name}");
        outgoing = [here->:Delivers:->];
        for r in outgoing {
            if here.qualifies(r) {
                print(f"  DISPATCH OK -> {r.name} ({r.weight}t)");
            } else {
                print(f"  SKIP       -> {r.name} ({r.weight}t)");
            }
        }
        visit [-->];
    }
}

with entry {
    north = Depot(depot_name="North");
    south = Depot(depot_name="South");

    root +>:Delivers(leg_label="L1"):+> north;
    root +>:Delivers(leg_label="L2"):+> south;

    north +>:Delivers(leg_label="N-A"):+> Route(name="North-Central", weight=5.5);
    north +>:Delivers(leg_label="N-B"):+> Route(name="North-Coast", weight=1.0);
    north +>:Delivers(leg_label="N-C"):+> Route(name="North-Mountain", weight=8.0);

    south +>:Delivers(leg_label="S-A"):+> Route(name="South-Port", weight=9.5);
    south +>:Delivers(leg_label="S-B"):+> Route(name="South-Inland", weight=2.0);
    south +>:Delivers(leg_label="S-C"):+> Route(name="South-Border", weight=7.25);

    root spawn DispatchAuditor();
}

"""Google Drive (DWD scoped) ACL inheritance demo.

Models a Shared Drive with limited-access folders, drive membership,
folder-level grants, and a walker that recomputes effective permissions
for each document. The walker also detects stale ACLs and cascades
invalidation to children when a folder's grant changes.
"""

node Drive {
    has name: str = "";
    has members: list[str] = ["user@org"];
}

node Folder {
    has name: str = "";
    has limited_access: bool = False;
    has grants: list[str] = [];
    has stale: bool = False;
}

node Document {
    has title: str = "";
    has effective_acl: list[str] = [];
    has stale: bool = False;
}

edge Contains {}
edge Grants {}

walker AclAuditor {
    has drive_acl: list[str] = [];
    has baseline_acl: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter with Drive entry {
        self.baseline_acl = list(here.members);
        self.drive_acl = list(here.members);
        print(f"=== Auditing drive: {here.name} (members: {self.baseline_acl}) ===");
        visit [-->];
    }

    can audit_folder with Folder entry {
        if here.limited_access {
            print(f"  [limited-access boundary] '{here.name}' truncates inherited drive ACL");
            self.drive_acl = list(here.grants);
        } else {
            if here.grants {
                merged: list[str] = list(self.drive_acl);
                for g in here.grants {
                    if g not in merged {
                        merged.append(g);
                    }
                }
                self.drive_acl = merged;
                print(f"  Folder '{here.name}' grants: {here.grants} -> effective scope: {self.drive_acl}");
            }
        }
        if here.stale {
            print(f"  [stale] folder '{here.name}' grant changed -> cascading invalidate");
        }
        visit [-->];
    }

    can audit_doc with Document entry {
        acl = list(self.drive_acl);
        if here.stale {
            print(f"  [re-traverse] doc '{here.title}' marked stale; recomputing");
        }
        here.effective_acl = acl;
        print(f"  Doc '{here.title}' effective_acl = {here.effective_acl}");
    }
}

with entry {
    team_drive = Drive(name="Engineering DWD");
    root ++> team_drive;

    shared_folder = Folder(name="Shared Projects");
    limited_folder = Folder(name="Confidential", limited_access=True, grants=["lead@org"]);
    stale_folder = Folder(name="Renamed Team", stale=True, grants=["newteam@org"]);

    team_drive ++> shared_folder;
    team_drive ++> limited_folder;
    team_drive ++> stale_folder;

    doc_a = Document(title="roadmap.md");
    doc_b = Document(title="spec.doc");
    doc_c = Document(title="secrets.docx");

    shared_folder ++> doc_a;
    shared_folder ++> doc_b;
    limited_folder ++> doc_c;

    print("--- Drive-wide baseline ---");
    team_drive ++> Document(title="public_readme.md");

    root spawn AclAuditor();
}

"""Data center clearance enforcement.

Server rooms post a clearance level they require. Technicians carry a
granted clearance level; they are admitted to a room only when their
level meets the requirement. A denial ends the walkthrough immediately,
so a technician that is refused at one room never reaches any deeper
room in the corridor. The final report counts how many rooms each
technician successfully entered.
"""

node Room {
    has label: str = "";
    has required_level: int = 0;
}

edge LeadsTo {
    has label: str = "";
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_visited: int = 0;
    has denied: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can walk with Room entry {
        if self.denied {
            # Already refused at an earlier room; corridor ends here.
            disengage;
        }
        if self.clearance >= here.required_level {
            self.rooms_visited += 1;
            print(f"{self.name} admitted to {here.label} (needs {here.required_level})");
            visit [-->];
        } else {
            self.denied = True;
            print(f"{self.name} DENIED at {here.label} (needs {here.required_level}, has {self.clearance})");
            disengage;
        }
    }
}

with entry {
    # Build the corridor: ServerA -> ServerB -> Vault -> ColdStorage
    server_a = Room(label="ServerA", required_level=1);
    server_b = Room(label="ServerB", required_level=2);
    vault = Room(label="Vault", required_level=3);
    cold = Room(label="ColdStorage", required_level=4);
    root ++> server_a ++> server_b ++> vault ++> cold;

    # Junior: cleared for level 1 only -> stopped at ServerB.
    junior = Technician(name="Junior", clearance=1);
    root spawn junior;
    print(f"{junior.name} reached {junior.rooms_visited} room(s)");

    # Mid: cleared for level 3 -> into the Vault, stopped at ColdStorage.
    mid = Technician(name="Mid", clearance=3);
    root spawn mid;
    print(f"{mid.name} reached {mid.rooms_visited} room(s)");

    # Senior: cleared for everything -> reaches every room.
    senior = Technician(name="Senior", clearance=5);
    root spawn senior;
    print(f"{senior.name} reached {senior.rooms_visited} room(s)");
}

