"""GitHub Actions CI pipeline modeled as a typed-edge graph.

Stages are connected by DependsOn edges (the CI dependency order). Jobs own
their stages via AssignedTo edges. A walker enforces the pipeline sequence,
detects cycles, and halts when a critical stage fails. The runner has been
folded into the Stage node (it just carries a host label); the whole demo is
self-contained and avoids any filesystem state.
"""

node Stage {
    has title: str = "";
    has command: str = "";
    has passed: bool = False;
    has critical: bool = True;
    has host: str = "";
}

node Job {
    has name: str = "";
}

edge DependsOn {
    has order: int = 0;
}

edge AssignedTo {
    has slot: int = 0;
}

walker CIPipeline {
    has blocked: bool = False;
    has visited: list[str] = [];

    can start with Root entry {
        print("git push received -> GitHub Actions triggered");
        visit [-->];
    }

    can enter_job with Job entry {
        print(f"  [job] {here.name}");
        visit [-->];
    }

    can run_stage with Stage entry {
        # Cycle guard: stages are tracked by title; revisit = cycle.
        for tag in self.visited {
            if tag == here.title {
                cycle_msg = f"    CYCLE detected at stage '{here.title}'";
                print(cycle_msg);
                self.blocked = True;
                disengage;
            }
        }
        self.visited.append(here.title);

        if not here.passed {
            outcome = "FAIL";
            print(f"    [{outcome}] {here.title}: {here.command} on {here.host}");
            if here.critical {
                self.blocked = True;
                print("    critical stage failed -> workflow halted");
                disengage;
            }
        } else {
            print(f"    [PASS] {here.title}: {here.command} on {here.host}");
        }
        visit [-->];
    }
}

with entry {
    tests = Job(name="tests");
    lint = Job(name="lint");
    build = Job(name="build");

    test_stage = Stage(title="tests", command="pytest", passed=True, critical=True, host="ubuntu-22.04");
    lint_stage = Stage(title="lint", command="ruff check", passed=False, critical=True, host="ubuntu-22.04");
    build_stage = Stage(title="build", command="python -m build", passed=True, critical=True, host="ubuntu-22.04");

    root ++> tests ++> lint ++> build;

    tests +>:AssignedTo(slot=0):+> test_stage;
    lint +>:AssignedTo(slot=1):+> lint_stage;
    build +>:AssignedTo(slot=2):+> build_stage;

    test_stage +>:DependsOn(order=0):+> lint_stage;
    lint_stage +>:DependsOn(order=1):+> build_stage;

    print("=== CI run #1: lint fails ===");
    runner_one = CIPipeline();
    root spawn runner_one;
    verdict_one = "FAILED" if runner_one.blocked else "PASSED";
    print(f"workflow verdict: {verdict_one}");

    print("");
    print("=== CI run #2: all green ===");
    test_stage.passed = True;
    lint_stage.passed = True;
    runner_two = CIPipeline();
    root spawn runner_two;
    verdict_two = "FAILED" if runner_two.blocked else "PASSED";
    print(f"workflow verdict: {verdict_two}");
}

