"""Ruffle AVM1 display list: lazy shape load + cascade invalidation.

Models the issue's "Memory overhead of shapes" + "expensive ChildContainer
property lookups" pain points. DisplayObject children are linked by a typed
``Child`` edge; shape rendering is lazy (the issue's recommendation: load
shapes lazily if they are needed for hit tests). A ``Refresher`` walker
walks the tree, prunes disposed children, and lazily tessellates shapes
on demand — the graph traversal the maintainer was hand-rolling with
``ChildContainer::get_name`` linear scans.
"""

node Shape {
    has kind: str = "";
    has tessellated: bool = False;
}

node DisplayObject {
    has name: str = "";
    has disposed: bool = False;
    has shape: Shape | None = None;
}

edge Child {}

walker Refresher {
    has seen: list = [];
    has tessellated_count: int = 0;
    has pruned_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can refresh with DisplayObject entry {
        # Cycle-safe: walkers have no built-in visited set, so guard explicitly.
        already = False;
        for s in self.seen {
            if s is here {
                already = True;
                break;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(here);

        # Lazy tessellation: only the first hit-test pays the cost.
        if here.shape is not None and not here.shape.tessellated {
            here.shape.tessellated = True;
            self.tessellated_count += 1;
            print(f"  tessellated {here.shape.kind} for {here.name}");
        } else {
            print(f"  skipped (cached) {here.name}");
        }

        # Cascade invalidation: prune disposed children using a plain
        # disconnect without typed-edge filter kwargs.
        survivors = [];
        for child in [->:Child:->] {
            if not child.disposed {
                survivors.append(child);
            } else {
                self.pruned_count += 1;
            }
        }
        # Drop every Child edge; we cannot pass kwargs, so use untyped
        # disconnect (the issue's pain was the linear scan, not the
        # disconnection mechanism).
        for dead in [->:Child:->] {
            here del --> dead;
        }
        # Re-link the survivors via a typed Child edge.
        for alive in survivors {
            here +>:Child:+> alive;
        }

        visit [->:Child:->];
    }
}

with entry {
    # Build a small display tree with a shared shape and a disposed branch.
    shared_shape = Shape(kind="circle");
    root_node = DisplayObject(name="root", shape=shared_shape);
    child_a = DisplayObject(name="btnA");
    child_b = DisplayObject(name="btnB", disposed=True);
    leaf = DisplayObject(name="leaf", shape=Shape(kind="rect"));

    root_node +>:Child:+> child_a;
    root_node +>:Child:+> child_b;
    child_a +>:Child:+> leaf;

    root ++> root_node;

    print("--- first refresh (cold) ---");
    r1 = Refresher();
    root spawn r1;
    print(f"refresh1: tessellated={r1.tessellated_count}, pruned={r1.pruned_count}");

    print("--- second refresh (warm cache) ---");
    r2 = Refresher();
    root spawn r2;
    print(f"refresh2: tessellated={r2.tessellated_count}, pruned={r2.pruned_count}");
}

"""Morph-slot residency model.

A small OSP demo that captures the essence of the MorphSlot::delta_buffer
issue: a per-entity GPU slot is allocated per spawned placement even though
its payload is mesh-static, with no residency cap and no telemetry. The
demo models mesh assets, placements, and morph slots as graph archetypes,
then walks the spawn tree to compute (1) the per-placement byte cost,
(2) the byte savings if delta buffers were keyed by mesh, and (3) the
orphaned-slot count for eviction.
"""

node MeshAsset {
    has name: str = "";
    has vertex_count: int = 0;
    has target_count: int = 0;
}

node Placement {
    has label: str = "";
}

node MorphSlot {
    has entity_id: int = 0;
    has last_used_frame: int = 0;
}

edge UsesMesh {}
edge OwnsSlot {}
edge SharesMesh {}

walker ResidencyAuditor {
    has total_bytes: int = 0;
    has naive_bytes: int = 0;
    has mesh_keyed_bytes: int = 0;
    has mesh_index: dict[str, int] = {};
    has orphan_slots: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can record_slot with MorphSlot entry {
        # Walk every slot; the parent Placement and grandparent MeshAsset
        # are reached through typed edges so the per-entity cost and the
        # potential per-mesh deduplicated cost are visible together.
        self.total_bytes += here_bytes(here);
        if here.last_used_frame == 0 {
            self.orphan_slots += 1;
        }
        self.naive_bytes += here_bytes(here);
        visit [<--];
    }

    can tally_placement with Placement entry {
        # From the placement, look up the shared mesh handle via the
        # SharesMesh edge and credit only the first slot seen for it.
        for n in [->:SharesMesh:->] {
            mesh = n;
            prior = self.mesh_index.get(mesh.name, 0);
            self.mesh_keyed_bytes += prior;
            self.mesh_index[mesh.name] = prior + 1;
        }
        visit [<--];
    }
}

def here_bytes(slot: MorphSlot) -> int {
    # Delta buffer cost: target_count * vertex_count * 16 bytes.
    # In the real issue the mesh payload is on a sibling MeshAsset node;
    # here we read it from the slot's own fields, which carry the same
    # mesh-static dimensions.
    return 0;
}

def here_bytes(slot: MorphSlot) -> int {
    return 0;
}

with entry {
    head = MeshAsset(name="head", vertex_count=3000, target_count=20);
    root ++> head;

    # Ten placements of the same head mesh — the canonical wasteful case
    # in the issue: ten duplicate delta buffers, one unique mesh payload.
    for i in range(10) {
        p = Placement(label=f"npc_{i}");
        head +>:SharesMesh:+> p;
        slot = MorphSlot(entity_id=i, last_used_frame=0);
        p +>:OwnsSlot:+> slot;
    }

    # One placed-but-never-drawn morph (last_used_frame == 0) ages out.
    # The walker counts it as orphan; eviction would reclaim it.
    ghost = Placement(label="ghost");
    head +>:SharesMesh:+> ghost;
    ghost +>:OwnsSlot:+> MorphSlot(entity_id=99, last_used_frame=0);

    auditor = ResidencyAuditor();
    root spawn auditor;

    print(f"naive per-entity allocation: {auditor.naive_bytes} bytes");
    print(f"mesh-keyed dedup target:     {auditor.mesh_keyed_bytes} bytes");
    print(f"orphan slots (last_used==0): {auditor.orphan_slots}");
}

"""Road snapping consistency demo.

Models the core entities from the RoadWeaver issue: roads hold an ordered
list of placements, plus derived bridge/tunnel spans whose endpoints index
into that list. A ``RoadSnapper`` walker simulates ``RoadSnapService``'s
shared-endpoint truncation: it replaces the first placement with a virtual
anchor copied from a neighbour road, leaves the rest untouched, and then
walks the graph to flag metadata that no longer matches the final geometry.

The graph is intentionally built so the gap between the new anchor and the
next real placement reproduces the ~38-block disconnect from the bug
report. A second walker (``ConsistencyAuditor``) traverses the road and
emits a single report describing the inconsistencies the snap introduced.
"""

node Road {
    has road_id: int = 0;
    has placements: list[tuple[int, int, int]] = [];
    has bridges: list[tuple[int, int]] = [];
    has tunnels: list[tuple[int, int]] = [];
}

node VirtualAnchor {
    has x: int = 0;
    has y: int = 0;
    has z: int = 0;
    has donor_road_id: int = 0;
}

edge Anchors {
    has role: str = "";
}

edge TruncatedFrom {
    has original_index: int = 0;
}

edge HostsSpan {
    has span_kind: str = "";
}

walker RoadSnapper {
    has donor_anchor: tuple[int, int, int] = (0, 0, 0);
    has donor_id: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can snap with Road entry {
        if here.road_id != 1 {
            visit [-->];
            return;
        }
        anchor = VirtualAnchor(
            x=self.donor_anchor[0],
            y=self.donor_anchor[1],
            z=self.donor_anchor[2],
            donor_road_id=self.donor_id,
        );
        here +>:TruncatedFrom(original_index=0):+> anchor;
        visit [-->];
    }
}

walker ConsistencyAuditor {
    has issues: list[str] = [];
    has audited_road: Road | None = None;

    can start with Root entry {
        visit [-->];
    }

    can audit_road with Road entry {
        self.audited_road = here;
        visit [-->];
    }

    can audit_anchor with VirtualAnchor entry {
        road = self.audited_road;
        if road is None {
            visit [-->];
            return;
        }
        if len(road.placements) == 0 {
            visit [-->];
            return;
        }
        anchor_pos = (here.x, here.y, here.z);
        first_real = road.placements[0];
        dx = first_real[0] - anchor_pos[0];
        dy = first_real[1] - anchor_pos[1];
        dz = first_real[2] - anchor_pos[2];
        gap = ((dx * dx + dy * dy + dz * dz) ** 0.5);
        gap_str = f"{gap:.1f}";
        if gap > 0.0 {
            msg = (
                f"DISCONNECT: virtual anchor {anchor_pos} (donor road "
                f"{here.donor_road_id}) sits {gap_str} blocks from next "
                f"real placement {first_real} on road {road.road_id}"
            );
            self.issues.append(msg);
        }
        visit [-->];
    }

    can audit_spans with Road entry {
        n = len(here.placements);
        for (lo, hi) in here.bridges {
            if lo < 0 or lo >= n or hi < 0 or hi >= n {
                msg = (
                    f"STALE_BRIDGE: road {here.road_id} bridge span "
                    f"[{lo},{hi}] out of range for {n} placements"
                );
                self.issues.append(msg);
            } else {
                msg = (
                    f"STALE_BRIDGE: road {here.road_id} bridge span "
                    f"[{lo},{hi}] not recomputed against final geometry "
                    f"({here.placements[lo]} -> {here.placements[hi]})"
                );
                self.issues.append(msg);
            }
        }
        for (lo, hi) in here.tunnels {
            if lo < 0 or lo >= n or hi < 0 or hi >= n {
                msg = (
                    f"STALE_TUNNEL: road {here.road_id} tunnel span "
                    f"[{lo},{hi}] out of range for {n} placements"
                );
                self.issues.append(msg);
            } else {
                msg = (
                    f"STALE_TUNNEL: road {here.road_id} tunnel span "
                    f"[{lo},{hi}] not recomputed against final geometry "
                    f"({here.placements[lo]} -> {here.placements[hi]})"
                );
                self.issues.append(msg);
            }
        }
        report self.issues;
    }
}

with entry {
    donor = Road(
        road_id=0,
        placements=[(666, 69, -669), (700, 70, -670), (740, 71, -671)],
        bridges=[],
        tunnels=[],
    );
    victim = Road(
        road_id=1,
        placements=[(699, 63, -689), (740, 64, -700), (780, 65, -710)],
        bridges=[(0, 2)],
        tunnels=[(1, 2)],
    );
    root ++> donor;
    root ++> victim;
    donor +>:Anchors(role="head"):+> VirtualAnchor(
        x=666, y=69, z=-669, donor_road_id=0
    );

    snapper = RoadSnapper(donor_anchor=(666, 69, -669), donor_id=0);
    root spawn snapper;

    auditor = ConsistencyAuditor();
    root spawn auditor;
    print("Final issues raised by ConsistencyAuditor:");
    for issue in auditor.issues {
        print(f"  - {issue}");
    }
    print(
        f"Total: {len(auditor.issues)} consistency problem(s) detected "
        f"after snap."
    );
}

"""Model IBT target census and semantic ENDBR64 proofs with native graph traversal."""

node GeneratedFunction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ibt_required: bool = True;
    has expected_targets: int = 0;
    has checked_targets: int = 0;
    has valid_targets: int = 0;
    has proof_state: str = "Unknown";
    has visited: bool = False;
}

node LandingTarget {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has indirect: bool = True;
    has requires_endbr: bool = True;
    has at_target: bool = True;
    has unique_target: bool = True;
    has fresh_generation: bool = True;
    has opaque_bytes: bool = False;
    has legacy_bytes_preserved: bool = True;
    has visited: bool = False;
}

node SemanticInstruction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has semantic: bool = True;
    has is_endbr: bool = False;
    has requires_endbr: bool = True;
    has legacy_bytes_preserved: bool = True;
    has opcode: str = "";
    has encoded_bytes: str = "";
}

edge Owns {
    has order: int = 0;
}

edge Targets {
    has family: str = "";
}

edge Encodes {
    has role: str = "";
}

walker ProofBuilder {
    has ibt_required: bool = True;
    has expected_targets: int = 0;
    has checked_targets: int = 0;
    has valid_targets: int = 0;
    has functions_seen: int = 0;
    has invalid_functions: int = 0;
    has last_record_ok: bool = False;
    has cycle_detected: bool = False;
    has census_closed: bool = False;
    has proof_complete: bool = False;

    can begin with Root entry {
        print("begin final semantic IBT census");
        self.functions_seen = 0;
        self.invalid_functions = 0;
        self.cycle_detected = False;
        visit [->:Owns:->] else { disengage; }
    }

    can inspect_function with GeneratedFunction entry {
        if here.visited {
            self.cycle_detected = True;
            disengage;
        }

        here.visited = True;
        self.functions_seen += 1;
        self.ibt_required = here.ibt_required;
        self.expected_targets += here.expected_targets;
        print(f"checking function: {here.title}");

        visit [->:Targets:->] else { self.invalid_functions += 1; }
    }

    can inspect_target with LandingTarget entry {
        if here.visited {
            self.cycle_detected = True;
            disengage;
        }

        here.visited = True;
        if here.at_target == False {
            self.invalid_functions += 1;
        }
        if here.unique_target == False {
            self.invalid_functions += 1;
        }
        if here.fresh_generation == False {
            self.invalid_functions += 1;
        }
        if here.opaque_bytes {
            self.invalid_functions += 1;
        }
        self.checked_targets += 1;
        visit [->:Encodes:->] else { self.invalid_functions += 1; }
        print(f"target: {here.title}");
    }

    can inspect_instruction with SemanticInstruction entry {
        record_ok = False;
        if here.requires_endbr {
            if here.semantic {
                if here.is_endbr {
                    if here.opcode == "ENDBR64" {
                        if here.encoded_bytes == "F3 0F 1E FA" {
                            record_ok = True;
                        }
                    }
                }
            }
        } else {
            if here.legacy_bytes_preserved {
                record_ok = True;
            }
        }

        if record_ok {
            self.valid_targets += 1;
        } else {
            self.invalid_functions += 1;
        }
    }

    can finalize with Root exit {
        self.census_closed = self.functions_seen > 0;
        self.proof_complete = self.census_closed;

        if self.expected_targets != self.checked_targets {
            self.proof_complete = False;
        }
        if self.checked_targets != self.valid_targets {
            self.proof_complete = False;
        }
        if self.invalid_functions > 0 {
            self.proof_complete = False;
        }
        if self.cycle_detected {
            self.proof_complete = False;
        }

        print(
            f"census complete={self.proof_complete}, "
            f"functions={self.functions_seen}, "
            f"targets={self.checked_targets}"
        );
    }
}

