"""ElectroDB-style read-path JIT formatter demo.

Models the per-item formatting pipeline that the issue complains about:
a schema is fixed at entity construction, but every read re-walks it.
We model an Entity (with attributes and nested sub-models), a ReadItem,
a typed Format edge, and walkers that traverse the schema graph and
cascade-invalidate cached formatters when an entity is dropped.
"""

# ---------- Edge archetype ----------
edge Format {
    has role: str = "";
}

# ---------- Base schema-shape node: shared fields for the union trigger ----------
node SchemaShape {
    has label: str = "";
}

# ---------- Entity: the model whose schema is walked per item ----------
node Entity(SchemaShape) {
    has attributes: list[str] = [];
    has owned: list[str] = [];
}

# ---------- SubModel: nested shape inside an Entity ----------
node SubModel(SchemaShape) {
    has fields: list[str] = [];
}

# ---------- CompiledSchema: produced once at Entity construction ----------
node CompiledSchema(SchemaShape) {
    has attribute_count: int = 0;
    has nested_count: int = 0;
}

# ---------- ReadItem: one row pulled from the store ----------
node ReadItem {
    has label: str = "";
}

# ---------- JitFormatter: walker that performs the read-path formatting ----------
walker JitFormatter {
    has formatted_count: int = 0;
    has visited_schemas: list[str] = [];

    can start with Root entry {
        visit [->:Format:->];
    }

    can shape with CompiledSchema entry {
        if here.label not in self.visited_schemas {
            self.visited_schemas.append(here.label);
        }
        visit [here->:Format:->];
    }

    can collect_attr with Entity entry {
        self.formatted_count += len(here.attributes);
        visit [here->:Format:->];
    }

    can collect_nested with SubModel entry {
        self.formatted_count += len(here.fields);
    }

    can apply with ReadItem entry {
        visit [here->:Format:->];
    }

    # Union ability: a single routine handles the three schema shapes
    # that the read path formats over. The body only touches the shared
    # ``label`` field declared on the common SchemaShape parent.
    can finalize with CompiledSchema | Entity | SubModel entry {
        if here.label not in self.visited_schemas {
            self.visited_schemas.append(here.label);
        }
    }
}

# ---------- CascadeInvalidator: walker that drops cached formatters ----------
walker CascadeInvalidator {
    has invalidated: int = 0;

    can start with Root entry {
        visit [->:Format:->];
    }

    can drop_schema with CompiledSchema entry {
        self.invalidated += 1;
        visit [-->];
    }

    can drop_item with ReadItem entry {
        self.invalidated += 1;
        visit [-->];
    }

    # Union ability: drops any schema-shape node in one place.
    can drop_shape with Entity | SubModel entry {
        self.invalidated += 1;
        visit [-->];
    }
}

# ---------- Demo wiring ----------
with entry {
    # Build a User entity with two nested sub-models.
    user_schema = CompiledSchema(label="User", attribute_count=6, nested_count=2);
    user_email = SubModel(label="email", fields=["addr", "verified"]);
    user_addr = SubModel(label="address", fields=["city", "zip"]);
    user = Entity(label="User", attributes=["id", "name", "email", "city", "zip", "role"],
                  owned=["id", "name"]);

    # Build an Order entity that shares the address sub-model.
    order_schema = CompiledSchema(label="Order", attribute_count=4, nested_count=1);
    order_addr = SubModel(label="address", fields=["city", "zip"]);
    order = Entity(label="Order", attributes=["id", "total", "city", "zip"], owned=["id"]);

    # Read items being shaped.
    item_a = ReadItem(label="row-1");
    item_b = ReadItem(label="row-2");

    # Typed-edge wiring: Format edges carry the role of each relation.
    user +>:Format(role="compiles"):+> user_schema;
    user_schema +>:Format(role="owns"):+> user_email;
    user_schema +>:Format(role="owns"):+> user_addr;
    item_a +>:Format(role="shapes"):+> user_schema;

    order +>:Format(role="compiles"):+> order_schema;
    order_schema +>:Format(role="owns"):+> order_addr;
    item_b +>:Format(role="shapes"):+> order_schema;

    # Root chains in everything so a single spawn reaches the graph.
    root ++> user ++> order ++> item_a ++> item_b;

    # Run the JIT read-path formatter.
    fmt = JitFormatter();
    root spawn fmt;
    print(f"[jit] formatted {fmt.formatted_count} attribute slots "
          f"across {len(fmt.visited_schemas)} compiled schemas");

    # Now invalidate: dropping an entity must cascade.
    inv = CascadeInvalidator();
    root spawn inv;
    print(f"[cascade] invalidated {inv.invalidated} cached entries");
}

"""Static namespace call-graph demo with dot, literal bracket, and shadowed calls."""

node Function {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has id: str = "";
    has source_file: str = "";
}

node Namespace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has id: str = "";
}

node CallSite {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has id: str = "";
    has receiver: str = "";
    has member: str = "";
    has access_form: str = "";
    has resolved: bool = False;
    has shadowed: bool = False;
}

edge Contains { }

edge Resolves {
    has receiver: str = "";
    has member: str = "";
    has access_form: str = "";
}

edge Exports {
    has member: str = "";
}

edge Imports {
    has alias: str = "";
}

walker CallGraph {
    has seen: list[str] = [];

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_function with Function entry {
        if here.id in self.seen {
            print(f"cycle/revisit skipped: {here.id}");
        } else {
            self.seen.append(here.id);
            print(f"function: {here.title} [{here.id}]");
            visit [->:Contains:->] else { disengage; }
        }
    }

    can inspect_namespace with Namespace entry {
        if here.id in self.seen {
            print(f"namespace revisit skipped: {here.id}");
        } else {
            self.seen.append(here.id);
            print(f"imported namespace: {here.title}");
            visit [->:Exports:->] else { disengage; }
        }
    }

    can inspect_call with CallSite entry {
        form_label = "BRACKET" if here.access_form == "bracket" else "DOT";
        call_text = f"{here.receiver}[{here.member}]" if here.access_form == "bracket" else f"{here.receiver}.{here.member}";

        if here.resolved {
            print(f"{form_label} {here.title}: {call_text}");
            if here.shadowed {
                print("  shadow guard: local receiver is not an imported export");
            }
            visit [->:Resolves:->] else { disengage; }
        } else {
            print(f"UNRESOLVED {here.title}: {call_text}");
        }
    }
}

with entry {
    names = Namespace(
        id="lib.names",
        title="names",
        year=2026
    );

    render = Function(
        id="app.renderGreeting",
        title="renderGreeting",
        source_file="app.ts"
    );

    prepare = Function(
        id="lib.prepareName",
        title="prepareName",
        source_file="names.ts"
    );

    trim = Function(
        id="lib.trimName",
        title="trimName",
        source_file="names.ts"
    );

    nested = Function(
        id="app.nested",
        title="nested",
        source_file="app.ts"
    );

    local_prepare = Function(
        id="app.nested.prepareName",
        title="prepareName",
        source_file="app.ts"
    );

    dot_call = CallSite(
        id="call.dot",
        title="renderGreeting.dot",
        receiver="names",
        member="prepareName",
        access_form="dot",
        resolved=True
    );

    bracket_call = CallSite(
        id="call.bracket",
        title="renderGreeting.bracket",
        receiver="names",
        member="prepareName",
        access_form="bracket",
        resolved=True
    );

    dynamic_call = CallSite(
        id="call.dynamic",
        title="renderGreeting.dynamic",
        receiver="names",
        member="key",
        access_form="computed",
        resolved=False
    );

    trim_call = CallSite(
        id="call.trim",
        title="prepareName.trim",
        receiver="names",
        member="trimName",
        access_form="dot",
        resolved=True
    );

    shadow_call = CallSite(
        id="call.shadowed",
        title="nested.shadowed",
        receiver="names",
        member="prepareName",
        access_form="bracket",
        resolved=True,
        shadowed=True
    );

    root ++> render;
    root ++> nested;
    root +>:Imports(alias="names"):+> names;

    render +>:Contains:+> dot_call;
    render +>:Contains:+> bracket_call;
    render +>:Contains:+> dynamic_call;
    prepare +>:Contains:+> trim_call;
    nested +>:Contains:+> shadow_call;

    dot_call +>:Resolves(
        receiver="names",
        member="prepareName",
        access_form="dot"
    ):+> prepare;

    bracket_call +>:Resolves(
        receiver="names",
        member="prepareName",
        access_form="bracket"
    ):+> prepare;

    trim_call +>:Resolves(
        receiver="names",
        member="trimName",
        access_form="dot"
    ):+> trim;

    shadow_call +>:Resolves(
        receiver="names",
        member="prepareName",
        access_form="bracket"
    ):+> local_prepare;

    names +>:Exports(member="prepareName"):+> prepare;
    names +>:Exports(member="trimName"):+> trim;

    root spawn CallGraph();
}

