"""Flight network: legs store ticket prices; a scout walker reports peak fare for normalization."""

node Airport {
    has title: str = "";
    has code: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge FlightLeg {
    has price: float = 0.0;

    def fare_fraction(top_fare: float) -> float {
        if top_fare <= 0.0 {
            return 0.0;
        }
        return self.price / top_fare;
    }
}

walker Scout {
    has reports: list[float] = [];
    has seen_codes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can map with Airport entry {
        if here.code in self.seen_codes {
            disengage;
        }
        self.seen_codes.append(here.code);
        for leg in [edge ->:FlightLeg:->] {
            report leg.price;
            self.reports.append(leg.price);
        }
        visit [-->];
    }
}

