```jac
"""Local evidence index for repository facts.

Models the core scenario from the issue: a small in-memory index of
repository evidence (files, analyzed Rust items, and findings) where
analyzers can record facts with provenance, look up cached results
by content hash, and walk the dependency graph to invalidate downstream
findings when a source file changes.

The graph is built with typed edges so traversal is explicit:
  - Contains: a crate/file owns its items
  - DerivedFrom: a finding cites the items it was produced from
  - DependsOn: an analyzer depends on upstream findings

A walker traverses the dependency graph and invalidates any finding
whose provenance file's hash has changed (cache invalidation by
content hash, as the issue requires). A second walker walks the
ownership tree to surface every fact an analyzer can query.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node RepoFile {
    has path: str = "";
    has content_hash: str = "";
    has available: bool = True;
}

node RustItem {
    has kind: str = "";
    has name: str = "";
    has available: bool = True;
}

node Finding {
    has summary: str = "";
    has confidence: float = 0.0;
    has stale: bool = False;
    has available: bool = True;
}

node Analyzer {
    has name: str = "";
    has available: bool = True;
}

# ---------------------------------------------------------------------------
# Typed edge archetypes
# ---------------------------------------------------------------------------

edge Contains {
    has line: int = 0;
}

edge DerivedFrom {
    has role: str = "evidence";
}

edge DependsOn {
    has weight: float = 1.0;
}

# ---------------------------------------------------------------------------
# Walker 1: indexer — surfaces every fact reachable through Contains
# ---------------------------------------------------------------------------

walker Indexer {
    has facts_seen: int = 0;
    has current_path: str = "";

    can start with Root entry {
        print("== Indexer: walking the evidence tree ==");
        visit [-->];
    }

    can walk_files with RepoFile entry {
        self.current_path = here.path;
        self.facts_seen += 1;
        print(f"  file  {here.path}  hash={here.content_hash}");
        visit [-->];
    }

    can walk_items with RustItem entry {
        self.facts_seen += 1;
        print(f"    item {here.kind} {here.name} in {self.current_path}");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Walker 2: invalidator — propagates staleness through DerivedFrom edges
# ---------------------------------------------------------------------------

walker Invalidator {
    has changed_paths: list[str] = [];
    has invalidated: int = 0;

    can start with Root entry {
        if not self.changed_paths {
            print("== Invalidator: no file hashes changed, nothing to do ==");
            disengage;
        }
        print("== Invalidator: propagating staleness ==");
        print(f"   changed files: {self.changed_paths}");
        visit [-->];
    }

    can scan with RepoFile entry {
        if here.content_hash in self.changed_paths {
            print(f"  hash drift on {here.path} -> mark downstream");
            visit [->:Contains:->];
        } else {
            visit [-->];
        }
    }

    can scan_items with RustItem entry {
        visit [-->];
    }

    can mark with Finding entry {
        here.stale = True;
        here.available = False;
        self.invalidated += 1;
        print(f"    INVALIDATED finding '{here.summary}' "
              f"(confidence={here.confidence})");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Walker 3: provenance reporter — walks DerivedFrom edges for one finding
# ---------------------------------------------------------------------------

walker Provenance {
    has evidence: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with Analyzer entry {
        visit [-->];
    }

    can gather_items with RustItem entry {
        self.evidence.append(f"{here.kind}::{here.name}");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demonstration graph
# ---------------------------------------------------------------------------

with entry {
    # Two analyzers sharing the same indexed facts.
    analyzer_a = Analyzer(name="dead-code-detector");
    analyzer_b = Analyzer(name="unsafe-auditor");

    # Three source files, each with a content hash.
    f_main = RepoFile(path="src/main.rs", content_hash="hash-main-v1");
    f_lib  = RepoFile(path="src/lib.rs",  content_hash="hash-lib-v1");
    f_util = RepoFile(path="src/util.rs", content_hash="hash-util-v1");

    # Rust items owned by their files via Contains edges.
    fn_main = RustItem(kind="fn",   name="run");
    fn_lib  = RustItem(kind="fn",   name="helper");
    struct_util = RustItem(kind="struct", name="Bag");

    root +>:Contains(line=1):+> f_main;
    root +>:Contains(line=1):+> f_lib;
    root +>:Contains(line=1):+> f_util;

    f_main +>:Contains(line=10):+> fn_main;
    f_lib  +>:Contains(line=42):+> fn_lib;
    f_util +>:Contains(line=7):+>  struct_util;

    # Two analyzers attach to the root so their sub-trees exist.
    root ++> analyzer_a;
    root ++> analyzer_b;

    # Findings derived from items, citing their evidence by edge.
    finding_dead = Finding(summary="unused fn `helper`", confidence=0.92);
    finding_unsafe = Finding(summary="unsafe block in `Bag`", confidence=0.81);

    analyzer_a +>:DerivedFrom(role="primary"):+> finding_dead;
    finding_dead +>:DerivedFrom(role="evidence"):+> fn_lib;

    analyzer_b +>:DerivedFrom(role="primary"):+> finding_unsafe;
    finding_unsafe +>:DerivedFrom(role="evidence"):+> struct_util;

    # Cross-analyzer dependency: dead-code depends on unsafe-auditor's output.
    analyzer_a +>:DependsOn(weight=0.5):+> analyzer_b;

    # ---- Demo 1: indexer walks the whole evidence tree ----
    idx = Indexer();
    root spawn idx;
    print(f"indexer surfaced {idx.facts_seen} facts\n");

    # ---- Demo 2: invalidator reacts to a changed content hash ----
    inv = Invalidator(changed_paths=["hash-lib-v1"]);
    root spawn inv;
    print(f"invalidator invalidated {inv.invalidated} findings\n");

    # ---- Demo 3: provenance for the now-stale dead-code finding ----
    prov = Provenance();
    finding_dead spawn prov;
    print(f"finding '{finding_dead.summary}' cites: {prov.evidence}");
    print(f"  stale={finding_dead.stale}, available={finding_dead.available}");
}
