"""Native reasoning-loop guard with bounded traversal and safe intervention."""

node GuardProfile {
    has name: str = "";
    has guard_state: str = "observe";
    has suspected_loops: int = 0;
}

node StreamAttempt {
    has attempt_id: str = "";
    has committed: bool = False;
    has aborted: bool = False;
    has abort_reason: str = "";
}

node ReasoningSegment {
    has text: str = "";
    has fingerprint: str = "";
    has concrete_anchor: bool = False;
    has loop_suspected: bool = False;
}

edge OwnsAttempt { }
edge HasSegment { }
edge NextSegment { }

walker LoopGuard {
    has profile: GuardProfile | None = None;
    has attempt: StreamAttempt | None = None;
    has previous_fingerprint: str = "";
    has exact_repeats: int = 0;
    has stalled_segments: int = 0;
    has steps: int = 0;
    has max_steps: int = 12;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_profile with GuardProfile entry {
        self.profile = here;
        visit [->:OwnsAttempt:->] else { disengage; }
    }

    can inspect_attempt with StreamAttempt entry {
        self.attempt = here;
        visit [->:HasSegment:->] else { disengage; }
    }

    can inspect_segment with ReasoningSegment entry {
        self.steps += 1;
        print(f"segment {self.steps}: {here.text}");

        if here.concrete_anchor {
            self.stalled_segments = 0;
        } else {
            self.stalled_segments += 1;
        }

        if here.fingerprint == self.previous_fingerprint {
            self.exact_repeats += 1;
        } else {
            self.exact_repeats = 0;
        }

        if self.exact_repeats >= 2 or self.stalled_segments >= 3 {
            here.loop_suspected = True;

            if self.profile is not None {
                self.profile.suspected_loops += 1;

                if self.attempt is not None {
                    if self.attempt.committed == False {
                        self.attempt.aborted = True;
                        self.attempt.abort_reason = "reasoning_loop";
                        self.profile.guard_state = "abort_if_uncommitted";
                    } else {
                        self.profile.guard_state = "observe_visible_output";
                    }
                }
            }

            print(f"loop detected at segment {self.steps}");
            disengage;
        } else {
            if self.steps >= self.max_steps {
                if self.profile is not None {
                    self.profile.guard_state = "observe_depth_cap";
                }
                disengage;
            } else {
                self.previous_fingerprint = here.fingerprint;
                visit [->:NextSegment:->] else { disengage; }
            }
        }
    }
}

with entry {
    profile = GuardProfile(name="Proxy reasoning guard");
    attempt = StreamAttempt(attempt_id="B-leg-1", committed=False);

    first = ReasoningSegment(
        text="I should verify the implementation",
        fingerprint="verify implementation",
        concrete_anchor=False
    );
    second = ReasoningSegment(
        text="Let me ensure the implementation is verified",
        fingerprint="ensure implementation",
        concrete_anchor=False
    );
    third = ReasoningSegment(
        text="I need to confirm the implementation before proceeding",
        fingerprint="confirm implementation",
        concrete_anchor=False
    );
    fourth = ReasoningSegment(
        text="Now I will verify everything carefully",
        fingerprint="verify carefully",
        concrete_anchor=False
    );

    root ++> profile;
    profile +>:OwnsAttempt:+> attempt;
    attempt +>:HasSegment:+> first;
    first +>:NextSegment:+> second;
    second +>:NextSegment:+> third;
    third +>:NextSegment:+> fourth;
    fourth +>:NextSegment:+> second;

    root spawn LoopGuard();
    print(f"final state: {profile.guard_state}, aborted={attempt.aborted}");
}

"""Governed harness optimization with approval, held-out scoring, lineage, rollback, and cycle safety."""

node Pilot {
    has name: str = "";
    has isolated: bool = False;
    has approved: bool = False;
    has reversible: bool = False;
}

node Candidate {
    has title: str = "";
    has revision: str = "";
    has allowlisted: bool = False;
    has approved: bool = False;
    has rolled_back: bool = False;
    has lineage: str = "";
}

node Evaluation {
    has corpus: str = "";
    has score: float = 0.0;
    has missed_defects: int = 0;
    has false_positives: int = 0;
    has leakage_free: bool = False;
    has latency_ms: int = 0;
    has cost_cents: int = 0;
}

edge Runs { }
edge Targets { }
edge DependsOn { }
edge ScoredBy { }

walker GovernanceAudit {
    has seen_titles: list[str] = [];

    can start with Root entry {
        print("Governance audit started");
        visit [->:Runs:->] else { disengage; }
    }

    can review with Pilot entry {
        decision = "REFUSED";
        if here.approved {
            if here.isolated {
                if here.reversible {
                    decision = "APPROVED";
                }
            }
        }
        print(f"{here.name}: {decision}");
        visit [->:Targets:->] else { disengage; }
    }

    can inspect with Candidate entry {
        if here.title in self.seen_titles {
            print(f"revisited candidate {here.title}; audit stops");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            allowlist_status = "ALLOWLISTED" if here.allowlisted else "NOT ALLOWLISTED";
            approval_status = "APPROVED" if here.approved else "REFUSED";
            rollback_status = "ROLLED BACK" if here.rolled_back else "ACTIVE";
            print(f"{here.title} {here.revision}: {allowlist_status}, {approval_status}, {rollback_status}, lineage={here.lineage}");
            visit [->:ScoredBy:->] else { disengage; }
        }
    }

    can score with Evaluation entry {
        outcome = "REJECT";
        if here.leakage_free {
            if here.score >= 0.8 {
                if here.missed_defects == 0 {
                    outcome = "ACCEPT";
                }
            }
        }
        print(f"{here.corpus}: {outcome}, score={here.score}, missed={here.missed_defects}, false_positives={here.false_positives}, latency_ms={here.latency_ms}, cost_cents={here.cost_cents}");
        visit [-->] else { disengage; }
    }
}

walker DependencyGuard {
    has seen_titles: list[str] = [];

    can check with Candidate entry {
        if here.title in self.seen_titles {
            print(f"dependency cycle detected at {here.title}; stopping safely");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            print(f"dependency check: {here.title}");
            visit [->:DependsOn:->] else { disengage; }
        }
    }
}

