        if not here.dismissed {
            line = f"[FAILED] {here.detail} | status={here.status}";
            self.findings.append(line);
        }
        visit [-->];
    }
}

walker DismissFailed {
    has target_detail: str = "";
    has cleared: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk_host with Host entry {
        visit [->:OwnsProfile:->];
    }

    can walk_profile with WindowsProfile entry {
        visit [->:Removes:->];
    }

    can dismiss with FailedRemoval entry {
        if not here.dismissed and (self.target_detail == "" or here.detail == self.target_detail) {
            here.dismissed = True;
            self.cleared += 1;
        }
        visit [-->];
    }
}

with entry {
    # Two hosts, each with profiles; the second profile on host-b
    # has a failed-remove row that the admin needs to surface + clear.
    host_a = Host(hostname="finance-laptop-01");
    host_b = Host(hostname="eng-laptop-07");

    prof_a1 = WindowsProfile(profile_id="win-cfg-001", name="BitLocker Policy");
