"""Depot dispatch checker: walk routes from each depot and qualify legs by cargo weight."""

node Depot {
    has name: str = "";
}

node Route {
    has label: str = "";
    has cargo_tonnes: float = 0.0;

    def qualifies() -> bool {
        return self.cargo_tonnes >= 2.0 and self.cargo_tonnes <= 8.0;
    }
}

edge Serves {}

walker Dispatcher {
    has depot_name: str = "";
    can start with Root entry {
        visit [-->];
    }
    can check_depot with Depot entry {
        self.depot_name = here.name;
        print(f"Depot {self.depot_name} routes:");
        visit [-->];
    }
    can inspect_route with Route entry {
        verdict = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"  [{verdict}] {here.label} ({here.cargo_tonnes}t)");
    }
}

with entry {
    north = Depot(name="North");
