    north +>:Serves:+> Route(label="N-B", cargo_tonnes=3.0);
    north +>:Serves:+> Route(label="N-C", cargo_tonnes=7.5);
    north +>:Serves:+> Route(label="N-D", cargo_tonnes=9.0);

    south +>:Serves:+> Route(label="S-A", cargo_tonnes=2.0);
    south +>:Serves:+> Route(label="S-B", cargo_tonnes=8.0);
    south +>:Serves:+> Route(label="S-C", cargo_tonnes=0.5);
    south +>:Serves:+> Route(label="S-D", cargo_tonnes=5.5);

    root ++> north ++> south;
    root spawn Dispatcher();
}

"""Delivery routes: model depots as nodes carrying cargo weights and dispatch only routes within the legal weight band."""

node Route {
    has cargo: float = 0.0;

    def is_dispatchable() -> bool {
        return self.cargo >= 2.0 and self.cargo <= 8.0;
    }

    def best_label() -> str {
        label = "DISPATCH" if self.is_dispatchable() else "HOLD";
        return label;
    }
}

node Depot {
    has name: str = "";
    has cargo: float = 0.0;

    def is_dispatchable() -> bool {
        return self.cargo >= 2.0 and self.cargo <= 8.0;
    }

    def best_label() -> str {
        label = "DISPATCH" if self.is_dispatchable() else "HOLD";
        return label;
    }
}

walker Dispatcher {
    has dispatched: int = 0;
    has held: int = 0;

    can start with Root entry {
        print("Dispatch audit starting");
        visit [-->];
    }

    can audit with Route | Depot entry {
        if here.is_dispatchable() {
            self.dispatched += 1;
            label = "DISPATCH";
        } else {
            self.held += 1;
            label = "HOLD";
        }
        print(f"[{label}] {here.best_label()} cargo={here.cargo}t");
        visit [-->];
    }
}

with entry {
    root ++> Route(cargo=3.5)
        ++> Route(cargo=9.0)
        ++> Depot(name="North", cargo=5.0)
        ++> Route(cargo=1.5)
        ++> Depot(name="South", cargo=7.5);
    dispatcher = Dispatcher();
    root spawn dispatcher;
    print(f"Routes dispatched: {dispatcher.dispatched}, held: {dispatcher.held}");
}

