"""Per-user private root notes-and-tasks service demo.

Each authenticated user owns a private root. The ``CreateTask`` walker is
spawned on the authenticated user's root, lands there automatically, and
attaches a fresh ``Task`` node under it. Spawning it twice creates two
tasks; the listing walker ``ListTasks`` then reports what landed under the
same private root.
"""

# --- domain archetype -------------------------------------------------------
node Task {
    has title: str = "";
    has done: bool = False;
}

# --- walker that creates tasks on the calling user's private root -----------
walker CreateTask {
    has title: str;

    # Lands on the authenticated user's private root automatically.
    can land with Root entry {
        next_title = self.title;
        here ++> Task(title=next_title);
        print(f"created task '{next_title}' on user root");
    }
}

# --- walker that reports every task under the private root -------------------
walker ListTasks {
    has count: int = 0;

    can start with Root entry {
        print("tasks on user root:");
        visit [-->];
    }

    can tally with Task entry {
        self.count += 1;
        marker = "x" if here.done else " ";
        print(f"  [{marker}] {here.title}");
        visit [-->];
    }
}

# --- demo wiring -------------------------------------------------------------
with entry {
    # Each authenticated user gets their own private root.
    user_a_root = root;

    user_a_root spawn CreateTask(title="Write design doc");
    user_a_root spawn CreateTask(title="Review pull request");

    user_a_root spawn ListTasks();
}

"""Sanitize only projected judge fields while preserving full rollout data."""

def sanitize_text(text: str) -> str {
    return text.replace("\\ud800", "�");
}

node VerifyRequest {
    has request_id: str = "";
    has expected_text: str = "";
    has generated_text: str = "";
    has token_ids: list[int] = [];
}

node Response {
    has response_text: str = "";
    has parsed_output: str = "";
    has metadata: str = "";
    has tool_content: str = "";
    has token_ids: list[int] = [];
}

node JudgeEvaluation {
    has judge_response: str = "";
    has failure_reason: str = "";
    has reward: float = 0.0;
}

node JudgePayload {
    has expected_text: str = "";
    has generated_text: str = "";
    has response_text: str = "";
    has parsed_output: str = "";
    has metadata: str = "";
    has tool_content: str = "";
    has judge_response: str = "";
    has failure_reason: str = "";
    has reward: float = 0.0;
}

edge OwnsRequest { }
edge ReturnsResponse { }
edge ProducesEvaluation { }
edge ProjectsJudgeFields { }

walker JudgeFieldSanitizer {
    has sanitized_fields: int = 0;

    can start with Root entry {
        visit [->:OwnsRequest:->] else { disengage; }
    }

    can follow_request with VerifyRequest entry {
        visit [->:ReturnsResponse:->] else { disengage; }
    }

    can follow_response with Response entry {
        visit [->:ProducesEvaluation:->] else { disengage; }
    }

    can follow_evaluation with JudgeEvaluation entry {
        visit [->:ProjectsJudgeFields:->] else { disengage; }
    }

    can sanitize_projection with JudgePayload entry {
        if self.sanitized_fields == 0 {
            here.expected_text = sanitize_text(here.expected_text);
            here.generated_text = sanitize_text(here.generated_text);
            here.response_text = sanitize_text(here.response_text);
            here.parsed_output = sanitize_text(here.parsed_output);
            here.metadata = sanitize_text(here.metadata);
            here.tool_content = sanitize_text(here.tool_content);
            here.judge_response = sanitize_text(here.judge_response);
            here.failure_reason = sanitize_text(here.failure_reason);
            self.sanitized_fields += 8;
            print("sanitized only the projected judge and echo fields");
        }
    }
}

with entry {
    bad = "\\ud800";

    request = VerifyRequest(
        request_id="req-3036",
        expected_text="expected " + bad + " answer",
        generated_text="generated " + bad + " answer",
        token_ids=[1, 2, 3, 4]
    );

    response = Response(
        response_text="echo " + bad + " response",
        parsed_output="parsed " + bad + " output",
        metadata="metadata " + bad + " value",
        tool_content="tool " + bad + " content",
        token_ids=[10, 20, 30, 40]
    );

    evaluation = JudgeEvaluation(
        judge_response="judge " + bad + " response",
        failure_reason="failure " + bad + " reason",
        reward=1.0
    );

    projected = JudgePayload(
        expected_text=request.expected_text,
        generated_text=request.generated_text,
        response_text=response.response_text,
        parsed_output=response.parsed_output,
        metadata=response.metadata,
        tool_content=response.tool_content,
        judge_response=evaluation.judge_response,
        failure_reason=evaluation.failure_reason,
        reward=evaluation.reward
    );

    root +>:OwnsRequest:+> request;
    request +>:ReturnsResponse:+> response;
    response +>:ProducesEvaluation:+> evaluation;
    evaluation +>:ProjectsJudgeFields:+> projected;

    sanitizer = JudgeFieldSanitizer();
    root spawn sanitizer;
    print(f"projected field count: {sanitizer.sanitized_fields}");
}

"""CpuFrameTimings: between_frames must anchor at frame start, not after draw_frame."""

node TimingSpan {
    has label: str = "";
    has cost_ms: float = 0.0;
}

node FrameTick {
    has frame_id: int = 0;
}

edge InSequence { }

walker TimingAuditor {
    has frame_id: int = 0;
    has elapsed_since_redraw: float = 0.0;
    has between_frames_correct_ms: float = 0.0;
    has between_frames_buggy_ms: float = 0.0;
    has rof_pre_draw_ms: float = 0.0;
    has rof_draw_call_ms: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can open_frame with FrameTick entry {
        self.frame_id = here.frame_id;
        self.elapsed_since_redraw = 0.0;
        visit [->:InSequence:->] else { disengage; };
    }

    can walk_span with TimingSpan entry {
        if here.label == "frame_start" {
            self.between_frames_correct_ms = self.elapsed_since_redraw;
        } elif here.label == "rof_pre_draw" {
            self.rof_pre_draw_ms = here.cost_ms;
        } elif here.label == "rof_draw_call" {
            self.rof_draw_call_ms = here.cost_ms;
        } elif here.label == "post_draw_sample" {
            self.between_frames_buggy_ms = self.elapsed_since_redraw;
            absorbed = self.between_frames_buggy_ms - self.between_frames_correct_ms;
            render_sum = self.rof_pre_draw_ms + self.rof_draw_call_ms;
            buggy_verdict = "compositor" if self.between_frames_buggy_ms > 15.0 else "engine";
            fixed_verdict = "compositor" if self.between_frames_correct_ms > 15.0 else "engine_idle";
            print(f"frame {self.frame_id}: correct between_frames={self.between_frames_correct_ms} ms "
                  f"(captured at rof_pre_t0)");
            print(f"frame {self.frame_id}: buggy between_frames={self.between_frames_buggy_ms} ms "
                  f"(sampled after draw_frame returned)");
            print(f"frame {self.frame_id}: render path wrongly absorbed={absorbed} ms "
                  f"(rof_pre_draw+rof_draw_call={render_sum})");
            print(f"frame {self.frame_id}: buggy panel says '{buggy_verdict}'; "
                  f"fixed anchor says '{fixed_verdict}'");
        }
        self.elapsed_since_redraw += here.cost_ms;
        visit [->:InSequence:->] else { disengage; };
    }
}

with entry {
    tick = FrameTick(frame_id=901);
    root ++> tick;
    tick +>:InSequence:+> TimingSpan(label="idle_gap", cost_ms=12.0)
        +>:InSequence:+> TimingSpan(label="frame_start", cost_ms=0.0)
        +>:InSequence:+> TimingSpan(label="rof_pre_draw", cost_ms=4.5)
        +>:InSequence:+> TimingSpan(label="rof_draw_call", cost_ms=8.2)
        +>:InSequence:+> TimingSpan(label="post_draw_sample", cost_ms=0.0)
        +>:InSequence:+> TimingSpan(label="redraw_end_stamp", cost_ms=0.0);
    root spawn TimingAuditor();
}

"""Restaurant kitchen health inspection.

A patrol walker walks each station (grill, fryer, cold prep) and runs
two checks at every stop: a temperature safety audit (anything above 40 C
is a violation) and a visit log. A union ability keeps the inspection
behavior identical across station types.
"""

