"""Restaurant kitchen health inspection.

One inspector walker binds TWO abilities to the same trigger type
(``with KitchenStation entry``); both run in declaration order on every
station visit. The temperature check uses ``skip`` to leave just its
own ability early while the sibling logging ability still runs.
"""

node KitchenStation {
    has station: str;
    has temp_c: float;
}

walker HealthInspector {
    has violations: int = 0;
    has stops: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # First ability bound to KitchenStation entry.
    can check_temp with KitchenStation entry {
        if here.temp_c <= 40.0 {
            print(f"[temp] {here.station} ok ({here.temp_c} C)");
            skip;  # leave this ability only
        }
        self.violations += 1;
        print(f"[temp] {here.station} TOO WARM ({here.temp_c} C) -- violation");
    }

    # Second ability bound to the SAME trigger: still runs after skip.
    can log_stop with KitchenStation entry {
        self.stops += 1;
        print(f"[log] stop #{self.stops} recorded at {here.station}");
        visit [-->];
    }
}

with entry {
    grill = KitchenStation(station="grill", temp_c=38.0);
    fryer = KitchenStation(station="fryer", temp_c=47.5);
    coldprep = KitchenStation(station="cold prep", temp_c=35.0);
    root ++> grill ++> fryer ++> coldprep;

    inspector = HealthInspector();
    root spawn inspector;
    print(f"inspection done: {inspector.stops} stations visited, "
          f"{inspector.violations} violation(s)");
}

"""Versioned project templates.

Models SLIP-027: system templates are versioned and immutable; users
clone them into their own project tree via a walker that copies
structure and records template/version provenance. A reachability
walker also demonstrates cascade-invalidation behaviour: deleting a
template invalidates projects that were derived from it.
"""

node Project {
    has name: str = "";
    has kind: str = "";
    has derived_from: str = "";
    has derived_version: str = "";
    has valid: bool = True;
}

node Template {
    has name: str = "";
    has version: str = "";
    has immutable: bool = True;
}

node Task {
    has title: str = "";
    has done: bool = False;
}

edge Suggests { }
edge DerivesFrom { has version: str = ""; }

walker Templater {
    has owner_name: str = "";

    can start with Root entry {
        print(f"Templater '{self.owner_name}' is browsing system templates");
        visit [-->];
    }

    can pick with Template entry {
        print(f"  applying template {here.name} v{here.version} (immutable={here.immutable})");
        new_project = Project(
            name=self.owner_name + "-" + here.name,
            kind="templated",
            derived_from=here.name,
            derived_version=here.version
        );
        here +>:DerivesFrom(version=here.version):+> new_project;
        new_project spawn Copier(template_name=here.name, template_version=here.version);
        visit [-->];
    }

    can inspect with Project entry {
        status = "valid" if here.valid else "INVALIDATED";
        print(
            f"  project {here.name} kind={here.kind} [{status}] "
            f"from {here.derived_from}@{here.derived_version}"
        );
        visit [-->];
    }
}

walker Copier {
    has template_name: str = "";
    has template_version: str = "";

    can copy with Project entry {
        visit [->:Suggests:->];
    }

    can place with Task entry {
        copied = Task(title=here.title, done=False);
        here +>:Suggests:+> copied;
    }
}

walker ApplyAgain {
    has owner_name: str = "";

    can start with Root entry {
        for t in [-->] {
            if isinstance(t, Template) and t.name == "creator-content" {
                existing = [t->:DerivesFrom:->];
                if len(existing) > 0 {
                    print(
                        f"idempotent: '{self.owner_name}' already has "
                        f"{len(existing)} project(s) from creator-content; skipping re-apply"
                    );
                } else {
                    print(f"  re-applying creator-content for {self.owner_name}");
                    new_project = Project(
                        name=self.owner_name + "-" + t.name + "-redo",
                        kind="templated",
                        derived_from=t.name,
                        derived_version=t.version
                    );
                    t +>:DerivesFrom(version=t.version):+> new_project;
                }
            }
        }
        visit [-->];
    }
}

with entry {
    # Two immutable system templates at distinct versions.
    tpl_finite = Template(name="finite-client", version="1.0.0");
    tpl_creator_v1 = Template(name="creator-content", version="1.0.0");
    tpl_creator_v2 = Template(name="creator-content", version="1.2.0");

    # A template's suggested task structure (copied into a project on apply).
    root ++> tpl_finite ++> Task(title="brief")
        ++> Task(title="milestones")
        ++> Task(title="deliverables");
    root ++> tpl_creator_v1 ++> Task(title="outline")
        ++> Task(title="draft");
    root ++> tpl_creator_v2 ++> Task(title="outline")
        ++> Task(title="draft")
        ++> Task(title="publish");

    print("--- applying templates ---");
    root spawn Templater(owner_name="alice");

    print("--- idempotence check (re-apply creator-content) ---");
    ApplyAgain(owner_name="alice") spawn root;
}

"""Broadcast a restock order from several depots at once.

The dispatch hub keeps a list of depot nodes. Instead of walking from
each depot separately, the whole list is used as the query anchor:
one expression gathers every store reachable in one hop from any depot.
"""

node Depot {
    has name: str;
}

node Store {
    has name: str;
    has stock: int;
}

edge Serves {}

def low_stock(s: Store) -> bool {
    return s.stock < 20;
}

walker Dispatcher {
    can start with Root entry {
        depots = [-->][?:Depot];
        names = [d.name for d in depots];
        print(f"Anchoring from {len(depots)} depot(s): {names}");

        # A list of nodes anchors one combined query -- every depot's
        # neighbourhood composes into a single deduplicated result
        covered = [depots ->:Serves:->];
        print(f"Combined reach: {len(covered)} store visit slot(s)");

        needy = [s for s in covered if low_stock(s)];
        for s in needy {
            print(f"Restock needed at {s.name} (stock={s.stock})");
        }
        if not needy {
            print("All covered stores are fully stocked");
        }
    }
}

with entry {
    east = Depot(name="East Depot");
    west = Depot(name="West Depot");

    bakery = Store(name="Bakery Corner", stock=8);
    deli = Store(name="Deli Lane", stock=42);
    cafe = Store(name="Cafe Row", stock=15);

    east +>: Serves() :+> bakery;
    east +>: Serves() :+> deli;
    west +>: Serves() :+> deli;      # both depots cover Deli Lane
    west +>: Serves() :+> cafe;

    root ++> east;
    root ++> west;
    root spawn Dispatcher();
}

