"""Org-chart payroll rollup: bottom-up salary total and headcount for every manager.

Employees are nodes; the reports-to relationship is a typed edge.
A walker rooted at the CEO descends the tree once, accumulates each
subtree's payroll and headcount at its manager, then reports the
totals bottom-up.
"""

node Employee {
    has name: str = "";
    has salary: int = 0;
    has reports_total: int = 0;
    has headcount_total: int = 0;
}

edge ReportsTo {}

walker PayrollRollup {
    has salary_total: int = 0;
    has head_count: int = 0;

    can start with Root entry {
        # Find the CEO: the only employee with no incoming ReportsTo edge.
        ceo = [-->][?:Employee];
        visit ceo;
    }

    can rollup with Employee entry {
        subtree_salary = here.salary;
        subtree_headcount = 1;
        # Walk direct reports and roll each one up, then accumulate.
        if [->:ReportsTo:->] {
            for rep in [->:ReportsTo:->] {
                sub = PayrollRollup();
                rep spawn sub;
                subtree_salary = subtree_salary + sub.salary_total;
                subtree_headcount = subtree_headcount + sub.head_count;
            }
        }
        # Bottom-up: each manager's total includes their own compensation
        # plus the rolled-up totals of every report beneath them.
        here.reports_total = subtree_salary;
        here.headcount_total = subtree_headcount;
        self.salary_total = subtree_salary;
        self.head_count = subtree_headcount;
    }
}

walker Report {
    can start with Root entry {
        print("=== Payroll rollup (manager -> subtree payroll / headcount) ===");
        visit [-->];
    }

    can show with Employee entry {
        if here.reports_total > 0 or here.headcount_total > 0 {
            print(f"{here.name}: payroll=${here.reports_total}, "
                  f"headcount={here.headcount_total}");
        }
        visit [-->];
    }
}

with entry {
    # Sample org: CEO at the top, two VPs, four ICs reporting through them.
    ceo = Employee(name="CEO-Avery", salary=250000);
    vp_eng = Employee(name="VP-Eng-Bo", salary=180000);
    vp_sales = Employee(name="VP-Sales-Cara", salary=170000);
    ic1 = Employee(name="Eng-Dani", salary=120000);
    ic2 = Employee(name="Eng-Eli", salary=115000);
    ic3 = Employee(name="Sales-Fae", salary=95000);
    ic4 = Employee(name="Sales-Gus", salary=90000);

    root ++> ceo;
    ceo +>:ReportsTo:+> vp_eng;
    ceo +>:ReportsTo:+> vp_sales;
    vp_eng +>:ReportsTo:+> ic1;
    vp_eng +>:ReportsTo:+> ic2;
    vp_sales +>:ReportsTo:+> ic3;
    vp_sales +>:ReportsTo:+> ic4;

    # First pass: roll payroll + headcount up from the leaves.
    root spawn PayrollRollup();
    # Second pass: print each manager's totals.
    root spawn Report();
}

"""Mutual friendships in a small neighborhood: houses linked by buddy edges
that point both ways. Two greeter walkers spawn at each end and prove the
link is bidirectional using forward traversal only — with a cycle guard so
they cannot bounce back and forth forever."""

node House {
    has name: str = "";
    has color: str = "";
}

edge Buddy {
    has since: str = "";
}

walker Greeter {
    has visited: list[str] = [];
    has partner: str = "";

    can start with Root entry {
        visit [-->];
    }

    can greet with House entry {
        self.visited.append(here.name);
        print(f"Greeter arrived at {here.name} ({here.color})");

        # Cycle guard: forward-traverse along Buddy edges only to
        # neighbors we have not yet visited. This prevents bouncing
        # back and forth forever between the two houses.
        next_targets = [tgt for tgt in [-->] if tgt.name not in self.visited];
        if self.partner in self.visited {
            print(f"Greeter has reached partner '{self.partner}'; stopping here");
            disengage;
        }
        visit next_targets;
    }
}

with entry {
    blue_house = House(name="Blue House", color="blue");
    red_house = House(name="Red House", color="red");

    # Bidirectional buddy links created in a single statement: each
    # house points to the other through a Buddy edge.
    blue_house +>:Buddy(since="2018"):+> red_house;
    red_house +>:Buddy(since="2018"):+> blue_house;

    root ++> blue_house;
    root ++> red_house;

    # Spawn a greeter at each house; each is told which partner it
    # is looking for. Forward-only traversal along Buddy edges reaches
    # the other house in one hop, and the visited guard stops the loop.
    g1 = Greeter(partner="Red House");
    blue_house spawn g1;

    g2 = Greeter(partner="Blue House");
    red_house spawn g2;
}

"""Open-world product attribute relation extraction.

Models the core scenario from the issue: a product page exposes an arbitrary
catalog of key/value pairs across several DOM relation layouts (table rows,
definition lists, label/value spans). Fixed fields remain canonical while
relation rules extract long-tail attributes without requiring per-key selectors.

Demonstrates:
  * typed edges for relation layouts (TableRows, DefinitionList, LabelValue),
  * a walker that walks every relation rule and harvests raw key/value pairs,
  * backward compatibility: raw_attributes (closed-world) stay as-is.
"""

# ---------- Entity archetypes ----------

node RelationRule {
    has rule_name: str = "";
    has region_selector: str = "";
    has row_selector: str = "";
    has key_selector: str = "";
    has value_selector: str = "";
    has layout_kind: str = "";
}

node RawAttribute {
    has raw_key: str = "";
    has raw_values: list[str] = [];
    has section: str = "";
    has source_rule: str = "";
}

node FixedField {
    has field_name: str = "";
    has value: str = "";
}

node ProductPage {
    has url: str = "";
    has title: str = "";
}

# ---------- Typed edges ----------

edge AppliesTo {
    # RelationRule -> ProductPage region(s) it covers.
}

edge HarvestedFrom {
    # RawAttribute -> RelationRule it was extracted by.
}

edge HasFixedField {
    # ProductPage -> FixedField (closed-world canonical fields).
}

edge CoversLayout {
    # ProductPage -> RelationRule (the page declares it uses this layout).
}

# ---------- Walker: extract arbitrary attributes via relation rules ----------

walker AttributeHarvester {
    has page_url: str = "";
    has harvested: dict[str, list[str]] = {};
    has visited_rules: list[str] = [];

    can begin with Root entry {
        # Find the product page to start harvesting on.
        visit [-->];
    }

    can enter_page with ProductPage entry {
        self.page_url = here.url;
        print(f"Harvesting attributes from {here.url}");
        # First, walk the fixed fields (closed-world) and report them.
        visit [-->];
    }

    can collect_fixed with FixedField entry {
        print(f"  [fixed] {here.field_name} = {here.value}");
        visit [-->];
    }

    can dispatch_layout with RelationRule entry {
        # Cycle / revisit guard: jac 0.36.1 has no built-in once-per-node
        # visitation, so we keep an explicit list of rules we've already
        # processed on this walker.
        already = False;
        for name in self.visited_rules {
            if name == here.rule_name {
                already = True;
            }
        }
        if already {
            visit [-->];
        }
        self.visited_rules.append(here.rule_name);
        print(f"  [layout:{here.layout_kind}] rule={here.rule_name} "
              f"region={here.region_selector}");
        # Walk to the raw attributes produced by this rule.
        visit [-->];
    }

    can record_attribute with RawAttribute entry {
        # Section context preserved; raw key + raw values kept lossless.
        bucket = self.harvested.get(here.raw_key, []);
        for v in here.raw_values {
            bucket.append(v);
        }
        self.harvested[here.raw_key] = bucket;
        section_label = here.section if here.section else "(no section)";
        print(f"    + raw[{here.raw_key}] = {here.raw_values}  "
              f"src={here.source_rule} section={section_label}");
        visit [-->];
    }
}

# ---------- Walker: simulate a future page with an unseen label ----------

walker FuturePageCheck {
    has seen_keys: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can on_page with ProductPage entry {
        print(f"Future-page probe on {here.url}:");
        visit [-->];
    }

    can on_rule with RelationRule entry {
        # A future page that introduces a never-seen key still works because
        # the rule is layout-oriented, not label-oriented.
        print(f"  layout rule available: {here.rule_name} "
              f"({here.layout_kind}) -> any future label is accepted");
        visit [-->];
    }

    can on_attr with RawAttribute entry {
        self.seen_keys.append(here.raw_key);
        print(f"  harvested unseen key: {here.raw_key} = {here.raw_values}");
        visit [-->];
    }
}

# ---------- Demonstration graph ----------

with entry {
    page = ProductPage(url="https://example.com/guitar/42", title="Vintage Guitar");

    # Closed-world fixed fields (unchanged behavior).
    title_field = FixedField(field_name="title", value="Vintage Guitar");
    price_field = FixedField(field_name="price", value="1299.00");
    state_field = FixedField(field_name="state", value="used");

    # Three relation rules for the six recurring DOM layouts.
    table_rule = RelationRule(
        rule_name="spec_table",
        region_selector="table.product-specifications",
        row_selector="tr",
        key_selector="th",
        value_selector="td",
        layout_kind="table_rows"
    );

    dl_rule = RelationRule(
        rule_name="spec_dl",
        region_selector="dl.spec",
        row_selector="",
        key_selector="dt",
        value_selector="dd",
        layout_kind="definition_list"
    );

    lv_rule = RelationRule(
        rule_name="spec_label_value",
        region_selector="ul.attributes",
        row_selector="li",
        key_selector="span.label",
        value_selector="span.value",
        layout_kind="label_value"
    );

    # Raw attributes harvested (lossless: raw key + raw values + section).
    a1 = RawAttribute(
        raw_key="Resonanzbodenmaterial",
        raw_values=["Fichte"],
        section="Technical data",
        source_rule="spec_table"
    );
    a2 = RawAttribute(
        raw_key="Division",
        raw_values=["Scientific Instruments"],
        section="Provenance",
        source_rule="spec_dl"
    );
    a3 = RawAttribute(
        raw_key="photo-technology",
        raw_values=["Albumen print"],
        section="Photography",
        source_rule="spec_label_value"
    );

    # Wire the graph.
    root ++> page;
    page +>:HasFixedField:+> title_field;
    page +>:HasFixedField:+> price_field;
    page +>:HasFixedField:+> state_field;

    page +>:CoversLayout:+> table_rule;
    page +>:CoversLayout:+> dl_rule;
    page +>:CoversLayout:+> lv_rule;

    table_rule +>:AppliesTo:+> a1;
    dl_rule    +>:AppliesTo:+> a2;
    lv_rule    +>:AppliesTo:+> a3;

    # Spawn the harvester walker.
    harvester = AttributeHarvester();
    page spawn harvester;

    print("");
    print("Harvested open-world keys (raw, untranslated):");
    for (k, vs) in harvester.harvested.items() {
        print(f"  {k} -> {vs}");
    }

    # Future-page check: a page that uses the SAME layout but with unseen keys
    # must not require schema regeneration.
    print("");
    future = ProductPage(url="https://example.com/instrument/77",
                         title="Antique Barometer");
    future_rule_copy = RelationRule(
        rule_name="spec_table",
        region_selector="table.product-specifications",
        row_selector="tr",
        key_selector="th",
        value_selector="td",
        layout_kind="table_rows"
    );
    future_attr = RawAttribute(
        raw_key="Aneroid-Mechanismus",
        raw_values=["Quecksilber"],
        section="Technical data",
        source_rule="spec_table"
    );
    root ++> future;
    future +>:CoversLayout:+> future_rule_copy;
    future_rule_copy +>:AppliesTo:+> future_attr;

    probe = FuturePageCheck();
    future spawn probe;
    print(f"Unseen keys accepted on the future page: {probe.seen_keys}");
}

