"""Secure XML graph audit: reject multiple document roots and stop cyclic traversal."""

node XmlRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
}

node XmlParser(XmlRecord) {
    has strict: bool = True;
}

node XmlDocument(XmlRecord) {
    has root_count: int = 0;
    has valid: bool = True;
}

node XmlElement(XmlRecord) {
    has tag: str = "";
}

edge Uses {
    has purpose: str = "parse";
}

edge Produces {
    has parser_version: str = "";
}

edge Contains {
    has relation: str = "child";
}

walker XmlAuditor {
    has seen_keys: list[str] = [];

    can start with Root entry {
        visit [->:Uses:->] else {
            disengage;
        }
    }

    can inspect_parser with XmlParser entry {
        print(f"Auditing parser: {here.title}");
        visit [->:Produces:->] else {
            disengage;
        }
    }

    can inspect_document with XmlDocument entry {
        if here.root_count != 1 {
            here.valid = False;
            here.available = False;
            print(f"Rejected {here.title}: {here.root_count} top-level roots");
            disengage;
        }

        print(f"Accepted document: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_element with XmlElement entry {
        if here.key in self.seen_keys {
            print(f"Cycle detected at element {here.tag}; stopping this branch");
            disengage;
        }

        self.seen_keys.append(here.key);
        print(f"Visited element: <{here.tag}>");
        visit [->:Contains:->] else {
            disengage;
        }
    }
}

with entry {
    parser = XmlParser(
        title="xmldom-compatible parser",
        year=2024,
        strict=True
    );

    safe_doc = XmlDocument(
        title="safe.xml",
        year=2024,
        root_count=1
    );
    safe_root = XmlElement(
        key="safe-root",
        title="root",
        tag="root"
    );
    safe_child = XmlElement(
        key="safe-child",
        title="child",
        tag="child"
    );

    unsafe_doc = XmlDocument(
        title="malformed.xml",
        year=2024,
        root_count=2
    );
    first_root = XmlElement(
        key="first-root",
        title="first",
        tag="first"
    );
    second_root = XmlElement(
        key="second-root",
        title="second",
        tag="second"
    );

    root +>:Uses(purpose="XML parsing"):+> parser;
    parser +>:Produces(parser_version="0.6.0"):+> safe_doc;
    parser +>:Produces(parser_version="0.6.0"):+> unsafe_doc;

    safe_doc +>:Contains(relation="document element"):+> safe_root;
    safe_root +>:Contains(relation="child element"):+> safe_child;
    safe_child +>:Contains(relation="cycle probe"):+> safe_root;

    unsafe_doc +>:Contains(relation="first document element"):+> first_root;
    unsafe_doc +>:Contains(relation="second document element"):+> second_root;

    root spawn XmlAuditor();
}
