"""Confined validation-ownership probe with admitted sources and cycle detection."""

node Candidate {
    has name: str = "";
    has shell: str = "/trusted/interceptor";
    has variant_limit: int = 0;
    has probe_open: bool = False;
}

node ValidationTarget {
    has name: str = "";
    has owner: str = "";
    has semantic_fingerprint: str = "";
    has invalidated: bool = False;
}

node Source {
    has name: str = "";
    has declared: bool = False;
    has admitted: bool = False;
    has consumed: bool = False;
}

edge Owns {
    has target_kind: str = "";
}

edge DependsOn {
    has required: bool = True;
}

edge Reads {
    has declared_path: str = "";
}

walker OwnershipProbe {
    has remaining: int = 12;
    has seen: list[str] = [];
    has cycles: int = 0;
    has rejected: int = 0;
    has consumed: int = 0;

    can begin with Root entry {
        print("probe started with one aggregate budget");
        visit [-->] else { disengage; }
    }

    can inspect_candidate with Candidate entry {
        if self.remaining <= 0 {
            print("candidate rejected: aggregate budget exhausted");
            disengage;
        }
        self.remaining = self.remaining - 1;
        print(f"candidate {here.name} uses {here.shell}");
        if here.variant_limit > 4 {
            self.rejected = self.rejected + 1;
        }
        visit [->:Owns:->] else { disengage; }
    }

    can inspect_target with ValidationTarget entry {
        if self.remaining <= 0 {
            print("target rejected: aggregate budget exhausted");
            disengage;
        }
        self.remaining = self.remaining - 1;
        if here.invalidated {
            print(f"target {here.name} is invalidated");
        } else {
            print(f"owner {here.owner} -> {here.name} ({here.semantic_fingerprint})");
        }
        visit [->:DependsOn:->] else { disengage; }
    }

    can inspect_source with Source entry {
        if self.remaining <= 0 {
            print("source rejected: aggregate budget exhausted");
            disengage;
        }
        self.remaining = self.remaining - 1;

        if here.name in self.seen {
            self.cycles = self.cycles + 1;
            print(f"cycle rejected at source {here.name}");
            disengage;
        } else {
            self.seen.append(here.name);
            if here.declared == False or here.admitted == False {
                self.rejected = self.rejected + 1;
                print(f"source {here.name} rejected outside admitted set");
            } else {
                here.consumed = True;
                self.consumed = self.consumed + 1;
                print(f"source {here.name} consumed");
            }
            visit [->:Reads:->] else { disengage; }
        }
    }
}

with entry {
    candidate = Candidate(
        name="make-release",
        shell="/trusted/interceptor",
        variant_limit=2,
        probe_open=True
    );
    target = ValidationTarget(
        name="rom-check",
        owner="make-release",
        semantic_fingerprint="owner:rom-check"
    );
    source_a = Source(name="rules.mk", declared=True, admitted=True);
    source_b = Source(name="generated-registry.c", declared=True, admitted=False);

    root ++> candidate;
    candidate +>:Owns(target_kind="semantic"):+> target;
    target +>:DependsOn(required=True):+> source_a;
    source_a +>:Reads(declared_path="generated-registry.c"):+> source_b;
    source_b +>:Reads(declared_path="rules.mk"):+> source_a;

    root spawn OwnershipProbe();
}

"""PM seat dispatcher: modeled as nodes + typed edges with a patrol walker.

Models the domain:cli seat scenario from the issue as a small graph:
- Seat: who currently holds a lane, with capacity (ceiling 3) and tier.
- Card: an in-flight unit of work (PR / issue) with lane labels and a claim.
- Claim: a typed edge recording which session / identity claims which card.
- Audit: an inherited ledger (half-state anchor) holding patrol rows.

A patrol walker walks Claim edges from a seat, enforces the ceiling,
refuses identity-mismatched claims, and reports in-flight loads. A
cascade walker demonstrates the recursive invalidation the issue
complains about (hand-rolled recursion replaced by walker traversal).
"""

# ---------- Edge archetypes (relationships carry meaning) ----------

edge Claims {
    has session_id: str = "";
    has identity: str = "";
}

edge Lists {
    has label: str = "";
}

edge Anchors {
    has row_id: str = "";
}

# ---------- Node archetypes ----------

node Seat {
    has title: str = "";
    has lane: str = "";
    has holder: str = "";
    has ceiling: int = 3;
    has current_count: int = 0;
}

node Card {
    has title: str = "";
    has lane: str = "";
    has identity: str = "";
    has state: str = "queued";
    has needs_review: bool = False;
}

node Claim {
    has session_id: str = "";
    has identity: str = "";
}

node Ledger {
    has title: str = "";
}

# ---------- Walker: Patrol the seat ----------

walker Patrol {
    has seat_holder: str = "";
    has seat_lane: str = "";
    has ceiling: int = 3;
    has current_count: int = 0;
    has in_flight: list[str] = [];
    has refused: list[str] = [];

    can start with Root entry {
        # Visit every Seat node reachable from root via plain edges.
        visit [-->];
    }

    can seat_visit with Seat entry {
        self.seat_holder = here.holder;
        self.seat_lane = here.lane;
        self.ceiling = here.ceiling;
        self.current_count = 0;
        print(f"Patrol on seat '{here.title}' (lane={here.lane}, "
              f"holder={here.holder}, ceiling={here.ceiling})");
        # Walk outgoing Claims edges from this seat to its cards.
        visit [->:Claims:->];
    }

    can claim_visit with Claim entry {
        # The seat's own ability fires for Claim nodes reached via Claims edges.
        visit [->:Claims:->];
    }

    can card_visit with Card entry {
        # Identity-mismatch guard: the claiming identity MUST equal the
        # seat's holder (the issue's cross-account rule). If not, refuse.
        if here.identity != self.seat_holder {
            self.refused.append(here.title);
            print(f"  REFUSED card '{here.title}' — "
                  f"identity={here.identity} != seat={self.seat_holder}");
        } elif self.current_count >= self.ceiling {
            self.refused.append(here.title);
            print(f"  CEILING card '{here.title}' — at cap {self.ceiling}");
        } else {
            self.in_flight.append(here.title);
            self.current_count = self.current_count + 1;
            print(f"  ACCEPT card '{here.title}' (lane={here.lane})");
        }
        visit [-->];
    }
}

# ---------- Walker: Cascade-invalidate children (replaces manual recursion) ----------

walker CascadeInvalidate {
    has visited: set[str] = set();

    can start with Root entry {
        visit [-->];
    }

    can fan_out with Card entry {
        if here.title in self.visited {
            # Cycle policy: explicit guard, since walkers don't dedupe.
            return;
        }
        self.visited.add(here.title);
        here.state = "invalidated";
        print(f"Invalidated: {here.title}");
        visit [-->];
    }
}

# ---------- Walker: Half-state anchor scan ----------

walker AnchorScan {
    has matched: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can visit_ledger with Ledger entry {
        # Walk Anchors edges to read patrol rows attached to this anchor.
        visit [->:Anchors:->];
    }

    can visit_row with Card entry {
        # Record every card reachable through the anchor.
        self.matched.append(here.title);
        print(f"Anchor row -> card '{here.title}' lane={here.lane}");
        visit [-->];
    }
}

# ---------- Demonstration wiring ----------

with entry {
    # --- Seat: the domain:cli lane held by os-trump ---
    seat = Seat(
        title="PM seat",
        lane="domain:cli",
        holder="os-trump",
        ceiling=3
    );
    root ++> seat;

    # --- Cards: in-flight work, some claimed, some cross-account ---
    c1 = Card(title="#11925", lane="domain:cli", identity="os-zhuang");
    c2 = Card(title="#13149", lane="domain:cli", identity="os-trump",
              needs_review=True);
    c3 = Card(title="#13153", lane="domain:cli", identity="os-trump");
    c4 = Card(title="#9857",  lane="domain:cli", identity="os-trump");

    # --- Claims: typed edges recording session + identity ---
    seat +>:Claims(session_id="sess-A", identity="os-zhuang"):+> c1;
    seat +>:Claims(session_id="sess-B", identity="os-trump"):+> c2;
    seat +>:Claims(session_id="sess-C", identity="os-trump"):+> c3;
    seat +>:Claims(session_id="sess-D", identity="os-trump"):+> c4;

    # --- Anchor ledger: half-state anchor #9857 with patrol rows ---
    anchor = Ledger(title="anchor #9857");
    root ++> anchor;
    anchor +>:Anchors(row_id="H2"):+>  c1;
    anchor +>:Anchors(row_id="H34"):+> c1;
    anchor +>:Anchors(row_id="H6"):+>  c2;

    # --- Demo 1: Patrol walk ---
    print("=== Patrol ===");
    patrol = Patrol();
    seat spawn patrol;
    print(f"in_flight={patrol.in_flight} refused={patrol.refused}");

    # --- Demo 2: Cascade invalidation over a chain ---
    print("\n=== Cascade invalidate ===");
    chain_root = Card(title="root-card", lane="domain:cli", identity="os-trump");
    chain_root ++> (c2c := Card(title="child-A", lane="domain:cli",
