"""Recursive CTE: model WITH RECURSIVE as a walker that iterates a
working-table over a typed `Produces` edge until a depth guard or cycle
detection disengages. The walker simulates PostgreSQL's recursive
union: seed rows, then repeatedly derive new rows from prior ones."""

# A single row in the CTE working table. `n` is the column the query
# computes on; `depth` tracks the iteration index for safety bounds.
node Row {
    has n: int = 0;
    has depth: int = 0;
}

# The recursive derivation: a row points to the rows it produced on the
# next iteration. Typed edge because the parent/child link is the whole
# point of the working table.
edge Produces { has limit_n: int = 100; }

# The CTE binding `t(n)`. Owns the schema/depth cap; the recursive
# walker is spawned onto it to begin iteration.
node CTE {
    has name: str = "t";
    has max_depth: int = 100;
}

walker Iter {
    # Tracks rows already emitted so the walker doesn't loop forever on
    # a recursive query that never terminates (jac 0.36.1 has no
    # built-in visited-set, so the policy is explicit domain logic).
    has seen: list[int] = [];

    can start with Root entry {
        # Seed: VALUES (1). Build the first row and step into it.
        seed = Row(n=1, depth=0);
        root ++> seed;
        visit [-->];
    }

    can enter_cte with CTE entry {
        # Mirror the WHERE n < 100 stop condition via the typed edge's
        # `limit_n` payload. Cap the iteration by depth as well.
        if here.max_depth <= 0 {
            disengage;
        }
        visit [-->];
    }

    can step with Row entry {
        d = here.depth;
        # Domain rule from the issue: stop when the WHERE clause no
        # longer holds. PostgreSQL emits n+1 until n < 100 fails.
        if here.n >= 100 {
            disengage;
        }
        # Record this row's value so duplicate derivation terminates.
        self.seen.append(here.n);
        # Produce the next row: n+1, just like SELECT n+1 FROM t.
        nxt_n = here.n + 1;
        if nxt_n in self.seen {
            # Cycle detected by value: stop cleanly.
            disengage;
        }
        child = Row(n=nxt_n, depth=d + 1);
        here +>:Produces(limit_n=100):+> child;
        # Continue the recursive union into the new row.
        visit [->:Produces:->];
    }
}

walker SumResult {
    # Accumulates the running total as it walks the finished working
    # table. A single exit report keeps the contract tidy.
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can collect with Row entry {
        self.total += here.n;
        visit [-->];
    }

    can finish with Root exit {
        print(f"sum(n) = {self.total}");
    }
}

with entry {
    cte = CTE(name="t", max_depth=100);
    root ++> cte;

    Iter() spawn root;
    SumResult() spawn root;
}

"""Trust-model demo: artifacts with typed integrity/staleness attributes
linked by resolution dependencies; a walker audits the dependency graph
for cycles and reports a PACELC position per artifact.

Models the essential scenario from the AIKR CG kroftrust issue:
  - Artifacts carry {integrity, staleness_bound} as typed attributes.
  - Resolution dependency is a typed edge carrying PACELC + governance.
  - A walker performs dependency traversal (cycle-safe), gathers typed
    attributes, and reports a per-artifact resolution profile.
"""

# ---------- Edge archetypes ----------

# Resolution dependency: the source artifact depends on the target's
# resolution authority. Carries the PACELC position (PC/EC axes) and a
# governance/control label so technical and governance concerns are not
# conflated (issue §2).
edge Resolves {
    has pacelc: str = "PC/EC";        # "PC/EC" | "PA/EL" | "PC/EL" | "PA/EC"
    has governance: str = "self";      # "self" | "publisher" | "registry"
}

# Revision / supersession edge: artifact a is superseded by artifact b
# within a bounded-staleness window. Carries the staleness bound T.
edge Supersedes {
    has staleness_bound: str = "T";    # e.g. "24h", "7d"
}

# ---------- Node archetypes ----------

node Artifact {
    has name: str = "";
    has integrity: str = "content-addressed";  # "content-addressed" | "location-bound"
    has staleness_bound: str = "T";
    has pacelc: str = "";
    has governance: str = "";
}

# ---------- Walker ----------

walker DependencyAuditor {
    has seen: list[str] = [];
    has cycles: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        visit [-->];
    }

    can audit with Artifact entry {
        # Resolve this artifact's effective PACELC + governance: if it
        # has explicit fields use those, otherwise fall back to the
        # dependency-edge values carried by its first incoming edge.
        effective_pc = here.pacelc if here.pacelc != "" else "PC/EC";
        effective_gov = here.governance if here.governance != "" else "self";
        here.pacelc = effective_pc;
        here.governance = effective_gov;

        # Cycle policy: explicit guard set (jac 0.36.1 has no built-in
        # once-per-node visitation, so we maintain one on the walker).
        if here.name in self.seen {
            cycle_label = f"cycle at {here.name}";
            self.cycles.append(cycle_label);
            disengage;
        }
        self.seen.append(here.name);

        # Domain rule: depth cap preserved from source.
        if self.depth >= self.max_depth {
            disengage;
        }

        print(
            f"[{here.name}] integrity={here.integrity} "
            f"staleness<={here.staleness_bound} "
            f"pacelc={effective_pc} gov={effective_gov} "
            f"depth={self.depth}"
        );

        self.depth += 1;
        visit [->:Resolves:->];
    }
}

# ---------- Demonstration graph ----------

with entry {
    # Three artifacts forming a resolution chain.
    root_doc = Artifact(
        name="identity",
        integrity="content-addressed",
        staleness_bound="1h",
    );
    policy_doc = Artifact(
        name="policy",
        integrity="location-bound",
        staleness_bound="24h",
    );
    revocation_doc = Artifact(
        name="revocation",
        integrity="content-addressed",
        staleness_bound="7d",
    );

    # Resolution dependencies (typed, carrying PACELC + governance).
    root_doc +>:Resolves(pacelc="PC/EL", governance="self"):+> policy_doc;
    policy_doc +>:Resolves(pacelc="PA/EC", governance="publisher"):+> revocation_doc;

    # Supersession edge (bounded staleness): policy is superseded by
    # a newer policy within 24h of the swap.
    policy_doc +>:Supersedes(staleness_bound="24h"):+> revocation_doc;

    # Wire to root and spawn the auditor.
    root ++> root_doc ++> policy_doc ++> revocation_doc;
    root spawn DependencyAuditor();

    print(f"cycles detected: {DependencyAuditor().cycles}");
}

"""Dependency performance demo for a CAD document graph.

Models a nui4-style document where compile / evaluation must traverse a
graph of components connected by typed dependency edges. The walker
captures the recursive traversal the issue is about: dependency walk
with an explicit visited set (Jac 0.36.1 walkers have no built-in
once-per-node guarantee, so cycle policy is explicit), cascade
invalidation when a producer node is dirtied, and an order summary
on return to root.
"""

node Component {
    has name: str = "";
    has kind: str = "compute";
    has dirty: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

edge Owns { }

walker DependencyWalker {
    has visited: list[str] = [];
    has visit_order: list[str] = [];
    has cycle_found: bool = False;
    has invalidated: list[str] = [];

    can start with Root entry {
        print(f"== walking dependency graph from root ==");
        self.visited = [];
        self.visit_order = [];
        visit [->:DependsOn:->];
    }

    can visit_node with Component entry {
        if here.name in self.visited {
            cycle_label = f"cycle detected at {here.name}";
            self.cycle_found = True;
            print(cycle_label);
            disengage;
        }
        self.visited.append(here.name);
        self.visit_order.append(here.name);
        print(f"  -> component {here.name} ({here.kind})");
        if here.dirty {
            inv_label = f"invalidate:{here.name}";
            self.invalidated.append(inv_label);
            for anc_name in self.visited {
                cascade_label = f"cascade:{anc_name}";
                self.invalidated.append(cascade_label);
            }
        }
        visit [->:DependsOn:->];
    }

    can summarize with Root entry {
        joined = ", ".join(self.visit_order);
        print(f"visit order: {joined}");
        cycle_msg = "yes" if self.cycle_found else "no";
        print(f"cycle detected: {cycle_msg}");
        inv_count = len(self.invalidated);
        print(f"invalidations issued: {inv_count}");
    }
}

with entry {
    comp_a = Component(name="A", kind="source");
    comp_b = Component(name="B", kind="transform");
    comp_c = Component(name="C", kind="transform");
    comp_d = Component(name="D", kind="sink");

    root +>:Owns:+> comp_a;
    comp_a +>:DependsOn(weight=2):+> comp_b;
    comp_a +>:DependsOn(weight=1):+> comp_c;
    comp_b +>:DependsOn(weight=3):+> comp_d;
    comp_c +>:DependsOn(weight=2):+> comp_d;

    walker1 = DependencyWalker();
    root spawn walker1;

    comp_b.dirty = True;
    walker2 = DependencyWalker();
    root spawn walker2;
}

