"""DMC3 L3 resource-pool lifecycle: LoadedResource registry with typed
state transitions, loader-node ownership, and a quiescence walker that
verifies every record has settled to state0 or state3.

Models the canonical 363-record pool with seven groups, the central
state writers (acquisition -> state1 -> state2 -> state3, cancellation
state1/state2 -> state4, release resets to state0), and bounded
loader-node (kind, id) ownership above the registry. A QuiescenceAuditor
walker walks the registry and reports any record that violates the
quiescence predicate (`0x1401B84B0`): every record must be state0 or
state3. The Release walker exercises the three distinct state-zero
policies (deferred state4 cleanup, owner release, full reset).
"""

# --- Edge archetypes (typed relationships) --------------------------------

edge Owns {
    # Loader-node bounded ownership (claim++ / claim--) -- (kind, id) identity.
    has kind: str = "";
    has resource_id: int = 0;
}

edge Acquires {
    # Materialization seam: L2 provider identity -> L3 FileSlot ownership.
    has provider: str = "";
}

edge PostLoad {
    # Typed post-load dispatch path (MOD / EFM / SCM / SHW / PNST family).
    has family: str = "";
}

# --- Node archetypes -------------------------------------------------------

node LoadedResource {
    has title: str = "";          # debug name (slot label)
    has group: int = 0;           # group index 0..6 (seven groups)
    has state: int = 0;           # lifecycle: 0,1,2,3,4
    has available: bool = True;   # quiescence-eligible
}

node LoaderNode {
    has title: str = "";
    has kind: str = "";           # loader family (kind of (kind, id))
    has resource_id: int = 0;     # bounded identity
}

node FileSlot {
    has title: str = "";
    has backing: str = "";        # backing/owned subobject region
    has available: bool = True;
}

# --- Walkers ---------------------------------------------------------------

walker QuiescenceAuditor {
    has bad: list = [];

    can start with Root entry {
        print("QuiescenceAuditor: scanning registry");
        visit [-->];
    }

    can audit with LoadedResource entry {
        # Central quiescence predicate `0x1401B84B0`: state must be 0 or 3.
        if not (here.state == 0 or here.state == 3) {
            self.bad.append(here.title);
            print(f"  ! violation: {here.title} group={here.group} state={here.state}");
        }
        visit [-->];
    }
}

walker Release {
    has group_filter: int = -1;

    can start with Root entry {
        if self.group_filter >= 0 {
            print(f"Release: group-{self.group_filter} reset (state0 unconditional)");
        } else {
            print("Release: full 363-record reset (state0 unconditional)");
        }
        visit [-->];
    }

    can release with LoadedResource entry {
        # Three distinct state-zero policies, faithfully preserved.
        if self.group_filter >= 0 {
            if here.group == self.group_filter {
                here.state = 0;
                here.available = True;
            }
        } else {
            here.state = 0;
            here.available = True;
        }
        visit [-->];
    }
}

walker Acquire {
    has provider: str = "L2-unknown";
    has family: str = "MOD";

    can start with Root entry {
        print(f"Acquire: provider={self.provider} -> state1 via materialization seam");
        visit [-->];
    }

    can acquire with LoadedResource entry {
        # `0x1401B84E0` acquisition: state1 only on materialization success.
        if here.state == 0 {
            here.state = 1;
            print(f"  + acquired {here.title} -> state1");
        }
        visit [-->];
    }
}

# --- Demonstration wiring -------------------------------------------------

with entry {
    auditor = QuiescenceAuditor();

    # Three records spanning two groups; one starts mid-lifecycle to give
    # the auditor something to find.
    r0 = LoadedResource(title="slot_0", group=0, state=0);
    r1 = LoadedResource(title="slot_1", group=0, state=3);
    r2 = LoadedResource(title="slot_2", group=5, state=2);

    # Loader-node bounded ownership (claim++).
    loader = LoaderNode(title="loader_a", kind="MOD", resource_id=42);

    # FileSlot backing materialization.
    slot = FileSlot(title="fileslot_a", backing="region_a");

    # Typed edges carry meaning: who owns what, who acquires what, which
    # family path the typed post-load takes.
    loader +>:Owns(kind="MOD", resource_id=42):+> r1;
    root +>:Acquires(provider="L2-selected"):+> slot +>:PostLoad(family="MOD"):+> r0;
    r0 +>:PostLoad(family="MOD"):+> r1;
    r1 +>:PostLoad(family="MOD"):+> r2;

    print("--- Quiescence audit ---");
    root spawn auditor;
    print(f"violations: {auditor.bad}");

    print("--- Group-0 release (state0 unconditional for group 0) ---");
    root spawn Release(group_filter=0);
    auditor2 = QuiescenceAuditor();
    root spawn auditor2;
    print(f"violations: {auditor2.bad}");
}

