    has suggestions: list[str] = [];
}

edge Coauthored { has since: str = ""; }

walker SuggestContacts {
    has owner_name: str = "";
    has first_hop: list = [];
    has seen: dict = {};
    has results: list = [];
    has target: Researcher | None = None;

    can start with Root entry {
        if self.target is None {
            print("No researcher to suggest contacts for.");
            disengage;
        }
        visit [-->];
    }

    can land_on_target with Researcher entry {
        if self.target is None or here.name != self.target.name {
            visit [-->];
        } else {
            print(f"Suggesting contacts for {here.name}:");
            # First hop: gather direct co-authors to exclude later.
            self.first_hop = [];
            for person in self.first_hop {
                continue;
            }
            self.first_hop = [r.name for r in [->:Coauthored:->]];
            # Second hop: walk to co-authors of co-authors, collecting names.
            self.results = [];
            for direct in [->:Coauthored:->] {
                for second in [direct->:Coauthored:->] {
                    if second.name == here.name {
                        continue;
                    }
                    if second.name in self.first_hop {
                        continue;
                    }
                    if second.name in self.results {
                        continue;
                    }
                    self.results.append(second.name);
                }
            }
            print(f"  direct co-authors: {self.first_hop}");
            print(f"  suggested contacts (distance 2): {self.results}");
            disengage;
        }
    }
}

with entry {
