"""univers-ark-cli compile blast radius: model the monolithic command tree and
audit how much of it must be rebuilt when one command family changes.

Nodes:    CommandFamily (owns a library), Command (the leaf CLI surface)
Edges:    Owns (CommandFamily -> Command), Depends (Command -> Command)
Walker:   BuildAuditor walks the graph from root, counts cross-family deps
          and flags the cascade that would force a wide rebuild.
"""

node Command {
    has name: str = "";
    has is_schema_generated: bool = False;
    has owner_family: str = "";
}

node CommandFamily {
    has name: str = "";
    has library_name: str = "";
    has is_cli_assembly: bool = False;
}

edge Owns {
    has since: str = "";
}

edge Depends {
    has reason: str = "";
}

walker BuildAuditor {
    has visited_families: list[str] = [];
    has cross_family_edges: int = 0;
    has within_family_edges: int = 0;
    has schema_hits: int = 0;
    has audit_lines: list[str] = [];

    can start with Root entry {
        self.audit_lines.append("starting blast-radius audit");
        visit [->:Owns:->];
    }

    can descend with CommandFamily entry {
        if here.name in self.visited_families {
            self.audit_lines.append(
                f"cycle guard hit on family {here.name}; disengaging"
            );
            disengage;
        }
        self.visited_families.append(here.name);

        kind = "CLI assembly" if here.is_cli_assembly else "library";
        self.audit_lines.append(
            f"[{kind}] family={here.name} library={here.library_name}"
        );

        visit [->:Owns:->];
    }

    can classify with Command entry {
        if here.is_schema_generated {
            self.schema_hits += 1;
            self.audit_lines.append(
                f"  schema-generated command: {here.name}"
            );
        }

        current_family = self.visited_families[-1];
        edges = [here ->:Depends:->];
        for e in edges {
            target_owner = e.owner_family;
            if target_owner == current_family {
                self.within_family_edges += 1;
            } else {
                self.cross_family_edges += 1;
                self.audit_lines.append(
                    f"  CROSS-FAMILY dep: {here.name} -> "
                    f"(forces {target_owner} rebuild)"
                );
            }
        }

        visit [->:Depends:->];
    }

    can finish with Root entry {
        self.audit_lines.append("---");
        self.audit_lines.append(
            f"families audited: {len(self.visited_families)}"
        );
        self.audit_lines.append(
            f"within-family edges (cheap): {self.within_family_edges}"
        );
        self.audit_lines.append(
            f"cross-family edges (blast radius): {self.cross_family_edges}"
        );
        self.audit_lines.append(
            f"schema-generated commands: {self.schema_hits}"
        );

        for line in self.audit_lines {
            print(line);
        }
    }
}

with entry {
    cli = CommandFamily(
        name="cli", library_name="ark_cli", is_cli_assembly=True
    );
    ingest = CommandFamily(
        name="ingest", library_name="ark_ingest"
    );
    export = CommandFamily(
        name="export", library_name="ark_export"
    );

    root +>:Owns(since="v1"):+> cli;
    root +>:Owns(since="v1"):+> ingest;
    root +>:Owns(since="v1"):+> export;

    cmd_ingest_a = Command(
        name="ingest.run", is_schema_generated=True, owner_family="ingest"
    );
    cmd_ingest_b = Command(
        name="ingest.status", owner_family="ingest"
    );
    cmd_export_a = Command(
        name="export.to_parquet", is_schema_generated=True, owner_family="export"
    );
    cmd_export_b = Command(
        name="export.to_csv", owner_family="export"
    );
    cmd_cli_root = Command(
        name="ark", is_schema_generated=True, owner_family="cli"
    );

    cli +>:Owns(since="v1"):+> cmd_cli_root;
    ingest +>:Owns(since="v1"):+> cmd_ingest_a;
    ingest +>:Owns(since="v1"):+> cmd_ingest_b;
    export +>:Owns(since="v1"):+> cmd_export_a;
    export +>:Owns(since="v1"):+> cmd_export_b;

    cmd_ingest_a +>:Depends(reason="run-after"):+> cmd_ingest_b;
    cmd_export_a +>:Depends(reason="needs-data"):+> cmd_ingest_a;
    cmd_cli_root +>:Depends(reason="registers"):+> cmd_export_a;

    root spawn BuildAuditor();
}

