"""Semantic-closure audit: walk binding authority through manifestations and consumers."""

node Authority {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: str = "";
}

node Manifestation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has listed: bool = True;
}

node Consumer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has verified: bool = True;
}

edge Owns {
    has source: str = "";
}

edge Exposes {
    has surface: str = "";
}

edge ConsumedBy {
    has contract: str = "";
}

edge DependsOn {
    has order: int = 0;
}

walker ClosureAuditor {
    has seen: list[str] = [];
    has gaps: int = 0;
    has cycles: int = 0;

    can begin with Root entry {
        print("starting semantic-closure audit");
        visit [->:Owns:->] else { disengage; }
    }

    can audit_authority with Authority entry {
        if here.title in self.seen {
            self.cycles += 1;
            print(f"cycle detected at authority: {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        print(f"binding authority: {here.title} ({here.revision})");
        visit [->:Exposes:->] else { disengage; }
    }

    can audit_manifestation with Manifestation entry {
        if here.title in self.seen {
            self.cycles += 1;
            print(f"cycle detected at manifestation: {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        if here.listed {
            print(f"listed manifestation: {here.title}");
        } else {
            self.gaps += 1;
            print(f"closure gap: unlisted manifestation: {here.title}");
        }
        visit [->:ConsumedBy:->] else { disengage; }
    }

    can audit_consumer with Consumer entry {
        if here.title in self.seen {
            self.cycles += 1;
            print(f"cycle detected at consumer: {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        if here.verified and here.available {
            print(f"verified consumer: {here.title}");
        } else {
            self.gaps += 1;
            print(f"closure gap: stale consumer: {here.title}");
        }
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
    authority = Authority(
        title="Binding Contract",
        year=2025,
        revision="amended-r3"
    );
    api_surface = Manifestation(
        title="Store API",
        year=2025,
        listed=True
    );
    replay_surface = Manifestation(
        title="Replay API",
        year=2025,
        listed=False
    );
    writer = Consumer(
        title="Primary Writer",
        year=2025,
        verified=True
    );
    reader = Consumer(
        title="Replay Reader",
        year=2025,
        verified=False,
        available=False
    );

    root +>:Owns(source="issue-and-spec"):+> authority;
    authority +>:Exposes(surface="runtime"):+> api_surface;
    authority +>:Exposes(surface="replay"):+> replay_surface;
    api_surface +>:ConsumedBy(contract="store"):+> writer;
    replay_surface +>:ConsumedBy(contract="replay"):+> reader;
    writer +>:DependsOn(order=1):+> reader;
    reader +>:DependsOn(order=2):+> writer;

    root spawn ClosureAuditor();
}

"""DeepCopy cycle-safety demo: copy a self-referential document graph.

Models the oastools parser bug where generated DeepCopy recurses without
tracking already-copied nodes, overflowing the stack on cyclic documents.
A `CopyWalker` threads a visited map (source-pointer -> already-made copy)
through the traversal so a node reached twice returns its existing copy,
preserving cycle structure rather than just avoiding the crash.
"""

node Schema {
    has name: str = "";
    has children: list = [];
}

node Encoding {
    has name: str = "";
    has children: list = [];
}

node MediaType {
    has name: str = "";
    has children: list = [];
}

edge SchemaChild {}
edge EncodingChild {}
edge MediaEncoding {}

walker CopyWalker {
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can copy_schema with Schema entry {
        key = id(here);
        if key in self.visited {
            print(f"cycle hit on schema {here.name} -> reusing copy");
            return;
        }
        new_schema = Schema(name=here.name);
        self.visited[key] = new_schema;
        print(f"copying schema {here.name}");
        visit [->:SchemaChild:->];
    }

    can copy_encoding with Encoding entry {
        key = id(here);
        if key in self.visited {
            print(f"cycle hit on encoding {here.name} -> reusing copy");
            return;
        }
        new_enc = Encoding(name=here.name);
        self.visited[key] = new_enc;
        print(f"copying encoding {here.name}");
        visit [->:EncodingChild:->];
    }

    can copy_media with MediaType entry {
        key = id(here);
        if key in self.visited {
            print(f"cycle hit on media type {here.name} -> reusing copy");
            return;
        }
        new_mt = MediaType(name=here.name);
        self.visited[key] = new_mt;
        print(f"copying media type {here.name}");
        visit [->:MediaEncoding:->];
    }
}

walker RewriterWalker {
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can rewrite_schema with Schema entry {
        key = id(here);
        if key in self.visited {
            print(f"rewriter cycle-safe on schema {here.name}");
            return;
        }
        self.visited[key] = here.name;
        print(f"rewriting schema {here.name}");
        visit [->:SchemaChild:->];
    }

    can rewrite_encoding with Encoding entry {
        key = id(here);
        if key in self.visited {
            print(f"rewriter cycle-safe on encoding {here.name}");
            return;
        }
        self.visited[key] = here.name;
        print(f"rewriting encoding {here.name}");
        visit [->:EncodingChild:->];
    }

    can rewrite_media with MediaType entry {
        key = id(here);
        if key in self.visited {
            print(f"rewriter cycle-safe on media type {here.name}");
            return;
        }
        self.visited[key] = here.name;
        print(f"rewriting media type {here.name}");
        visit [->:MediaEncoding:->];
    }
}

with entry {
    # Repro 1: schema that references itself.
    s = Schema(name="RootSchema");
    s +>:SchemaChild:+> s;

    # Repro 2: encoding that references itself.
    e = Encoding(name="RootEncoding");
    e +>:EncodingChild:+> e;

    # Repro 3: media type whose encoding reaches the cyclic encoding.
    mt = MediaType(name="RootMediaType");
    mt +>:MediaEncoding:+> e;

    print("--- DeepCopy traversal (cycle-safe via visited map) ---");
    copier = CopyWalker();
    root spawn copier;

    print("\n--- Rewriter traversal (matches copy semantics) ---");
    rewriter = RewriterWalker();
    root spawn rewriter;
}

