"""Frontier propagation across loop iterations.

Models the compiler bug from impulse-graph/impulse-graph-java #4:
fixed-point traversal loops statically bind their input register to the
initial seed, so every iteration re-walks from $R_0 instead of advancing
from $R_1.  The walkers below perform explicit fixed-point expansion
along ``Follows`` edges, accumulating newly-discovered nodes and feeding
the next frontier forward, until a closure step produces no new members.
Two flavors are demonstrated side-by-side:

* ``RepeatUntilStableBuggy`` — naive re-walk from the seed every iteration
  (terminates after one hop, exactly like the broken compiler).
* ``RepeatUntilStableFixed`` — register-forwarding accumulator that
  carries the frontier forward (matches the proposed fix).
"""

node Step {
    has name: str = "";
    has visited: bool = False;
    has hop: int = 0;
}

edge Follows { }

walker RepeatUntilStableBuggy {
    has max_hops: int = 10;
    has trace: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # Statically bound to the seed frontier every iteration — the bug.
    can buggy_loop with Step entry {
        i = 0;
        while i < self.max_hops {
            i += 1;
            fresh = [here];
            for n in fresh {
                if not n.visited {
                    n.visited = True;
                    n.hop = i;
                    self.trace.append(f"buggy hop={i} reached {n.name}");
                    visit [->:Follows:->];
                }
            }
            if i >= 2 {
                self.trace.append("buggy: terminated after hop 1 (frontier never advanced)");
                disengage;
            }
        }
    }
}

walker RepeatUntilStableFixed {
    has max_hops: int = 10;
    has trace: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can fixed_loop with Step entry {
        frontier = [here];
        i = 0;
        while frontier and i < self.max_hops {
            i += 1;
            next_frontier = [];
            for n in frontier {
                if not n.visited {
                    n.visited = True;
                    n.hop = i;
                    self.trace.append(f"fixed hop={i} reached {n.name}");
                }
            }
            # Register-forwarding: feed this iteration's destinations in
            # as the next iteration's sources.
            for n in frontier {
                next_frontier.extend([e for e in [n-->] if not e.visited]);
            }
            frontier = next_frontier;
        }
        if not frontier {
            self.trace.append(f"fixed: stable after hop {i} (frontier exhausted)");
        }
    }
}

walker Reachability {
    has target: str = "";
    has found: bool = False;
    has trace: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can climb with Step entry {
        if here.name == self.target {
            self.found = True;
            self.trace.append(f"reachable: {here.name}");
            disengage;
        }
        visit [->:Follows:->];
    }
}

with entry {
    # Linear DAG: A -> B -> C -> D
    a = Step(name="A");
    b = Step(name="B");
    c = Step(name="C");
    d = Step(name="D");
    a +>:Follows:+> b;
    b +>:Follows:+> c;
    c +>:Follows:+> d;

    # Cycle: E -> F -> E  (also reachable from D)
    e = Step(name="E");
    f = Step(name="F");
    e +>:Follows:+> f;
    f +>:Follows:+> e;
    d +>:Follows:+> e;

    print("=== repeatUntilStable (buggy: static seed) ===");
    buggy = RepeatUntilStableBuggy();
    a spawn buggy;
    for line in buggy.trace {
        print(line);
    }

    # Fresh nodes for the fixed walker so we get a clean trace.
    a2 = Step(name="A");
    b2 = Step(name="B");
    c2 = Step(name="C");
    d2 = Step(name="D");
    e2 = Step(name="E");
    f2 = Step(name="F");
    a2 +>:Follows:+> b2;
    b2 +>:Follows:+> c2;
    c2 +>:Follows:+> d2;
    d2 +>:Follows:+> e2;
    e2 +>:Follows:+> f2;
    f2 +>:Follows:+> e2;

    print("\n=== repeatUntilStable (fixed: register-forwarding accumulator) ===");
    fixed = RepeatUntilStableFixed();
    a2 spawn fixed;
    for line in fixed.trace {
        print(line);
    }

    print("\n=== reachability probe for 'E' on the cyclic branch ===");
    probe = Reachability(target="E");
    a2 spawn probe;
    print(f"found={probe.found}");
    for line in probe.trace {
        print(line);
    }
}
