"""Retrospective draft review with typed relationships and cycle-safe walkers."""

node Retrospective {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stage: str = "DISCUSS";
    has facilitator_name: str = "";
}

node ReviewItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has review_id: str = "";
    has kind: str = "DECISION";
    has review_status: str = "DRAFT";
    has review_decision: str = "HOLD";
    has owner_name: str = "";
    has due_date: str = "";
    has topic: str = "";
    has source: str = "";
}

node Participant {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
}

edge Contains {
    has position: int = 0;
}

edge FacilitatedBy {
    has role: str = "cycle-facilitator";
}

edge OwnedBy {
    has role: str = "project-member";
}

edge RelatedDraft {
    has relation: str = "extracted-neighbor";
}

walker FacilitatorReview {
    has facilitator_name: str = "";
    has seen_ids: list[str] = [];
    has accepted_count: int = 0;
    has rejected_count: int = 0;
    has unresolved_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can open with Retrospective entry {
        if (self.facilitator_name != here.facilitator_name) {
            print("review denied: facilitator mismatch");
            disengage;
        }
        if (here.stage != "DISCUSS") {
            print("review denied: retrospective is not in DISCUSS");
            disengage;
        }
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can review with ReviewItem entry {
        if (here.review_id in self.seen_ids) {
            print(f"cycle skipped at {here.review_id}");
            return;
        }
        self.seen_ids.append(here.review_id);

        if (here.review_status != "DRAFT") {
            print(f"{here.review_id} already resolved");
        } elif (here.kind == "ACTION" and here.owner_name == "") {
            print(f"{here.review_id} remains DRAFT: owner required");
            self.unresolved_count += 1;
            return;
        } elif (here.review_decision == "REJECT") {
            print(f"rejecting and deleting {here.review_id}");
            self.rejected_count += 1;
            del here;
            return;
        } else {
            here.review_status = "CONFIRMED";
            self.accepted_count += 1;
            print(f"confirmed {here.review_id} from {here.source}");
        }

        visit [->:RelatedDraft:->] else {
            disengage;
        }
    }
}

walker OwnershipAudit {
    has member_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can scan with Retrospective entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can check with ReviewItem entry {
        if (here.review_status == "CONFIRMED" and here.owner_name != "") {
            visit [->:OwnedBy:->] else {
                disengage;
            }
        }
    }

    can verify with Participant entry {
        self.member_count += 1;
        print(f"confirmed owner: {here.name}");
    }
}

with entry {
    retrospective = Retrospective(
        title="Sprint 18 retrospective",
        year=2025,
        facilitator_name="Ari"
    );

    facilitator = Participant(
        title="Cycle facilitator Ari",
        name="Ari"
    );
    mina = Participant(
        title="Project member Mina",
        name="Mina"
    );

    decision = ReviewItem(
        title="Adopt smaller releases",
        review_id="D-1",
        kind="DECISION",
        review_decision="ACCEPT",
        source="transcript:42"
    );
    action = ReviewItem(
        title="Publish release checklist",
        review_id="A-1",
        kind="ACTION",
        review_decision="ACCEPT",
        owner_name="Mina",
        due_date="2025-06-30",
        topic="release process",
        source="transcript:57"
    );
    summary = ReviewItem(
        title="The team wants safer releases",
        review_id="S-1",
        kind="SUMMARY",
        review_decision="ACCEPT",
        source="generated-summary"
    );
    unassigned = ReviewItem(
        title="Document rollback steps",
        review_id="A-2",
        kind="ACTION",
        review_decision="ACCEPT",
        topic="release process",
        source="transcript:61"
    );
    rejected = ReviewItem(
        title="Skip all release checks",
        review_id="D-2",
        kind="DECISION",
        review_decision="REJECT",
        source="transcript:64"
    );

    root ++> retrospective;
    retrospective +>:FacilitatedBy(role="assigned-facilitator"):+> facilitator;
    retrospective +>:Contains(position=1):+> decision;
    retrospective +>:Contains(position=2):+> action;
    retrospective +>:Contains(position=3):+> summary;
    retrospective +>:Contains(position=4):+> unassigned;
    retrospective +>:Contains(position=5):+> rejected;

    action +>:OwnedBy(role="project-member"):+> mina;

    decision +>:RelatedDraft(relation="supports"):+> action;
    action +>:RelatedDraft(relation="summarizes"):+> summary;
    summary +>:RelatedDraft(relation="originates-from"):+> decision;

    reviewer = root spawn FacilitatorReview(facilitator_name="Ari");
    auditor = root spawn OwnershipAudit();

    print(
        f"accepted={reviewer.accepted_count}, "
        f"rejected={reviewer.rejected_count}, "
        f"unresolved={reviewer.unresolved_count}, "
        f"owners_checked={auditor.member_count}"
    );
}
