"""Bun version policy propagation across CI, release, and Docker consumers.

Models the issue's core scenario: a single declared Bun version is the
authoritative policy. Workflow jobs and Docker consumers reference that
policy through typed edges rather than each repeating the literal value,
so any deliberate bump propagates by editing one place. A walker audits
every consumer to verify each one asserts the exact expected version.
"""

node BunVersionPolicy {
    has expected_version: str = "1.3.14";
    has declared_at: str = "ralphie-issue-129";
}

node WorkflowFile {
    has path: str = "";
    has job_name: str = "";
    has asserts_version: bool = False;
    has observed_version: str = "";
}

node DockerConsumer {
    has image_name: str = "";
    has base_image: str = "";
    has observed_version: str = "";
}

edge PinsBun {
    has source: str = "policy";
}

walker BunPolicyAuditor {
    has expected: str = "1.3.14";
    has drift_count: int = 0;
    has checked: int = 0;

    can start with Root entry {
        print("Auditing Bun policy graph");
        visit [->:PinsBun:->];
    }

    can audit_policy with BunVersionPolicy entry {
        self.expected = here.expected_version;
        print(f"Policy declares expected_version = {here.expected_version}");
        visit [->:PinsBun:->];
    }

    can audit_workflow with WorkflowFile entry {
        self.checked += 1;
        if here.asserts_version and here.observed_version != self.expected {
            print(f"DRIFT in {here.path}::{here.job_name}: "
                  f"expected {self.expected}, got {here.observed_version}");
            self.drift_count += 1;
        } else {
            status = "ok" if here.asserts_version else "unverified";
            print(f"  {here.path}::{here.job_name} -> {status}");
        }
    }

    can audit_docker with DockerConsumer entry {
        self.checked += 1;
        if here.observed_version != self.expected {
            print(f"DRIFT in docker {here.image_name}: "
                  f"expected {self.expected}, got {here.observed_version}");
            self.drift_count += 1;
        } else {
            print(f"  docker {here.image_name} -> ok ({here.base_image})");
        }
    }
}

with entry {
    policy = BunVersionPolicy(
        expected_version="1.3.14",
        declared_at="ralphie-issue-129"
    );

    ci_test = WorkflowFile(
        path=".github/workflows/ci.yml",
        job_name="test",
        asserts_version=True,
        observed_version="1.3.14"
    );

    ci_lint = WorkflowFile(
        path=".github/workflows/ci.yml",
        job_name="lint",
        asserts_version=True,
        observed_version="1.3.14"
    );

    release_build = WorkflowFile(
        path=".github/workflows/release.yml",
        job_name="build",
        asserts_version=True,
        observed_version="1.3.14"
    );

    release_publish = WorkflowFile(
        path=".github/workflows/release.yml",
        job_name="publish",
        asserts_version=True,
        observed_version="1.3.14"
    );

    docker_runtime = DockerConsumer(
        image_name="ralphie-runtime",
        base_image="oven/bun:1.3.14-distroless",
        observed_version="1.3.14"
    );

    policy +>:PinsBun:+> ci_test;
    policy +>:PinsBun:+> ci_lint;
    policy +>:PinsBun:+> release_build;
    policy +>:PinsBun:+> release_publish;
    policy +>:PinsBun:+> docker_runtime;

    root spawn BunPolicyAuditor();
}

