"""Docker retention policy on a shared VPS.

Models the core entities from issue #613: the host's disk pressure, the
running production release, the verified rollback release, the Preview
images, the BuildKit cache, and unrelated workloads.  A Reaper walker
performs the fail-closed retention sweep that the issue requires:
protect the running release, the rollback release, every container's
referenced image, every active Preview, and everything unrelated to
Project Space, then evict only what's truly stale.
"""

node Host {
    has name: str = "";
    has total_gib: float = 0.0;
    has used_gib: float = 0.0;

    def pct_used() -> float {
            pct = (self.used_gib / self.total_gib) * 100.0;
            return pct;
        }
}

node Image {
    has tag: str = "";
    has size_gib: float = 0.0;
    has active: bool = False;
    has preview: bool = False;
    has project_space: bool = False;
    has last_used_days: int = 999;
}

node Container {
    has name: str = "";
    has running: bool = False;
}

node Cache {
    has label: str = "";
    has size_gib: float = 0.0;
    has age_days: int = 0;
}

edge Disk { }
edge Repo { }
edge ContainerRef { }
edge CacheRef { }
edge ProtectedBy { }

walker Reaper {
    has protected_tags: list[str] = [];
    has evicted_gib: float = 0.0;
    has protected_count: int = 0;
    has evicted_count: int = 0;
    has warnings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can survey with Host entry {
        pct = here.pct_used();
        if pct >= 90.0 {
            self.warnings.append(f"CRITICAL disk {pct:.1f}%");
        } elif pct >= 80.0 {
            self.warnings.append(f"WARNING disk {pct:.1f}%");
        } elif pct >= 70.0 {
            self.warnings.append(f"NOTICE disk {pct:.1f}%");
        }
        visit [->:Repo:->];
    }

    can audit_image with Image entry {
        tag = here.tag;
        guarded = False;
        for keep in self.protected_tags {
            if keep == tag {
                guarded = True;
            }
        }
        if here.active {
            guarded = True;
        }
        if here.preview and here.last_used_days <= 7 {
            guarded = True;
        }
        if not here.project_space {
            guarded = True;
        }
        if guarded {
            self.protected_count += 1;
        } else {
            self.evicted_gib += here.size_gib;
            self.evicted_count += 1;
            here.active = False;
        }
        visit [-->];
    }

    can audit_container with Container entry {
        visit [->:ContainerRef:->];
    }

    can audit_cache with Cache entry {
        if here.age_days > 14 or here.size_gib > 30.0 {
            self.evicted_gib += here.size_gib;
            self.evicted_count += 1;
        }
        visit [-->];
    }
}

with entry {
    host = Host(name="os-vps", total_gib=465.0, used_gib=458.0);

    running = Image(tag="web:097d42d", size_gib=1.3, active=True,
                     project_space=True, last_used_days=0);
    rollback = Image(tag="web:8a31f02", size_gib=1.3, project_space=True,
                      last_used_days=2);
    fresh_preview = Image(tag="web:pr-481", size_gib=1.4, preview=True,
                           project_space=True, last_used_days=1);
    stale_preview = Image(tag="web:pr-312", size_gib=1.5, preview=True,
                           project_space=True, last_used_days=42);
    old_release = Image(tag="web:5e7a910", size_gib=1.4, project_space=True,
                         last_used_days=90);
    unrelated = Image(tag="postgres:16", size_gib=0.4, project_space=False,
                       last_used_days=3);

    web = Container(name="project-space-web", running=True);
    docs = Container(name="project-space-docs", running=True);

    cache_good = Cache(label="web-build", size_gib=10.0, age_days=3);
    cache_stale = Cache(label="docs-build", size_gib=36.6, age_days=60);

    root +>:Disk:+> host;
    host +>:Repo:+> running;
    host +>:Repo:+> rollback;
    host +>:Repo:+> fresh_preview;
    host +>:Repo:+> stale_preview;
    host +>:Repo:+> old_release;
    host +>:Repo:+> unrelated;
    host +>:ContainerRef:+> web;
    host +>:ContainerRef:+> docs;
    host +>:CacheRef:+> cache_good;
    host +>:CacheRef:+> cache_stale;
    web +>:ProtectedBy:+> running;
    docs +>:ProtectedBy:+> rollback;

    reaper = Reaper(
        protected_tags=["web:097d42d", "web:8a31f02"]
    );
    root spawn reaper;

    print(f"disk pct = {host.pct_used():.1f}%");
    print(f"protected: {reaper.protected_count}, "
          f"evicted: {reaper.evicted_count}, "
          f"reclaimed GiB: {reaper.evicted_gib:.1f}");
    for w in reaper.warnings {
        print(f"  {w}");
    }
    print(f"running preserved: {running.active}, "
          f"rollback preserved: {not (rollback.tag == '')}, "
          f"unrelated preserved: {not (unrelated.tag == '')}, "
          f"stale preview evicted: {not stale_preview.active}");
}
