"""Level authoring validation: model a Godot-like location hierarchy.

Mirrors the validation exercise: a Location contains rooms; each room contains
furniture; a furniture prefab is an inherited scene whose children must not
be promoted to construction-part siblings. A repairable authoring error is
modeled as a dangling reference (a furniture pointing at a prefab that does
not exist in the registry) and the warning clears once it is repaired.
"""

node Prefab {
    has name: str = "";
}

node Furniture {
    has name: str = "";
    has placed: bool = True;
    has prefab_ref: str = "";
}

node Room {
    has name: str = "";
}

node Location {
    has title: str = "";
}

edge ContainsRoom {}
edge ContainsFurniture {}
edge VariantOf {}

walker Inspector {
    has path: list[str] = [];

    can start with Root entry {
        print(f"=== hierarchy walk ===");
        visit [-->];
    }

    can visit_location with Location entry {
        self.path.append(here.title);
        print(f"location: {here.title}");
        visit [->:ContainsRoom:->];
    }

    can visit_room with Room entry {
        print(f"  room: {here.name}");
        visit [->:ContainsFurniture:->];
    }

    can visit_furniture with Furniture entry {
        marker = "OK" if here.prefab_ref != "" else "WARN: no prefab";
        print(f"    furniture: {here.name}  prefab={here.prefab_ref} [{marker}]");
    }
}

walker VariantChecker {
    can start with Root entry {
        print(f"=== variant isolation check ===");
        visit [->:VariantOf:->];
    }

    can check_variant with Furniture entry {
        print(f"variant {here.name} anchored to base prefab '{here.prefab_ref}'");
    }
}

walker RepairAuditor {
    can start with Root entry {
        print(f"=== repairable authoring-error audit ===");
        visit [-->];
    }

    can scan_location with Location entry {
        visit [->:ContainsRoom:->];
    }

    can scan_room with Room entry {
        visit [->:ContainsFurniture:->];
    }

    can scan_furniture with Furniture entry {
        if here.prefab_ref == "" {
            print(f"[WARN] {here.name} in current room has no prefab reference");
        } else {
            print(f"[OK]   {here.name} -> prefab '{here.prefab_ref}'");
        }
    }
}

with entry {
    sofa_prefab = Prefab(name="sofa_prefab");
    radio_prefab = Prefab(name="radio_prefab");

    loc = Location(title="Bunker");
    root ++> loc;

    spawn_room = Room(name="spawn_kitchen");
    radio_room = Room(name="radio_room");
    loc +>:ContainsRoom:+> spawn_room;
    loc +>:ContainsRoom:+> radio_room;

    f1 = Furniture(name="kitchen_table", prefab_ref="table_prefab");
    f2 = Furniture(name="radio_set",     prefab_ref="radio_prefab");
    f3 = Furniture(name="broken_chair",  prefab_ref="");
    spawn_room +>:ContainsFurniture:+> f1;
    spawn_room +>:ContainsFurniture:+> f3;
    radio_room  +>:ContainsFurniture:+> f2;

    variant = Furniture(name="radio_set_variant", prefab_ref="radio_prefab");
    root +>:VariantOf:+> variant;

    root spawn Inspector();
    root spawn VariantChecker();
    root spawn RepairAuditor();

    print("=== fix: assign a real prefab to the broken chair ===");
    f3.prefab_ref = "chair_prefab";
    root spawn RepairAuditor();
}

