    can tour with Grove entry {
        print(f"Entering grove: {here.grove_name}");
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        device_kind = here.kind;
        idle = here.idle_hours;
        here.idle_hours = 0;
        self.serviced += 1;
        print(f"[SERVICED] kind={device_kind}, idle_hours={idle}, counter reset, total serviced={self.serviced}");
        visit [-->];
    }
}

with entry {
