    north ++> Pump(idle_hours=14);
    north ++> Pump(idle_hours=3);
    north ++> Sprinkler(idle_hours=22);
    south ++> Sprinkler(idle_hours=7);
    south ++> Sprinkler(idle_hours=11);
    south ++> Pump(idle_hours=5);

