"""A worker degrades cleanly when a VFS watcher cannot initialize."""

node Worker {
    has title: str = "";
    has running: bool = True;
}

node Project {
    has title: str = "";
    has live_sync_enabled: bool = True;
    has db_flusher_running: bool = True;
}

node VfsWatcher {
    has title: str = "";
    has enabled: bool = True;
    has registered: bool = True;
    has failure_reason: str = "";
}

node Directory {
    has title: str = "";
    has path: str = "";
    has available: bool = True;
}

edge Owns { }
edge HasWatcher { }
edge Watches { }
edge Contains { }

walker WatcherAudit {
    has seen_paths: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect_worker with Worker entry {
        if here.running {
            print(f"worker {here.title} is running");
        } else {
            print(f"worker {here.title} is stopped");
        }
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect_project with Project entry {
        if here.live_sync_enabled {
            print(f"project {here.title}: live DBFS sync enabled");
        } else {
            print(f"project {here.title}: live DBFS sync disabled; DB flusher remains running={here.db_flusher_running}");
        }
        visit [->:HasWatcher:->] else {
            disengage;
        }
    }

    can inspect_watcher with VfsWatcher entry {
        if here.enabled {
            print(f"watcher {here.title} initialized");
            visit [->:Watches:->] else {
                disengage;
            }
        } else {
            print(f"watcher {here.title} failed with {here.failure_reason}; registered={here.registered}; skipping live walk");
        }
    }

    can walk_directory with Directory entry {
        if here.path in self.seen_paths {
            print(f"cycle detected at {here.path}; stopping this walk safely");
            disengage;
        } else {
            self.seen_paths.append(here.path);
            print(f"watching {here.path}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }
}

with entry {
    worker = Worker(title="carbide-worker");
    failed_project = Project(
        title="broken-vfs-project",
        live_sync_enabled=False,
        db_flusher_running=True
    );
    failed_watcher = VfsWatcher(
        title="broken-watcher",
        enabled=False,
        registered=False,
        failure_reason="ENOSPC"
    );
    healthy_project = Project(title="healthy-vfs-project");
    healthy_watcher = VfsWatcher(title="healthy-watcher");
    root_directory = Directory(title="root", path="/workspace");
    nested_directory = Directory(title="cache", path="/workspace/cache");

    root ++> worker;
    worker +>:Owns:+> failed_project;
    worker +>:Owns:+> healthy_project;
    failed_project +>:HasWatcher:+> failed_watcher;
    healthy_project +>:HasWatcher:+> healthy_watcher;
    healthy_watcher +>:Watches:+> root_directory;
    root_directory +>:Contains:+> nested_directory;
    nested_directory +>:Contains:+> root_directory;

    root spawn WatcherAudit();
}
