"""Build-system dependency audit.

A walker traverses a dependency graph that contains diamonds (shared
libraries needed by multiple modules). Each ``Task`` node represents a
build step with a cost in minutes. A task reachable by several paths
must still be counted exactly once: the walker carries an explicit
guard set so that revisiting a node does not double-count it.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has available: bool = True;
}

edge DependsOn {}

walker BuildAuditor {
    has total_minutes: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        print(f"Auditing build graph from root");
        visit [-->];
    }

    can audit with Task entry {
        # Cycle / diamond policy: explicit guard set on the walker.
        if here.title in self.visited {
            print(f"[skip] {here.title} already audited");
            visit [-->];
            return;
        }
        self.visited.append(here.title);

        label = "OK" if here.available else "STALE";
        print(f"[{label}] {here.title} (+{here.minutes} min)");
        self.total_minutes = self.total_minutes + here.minutes;
        visit [-->];
    }
}

with entry {
    # Diamond shape:
    #   compile_core -> link_ui, link_db -> bundle_app
    # `link_common` is reached by both link_ui and link_db.
    link_common = Task(title="link_common", minutes=4);
    compile_core = Task(title="compile_core", minutes=10);
    link_ui = Task(title="link_ui", minutes=6);
    link_db = Task(title="link_db", minutes=6);
    bundle_app = Task(title="bundle_app", minutes=8);
    test_suite = Task(title="test_suite", minutes=5, available=False);

    root ++> compile_core
        ++> link_ui
        +>:DependsOn:+> link_common
        ++> bundle_app;
    root ++> link_db
        +>:DependsOn:+> link_common;
    root ++> bundle_app;
    root ++> test_suite;

    auditor = BuildAuditor();
    root spawn auditor;
    print(f"Total audited minutes: {auditor.total_minutes}");
}

