"""M3 initiative: walk release and backlog dependency chains in strict order."""

node Task {
    has number: int = 0;
    has title: str = "";
    has complete: bool = False;
    has gate: str = "";
}

node Epic {
    has number: int = 0;
    has title: str = "";
    has gate_label: str = "";
}

node Initiative {
    has number: int = 0;
    has title: str = "";
}

edge DependsOn { }

walker ReleaseAuditor {
    has visited: list[int] = [];
    has steps: list[str] = [];
    has gate_a_ready: bool = True;
    has gate_b_ready: bool = True;
    has gate_c_ready: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can summarize with Initiative | Epic entry {
        print(f"#{here.number}: {here.title}");
        visit [-->];
    }

    can traverse_chain with Task entry {
        if here.number in self.visited {
            print(f"  CYCLE at #{here.number}");
            disengage;
        }
        self.visited.append(here.number);

        state = "DONE" if here.complete else "OPEN";
        if not here.complete {
            if here.gate == "A" {
                self.gate_a_ready = False;
            } elif here.gate == "B" {
                self.gate_b_ready = False;
            } elif here.gate == "C" {
                self.gate_c_ready = False;
            }
        }
        print(f"  [{state}] #{here.number} {here.title} (gate {here.gate})");
        self.steps.append(f"#{here.number}:{state}");
        visit [->:DependsOn:->] else { visit [-->]; };
    }
}

