"""Repository context graph with bounded traversal and cycle detection."""

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has invalidated: bool = False;
}

node Instruction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "";
}

node Runner {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has timeout_ms: int = 0;
    has output_limit: int = 0;
}

node Context {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cache_key: str = "";
    has stale: bool = False;
}

edge Contains {
    has slot: str = "";
}

edge Executes {
    has timeout_ms: int = 0;
    has output_limit: int = 0;
}

edge Projects {
    has source_path: str = "";
}

edge Invalidates {
    has reason: str = "";
}

walker ContextAuditor {
    has seen: list[str] = [];
    has steps: int = 0;
    has step_limit: int = 12;

    can start with Root entry {
        print("auditing repository context dependencies");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Repository | Instruction | Runner | Context entry {
        if self.steps >= self.step_limit {
            print("bounded traversal stopped at the step limit");
            disengage;
        } else {
            self.steps += 1;
            if here.title in self.seen {
                print(f"cycle detected at {here.title}; invalidation walk stopped");
                disengage;
            } else {
                self.seen.append(here.title);
                state = "available" if here.available else "unavailable";
                print(f"{here.title}: {state}");
                visit [-->] else {
                    disengage;
                }
            }
        }
    }
}

