    has year: int = 0;
    has available: bool = True;
}

node Interest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge PursuedAt {
    has start_year: int = 0;
    has end_year: int = 0;
    has evidence: str = "";
}

edge TaggedWith {
    has start_year: int = 0;
    has end_year: int = 0;
    has evidence: str = "";
}

walker RamenTrail {
    has requested_theme: str = "Ramen";
    has max_depth: int = 8;
    has depth: int = 0;

    can begin with Root entry {
        print("Tracing temporal interest graph");
        visit [-->] else {
            disengage;
        }
    }

    can follow_interest with Interest entry {
        if self.depth >= self.max_depth {
            print("Depth limit reached; stopping safely");
            disengage;
        }
        self.depth = self.depth + 1;
        print(f"Interest: {here.title}");
        visit [->:PursuedAt:->] else {
            disengage;
        }
    }

    can inspect_place with Place entry {
        if self.depth >= self.max_depth {
            print("Depth limit reached; stopping safely");
            disengage;
        }
        self.depth = self.depth + 1;

        status = "active" if here.available else "dormant";
        print(f"Place: {here.title} [{status}, {here.first_seen}-{here.last_seen}]");

        visit [->:TaggedWith:->] else {
            disengage;
        }
    }

    can inspect_theme with Theme entry {
        if self.depth >= self.max_depth {
            print("Depth limit reached; stopping safely");
            disengage;
        }
        self.depth = self.depth + 1;

        if here.title == self.requested_theme {
            print(f"Theme reached: {here.title}");
        }
    }
}

