"""Reactive DAG inspector: model cells, their dependency edges, drain steps,
and an inspector walker that walks the DAG by depth and reports the last
drain trace — the relationship the dashboard would render.

Pinned jac 0.36.1 semantics:
  * No built-in visited set on walkers -> the walker carries an explicit
    cycle guard so it cannot loop on diamond dependencies.
  * Typed edges carry the meaning (Dep, TriggeredBy); structural walk
    uses Dep; the drain-trace walker uses TriggeredBy to replay order.
  * Single exit ``report`` accumulated as a list field on the walker.
"""

node Cell {
    has title: str = "";
    has op: str = "";
    has verdict: str = "ok";
    has is_leaf: bool = False;
    has combinator: str = "lift";
    has recompute_unit: str = "ms";

    has status_hist_ok: int = 0;
    has status_hist_fail: int = 0;
    has status_hist_stale: int = 0;
    has freshness_us: int = 0;

    has claimed_keys: int = 0;

    has depth: int = 0;
}

# A structural edge: cell B depends on cell A (A is parent of B).
edge Dep { }

# A causal edge: step S of the last drain was triggered by cell A.
edge TriggeredBy { }

# One row of the last drain's trace. The Report itself is accumulated
# on the walker, so we model a step as a node too so the inspector
# walker can follow TriggeredBy edges in trace order.
node DrainStep {
    has cell_title: str = "";
    has claimed: int = 0;
    has changed: int = 0;
    has duration_us: int = 0;
}

walker Inspector {
    # Cycle guard for structural walk (no built-in dedupe in 0.36.1).
    has seen: list[str] = [];
    # Accumulated dashboard payload.
    has rows: list[dict] = [];
    # Trace replay buffer.
    has trace: list[str] = [];
    has max_depth: int = 16;

    can start with Root entry {
        print("[dashboard] mounting /reactive-dag view");
        visit [-->];
    }

    can index_cell with Cell entry {
        if here.title in self.seen {
            # Cycle policy of the source: skip, do not recurse.
            return;
        }
        self.seen.append(here.title);

        worst = "ok";
        if here.status_hist_fail > 0 {
            worst = "fail";
        } elif here.status_hist_stale > 0 {
            worst = "stale";
        }

        row = {
            "title": here.title,
            "depth": here.depth,
            "op": here.op,
            "verdict": here.verdict,
            "worst": worst,
            "combinator": here.combinator,
            "unit": here.recompute_unit,
            "ok": here.status_hist_ok,
            "fail": here.status_hist_fail,
            "stale": here.status_hist_stale,
            "freshness_us": here.freshness_us,
            "claimed_keys": here.claimed_keys,
            "leaf": here.is_leaf,
        };
        self.rows.append(row);
        print(f"  cell[{here.depth}] {here.title} op={here.op} worst={worst} "
              f"ok={here.status_hist_ok} fail={here.status_hist_fail} "
              f"stale={here.status_hist_stale}");

        if here.depth >= self.max_depth {
            return;
        }
        visit [->:Dep:->];
    }

    can replay_step with DrainStep entry {
        line = (f"step: cell={here.cell_title} claimed={here.claimed} "
                f"changed={here.changed} dur_us={here.duration_us}");
        self.trace.append(line);
        print("  " + line);
        visit [->:TriggeredBy:->];
    }
}

# Convenience: a drain report's "triggered_by" field names a parent cell.
# We expose a small builder that wires TriggeredBy edges between DrainSteps
# and the Cell they were triggered by, so the inspector walker can replay
# the trace without bespoke queue plumbing.

with entry {
    # Build a tiny reactive DAG: root -> A -> B -> C (diamond), plus D.
    a = Cell(title="A", op="fetch_users", verdict="ok",
             status_hist_ok=42, status_hist_fail=0, status_hist_stale=1,
             freshness_us=1200, depth=1);
    b = Cell(title="B", op="enrich", verdict="ok", is_leaf=True,
             status_hist_ok=42, status_hist_fail=2, status_hist_stale=0,
             freshness_us=900, depth=2);
    c = Cell(title="C", op="score", verdict="fail",
             status_hist_ok=10, status_hist_fail=30, status_hist_stale=5,
             freshness_us=2_000_000, depth=3);
    d = Cell(title="D", op="render", verdict="ok", is_leaf=True,
             status_hist_ok=5, status_hist_fail=0, status_hist_stale=0,
             freshness_us=500, depth=2);

    # Structural edges (typed): A is parent of B and D; B is parent of C.
    a +>:Dep:+> b;
    a +>:Dep:+> d;
    b +>:Dep:+> c;
    # Synthetic back-edge to exercise the cycle guard on the walker.
    c +>:Dep:+> a;

    # Last drain's trace: step1 triggered by A, step2 triggered by B,
    # step3 triggered by C. The report itself is what callers discard;
    # we attach it to root so the walker can find it.
    s1 = DrainStep(cell_title="A", claimed=3, changed=2, duration_us=410);
    s2 = DrainStep(cell_title="B", claimed=5, changed=5, duration_us=220);
    s3 = DrainStep(cell_title="C", claimed=1, changed=0, duration_us=900);
    # TriggeredBy points from the step to the cell that triggered it.
    s1 +>:TriggeredBy:+> a;
    s2 +>:TriggeredBy:+> b;
    s3 +>:TriggeredBy:+> c;

    root ++> a ++> b ++> c;
    root ++> d;
    root ++> s1 ++> s2 ++> s3;

    insp = Inspector(max_depth=8);
    root spawn insp;

    print(f"[dashboard] cells indexed: {len(insp.rows)}");
    print(f"[dashboard] trace lines:   {len(insp.trace)}");
}

