"""Forge env up: GitSource frontends must be materialized before the dev
server runs. The bug is that `up` reads the KCL-rendered Path straight off
the Frontend node, while a GitSource frontend has no path until it is
resolved into a source dir. We model the three lanes (build, deploy, up)
as walkers that share a Resolver walker; only the Resolver actually
traverses the source tree to materialize a source dir. `up` without the
resolve step runs npm in the empty Path, mirroring the original bug."""

node Frontend {
    has name: str = "";
    has kind: str = "";
    has path: str = "";
    has repo: str = "";
    has ref: str = "";
    has subdir: str = "";
}

node SourceDir {
    has materialized: bool = False;
    has location: str = "";
}

edge Declared {
    has lane: str = "";
}

edge ResolvedInto { }

walker Resolver {
    has resolved_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can resolve_frontend with Frontend entry {
        key = here.name;
        if key in self.visited {
            disengage;
        }
        self.visited.append(key);

        if here.kind == "git" {
            here.path = f"~/Library/Caches/forge/sources/{here.repo.replace('/', '-')}-{here.ref}/{here.subdir}";
            here.kind = "materialized";
            self.resolved_count += 1;
            print(f"  resolved {here.name} -> {here.path}");
            src = SourceDir(materialized=True, location=here.path);
            here +>:ResolvedInto:+> src;
        } else {
            print(f"  skipped {here.name} (kind={here.kind}, no resolve needed)");
        }
        visit [-->];
    }

    can walk_sources with SourceDir entry {
        print(f"  source ready: {here.location} (materialized={here.materialized})");
        visit [-->];
    }
}

walker UpLane {
    has target: str = "";
    has served_dir: str = "";

    can start with Root entry {
        print(f"[up] target={self.target}");
        visit [-->];
    }

    can pick_target with Frontend entry {
        if here.name == self.target {
            self.served_dir = here.path;
            if self.served_dir == "" {
                print(f"[up] BUG: {here.name} has no path; npm would run in project root");
            } else {
                print(f"[up] serving {here.name} from {self.served_dir}");
            }
            disengage;
        }
        visit [-->];
    }
}

walker BuildLane {
    can start with Root entry {
        print("[build] resolving cross-repo frontend sources...");
        visit [-->];
    }

    can announce with Frontend entry {
        if here.kind == "git" {
            print(f"[build]   {here.repo}@{here.ref}//{here.subdir} -> {here.path}");
        }
        visit [-->];
    }
}

with entry {
    reliant_web = Frontend(
        name="reliant-web",
        kind="git",
        repo="github.com/reliant-labs/reliant",
        ref="v1.7.9",
        subdir="web"
    );
    admin_ui = Frontend(
        name="admin-ui",
