"""Event-driven incident federation with durable queueing and cycle-safe delivery."""

node Incident {
    has title: str = "";
    has revision: int = 0;
    has urgency: int = 0;
    has monitored: bool = True;
    has state: str = "open";
}

node ReplicationEvent {
    has event_id: str = "";
    has urgency: int = 0;
    has stage: str = "local-stored";
    has attempts: int = 0;
    has expired: bool = False;
}

node Peer {
    has name: str = "";
    has online: bool = True;
    has quiet_hours: bool = False;
    has delivery_state: str = "pending";
    has remote_storage: str = "not-stored";
    has review_state: str = "not-started";
}

edge Emits { }

edge QueuedFor {
    has priority: int = 0;
}

edge PeerLink { }

walker FederationDispatcher {
    has active_event: str = "";
    has seen_peers: list[str] = [];
    has delivered_peers: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can collect with Incident entry {
        print(f"incident {here.title} revision {here.revision} is {here.state}");
        visit [->:Emits:->] else {
            disengage;
        }
    }

    can stage with ReplicationEvent entry {
        self.active_event = here.event_id;
        here.stage = "queued";
        here.attempts = here.attempts + 1;
        print(f"event {here.event_id} durably queued for urgent delivery");
        visit [->:QueuedFor:->] else {
            disengage;
        }
    }

    can deliver with Peer entry {
        if here.name in self.seen_peers {
            print(f"cycle guard stopped at peer {here.name}");
            disengage;
        }

        self.seen_peers.append(here.name);

        if here.online and not here.quiet_hours {
            here.delivery_state = "radio-sent";
            here.remote_storage = "stored";
            here.review_state = "awaiting-approval";
            self.delivered_peers = self.delivered_peers + 1;
            print(f"{self.active_event} sent to {here.name}; remote review remains pending");
        } else {
            here.delivery_state = "pending";
            print(f"{self.active_event} pending for {here.name}: peer or policy blocked");
        }

        visit [->:PeerLink:->] else {
            disengage;
        }
    }
}

with entry {
    incident = Incident(
        title="Bridge outage",
        revision=7,
        urgency=10,
        monitored=True
    );
    event = ReplicationEvent(event_id="inc-7", urgency=10);
    primary = Peer(name="North relay", online=True, quiet_hours=False);
    backup = Peer(name="South relay", online=False, quiet_hours=False);

    root ++> incident;
    incident +>:Emits:+> event;
    event +>:QueuedFor(priority=10):+> primary;
    primary +>:PeerLink:+> backup;
    backup +>:PeerLink:+> primary;

    root spawn FederationDispatcher();
}

