"""Orchard maintenance tour.

A single union-trigger ability handles both irrigation pumps and
sprinklers, logging each device, its idle hours, and resetting the
counter before reporting the total devices serviced.
"""

node Pump {
    has label: str = "";
    has idle_hours: int = 0;
    has serviced: bool = False;

    def reset_idle() {
        self.idle_hours = 0;
    }
}

node Sprinkler {
    has label: str = "";
    has idle_hours: int = 0;
    has serviced: bool = False;

    def reset_idle() {
        self.idle_hours = 0;
    }
}

walker Crew {
    has total_serviced: int = 0;

    can start with Root entry {
        print("Crew starting maintenance tour");
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        kind = "Pump" if isinstance(here, Pump) else "Sprinkler";
        print(f"[{kind}] {here.label} — idle {here.idle_hours}h, resetting counter");
        here.reset_idle();
        here.serviced = True;
        self.total_serviced += 1;
        visit [-->];
    }
}

