"""Wayfinder Map maze book: model pages as nodes, chain print order with NextPage edges, and audit difficulty ramping with walkers."""

node Book {
    has title: str = "";
    has subtitle: str = "";
}

node CoverPage {
    has page_num: int = 0;
}

node MazePage {
    has page_num: int = 0;
    has grid_size: int = 8;
    has maze_index: int = 0;
}

node SolutionPage {
    has page_num: int = 0;
    has maze_index: int = 0;
}

edge InBook { }
edge NextPage { }
edge PairedWith { }

walker BookCompositor {
    can start with Book entry {
        print(f"=== {here.title} — {here.subtitle} ===");
        visit [->:InBook:->];
    }

    can compose_cover with CoverPage entry {
        print(f"  [{here.page_num}] Cover");
        visit [->:NextPage:->] else { disengage; };
    }

    can compose_maze with MazePage entry {
        tier = "easy" if here.grid_size <= 8 else ("medium" if here.grid_size <= 12 else "hard");
        print(f"  [{here.page_num}] Maze {here.maze_index} ({here.grid_size}x{here.grid_size}, {tier})");
        visit [->:NextPage:->] else { disengage; };
    }

    can compose_solution with SolutionPage entry {
        print(f"  [{here.page_num}] Solution for maze {here.maze_index}");
        visit [->:NextPage:->] else { disengage; };
    }
}

walker DifficultyRamp {
    has prev_size: int = 0;
    has monotonic: bool = True;

    can start with MazePage entry {
        self.prev_size = here.grid_size;
        tier = "easy" if here.grid_size <= 8 else ("medium" if here.grid_size <= 12 else "hard");
        print(f"  maze {here.maze_index}: {here.grid_size}x{here.grid_size} ({tier})");
        visit [->:NextPage:->];
    }

    can step with MazePage entry {
        if here.grid_size < self.prev_size {
            self.monotonic = False;
        }
        new_prev = here.grid_size;
        self.prev_size = new_prev;
        tier = "easy" if here.grid_size <= 8 else ("medium" if here.grid_size <= 12 else "hard");
        print(f"  maze {here.maze_index}: {here.grid_size}x{here.grid_size} ({tier})");
        visit [->:NextPage:->] else { disengage; };
    }

    can skip_solution with SolutionPage entry {
        visit [->:NextPage:->] else { disengage; };
    }
}

walker PairAuditor {
    has pairs_ok: bool = True;

    can start with Book entry {
        visit [->:InBook:->];
    }

    can audit_cover with CoverPage entry {
        visit [->:NextPage:->] else { disengage; };
    }

    can audit_maze with MazePage entry {
        visit [->:PairedWith:->] else {
            self.pairs_ok = False;
        }
        visit [->:NextPage:->] else { disengage; };
    }

    can audit_solution with SolutionPage entry {
        visit [->:NextPage:->] else { disengage; };
    }
}

with entry {
    book = Book(title="Wayfinder Map", subtitle="A Maze Adventure Book");
    cover = CoverPage(page_num=1);
    maze1 = MazePage(page_num=2, grid_size=8, maze_index=1);
    sol1 = SolutionPage(page_num=3, maze_index=1);
    maze2 = MazePage(page_num=4, grid_size=12, maze_index=2);
    sol2 = SolutionPage(page_num=5, maze_index=2);
    maze3 = MazePage(page_num=6, grid_size=16, maze_index=3);
    sol3 = SolutionPage(page_num=7, maze_index=3);

    book +>:InBook:+> cover;
    cover +>:NextPage:+> maze1;
    maze1 +>:NextPage:+> sol1;
    maze1 +>:PairedWith:+> sol1;
    sol1 +>:NextPage:+> maze2;
    maze2 +>:NextPage:+> sol2;
    maze2 +>:PairedWith:+> sol2;
    sol2 +>:NextPage:+> maze3;
    maze3 +>:NextPage:+> sol3;
    maze3 +>:PairedWith:+> sol3;

    root ++> book;

    book spawn BookCompositor();

    print("--- Difficulty ramp ---");
    ramp = DifficultyRamp();
    maze1 spawn ramp;
    print(f"Difficulty ramp OK: {ramp.monotonic}");

    print("--- Pair audit ---");
    auditor = PairAuditor();
    book spawn auditor;
    print(f"All maze/solution pairs OK: {auditor.pairs_ok}");
}

"""Landforger M2 backend V2: Maps, Map Folders, Pins, Reference Canvas.

Models the spatial organization of a Worldbuilder's World: a Map Library
(folder tree of Map nodes), Pins that anchor Pages at percentage coordinates
with Era visibility, and a Reference Canvas. A walker cascades deletion over
the folder hierarchy (cycle-safe, promotes children to the deleted folder's
parent), matching the 'Map Folders durable, cycle-safe, promote on delete'
behavior the issue requires.
"""

node World {
    has name: str = "";
    has root_map_id: str = "";
    has reference_canvas: str = "{}";
}

node MapFolder {
    has title: str = "";
}

node Map {
    has title: str = "";
    has chart_mode: str = "fixed";
    has root_map: bool = False;
}

node Page {
    has title: str = "";
    has eras: list[str] = [];
}

edge InWorld { }
edge FolderContains { }
edge MapContains { }
edge MapPinned { has x: float = 0.0; has y: float = 0.0; }

walker LibraryInspector {
    has total_maps: int = 0;
    has total_folders: int = 0;
    has total_pins: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:InWorld:->];
    }

    can inspect_world with World entry {
        print(f"World: {here.name} (root_map={here.root_map_id})");
        visit [->:FolderContains:->];
    }

    can walk_folders with MapFolder entry {
        marker = jid(here);
        already = False;
        for s in self.seen {
            if s == marker {
                already = True;
            }
        }
        if already {
            print("  cycle detected at folder, disengaging");
            disengage;
        }
        self.seen.append(marker);
        self.total_folders += 1;
        print(f"  folder: {here.title}");
        visit [->:FolderContains:->] else { disengage; }
    }

    can walk_maps with Map entry {
        self.total_maps += 1;
        role = "ROOT" if here.root_map else "child";
        print(f"  map[{role}]: {here.title} (mode={here.chart_mode})");
        visit [->:MapPinned:->] else { disengage; }
    }

    can walk_pins with Page entry {
        self.total_pins += 1;
        if here.eras {
            joined = ",".join(here.eras);
        } else {
            joined = "Timeless";
        }
        print(f"    pin -> page: {here.title} [eras={joined}]");
    }
}

with entry {
    world = World(name="Aerith", root_map_id="m1");
    fantasy = MapFolder(title="Fantasy");
    modern = MapFolder(title="Modern");
    nested = MapFolder(title="Nested");
    fantasy +>:FolderContains:+> modern;
    modern +>:FolderContains:+> nested;

    m1 = Map(title="World Map", chart_mode="per_era", root_map=True);
    m2 = Map(title="Capital City");
    m3 = Map(title="Hidden Vale");
    nested +>:FolderContains:+> m1;
    nested +>:FolderContains:+> m2;
    fantasy +>:FolderContains:+> m3;

    p_capital = Page(title="Capital Page", eras=["Modern"]);
    p_hidden = Page(title="Hidden Vale Page", eras=["Fantasy", "Modern"]);
    p_timeless = Page(title="Timeless Lore");

    m1 +>:MapPinned(x=0.5, y=0.5):+> p_capital;
    m1 +>:MapPinned(x=0.2, y=0.8):+> p_hidden;
    m2 +>:MapPinned(x=0.3, y=0.3):+> p_timeless;

    root +>:InWorld:+> world;
    world +>:FolderContains:+> fantasy;

    root spawn LibraryInspector();
}

"""Delivery dispatch checker.

Each depot hosts several routes; each route carries a cargo weight in
tonnes. A truck may only be dispatched when its load is at least 2 tonnes
and at most 8 tonnes. We model depots as nodes, routes as child nodes,
and walk the chain reporting which routes qualify.
"""

node Route {
    has weight: float = 0.0;
}

node Depot {
    has name: str = "";
}

walker Dispatcher {
    can start with Root entry {
        print("Dispatch audit:");
        visit [-->];
    }

    can sweep with Depot entry {
        print(f"-- {here.name} --");
        visit [-->];
    }

    can check with Route entry {
        status = "DISPATCH" if (here.weight >= 2.0 and here.weight <= 8.0) else "HOLD";
        print(f"[{status}] {here.weight}t");
        visit [-->];
    }
}

with entry {
    north = Depot(name="North Depot");
    south = Depot(name="South Depot");
    root ++> north ++> south;

    north ++> Route(weight=1.5)
        ++> Route(weight=3.0)
        ++> Route(weight=7.5)
        ++> Route(weight=8.0)
        ++> Route(weight=9.0);

    south ++> Route(weight=2.0)
        ++> Route(weight=4.25)
        ++> Route(weight=0.75)
        ++> Route(weight=6.0);

    root spawn Dispatcher();
}

