"""One-Canvas dbt authority demo with typed dependencies and cycle detection."""

node Project {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has external_authority: bool = False;
}

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has dbt_name: str = "";
    has source_path: str = "";
}

node Model {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has dbt_name: str = "";
    has model_path: str = "";
    has round_trip_safe: bool = True;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has semantic_sha: str = "";
    has render_profile: str = "";
    has read_only: bool = True;
}

edge Contains {
    has role: str = "";
}

edge DependsOn {
    has logical_reason: str = "";
}

edge Generates {
    has profile: str = "";
}

walker AuthorityAuditor {
    has seen: list[str] = [];

    can start with Root entry {
        print("Auditing one shared Canvas");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_project with Project entry {
        authority = "external dbt" if here.external_authority else "DVT-native";
        print(f"Project {here.title}: {authority}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_source with Source entry {
        print(f"Shared Source {here.title} keeps dbt fact {here.dbt_name}");
    }

    can inspect_model with Model entry {
        if here.identity in self.seen {
            print(f"cycle detected at {here.identity}");
            disengage;
        } else {
            self.seen = self.seen + [here.identity];
            mode = "round-trip" if here.round_trip_safe else "authority transition required";
            print(f"Model {here.title}: {mode}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_artifact with Artifact entry {
        print(f"Read-only projection {here.title}, profile {here.render_profile}");
    }
}

with entry {
    project = Project(
        title="analytics-dbt",
        identity="project:analytics",
        external_authority=True
    );
    source = Source(
        title="raw_orders",
        identity="source:raw_orders",
        dbt_name="raw.orders",
        source_path="models/sources.yml"
    );
    model_a = Model(
        title="orders",
        identity="model:orders",
        dbt_name="orders",
        model_path="models/orders.sql",
        round_trip_safe=True
    );
    model_b = Model(
        title="orders_enriched",
        identity="model:orders_enriched",
        dbt_name="orders_enriched",
        model_path="models/orders_enriched.sql",
        round_trip_safe=False
    );
    artifact = Artifact(
        title="orders compiled SQL",
        identity="artifact:orders",
        semantic_sha="sha256:demo",
        render_profile="dbt-sql",
        read_only=True
    );

    root +>:Contains(role="external project"):+> project;
    project +>:Contains(role="shared source"):+> source;
    project +>:Contains(role="shared model"):+> model_a;
    project +>:Contains(role="shared model"):+> model_b;
    model_a +>:DependsOn(logical_reason="logical DVT identity"):+> source;
    model_a +>:DependsOn(logical_reason="model dependency"):+> model_b;
    model_b +>:DependsOn(logical_reason="demonstration cycle"):+> model_a;
    model_a +>:Generates(profile="dbt-sql"):+> artifact;

    root spawn AuthorityAuditor();
}

