"""Recursive CTE-style subquery: model a tree where the recursive CTE
result feeds into a downstream query, exactly the scenario from issue
#1237. A walker descends the tree collecting IDs (the CTE), then another
walker uses that collected set as a subquery filter against a separate
collection of Foo nodes (the consumer query).
"""

node TreeNode {
    has id: int = 0;
    has name: str = "";
}

node Foo {
    has id: int = 0;
    has label: str = "";
}

edge ParentOf { }

walker CollectSubtree {
    has collected_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with TreeNode entry {
        self.collected_ids.append(here.id);
        visit [->:ParentOf:->];
    }
}

walker QueryWithSubquery {
    has allowed_ids: list[int] = [];
    has matches: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can filter with Foo entry {
        if here.id in self.allowed_ids {
