"""Repository pipeline runner demo with typed dependencies, exact revisions, and cycle detection."""

node Pipeline {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has max_parallel: int = 1;
}

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: str = "";
}

node Attempt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "queued";
    has revision: str = "";
    has repository_revision: str = "";
}

edge Targets { }
edge Runs { }
edge DependsOn {
    has reason: str = "";
}
edge HasAttempt {
    has slot: int = 0;
}

walker DependencyPlanner {
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print("planning repository dependencies");
        visit [->:Targets:->];
    }

    can inspect_pipeline with Pipeline entry {
        print(f"pipeline: {here.title}");
        visit [->:Runs:->];
    }

    can inspect_repository with Repository entry {
        if here.title in self.seen {
            self.cycle_found = True;
            print(f"cycle detected at repository {here.title}");
            disengage;
        }

        self.seen.append(here.title);
        print(f"repository: {here.title} revision={here.revision}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker AttemptAuditor {
    can start with Root entry {
        print("auditing scheduled attempts");
        visit [->:Targets:->];
    }

    can inspect_pipeline with Pipeline entry {
        visit [->:Runs:->];
    }

    can inspect_repository with Repository entry {
        print(f"checking attempts for {here.title}");
        visit [->:HasAttempt:->] else {
            disengage;
        }
    }

    can inspect_attempt with Attempt entry {
        if here.revision != here.repository_revision {
            here.state = "invalidated";
            here.available = False;
            print(f"invalidated {here.title}: revision mismatch");
        } else {
            print(f"ready {here.title}: exact revision confirmed");
        }
    }
}

with entry {
    pipeline = Pipeline(
        title="linux-release",
        max_parallel=2
    );

    app = Repository(
        title="app",
        revision="abc123"
    );
    build = Repository(
        title="build-tools",
        revision="def456"
    );
    release = Repository(
        title="release-config",
        revision="ghi789"
    );

    app_attempt = Attempt(
        title="attempt-app-1",
        state="running",
        revision="old999",
        repository_revision="abc123"
    );

    root +>:Targets:+> pipeline;
    pipeline +>:Runs:+> app;
    app +>:DependsOn(reason="build tooling"):+> build;
    build +>:DependsOn(reason="release metadata"):+> release;
    release +>:DependsOn(reason="cycle demonstration"):+> app;
    app +>:HasAttempt(slot=1):+> app_attempt;

    root spawn DependencyPlanner();
    root spawn AttemptAuditor();
}

