"""Mapsnap incremental fit: model pages, stages, and rung sets as a graph.

Demonstrates the cross-page coupling the issue cares about: snap's hash
for a page depends on its neighbour poses and on the volume-wide rung
set, so a single page's invalidation ripples through the neighbours
that snap consulted. A walker walks the snap dependency edges and
emits one incremental-fit plan per affected page."""

# ---- Nodes -----------------------------------------------------------------

node NodeBase {
    has kind: str = "";
    has label: str = "";
    has fingerprint: str = "";
}

node Page(NodeBase) {
    has keymap_loc: str = "";
    has stage_version: int = 0;
}

node Stage(NodeBase) {
    has stage_name: str = "";
    has stage_version: int = 0;
}

node RungSet(NodeBase) {
    has volume: str = "";
}

# Snap's neighbour-pose prior: a typed dependency from one page to another.
edge SnapPrior {
    has weight: float = 0.0;
}

# Stage -> Page: which page the stage ran on.
edge RanOn { }

# Page -> Page: snap consumed the neighbour's published fit.
edge ConsultedPose { }

# Page -> RungSet: snap for this page read the volume's rung set.
edge UsedRungs { }

# ---- Walker ----------------------------------------------------------------

# `FitPlanner` traverses the per-page snap dependencies. For each page it
# reaches it records why the page must be recomputed (own hash change,
# neighbour pose change, or rung-set change). One exit `report` collects
# the plan.
walker FitPlanner {
    has changed_pages: list[str] = [];
    has changed_rungs: str = "";

    can start with Root entry {
        visit [-->];
    }

    # Union ability: same logic whether we land on a Page or on a RungSet.
    # Both node kinds share `label`, `fingerprint`, and `kind` via NodeBase.
    can plan with Page | RungSet entry {
        reason = "";
        if here.kind == "rungset" {
            self.changed_rungs = here.fingerprint;
            reason = "rungs=" + here.fingerprint;
        } else {
            self.changed_pages.append(here.label);
            label_reason = "neighbour-of-rungs" if self.changed_rungs != "" else "own-hash";
            reason = label_reason;
        }
        print(f"[plan] {here.label}: {reason}");
        visit [-->];
    }
}

# `SnapWalker` simulates a single A/B that mutates a few pages and the
# rung set, then spawns the planner to compute which pages must re-snap.
walker SnapWalker {
    has volume: str = "";

    can start with Root entry {
        print(f"== incremental fit for volume {self.volume} ==");
        visit [-->];
    }

    can plan_volume with RungSet entry {
        print(f"rung-set fingerprint = {here.fingerprint}");
        visit [-->];
    }

    can plan_page with Page entry {
