"""NodeScript execution plan: dedupe reachable nodes via a visited set during traversal.

Models the essential issue — converging (diamond) graphs cause a node to be
enqueued multiple times and execution-plan construction degrades to quadratic.
The walker marks each node when it is first enqueued (not when it is later
recorded into the plan), guaranteeing each reachable node appears exactly once
while preserving the deterministic traversal order over typed ``DependsOn`` edges.
Disconnected nodes that no ``DependsOn`` edge reaches are correctly excluded.
"""

node Step {
    has label: str = "";
    has visited: bool = False;
}

# Typed edge: a Step depends on another Step's output (graph dependency).
edge DependsOn {
    has weight: int = 1;
}

walker ExecutionPlanner {
    has plan: list[str] = [];

    can start with Root entry {
        print("Building execution plan from root via DependsOn edges");
        visit [->:DependsOn:->];
    }

    # Traversal ability over the typed edge. Marking at enqueue time is the
    # fix for the duplicate-enqueue bug: once a Step is reached via any path,
    # subsequent re-entries (the diamond case) are no-ops.
    can plan_step with Step entry {
        if here.visited {
            print(f"  skip duplicate enqueue for {here.label}");
            return;
        }
        here.visited = True;
        self.plan.append(here.label);
        print(f"  enqueued {here.label}");
        visit [->:DependsOn:->];
    }

    can report_plan with Root entry {
        print(f"Final plan ({len(self.plan)} steps): {self.plan}");
    }
}

with entry {
    # Diamond: root -> A,B -> C, then C -> E. C is the convergence point.
    a = Step(label="A");
    b = Step(label="B");
    c = Step(label="C");
    e = Step(label="E");

    # Disconnected node: not linked by DependsOn from root; must NOT appear
    # in the execution plan (preserves the valid-disconnected-node contract).
    d = Step(label="D");

    root +>:DependsOn:+> a;
    root +>:DependsOn:+> b;
    a +>:DependsOn:+> c;
    b +>:DependsOn:+> c;
    c +>:DependsOn:+> e;

    # d is intentionally orphaned from the typed dependency graph.
    root ++> d;

    planner = ExecutionPlanner();
    root spawn planner;
}

"""Order auditor: skip invalid orders and halt the walk on fraud flags."""

node Order {
    has amount: float = 0.0;
    has is_valid: bool = True;
    has is_fraud: bool = False;
}

walker OrderAuditor {
    has audited_count: int = 0;

    can start with Root entry {
        print("Order audit started");
        visit [-->];
    }

    can audit with Order entry {
        if here.is_fraud {
            print(f"[HALT] amount={here.amount} — fraud flagged, stopping audit");
            disengage;
        }
        if not here.is_valid {
            print(f"[SKIP] amount={here.amount} — invalid order, continuing");
            visit [-->] else { disengage; };
        } else {
            self.audited_count += 1;
            print(f"[OK] amount={here.amount} — audited (total {self.audited_count})");
            visit [-->] else { disengage; };
        }
    }
}

