        ++> Order(amount=75.25, is_valid=True, is_fraud=False)
        ++> Order(amount=999.99, is_valid=True, is_fraud=True)
        ++> Order(amount=15.00, is_valid=True, is_fraud=False);
    auditor = OrderAuditor();
    root spawn auditor;
    print(f"Audit finished with {auditor.audited_count} orders passed");
}

