"""Composite fan-out: model the unbounded expansion of a composite inbox message.

The original machinery in whizbang expanded a single composite row into
child inbox rows one shot at receipt time. A pathological composite can
yield six-figure child rows from one parent, blowing past the per-composite
``MaxInnerEventsAllowed`` cap in practice and silently amplifying inbox depth
inside the consumer. This demo recreates that shape in idiomatic Jac:

- ``Composite`` and ``InboxRow`` are the two archetypes.
- A ``Carries`` typed edge links a composite to its child rows so the
  fan-out is a real graph, not an id-keyed adjacency list.
- ``FanoutWalker`` walks children off a composite, enforcing the cap
  (depth and total child budget) so the unbounded path is observable.
- ``Reachability`` walker reports the size of the subtree a composite
  expands into, exposing the very number that drove the bug report.
"""

node Composite {
    has title: str = "";
    has inner_event_count: int = 0;
    has max_inner_allowed: int = 1000;
}

node InboxRow {
    has title: str = "";
    has ordinal: int = 0;
    has processed: bool = False;
}

edge Carries {
    has ordinal: int = 0;
}

walker FanoutWalker {
    has processed_count: int = 0;
    has budget: int = 0;
    has cap: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can expand with Composite entry {
        print(f"composite '{here.title}' declares "
              f"{here.inner_event_count} inner events, "
              f"cap={here.max_inner_allowed}");
        if here.inner_event_count > here.max_inner_allowed {
            print(f"  REJECT: exceeds cap, would fan out "
                  f"{here.inner_event_count - here.max_inner_allowed} over budget");
            disengage;
        }
        self.budget = here.max_inner_allowed;
        self.cap = here.max_inner_allowed;
        visit [->:Carries:->];
    }

    can drain with InboxRow entry {
        if self.processed_count >= self.cap {
            print(f"  STOP: budget exhausted at {self.processed_count} rows");
            disengage;
        }
        self.processed_count += 1;
        here.processed = True;
        if self.processed_count % 10000 == 0 {
            print(f"  ...drained {self.processed_count} child rows");
        }
    }
}

walker Reachability {
    can start with Root entry {
        visit [-->];
    }

    can measure with Composite entry {
        # Walk every Carries edge off this composite and count the
        # subtree size — the very number that surprised operators.
        count = 0;
        for child in [->:Carries:->] {
            count += 1;
            _ = child;
        }
        verdict = "BOUNDED" if count <= here.max_inner_allowed else "UNBOUNDED";
        print(f"composite '{here.title}': subtree={count}, "
              f"cap={here.max_inner_allowed} -> {verdict}");
    }
}

with entry {
    # A small, well-behaved composite.
    small = Composite(title="small-batch", inner_event_count=5, max_inner_allowed=1000);
    small_child = InboxRow(title="small-0", ordinal=0);
    small +>:Carries(ordinal=0):+> small_child;

    # A pathological composite — mirrors the bug report's six-figure fan-out.
    # The composite is admitted with inner_event_count past its declared cap,
    # which is the exact failure mode described in #584.
    giant = Composite(title="redelivery-storm", inner_event_count=210000, max_inner_allowed=50000);
    # We attach a handful of representative child rows; the walker still
    # reports the declared inner_event_count, which is the bug's surface.
    giant_child_a = InboxRow(title="giant-0", ordinal=0);
    giant_child_b = InboxRow(title="giant-1", ordinal=1);
    giant +>:Carries(ordinal=0):+> giant_child_a;
    giant +>:Carries(ordinal=1):+> giant_child_b;

    root ++> small ++> giant;

    print("=== reachability audit ===");
    root spawn Reachability();

    print("\n=== bounded fan-out attempt ===");
    root spawn FanoutWalker();

    print("\n=== fan-out against the pathological composite ===");
    giant spawn FanoutWalker();
}

"""Portable retention sweep over a selected SQLite runtime and bounded batches."""

node SqliteRuntime {
    has source_class: str = "";
    has selected_version: str = "";
    has supports_limit_delete: bool = False;
    has capability_status: str = "";
}

node RetentionBatch {
    has name: str = "";
    has batch_limit: int = 0;
    has delete_strategy: str = "";
    has transactional: bool = True;
}

node RetentionRow {
    has batch_name: str = "";
    has table_name: str = "";
    has row_id: int = 0;
    has status: str = "";
    has batch_limit: int = 0;
    has slot: int = 0;
    has stale: bool = False;
    has purged: bool = False;
}

edge BatchQueue {
    has order: int = 0;
}

edge Purges {
    has reason: str = "";
}

edge Continues {
    has order: int = 0;
}

walker RetentionSweep {
    has seen_batches: list[str] = [];
    has purged_rows: int = 0;
    has failed_step: str = "";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_runtime with SqliteRuntime entry {
        print(f"runtime {here.source_class} SQLite {here.selected_version}: {here.capability_status}");
        if here.supports_limit_delete {
            print("optional DELETE LIMIT grammar is available");
        } else {
            print("DELETE LIMIT is unavailable; using bounded ID-subquery deletes");
        }
        visit [->:BatchQueue:->] else { disengage; }
    }

    can inspect_batch with RetentionBatch entry {
        if here.name in self.seen_batches {
            self.failed_step = here.name + " (dependency cycle)";
            print(f"failed step: {self.failed_step}");
            disengage;
        } else {
            self.seen_batches.append(here.name);
            if not here.transactional {
                self.failed_step = here.name + " (not transactional)";
                print(f"failed step: {self.failed_step}");
                disengage;
            } else {
                print(f"step {here.name}: bound {here.batch_limit} rows with {here.delete_strategy}");
                visit [->:Purges:->] else {
                    print(f"step {here.name}: no stale rows");
                }
            }
        }
    }

    can purge_row with RetentionRow entry {
        if here.stale and here.slot <= here.batch_limit {
            here.purged = True;
            self.purged_rows += 1;
            print(f"{here.batch_name}: purged {here.table_name} row {here.row_id} ({here.status})");
        }
        visit [->:Continues:->] else {
            print(f"{here.batch_name}: row frontier complete");
        }
    }
}

with entry {
    runtime = SqliteRuntime(
        source_class="Homebrew production library",
        selected_version="3.53.4",
        supports_limit_delete=False,
        capability_status="portable mutation path required"
    );

    history = RetentionBatch(
        name="history",
        batch_limit=2,
        delete_strategy="DELETE ... WHERE id IN (SELECT id ... LIMIT ?)"
    );
    completed = RetentionBatch(
        name="completed memory jobs",
        batch_limit=2,
        delete_strategy="DELETE ... WHERE id IN (SELECT id ... LIMIT ?)"
    );
    transcripts = RetentionBatch(
        name="completed transcript captures",
        batch_limit=2,
        delete_strategy="DELETE ... WHERE id IN (SELECT id ... LIMIT ?)"
    );

    root ++> runtime;
    runtime +>:BatchQueue(order=1):+> history;

    history_row_1 = RetentionRow(batch_name="history", table_name="history", row_id=101, status="expired", batch_limit=2, slot=1, stale=True);
    history_row_2 = RetentionRow(batch_name="history", table_name="history", row_id=102, status="expired", batch_limit=2, slot=2, stale=True);
    history_row_3 = RetentionRow(batch_name="history", table_name="history", row_id=103, status="expired", batch_limit=2, slot=3, stale=True);

    completed_row_1 = RetentionRow(batch_name="completed memory jobs", table_name="memory_jobs", row_id=201, status="completed", batch_limit=2, slot=1, stale=True);
    completed_row_2 = RetentionRow(batch_name="completed memory jobs", table_name="memory_jobs", row_id=202, status="dead", batch_limit=2, slot=2, stale=True);

    transcript_row_1 = RetentionRow(batch_name="completed transcript captures", table_name="transcript_capture_jobs", row_id=301, status="completed", batch_limit=2, slot=1, stale=True);
    transcript_row_2 = RetentionRow(batch_name="completed transcript captures", table_name="transcript_capture_jobs", row_id=302, status="dead", batch_limit=2, slot=2, stale=True);

    history +>:Purges(reason="retention age"):+> history_row_1;
    history +>:Purges(reason="retention age"):+> history_row_2;
    history +>:Purges(reason="retention age"):+> history_row_3;

    completed +>:Purges(reason="retention age"):+> completed_row_1;
    completed +>:Purges(reason="retention age"):+> completed_row_2;

    transcripts +>:Purges(reason="retention age"):+> transcript_row_1;
    transcripts +>:Purges(reason="retention age"):+> transcript_row_2;

    history_row_2 +>:Continues(order=1):+> completed;
    completed_row_2 +>:Continues(order=2):+> transcripts;

    root spawn RetentionSweep();
}

"""Security vulnerability scanner for the xmldom package.

Models xmldom releases, the CVEs filed against them, and the dependency
edges between a project and vulnerable releases. A walker traverses the
dependency graph and reports each transitive vulnerability hit, mirroring
the cascade-style report a security auditor needs when evaluating a
project's exposure to a vulnerable package.
"""

node Release {
    has version: str = "";
    has package: str = "";
}

node Vulnerability {
    has cve_id: str = "";
    has severity: str = "";
    has score: float = 0.0;
    has summary: str = "";
    has alert_id: str = "";
}

node Project {
    has name: str = "";
}

edge Affects {
    # Release is affected by a Vulnerability.
}

edge DependsOn {
    # Project depends on a particular Release.
}

walker SecurityAuditor {
    has project_name: str = "SRM-Test-DEV/test-56";
    has hits: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_project with Project entry {
        print(f"Auditing project: {self.project_name}");
        visit [-->];
    }

    can follow_dep with DependsOn entry {
        visit [->:DependsOn:->];
    }

    can inspect_release with Release entry {
        print(f"  Release {here.package}@{here.version} -- checking CVEs");
        visit [->:Affects:->];
    }

    can record_vuln with Vulnerability entry {
        label = f"[{here.severity} {here.score}] {here.cve_id}: {here.summary}";
        self.hits = self.hits + [label];
        print(f"    !! Hit: {label}");
    }
}

with entry {
    # Build the xmldom release under audit.
    xmldom_0_6 = Release(version="0.6.0", package="xmldom");
    xmldom_0_7 = Release(version="0.7.0", package="xmldom");
    xmldom_0_8 = Release(version="0.8.4", package="@xmldom/xmldom");

    # The three CVEs filed against xmldom.
    cve_32796 = Vulnerability(
        cve_id="CVE-2021-32796",
        severity="MEDIUM",
        score=5.3,
        summary="special-char escape flaw in removed-element serialization",
        alert_id="15daa12a-21fb-42e7-9b19-ee8490e8c788"
    );
    cve_37616 = Vulnerability(
        cve_id="CVE-2022-37616",
        severity="CRITICAL",
        score=9.8,
        summary="prototype pollution via copy() p variable",
        alert_id="82db6447-5761-4e0a-a23c-cd4293cf469d"
    );
    cve_39353 = Vulnerability(
        cve_id="CVE-2022-39353",
        severity="CRITICAL",
        score=9.8,
        summary="parser accepts multi-root docs, breaks single-root assumption",
        alert_id="fb6e2875-4db3-4092-89f6-1f0c23ec4399"
    );

    # Wire the project, its dependency, and which releases each CVE affects.
    app = Project(name="SRM-Test-DEV/test-56");
    root ++> app +>:DependsOn:+> xmldom_0_6;

    xmldom_0_6 +>:Affects:+> cve_32796;
    xmldom_0_6 +>:Affects:+> cve_37616;
    xmldom_0_8 +>:Affects:+> cve_39353;

    auditor = SecurityAuditor(project_name="SRM-Test-DEV/test-56");
    root spawn auditor;

    print(f"\nTotal vulnerabilities affecting project: {len(auditor.hits)}");
    for (i, hit) in enumerate(auditor.hits) {
        print(f"  {i + 1}. {hit}");
    }
}

"""Restaurant recommender: find restaurants matching a minimum rating via a spawn-parameterized walker."""

node Restaurant {
    has title: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker FoodieFinder {
    has min_rating: float = 0.0;
    has matches: list = [];

    can start with Root entry {
        visit [-->];
    }

    can search with Restaurant entry {
        if here.rating >= self.min_rating {
            self.matches.append(here);
        }
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(title="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(title="Joe's Diner", cuisine="American", rating=3.7)
        ++> Restaurant(title="Sushi Yasuda", cuisine="Japanese", rating=4.6)
