    }
}

"""Location hierarchy audit that terminates safely when parent links contain a cycle."""

node Location {
    has location_id: str = "";
    has name: str = "";
}

edge ParentOf { }

walker LocationAuditor {
    has visited_ids: list[str] = [];

    can start with Root entry {
        print("Auditing location hierarchy");
        visit [->:ParentOf:->] else {
            disengage;
        }
    }

    can inspect with Location entry {
        if here.location_id in self.visited_ids {
            print(f"Cycle detected at {here.name}; audit stopped safely");
            disengage;
        } else {
            self.visited_ids.append(here.location_id);
            print(f"Visited {here.name}");
            visit [->:ParentOf:->] else {
                disengage;
            }
        }
    }
}

with entry {
    a = Location(location_id="A", name="A");
    c = Location(location_id="C", name="C");
    b = Location(location_id="B", name="B");
    d = Location(location_id="D", name="D");

    root +>:ParentOf:+> a;
    a +>:ParentOf:+> c;
    c +>:ParentOf:+> b;
    b +>:ParentOf:+> a;
    b +>:ParentOf:+> d;

    root spawn LocationAuditor();
}

