"""Order auditor: invalid orders skip ahead, fraud-flagged orders halt the walk."""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has flagged_fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Auditing orders...");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        if here.flagged_fraud {
            print(f"[HALT] {here.label}: fraud flagged on ${here.amount:.2f} - stopping audit");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] {here.label}: invalid order, moving on");
            visit [-->] else { disengage; }
        }
        print(f"[OK]   {here.label}: ${here.amount:.2f} audited");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Order(label="ORD-1", amount=120.50, valid=True)
        ++> Order(label="ORD-2", amount=99.99, valid=False)
        ++> Order(label="ORD-3", amount=45.00, valid=True)
        ++> Order(label="ORD-4", amount=500.00, valid=True, flagged_fraud=True)
        ++> Order(label="ORD-5", amount=75.25, valid=True);
    root spawn OrderAuditor();
}
