"""Bounded-memory vectorized Stream merge with distinct ElementID semantics."""

node StreamQuery {
    has title: str = "";
    has limit: int = 0;
    has offset: int = 0;
}

node Batch {
    has title: str = "";
    has source: str = "";
}

node Element {
    has title: str = "";
    has element_id: str = "";
    has rank: int = 0;
    has available: bool = True;
}

edge InputBatch {
    has ordinal: int = 0;
}

edge Row {
    has position: int = 0;
}

edge MergeOrder {
    has stable_rank: int = 0;
}

walker BoundedMerge {
    has seen_ids: list[str] = [];
    has kept_ids: list[str] = [];
    has distinct_seen: int = 0;
    has emitted: int = 0;
    has cap: int = 0;
    has offset: int = 0;
    has limit: int = 0;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can prepare with StreamQuery entry {
        self.limit = here.limit;
        self.offset = here.offset;
        self.cap = self.limit + self.offset;
        print(f"merge {here.title}: cap={self.cap}, no full row buffer");
        visit [->:MergeOrder:->] else { disengage; }
    }

    can consume with Element entry {
        if here.element_id not in self.seen_ids {
            self.seen_ids.append(here.element_id);
            self.distinct_seen += 1;

            if self.distinct_seen > self.offset {
                if self.emitted < self.limit {
                    self.emitted += 1;
                    self.kept_ids.append(here.element_id);
                    print(f"kept {here.element_id} at stable rank {here.rank}");
                }
            }

            if self.cap > 0 and self.distinct_seen >= self.cap {
                print(f"stop: retained {self.distinct_seen} distinct IDs");
                disengage;
            }
        }

        visit [->:MergeOrder:->] else { disengage; }
    }

    can summarize with Root exit {
        print(f"report: {self.emitted} rows, state size {len(self.seen_ids)}");
    }
}

with entry {
    query = StreamQuery(title="LIMIT 2 OFFSET 1", limit=2, offset=1);
    batch_a = Batch(title="A", source="index shard A");
    batch_b = Batch(title="B", source="index shard B");

    root ++> query;
    query +>:InputBatch(ordinal=1):+> batch_a;
    query +>:InputBatch(ordinal=2):+> batch_b;

    first = Element(element_id="E1", rank=1);
    duplicate = Element(element_id="E1", rank=2);
    second = Element(element_id="E2", rank=3);
    third = Element(element_id="E4", rank=4);
    fourth = Element(element_id="E5", rank=5);

    batch_a +>:Row(position=1):+> first;
    batch_b +>:Row(position=1):+> duplicate;
    batch_a +>:Row(position=2):+> second;
    batch_b +>:Row(position=2):+> third;
    batch_a +>:Row(position=3):+> fourth;

    query +>:MergeOrder(stable_rank=1):+> first;
    first +>:MergeOrder(stable_rank=2):+> duplicate;
    duplicate +>:MergeOrder(stable_rank=3):+> second;
    second +>:MergeOrder(stable_rank=4):+> third;
    third +>:MergeOrder(stable_rank=5):+> fourth;

    root spawn BoundedMerge();
}

"""Kong declarative compilation: explicit resources, bindings, and operations."""

node Resource {
    has local_id: str = "";
    has kind: str = "";
    has namespace: str = "default";
    has parent_id: str = "";
    has collection_present: bool = True;
    has source_file: str = "";
    has invalidated: bool = False;
}

node RemoteBinding {
    has local_id: str = "";
    has remote_id: str = "";
    has scope: str = "";
    has phase: str = "";
    has deferred: bool = False;
    has secret: bool = False;
}

node Operation {
    has operation_id: str = "";
    has action: str = "";
    has destination_path: str = "";
    has source_field: str = "";
    has phase: str = "";
    has post_resolution: bool = False;
    has executable: bool = True;
}

edge HasResource {
    has slot: str = "";
}

edge IdentityOf {
    has phase: str = "";
}

edge CompiledInto {
    has destination: str = "";
}

edge Schedules {
    has sequence: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

walker ModelAudit {
    has resource_count: int = 0;
    has binding_count: int = 0;
    has operation_count: int = 0;

    can begin with Root entry {
        print("auditing canonical compiled resources");
        visit [->:HasResource:->] else { disengage; }
    }

    can inspect_resource with Resource entry {
        self.resource_count += 1;
        state = "invalidated" if here.invalidated else "active";
        print(f"resource {here.local_id}: {here.kind}, parent={here.parent_id}, {state}");
        visit [-->] else { disengage; }
    }

    can inspect_binding with RemoteBinding entry {
        self.binding_count += 1;
        binding_state = "deferred" if here.deferred else "bound";
        disclosure = "secret source withheld" if here.secret else f"remote={here.remote_id}";
        print(f"binding {here.local_id}: {binding_state}, {disclosure}, phase={here.phase}");
    }

    can inspect_operation with Operation entry {
        self.operation_count += 1;
        print(f"operation {here.operation_id}: {here.action} -> {here.destination_path}");
    }
}

walker DependencyAudit {
    has seen_operations: list[str] = [];
    has cycle_found: bool = False;
    has visited_count: int = 0;

    can begin with Root entry {
        print("walking explicit operation dependencies");
        visit [->:Schedules:->] else { disengage; }
    }

    can order with Operation entry {
        if here.operation_id in self.seen_operations {
            self.cycle_found = True;
            print(f"cycle detected at operation {here.operation_id}");
            disengage;
        } else {
            self.seen_operations.append(here.operation_id);
            self.visited_count += 1;
            print(f"planned {here.operation_id} in phase {here.phase}");
            visit [->:DependsOn:->] else {
                print(f"{here.operation_id} has no remaining dependencies");
                disengage;
            }
        }
    }
}

