"""Deterministic workflow output merge with reject-on-conflict semantics."""

node Workflow {
    has title: str = "";
    has conflict_policy: str = "reject-on-conflict";
    has merge_result: str = "pending";
}

node Task {
    has title: str = "";
    has completion_rank: int = 0;
}

node Output {
    has key: str = "";
    has value: str = "";
    has producer: str = "";
    has decision: str = "candidate";
}

edge Hosts { }
edge Contains { }
edge Produces { }

walker MergeAuditor {
    has seen_keys: list[str] = [];
    has conflict_keys: list[str] = [];
    has candidate_count: int = 0;
    has conflict_count: int = 0;
    has merge_result: str = "pending";

    can start with Root entry {
        visit [->:Hosts:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        print(f"workflow {here.title}: policy={here.conflict_policy}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_task with Task entry {
        print(f"task {here.title} completed at rank {here.completion_rank}");
        visit [->:Produces:->] else {
            disengage;
        }
    }

    can inspect_output with Output entry {
        self.candidate_count += 1;

        if here.key in self.seen_keys {
            self.conflict_count += 1;

            if here.key not in self.conflict_keys {
                self.conflict_keys.append(here.key);
            }

            print(f"conflict on {here.key} from {here.producer}; candidate rejected");
        } else {
            self.seen_keys.append(here.key);
            print(f"candidate {here.producer}.{here.key} = {here.value}");
        }
    }

    can summarize with Root exit {
        if self.conflict_count > 0 {
            self.merge_result = "rejected: no conflicting key is committed";
        } else {
            self.merge_result = "committed: all keys are unique";
        }

        print(f"merge result: {self.merge_result}");
        print(f"candidates={self.candidate_count}, conflicts={self.conflict_count}");
    }
}

with entry {
    workflow = Workflow(
        title="customer-enrichment",
        conflict_policy="reject-on-conflict"
    );

    first_task = Task(title="PrimaryLookup", completion_rank=2);
    second_task = Task(title="BackupLookup", completion_rank=1);

    first_output = Output(
        key="customer_id",
        value="C-100",
        producer="PrimaryLookup"
    );
    second_output = Output(
        key="customer_id",
        value="C-200",
        producer="BackupLookup"
    );

    root +>:Hosts:+> workflow;
    workflow +>:Contains:+> first_task;
    workflow +>:Contains:+> second_task;
    first_task +>:Produces:+> first_output;
    second_task +>:Produces:+> second_output;

    root spawn MergeAuditor();
}

