"""Audit graph demo with typed evidence links and an explicit cycle guard."""

node Candidate {
    has title: str = "";
    has revision: int = 0;
    has frozen: bool = False;
}

node Claim {
    has title: str = "";
    has status: str = "";
}

node Dependency {
    has title: str = "";
    has conditional: bool = False;
}

node Certificate {
    has digest: str = "";
    has valid: bool = False;
}

edge Contains { }
edge Audits {
    has obligation: str = "";
}
edge Evidence {
    has proof_sha256: str = "";
}
edge DependsOn {
    has reason: str = "";
}
edge Supports {
    has note: str = "";
}

walker Auditor {
    has hops: int = 0;
    has max_hops: int = 6;

    can start with Root entry {
        print("Starting independent claim audit");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspectCandidate with Candidate entry {
        print(f"Candidate: {here.title}, revision {here.revision}");
        visit [->:Audits:->] else {
            disengage;
        }
    }

    can inspectClaim with Claim entry {
        if self.hops >= self.max_hops {
            print(f"Cycle/depth guard stopped at claim: {here.title}");
            disengage;
        } else {
            self.hops += 1;
            print(f"Claim: {here.title} [{here.status}]");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspectDependency with Dependency entry {
        if self.hops >= self.max_hops {
            print(f"Cycle/depth guard stopped at dependency: {here.title}");
            disengage;
        } else {
            self.hops += 1;
            print(f"Dependency: {here.title}");
            visit [->:Supports:->] else {
                disengage;
            }
        }
    }
}

walker CertificateVerifier {
    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspectCandidate with Candidate entry {
        visit [->:Evidence:->] else {
            disengage;
        }
    }

    can verify with Certificate entry {
        if here.valid {
            print(f"Certificate accepted: {here.digest}");
        } else {
            print(f"Certificate rejected: {here.digest}");
        }
    }
}

