    );

    api +>:RaisesRisk(confidence=0.92):+> risk_pdb;
    ingress +>:RaisesRisk(confidence=0.71):+> risk_ingress;

    api +>:AffectsWorkload(replica_count=3, pdb_min_available=2):+> ingress;
