"""Hiking trail: a chain of plain waypoints walked by a hiker who counts stops."""

# Plain waypoints — no fields needed; the node archetype exists just to
# give the chain graph identity and to be the trigger type for the hiker.
node Waypoint;

walker Hiker {
    has target: int = 3;
    has stops: int = 0;

    can start with Root entry {
        print("Hiker sets off from the trailhead");
        visit [-->] else { disengage; }
    }

    can trek with Waypoint entry {
        self.stops += 1;
        print(f"Stop #{self.stops} reached");
        if self.stops >= self.target {
            print(f"Trip complete after {self.stops} waypoints");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # A straight chain of plain waypoints from trailhead to summit.
    # Each ++> creates one Waypoint node; no payload required.
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    hiker = Hiker(target=4);
    root spawn hiker;
}

"""CI pipeline walker: model workflow stages as nodes, dependencies as typed edges, and traverse in dependency order."""

node Stage {
    has name: str = "";
    has status: str = "pending";
    has duration_s: int = 0;
}

edge DependsOn {
    has required: bool = True;
}

node Job {
    has name: str = "";
    has runner: str = "ubuntu-latest";
}

walker RunPipeline {
    has visited: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        print("=== CI Pipeline: tally ===");
        print(f"Visited guard initialized ({len(self.visited)} so far)");
        visit [->:DependsOn:->];
    }

    can collect with Job entry {
        print(f"[JOB] {here.name} on {here.runner}");
        visit [->:DependsOn:->];
    }

    can run with Stage entry {
        if here.name in self.visited {
            print(f"[SKIP] {here.name} already done (cycle guard)");
            return;
        }
        self.visited.append(here.name);
        self.order.append(here.name);

        # Simulate the stage doing work.
        here.status = "running";
        print(f"[RUN ] {here.name} (dep ok={not False})");
        here.status = "passed";
        here.duration_s = 7;

        # Cascade-invalidate any stage that declared a dependency on us and is still pending.
        for child in [->:DependsOn:->] {
            if child.status == "pending" {
                child.status = "blocked";
                print(f"[INVD] {child.name} invalidated by upstream {here.name}");
            }
        }

        visit [->:DependsOn:->];
    }
}

walker CycleDetector {
    has path: list[str] = [];

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can scan with Stage entry {
        if here.name in self.path {
            print(f"[CYCLE] detected at {here.name}; path={self.path + [here.name]}");
            disengage;
        }
        self.path.append(here.name);
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
    # Build a tiny CI graph: lint -> test, lint -> build, build -> test.
    lint = Stage(name="lint", duration_s=2);
    build_stage = Stage(name="build", duration_s=5);
    test_stage = Stage(name="test", duration_s=10);
    publish_stage = Stage(name="publish", duration_s=3);

    lint_job = Job(name="lint-job", runner="ubuntu-latest");
    build_job = Job(name="build-job", runner="ubuntu-latest");
    test_job = Job(name="test-job", runner="ubuntu-latest");

    # Wire jobs under root.
    root ++> lint_job ++> build_job ++> test_job;

    # Stage dependency edges (typed: DependsOn).
    root +>:DependsOn:+> lint;
    lint +>:DependsOn:+> build_stage;
    build_stage +>:DependsOn:+> test_stage;
    test_stage +>:DependsOn:+> publish_stage;
    lint +>:DependsOn:+> test_stage;

    # Cycle sanity check first.
    cycle_walker = CycleDetector();
    root spawn cycle_walker;

    print("--- starting pipeline run ---");
    pipeline = RunPipeline();
    root spawn pipeline;

    print("--- final report ---");
    print(f"execution order: {pipeline.order}");
    print(f"stages visited:  {len(pipeline.visited)}");
}

