"""Bug tracker: file a new ticket under a project and capture it in one expression.

Demonstrates the grouped connection creation form (`(n := Node(...))`)
so the freshly created ticket is bound to a name in the same statement,
then prints its title and priority immediately without a separate lookup.
"""

node Project {
    has title: str = "";
}

node Ticket {
    has title: str = "";
    has priority: int = 0;
    has available: bool = True;
}

walker Triage {
    can start with Root entry {
        visit [-->];
    }

    can file with Project entry {
        print(f"Filing tickets under project: {here.title}");
        visit [-->];
    }

    can show with Ticket entry {
        status = "OPEN" if here.available else "CLOSED";
        print(f"[{status}] {here.title} (priority={here.priority})");
        visit [-->];
    }
}

with entry {
    project = Project(title="Jac Runtime");
