    # Connect and grab the fresh ticket in one expression.
    root ++> (fresh := Ticket(title="Walker hangs on cyclic graphs", priority=1));
    print(f"Captured ticket -> {fresh.title} (priority {fresh.priority})");

    # File another ticket directly under the project node.
    project ++> (project_fresh := Ticket(title="Typed edges in 0.36.1", priority=3));
    print(f"Captured ticket -> {project_fresh.title} (priority {project_fresh.priority})");

    # Walk the whole bug tracker from root and let triage print every ticket.
    root spawn Triage();
}

