"""Cache audit demo: verify cache compatibility and commit ancestry."""

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has repo_name: str = "";
    has head_ref: str = "";
    has model_version: str = "";
    has config_hash: str = "";
}

node CacheEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has analyzed_ref: str = "";
    has model_version: str = "";
    has config_hash: str = "";
}

node Commit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ref: str = "";
    has message: str = "";
}

edge Contains { }
edge NextCache { }
edge RepositoryOf { }
edge Head { }
edge Parent { }

walker CacheAuditor {
    has target_cache: str = "";
    has expected_model: str = "";
    has expected_config: str = "";
    has cache_enabled: bool = True;
    has phase: str = "find";
    has target_ref: str = "";
    has hops: int = 0;
    has max_hops: int = 6;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_repository with Repository entry {
        if self.phase == "find" {
            visit [->:Contains:->] else {
                print(f"cache {self.target_cache} was not found");
                disengage;
            }
        } else {
            visit [->:Head:->] else {
                print(f"repository {here.repo_name} has no HEAD");
                disengage;
            }
        }
    }

    can inspect_cache with CacheEntry entry {
        if here.title != self.target_cache {
            visit [->:NextCache:->] else {
                print(f"cache {self.target_cache} was not found");
                disengage;
            }
        } else {
            if self.cache_enabled {
                if here.model_version != self.expected_model {
                    print(f"cache {here.title} rejected: model version mismatch");
                    disengage;
                } else {
                    if here.config_hash != self.expected_config {
                        print(f"cache {here.title} rejected: configuration mismatch");
                        disengage;
                    } else {
                        self.target_ref = here.analyzed_ref;
                        self.phase = "check";
                        visit [->:RepositoryOf:->] else {
                            print(f"cache {here.title} rejected: repository link missing");
                            disengage;
                        }
                    }
                }
            } else {
                print(f"cache {here.title} bypassed: caching disabled");
                disengage;
            }
        }
    }

    can check_commit with Commit entry {
        if here.ref == self.target_ref {
            print(f"cache {self.target_cache} accepted: {here.ref} is an ancestor of HEAD");
            disengage;
        } else {
            if self.hops >= self.max_hops {
                print(f"cache {self.target_cache} rejected: cycle guard stopped ancestry scan");
                disengage;
            } else {
                self.hops = self.hops + 1;
                visit [->:Parent:->] else {
                    print(f"cache {self.target_cache} rejected: analyzed ref is stale");
                    disengage;
                }
            }
        }
    }
}

with entry {
    repo = Repository(
        title="checkOwners",
        repo_name="smusali/checkOwners",
        model_version="model-7",
        config_hash="config-a"
    );

    head = Commit(title="HEAD", ref="c3", message="current analysis");
    middle = Commit(title="Previous", ref="c2", message="known ancestor");
    base = Commit(title="Base", ref="c1", message="old base");

    warm = CacheEntry(
        title="warm-cache",
        analyzed_ref="c2",
        model_version="model-7",
        config_hash="config-a"
    );
    stale = CacheEntry(
        title="stale-cache",
        analyzed_ref="c9",
        model_version="model-7",
        config_hash="config-a"
    );
    incompatible = CacheEntry(
        title="old-model-cache",
        analyzed_ref="c2",
        model_version="model-6",
        config_hash="config-a"
    );

    root ++> repo;
    repo +>:Head:+> head;
    repo +>:Contains:+> warm;
    warm +>:NextCache:+> stale;
    stale +>:NextCache:+> incompatible;

    warm +>:RepositoryOf:+> repo;
    stale +>:RepositoryOf:+> repo;
    incompatible +>:RepositoryOf:+> repo;

    head +>:Parent:+> middle;
    middle +>:Parent:+> base;
    base +>:Parent:+> base;

    root spawn CacheAuditor(
        target_cache="warm-cache",
        expected_model="model-7",
        expected_config="config-a"
    );

    root spawn CacheAuditor(
        target_cache="stale-cache",
        expected_model="model-7",
        expected_config="config-a"
    );

    root spawn CacheAuditor(
        target_cache="old-model-cache",
        expected_model="model-7",
        expected_config="config-a"
    );

    root spawn CacheAuditor(
        target_cache="warm-cache",
        expected_model="model-7",
        expected_config="config-a",
        cache_enabled=False
    );
}

"""Process tree audit with cycle-safe traversal and cache invalidation."""

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has generation: int = 0;
    has cache_valid: bool = True;
}

node Image {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
}

edge ChildOf: Process --> Process { }
edge RunsImage: Process --> Image { }

walker ProcessAudit {
    has seen_keys: list[str] = [];
    has invalidated: list[str] = [];
    has reports: list[list[str]] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect with Process entry {
        key = f"{here.pid}:{here.generation}";
        if key in self.seen_keys {
            print(f"cycle or repeated PID generation detected: {key}");
            skip;
        }

        self.seen_keys.append(key);

        if here.cache_valid {
            here.cache_valid = False;
            self.invalidated.append(key);
            print(f"invalidated whitelist cache for {here.title} ({key})");
        }

        if not here.available {
            print(f"cleaned up exited process {here.title} ({key})");
        }

        visit [->:RunsImage:->];
        visit [->:ChildOf:->] else { skip; }
    }

    can inspect_image with Image entry {
        print(f"image storage uses actual path length: {here.path}");
    }

    can finish with Root exit {
        report self.invalidated;
    }
}

with entry {
    init = Process(title="hidguardian", year=2024, pid=100, generation=1);
    worker = Process(title="game.exe", year=2024, pid=200, generation=1);
    reused = Process(
        title="replacement.exe",
        year=2025,
        pid=200,
        generation=2,
        available=False
    );

    init_image = Image(
        title="hidguardian.sys",
        path="C:/Drivers/hidguardian.sys"
    );
    worker_image = Image(
        title="game.exe",
        path="C:/Games/game.exe"
    );
    replacement_image = Image(
        title="replacement.exe",
        path="C:/Games/replacement.exe"
    );

    root ++> init;
    init +>:ChildOf:+> worker;
    worker +>:ChildOf:+> reused;
    reused +>:ChildOf:+> init;

    init +>:RunsImage:+> init_image;
    worker +>:RunsImage:+> worker_image;
    reused +>:RunsImage:+> replacement_image;

    root spawn ProcessAudit();
}

