"""Dancer2 canonical route references: model named-route references, handler
relationships, route-local parameters, and complete-or-refuse rename contract
as a small typed graph walked by a rename-audit walker.
"""

# --- Entity archetypes -------------------------------------------------------

node App {
    has app_name: str = "";
    has root_id: str = "";
}

node RouteFact {
    has route_name: str = "";
    has path: str = "";
    has generation: int = 0;
}

node HandlerAnchor {
    has anchor_kind: str = "";
    has label: str = "";
    has is_canonical: bool = False;
}

node RouteParam {
    has param_key: str = "";
}

# --- Edges (typed where the relationship carries meaning) --------------------

edge BelongsToApp { }
edge DeclaredInApp { }
edge InlineHandler { has is_coderef: bool = False; }
edge UsesParam { }
edge RefersTo { has generation: int = 0; }

# --- Walkers -----------------------------------------------------------------

walker RouteRenameAuditor {
    has route_name: str = "";
    has allow_rename: bool = False;
    has refusal_reason: str = "";
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with RouteFact entry {
        if here.route_name != self.route_name {
            visit [-->] else { disengage; }
        }

        # Cycle guard: walkers in jac 0.36 do not dedupe on cyclic graphs.
        for seen in self.visited {
            if seen == here.route_name {
                self.refusal_reason = "cycle detected";
                disengage;
            }
        }
        self.visited.append(here.route_name);

        # Look at every outgoing edge from this RouteFact.
        outgoing = [-->];

        # 1) Inline handler relation: must be a real source-backed callback.
        handler_seen = False;
        for n in outgoing[?:HandlerAnchor] {
            handler_seen = True;
            # Strings are not Dancer2 handler subroutine references; only
            # canonical coderef-typed edges count.
            # The presence of any InlineHandler edge is the signal.
        }
        if not handler_seen {
            self.refusal_reason = "no inline handler anchor";
            disengage;
        }

        # 2) All references must be source-backed, same app/root, exact.
        ref_count = 0;
        for n in outgoing[?:RouteFact] {
            ref_count += 1;
        }
        if ref_count == 0 {
            self.refusal_reason = "no admitted references";
            disengage;
        }

        # 3) Route-local parameters: every param edge must be proven.
        param_count = 0;
        for n in outgoing[?:RouteParam] {
            param_count += 1;
        }

        # All checks passed: the complete current literal reference
        # denominator for the admitted source family is proven.
        self.allow_rename = True;
        summary = f"route {here.route_name} path={here.path} " +
            f"refs={ref_count} params={param_count}";
        print(summary);
        visit [-->];
    }
}

walker CascadeInvalidate {
    can start with Root entry {
        visit [-->];
    }

    can drop with App entry {
        print(f"invalidating app {here.app_name} root={here.root_id}");
        # Deleting the app node auto-purges its remaining edges.
        del here;
        disengage;
    }
}

# --- Demo wiring -------------------------------------------------------------

with entry {
    # Application A, root R1: a single supported named route with full
    # source-backed denominator (handler, references, params).
    app_a = App(app_name="web", root_id="R1");
    route_a = RouteFact(route_name="user_show", path="/user/:id", generation=1);
    handler_a = HandlerAnchor(anchor_kind="coderef", label="\&user_show_cb",
        is_canonical=True);
    ref_site = RouteFact(route_name="user_show_ref", path="", generation=1);
    param_id = RouteParam(param_key="id");
    param_name = RouteParam(param_key="name");

    root ++> app_a;
    app_a +>:DeclaredInApp:+> route_a;
    route_a +>:InlineHandler(is_coderef=True):+> handler_a;
    route_a +>:RefersTo(generation=1):+> ref_site;
    route_a +>:UsesParam:+> param_id;
    route_a +>:UsesParam:+> param_name;

    # Application B, root R1: same route NAME but different root identity,
    # so it is a distinct target and must NOT be merged into app A's rename.
    app_b = App(app_name="admin", root_id="R2");
    route_b = RouteFact(route_name="user_show", path="/admin/user/:id",
        generation=1);
    handler_b = HandlerAnchor(anchor_kind="string", label="user_show",
        is_canonical=False);
    app_b +>:DeclaredInApp:+> route_b;
    route_b +>:InlineHandler(is_coderef=False):+> handler_b;

    # Audit the named route "user_show" from app A's perspective.
    print("--- audit: user_show (app=web) ---");
    route_a spawn RouteRenameAuditor(route_name="user_show");

    # Cascade-invalidate app B to demonstrate walker-driven deletion of
    # the app node (and the auto-purge of its remaining route edge).
    print("--- cascade: drop app=admin ---");
    app_b spawn CascadeInvalidate();
}

