"""Cycle-safe JSON field collector.

Models the `collectJSONFields` helper from go-hooppy issue #123, where
recursing into self-referential embedded structs caused a stack overflow
instead of a proper diagnostic. The fix threads a visited set through the
walk so a type already on the path is skipped, mirroring what
`encoding/json`'s `typeFields` does.

The walker below is the idiomatic Jac equivalent: a `FieldCollector`
walker traverses embedded-field edges through the type graph, accumulating
field names on a single typed `has` accumulator. Without the visited set
the walker would loop forever on cyclic graphs (jac 0.36.1 has no
built-in once-per-node visitation), exactly matching the original bug.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node GoType {
    has name: str = "";
    has fields: list[str] = [];

    def describe() -> str {
        return f"{self.name}={self.fields}";
    }
}

# A concrete struct type with a list of (field_name, embedded_type_name)
# pairs. embedded targets are resolved via `Embeds` typed edges so the
# graph is the relationship, not a string lookup.
node StructType(GoType) {
    has embeds: list[str] = [];

    override def describe() -> str {
        return f"struct {self.name} embeds={self.embeds} fields={self.fields}";
    }
}

# ---------------------------------------------------------------------------
# Relationship: "struct X embeds struct Y by name"
# ---------------------------------------------------------------------------

edge Embeds { has since: str = "v1"; }

# ---------------------------------------------------------------------------
# Walker: cycle-safe JSON field collector
# ---------------------------------------------------------------------------

walker FieldCollector {
    has visited: list[GoType] = [];
    has collected: list[str] = [];

    def already_seen(t: GoType) -> bool {
        for v in self.visited {
            if v.name == t.name {
                return True;
            }
        }
        return False;
    }

    def mark(t: GoType) -> None {
        self.visited.append(t);
        for fname in t.fields {
            self.collected.append(fname);
        }
    }

    can start with Root entry {
        visit [-->];
    }

    # Single union ability handles both kinds of GoType we model.
    # The body's only shared contract is `name` + `fields` (declared on
    # the base) plus the traversal via the typed `Embeds` edge.
    can collect with GoType entry {
        if self.already_seen(here) {
            # Cycle hit: skip this type, do NOT re-enter its edges.
            # This is the fix from issue #123.
            print(f"[skip-cycle] {here.name} already on path");
        } else {
            self.mark(here);
            print(f"[collect]  {here.describe()}");
            visit [->:Embeds:->];
        }
    }
}

# ---------------------------------------------------------------------------
# Demo graph
# ---------------------------------------------------------------------------

with entry {
    # ----- Cyclic case: selfRef { *selfRef; A int } ------------------------
    self_ref = StructType(name="selfRef", fields=["a"], embeds=["selfRef"]);

    # ----- Mutual recursion: mutA embeds *mutB embeds *mutA ---------------
    mut_a = StructType(name="mutA", fields=["x"], embeds=["mutB"]);
    mut_b = StructType(name="mutB", fields=["y"], embeds=["mutA"]);

    # ----- Acyclic case: ordinary embedded chain --------------------------
    base = StructType(name="Base", fields=["id"], embeds=[]);
    middle = StructType(name="Middle", fields=["name"], embeds=["Base"]);
    top = StructType(name="Top", fields=["leaf"], embeds=["Middle"]);

    # Wire the edges. Cycles are intentional — the walker must NOT die.
    self_ref +>:Embeds:+> self_ref;
    mut_a +>:Embeds:+> mut_b;
    mut_b +>:Embeds:+> mut_a;
    top +>:Embeds:+> middle;
    middle +>:Embeds:+> base;

    # ----- Run the collector on each entry point ---------------------------
    for entry_node in [self_ref, mut_a, top] {
        print(f"\n--- collecting from {entry_node.name} ---");
        w = FieldCollector();
        root spawn w;
        # Manually seed the walker onto the chosen entry by re-rooting:
        # since walkers spawn at root, we instead just collect by
        # dispatching the same visited/collected logic into a fresh walker
        # whose start fires at our node. To keep the demo single-shot we
        # detach the node from root and re-attach, then spawn.
        root del --> entry_node;
        root ++> entry_node;
        w2 = FieldCollector();
        root spawn w2;
        print(f"result for {entry_node.name}: {w2.collected}");
    }

    # Re-attach the acyclic one for the final showcase run.
    print("\n=== showcase: selfRef must NOT overflow ===");
    root del --> mut_a;
    root del --> top;
    root ++> self_ref;
    walker_show = FieldCollector();
    root spawn walker_show;
    print(f"collected from selfRef: {walker_show.collected}");
    print("returned without stack overflow");
}

"""Bounded RLM context selection with typed graph traversal and cycle safety."""

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has final_answer: str = "";
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has depth: int = 0;
    has token_cost: int = 0;
    has query: str = "";
    has result: str = "";
}

node SourceDocument {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has body: str = "";
    has provenance: str = "";
}

node ContextSlice {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has text: str = "";
    has provenance: str = "";
    has audience: str = "";
    has selected: bool = False;
}

edge HasSession { }
edge OwnsTask { }
edge ReadsDocument { }
edge ContainsSlice { }
edge SelectsSlice { }
edge Spawns {
    has attempt: int = 0;
}

walker RlmExecutor {
    has max_calls: int = 6;
    has max_tokens: int = 64;
    has max_depth: int = 2;
    has attempted_calls: int = 0;
    has completed_calls: int = 0;
    has blocked_calls: int = 0;
    has tokens_used: int = 0;
    has cycle_hits: int = 0;
    has seen_titles: list[str] = [];
    has final_answer: str = "";

    can start with Root entry {
        print("RLM root: entering bounded session");
        visit [->:HasSession:->] else {
            disengage;
        }
    }

    can open_session with Session entry {
        print(f"Session: {here.title}");
        visit [->:OwnsTask:->] else {
            disengage;
        }
    }

    can execute_task with Task entry {
        self.attempted_calls = self.attempted_calls + 1;

        if self.attempted_calls > self.max_calls {
            self.blocked_calls = self.blocked_calls + 1;
            print("Call budget exhausted");
            disengage;
        } else {
            if here.title in self.seen_titles {
                self.cycle_hits = self.cycle_hits + 1;
                print(f"Cycle guarded at {here.title}");
            } else {
                if here.depth > self.max_depth {
                    self.blocked_calls = self.blocked_calls + 1;
                    print(f"Depth limit blocked {here.title}");
                } else {
                    if self.tokens_used + here.token_cost > self.max_tokens {
                        self.blocked_calls = self.blocked_calls + 1;
                        print(f"Token budget blocked {here.title}");
                    } else {
                        self.seen_titles = self.seen_titles + [here.title];
                        self.tokens_used = self.tokens_used + here.token_cost;
                        self.completed_calls = self.completed_calls + 1;
                        print(f"Task {here.title}: selecting external context");

                        if here.result != "" {
                            self.final_answer = here.result;
                            print(f"Child result: {here.result}");
                        }

                        visit [-->] else {
                            disengage;
                        }
                    }
                }
            }
        }
    }

    can inspect_document with SourceDocument entry {
        print(f"External document: {here.title} ({here.provenance})");
        visit [->:ContainsSlice:->] else {
            disengage;
        }
    }

    can inspect_slice with ContextSlice entry {
        if here.available and here.selected {
            print(f"Selected [{here.audience}] {here.provenance}: {here.text}");
        } else {
            print(f"Context unavailable: {here.title}");
        }
    }
}

with entry {
    session = Session(title="bounded RLM session", year=2026);

    document = SourceDocument(
        title="large research corpus",
        year=2026,
        body="Addressable external state is kept outside task prompts.",
        provenance="corpus://research/2026"
    );

    selected = ContextSlice(
        title="relevant evidence",
        year=2026,
        text="The selected evidence supports the child conclusion.",
        provenance="corpus://research/2026#section-7",
        audience="evaluation",
        selected=True
    );

    parent = Task(
        title="parent selection",
        year=2026,
        depth=0,
        token_cost=14,
        query="Find the evidence needed by a recursive child."
    );

    child = Task(
        title="child analysis",
        year=2026,
        depth=1,
        token_cost=18,
        query="Analyze only the selected evidence.",
        result="The held-out conclusion follows from the selected evidence."
    );

    root +>:HasSession:+> session;
    session +>:OwnsTask:+> parent;
    parent +>:ReadsDocument:+> document;
    parent +>:SelectsSlice:+> selected;
    document +>:ContainsSlice:+> selected;
    parent +>:Spawns(attempt=1):+> child;
    child +>:ReadsDocument:+> document;
    child +>:SelectsSlice:+> selected;
    child +>:Spawns(attempt=2):+> parent;

    executor = RlmExecutor(max_calls=6, max_tokens=64, max_depth=2);
    root spawn executor;

    session.final_answer = executor.final_answer;
    print(f"Final answer: {session.final_answer}");
    print(f"Calls {executor.completed_calls}/{executor.attempted_calls}, "
          f"tokens {executor.tokens_used}, cycles {executor.cycle_hits}");
}

"""Model pnpm's two-document lockfile and audit its dependency graph."""

node LockDocument {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has document_kind: str = "";
    has document_index: int = 0;
    has dependency_entries: int = 0;
}

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has package_name: str = "";
    has version: str = "";
    has application: bool = False;
    has invalidated: bool = False;
}

edge Contains {
    has role: str = "";
}

edge DependsOn {
    has optional: bool = False;
}

walker LockfileScanner {
    has seen: list[str] = [];
    has seen_documents: list[str] = [];
    has cycle_keys: list[str] = [];
    has empty_documents: int = 0;
    has application_packages: int = 0;
    has cycle_count: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_document with LockDocument entry {
        if here.title in self.seen_documents {
            skip;
        } else {
            self.seen_documents.append(here.title);
            if here.document_index == 0 && here.dependency_entries == 0 {
                self.empty_documents += 1;
                print(f"document {here.document_index}: {here.title} has no dependency entries");
            } else {
                print(f"document {here.document_index}: {here.title} has {here.dependency_entries} entries");
            }
            visit [->:Contains:->];
        }
    }

    can inspect_package with Package entry {
        package_key = here.package_name + "@" + here.version;
        if package_key in self.seen {
            if package_key not in self.cycle_keys {
                self.cycle_keys.append(package_key);
                self.cycle_count += 1;
                print(f"cycle detected at {package_key}");
            }
        } else {
            self.seen.append(package_key);
            if here.application {
                self.application_packages += 1;
            }
            if here.invalidated {
                print(f"invalidated package: {package_key}");
            } else {
                print(f"reachable package: {package_key}");
            }
            visit [->:DependsOn:->];
        }
    }

    can summarize with exit {
        print(f" audit: {self.application_packages} application packages, {self.empty_documents} empty documents, {self.cycle_count} cycles");
    }
}

with entry {
    environment = LockDocument(
        title="pnpm toolchain environment document",
        year=2026,
        document_kind="environment",
        document_index=0,
        dependency_entries=0
    );
    dependencies = LockDocument(
        title="application dependency document",
        year=2026,
        document_kind="dependencies",
        document_index=1,
        dependency_entries=3
    );
    pnpm = Package(
        title="pnpm@12.3.4",
        package_name="pnpm",
        version="12.3.4",
        application=True
    );
    yaml = Package(
        title="yaml@2.8.1",
        package_name="yaml",
        version="2.8.1",
        application=True
    );
    scanner = Package(
        title="dependency-scanner@1.0.0",
        package_name="dependency-scanner",
        version="1.0.0",
        application=True,
        invalidated=True
    );

    root +>:Contains(role="environment"):+> environment;
    environment +>:Contains(role="next document"):+> dependencies;
    dependencies +>:Contains(role="package"):+> pnpm;
    pnpm +>:DependsOn(optional=False):+> yaml;
    yaml +>:DependsOn(optional=False):+> scanner;
    scanner +>:DependsOn(optional=False):+> pnpm;

    root spawn LockfileScanner();
}

"""Bounded AgentCore goal evidence with typed relationships and safe retention review."""

node Goal {
    has goal_id: str = "";
    has status: str = "ACTIVE";
    has retention_class: str = "UNKNOWN";
}

node Attempt {
    has attempt_id: str = "";
    has outcome: str = "";
    has retry_reason: str = "";
}

node Evidence {
    has label: str = "";
    has classification: str = "REVIEW";
    has selected: bool = False;
    has copied: bool = False;
    has review_required: bool = False;
}

node SourcePointer {
    has reference: str = "";
    has commit_sha: str = "";
}

edge HasAttempt { }
edge Produces { }
edge RetryLeadsTo { }
edge PointsTo { }

walker RetentionAuditor {
    has keep_count: int = 0;
    has archive_count: int = 0;
    has candidate_count: int = 0;
    has review_count: int = 0;
    has hops: int = 0;
    has max_hops: int = 12;

    can start with Root entry {
        print("Auditing one bounded goal/run");
        visit [-->] else { disengage; }
    }

    can inspect_goal with Goal entry {
        print(f"Goal {here.goal_id}: {here.status}");
        if self.hops >= self.max_hops {
            print("Traversal stopped at the safety hop limit");
            disengage;
        } else {
            self.hops += 1;
            visit [->:HasAttempt:->] else { disengage; }
        }
    }

    can inspect_attempt with Attempt entry {
        print(f"Attempt {here.attempt_id}: {here.outcome}");
        if self.hops >= self.max_hops {
            print("Traversal stopped at the safety hop limit");
            disengage;
        } else {
            self.hops += 1;
            visit [->:Produces:->] else { disengage; }
        }
    }

    can classify_evidence with Evidence entry {
        if here.classification == "KEEP" {
            self.keep_count += 1;
            print(f"KEEP {here.label}");
        }
        if here.classification == "ARCHIVE" {
            self.archive_count += 1;
            print(f"ARCHIVE {here.label}");
        }
        if here.classification == "DELETE_CANDIDATE" {
            self.candidate_count += 1;
            print(f"CANDIDATE only: {here.label}");
        }
        if here.classification == "REVIEW" {
            self.review_count += 1;
            here.review_required = True;
            print(f"REVIEW {here.label}");
        }
        if here.copied {
            here.review_required = True;
            print(f"No-copy policy requires review: {here.label}");
        }
        if self.hops >= self.max_hops {
            print("Traversal stopped at the safety hop limit");
            disengage;
        } else {
            self.hops += 1;
            visit [->:RetryLeadsTo:->] else {
                visit [->:PointsTo:->] else { disengage; }
            }
        }
    }

    can inspect_pointer with SourcePointer entry {
        print(f"Source pointer: {here.reference} @ {here.commit_sha}");
    }

    can summarize with Root exit {
        print(f"Summary keep={self.keep_count}, archive={self.archive_count}, candidates={self.candidate_count}, review={self.review_count}");
    }
}

with entry {
    goal = Goal(goal_id="issue-3-agentcore-temp-retention", status="SUCCESS", retention_class="KEEP");
    first = Attempt(attempt_id="attempt-01", outcome="FAILED", retry_reason="initial proof incomplete");
    second = Attempt(attempt_id="attempt-02", outcome="SUCCESS", retry_reason="completed bounded proof");
    old_log = Evidence(label="attempt-01/raw.log", classification="DELETE_CANDIDATE", selected=False);
    result = Evidence(label="RESULT.md", classification="KEEP", selected=True);
    source = SourcePointer(reference="github.com/amitkarpe/agent-os/issues/3", commit_sha="6d49bd2dc767cd429ba51c555bac5a6a1a2341f8");

    root ++> goal;
    goal +>:HasAttempt:+> first;
    first +>:Produces:+> old_log;
    old_log +>:RetryLeadsTo:+> second;
    second +>:Produces:+> result;
    result +>:PointsTo:+> source;

    root spawn RetentionAuditor();
}

