"""Quadratic assign_product scenario: many products linked to one task.

Models the IfcOpenShell issue where each call into sequence.assign_product
re-scans the task's full HasAssignments inverse. The demo creates one task
holding N products, then walks every link to demonstrate the per-link scan
the issue complains about, and finally shows the batch form that avoids it.
"""

node Product {
    has name: str = "";
    has kind: str = "";
}

node Task {
    has title: str = "";
}

# Typed edge carries the relationship's identity (mirrors IfcRelAssignsToProduct).
edge AssignedTo {
    has tag: str = "";
}

walker PerLinkScanner {
    # Mirrors the O(N) pre-check inside sequence.assign_product: every
    # call walks the whole task->product list to ask "already linked?"
    has scan_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan_all with Task entry {
        # First "inverse read": gather every assignment off this task.
        links = [->:AssignedTo:->];
        # Second "inverse read": re-walk to count (the redundant scan
        # the issue calls out as pure waste).
        total = 0;
        for _ in [->:AssignedTo:->] {
            total += 1;
        }
        self.scan_count = total;
        print(f"per-link scan on '{here.title}': {total} assignments walked twice per call");
        visit [-->];
    }

    can visit_product with Product entry {
        # Each product visit would, in the original API, trigger another
        # full scan of the task's HasAssignments inverse.
        print(f"  -> visiting product {here.name} ({here.kind})");
    }
}

walker BatchAssigner {
    # Mirrors the suggested fix: one subset check over the whole batch,
    # not one scan per product.
    has pending: list[Product] = [];
    has task_title: str = "";

    can start with Root entry {
        visit [-->];
    }

    can gather_task with Task entry {
        self.task_title = here.title;
        print(f"batch check on '{here.title}': 1 inverse read for all products");
        visit [-->];
    }

    can gather_product with Product entry {
        self.pending.append(here);
    }

    can summarize with Root entry {
        existing_titles = [];
        for p in [->:AssignedTo:->] {
            existing_titles.append(p.name);
        }
        existing = set(existing_titles);
        candidate_names = [p.name for p in self.pending];
        new_count = 0;
        for name in candidate_names {
            if name not in existing {
                new_count += 1;
            }
        }
        already = len(self.pending) - new_count;
        print(f"batch saw {len(self.pending)} candidates, "
              f"{new_count} new, {already} already linked");
    }
}

with entry {
    # Build a task with N products on it, mirroring the fan-in case from
    # the issue (one task owning many flow segments / fittings).
    task = Task(title="Install floor services");
    root ++> task;

    kinds = ["IfcFlowSegment", "IfcFlowFitting", "IfcFlowTerminal"];
    for i in range(8) {
        p = Product(name=f"segment-{i}", kind=kinds[i % 3]);
        task +>:AssignedTo(tag=f"link-{i}"):+> p;
    }

    print("=== per-link (quadratic) form ===");
    scanner = PerLinkScanner();
    root spawn scanner;

    print("=== batch (one scan) form ===");
    batcher = BatchAssigner();
    root spawn batcher;
}

