"""LMCache Q3 Roadmap tracker: sections, work items, and accelerator dependencies
modeled as graph nodes traversed by a planner walker that performs dependency
ordering, reachability, and invalidation natively in Jac."""

# --- Node archetypes ---------------------------------------------------------

node Roadmap {
    has title: str = "";
    has quarter: str = "";
}

node Section {
    has title: str = "";
    has objective: str = "";
    has order_index: int = 0;
}

node WorkItem {
    has title: str = "";
    has done: bool = False;
    has ref_issue: str = "";
}

node Accelerator {
    has name: str = "";
    has vendor: str = "";
}

# --- Edge archetypes ---------------------------------------------------------

edge BelongsTo { }     # WorkItem -> Section, Section -> Roadmap
edge NeedsAccel { }   # WorkItem -> Accelerator (integration step depends on platform)
edge DependsOn { }    # WorkItem -> WorkItem (ordering constraint)

# --- Planner walker: traverses Section graph, invalidates stale items --------

walker Planner {
    has log_lines: list[str] = [];
    has invalidated: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can overview with Roadmap entry {
        self.log_lines.append(f"ROADMAP: {here.title} ({here.quarter})");
        visit [-->];
    }

    can list_sections with Section entry {
        self.log_lines.append(
            f"  Section[{here.order_index}] {here.title} :: {here.objective}"
        );
        visit [-->];
    }

    can audit_items with WorkItem entry {
        state = "DONE" if here.done else "OPEN";
        ref = f" ({here.ref_issue})" if here.ref_issue != "" else "";
        self.log_lines.append(f"    - [{state}] {here.title}{ref}");

        # Cascade invalidation: if the item links to an accelerator
        # integration and is not done yet, count and flag the invalidation.
        accel_targets = [here ->:NeedsAccel:->];
        has_accel = False;
        for _node in accel_targets {
            has_accel = True;
        }
        if has_accel and not here.done {
            self.invalidated += 1;
            self.log_lines.append(
                f"      ! invalidated (needs accelerator integration)"
            );
        }
        visit [-->];
    }

    can note_accel with Accelerator entry {
        self.log_lines.append(f"      accel: {here.name} ({here.vendor})");
        visit [-->];
    }
}

# --- Demonstration wiring ----------------------------------------------------

with entry {
    rm = Roadmap(title="LMCache 2026 Q3 Roadmap", quarter="2026-Q3");

    s1 = Section(
        title="Distributed KV Cache",
        objective="efficiently handle KV caches across multiple nodes",
        order_index=1,
    );
    s2 = Section(
        title="Ecosystem Support",
        objective="support and integrate with the latest innovations",
        order_index=2,
    );
    s3 = Section(
        title="KV Cache Optimization",
        objective="make KV cache smaller, faster, smarter",
        order_index=3,
    );

    w_peer = WorkItem(
        title="P2P KV cache sharing stress test",
        done=False,
        ref_issue="#4041",
    );
    w_sglang = WorkItem(
        title="SGLang MP mode async store/retrieve",
        done=False,
        ref_issue="",
    );
    w_maca = WorkItem(
        title="New accelerator: MACA",
        done=False,
        ref_issue="#3856",
    );
    w_ascend = WorkItem(
        title="New accelerator: Ascend",
        done=False,
        ref_issue="#3968",
    );
    w_compress = WorkItem(
        title="More KV cache compression algorithms",
        done=True,
        ref_issue="",
    );

    a_maca = Accelerator(name="MACA", vendor="MetaX");
    a_ascend = Accelerator(name="Ascend", vendor="Huawei");

    # Roadmap -> Sections (ordered by traversal from root)
    root ++> rm;
    rm ++> s1;
    rm ++> s2;
    rm ++> s3;

    # Sections -> WorkItems
    s1 ++> w_peer;
    s1 ++> w_sglang;
    s2 ++> w_maca;
    s2 ++> w_ascend;
    s3 ++> w_compress;

    # WorkItem -> Accelerator (typed edge: integration depends on accelerator)
    w_maca +>:NeedsAccel:+> a_maca;
    w_ascend +>:NeedsAccel:+> a_ascend;

    # WorkItem -> WorkItem ordering constraint (typed edge)
    w_sglang +>:DependsOn:+> w_peer;

    # Spawn the planner on root and print the accumulated log.
    planner = Planner();
    root spawn planner;

    for line in planner.log_lines {
        print(line);
    }
    print(f"\nTotal items invalidated by missing accel integration: "
          f"{planner.invalidated}");
}

