"""Compose Preview runtime DEX cache: model Gradle-resolved Compose artifacts,
their dependency graph, fingerprinting, DEX cache invalidation, and cascade
regeneration as native Jac walkers over typed edges.

The hand-rolled machinery the issue complains about (dependency list walks,
cache invalidation by fingerprint comparison, cascade delete of stale DEX,
reachability from the project root, cycle-safe dependency traversal) is
lifted to typed edges + walkers. The scaffolding dies; the semantics
(fingerprint-based invalidation, cycle-safe traversal, cascade regeneration)
survive.
"""

# ----------------------------------------------------------------------
# Node archetypes
# ----------------------------------------------------------------------

node Project {
    has name: str = "";
    has kotlin_version: str = "";
    has variant: str = "debug";
}

node Artifact {
    # A Gradle-resolved Maven artifact: group:name:version.
    has group: str = "";
    has name: str = "";
    has version: str = "";

    def fingerprint() -> str {
        return f"{self.group}:{self.name}:{self.version}";
    }

    def is_compose_related() -> bool {
        compose_related = False;
        if self.group == "androidx.compose.runtime" { compose_related = True; }
        if self.group == "androidx.compose.ui" { compose_related = True; }
        if self.group == "androidx.compose.foundation" { compose_related = True; }
        if self.group == "androidx.compose.material3" { compose_related = True; }
        return compose_related;
    }
}

node ComposeCompilerPlugin {
    has kotlin_target: str = "";
    has plugin_artifact: str = "";
}

node DexCache {
    # The cached preview-runtime DEX for a particular fingerprint.
    has cache_key: str = "";
    has present: bool = False;
}

# ----------------------------------------------------------------------
# Edge archetypes
# ----------------------------------------------------------------------

edge Resolved {
    # A Project resolves an Artifact (Gradle dependency resolution).
    has variant: str = "";
}

edge DependsOn {
    # Artifact-to-artifact dependency (POM-level).
}

edge UsesPlugin {
    # Project uses a Compose Compiler plugin.
}

edge CachedAs {
    # A resolved Compose artifact set was cached as a DexCache entry.
}

# ----------------------------------------------------------------------
# Walker: walk the resolved-artifact tree from a Project and rebuild the
# DEX cache. Carries an explicit cycle guard because jac 0.36.1 walkers
# have no built-in once-per-node visitation.
# ----------------------------------------------------------------------

walker RebuildPreviewDex {
    has visited_fingerprints: list[str] = [];
    has compose_fingerprints: list[str] = [];
    has invalidated: bool = False;

    can start with Root entry {
        # Root has no project metadata; just kick off traversal to the Project.
        visit [-->];
    }

    can enter_project with Project entry {
        print(f"Project: {here.name} (variant={here.variant}, kotlin={here.kotlin_version})");
        print("Triggering Gradle sync to obtain resolved Compose artifacts...");
        visit [->:Resolved:->];
    }

    can traverse_artifacts with Artifact entry {
        # Cycle guard: don't revisit artifacts with the same fingerprint.
        fp = here.fingerprint();
        already_seen = False;
        for seen in self.visited_fingerprints {
            if seen == fp {
                already_seen = True;
            }
        }
        if already_seen {
            return;
        }
        self.visited_fingerprints.append(fp);

        if here.is_compose_related() {
            self.compose_fingerprints.append(fp);
            print(f"  resolved compose artifact: {fp}");
        } else {
            print(f"  resolved non-compose artifact: {fp}");
        }

        # Recurse into POM dependencies via typed edge.
        visit [->:DependsOn:->];
    }

    can check_compiler_plugin with ComposeCompilerPlugin entry {
        plugin_for_kotlin = here.plugin_artifact;
        print(f"Compose compiler plugin mapped to kotlin {here.kotlin_target}: {plugin_for_kotlin}");
    }

    can reconcile_cache with DexCache entry {
        # Invalidate cache if the fingerprint set no longer matches.
        cached_key = here.cache_key;
        current_key = "";
        for fp in self.compose_fingerprints {
            current_key = current_key + fp + "|";
        }
        if cached_key != current_key {
            print(f"Cache MISS / STALE: regenerating DEX for {len(self.compose_fingerprints)} compose artifacts");
            self.invalidated = True;
            # Cascade: drop the stale cache entry node; its edges auto-purge.
            del here;
            visit [->:CachedAs:->];
        } else {
            print(f"Cache HIT: reusing existing DEX for fingerprint {cached_key[:32]}...");
        }
    }
}

# ----------------------------------------------------------------------
# Walker: cascade-invalidate stale DexCache entries reachable from a
# DexCache node when its resolved dependency set changes.
# ----------------------------------------------------------------------

walker CascadeInvalidate {
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:CachedAs:->];
    }

    can sweep with DexCache entry {
        # Cycle-safe: don't revisit the same cache entry twice.
        key = here.cache_key;
        already = False;
        for s in self.seen {
            if s == key {
                already = True;
            }
        }
        if already {
            return;
        }
        self.seen.append(key);

        if here.present {
            print(f"Invalidating stale DEX cache entry: {here.cache_key}");
            here.present = False;
        }
        # Walk forward along cached-as relationships to purge dependents.
        visit [->:CachedAs:->];
    }
}

# ----------------------------------------------------------------------
# Demo wiring
# ----------------------------------------------------------------------

with entry {
    project = Project(
        name="UserApp",
        kotlin_version="2.3.21",
        variant="debug"
    );
    root ++> project;

    # Resolved Compose artifacts (Gradle would hand us these).
    runtime = Artifact(group="androidx.compose.runtime", name="runtime", version="1.7.5");
    ui = Artifact(group="androidx.compose.ui", name="ui", version="1.7.5");
    foundation = Artifact(group="androidx.compose.foundation", name="foundation", version="1.7.5");
    material3 = Artifact(group="androidx.compose.material3", name="material3", version="1.3.1");

    project +>:Resolved(variant="debug"):+> runtime;
    project +>:Resolved(variant="debug"):+> ui;
    project +>:Resolved(variant="debug"):+> foundation;
    project +>:Resolved(variant="debug"):+> material3;

    # POM-level deps among artifacts (ui -> runtime, foundation -> ui, material3 -> foundation).
    ui +>:DependsOn:+> runtime;
    foundation +>:DependsOn:+> ui;
    material3 +>:DependsOn:+> foundation;

    # Compose compiler plugin must track Kotlin version.
    plugin = ComposeCompilerPlugin(
        kotlin_target="2.3.21",
        plugin_artifact="org.jetbrains.kotlin:compose-compiler-plugin:2.3.21"
    );
    project +>:UsesPlugin:+> plugin;

    # Stale cache entry: its fingerprint reflects the OLD hardcoded
    # versions (compose 1.6.0 / material3 1.2.0) and so will be invalidated.
    stale_cache = DexCache(
        cache_key="androidx.compose.runtime:runtime:1.6.0|androidx.compose.ui:ui:1.6.0|androidx.compose.foundation:foundation:1.6.0|androidx.compose.material3:material3:1.2.0|",
        present=True
    );
    project +>:CachedAs:+> stale_cache;

    print("=== Phase 1: rebuild preview DEX from resolved Gradle artifacts ===");
    root spawn RebuildPreviewDex();

    print("");
    print("=== Phase 2: cascade-invalidate any remaining stale cache entries ===");
    root spawn CascadeInvalidate();
}
