"""CI fleet liveness demo with typed host and job relationships."""

node Fleet {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has classification: str = "UNKNOWN_STOP";
    has queued_jobs: int = 0;
}

node Listener {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has online: bool = True;
    has one_job_mode: bool = True;
    has jobs_completed: int = 0;
}

node Job {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has queued: bool = True;
    has completed: bool = False;
    has runner_id: int = 0;
}

edge Hosts {
    has role: str = "";
}

edge Assigned {
    has queue: str = "";
    has attempt: int = 0;
}

walker LivenessAudit {
    has restored_runner: int = 1;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_fleet with Fleet entry {
        print(f"fleet {here.title}: {here.classification}, "
              f"{here.queued_jobs} queued jobs");
        visit [->:Hosts:->] else {
            disengage;
        }
    }

    can inspect_listener with Listener entry {
        state = "online/idle" if here.online else "offline";
        print(f"{here.title}: {state}");

        if here.available {
            visit [->:Assigned:->] else {
                print(f"{here.title}: no assigned one-job generation");
                disengage;
            }
            here.online = True;
            here.jobs_completed += 1;
            print(f"{here.title}: one-job restart returned online/idle");
        } else {
            print(f"{here.title}: listener unavailable; restart evidence required");
            disengage;
        }
    }

    can process_job with Job entry {
        if here.queued {
            here.queued = False;
            here.completed = True;
            here.runner_id = self.restored_runner;
            print(f"{here.title}: completed by runner {here.runner_id}");
        } else {
            print(f"{here.title}: already processed");
        }

        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    fleet = Fleet(
        title="pc-ci trusted fleet",
        year=2026,
        classification="LISTENER_RESTART_FAILED",
        queued_jobs=2
    );

    ci1 = Listener(title="pc-ci-1", year=2026, available=True, online=True);
    ci2 = Listener(title="pc-ci-2", year=2026, available=True, online=True);
    ci3 = Listener(title="pc-ci-3", year=2026, available=False, online=False);

    job0 = Job(title="trusted-executor-pack-0", year=2026, runner_id=0);
    job1 = Job(title="trusted-executor-pack-1", year=2026, runner_id=0);

    root ++> fleet;
    fleet +>:Hosts(role="ci-linux"):+> ci1;
    fleet +>:Hosts(role="ci-linux"):+> ci2;
    fleet +>:Hosts(role="ci-linux"):+> ci3;

    ci1 +>:Assigned(queue="trusted-executor-pack-0", attempt=1):+> job0;
    ci2 +>:Assigned(queue="trusted-executor-pack-1", attempt=1):+> job1;

    root spawn LivenessAudit();
}

