"""Factory zone patrol: monitor temperature and smoke sensors across zones.

One monitoring routine handles both sensor types via a union trigger, prints
each reading as nominal or alert, and the walker summarizes the alert list
at the end.
"""

node Sensor {
    has label: str = "";
    has reading: float = 0.0;
    has unit: str = "";

    def is_alert() -> bool;
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    override def is_alert() -> bool {
        return self.celsius > 75.0;
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    override def is_alert() -> bool {
        return self.ppm > 50.0;
    }
}

node Zone {
    has name: str = "";
}

walker Patrol {
    has alerts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Zone entry {
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        if here.is_alert() {
            label = f"[ALERT] {here.label} reading {here.celsius}C"
                if isinstance(here, TempSensor)
                else f"[ALERT] {here.label} reading {here.ppm}ppm";
            print(label);
            self.alerts.append(label);
        } else {
            msg = f"nominal: {here.label} at {here.celsius}C"
                if isinstance(here, TempSensor)
                else f"nominal: {here.label} at {here.ppm}ppm";
            print(msg);
        }
    }
}

with entry {
    zone_a = Zone(name="Zone A");
    zone_b = Zone(name="Zone B");
    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="Boiler-1", celsius=91.5);
    zone_a ++> SmokeSensor(label="Vent-1", ppm=12.0);
    zone_b ++> TempSensor(label="Boiler-2", celsius=62.0);
    zone_b ++> SmokeSensor(label="Vent-2", ppm=73.0);

    patrol = Patrol();
    root spawn patrol;

    print("--- Alert summary ---");
    if len(patrol.alerts) == 0 {
        print("All sensors nominal.");
    } else {
        print(f"{len(patrol.alerts)} alert(s):");
        for alert_label in patrol.alerts {
            print(alert_label);
        }
    }
}

