"""City itinerary: stations connected to hotels and attractions.

A walker leaves each station, ignores hotels, and shortlists only those
attractions rated 4 stars or above. The remaining attractions form the
final itinerary.
"""

node Hotel {
    has name: str = "";
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

node Station {
    has label: str = "";
}

walker ItineraryPlanner {
    has picks: list = [];

    can start with Root entry {
        print("Planning itinerary across all stations...");
        visit [-->];
    }

    can curate with Station entry {
        print(f"--- {here.label} ---");
        picks_at_station = [];
        for child in [-->] {
            if isinstance(child, Attraction) and child.stars >= 4 {
                picks_at_station.append(child);
            }
        }
        if not picks_at_station {
            print("  no qualifying attractions");
        } else {
            for attraction in picks_at_station {
                self.picks.append(attraction);
                print(f"  + {attraction.name} ({attraction.stars}*)");
            }
        }
        visit [-->];
    }

    can summarize with Root exit {
        print("");
        print("Final itinerary:");
        if not self.picks {
            print("  (no attractions met the 4+ star bar)");
        } else {
            for stop in self.picks {
                print(f"  -> {stop.name} ({stop.stars}*)");
            }
        }
    }
}

with entry {
    central = Station(label="Central Station");
    harbor = Station(label="Harbor Station");
    old_town = Station(label="Old Town Station");
    root ++> central ++> harbor ++> old_town;

    central ++> Hotel(name="Grand Plaza");
    central ++> Attraction(name="Skyline Tower", stars=5);
    central ++> Attraction(name="City Museum", stars=4);
    central ++> Hotel(name="Budget Inn");

    harbor ++> Attraction(name="Lighthouse", stars=3);
    harbor ++> Attraction(name="Aquarium", stars=5);
    harbor ++> Hotel(name="Seaside Resort");

    old_town ++> Attraction(name="Cathedral", stars=4);
    old_town ++> Hotel(name="Heritage Lodge");
    old_town ++> Attraction(name="Street Market", stars=2);

    root spawn ItineraryPlanner();
}

"""Journal share-link grant toggle.

Demonstrates a walker that arms a READ grant on a note (so anyone with the
link can read it), and another walker that revokes the grant, returning
the note to owner-only access. A flag on the note itself surfaces the
transition in the printed output.
"""

node Note {
    has title: str = "";
    has body: str = "";
    has owner: str = "";
    has shared: bool = False;
}

walker GrantRead {
    has reader: str = "";

    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        here.shared = True;
        print(f"[GRANT] {here.title} is now shared (READ) "
              f"for {self.reader} | shared={here.shared}");
        visit [-->];
    }
}

walker RevokeRead {
    can start with Root entry {
        visit [-->];
    }

    can disarm with Note entry {
        here.shared = False;
        print(f"[REVOKE] {here.title} returned to owner-only "
              f"| shared={here.shared}");
        visit [-->];
    }
}

with entry {
    n1 = Note(title="Morning Pages", body="...", owner="alex");
    n2 = Note(title="Trip Recap", body="...", owner="alex");
    n3 = Note(title="Book List", body="...", owner="alex");
    root ++> n1 ++> n2 ++> n3;

    print("--- before grant ---");
    print(f"{n1.title} shared={n1.shared}");
    print(f"{n2.title} shared={n2.shared}");
    print(f"{n3.title} shared={n3.shared}");

    root spawn GrantRead(reader="bob");
    root spawn RevokeRead();

    print("--- after revoke ---");
    print(f"{n1.title} shared={n1.shared}");
    print(f"{n2.title} shared={n2.shared}");
    print(f"{n3.title} shared={n3.shared}");
}

"""Cycle-safe social proof extraction over typed graph relationships."""

node GraphEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has incoming_edge_type: str = "";
}

node SocialProofStep {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_title: str = "";
    has edge_type: str = "";
    has verb: str = "";
    has target_title: str = "";
}

edge SocialLink {
    has edge_type: str = "";
}

walker SocialProofExtractor {
    has candidate_title: str = "";
    has anchor_title: str = "";
    has edge_verbs: dict[str, str] = {};
    has seen_titles: list[str] = [];
    has steps: list[SocialProofStep] = [];
    has description: str = "";
    has previous_title: str = "";
    has stopped_on_cycle: bool = False;
    has confidence: float = 0.85;

    def resolve_verb(edge_name: str) -> str {
        mapped = self.edge_verbs.get(edge_name);
        if mapped is None {
            return edge_name;
        }
        return mapped;
    }

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can extract with GraphEntity entry {
        print("Visited " + here.title);

        if here.title in self.seen_titles {
            self.description = self.description + " -> [...]";
            self.stopped_on_cycle = True;
            print("Cycle policy: truncated with [...]");
            disengage;
        }

        self.seen_titles.append(here.title);

        if self.anchor_title == "" {
            self.anchor_title = here.title;
        }

        if self.previous_title != "" {
            edge_name = here.incoming_edge_type;
            verb = self.resolve_verb(edge_name);
            step = SocialProofStep(
                source_title=self.previous_title,
                edge_type=edge_name,
                verb=verb,
                target_title=here.title
            );
            self.steps.append(step);

            phrase = self.previous_title + " " + verb + " " + here.title;
            if self.description == "" {
                self.description = phrase;
            } else {
                self.description = self.description + ", then " + phrase;
            }
        }

        if here.title == self.candidate_title {
            if len(self.steps) == 0 {
                self.description = "directly related";
            }

            print("Social proof: " + self.description);
            print("Anchor=" + self.anchor_title + ", Candidate=" + self.candidate_title);
            print("Steps=" + str(len(self.steps)) + ", Confidence=" + str(self.confidence));

            for step in self.steps {
                print(
                    step.source_title
                    + " --[" + step.edge_type + "/" + step.verb + "]--> "
                    + step.target_title
                );
            }

            disengage;
        }

        self.previous_title = here.title;
        visit [->:SocialLink:->] else { disengage; }
    }

    can finish with exit {
        print("Social proof report: " + self.description);
    }
}

