"""JSONata letrec redesign: side-table lambda tags, O(n) escape walk on scope exit, and value-carried closures."""

node Scope {
    has name: str = "";
    has depth: int = 0;
}

node StoredLambda {
    has lambda_id: str = "";
    has body_hint: str = "";
    has recursive: bool = False;
}

node LambdaRef {
    has lambda_id: str = "";
}

node LambdaTag(LambdaRef) {
}

node Closure(LambdaRef) {
}

node ValueNode {
    has kind: str = "";
    has node_key: str = "";
}

edge ChildScope { }

edge Binds {
    has var_name: str = "";
}

edge SideTable { }

edge Holds { }

edge Nested { }

edge SelfRec { }

edge ResolvesTo { }

edge Captures { }

edge EscapedFrom { }

walker EscapeAnalyzer {
    has live_ids: list[str] = [];
    has visited_keys: list[str] = [];
    has visited_lambdas: list[str] = [];

    def seen_key(key: str) -> bool {
        for k in self.visited_keys {
            if k == key {
                return True;
            }
        }
        return False;
    }

    def mark_key(key: str) {
        self.visited_keys.append(key);
    }

    def seen_lambda(lid: str) -> bool {
        for k in self.visited_lambdas {
            if k == lid {
                return True;
            }
        }
        return False;
    }

    def mark_lambda(lid: str) {
        self.visited_lambdas.append(lid);
    }

    def record_id(lambda_id: str) {
        for existing in self.live_ids {
            if existing == lambda_id {
                return;
            }
        }
        self.live_ids.append(lambda_id);
    }

    can start with Root entry {
        visit [-->];
    }

    can enter_scope with Scope entry {
        if here.depth == 0 {
            visit [->:ChildScope:->] else {
                disengage;
            };
        } else {
            visit [->:EscapedFrom:->] else {
                disengage;
            };
        }
    }

    can walk_value with ValueNode entry {
        key = here.node_key;
        if key != "" {
            if self.seen_key(key) {
                disengage;
            }
            self.mark_key(key);
        }
        visit [->:Nested:->];
        visit [->:Holds:->];
    }

    can collect_tag with LambdaTag | Closure entry {
        self.record_id(here.lambda_id);
    }

    can resolve_closure with Closure entry {
        visit [->:ResolvesTo:->] else {
            disengage;
        };
    }

    can walk_lambda with StoredLambda entry {
        lid = here.lambda_id;
        if self.seen_lambda(lid) {
            disengage;
        }
        self.mark_lambda(lid);
        self.record_id(lid);
        visit [->:Captures:->] else {
            disengage;
        };
    }
}

walker ScopePopper {
    has preserve_ids: list[str] = [];
    has migrated_ids: list[str] = [];

    def should_preserve(lambda_id: str) -> bool {
        for pid in self.preserve_ids {
            if pid == lambda_id {
                return True;
            }
        }
        return False;
    }

    def mark_migrated(lambda_id: str) {
        for mid in self.migrated_ids {
            if mid == lambda_id {
                return;
            }
        }
        self.migrated_ids.append(lambda_id);
    }

    can start with Root entry {
        visit [-->];
    }

    can on_scope with Scope entry {
        if here.depth == 0 {
            visit [->:ChildScope:->] else {
                disengage;
            };
        } else {
            if here.depth == 1 {
                visit [->:SideTable:->] else {
                    disengage;
                };
            } else {
                disengage;
            }
        }
    }

    can migrate_lambda with StoredLambda entry {
        if self.should_preserve(here.lambda_id) {
            self.mark_migrated(here.lambda_id);
        }
        disengage;
    }
}

with entry {
    outer = Scope(name="outer", depth=0);
    inner = Scope(name="inner", depth=1);
    root ++> outer;
    outer +>:ChildScope:+> inner;

    side_lam = StoredLambda(
        lambda_id="f1",
        body_hint="function(){ $f() }",
        recursive=True
    );
    inner +>:SideTable:+> side_lam;
    side_lam +>:SelfRec:+> side_lam;

    tag = LambdaTag(lambda_id="f1");
    bind_cell = ValueNode(kind="bind", node_key="bind_f");
    inner +>:Binds(var_name="f"):+> bind_cell;
    bind_cell +>:Holds:+> tag;

    result = ValueNode(kind="array", node_key="escaped_result");
    elem = ValueNode(kind="elem", node_key="elem0");
    inner +>:EscapedFrom:+> result;
    result +>:Nested:+> elem;
    elem +>:Holds:+> tag;

    capt_env = ValueNode(kind="capture_env", node_key="captures");
    letrec_lam = StoredLambda(
        lambda_id="f1_body",
        body_hint="letrec self-call",
        recursive=True
    );
    carried = Closure(lambda_id="f1");
    elem +>:Nested:+> capt_env;
    capt_env +>:Holds:+> carried;
    carried +>:ResolvesTo:+> letrec_lam;
    letrec_lam +>:SelfRec:+> letrec_lam;
    letrec_lam +>:Captures:+> capt_env;

    analyzer = EscapeAnalyzer();
    root spawn analyzer;
    print(f"escape walk live ids: {analyzer.live_ids}");

    popper = ScopePopper(preserve_ids=analyzer.live_ids);
    root spawn popper;
    print(f"scope pop migrated ids: {popper.migrated_ids}");
}

