"""Awkward-schema catalog validator.

Models the v2 catalog API as a graph of tables, columns, keys, and
references. A walker performs the cascade-delete / invalidation /
dependency-ordering traversal that the issue describes, but expressed
in idiomatic Jac with typed edges instead of hand-rolled recursion
over id-keyed registries.
"""

node Column {
    has col_name: str = "";
    has col_type: str = "";
    has nullable: bool = True;
    has is_blob: bool = False;
}

node Table {
    has table_name: str = "";
    has arity: int = 0;
    has is_view: bool = False;
}

node Key {
    has key_name: str = "";
    has is_compound: bool = False;
}

node Schema {
    has schema_name: str = "";
}

edge HasColumn { }
edge HasKey { }
edge References { has on_delete: str = "RESTRICT"; }
edge OwnsTable { }

walker CatalogAuditor {
    has seen: list[str] = [];
    has cycle_detected: bool = False;
    has deleted_count: int = 0;
    has orphan_count: int = 0;
    has dead_ref_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Schema entry {
        print(f"[schema] {here.schema_name}");
        visit [->:OwnsTable:->];
    }

    can audit_table with Table entry {
        if here.table_name in self.seen {
            self.cycle_detected = True;
            print(f"  [cycle] table revisited: {here.table_name}");
            disengage;
        }
        self.seen.append(here.table_name);
        status = "VIEW" if here.is_view else "TABLE";
        print(f"  [{status}] {here.table_name} (arity={here.arity})");
        visit [->:HasColumn:->] else {
            visit [->:References:->];
        }
    }

    can audit_column with Column entry {
        kind = "BLOB" if here.is_blob else here.col_type;
        null_mark = "?" if here.nullable else "!";
        print(f"    - {here.col_name}: {kind}{null_mark}");
        visit [->:References:->] else {
            disengage;
        }
    }

    can chase_ref with Column | Table entry {
        target = [-->];
        if not target {
            self.dead_ref_count += 1;
            print(f"    [dead-ref] dangling reference from {here}");
            disengage;
        }
        visit target;
    }

    can catalog_key with Key entry {
        flag = "compound" if here.is_compound else "simple";
        print(f"  [key:{flag}] {here.key_name}");
        visit [-->] else { disengage; }
    }

    can purge with Schema entry {
        self.deleted_count = len([-->]);
        print(f"[purge] marking {self.deleted_count} owned tables invalid");
        for t in [->:OwnsTable:->] {
            del t;
            self.orphan_count += 1;
        }
        print(f"[purge] orphaned {self.orphan_count} table nodes");
    }
}

with entry {
    northwind = Schema(schema_name="northwind");
    awkward = Schema(schema_name="awkward");

    t_unicode = Table(table_name="Ünïcödé", arity=3);
    t_reserved = Table(table_name="select", arity=2);
    t_selfref = Table(table_name="employee", arity=5);
    t_mutual_a = Table(table_name="order_a", arity=4);
