    northwind +>:OwnsTable:+> t_unicode;
    northwind +>:OwnsTable:+> t_reserved;
    northwind +>:OwnsTable:+> t_selfref;
    northwind +>:OwnsTable:+> t_mutual_a;
    northwind +>:OwnsTable:+> t_mutual_b;
    northwind +>:OwnsTable:+> t_blob;
    northwind +>:OwnsTable:+> t_view;
    awkward +>:OwnsTable:+> t_high;

    c_unicode = Column(col_name="naïve", col_type="TEXT");
    c_reserved = Column(col_name="from", col_type="INT", nullable=False);
    c_blob = Column(col_name="payload", col_type="BLOB", nullable=False, is_blob=True);
    c_blob_opt = Column(col_name="thumb", col_type="BLOB");
    c_view_a = Column(col_name="total", col_type="NUMERIC");
    c_view_b = Column(col_name="label", col_type="TEXT");
    c_high_a = Column(col_name="col_000", col_type="INT", nullable=False);

    t_unicode +>:HasColumn:+> c_unicode;
    t_reserved +>:HasColumn:+> c_reserved;
    t_blob +>:HasColumn:+> c_blob;
    t_blob +>:HasColumn:+> c_blob_opt;
    t_view +>:HasColumn:+> c_view_a;
    t_view +>:HasColumn:+> c_view_b;
    t_high +>:HasColumn:+> c_high_a;

    k_emp = Key(key_name="pk_employee", is_compound=False);
    k_order = Key(key_name="pk_order", is_compound=True);
    t_selfref +>:HasKey:+> k_emp;
    t_mutual_a +>:HasKey:+> k_order;

    c_reserved +>:References(on_delete="RESTRICT"):+> c_unicode;
    c_unicode +>:References:+> c_reserved;
    c_blob +>:References:+> c_blob_opt;
    c_view_a +>:References:+> c_view_b;

    root ++> northwind ++> awkward;

    auditor = CatalogAuditor();
    root spawn auditor;
    print(
        f"audit done — seen={len(auditor.seen)} "
        f"cycle={auditor.cycle_detected} "
        f"dead_refs={auditor.dead_ref_count}"
    );

    purger = CatalogAuditor();
    northwind spawn purger;
    print(
        f"purge done — deleted={purger.deleted_count} "
        f"orphaned={purger.orphan_count}"
    );
}

