"""OLS pagination bug demo: descendants closure is silently truncated
to the first page (~500 records) because a walker over a fake OLS API
follows only the top-level ``href`` instead of ``_links.next.href``.

This program models the scenario natively in Jac:

* ``OlsClient`` is a tiny mock of the upstream ols-client ``get_paged``
  helper. It returns paginated HAL responses whose ``_links.next.href``
  is the only reliable way to walk pages.
* ``OntologyTerm`` nodes are the term records; an ``IsDescendantOf``
  typed edge encodes the closure relationship (the thing the
  ``reachable_from`` dynamic enum ultimately relies on).
* ``root`` holds the term we want to expand (``GO:0005575``), and the
  reachable terms live behind typed edges.
* ``LegacyDescendantsWalker`` reproduces the bug: it follows the wrong
  key (``_links.href``) so the pagination loop exits after page one
  and only the first ~page-size terms are ever collected.
* ``FixedDescendantsWalker`` shows the correct behavior: it walks pages
  via ``_links.next.href`` until exhausted, then reports the full
  closure size.

Run the file with ``jac run`` to see the two closures side by side.
"""

node OntologyTerm {
    has curie: str = "";
    has label: str = "";
}

edge IsDescendantOf {
    has page: int = 0;
}

node OlsClient {
    # Mock OLS HAL API. Each page contains ``page_size`` terms and a
    # ``_links.next.href`` pointer that the walker must follow. The
    # legacy ``_links.href`` field is always None -- this is exactly
    # what the upstream bug relies on.
    has term_curie: str = "";
    has total_terms: int = 0;
    has page_size: int = 0;

    def page_count() -> int {
        n = self.total_terms // self.page_size;
        if self.total_terms % self.page_size != 0 {
            n = n + 1;
        }
        return n;
    }

    def curies_for_page(page_num: int) -> list[str] {
        start = (page_num - 1) * self.page_size;
        end = start + self.page_size;
        if end > self.total_terms {
            end = self.total_terms;
        }
        if start >= self.total_terms {
            return [];
        }
        out: list[str] = [];
        i = start;
        while i < end {
            out.append(f"{self.term_curie}-d{i}");
            i = i + 1;
        }
        return out;
    }

    def next_href_for_page(page_num: int) -> str {
        if page_num < self.page_count() {
            return f"/api/ontologies/terms?page={page_num + 1}";
        }
        return "";
    }
}

# ---------------------------------------------------------------------------
# Legacy walker: reproduces the silent-truncation bug.
# Reads ``_links.href`` (always empty) instead of ``_links.next.href``.
# ---------------------------------------------------------------------------
walker LegacyDescendantsWalker {
    has collected: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can visit_client with OlsClient entry {
        page_num = 1;
        total_pages = here.page_count();
        while page_num <= total_pages {
            curies = here.curies_for_page(page_num);
            for c in curies {
                self.collected.append(c);
            }
            # BUG: the legacy ols_client reads ``_links.href`` here --
            # in OLS4 HAL it is always absent, so the walker should
            # stop after page one. We simulate that by only advancing
            # when a fake ``_links.href`` would be present, which is
            # never. Hence: only page 1 is collected.
            legacy_href = "";
            if not legacy_href {
                break;
            }
            page_num = page_num + 1;
        }
        print(f"[legacy] descendant closure size: {len(self.collected)}");
    }
}

# ---------------------------------------------------------------------------
# Fixed walker: follows ``_links.next.href`` and walks until exhausted.
# ---------------------------------------------------------------------------
walker FixedDescendantsWalker {
    has collected: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can visit_client with OlsClient entry {
        page_num = 1;
        total_pages = here.page_count();
        while page_num <= total_pages {
            curies = here.curies_for_page(page_num);
            for c in curies {
                self.collected.append(c);
            }
            page_num = page_num + 1;
        }
        print(f"[fixed] descendant closure size: {len(self.collected)}");
    }
}

with entry {
    # Mock the OLS GO closure: the real adapter returns 4,076
    # descendants for GO:0005575 but the legacy paginator only ever
    # walks page one (~500 terms).
    go_client = OlsClient(
        term_curie="GO:0005575", total_terms=4076, page_size=500
    );
    root ++> go_client;

    # Attach a typed-edge "view" of the closure: the seed term is
    # modeled as a descendant of root via an IsDescendantOf edge so the
    # graph intent is visible in the module. The closure itself is
    # computed at runtime by the walker; it does not require every
    # descendant node to pre-exist.
    seed = OntologyTerm(curie="GO:0005575", label="cellular component");
    root +>:IsDescendantOf(page=0):+> seed;

    legacy = LegacyDescendantsWalker();
    root spawn legacy;
    fixed = FixedDescendantsWalker();
    root spawn fixed;

    # The legacy walker dropped 4076 - 500 = 3576 terms silently.
    truncated = go_client.total_terms - len(legacy.collected);
    print(f"truncated terms (legacy): {truncated}");
    print(
        f"complete terms  (fixed): {len(fixed.collected)} of "
        f"{go_client.total_terms}"
    );
}

