"""Warehouse packing line: stations announce robots served; robots announce each station stop.

Models a three-station packing line where each station tracks which robot it has
served (boxes packed) and each robot tracks the stations it stopped at. A walker
walks the line, dispatching robots to stations and tallying stops/packs.
"""

node Station {
    has name: str = "";
    has boxes_packed: int = 0;
    has last_robot: str = "";

    def serve(robot_name: str) -> None {
        self.boxes_packed += 1;
        self.last_robot = robot_name;
        print(f"Station {self.name} announces: serving robot {robot_name} "
              f"(total packed: {self.boxes_packed})");
    }
}

node Robot {
    has name: str = "";
    has stops: int = 0;
    has stations_visited: list[str] = [];

    def stop_at(station: Station) -> None {
        self.stops += 1;
        self.stations_visited.append(station.name);
        print(f"Robot {self.name} announces: stopped at station {station.name} "
              f"(total stops: {self.stops})");
        station.serve(self.name);
    }
}

walker Dispatcher {
    has robot: Robot = Robot();

    can start with Root entry {
        print(f"Dispatcher dispatching robot {self.robot.name} onto the line");
        visit [-->];
    }

    can dispatch with Station entry {
        self.robot.stop_at(here);
        if here.name == "C" {
            visit [-->] else { disengage; }
        } else {
            visit [-->];
        }
    }
}

with entry {
    a = Station(name="A");
    b = Station(name="B");
    c = Station(name="C");
    root ++> a ++> b ++> c;

    r2 = Robot(name="R2");
    root spawn Dispatcher(robot=r2);
}

"""Build dependency audit: count total build minutes across a DAG of tasks,
ensuring each task is counted exactly once even when the graph contains
diamonds (tasks reachable by multiple paths)."""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

walker Auditor {
    # Per-walker duplicate guard. Walkers in jac 0.36 do not deduplicate
    # visits on diamond-shaped graphs, so we track visited tasks ourselves
    # and refuse to recurse from already-seen nodes. We also keep a small
    # lookup of minutes so the final summary doesn't have to re-walk.
    has seen: list = [];
    has minutes_map: dict = {};

    can start with Root entry {
        visit [-->] else { report self.totals(); }
    }

    can audit with Task entry {
        if here.name not in self.seen {
            self.seen.append(here.name);
            self.minutes_map[here.name] = here.minutes;
            print(f"[{here.minutes}m] {here.name}");
            visit [-->] else { report self.totals(); }
        }
        # else: already audited — do NOT recurse, do NOT count again.
    }

    def totals() -> dict {
        total = 0;
        for nm in self.seen {
            total += self.minutes_map.get(nm, 0);
        }
        return {"minutes": total, "count": len(self.seen), "tasks": list(self.seen)};
    }
}

with entry {
    # Diamond: shared lib "core" is needed by both "module_a" and "module_b",
    # and both of those are needed by "app". The auditor must count "core"
    # exactly once even though two paths reach it.
    core = Task(name="core", minutes=10);
    module_a = Task(name="module_a", minutes=25);
    module_b = Task(name="module_b", minutes=15);
    app = Task(name="app", minutes=5);

    root ++> core
        ++> module_a ++> core
        ++> module_b ++> core
        ++> app ++> module_a ++> module_b;

    auditor = Auditor();
    root spawn auditor;
    summary = auditor.totals();
    print(f"unique tasks audited: {summary['count']}");
    print(f"total build minutes: {summary['minutes']}");
    print(f"task list: {summary['tasks']}");
}

"""Lifecycle harness graph with typed dependencies and cycle detection."""

node LifecycleItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has lifecycle_state: str = "";
    has observation: str = "";
}

node Package(LifecycleItem) {
    has manifest_hash: str = "";
}

node Application(LifecycleItem) {
    has runtime: str = "";
}

node WorkProbe(LifecycleItem) {
    has command: str = "";
}

edge DependsOn {
    has phase: str = "";
}

walker LifecycleAudit {
    has steps: int = 0;
    has max_steps: int = 8;
    has seen_titles: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("starting packed lifecycle audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Package | Application | WorkProbe entry {
        if here.title in self.seen_titles {
            self.cycle_detected = True;
            print(f"cycle detected at {here.title}");
            disengage;
        }

        if self.steps >= self.max_steps {
            self.cycle_detected = True;
            print(f"depth guard stopped at {here.title}");
            disengage;
        }

        self.seen_titles.append(here.title);
        self.steps += 1;
        state_label = "available" if here.available else "blocked";
        print(f"{here.title}: {state_label}, {here.lifecycle_state}, {here.observation}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

with entry {
    app = Application(
        title="SQLite integration application",
        year=2025,
        available=True,
        lifecycle_state="ready",
        observation="http=200",
        runtime="node"
    );
    package = Package(
        title="packed zmdb product",
        year=2025,
        available=True,
        lifecycle_state="installed",
        observation="archive and dependencies measured",
        manifest_hash="sha256:product"
    );
    probe = WorkProbe(
        title="first SQL query",
        year=2025,
        available=True,
        lifecycle_state="complete",
        observation="rows=3",
        command="SELECT count(*)"
    );

    root ++> app;
    app +>:DependsOn(phase="package-install"):+> package;
    package +>:DependsOn(phase="startup-readiness"):+> probe;
    probe +>:DependsOn(phase="steady-state-handoff"):+> app;

    root spawn LifecycleAudit(max_steps=8);
}

"""Resource limits: reject pathological dependency closure, provenance cycles, and archive abuse before execution."""

node SemanticModel {
    has name: str = "";
    has assertion_count: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveBundle {
    has label: str = "";
    has max_entries: int = 100;
    has max_entry_bytes: int = 1048576;
    has max_total_bytes: int = 10485760;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveEntry {
    has entry_path: str = "";
    has byte_size: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }
edge ContainsEntry { has ordinal: int = 0; }
edge ProvenanceLink { has step: int = 0; }
edge Stop { }

walker DependencyAuditor {
    has target: str = "";
    has engaged: bool = False;
    has max_depth: int = 4;
    has max_closure: int = 8;
    has depth: int = 0;
    has _seen: list[str] = [];
    has count: int = 0;
    has rejected: bool = False;
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit with SemanticModel entry {
        if not self.engaged {
            if self.target != "" and here.name != self.target {
                visit [-->] else { disengage; };
            }
            self.engaged = True;
        }
        if self.rejected {
            disengage;
        }
        if here.name in self._seen {
            self.rejected = True;
            self.reason = f"dependency cycle at {here.name}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self._seen.append(here.name);
        self.count += 1;
        if self.count > self.max_closure {
            self.rejected = True;
            self.reason = f"closure exceeds {self.max_closure} models";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if self.depth > self.max_depth {
            self.rejected = True;
            self.reason = f"dependency depth exceeds {self.max_depth}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        print(f"  ok model {here.name} depth={self.depth} assertions={here.assertion_count}");
        child_depth = self.depth + 1;
        self.depth = child_depth;
        visit [->:DependsOn:->] else {
            if not self.rejected {
                print(f"ACCEPT: dependency closure {self.count} models within depth {self.max_depth}");
            }
        };
        parent_depth = self.depth - 1;
        self.depth = parent_depth;
        visit [->:Stop:->] else { };
    }
}

walker ProvenanceAuditor {
    has target: str = "";
    has engaged: bool = False;
    has max_depth: int = 5;
    has depth: int = 0;
    has _seen: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can trace with SemanticModel entry {
        if not self.engaged {
            if self.target != "" and here.name != self.target {
                visit [-->] else { disengage; };
            }
            self.engaged = True;
        }
        if self.rejected {
            disengage;
        }
        if here.name in self._seen {
            self.rejected = True;
            self.reason = f"provenance cycle at {here.name}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if self.depth > self.max_depth {
            self.rejected = True;
            self.reason = f"provenance depth exceeds {self.max_depth}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self._seen.append(here.name);
        print(f"  ok provenance step={self.depth} artifact={here.name}");
        child_depth = self.depth + 1;
        self.depth = child_depth;
        visit [->:ProvenanceLink:->] else {
            if not self.rejected {
                print(f"ACCEPT: provenance chain depth {self.depth} within limit {self.max_depth}");
            }
        };
        parent_depth = self.depth - 1;
        self.depth = parent_depth;
        visit [->:Stop:->] else { };
    }
}

walker ArchiveVerifier {
    has target_label: str = "";
    has engaged: bool = False;
    has max_entries: int = 5;
    has max_entry_bytes: int = 1000;
    has max_total_bytes: int = 5000;
    has entries_seen: int = 0;
    has bytes_total: int = 0;
    has normalized_paths: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";
    has bundle_label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect with ArchiveBundle entry {
        if not self.engaged {
            if self.target_label != "" and here.label != self.target_label {
                visit [-->] else { disengage; };
            }
            self.engaged = True;
            self.bundle_label = here.label;
            self.max_entries = here.max_entries;
            self.max_entry_bytes = here.max_entry_bytes;
            self.max_total_bytes = here.max_total_bytes;
            print(f"=== archive audit: {self.bundle_label} ===");
        }
        visit [->:ContainsEntry:->] else {
            if not self.rejected {
                print(f"ACCEPT: archive {self.bundle_label} ({self.entries_seen} entries, {self.bytes_total} bytes)");
            }
        };
        visit [->:Stop:->] else { };
    }

    can scan with ArchiveEntry entry {
        if self.rejected {
            disengage;
        }
        path = here.entry_path;
        if path.startswith("/") {
            self.rejected = True;
            self.reason = "absolute archive path rejected";
            print(f"REJECT: {self.reason} ({path})");
            disengage;
        }
        if "../" in path or path == ".." {
            self.rejected = True;
            self.reason = "path traversal rejected";
            print(f"REJECT: {self.reason} ({path})");
            disengage;
        }
        norm = path.lower();
        if norm in self.normalized_paths {
            self.rejected = True;
            self.reason = f"duplicate normalized path ({norm})";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if here.byte_size > self.max_entry_bytes {
            self.rejected = True;
            self.reason = f"entry exceeds {self.max_entry_bytes} bytes";
            print(f"REJECT: {self.reason} ({here.byte_size})");
            disengage;
        }
        next_count = self.entries_seen + 1;
        if next_count > self.max_entries {
            self.rejected = True;
            self.reason = f"entry count exceeds {self.max_entries}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        next_total = self.bytes_total + here.byte_size;
        if next_total > self.max_total_bytes {
            self.rejected = True;
            self.reason = f"total uncompressed exceeds {self.max_total_bytes}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self.normalized_paths.append(norm);
        self.entries_seen = next_count;
        self.bytes_total = next_total;
        print(f"  ok entry {path} ({here.byte_size} bytes)");
        visit [->:Stop:->] else { };
    }
}

with entry {
    core = SemanticModel(name="core", assertion_count=12, title="Core", year=2026);
    util = SemanticModel(name="util", assertion_count=8, title="Util", year=2026);
    schema = SemanticModel(name="schema", assertion_count=20, title="Schema", year=2026);
