"""Blast-radius review over a connected-type architecture graph.

Models the essential scenario from ggcdevs/pente3D.ai issue #25:
given a type X whose exported contract changed, find the downstream
modules Y/Z that reference it, classify them as pure or glue, and
report which consumers were left untested by the changeset.

The hand-rolled machinery the issue complains about (recursive parent
walks, manual cascade invalidation, per-consumer query loops) is
replaced by a walker over typed edges.
"""

node Module {
    has name: str = "";
    has kind: str = "pure";
    # Pure modules are covered by co-located Y.test.ts; glue modules
    # (render, net, ui) are covered only by Playwright e2e tests.
    has in_changeset: bool = False;
    has tests_touched: bool = False;
}

node Type {
    has name: str = "";
    has contract: str = "";
    # Snapshot of the type's exported signature/fields/methods/exports
    # BEFORE the commit. Diffed against post-commit to decide whether
    # the contract actually changed (the staleness filter from §Design).
    has contract_changed: bool = False;
}

edge References {
    has relation: str = "uses";
    # Creates / param / returns / field / extends / uses.
}

walker BlastRadius {
    has origin: str = "";
    has visited: list[str] = [];
    has pure_uncovered: list[str] = [];
    has glue_uncovered: list[str] = [];

    can start with Type entry {
        # Seed: remember the type whose contract changed.
        self.origin = here.name;
        self.visited = self.visited + [here.name];
        visit [->:References:->];
    }

    can audit with Module entry {
        # The change is "blasting" a module if neither the module nor
        # its tests appear in the changeset. This is the test-delta
        # cross-reference the issue describes.
        covered = here.in_changeset or here.tests_touched;
        if not covered {
            if here.kind == "pure" {
                self.pure_uncovered = self.pure_uncovered + [here.name];
            } else {
                self.glue_uncovered = self.glue_uncovered + [here.name];
            }
        }
        visit [-->];
    }

    can summarize with Root entry {
        # The single exit report: a question the agent must answer,
        # not an assertion the tool can't back up.
        print(
            f"Type {self.origin}'s contract changed; "
            f"consumers with no test delta in this change:"
        );
        has_pure = len(self.pure_uncovered) > 0;
        has_glue = len(self.glue_uncovered) > 0;
        pure_label = "(pure)" if has_pure else "(none)";
        glue_label = "(glue)" if has_glue else "(none)";
        pure_list = ", ".join(self.pure_uncovered) if has_pure else "—";
        glue_list = ", ".join(self.glue_uncovered) if has_glue else "—";
        print(f"  pure: {pure_list} {pure_label}");
        print(f"  glue: {glue_list} {glue_label}");
        if has_pure {
            print(
                "  Confirm each pure consumer is unaffected or covered "
                "by a co-located Y.test.ts delta."
            );
        }
        if has_glue {
            print(
                "  Glue consumers are Playwright-verified, not unit-"
                "tested: confirm an e2e still covers this path."
            );
        }
        disengage;
    }
}

with entry {
    # Architecture: a single type whose contract changed, with
    # downstream pure and glue consumers. Some consumers were also
    # touched in the changeset (so they are NOT flagged).
    scene_sync = Type(name="SceneSync", contract="engine:Scene", contract_changed=True);

    sync_engine = Module(name="SyncEngine", kind="pure", in_changeset=True, tests_touched=True);
    scene_view = Module(name="SceneView", kind="pure");
    render_loop = Module(name="RenderLoop", kind="glue");
    net_io = Module(name="NetIO", kind="glue", in_changeset=True, tests_touched=False);
    ui_panel = Module(name="UIPanel", kind="glue");

    scene_sync +>:References(relation="creates"):+> sync_engine;
    scene_sync +>:References(relation="field"):+> scene_view;
    scene_sync +>:References(relation="param"):+> render_loop;
    scene_sync +>:References(relation="returns"):+> net_io;
    scene_sync +>:References(relation="uses"):+> ui_panel;
    root ++> scene_sync;

    b = BlastRadius();
    scene_sync spawn b;
    root spawn b;
}

"""GatiGo roadmap loop-gate traversal.

Models the GatiGo web loop engineering roadmap (#12) as a graph of
issues connected by ``Blocks`` edges (a later gate cannot unlock until
the earlier behavior gate resolves) and ``BelongsTo`` edges (an issue
sits inside one of three execution loops). A walker marches through
the dependency DAG, skipping ``#15`` until it resolves, and reports
which loop is currently the "next unblocked" milestone for the
coordinator to pick up.
"""

# ---------- node archetypes ----------

node Issue {
    has title: str = "";
    has number: int = 0;
    has resolved: bool = False;
    has is_gate: bool = False;
    has loop_index: int = -1;
}

node Loop {
    has loop_name: str = "";
    has loop_index: int = 0;
}

# ---------- typed edges ----------

edge Blocks {
    # An issue blocks another until it resolves.
    has reason: str = "";
}

edge BelongsTo {
    # An issue belongs to a loop.
}

# ---------- walker ----------

walker RoadmapAuditor {
    has next_issue: str = "";
    has next_loop: int = -1;
    has next_loop_name: str = "";

    can start with Root entry {
        # Step into every loop group.
        visit [-->];
    }

    can scan_loops with Loop entry {
        # Record the current loop we're traversing, then walk into its issues.
        self.next_loop_name = here.loop_name;
        self.next_loop = here.loop_index;
        visit [->:BelongsTo:->];
    }

    can audit with Issue entry {
        # #15 is a blocking investigation, not a feature gate — skip it
        # explicitly until it resolves (mirrors the rule "do not collect
        # or interpret Gate 0 behavior until #15 resolves").
        if here.number == 15 {
            if not here.resolved {
                print(f"[skip] #{here.number} {here.title} — travel-time "
                      f"investigation still open");
            } else {
                print(f"[ok]   #{here.number} {here.title} — resolved, "
                      f"collecting Gate 0 behavior now");
            }
            return;
        }

        # Only behavior gates can unlock the next loop, and only if
        # the gate itself is resolved.
        if here.is_gate {
            label = "READY" if here.resolved else "BLOCKED";
            print(f"[{label}] gate #{here.number} {here.title} "
                  f"(loop {here.loop_index})");
            if not here.resolved {
                self.next_issue = f"#{here.number} {here.title}";
                self.next_loop = here.loop_index;
                self.next_loop_name = f"Loop {here.loop_index}";
            }
            return;
        }

        # Plain implementation tasks: report and keep walking.
        status = "done" if here.resolved else "todo";
        print(f"[{status}] #{here.number} {here.title}");
    }
}

# ---------- demo wiring ----------

with entry {
    # Loops in execution order.
    loop0 = Loop(loop_name="Loop 0 — activation", loop_index=0);
    loop1 = Loop(loop_name="Loop 1 — collaboration", loop_index=1);
    loop2 = Loop(loop_name="Loop 2 — decision", loop_index=2);

    # Issues per loop, with resolved status reflecting the issue body.
    # Each issue carries its own loop_index so the auditor can report it
    # without relying on a back-walk through a typed edge.
    i7   = Issue(title="Green CI and coordinator environment",
                 number=7,  resolved=True,  loop_index=0);
    i8   = Issue(title="Candidate selection and share-intent fake door",
                 number=8,  resolved=True,  loop_index=0);
    i15  = Issue(title="Travel-time accuracy investigation",
                 number=15, resolved=False, loop_index=0);
    i9   = Issue(title="Gate 0: recommendation activation",
                 number=9,  is_gate=True,  resolved=False, loop_index=0);
    i2   = Issue(title="Persistent room and share link",
                 number=2,  resolved=False, loop_index=1);
    i3   = Issue(title="Guest departure-station response",
                 number=3,  resolved=False, loop_index=1);
    i10  = Issue(title="Gate 1: room sharing and guest response",
                 number=10, is_gate=True,  resolved=False, loop_index=1);
    i4   = Issue(title="Confirm place and map handoff",
                 number=4,  resolved=False, loop_index=2);
    i11  = Issue(title="Gate 2: confirmation and navigation handoff",
                 number=11, is_gate=True,  resolved=False, loop_index=2);

    # BelongsTo: every issue sits inside exactly one loop.
    loop0 +>:BelongsTo:+> i7;
    loop0 +>:BelongsTo:+> i8;
    loop0 +>:BelongsTo:+> i15;
    loop0 +>:BelongsTo:+> i9;
    loop1 +>:BelongsTo:+> i2;
    loop1 +>:BelongsTo:+> i3;
    loop1 +>:BelongsTo:+> i10;
    loop2 +>:BelongsTo:+> i4;
    loop2 +>:BelongsTo:+> i11;

    # Blocks: a behavior gate blocks the next loop's gate from
    # being considered "ready".
    i9 +>:Blocks(reason="Loop 1 cannot start until Gate 0 resolves"):+> i10;
    i10 +>:Blocks(reason="Loop 2 cannot start until Gate 1 resolves"):+> i11;

    # Hang the loops off root in execution order.
    root ++> loop0 ++> loop1 ++> loop2;

    print("=== GatiGo roadmap audit ===");
    auditor = RoadmapAuditor();
    root spawn auditor;
    print("");
    if auditor.next_issue != "" {
        print(f"Coordinator stops at: {auditor.next_issue} "
              f"(inside {auditor.next_loop_name})");
    } else {
        print("Coordinator stops at: no unresolved gate — all loops clear");
    }
}

"""Online store checkout: typed products with kind-specific shipping rules.

One ``Checkout`` walker visits each ``Product`` and dispatches via a
union ability per concrete type, so the same routine reacts correctly
to paper books, digital books, electronics, and clothing.
"""

node Product {
    has name: str = "";
    has price: float = 0.0;
}

node PaperBook(Product) {
    has weight_lbs: float = 0.0;

    def shipping_cost() -> float {
        # Flat $3 plus $1 per pound.
        return 3.0 + self.weight_lbs;
    }

    def kind_label() -> str {
        return "Paper book";
    }
}

node DigitalBook(Product) {
    has file_size_mb: float = 0.0;

    def shipping_cost() -> float {
        # No physical shipping for digital goods.
        return 0.0;
    }

    def kind_label() -> str {
        return "Digital book";
    }
}

node Electronics(Product) {
    has warranty_months: int = 0;

    def shipping_cost() -> float {
        # Fragile handling surcharge on top of a $7 base.
        return 7.0 + 2.5;
    }

    def kind_label() -> str {
        return "Electronics";
    }
}

node Clothing(Product) {
    has size: str = "";

    def shipping_cost() -> float {
        # Lightweight flat rate.
        return 4.0;
    }

    def kind_label() -> str {
        return f"Clothing (size {self.size})";
    }
}

walker Checkout {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has lines: list[str] = [];

    can start with Root entry {
        print("=== Checkout ===");
        visit [-->];
    }

    can bill with PaperBook | DigitalBook | Electronics | Clothing entry {
        line = here.kind_label();
        cost = here.price + here.shipping_cost();
        self.subtotal += here.price;
        self.shipping += here.shipping_cost();
        self.lines.append(f"{line}: ${here.price:.2f} + ship ${here.shipping_cost():.2f} = ${cost:.2f}");
        visit [-->];
    }
}

with entry {
    root ++> PaperBook(name="The Pragmatic Programmer", price=29.99, weight_lbs=1.2)
        ++> DigitalBook(name="Jac by Example", price=14.99, file_size_mb=8.4)
        ++> Electronics(name="USB-C Hub", price=49.99, warranty_months=24)
        ++> Clothing(name="Crewneck Tee", price=22.50, size="M");

    cart = root spawn Checkout();

    print("\n--- Itemized receipt ---");
    for ln in cart.lines {
        print(ln);
    }
    print(f"Subtotal: ${cart.subtotal:.2f}");
    print(f"Shipping: ${cart.shipping:.2f}");
    print(f"Total:    ${cart.subtotal + cart.shipping:.2f}");
}

