"""TDF manifest traversal: model manifest/segment/integrity/policy as a graph
and walk it with a verifier walker that mirrors the cascading verification the
issue's hand-rolled code repeats four times."""

# ── Node archetypes ─────────────────────────────────────────────────────────

node TdfManifest {
    has root_signature: str = "";
    has payload_key: str = "";
}

node IntegrityRow {
    has segment_name: str = "";
    has hash_b64: str = "";
    has expected_len: int = 16;
}

edge HasRow {
    has order: int = 0;
}

node Segment {
    has name: str = "";
    has plaintext: str = "";
    has gmac_b64: str = "";
}

edge BelongsTo { }

node PolicyBody {
    has raw_json: str = "{}";
}

edge PoliciesSegment { }

# ── Walker: cascade-verify the whole manifest ───────────────────────────────

walker Verifier {
    has report_lines: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        print("=== Manifest verifier ===");
        visit [-->];
    }

    can verify with TdfManifest entry {
        self.report_lines.append(f"manifest rootSig={here.root_signature[:8]}... key={here.payload_key[:4]}...");
        # Manifest has two typed-edge fan-outs we must walk in order.
        visit [->:HasRow:->];
    }

    can check_row with IntegrityRow entry {
        # Cycle-safe: IntegrityRow has no outgoing typed edges, so the
        # visit [...] else branch always fires and we disengage cleanly.
        if here.expected_len != 16 {
            self.report_lines.append(f"REJECT row {here.segment_name}: hash not 16 bytes");
            disengage;
        }
        self.report_lines.append(f"row[{here.segment_name}] hash={here.hash_b64[:8]}... len=16");
        visit [-->] else { disengage; }
    }

    can check_segment with Segment entry {
        # Constant-time-compare stand-in: just confirm both sides decoded.
        ok = here.gmac_b64 != "" and here.plaintext != "";
        status = "OK" if ok else "BAD";
        self.report_lines.append(f"segment[{here.name}] gmac={here.gmac_b64[:8]}... -> {status}");
        # Segments carry policy bodies via a typed edge.
        visit [->:PoliciesSegment:->];
    }

    can check_policy with PolicyBody entry {
        self.report_lines.append(f"policy body raw={here.raw_json}");
        visit [-->] else { disengage; }
    }
}

# ── Demo wiring ─────────────────────────────────────────────────────────────

with entry {
    manifest = TdfManifest(
        root_signature="deadbeefcafebabe0011223344556677",
        payload_key="pk_abcd1234"
    );

    # Two integrity rows (one bad — too short).
    row0 = IntegrityRow(segment_name="seg-0", hash_b64="AAAA", expected_len=16);
    row1 = IntegrityRow(segment_name="seg-1", hash_b64="BBBB", expected_len=8);

    # Segments with their GMAC tags.
    seg0 = Segment(name="seg-0", plaintext="hello", gmac_b64="gmac0abc");
    seg1 = Segment(name="seg-1", plaintext="world", gmac_b64="gmac1def");

    # Policy body attached to the first segment only.
    policy = PolicyBody(raw_json='{"dataAttributes":[{"attribute":"fqn/x"}]}');

    # Wire the graph: root -> manifest -> rows; segments join manifest via
    # BelongsTo; policy joins segment via PoliciesSegment.
    root ++> manifest;
    manifest +>:HasRow(order=0):+> row0;
    manifest +>:HasRow(order=1):+> row1;
    manifest +>:BelongsTo:+> seg0;
    manifest +>:BelongsTo:+> seg1;
    seg0 +>:PoliciesSegment:+> policy;

    v = Verifier();
    root spawn v;

    for line in v.report_lines {
        print(line);
    }
    print(f"verified {len(v.report_lines)} entities across the manifest");
}

"""Online store checkout: polymorphic receipt over paper books, digital books, electronics, and clothing.

One checkout routine reacts to each product's concrete kind via a union
ability and prints an itemized receipt (subtotal, shipping, total).
"""

# ----- Product archetypes -----
node Product {
    has name: str = "";
    has price: float = 0.0;

    def shipping_cost() -> float {
        return 0.0;
    }

    def kind_label() -> str {
        return "Product";
    }
}

node PaperBook(Product) {
    has weight_lb: float = 1.0;

    override def shipping_cost() -> float {
        return 0.99 + 0.75 * self.weight_lb;
    }

    override def kind_label() -> str {
        return "PaperBook";
    }
}

node DigitalBook(Product) {
    has drm: str = "watermark";

    override def shipping_cost() -> float {
        return 0.0;
    }

    override def kind_label() -> str {
        return "DigitalBook";
    }
}

node Electronics(Product) {
    has warranty_months: int = 12;
    has fragile: bool = True;

    override def shipping_cost() -> float {
        base = 7.50;
        if self.fragile {
            base = base + 3.25;
        }
        return base;
    }

    override def kind_label() -> str {
        return "Electronics";
    }
}

node Clothing(Product) {
    has size: str = "M";

    override def shipping_cost() -> float {
        return 4.25;
    }

    override def kind_label() -> str {
        return "Clothing";
    }
}

# ----- Cart container -----
node Cart {
    has label: str = "Cart";
    has items: list = [];
}

# ----- Checkout walker -----
walker Checkout {
    has subtotal: float = 0.0;
    has shipping: float = 0.0;
    has lines: list = [];

    can start with Root entry {
        visit [-->];
    }

    can open_cart with Cart entry {
        print(f"=== Receipt for {here.label} ===");
        visit [-->];
    }

    # Single union ability: fires for any concrete product kind.
    # Every product in the union exposes shipping_cost() and kind_label()
    # (declared on the Product base), so the body only touches those.
    can ring_up with PaperBook | DigitalBook | Electronics | Clothing entry {
        ship = here.shipping_cost();
        kind = here.kind_label();
        line_total = here.price + ship;

        self.subtotal = self.subtotal + here.price;
        self.shipping = self.shipping + ship;
        self.lines.append((kind, here.name, here.price, ship, line_total));

        print(f"  [{kind}] {here.name}: "
              + f"${here.price:.2f} + ${ship:.2f} ship = ${line_total:.2f}");
        visit [-->];
    }
}

with entry {
    cart = Cart(
        label="Order #1042",
        items=[
            PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.4),
            DigitalBook(name="Refactoring (eBook)", price=24.00, drm="drm-free"),
            Electronics(name="USB-C Hub", price=49.99, warranty_months=24, fragile=True),
            Clothing(name="Logo Hoodie", price=55.00, size="L"),
            PaperBook(name="Crafting Interpreters", price=32.50, weight_lb=2.1)
        ]
    );

    root ++> cart
        ++> PaperBook(name="The Pragmatic Programmer", price=29.95, weight_lb=1.4)
        ++> DigitalBook(name="Refactoring (eBook)", price=24.00, drm="drm-free")
        ++> Electronics(name="USB-C Hub", price=49.99, warranty_months=24, fragile=True)
        ++> Clothing(name="Logo Hoodie", price=55.00, size="L")
        ++> PaperBook(name="Crafting Interpreters", price=32.50, weight_lb=2.1);

    root spawn Checkout();
}

"""Delivery route audit: walk the depots and flag which cargo legs qualify for dispatch (2-8 tonnes)."""

node Route {
    has title: str = "";
    has weight: float = 0.0;

    def qualifies() -> bool {
        return self.weight >= 2.0 and self.weight <= 8.0;
    }
}

node Depot {
    has name: str = "";
    has region: str = "";
}

edge Serves { has leg_id: str = ""; }

walker DispatchAuditor {
    can start with Root entry {
        visit [-->];
    }

    can arrive with Depot entry {
        print(f"Depot: {here.name} ({here.region})");
        visit [-->];
    }

    can audit with Route entry {
        status = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"  [{status}] leg={here.title} weight={here.weight}t");
    }
}

with entry {
    north = Depot(name="North Hub", region="Northwest");
    south = Depot(name="South Hub", region="Southeast");

    root ++> north ++> Route(title="North->West A", weight=5.5);
    north ++> Route(title="North->West B", weight=1.2);
    north ++> Route(title="North->East", weight=8.0);

    root ++> south ++> Route(title="South->East", weight=3.0);
    south ++> Route(title="South->West", weight=9.5);
    south ++> Route(title="South->North", weight=0.5);

    root spawn DispatchAuditor();
}

"""Breadth-sidecar lineage: model CoinGecko Top-100 constituent snapshots
retained per accepted DATA PING so that the exact constituents can be replayed.

A Lineage walker walks parent -> child relationships through the breadcrumb
chain (Ping -> Sidecar -> Page -> Row), accumulating replay evidence on a
typed `report` field. A separate Replay walker re-derives the aggregate
breadth ratio and membership hash from the retained sidecar, proving the
lineage is self-sufficient without re-fetching."""

node DataPing {
    has label: str = "";
    has accepted: bool = True;
    has breadcrumb_id: str = "";
}

node Sidecar {
    has artifact_bytes: int = 0;
    has row_count: int = 0;
    has content_sha256: str = "";
    has path: str = "";
    has retrieved_at: str = "";
    has frozen_at: str = "";
    has replayability: str = "PASS";
}

node CoinPage {
    has page_label: str = "";
    has page_timestamp: str = "";
    has method_id: str = "";
    has filter_id: str = "";
    has raw_count: int = 0;
    has deduped_count: int = 0;
    has included_count: int = 0;
    has excluded_count: int = 0;
    has advancers: int = 0;
    has decliners: int = 0;
    has unchanged: int = 0;
    has median_return: float = 0.0;
    has membership_sha256: str = "";
    has breadth_ratio: float = 0.0;
}

node ConstituentRow {
    has coin_id: str = "";
    has symbol: str = "";
    has rank: int = 0;
    has market_cap: float = 0.0;
    has price: float = 0.0;
