"""Repository retention audit: model branch/ruleset retention classes and walk them.

This demo mirrors the B4 hygiene scenario: entities (branches, rulesets, evidence
records) are nodes; their relationships (PROTECTS, KEEPS, SUPERSEDES) are typed
edges; a walker traverses the retention graph classifying each ref into a
retention class. The walker terminates safely on dead-ends, never loops on the
supersession cycle, and emits one summary per spawned audit.
"""

node Branch {
    has name: str = "";
    has merged: bool = False;
    has active: bool = False;
    has historical: bool = False;
}

node Ruleset {
    has name: str = "";
    has active: bool = False;
}

node Evidence {
    has note: str = "";
}

edge Protects {
    has since: str = "";
}

edge Keeps {
    has reason: str = "";
}

edge Supersedes {
    has by_commit: str = "";
}

walker Auditor {
    has audit_log: list = [];
    has seen: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Branch entry {
        if here.name in self.seen {
            visit [-->];
        } else {
            self.seen = self.seen + [here.name];
            cls = "HUMAN_REVIEW";
            if here.active {
                cls = "KEEP_PROTECTED_CURRENT";
            } elif here.historical {
                cls = "KEEP_EVIDENCE";
            } elif here.merged {
                cls = "SAFE_DELETE";
            }
            line = f"BRANCH {here.name} -> {cls}";
            self.audit_log = self.audit_log + [line];
            print(line);
            visit [-->];
        }
    }

    can audit_ruleset with Ruleset entry {
        cls = "HUMAN_REVIEW";
        if here.active {
            cls = "KEEP_PROTECTED_CURRENT";
        } else {
            cls = "SAFE_DELETE";
        }
        line = f"RULESET {here.name} -> {cls}";
        self.audit_log = self.audit_log + [line];
        print(line);
        visit [-->];
    }

    can record with Evidence entry {
        line = f"EVIDENCE {here.note} -> KEEP_EVIDENCE";
        self.audit_log = self.audit_log + [line];
        print(line);
        visit [-->];
    }

    can summarize with Root entry {
        print("--- AUDIT SUMMARY ---");
        for log_line in self.audit_log {
            print(log_line);
        }
        print(f"total entries: {len(self.audit_log)}");
    }
}

with entry {
    main_branch = Branch(name="main", merged=True, active=True);
    pr59_branch = Branch(name="pr-59-governed-replacement", merged=True, active=False);
    pr56_branch = Branch(name="pr-56-dependabot", merged=False, active=False, historical=True);
    pr13_branch = Branch(name="pr-13-slice-001", merged=False, active=False, historical=True);
    rs_pr55 = Ruleset(name="Protect PR55 task branch", active=False);
    rs_pr_privacy = Ruleset(name="Protect PR-privacy-cleanup-002 task branch", active=False);
    canon_evidence = Evidence(note="canon references cc345bb");
    slice_evidence = Evidence(note="slice-001 historical candidate");

    root ++> main_branch;
    root ++> pr59_branch;
    root ++> pr56_branch;
    root ++> pr13_branch;
    root ++> rs_pr55;
    root ++> rs_pr_privacy;
    root ++> canon_evidence;
    root ++> slice_evidence;

    rs_pr55 +>:Protects(since="2024"):+> pr59_branch;
    rs_pr_privacy +>:Protects(since="2024"):+> pr56_branch;
    canon_evidence +>:Keeps(reason="merged HEAD"):+> main_branch;
    slice_evidence +>:Keeps(reason="unmerged candidate"):+> pr13_branch;
    pr59_branch +>:Supersedes(by_commit="cc345bb"):+> pr56_branch;

    auditor = Auditor();
    root spawn auditor;
}

