"""Deterministic scenario content hash walker.

Models the algorithm in `internal/scenario/hash.go` as an idiomatic Jac graph
traversal. The scenario directory is a node archetype, each walkable filesystem
entry (file or directory) is another node archetype, and the parent/child
relationship is a typed edge carrying the entry kind. A walker descends the
tree, skips the excluded entries (`hints/`, `solution.md`, `solution.sh`),
records a canonical byte slice per entry into a SHA-256 accumulator, and
reports the final digest (truncated to 12 hex chars, mirroring `Short`).
"""

import hashlib;

# ---- Domain archetypes ---------------------------------------------------

# The scenario root: a real scenario directory on disk.
node Scenario {
    has name: str = "";
    has root_path: str = "";
}

# A walkable filesystem entry. Files carry a payload; directories have none.
node Entry {
    has rel_path: str = "";
    has kind: str = "f";
    has exec_bit: bool = False;
    has payload: bytes = b"";
}

# Typed edge: parent directory -> child entry.
edge Contains { }

# ---- Accumulator + walker ------------------------------------------------

walker Hasher {
    # Visitor bookkeeping: the running digest material as canonical strings,
    # a cycle guard set (jac 0.36.1 walkers have no built-in visited set),
    # and a flag tracking whether the excluded hints subtree was seen.
    has digest_material: list[str] = [];
    has seen: set[str] = set();
    has skipped_hint_tree: bool = False;

    can start with Root entry {
        # Spawning on `root` and then visiting typed `Scenario` nodes mirrors
        # `ContentHash` being called with a scenario directory.
        visit [-->];
    }

    can descend with Scenario entry {
        # Begin the deterministic walk from this scenario's children.
        visit [-->];
    }

    can record with Entry entry {
        # Skip excluded entries (hints tree, solution files).
        if here.rel_path == "hints" or here.rel_path.startswith("hints/") {
            self.skipped_hint_tree = True;
            return;
        }
        if here.rel_path == "solution.md" or here.rel_path == "solution.sh" {
            return;
        }
        # Cycle policy: jac 0.36.1 walkers have no built-in visited set, so
        # an explicit guard is required to keep the walk finite on cyclic
        # graphs (e.g. a directory with a self-loop).
        if here.rel_path in self.seen {
            return;
        }
        self.seen.add(here.rel_path);

        # Canonical encoding matches the Go record format:
        #   directory: rel_path + \x00 + "d" + \x00
        #   file:      rel_path + \x00 + class + \x00 + 8B BE length + bytes
        if here.kind == "d" {
            self.digest_material.append(here.rel_path + "\x00d\x00");
        } else {
            cls = "x" if here.exec_bit else "f";
            length_hex = len(here.payload).to_bytes(8, "big").hex();
            self.digest_material.append(
                here.rel_path + "\x00" + cls + "\x00" + length_hex +
                here.payload.hex()
            );
        }

        # Continue walking: directories cascade, files are leaves.
        if here.kind == "d" {
            visit [-->] else { disengage; }
        }
    }
}

# ---- Determinism helpers ------------------------------------------------

def short_hash(digest_hex: str) -> str {
    # Mirrors `Short(h string) string` from hash.go: first 12 lowercase hex
    # chars; raise on malformed input (programming error, not runtime input).
    if len(digest_hex) < 64 {
        raise ValueError("Short(): digest shorter than 64 hex chars");
    }
    return digest_hex[:12].lower();
}

def compute_digest(material: list[str]) -> str {
    # Stand-in for sha256.Sum256 over the concatenated record bytes.
    h = hashlib.sha256();
    for piece in material {
        h.update(piece.encode("utf-8", errors="replace"));
    }
    return h.hexdigest();
}

# ---- Wiring the demo scenario -------------------------------------------

with entry {
    scn = Scenario(name="hashscn", root_path="/scenarios/hashscn");
    root ++> scn;

    # Build a tiny fixture matching the golden-vector shape from issue 09:
    #   scenario.yaml    (participates)
    #   checks/x.sh      (participates, exec bit off in embed.FS)
    #   image/Dockerfile (participates)
    #   hints/01.md      (excluded subtree)
    #   solution.md      (excluded)
    #   solution.sh      (excluded)
    e_yaml = Entry(rel_path="scenario.yaml", kind="f", payload=b"id: hashscn\n");
    e_check = Entry(rel_path="checks/x.sh", kind="f", payload=b"#!/bin/sh\necho ok\n");
    e_image_dir = Entry(rel_path="image", kind="d");
    e_docker = Entry(rel_path="image/Dockerfile", kind="f", payload=b"FROM scratch\n");
    e_hints = Entry(rel_path="hints", kind="d");
    e_hint_file = Entry(rel_path="hints/01.md", kind="f", payload=b"hint text\n");
    e_solution_md = Entry(rel_path="solution.md", kind="f", payload=b"secret\n");
    e_solution_sh = Entry(rel_path="solution.sh", kind="f", payload=b"#!/bin/sh\n");

    scn +>:Contains:+> e_yaml;
    scn +>:Contains:+> e_check;
    scn +>:Contains:+> e_image_dir;
    e_image_dir +>:Contains:+> e_docker;
    scn +>:Contains:+> e_hints;
    e_hints +>:Contains:+> e_hint_file;
    scn +>:Contains:+> e_solution_md;
    scn +>:Contains:+> e_solution_sh;

    # Spawn the deterministic walker on the graph rooted at `root`.
    hasher = Hasher();
    root spawn hasher;

    # Property checks (a)-(d) from issue 09 §4.
    # (a) hints/01.md and solution files must NOT be in the digest material.
    joined = "\n".join(hasher.digest_material);
    assert "hints/01.md" not in joined, "hints subtree leaked into digest";
    assert "solution.md" not in joined, "solution.md leaked into digest";
    assert "solution.sh" not in joined, "solution.sh leaked into digest";
    assert hasher.skipped_hint_tree, "hints/ directory entry was not skipped";

    # (b) build-relevant files (scenario.yaml, checks/x.sh, image/Dockerfile)
    # MUST appear in the digest material.
    assert "scenario.yaml" in joined, "scenario.yaml missing from digest";
    assert "checks/x.sh" in joined, "checks/x.sh missing from digest";
    assert "image/Dockerfile" in joined, "image/Dockerfile missing from digest";

    # (c) renaming a file would change `rel_path`, which feeds the digest.
    # (documented by the byte format, not asserted here against the static graph.)

    # (d) chmod +x on `checks/x.sh` only changes the hash on os-backed FS;
    # the embed.FS used in the cookbook keeps scripts non-executable, so
    # the recorded class is `f`. We assert that here.
    assert "x.sh\x00f\x00" in joined, "checks/x.sh class must be 'f' for embed.FS";

    digest_hex = compute_digest(hasher.digest_material);
    tag = "debugdungeon/scn-" + short_hash(digest_hex) + ":" + short_hash(digest_hex);
    print(f"digest (hex): {digest_hex}");
    print(f"short tag:    {tag}");
    print(f"entries hashed: {len(hasher.digest_material)}");
}

