"""Warehouse inventory audit: assign stable ids, persist items, and dump graph."""

node Item {
    has title: str = "";
    has sku: str = "";
    has stock: int = 0;
    has item_id: int = 0;
    has persisted: bool = False;
}

edge StockedAt {
    has aisle: str = "";
}

walker Auditor {
    has next_id: int = 1;
    has log: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Item entry {
        if here.item_id == 0 {
            here.item_id = self.next_id;
            self.next_id = self.next_id + 1;
        }
        if not here.persisted {
            print(f"[PERSIST] id={here.item_id} sku={here.sku} title={here.title} stock={here.stock}");
            here.persisted = True;
        }
        self.log = self.log + [here.item_id];
        visit [-->];
    }
}

walker Dumper {
    can start with Root entry {
        kids = [-->];
        self.dump_node("root", 0, kids);
    }

    can dump with Item entry {
        kids = [-->];
        self.dump_node(here.title, 1, [here]);
        self.dump_node("child", 2, kids);
        visit [-->];
    }

    def dump_node(label: str, depth: int, frontier: list) -> None {
        indent = "  " * depth;
        prefix = f"{indent}- {label}";
        if len(frontier) == 0 {
            print(f"{prefix}: (none)");
            return;
        }
        for node in frontier {
            print(f"{prefix}: item_id={node.item_id} sku={node.sku} stock={node.stock}");
        }
    }
}

with entry {
    a = Item(title="Hex Bolts", sku="HB-10", stock=240);
    b = Item(title="Wing Nuts", sku="WN-04", stock=88);
    c = Item(title="Washers", sku="WS-12", stock=512);
    root ++> a +>:StockedAt(aisle="A1"):+> b +>:StockedAt(aisle="A2"):+> c;

    root spawn Auditor();
    root spawn Dumper();
}

"""Flight network: priced legs normalize against the scout's peak fare report."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has ticket_price: float = 0.0;
    has origin_code: str = "";
    has dest_code: str = "";

    def fare_fraction(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.ticket_price / peak;
    }
}

walker Scout {
    has peak_fare: float = 0.0;
    has fare_report: list[float] = [];
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can sweep with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            report leg.ticket_price;
            self.fare_report.append(leg.ticket_price);
            if leg.ticket_price > self.peak_fare {
                self.peak_fare = leg.ticket_price;
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");
    bos = Airport(code="BOS");

    root ++> jfk;

    leg_jfk_lax = FlightLeg(
        ticket_price=450.0, origin_code="JFK", dest_code="LAX"
    );
    jfk +>:leg_jfk_lax:+> lax;

    leg_lax_ord = FlightLeg(
        ticket_price=320.0, origin_code="LAX", dest_code="ORD"
    );
    lax +>:leg_lax_ord:+> ord;

    leg_ord_bos = FlightLeg(
        ticket_price=580.0, origin_code="ORD", dest_code="BOS"
    );
    ord +>:leg_ord_bos:+> bos;

    leg_bos_jfk = FlightLeg(
        ticket_price=275.0, origin_code="BOS", dest_code="JFK"
    );
    bos +>:leg_bos_jfk:+> jfk;

    leg_jfk_ord = FlightLeg(
        ticket_price=510.0, origin_code="JFK", dest_code="ORD"
    );
    jfk +>:leg_jfk_ord:+> ord;

    scout = Scout();
    root spawn scout;

    peak = scout.peak_fare;
    print(f"Scout peak fare: ${peak} (reported {len(scout.fare_report)} legs)");

    legs = [
        leg_jfk_lax,
        leg_lax_ord,
        leg_ord_bos,
        leg_bos_jfk,
        leg_jfk_ord,
    ];
    for leg in legs {
        share = leg.fare_fraction(peak);
        print(
            f"{leg.origin_code}->{leg.dest_code} "
            f"${leg.ticket_price} is {share:.2%} of top fare"
        );
    }
}

