"""Incremental support propagation over a typed building graph with cycle detection."""

node SupportNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has walk_token: int = 0;
    has supported: bool = False;
    has dirty: bool = True;
}

node TerrainCell(SupportNode) { }

node BuildPiece(SupportNode) { }

edge Contains { }

edge Supports {
    has cost: int = 1;
}

walker SupportPropagator {
    has token: int = 1;
    has cycle_found: bool = False;
    has cycle_count: int = 0;

    can start with Root entry {
        print("support propagation started");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can propagate with TerrainCell | BuildPiece entry {
        if here.walk_token == self.token {
            self.cycle_found = True;
            self.cycle_count = self.cycle_count + 1;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            here.walk_token = self.token;
            here.supported = True;
            here.dirty = False;
            print(f"supported: {here.title}");
            visit [->:Supports:->] else {
                disengage;
            }
        }
    }
}

