"""Bounded conductor graph preserving review context and detecting timeout cycles."""

node Ticket {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has claim_limit: int = 0;
}

node Attempt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "";
    has repair_iterations: int = 0;
}

node Finding {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reviewer: str = "";
    has verdict: str = "";
    has excerpt: str = "";
}

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has timed_out: bool = False;
}

edge Contains { }
edge ReviewEvidence { }
edge RetryContext { }
edge RuntimeChild { }

walker Conductor {
    has seen_titles: list[str] = [];
    has claims: int = 0;
    has max_claims: int = 0;

    can begin with Root entry {
        print("bounded conductor run");
        visit [->:Contains:->] else { disengage; };
    }

    can inspect_ticket with Ticket entry {
        if (here.title in self.seen_titles) {
            print(f"cycle detected at {here.title}");
            disengage;
        }
        self.seen_titles.append(here.title);
        self.max_claims = here.claim_limit;
        print(f"ticket {here.title}: claim limit {here.claim_limit}");
        visit [->:Contains:->] else { disengage; };
    }

    can inspect_attempt with Attempt entry {
        if (here.title in self.seen_titles) {
            print(f"cycle detected at {here.title}");
            disengage;
        }
        if (self.claims >= self.max_claims) {
            print("claim budget exhausted");
            disengage;
        }
        self.seen_titles.append(here.title);
        self.claims += 1;
        print(f"claim {self.claims}: {here.title} ({here.status})");
        visit [->:ReviewEvidence:->];
        visit [->:RetryContext:->];
        visit [->:RuntimeChild:->];
    }

    can inspect_finding with Finding entry {
        if (here.title in self.seen_titles) {
            print(f"reused finding detected at {here.title}");
            disengage;
        }
        self.seen_titles.append(here.title);
        if (here.verdict != "approved") {
            print(f"UNTRUSTED REVIEW EVIDENCE [{here.reviewer}]: {here.excerpt}");
        }
    }

    can inspect_process with Process entry {
        if (here.title in self.seen_titles) {
            print(f"timeout descendant cycle at {here.title}");
            disengage;
        }
        self.seen_titles.append(here.title);
        if (here.timed_out) {
            print(f"runtime timeout: {here.title}; repair is bounded");
        } else {
            print(f"runtime child: {here.title}");
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    ticket = Ticket(
        title="Issue 6",
        year=2024,
        available=True,
        claim_limit=2
    );

    first = Attempt(
        title="attempt-1",
