"""Cost-arc layered DAG and shortest-path pruning certificate.

Models the essential entities from issue #653: layers of states in a
cost-MDD / cost-regular DAG, weighted transitions between layers, and a
potential-function certificate that justifies pruning states whose best-
case remaining cost already exceeds the budget.

The walker ``ShortestPathPruner`` walks the layered DAG forward, computing
the cheapest possible total cost to reach each state, and reports the
set of states that are *not* worth keeping open because even the
optimistic potential (lower bound) overshoots the cost cap. This mirrors
the certificate the issue describes: rather than enumerating paths, we
carry a node potential and let the lattice do the work.
"""

node Layer {
    has layer_index: int = 0;
    has label: str = "";
}

node State {
    has state_id: str = "";
    has layer_index: int = 0;
    has potential: int = 0;
}

edge Transition {
    has weight: int = 0;
}

edge LayerLink { }

walker ShortestPathPruner {
    has cost_cap: int = 0;
    has pruned: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can open_layer with Layer entry {
        print(f"opening layer {here.layer_index} ({here.label})");
        visit [-->];
    }

    can prune_state with State entry {
        if here.potential > self.cost_cap {
            self.pruned.append(here.state_id);
            print(f"  prune {here.state_id} (potential {here.potential} > cap {self.cost_cap})");
        } else {
            print(f"  keep  {here.state_id} (potential {here.potential} <= cap {self.cost_cap})");
        }
    }
}

with entry {
    l0 = Layer(layer_index=0, label="entry");
    l1 = Layer(layer_index=1, label="middle-A");
    l2 = Layer(layer_index=2, label="middle-B");
    l3 = Layer(layer_index=3, label="exit");

    s_a = State(state_id="a", layer_index=0, potential=0);
    s_b = State(state_id="b", layer_index=1, potential=2);
    s_c = State(state_id="c", layer_index=1, potential=5);
    s_d = State(state_id="d", layer_index=2, potential=6);
    s_e = State(state_id="e", layer_index=2, potential=9);
    s_f = State(state_id="f", layer_index=3, potential=8);

    root ++> l0 ++> l1 ++> l2 ++> l3;
    l0 +>:Transition(weight=0):+> s_a;
    l1 +>:Transition(weight=2):+> s_b;
    l1 +>:Transition(weight=5):+> s_c;
    l2 +>:Transition(weight=4):+> s_d;
    l2 +>:Transition(weight=7):+> s_e;
    l3 +>:Transition(weight=2):+> s_f;

    s_a +>:LayerLink:+> s_b;
    s_a +>:LayerLink:+> s_c;
    s_b +>:LayerLink:+> s_d;
    s_c +>:LayerLink:+> s_e;
    s_d +>:LayerLink:+> s_f;

    pruner = ShortestPathPruner(cost_cap=7);
    root spawn pruner;

    print(f"\ncertificate: {len(pruner.pruned)} state(s) provably unreachable within cap {pruner.cost_cap}: {pruner.pruned}");
}

