"""Bounded AEGIS import traversal that prevents cyclic dependency hangs."""

node AegisModule {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has invalidated: bool = False;
}

node IndexSymbol {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has line: int = 0;
}

edge Imports {
    has required: bool = True;
}

edge Defines {
    has line: int = 0;
}

walker AegisIndexer {
    has depth: int = 0;
    has max_depth: int = 4;
    has inspected: int = 0;
    has cycle_guard_triggered: bool = False;

    can begin with Root entry {
        print("Starting bounded AEGIS import indexing");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with AegisModule entry {
        self.inspected += 1;

        if here.available == False {
            here.invalidated = True;
            print(f"Invalidated unavailable module: {here.title}");
            disengage;
        }

        if self.depth >= self.max_depth {
            self.cycle_guard_triggered = True;
            print(f"Cycle/depth guard stopped traversal at: {here.title}");
            disengage;
        }

        print(f"Indexed {here.title} at depth {self.depth}");
        self.depth += 1;
        visit [->:Imports:->] else {
            disengage;
        }
    }
}

with entry {
    core = AegisModule(title="aegis.core", year=2024);
    loader = AegisModule(title="aegis.loader", year=2024);
    parser = AegisModule(title="aegis.parser", year=2024);
    symbol = IndexSymbol(title="AEGIS_INDEXER", year=2024, line=9);

    root ++> core;
    core +>:Imports(required=True):+> loader;
    loader +>:Imports(required=True):+> parser;
    parser +>:Imports(required=True):+> core;
    core +>:Defines(line=9):+> symbol;

    root spawn AegisIndexer(max_depth=4);
}

"""Integration graph demo with typed relationships, reachability, and cycle detection."""

node Repository {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
}

node Primitive {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
}

node Consumer {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
}

edge Relation {
    has kind: str = "";
}

walker IntegrationAuditor {
    can start with Root entry {
        print("Starting integration reachability audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Repository | Primitive | Consumer entry {
        if here.visited {
            print(f"[cycle] revisited {here.title}");
            disengage;
        } else {
            here.visited = True;
            status = "available" if here.available else "invalidated";
            print(f"[{status}] {here.title} ({here.key})");
            visit [->:Relation:->] else {
                disengage;
            }
        }
    }
}

