        title="External skill runtime",
        year=2024
    );

    root ++> repository;
    repository +>:Relation(kind="provides"):+> graph;
    graph +>:Relation(kind="composes"):+> retrieval;
    retrieval +>:Relation(kind="feeds"):+> wikiskill;
