"""Environment variable resolution with cycle detection.

Models the JENKINS-33239 scenario where a variable like
LD_LIBRARY_PATH=$ORACLE_HOME/lib:$LD_LIBRARY_PATH gets expanded
recursively until it runs out of memory. Here we express the
definition graph as typed edges between Variable nodes and let a
walker traverse it. Without a cycle guard the walker would loop
forever (the original bug); with the guard it terminates and
reports the offending cycle.
"""

node Variable {
    has name: str = "";
    has value: str = "";
}

# A definition edge says: this variable's R-value references that
# variable (e.g. LD_LIBRARY_PATH -> LD_LIBRARY_PATH is the self-cycle
# that triggers the bug).
edge Refs {
    has var_name: str = "";
}

walker Resolver {
    has max_depth: int = 32;
    has seen: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can expand with Variable entry {
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"[HALT] depth>{self.max_depth} at {here.name} -- runaway recursion (the JENKINS-33239 bug)");
            disengage;
        }
        if here.name in self.seen {
            cycle = self.seen[-1] + " -> " + here.name;
            print(f"[CYCLE] {cycle}");
            disengage;
        }
        self.seen.append(here.name);
        print(f"resolve {here.name} = {here.value} (path={' -> '.join(self.seen)})");
        # Follow every typed reference this variable makes in its R-value.
        visit [->:Refs:->];
    }
}

with entry {
    # Build the graph: LD_LIBRARY_PATH references both ORACLE_HOME/lib
    # and itself -- the self-reference is exactly the JENKINS-33239 case.
    path = Variable(name="LD_LIBRARY_PATH", value="$ORACLE_HOME/lib:$LD_LIBRARY_PATH");
    oracle = Variable(name="ORACLE_HOME", value="/opt/oracle");
    home = Variable(name="HOME", value="/root");

    # Typed edges carry the referenced variable's name as payload.
    path +>:Refs(var_name="ORACLE_HOME"):+> oracle;
    path +>:Refs(var_name="LD_LIBRARY_PATH"):+> path;
    oracle +>:Refs(var_name="HOME"):+> home;

    root ++> path;

    print("--- scenario 1: graph with self-cycle (the reported bug) ---");
    Resolver() spawn root;

    print("");
    print("--- scenario 2: same walker, no self-cycle, terminates cleanly ---");
    safe = Variable(name="PATH", value="path1:$HOME");
    safe +>:Refs(var_name="HOME"):+> home;
    root ++> safe;
    Resolver() spawn safe;
}

"""Model a planner that finalizes an intake issue after verifying its sub-issues."""

node IntakeIssue {
    has title: str = "";
    has number: int = 0;
    has plan: bool = True;
    has planned: bool = False;
    has trigger_label: str = "";
    has plan_comment_published: bool = False;
    has subissues_verified: bool = False;
}

node SubIssue {
    has title: str = "";
    has number: int = 0;
    has verified: bool = False;
}

edge IntakePlan {
    has role: str = "intake";
}

edge Decomposes {
    has role: str = "sub-issue";
}

walker Planner {
    has verified_count: int = 0;
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        print("walking the intake issue graph");
        visit [->:IntakePlan:->] else { disengage; }
    }

    can inspect with IntakeIssue entry {
        if self.depth >= self.max_depth {
            print(f"depth limit reached at #{here.number}; plan stays queued");
            disengage;
        }
        self.depth += 1;
        print(f"inspecting #{here.number}: {here.title}");
        if here.plan_comment_published && here.subissues_verified {
            here.planned = True;
            here.plan = False;
            if here.trigger_label != "" {
                print(f"consumed trigger label {here.trigger_label}");
                here.trigger_label = "";
            }
            print(f"#{here.number} is planned; plan label removed");
        } else {
            print(f"#{here.number} remains in the plan queue");
        }
        visit [->:Decomposes:->] else { disengage; }
    }

    can verify with SubIssue entry {
        if here.verified {
            self.verified_count += 1;
            print(f"verified sub-issue #{here.number}: {here.title}");
        } else {
            print(f"unverified sub-issue #{here.number}: {here.title}");
        }
    }
}

with entry {
    epic = IntakeIssue(
        title="Planner label transition",
        number=59,
        plan=True,
        planned=False,
        trigger_label="agent:planner:claude",
        plan_comment_published=True,
        subissues_verified=True
    );
    first = SubIssue(
        title="Add local planner transition",
        number=60,
        verified=True
    );
    second = SubIssue(
        title="Verify cloud parity",
        number=61,
        verified=True
    );

    root +>:IntakePlan(role="intake"):+> epic;
    epic +>:Decomposes:+> first;
    epic +>:Decomposes:+> second;

    root spawn Planner();

    print(
        f"final labels: plan={epic.plan}, "
        f"planned={epic.planned}, "
        f"trigger={epic.trigger_label}"
    );
}

"""Hiking trail: plain waypoints with no data, used purely as stops.

The trail is a chain of bare waypoints between a trailhead and a
summit. The waypoints carry no fields at all -- all the interesting
state (how many stops were made) lives on the hiker walker.
"""

node Waypoint { }

walker Hiker {
    has stops: int = 0;

    can start with Root entry {
        print("Leaving the trailhead");
        visit [-->];
    }

    can pass_through with Waypoint entry {
        self.stops += 1;
        print(f"Passed stop #{self.stops}");
        visit [-->];
