"""EAC benchmark graph: model the runtime/advisory/authority conditions and
walk the ablation matrix to surface blocked/escape/permit violations.

The issue hand-rolls dependency ordering across Baseline / DualDAG-Advisory
/ DualDAG-Authority conditions plus an evaluator-only ground-truth oracle.
We lift the relationship machinery to typed edges and let a walker traverse
them.
"""

node Condition {
    has label: str = "";
    has runs: int = 0;
    has bypassable: bool = False;
}

node SupportPolicy {
    has policy_id: str = "";
    has version: str = "";
    has fingerprint: str = "";
}

node Witness {
    has label: str = "";
    has admissible: bool = False;
    has stale: bool = False;
}

node GroundTruth {
    has label: str = "";
    has observed: bool = False;
}

# Edge archetypes: relationships that carry meaning in the protocol.
edge PolicyOf { }
edge WitnessOf { }
edge OracleOf { }
edge RunOf { }

walker Audit {
    has blocked: int = 0;
    has stale: int = 0;
    has bypass: int = 0;

    can start with Root entry {
        # Land on the policy first, then walk conditions via typed edges.
        visit [->:PolicyOf:->];
    }

    can pin with SupportPolicy entry {
        print(f"policy pinned: {here.policy_id} v{here.version}");
        visit [->:RunOf:->];
    }

    can sweep with Condition entry {
        here.runs += 1;
        if here.bypassable {
            self.bypass += 1;
            bypass_label = "BYPASS";
            print(f"[{bypass_label}] {here.label}: bypassable execution gate");
            visit [-->];
        } else {
            # Authority path: walk witness/admissibility via typed edge.
            visit [->:WitnessOf:->];
        }
    }

    can judge with Witness entry {
        if here.stale {
            self.stale += 1;
            admit_label = "ADMIT" if here.admissible else "REJECT";
            print(f"stale-witness {here.label}: {admit_label}");
        } elif not here.admissible {
            self.blocked += 1;
            print(f"blocked {here.label}: witness insufficient");
        }
        visit [-->];
    }

    can record with GroundTruth entry {
        # Oracle: independent ground truth, not visible to Authority.
        here.observed = True;
        print(f"oracle observed: {here.label}");
        visit [-->];
    }
}

with entry {
    # One frozen policy shared by both DualDAG variants.
    policy = SupportPolicy(
        policy_id="eac-primary",
        version="1.0.0",
        fingerprint="sha256:eac-primary-v1"
    );

    # Three conditions spanning the required ablation matrix.
    baseline = Condition(label="Baseline", bypassable=True);
    advisory = Condition(label="DualDAG-Advisory", bypassable=True);
    authority = Condition(label="DualDAG-Authority", bypassable=False);

    # Witnesses per condition: advisory admits stale, authority blocks.
    base_wit = Witness(label="baseline-wit", admissible=True, stale=False);
    adv_wit = Witness(label="advisory-wit", admissible=True, stale=True);
    auth_wit = Witness(label="authority-wit", admissible=False, stale=False);

    # Evaluator-only ground truth (the independent oracle).
    oracle = GroundTruth(label="evaluator-only");

    # Wire the graph: policy runs conditions, conditions hold witnesses,
    # the oracle sits alongside the rest of the topology.
    root +>:PolicyOf:+> policy;
    policy +>:RunOf:+> baseline +>:RunOf:+> advisory +>:RunOf:+> authority;
    baseline +>:WitnessOf:+> base_wit;
    advisory +>:WitnessOf:+> adv_wit;
    authority +>:WitnessOf:+> auth_wit;
    root +>:OracleOf:+> oracle;

    # Walk the protocol.
    auditor = Audit();
    root spawn auditor;

    print(
        f"summary: bypass={auditor.bypass} blocked={auditor.blocked} "
        f"stale={auditor.stale}"
    );
}

"""Plugin-build cycle detection modeled after Gradle issue #38843.

Models included plugin builds as nodes connected by ``includeBuild``
edges. The walker follows the edges and reports any back-edge it sees,
which is the situation that triggers Gradle's "A cycle has been detected
in the definition of plugin builds" error when Isolated Projects is on.
"""

node PluginBuild {
    has name: str = "";
}

edge IncludeBuild {
    has reason: str = "manual";
}

walker CycleDetector {
    has path: list[str] = [];
    has seen: list[str] = [];

    can begin with Root entry {
        self.path = [];
        self.seen = [];
        visit [-->];
    }

    can traverse with PluginBuild entry {
        if here.name in self.seen {
            print(f"CYCLE detected: {' -> '.join(self.path)} -> {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        self.path.append(here.name);
        visit [here ->:IncludeBuild:->];
    }
}

with entry {
    a := PluginBuild(name="dedebug");
    b := PluginBuild(name="dependency-analysis-gradle-plugin");
    c := PluginBuild(name="com.gradle.develocity");

    root +>:IncludeBuild(reason="pluginManagement"):+> a;
    a +>:IncludeBuild(reason="includeBuild('../b')"):+> b;
    b +>:IncludeBuild(reason="plugin coords"):+> c;
    c +>:IncludeBuild(reason="includeBuild('../b')"):+> b;

    root spawn CycleDetector();
}

