"""Orchard irrigation tour: a single crew routine services pumps and sprinklers alike.

Models an orchard where a maintenance crew walks the groves visiting irrigation
devices. Pumps and sprinklers share the same servicing routine via a union
trigger, which logs the device kind, idle hours, resets the counter, and
tracks total devices serviced across the tour.
"""

node Pump {
    has label: str = "";
    has idle_hours: int = 0;

    def kind() -> str {
        return "Pump";
    }
}

node Sprinkler {
    has label: str = "";
    has idle_hours: int = 0;

    def kind() -> str {
        return "Sprinkler";
    }
}

node Grove {
    has name: str = "";
}

walker Crew {
    has serviced: int = 0;

    can start with Root entry {
        print("Crew rolling out to the orchards");
        visit [-->];
    }

    # Union trigger: one routine handles Pump OR Sprinkler the same way.
    can service with Pump | Sprinkler entry {
        device_label = here.label;
        hours = here.idle_hours;
        kind_name = here.kind();
        self.serviced += 1;
        here.idle_hours = 0;
        print(f"[{kind_name}] {device_label} idled {hours}h -> serviced "
              f"(total: {self.serviced})");
        visit [-->];
    }

    can roll with Grove entry {
        print(f"-- passing through grove '{self}' --");
        visit [-->];
    }
}

with entry {
    north = Grove(name="North");
    south = Grove(name="South");
    root ++> north ++> south;

    north ++> Pump(label="Pump-A", idle_hours=14)
        ++> Sprinkler(label="Sprink-A", idle_hours=6);
