"""Kitchen line health inspection: check station temperatures and log every visit.

A single inspector walker runs two checks at every station: one flags any
station whose temperature is above 40 C as a violation, the other logs
every visit regardless of temperature. Both abilities fire at every
station using union triggers over the shared ``celsius`` field.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
    has kind: str = "";
}

walker Inspector {
    has station_count: int = 0;
    has violations: int = 0;

    can start with Root entry {
        print("Kitchen inspection starting...");
        visit [-->];
    }

    # Temperature check: flags anything above 40 C as a violation.
    # Union trigger so it fires on every station subtype equally.
    can check_temp with Station | Station entry {
        if here.celsius > 40.0 {
            self.violations += 1;
            print(f"  [VIOLATION] {here.kind} '{here.name}' at {here.celsius}C exceeds 40C limit");
        } else {
            print(f"  [ok] {here.kind} '{here.name}' at {here.celsius}C within limit");
        }
    }

    # Visit log: runs at every station, independent of temperature.
    can log_visit with Station | Station entry {
        self.station_count += 1;
        print(f"  -> visited station #{self.station_count}: {here.kind} '{here.name}'");
        visit [-->];
    }
}

with entry {
    grill = Station(name="Salamander", celsius=82.0, kind="grill");
    fryer = Station(name="Deep Fryer", celsius=175.0, kind="fryer");
    cold_prep = Station(name="Salad Bar", celsius=4.5, kind="cold-prep");
    pastry = Station(name="Chocolate Work", celsius=22.0, kind="cold-prep");

    root ++> grill ++> fryer ++> cold_prep ++> pastry;

    inspector = Inspector();
    root spawn inspector;

    print(f"\nInspection complete: visited {inspector.station_count} stations, "
          f"flagged {inspector.violations} violations");
}

"""Hybrid task viewer: drill into subtrees and walk back to parents."""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has parent: Task | None = None;
    has depth: int = 0;
    has expanded: bool = True;
}

node ViewerContext {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has focus: Task | None = None;
}

edge Contains {
    has order: int = 0;
}

edge Focuses {
    has mode: str = "subtree";
}

walker SubtreeViewer {
    has seen: list[Task] = [];

    can start with Root entry {
        print("ROOT CONTEXT");
        visit [-->] else { disengage; }
    }

    can enter with ViewerContext entry {
        print(f"open: {here.title}");
        visit [->:Focuses:->] else { disengage; }
    }

    can render with Task entry {
        if here in self.seen {
            print(f"cycle ignored at {here.title}");
            disengage;
        } else {
            self.seen.append(here);
            state = "open" if here.expanded else "collapsed";
            print(f"depth {here.depth}: {here.title} [{state}]");
            if here.expanded {
                visit [->:Contains:->] else { disengage; }
            } else {
                print(f"children hidden for {here.title}");
            }
        }
    }
}

walker ParentNavigator {
    has seen: list[Task] = [];

    can climb with Task entry {
        if here in self.seen {
            print(f"parent cycle ignored at {here.title}");
            disengage;
        } else {
            self.seen.append(here);
            parent_label = here.parent.title if here.parent is not None else "(root)";
            print(f"up: {here.title} -> {parent_label}");
            visit [<--] else { disengage; }
        }
    }
}

with entry {
    root_task = Task(title="Project Atlas", depth=0);
    build = Task(title="Build", parent=root_task, depth=1);
    sw_install = Task(title="sw-install", parent=build, depth=2);
    docs = Task(title="Write docs", parent=build, depth=2, expanded=False);
    tests = Task(title="Run tests", parent=sw_install, depth=3);

    root_view = ViewerContext(title="Project Atlas view", focus=root_task);

    root ++> root_view;
    root_view +>:Focuses(mode="subtree"):+> root_task;
    root_task +>:Contains(order=1):+> build;
    build +>:Contains(order=1):+> sw_install;
    build +>:Contains(order=2):+> docs;
    sw_install +>:Contains(order=1):+> tests;

    root spawn SubtreeViewer();
    sw_install spawn SubtreeViewer();
    sw_install spawn ParentNavigator();
}

