"""Data center clearance check.

Each server room posts the clearance level it requires. A technician
walking the corridor attempts to enter every room. If their clearance is
high enough they are admitted and continue deeper; if not, they are
denied and their walkthrough ends immediately. Report how many rooms
each technician reached before being turned away (or after completing
the corridor).
"""

node Room {
    has name: str = "";
    has required_clearance: int = 0;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied: bool = False;

    can start with Root entry {
        print(f"Technician {self.name} (clearance {self.clearance}) begins walkthrough");
        visit [-->] else { disengage; }
    }

    can attempt with Room entry {
        if self.denied {
            visit [-->] else { disengage; };
        }
        if self.clearance >= here.required_clearance {
            self.rooms_reached += 1;
            print(f"  {self.name} admitted to {here.name} (needs {here.required_clearance})");
            visit [-->] else { disengage; };
        } else {
            self.denied = True;
            print(f"  {self.name} DENIED at {here.name} (needs {here.required_clearance}, has {self.clearance})");
            disengage;
        }
    }
}

with entry {
