"""Dependency audit walker: walks the production dependency graph and flags
advisories. Mirrors `pnpm audit` behavior where vulnerable packages reach
the runtime through transitive parents that Dependabot can't bump directly."""

node Package {
    has name: str = "";
    has version: str = "";
    has available_fix: bool = True;
}

node Advisory {
    has severity: str = "";
    has vulnerable_below: str = "";
    has patched: str = "";
    has path: str = "";
}

edge DependsOn {
    has transitive: bool = False;
}

edge Flagged {
    has reason: str = "";
}

walker Audit {
    has production_only: bool = True;
    has findings: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_deps with Package entry {
        next_versions: list = [v.version for v in [-->]];
        if here.available_fix {
            print(f"ok: {here.name}@{here.version} reachable");
        } else {
            print(f"STUCK: {here.name}@{here.version} no upstream PR");
            self.findings.append({
                "name": here.name,
                "version": here.version,
                "blocked": True
            });
        }
        visit [-->];
    }

    can collect_advisory with Advisory entry {
        flagged = [-->];
        if len(flagged) > 0 {
            print(f"ADVISORY[{here.severity}] {here.path} -> fix {here.patched}");
            self.findings.append({
                "advisory": here.path,
                "severity": here.severity,
                "patched": here.patched
            });
        }
        visit [-->];
    }
}

walker BumpFloor {
    has floor_version: str = "3.3.17";

    can start with Root entry {
        print(f"Raising floor to nanoid@{self.floor_version} via overrides");
        visit [-->];
    }

    can rewrite with Package entry {
        if here.name == "nanoid" and here.available_fix {
            print(f"Override: nanoid {here.version} -> {self.floor_version}");
        }
        visit [-->];
    }
}

with entry {
    next_app = Package(name="next", version="14.0.0", available_fix=True);
    postcss = Package(name="postcss", version="8.4.0", available_fix=True);
    nanoid = Package(name="nanoid", version="3.3.16", available_fix=False);
    nanoid_patched = Package(name="nanoid", version="3.3.17", available_fix=True);

    adv_nanoid = Advisory(
        severity="high",
        vulnerable_below="3.3.17",
        patched="3.3.17",
        path="next>postcss>nanoid"
    );
    adv_mod = Advisory(
        severity="moderate",
        vulnerable_below="0.0.0",
        patched="0.0.0",
        path="transitive>moderate"
    );

    root ++> next_app +>:DependsOn:+> postcss +>:DependsOn:+> nanoid;
    root ++> adv_nanoid +>:Flagged:+> nanoid;
    root ++> adv_mod;

    auditor = Audit(production_only=True);
    root spawn auditor;
    print(f"findings: {auditor.findings}");

    bumper = BumpFloor(floor_version="3.3.17");
    root spawn bumper;

    print("After override, postcss now resolves to patched nanoid:");
    fixed = Package(name="nanoid", version="3.3.17", available_fix=True);
    postcss del --> nanoid;
    postcss +>:DependsOn:+> fixed;
    checker = Audit(production_only=True);
    root spawn checker;
    print(f"post-fix findings: {checker.findings}");
}
