"""Policy blast-radius gate: walk a service graph from a changed component,
collect every service affected through typed edges, and report the blast
radius plus which ones are still covered by policy."""

node Component {
    has name: str = "";
    has in_blast_radius: bool = True;
    has policy_covered: bool = False;
    has is_service: bool = True;
}

node Service {
    has name: str = "";
    has policy_covered: bool = False;
    has in_blast_radius: bool = True;
    has is_service: bool = True;
}

node Policy {
    has name: str = "";
    has standard: str = "";
}

edge Calls { has protocol: str = "http"; }
edge RunsOn { has runtime: str = ""; }
edge GuardedBy { has rule: str = ""; }

walker BlastRadius {
    has seen: list[str] = [];
    has hit_count: int = 0;
    has guarded_count: int = 0;

    can start with Root entry {
        print("Blast-radius scan starting from root");
        visit [->:Calls:->] else { disengage; }
    }

    can record with Service entry {
        guard = here.name in self.seen;
        if not guard {
            self.seen.append(here.name);
            self.hit_count += 1;
            tag = "IN" if here.in_blast_radius else "OUT";
            cover = "covered" if here.policy_covered else "uncovered";
            print(f"  reached [{tag}] {here.name} ({cover})");
        }
        if here.policy_covered {
            self.guarded_count += 1;
        }
        visit [->:Calls:->] else { disengage; }
    }
}

walker PolicyAudit {
    has hits: int = 0;
    has gaps: int = 0;

    can start with Root entry {
        print("Policy coverage audit");
        visit [-->] else { disengage; }
    }

    can inspect with Service entry {
        if here.policy_covered {
            print(f"  [OK] service {here.name} conforms to standard");
            self.hits += 1;
        } else {
            print(f"  [GAP] service {here.name} has no conforming policy");
            self.gaps += 1;
        }
    }

    can inspect_policy with Policy entry {
        print(f"  [POLICY] {here.name} (standard={here.standard})");
    }
}

with entry {
    auth = Service(name="auth", policy_covered=True);
    api = Service(name="api-gateway", policy_covered=True);
    orders = Service(name="orders", policy_covered=False);
    billing = Service(name="billing", policy_covered=True);
    reports = Service(name="reports", policy_covered=False);
    db = Service(name="postgres-primary", policy_covered=True);
    k8s = Service(name="k8s-cluster", in_blast_radius=False, policy_covered=True);

    root +>:Calls(protocol="grpc"):+> auth;
    auth +>:Calls:+> api;
    api +>:Calls:+> orders;
    orders +>:Calls:+> billing;
    billing +>:Calls:+> reports;
    reports +>:Calls:+> db;
    db +>:RunsOn(runtime="k8s"):+> k8s;

    p_opa = Policy(name="opa-authz", standard="authz/v1");
    p_sbom = Policy(name="sbom-emit", standard="spdx/v2");
    api +>:GuardedBy(rule="must emit OPA decision logs"):+> p_opa;
    auth +>:GuardedBy(rule="must ship SPDX SBOM"):+> p_sbom;

    print("--- Blast-radius walk from root ---");
    br = BlastRadius();
    root spawn br;
    print(f"\nFinal blast radius: {br.hit_count} services, "
          f"{br.guarded_count} policy-covered");

    print("\n--- Policy audit walk ---");
    pa = PolicyAudit();
    root spawn pa;
    print(f"\nAudit summary: {pa.hits} conformant, {pa.gaps} with gaps");
}

