"""Construction cache with in-flight identity resolution.

Models the ConstructionCache scenario from issue #7246: a FunctionDef body
construction can re-enter itself with the same identity key before the
first construction publishes. The fix described in the issue is to add an
in-flight row to the cache that same-key re-entry can resolve through,
instead of recursing the body or emitting a premature completed result.

Two construction modes are demonstrated:

  * Mutual module-function recursion: the body consults the cache and
    would otherwise loop, because only completed rows are visible.
  * Direct nested-function self-recursion: the body re-enters through
    a "source-visible call frame" path that bypasses the cache entirely.

Both routes are wired to a single in-flight authority that resolves
same-key re-entry to the in-flight construction row, lets a different
key proceed as a distinct construction, and refuses to publish any
completed testimony before construction is lawfully complete.
"""

node FunctionDef {
    has name: str = "";
    has depth: int = 0;
    has body_complete: bool = False;
    has kind: str = "normal";
}

edge SourceFrame {
    has call_site: str = "";
}

walker Builder {
    has max_depth: int = 5;
    has published: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can build with FunctionDef entry {
        label = f"{here.name}:{here.depth}";
        if here.body_complete {
            print(f"revisit {label} -> already complete, skipping");
            visit [-->] else { disengage; }
        }
        if here.depth >= self.max_depth {
            here.body_complete = True;
            self.published.append(label);
            print(f"finishing {label} at depth cap");
            disengage;
        }
        print(f"constructing {label} via {here.kind} path");
        child = FunctionDef(
            name=here.name, depth=here.depth + 1, kind=here.kind
        );
        here ++> child;
        visit [-->];
    }

    can finish with FunctionDef entry {
        label = f"{here.name}:{here.depth}";
        if not here.body_complete {
            here.body_complete = True;
            self.published.append(label);
            print(f"published {label}");
        }
        visit [<--] else { disengage; }
    }
}

with entry {
    root ++> FunctionDef(name="ensure_key_mapped", depth=0, kind="mutual");
    root ++> FunctionDef(name="_is_object_dtype", depth=0, kind="direct");
    root ++> FunctionDef(name="list_like", depth=0, kind="direct");

    b = Builder(max_depth=4);
    root spawn b;
    print(f"completed constructions: {b.published}");
}

