"""Canonical shape authoring: model nested, reusable shapes and placement
relationships that cannot override shape constraints.

Scenario distilled from IndependentImpact/standard2shape issue #17:

  - A CanonicalShape declares its own constraints (datatype, cardinality,
    value range, path, nested-node shape). These are INVARIANT.
  - A Placement points to a CanonicalShape and adds *context* (where the
    shape is used in a document). A placement may NEVER widen, narrow, or
    otherwise alter the canonical constraints.
  - A Specialization is an explicit, separately-named CanonicalShape that
    a placement references when its constraints legitimately differ.
    Specializations are themselves canonical shapes — they can be reused.

The traversal the issue complains about is the cascade-invalidate walk:
when a canonical shape changes, every placement that references it must
be re-validated, and every nested shape referenced through `Requires`
must also be re-checked. In a hand-rolled graph this is recursive
parent_id walking; here it is a single walker over typed edges with an
explicit cycle guard.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node CanonicalShape {
    has name: str = "";
    has datatype: str = "xsd:string";
    has min_count: int = 0;
    has max_count: int = -1;       # -1 == unbounded
    has value_constraint: str = ""; # e.g. an allowed-values regex/IRI
    has path_iri: str = "";
    has nested_ref: str = "";       # name of nested canonical shape, if any
    has version: int = 1;           # bumped on canonical edit
}

node Placement {
    has location: str = "";        # e.g. "Bundle/header/section-3"
    has override_attempt: str = "";# "" means none; non-empty means rejected
}

node Specialization {
    has name: str = "";
    has reason: str = "";
}

# Typed edges: the relationship carries meaning, so each is a real archetype.

edge References {
    has since_version: int = 0;
}

edge SpecializedFrom {
    has reason: str = "";
}

edge Requires {
    has kind: str = "nested";      # "nested" or "value"
}

# ---------------------------------------------------------------------------
# Walker: cascade re-validation across all placements and nested shapes
# ---------------------------------------------------------------------------

walker InvalidationCascade {
    has touched_count: int = 0;
    has rejected_count: int = 0;
    has specialized_count: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can descend with Placement entry {
        # 1. Reject any placement that tried to override canonical constraints.
        if here.override_attempt != "" {
            print(
                f"[REJECT] placement at {here.location} tried to override: "
                f"{here.override_attempt}"
            );
            self.rejected_count += 1;
        }

        # 2. Walk every References edge to the canonical shape(s) it points at.
        visit [->:References:->];
    }

    can cascade with CanonicalShape entry {
        self.touched_count += 1;
        print(
            f"[CHECK] canonical '{here.name}' v{here.version} "
            f"(datatype={here.datatype}, min={here.min_count}, "
            f"max={here.max_count}, path={here.path_iri})"
        );

        # 3. If this shape nests another canonical shape, keep cascading.
        if here.nested_ref != "" {
            visit [->:Requires:->];
        }

        # 4. Otherwise, dead-end walk completes cleanly.
    }
}

# ---------------------------------------------------------------------------
# Walker: dependency-aware specialization audit
# ---------------------------------------------------------------------------

walker SpecializationAuditor {
    has spec_count: int = 0;
    has cycle_detected: bool = False;

    can begin with Root entry {
        visit [-->];
    }

    can audit with Specialization entry {
        self.spec_count += 1;
        print(
            f"[SPEC] '{here.name}' specialization "
            f"(reason: {here.reason})"
        );
        # Walk back along the parent-of relationship.
        visit [<-:SpecializedFrom:<-];
    }
}

# ---------------------------------------------------------------------------
# Demonstration graph
# ---------------------------------------------------------------------------

with entry {
    # Three canonical shapes. `PersonShape` nests `IdentifierShape`.
    id_shape = CanonicalShape(
        name="IdentifierShape",
        datatype="xsd:string",
        min_count=1,
        max_count=1,
        value_constraint="regex:^ID-[0-9]+$",
        path_iri="ex:identifier"
    );

    person_shape = CanonicalShape(
        name="PersonShape",
        datatype="xsd:string",
        min_count=1,
        max_count=1,
        value_constraint="",
        path_iri="ex:fullName",
        nested_ref="IdentifierShape",
        version=2
    );

    # An explicit specialization — used only when a placement truly needs
    # constraints that differ from the canonical.
    person_strict = Specialization(
        name="PersonShapeStrict",
        reason="Legal-name placements require non-empty + regex constraint"
    );

    # Placements: two reuse the same canonical, one tries to override.
    p_a = Placement(location="Bundle/header/personA");
    p_b = Placement(location="Bundle/footer/personB");
    p_bad = Placement(
        location="Bundle/footer/personC",
        override_attempt="datatype=xsd:integer"
    );

    # Build the graph.
    root ++> id_shape;
    root ++> person_shape;
    root ++> person_strict;

    p_a +>:References(since_version=1):+> person_shape;
    p_b +>:References(since_version=2):+> person_shape;
    p_bad +>:References(since_version=2):+> person_shape;

    person_shape +>:Requires(kind="nested"):+> id_shape;

    person_strict +>:SpecializedFrom(reason="distinct constraints"):+> person_shape;

    # Spawn the cascade-invalidation walker from root.
    cascade = InvalidationCascade();
    root spawn cascade;
    print(
        f"cascade touched {cascade.touched_count} canonical shape(s), "
        f"rejected {cascade.rejected_count} placement override(s)"
    );

    # Spawn the specialization auditor from root.
    auditor = SpecializationAuditor();
    root spawn auditor;
    print(
        f"auditor found {auditor.spec_count} explicit specialization(s)"
    );
}

"""Build dependency graph with native typed edges and cycle-guarded traversal."""

node Workspace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node BuildUnit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has build_seconds: int = 0;
    has state: str = "new";
}

edge Contains { }

edge DependsOn {
    has reason: str = "";
}

walker DependencyWalker {
    has inspected_units: int = 0;

    can start with Root entry {
        print("Walking aipm build workspace");
        visit [-->];
    }

    can enter with Workspace entry {
        print(f"Workspace: {here.title}");
        visit [->:Contains:->];
    }

    can inspect with BuildUnit entry {
        if here.state == "seen" {
            print(f"[cycle-guard] revisited {here.title}");
        } else {
            here.state = "seen";
            self.inspected_units += 1;
            status = "ready" if here.available else "blocked";
            print(f"[{status}] {here.title}: {here.build_seconds}s");
            visit [->:DependsOn:->];
        }
    }
}

with entry {
    workspace = Workspace(title="aipm workspace", year=2026);

    engine = BuildUnit(
        title="libaipm-engine-spec",
        year=2026,
        build_seconds=23
    );
    schema = BuildUnit(
        title="jsonschema",
        year=2026,
        build_seconds=22
    );
    native = BuildUnit(
        title="libgit2-sys and aws-lc-sys",
        year=2026,
        build_seconds=158,
        available=False
    );

    root +>:Contains:+> workspace;
    workspace +>:Contains:+> engine;
    workspace +>:Contains:+> schema;
    workspace +>:Contains:+> native;

    engine +>:DependsOn(reason="local schema validation"):+> schema;
    schema +>:DependsOn(reason="native metadata support"):+> native;
    native +>:DependsOn(reason="workspace build integration"):+> engine;

    root spawn DependencyWalker();
}

A maintainer on the project djm204/frankenbeast (TypeScript) filed this issue about hand-rolled graph machinery causing pain:

Issue #4122: RecursivePlanner._buildSubGraph: validated PlanGraph discarded; raw-edges graph bypasses sub-graph cycle detection

## Summary

In `packages/franken-planner/src/planners/recursive.ts`, the private `_buildSubGraph` method (lines 97–126) calls `PlanGraph.fromTasks()` for validation but **discards its return value**, then returns `PlanGraph.createWithRawEdges()` — the test-only escape hatch that skips all cycle detection and topological sorting.

## Affected code

```ts
// packages/franken-planner/src/planners/recursive.ts, lines 124–125

// Line 124 — return value discarded; validation is a no-op
PlanGraph.fromTasks(tasksWithInternalDependencies, { reason: 'recursive expansion' });
// Line 125 — raw, unvalidated graph returned to the planner loop
return PlanGraph.createWithRawEdges(nodes, edges, 0, 'recursive expansion');
```

## Impact

- A cyclic sub-graph produced by a dynamically-expanding task is never caught by `RecursivePlanner`.  No `CyclicDependencyError` is raised; the planner executes tasks in an arbitrary (insertion) order or enters an infinite loop.
- The validated topologically-sorted graph from `fromTasks` is thrown away. The raw `nodes` map — built before external dependencies are stripped via `internalDependencies` — is returned instead, which means tasks may reference already-completed (external) dependencies as if they were unresolved.
- `createWithRawEdges` is documented as a testing escape-hatch; its use in a production code path is a structural error.

## Fix

Return the validated graph directly instead of the raw-edges one:

```ts
// Before (buggy)
PlanGraph.fromTasks(tasksWithInternalDependencies, { reason: 'recursive expansion' });
return PlanGraph.createWithRawEdges(nodes, edges, 0, 'recursive expansion');

// After (correct)
return PlanGraph.fromTasks(tasksWithInternalDependencies, { reason: 'recursive expansion' });
```

The `edges` map and the `createWithRawEdges` call can then be removed.

## Severity
**High** — cyclic sub-graphs from dynamic task expansions are silently accepted by the RecursivePlanner, bypassing all DAG validation.

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

"""Recursive task planner: model PlanGraph as a typed-edge DAG and walk it.

Models the scenario from issue #4122 — a planner that expands tasks into
sub-graphs must validate the sub-graph for cycles, otherwise a cyclic
dynamic expansion produces an unbounded traversal. Two walkers demonstrate
the fix: ``RawExpansion`` reproduces the buggy path (raw edges, no cycle
guard, hangs on cyclic input) and ``ValidatedExpansion`` reproduces the
fixed path (returns the validated graph and walks it with an explicit
visited set, so cycles terminate cleanly).
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Task {
    has title: str = "";
    has done: bool = False;
}

# A ``PlanGraph`` is the planner's view of a sub-task DAG. It owns its task
# nodes plus the typed ``DependsOn`` edges that connect them.
node PlanGraph {
    has label: str = "";
    has task_count: int = 0;
    has validated: bool = False;
}

# ---------------------------------------------------------------------------
# Typed edges
# ---------------------------------------------------------------------------

# ``DependsOn`` is the typed edge that encodes "task A must finish before
# task B can start".  The walker follows these to perform topological
# ordering; declaring them as a typed edge replaces the raw ``Map<id,
# id[]>`` adjacency scaffolding from the buggy TypeScript code.
edge DependsOn { }

# ``Contains`` ties a ``Task`` to its owning ``PlanGraph`` so the walker
# can iterate only over the tasks that belong to the sub-graph it is
# validating.
edge Contains { }

# ---------------------------------------------------------------------------
# Walkers
# ---------------------------------------------------------------------------

# Reproduces the *buggy* code path from issue #4122: the planner used to
# discard the validated graph and walk the raw edges. Because the walker
# has no visited-set in 0.36.1, a cyclic sub-graph here would loop
# forever — the very symptom the issue calls out.
walker RawExpansion {
    has visited_count: int = 0;
    has max_steps: int = 0;
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can expand with PlanGraph entry {
        print(f"[raw] expanding {self.reason!r} ({here.task_count} tasks)");
        self.visited_count = 0;
        visit [->:Contains:->];
    }

    # No cycle guard — exactly the behaviour the issue reports.  We cap
    # steps only to keep the demo finite; the cap is *not* the cycle
    # policy, it is a demo safety net so the script terminates.
    can traverse with Task entry {
        self.visited_count += 1;
        if self.visited_count > self.max_steps {
            print("[raw] step cap reached — cyclic sub-graph undetected, "
                  "planner would loop forever in production");
            disengage;
        }
        visit [->:DependsOn:->];
    }
}

# Reproduces the *fixed* code path: the validated graph is what gets
# walked. ``ValidatedExpansion`` carries an explicit visited-set (the
# cycle policy that must survive the lift), so a cyclic sub-graph
# terminates on the second visit instead of looping.
walker ValidatedExpansion {
    has visited_count: int = 0;
    has visited_titles: list[str] = [];
    has reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can expand with PlanGraph entry {
        if not here.validated {
            print(f"[validated] rejecting sub-graph {here.label!r}: "
                  "no cycle/topology check performed");
            disengage;
        }
        print(f"[validated] expanding {self.reason!r} ({here.task_count} tasks)");
        self.visited_count = 0;
        self.visited_titles = [];
        visit [->:Contains:->];
    }

    # Cycle guard — the domain rule that issue #4122 was failing to
    # enforce.  We record every title we have already walked; a repeat
    # means the sub-graph has a cycle and traversal stops cleanly with a
    # ``CyclicDependencyError``-shaped report.
    can traverse with Task entry {
        if here.title in self.visited_titles {
            print(f"[validated] CyclicDependencyError: "
                  f"task {here.title!r} revisited");
            disengage;
        }
        self.visited_titles.append(here.title);
        self.visited_count += 1;
        order = "pending" if not here.done else "done";
        print(f"  step {self.visited_count}: {here.title} ({order})");
        visit [->:DependsOn:->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # --- Sub-graph A: a clean DAG, both walkers must finish it -----------
    a_intake = Task(title="A:intake", done=True);
    a_parse = Task(title="A:parse");
    a_plan = Task(title="A:plan");
    a_execute = Task(title="A:execute");
    sub_a = PlanGraph(label="subgraph-A", task_count=4, validated=True);

    sub_a +>:Contains:+> a_intake;
    sub_a +>:Contains:+> a_parse;
    sub_a +>:Contains:+> a_plan;
    sub_a +>:Contains:+> a_execute;

    # Dependencies: intake -> parse -> plan -> execute
    a_intake +>:DependsOn:+> a_parse;
    a_parse +>:DependsOn:+> a_plan;
    a_plan +>:DependsOn:+> a_execute;

    # --- Sub-graph B: cyclic dynamic expansion (intake -> review -> intake)
    b_intake = Task(title="B:intake");
    b_review = Task(title="B:review");
    b_close = Task(title="B:close");
    sub_b = PlanGraph(label="subgraph-B", task_count=3, validated=True);

    sub_b +>:Contains:+> b_intake;
    sub_b +>:Contains:+> b_review;
    sub_b +>:Contains:+> b_close;

    b_intake +>:DependsOn:+> b_review;
    b_review +>:DependsOn:+> b_intake;   # <-- cycle
    b_intake +>:DependsOn:+> b_close;

    # --- Sub-graph C: looks valid by structure but was never validated,
    #     so the fixed walker must refuse it.
    c_only = Task(title="C:only");
    sub_c = PlanGraph(label="subgraph-C", task_count=1, validated=False);
    sub_c +>:Contains:+> c_only;

    root ++> sub_a ++> sub_b ++> sub_c;

    # ---- Buggy path: raw edges, no cycle guard -------------------------
    raw_walker = RawExpansion(reason="recursive expansion",
                              max_steps=20);
    root spawn raw_walker;
    print(f"[raw] walker terminated after {raw_walker.visited_count} steps");

    # ---- Fixed path: validated graph + explicit visited-set ------------
    fixed_walker = ValidatedExpansion(reason="recursive expansion");
    root spawn fixed_walker;
    print(f"[validated] walker terminated after "
          f"{fixed_walker.visited_count} steps");
}

