"""Knowledge graph shape demo: named edges expose entities while a depth cap keeps cycles safe."""

node KnowledgeEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Document(KnowledgeEntity) {
    has source: str = "";
}

node Fact(KnowledgeEntity) {
    has detail: str = "";
}

node Entity(KnowledgeEntity) {
    has kind: str = "";
}

edge Contains {
    has predicate: str = "";
}

edge About {
    has predicate: str = "";
}

edge RelatedTo {
    has predicate: str = "";
}

walker ShapeReader {
    has remaining_steps: int = 6;

    can begin with Root entry {
        print("Reading the shaped graph from its source document");
        visit [-->] else {
            disengage;
        }
    }

    can read_document with Document entry {
        print(f"document: {here.title} ({here.source})");
        if self.remaining_steps <= 0 {
            print("depth limit reached");
            disengage;
        } else {
            self.remaining_steps = self.remaining_steps - 1;
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_fact with Fact entry {
        print(f"fact: {here.title} — {here.detail}");
        if self.remaining_steps <= 0 {
            print("depth limit reached");
            disengage;
        } else {
            self.remaining_steps = self.remaining_steps - 1;
            visit [->:About:->] else {
                disengage;
            }
        }
    }

    can inspect_entity with Entity entry {
        print(f"entity: {here.title} [{here.kind}]");
        if self.remaining_steps <= 0 {
            print("cycle or depth limit stopped");
            disengage;
        } else {
            self.remaining_steps = self.remaining_steps - 1;
            visit [->:RelatedTo:->] else {
                disengage;
            }
        }
    }
}

with entry {
    document = Document(
        title="Ontology Shape Race",
        year=2026,
        available=True,
        source="controlled experiment"
    );
    fact = Fact(
        title="cheap model rule",
        year=2026,
        available=True,
        detail="A named entity relationship is easier for a small model to recognize."
    );
    researcher = Entity(
        title="Researcher",
        year=2026,
        available=True,
        kind="person"
    );
    model = Entity(
        title="Small model",
        year=2026,
        available=True,
        kind="model"
    );

    root ++> document;
    document +>:Contains(predicate="contains_fact"):+> fact;
    fact +>:About(predicate="about_entity"):+> researcher;
    researcher +>:RelatedTo(predicate="studies"):+> model;
    model +>:RelatedTo(predicate="evaluates"):+> researcher;

    root spawn ShapeReader(remaining_steps=6);
}

"""Information governance and privacy register demo.

Models an information-asset register with classification, retention,
stewardship metadata, and data-flow relations. A walker audits the
register for missing stewardship, expired retention, and cross-boundary
data flows — surfacing the exact governance gaps that the issue
(#2887) asks the system to expose.
"""

# --- Vocabularies (classification, regulatory tags, residency, etc.) ---

enum Classification {
    PUBLIC = "PUBLIC",
    INTERNAL = "INTERNAL",
    CONFIDENTIAL = "CONFIDENTIAL",
    RESTRICTED = "RESTRICTED",
}

enum Residency {
    EU = "EU",
    US = "US",
    APAC = "APAC",
}

# --- Base archetype: shared governance surface for the union trigger ---

node Governed {
    has name: str = "";

    def audit_label() -> str {
        return self.name;
    }
}

# --- Entity archetypes (inherit the shared governance surface) ---

node InformationAsset(Governed) {
    has classification: Classification = Classification.INTERNAL;
    has owner: str = "";
    has steward: str = "";
    has custodian: str = "";
    has last_review: str = "";
    has retention_days: int = 0;
    has days_since_review: int = 0;
    has redacted: bool = False;

    override def audit_label() -> str {
        return self.name;
    }
}

node DataFlow(Governed) {
    has protocol: str = "";
    has purpose: str = "";
    has residency: Residency = Residency.EU;
    has carries_pii: bool = False;

    override def audit_label() -> str {
        return self.name;
    }
}

node GovernanceTask(Governed) {
    has title: str = "";
    has severity: str = "info";
    has detail: str = "";

    override def audit_label() -> str {
        return self.name;
    }
}

# --- Typed edges: the relationships carry meaning ---

edge FlowsTo { }      # InformationAsset -> DataFlow -> InformationAsset
edge AssignedTo { }   # GovernanceTask -> InformationAsset

# --- Walker: audits the register for governance gaps ---

walker GovernanceAuditor {
    has findings: list[str] = [];

    can begin with Root entry {
        print("Governance audit starting");
        visit [->:FlowsTo:->];
    }

    can check_asset with InformationAsset entry {
        missing: list[str] = [];
        if here.owner == "" {
            missing.append("owner");
        }
        if here.steward == "" {
            missing.append("steward");
        }
        if here.custodian == "" {
            missing.append("custodian");
        }
        if len(missing) > 0 {
            self.findings.append(
                f"missing stewardship on {here.name}: {', '.join(missing)}"
            );
        }
        if here.days_since_review > 90 {
            self.findings.append(
                f"overdue review on {here.name} ({here.days_since_review} days)"
            );
        }
        if here.classification == Classification.RESTRICTED and not here.redacted {
            self.findings.append(
                f"restricted asset {here.name} not redacted in views"
            );
        }
        visit [->:FlowsTo:->];
    }

    can walk_flow with DataFlow entry {
        visit [->:FlowsTo:->];
    }
}

# --- Walker: surfaces cross-boundary data flows ---

walker CrossBoundaryScanner {
    has crossings: list[str] = [];

    can begin with Root entry {
        print("Cross-boundary scanner walking the data-flow graph");
        visit [->:FlowsTo:->];
    }

    can scan with InformationAsset entry {
        visit [->:FlowsTo:->];
    }

    can record with DataFlow entry {
        if here.carries_pii and here.residency != Residency.EU {
            self.crossings.append(
                f"PII flow ({here.purpose}) crossing EU boundary to {here.residency.value}"
            );
        }
        visit [->:FlowsTo:->];
    }
}

# --- Demonstration graph ---

with entry {
    customer_db = InformationAsset(
        name="CustomerDB",
        classification=Classification.RESTRICTED,
        owner="data-platform",
        steward="privacy-office",
        custodian="ops-eu",
        last_review="2024-09-01",
        retention_days=730,
        days_since_review=120,
        redacted=False,
    );

    analytics_warehouse = InformationAsset(
        name="AnalyticsWarehouse",
        classification=Classification.CONFIDENTIAL,
        owner="analytics",
        steward="",
        custodian="ops-eu",
        last_review="2024-11-15",
        retention_days=365,
        days_since_review=30,
        redacted=True,
    );

    partner_feed = InformationAsset(
        name="PartnerFeed",
        classification=Classification.INTERNAL,
        owner="",
        steward="partnerships",
        custodian="ops-us",
        last_review="2025-02-01",
        retention_days=180,
        days_since_review=10,
        redacted=True,
    );

    root +>:FlowsTo:+> customer_db;
    customer_db +>:FlowsTo:+> DataFlow(
        name="customer-to-analytics",
        protocol="kafka",
        purpose="analytics-pipeline",
        residency=Residency.US,
        carries_pii=True,
    );
    customer_db +>:FlowsTo:+> DataFlow(
        name="customer-to-archive",
        protocol="sftp",
        purpose="regulatory-archive",
        residency=Residency.EU,
        carries_pii=True,
    );
    root +>:FlowsTo:+> analytics_warehouse;
    analytics_warehouse +>:FlowsTo:+> DataFlow(
        name="analytics-reporting",
        protocol="airflow",
        purpose="reporting",
        residency=Residency.EU,
        carries_pii=False,
    );
    root +>:FlowsTo:+> partner_feed;
    partner_feed +>:FlowsTo:+> DataFlow(
        name="partner-exchange",
        protocol="api",
        purpose="partner-exchange",
        residency=Residency.US,
        carries_pii=True,
    );

    auditor = GovernanceAuditor();
    root spawn auditor;
    print("Governance findings:");
    for finding in auditor.findings {
        print(f"  - {finding}");
    }

    scanner = CrossBoundaryScanner();
    root spawn scanner;
    print("Cross-boundary transfers:");
    for crossing in scanner.crossings {
        print(f"  - {crossing}");
    }
}

A maintainer on the project entif-ai/rosetta (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #1461: VER-001: Rosetta VER Pack for representational vigilance, assessment gating, and recursive monitoring

## Status and collaboration boundary

This is an **exploratory integration and engineering-scoping proposal** based on:

- Jacques Raynal, Pierre Slangen, Elsa Raynal, and Jacques Margerit, [*Detecting Explanatory Insufficiency in Learned Representations: A Framework for Representational Vigilance, Version 3: Regime-Aware Interface with Representational Transition*](https://arxiv.org/abs/2606.13172), arXiv:2606.13172v4;
- the [Rosetta v3.0.0 Core Spine Specification](https://github.com/entif-ai/rosetta/blob/main/docs/RFCs/Rosetta%20v3.0.0%20Core%20Spine%20Specification.md);
- the current Rosetta pack and bootstrap implementation surface;
- and the provenance-preserving correspondence translation rules captured in #1459.

It does **not** imply endorsement of Rosetta by the VER authors, a formal partnership, team formation, assignment of maintainership, or a commitment to implementation. Any scientific-governance role for the VER authors must be agreed explicitly rather than inferred from correspondence.

The purpose of this issue is narrower:

> Define the smallest Rosetta v3-aligned pack, runtime adapter, deterministic demonstration, and scientific review path capable of encoding a complete VER episode without collapsing provenance, observation, interpretation, explanatory resistance, representational diagnosis, or transition governance into one score or one opaque narrative.

## Research basis

VER treats representational adequacy as a diagnostic object distinct from predictive performance. Its Version 3 architecture preserves five diagnostic operations:

1. representation identification;
2. explanatory-domain delimitation;
3. residual-structure detection;
4. explanatory-resistance evaluation;
5. vigilance signaling.

The paper then places a separate assessment gate between VER and representational transition:

```text
VER alert
  -> insufficiency assessment
  -> calibrated regime hypothesis
  -> TBER transition, only if warranted
```

VER's signal outcomes are:

- `stable_adequacy`;
- `vigilance_condition`;
- `representational_alert`.

The assessment gate distinguishes:

- suspected explanatory insufficiency;
- qualified explanatory insufficiency;
- manifestation class:
  - descriptive;
  - transformational;
  - generalization;
- resolution-regime hypothesis:
  - local-corrective;
  - representationally resolutive;
  - structurally recurrent;
  - undetermined.

The paper is explicit that:

```text
predictive performance != representational adequacy
representational alert != qualified explanatory insufficiency
qualified explanatory insufficiency != automatic representational transition
```

It also introduces recursive vigilance: after a representation is provisionally stabilized by an external transition process, VER may monitor whether the same residual family recurs across representational levels.

## Problem

Rosetta and VER are strongly complementary, but a naive integration would create several serious semantic errors.

Without a governed mapping, an implementation could:

- call any model error a residual structure;
- call any persistent residual evidence of representational inadequacy;
- treat a Rosetta Receipt as proof that a diagnosis is scientifically correct;
- identify a Tapestry, model configuration, explanation trace, probe readout, or policy bundle as the model's actual latent representation without qualification;
- treat an agent-generated explanation as direct access to an opaque model's causal reasoning;
- collapse performance, uncertainty, OOD status, robustness, residual persistence, explanatory resistance, and representational adequacy into one confidence scalar;
- emit a representational alert and silently trigger model replacement;
- overwrite earlier assessments when later evidence arrives;
- or add VER vocabulary to the `rosetta.*` namespace and thereby mutate the Core Spine instead of extending it through a Pack.

The integration must therefore preserve the full evidentiary ladder:

```text
what was observed
  != what Rosetta interpreted
  != what VER diagnosed
  != what an evaluator concluded
  != what a Receipt attested occurred
  != what a transition framework may later decide to change
```

## Outcome

Produce a first-wave **VER Integration Pack** plus a fixture-backed runtime proof that can answer, by traversing content-addressed artifacts:

> Which operational representation subject was monitored, for what explanatory domain, which residual structures were observed, why they were considered persistent, which local corrections and alternative explanations were actually examined, what effects those interventions produced, which vigilance signal followed, whether an insufficiency assessment was warranted, and what remained uncertain?

The first Demo Green claim must remain deliberately narrow:

> Rosetta can encode and verify the provenance structure of one complete VER monitoring and assessment episode while preserving the distinction between evidence, interpretation, diagnostic qualification, calibration, and transition consideration.

It must **not** claim:

- that Rosetta has computationally solved representational adequacy;
- that the fixture validates VER empirically;
- that a Receipt proves explanatory insufficiency;
- that an opaque model's internal causal representation has been observed;
- or that TBER transition is implemented.

## Inspected repository baseline

Planning in this issue is grounded against `main` at commit [`922f82275b6cd873ab7524cd4f7f0308aec82ec8`](https://github.com/entif-ai/rosetta/commit/922f82275b6cd873ab7524cd4f7f0308aec82ec8).

### Implemented or executable today

The repository already provides:

- deterministic JSON canonicalization and SHA-256-based content IDs;
- `TileEnvelope` construction with explicit `kind`, `pack`, `parents`, version, canonical body, and CID;
- Core constructors for `rosetta.run`, `rosetta.action`, `rosetta.toolcall`, `rosetta.observation`, and `rosetta.evaluation`;
- runtime kinds for `rosetta.con

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

"""VER monitoring episode with provenance, diagnosis, assessment, and cycle-safe recursive vigilance."""

node Observation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has domain: str = "";
    has residual: str = "";
}

node Interpretation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has explanation: str = "";
    has alternatives_examined: str = "";
}

node Diagnosis {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has signal: str = "stable_adequacy";
    has manifestation: str = "";
    has regime: str = "undetermined";
}

node Assessment {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cid: str = "";
    has qualification: str = "";
    has uncertainty: str = "";
    has transition_warranted: bool = False;
}

edge InterpretedAs {
    has basis: str = "";
}

edge AssessedBy {
    has gate: str = "";
}

edge RecursAt {
    has reason: str = "";
}

walker VigilanceMonitor {
    has hops: int = 0;
    has max_hops: int = 8;

    can begin with Root entry {
        print("VER episode traversal started");
        visit [-->] else {
            disengage;
        }
    }

    can observe with Observation entry {
        if self.hops >= self.max_hops {
            print("cycle guard reached before interpretation");
            disengage;
        } else {
            self.hops += 1;
            print(f"observed domain={here.domain}, residual={here.residual}");
            visit [->:InterpretedAs:->] else {
                disengage;
            }
        }
    }

    can interpret with Interpretation entry {
        if self.hops >= self.max_hops {
            print("cycle guard reached before diagnosis");
            disengage;
        } else {
            self.hops += 1;
            print(f"interpretation={here.explanation}");
            print(f"alternatives examined={here.alternatives_examined}");
            visit [->:AssessedBy:->] else {
                disengage;
            }
        }
    }

    can diagnose with Diagnosis entry {
        if self.hops >= self.max_hops {
            print("cycle guard reached during recursive diagnosis");
            disengage;
        } else {
            self.hops += 1;
            print(f"signal={here.signal}, manifestation={here.manifestation}");
            print(f"regime hypothesis={here.regime}");
            visit [->:AssessedBy:->] else {
                disengage;
            }
        }
    }

    can assess with Assessment entry {
        if self.hops >= self.max_hops {
            print("cycle guard stopped recursive monitoring");
            disengage;
        } else {
            self.hops += 1;
            print(f"qualification={here.qualification}");
            print(f"uncertainty={here.uncertainty}");
            print(f"transition warranted={here.transition_warranted}");
            visit [->:RecursAt:->] else {
                disengage;
            }
        }
    }
}

