"""CQRS read path for Telangana state scale.

Models the materialized-view refresh + CDN cache invalidation flow:
write path commits a Story, an explicit walker walks the dependency
graph of materialized views that depend on that story's domain and
ward, marks them stale, a second walker performs the refresh in
dependency order (mv_sla_dashboard -> mv_domain_heatmap ->
mv_stories_by_ward) and serves the cached payload. Domain logic that
survives from the original issue: invalidation must reach every
dependent view exactly once, refresh order must respect dependency
edges, and the CDN cache must be invalidated after a refresh.
"""

node Story {
    has story_id: str = "";
    has ward: str = "";
    has domain: str = "";
    has department: str = "";
    has confidence: float = 0.0;
}

node MaterializedView {
    has name: str = "";
    has last_refreshed: int = 0;
    has stale: bool = False;
    has payload: str = "";
}

node CDNCache {
    has endpoint: str = "";
    has cached_payload: str = "";
    has cache_hit: bool = False;
    has served_at_ms: int = 0;
}

edge DependsOn { has weight: int = 1; }

walker InvalidateViews {
    has tick: int = 0;
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can propagate with Story entry {
        next_views = [-->][?:MaterializedView];
        for v in next_views {
            if not v.stale {
                v.stale = True;
                self.invalidated.append(v.name);
            }
        }
        visit [-->];
    }
}

walker RefreshInOrder {
    has tick: int = 0;
    has refresh_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with MaterializedView entry {
        upstream = [<-:DependsOn:<-][?:MaterializedView];
        for u in upstream {
            if u.stale {
                u.stale = False;
                u.last_refreshed = self.tick;
                self.refresh_log.append(f"{u.name}@{self.tick}");
                u.payload = f"{u.name}-payload@{self.tick}";
            }
        }
        if here.stale {
            here.stale = False;
            here.last_refreshed = self.tick;
            self.refresh_log.append(f"{here.name}@{self.tick}");
            here.payload = f"{here.name}-payload@{self.tick}";
        }
        visit [-->];
    }

    can serve with CDNCache entry {
        target = "<cold>" if here.cached_payload == "" else "<warm>";
        here.cache_hit = target == "<warm>";
        here.served_at_ms = 5 if target == "<warm>" else 480;
        print(f"CDN {here.endpoint} served {target} in {here.served_at_ms}ms");
    }
}

with entry {
    story = Story(
        story_id="S-001",
        ward="Hyderabad-Charminar",
        domain="roads",
        department="GHMC",
        confidence=0.87
    );

    mv_stories = MaterializedView(name="mv_stories_by_ward", payload="");
    mv_heatmap = MaterializedView(name="mv_domain_heatmap", payload="");
    mv_sla = MaterializedView(name="mv_sla_dashboard", payload="");

    mv_sla +>:DependsOn:+> mv_heatmap;
    mv_heatmap +>:DependsOn:+> mv_stories;
    mv_stories +>:DependsOn:+> story;

    cdn = CDNCache(endpoint="/api/v1/map-stories", cached_payload="");

    root ++> story ++> mv_stories ++> mv_heatmap ++> mv_sla;
    root ++> cdn;

    print("--- Cold load ---");
    root spawn RefreshInOrder(tick=1);

    print("--- Story update triggers invalidation ---");
    root spawn InvalidateViews(tick=2);

    print("--- Refresh after invalidation ---");
    root spawn RefreshInOrder(tick=3);

    print("--- Warm CDN serve ---");
    root spawn RefreshInOrder(tick=4);
}

