"""Master Data Management: canonical entities, cross-references, and resolution review.

Demonstrates the core master-data / entity-resolution scenario: source
records from heterogeneous systems are linked to a canonical entity via
typed cross-reference edges. A resolver walker traverses the cross-refs,
applies deterministic matching, accumulates confidence and evidence,
and routes ambiguous matches into a steward review queue instead of
silently accepting them.
"""

# ----------------------------------------------------------------------
# Domain enum: governance domains
# ----------------------------------------------------------------------
enum Domain {
    CUSTOMER,
    ORGANIZATION,
    PRODUCT,
    DEVICE
}

# ----------------------------------------------------------------------
# Canonical entity archetype
# ----------------------------------------------------------------------
node CanonicalEntity {
    has domain: Domain = Domain.CUSTOMER;
    has canonical_id: str = "";
    has display_name: str = "";
    has confidence: float = 0.0;
    has match_rule: str = "";
    has review_status: str = "pending";
    has evidence_count: int = 0;
}

# ----------------------------------------------------------------------
# Source record archetype
# ----------------------------------------------------------------------
node SourceRecord {
    has source_system: str = "";
    has source_id: str = "";
    has raw_name: str = "";
    has raw_key: str = "";
}

# ----------------------------------------------------------------------
# Review queue item archetype
# ----------------------------------------------------------------------
node ReviewItem {
    has reason: str = "";
    has proposed_canonical: str = "";
    has evidence_count: int = 0;
    has review_status: str = "pending";
}

# ----------------------------------------------------------------------
# Typed edges: cross-reference, audit trail, review routing
# ----------------------------------------------------------------------
edge CrossRef {
    has confidence: float = 0.0;
    has rule: str = "";
    has rule_version: str = "v1";
}

edge AuditTrail {
    has action: str = "";
    has actor: str = "system";
}

edge NeedsReview {
    has reason: str = "";
}

# ----------------------------------------------------------------------
# Walker: deterministic resolver that walks cross-references
# ----------------------------------------------------------------------
walker Resolver {
    has threshold_auto: float = 0.85;
    has visits: int = 0;
    has ambiguous: int = 0;
    has auto_merged: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # Resolve a canonical entity: walk its source cross-references,
    # accumulate confidence, route low-confidence ones to review.
    can resolve with CanonicalEntity entry {
        self.visits += 1;
        print(f"[resolve] canonical={here.canonical_id} "
              f"domain={here.domain} review_status={here.review_status}");
        visit [->:CrossRef:->];
    }

    # A source record attached via CrossRef: score deterministic match
    # and either accumulate onto the canonical (auto) or escalate.
    can score with SourceRecord entry {
        if here.raw_key != "" and here.raw_key == here.source_id {
            conf = 0.95;
            rule = "exact_key";
        } elif here.raw_name != "" {
            conf = 0.70;
            rule = "name_match";
        } else {
            conf = 0.30;
            rule = "weak";
        }

        self.visits += 1;

        if conf >= self.threshold_auto {
            self.auto_merged += 1;
            print(f"  [auto] source={here.source_system}:{here.source_id} "
                  f"confidence={conf:.2f} rule={rule}");
            here +>:AuditTrail(action="auto_merged", actor="Resolver"):+>
                ReviewItem(reason="auto_merged",
                           proposed_canonical=here.source_id,
                           evidence_count=1,
                           review_status="auto");
        } else {
            self.ambiguous += 1;
            print(f"  [review] source={here.source_system}:{here.source_id} "
                  f"confidence={conf:.2f} rule={rule}");
            here +>:AuditTrail(action="needs_review", actor="Resolver"):+>
                ReviewItem(reason="low_confidence",
                           proposed_canonical=here.source_id,
                           evidence_count=1,
                           review_status="pending");
        }

        visit [->:AuditTrail:->];
    }

    can collect_review with ReviewItem entry {
        self.visits += 1;
        print(f"  [queue] review item: reason={here.reason} "
              f"status={here.review_status}");
    }
}

# ----------------------------------------------------------------------
# Walker: lineage auditor that walks every audit trail off a canonical
# ----------------------------------------------------------------------
walker LineageAuditor {
    has audit_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with CanonicalEntity entry {
        print(f"[audit] canonical={here.canonical_id}");
        visit [->:CrossRef:->];
    }

    can tally with SourceRecord entry {
        self.audit_count += 1;
        visit [->:AuditTrail:->];
    }

    can tally_audit with ReviewItem entry {
        self.audit_count += 1;
    }
}

# ----------------------------------------------------------------------
# Walker: steward review — manually merge or split candidates
# ----------------------------------------------------------------------
walker Steward {
    has merged: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can review with ReviewItem entry {
        new_status = "reviewed";
        new_reason = "steward_approved";
        here.review_status = new_status;
        here.reason = new_reason;
        self.merged += 1;
        print(f"[steward] approved review item, merged={self.merged}");
    }
}

# ----------------------------------------------------------------------
# Demonstration graph
# ----------------------------------------------------------------------
with entry {
    # Two heterogeneous source systems, one canonical customer.
    cust1 = CanonicalEntity(
        domain=Domain.CUSTOMER,
        canonical_id="CUST-001",
        display_name="Acme Holdings"
    );
    cust2 = CanonicalEntity(
        domain=Domain.ORGANIZATION,
        canonical_id="ORG-100",
        display_name="Globex"
    );
    cust3 = CanonicalEntity(
        domain=Domain.PRODUCT,
        canonical_id="PROD-77",
        display_name="Widget Pro"
    );

    root ++> cust1 ++> cust2 ++> cust3;

    # Source records linked to canonical via typed CrossRef edges.
    cust1 +>:CrossRef(confidence=0.95, rule="exact_key"):+>
        SourceRecord(source_system="CRM", source_id="ACME-1",
                     raw_name="Acme Holdings", raw_key="ACME-1");
    cust1 +>:CrossRef(confidence=0.70, rule="name_match"):+>
        SourceRecord(source_system="ERP", source_id="ERP-XYZ",
                     raw_name="Acme Holding Co.", raw_key="");
    cust1 +>:CrossRef(confidence=0.30, rule="weak"):+>
        SourceRecord(source_system="Support", source_id="SUP-9",
                     raw_name="", raw_key="");

    cust2 +>:CrossRef(confidence=0.95, rule="exact_key"):+>
        SourceRecord(source_system="CRM", source_id="GBX-2",
                     raw_name="Globex", raw_key="GBX-2");

    cust3 +>:CrossRef(confidence=0.70, rule="name_match"):+>
        SourceRecord(source_system="Catalog", source_id="CAT-W7",
                     raw_name="Widget Pro v2", raw_key="");

    # Spawn resolver walker — deterministic, no AI required.
    r = Resolver();
    root spawn r;
    print(f"resolver visited={r.visits} "
          f"auto_merged={r.auto_merged} ambiguous={r.ambiguous}");

    # Spawn lineage auditor walker.
    la = LineageAuditor();
    root spawn la;
    print(f"lineage_auditor audit_count={la.audit_count}");

    # Spawn steward to clear the review queue.
    st = Steward();
    root spawn st;
    print(f"steward merged={st.merged}");
}

