"""Order audit: skip invalid orders but halt the walk on fraud."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Starting order audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged — stopping audit (amount={here.amount})");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order — continuing (amount={here.amount})");
                visit [-->] else { disengage; };
            } else {
                print(f"[OK] approved order (amount={here.amount})");
                visit [-->] else { disengage; };
            }
        }
    }
}

