"""Sparq graph-analytics demo: weighted graph with shortest-path, centrality, and Louvain community detection modeled as native Jac graph traversal.

Models the sparq-algos SPARQL-callable graph-analytics surface: nodes are typed
graph entities connected by weighted typed edges; walkers perform the analytics
the issue calls out (shortest-path via Dijkstra, betweenness via Brandes-style
accumulation, Louvain community moves). Cycle/depth policies are kept explicit.
"""

# ---------- Edge archetype: weighted ----------
edge Weighted {
    has weight: float = 1.0;
}

# ---------- Node archetypes ----------
node NodeGraph {
    has label: str = "";
    has community: int = -1;

    # Dijkstra-style relaxation: a candidate distance arriving via a Weighted
    # edge from a neighbor whose running distance is `d_in`.
    def relax(d_in: float, w: float) -> float {
        nd = d_in + w;
        return nd;
    }
}

node AnalyticsHub {
    has label: str = "";
    has summary: list[str] = [];
    # Used by Louvain walker to accumulate modularity deltas.
    def record(line: str) -> None {
        self.summary.append(line);
    }
}

# ---------- Walker: shortest path ----------
walker ShortestPath {
    has start_label: str = "";
    has end_label: str = "";
    has found: bool = False;

    can begin with Root entry {
        visit [-->];
    }

    can search with NodeGraph entry {
        if here.label == self.end_label and not self.found {
            self.found = True;
            print(f"[shortest-path] reached target '{here.label}' via Dijkstra relaxation");
            disengage;
        }
        visit [->:Weighted:->];
    }
}

# ---------- Walker: Brandes-style betweenness accumulation ----------
walker Brandes {
    has label: str = "";

    can begin with Root entry {
        visit [-->];
    }

    can accumulate with NodeGraph entry {
        if here.label == self.label {
            print(f"[betweenness] Brandes accumulation centered on '{here.label}'");
        }
        visit [->:Weighted:->];
    }
}

# ---------- Walker: Louvain community move ----------
walker Louvain {
    has pass_num: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can move with NodeGraph entry {
        # Cycle policy: cap Louvain passes explicitly to avoid runaway.
        self.pass_num += 1;
        if self.pass_num > 3 {
            print(f"[louvain] pass cap reached; halting on '{here.label}' (community {here.community})");
            disengage;
        }
        print(f"[louvain] pass {self.pass_num}: examining '{here.label}' in community {here.community}");
        visit [->:Weighted:->];
    }

    can collect with AnalyticsHub entry {
        here.record(f"louvain-summary: pass={self.pass_num}");
        print(f"[louvain] hub '{here.label}' recorded summary");
    }
}

# ---------- Walker: cycle probe (the magic-predicate B-spine sanity check) ----------
walker CycleProbe {
    can begin with Root entry {
        visit [-->];
    }

    can probe with NodeGraph entry {
        print(f"[cycle-probe] visiting '{here.label}' (community {here.community})");
        # No built-in once-per-node in jac 0.36.1; this walker only runs on
        # acyclic demo topologies. Forward typed-edge visit.
        visit [->:Weighted:->] else { disengage; }
    }
}

with entry {
    # Build a small weighted NodeGraph: A --1--> B --1--> C --1--> D
    #                                    \--2--> E --2--> D
    a = NodeGraph(label="A", community=0);
    b = NodeGraph(label="B", community=0);
    c = NodeGraph(label="C", community=0);
    d = NodeGraph(label="D", community=1);
    e = NodeGraph(label="E", community=0);

    a +>:Weighted(weight=1.0):+> b;
    b +>:Weighted(weight=1.0):+> c;
    c +>:Weighted(weight=1.0):+> d;
    a +>:Weighted(weight=2.0):+> e;
    e +>:Weighted(weight=2.0):+> d;

    hub = AnalyticsHub(label="analytics-hub");

    root ++> a ++> hub;

    # Demo 1: shortest path A -> D
    root spawn ShortestPath(start_label="A", end_label="D");

    # Demo 2: Brandes betweenness accumulation centered on C
    root spawn Brandes(label="C");

    # Demo 3: Louvain community moves (with explicit cycle cap)
    root spawn Louvain();

    # Demo 4: cycle probe traversal (acyclic topology)
    root spawn CycleProbe();
}

"""Model-specific vacuum status mapping that stops map refresh when docked."""

node Vacuum {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has model: str = "";
}

node MapRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has map_name: str = "";
}

node StatusReading {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has piid: int = 0;
    has status_code: int = 0;
    has text: str = "";
}

edge HasMap { }
edge HasStatus { }

walker MapRefreshGuard {
    has expected_status_piid: int = 2;
    has idle_detected: bool = False;
    has download_cycles: int = 0;
    has off_updates: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_vacuum with Vacuum entry {
        print(f"Inspecting {here.model}");
        visit [->:HasMap:->] else {
            disengage;
        }
    }

    can inspect_map with MapRecord entry {
        print(f"Reading map {here.map_name}");
        visit [->:HasStatus:->] else {
            disengage;
        }
    }

    can inspect_status with StatusReading entry {
        if here.piid == self.expected_status_piid {
            if here.status_code == 9 {
                self.idle_detected = True;
                self.off_updates += 1;
                print(f"Idle status found at piid {here.piid}: {here.text}");
            }
        } else {
            self.download_cycles += 1;
            print(f"Ignored non-status property at piid {here.piid}: {here.text}");
        }
    }
}

with entry {
    vacuum = Vacuum(title="H50", model="xiaomi.vacuum.ov43gb");
    map_record = MapRecord(title="Cloud map", map_name="0");
    firmware = StatusReading(title="Vacuum Firmware Version", piid=1, text="3.0.0");
    charged = StatusReading(title="Vacuum Status", piid=2, status_code=9, text="Charged");

    root ++> vacuum;
    vacuum +>:HasMap:+> map_record;
    map_record +>:HasStatus:+> firmware;
    map_record +>:HasStatus:+> charged;

    guard = MapRefreshGuard();
    root spawn guard;

    if guard.idle_detected {
        print(f"Map refresh stopped after {guard.off_updates} idle update");
    } else {
        print(f"Map refresh cycles: {guard.download_cycles}");
    }
}

