"""npm audit dependency resolver: model advisories, dependencies, and a fixer walker.

The hand-rolled machinery in the original script walked an adjacency map of
package -> transitive deps, collected advisories, attempted upgrades, and
walked dependents to bump them too. Here we lift that into typed edges and
a walker that traverses the dependency graph.
"""

# ---------- archetypes ----------

node Package {
    has name: str = "";
    has installed: str = "0.0.0";
    has pinned: str = "0.0.0";
    has fixed_upstream: str = "0.0.0";
    has in_prod: bool = True;
}

node Advisory {
    has title: str = "";
    has severity: str = "low";
    has cve: str = "";
}

node FixNote {
    has note: str = "";
    has scope: str = "unfixable";
    has mitigation: str = "";
}

# ---------- typed edges ----------

edge DependsOn {
    has depth: int = 1;
}

edge ReportedFor {
    has severity: str = "low";
}

edge ResolvedBy {
    has strategy: str = "upgrade";
}

# ---------- walker ----------

walker AuditFixer {
    has nextjs_target: str = "15.0.0";
    has nextjs_downgrade_attempts: int = 0;
    has advisories_open: int = 0;
    has advisories_fixed: int = 0;
    has unfixable: int = 0;
    has visited: list[str] = [];
    has depth_cap: int = 6;

    can start with Root entry {
        visit [-->];
    }

    can walk_deps with Package entry {
        # Cycle guard: walkers have no built-in dedupe in jac 0.36.
        if here.name in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.name);

        # Collect advisories attached to this package.
        adv_edges = [here->:ReportedFor:->];
        for adv in adv_edges {
            self.advisories_open += 1;
            needs_bump = self._version_lt(here.installed, here.fixed_upstream);
            breaking = self._would_break_nextjs(here);

            if breaking {
                # The original script's blind --force downgrade is rejected.
                self.nextjs_downgrade_attempts += 1;
                self.advisories_fixed += 0;
                here.pinned = here.installed;
            } elif needs_bump and here.in_prod {
                here.pinned = here.fixed_upstream;
                self.advisories_fixed += 1;
                # Cascade: dependents must move too (transitive bump).
                visit [-->];
                return;
            } else {
                # Upstream has no fix yet; leave a FixNote behind.
                note = FixNote(
                    note=f"{here.name}@{here.installed} unfixable upstream",
                    scope="advisory",
                    mitigation="pin & monitor"
                );
                here +>:ResolvedBy(strategy="document"):+> note;
                self.unfixable += 1;
            }
        }

        # Honor depth cap (original behavior).
        if len(self.visited) >= self.depth_cap {
            disengage;
        }
        visit [-->];
    }

    can record_advice with Advisory entry {
        # Nothing to do here; traversal continues from package roots.
        visit [-->];
    }

    # --- helpers (methods, not walkers) ---

    def _version_lt(a: str, b: str) -> bool {
        try {
            pa = [int(x) for x in a.split(".")];
            pb = [int(x) for x in b.split(".")];
            n = min(len(pa), len(pb));
            for i in range(n) {
                if pa[i] < pb[i] { return True; }
                if pa[i] > pb[i] { return False; }
            }
            return len(pa) < len(pb);
        } except Exception {
            return False;
        }
    }

    def _would_break_nextjs(p: Package) -> bool {
        # nextjs must not be downgraded: that's the explicit constraint.
        return p.name == "nextjs" and p.fixed_upstream < p.installed;
    }
}

# ---------- demo wiring ----------

with entry {
    # Build a small production dep tree with a couple of advisories.
    nextjs = Package(name="nextjs", installed="15.1.0", fixed_upstream="15.1.4", in_prod=True);
    sharp = Package(name="sharp", installed="0.33.5", fixed_upstream="0.34.0", in_prod=True);
    libvips = Package(name="libvips", installed="8.15.0", fixed_upstream="8.16.0", in_prod=True);
    postcss = Package(name="postcss", installed="8.4.31", fixed_upstream="8.4.47", in_prod=True);
    vinext = Package(name="vinext", installed="0.5.0", fixed_upstream="0.5.0", in_prod=True);
    old_tool = Package(name="legacy-tool", installed="1.0.0", fixed_upstream="1.0.0", in_prod=True);  # no fix upstream

    # Two advisory nodes.
    adv_sharp = Advisory(title="sharp libvips RCE", severity="high", cve="CVE-2024-9999");
    adv_postcss = Advisory(title="postcss parser bug", severity="moderate", cve="CVE-2023-1234");

    # Wire tree: root -> nextjs -> (sharp, vinext) -> libvips; root -> postcss -> old_tool
    root ++> nextjs ++> sharp ++> libvips;
    nextjs ++> vinext;
    root ++> postcss ++> old_tool;

    # Attach advisories via typed edges.
    nextjs +>:ReportedFor(severity="low"):+> adv_sharp;
    sharp +>:ReportedFor(severity="high"):+> adv_sharp;
    postcss +>:ReportedFor(severity="moderate"):+> adv_postcss;

    # Run the fixer.
    fixer = AuditFixer();
    root spawn fixer;

    print(f"open={fixer.advisories_open} fixed={fixer.advisories_fixed} "
          f"unfixable={fixer.unfixable} nextjs_downgrade_attempts={fixer.nextjs_downgrade_attempts}");
    print(f"sharp pinned to {sharp.pinned}");
    print(f"postcss pinned to {postcss.pinned}");
    print(f"legacy-tool pinned to {old_tool.pinned}");
    # The nextjs-downgrade temptation was rejected; that is the bug the issue calls out.
}

"""Type alias cycle detection: model self-referencing and mutual typealiases
as nodes, traverse with a walker that detects cycles the way the checker
must — by carrying an explicit guard set, since walkers have no built-in
once-per-node visitation in Jac 0.36.1. Nominal recursive types remain
resolvable because the recursion terminates on a named boundary."""

# --- Node archetypes ---------------------------------------------------------

node AliasDecl {
    has name: str = "";
    # The "shape" being aliased: a payload label so we can distinguish
    # structural aliases (which must terminate, no infinite shape) from
    # nominal aliases (which terminate at the named boundary).
    has kind: str = "structural";   # "structural" or "nominal"
}

node TypeRef {
    has name: str = "";
}

# --- Edges -------------------------------------------------------------------

# `aliases` carries the alias declaration to the type it expands to.
edge Aliases { }

# `expands` marks the structural expansion: a typealias to a record-of-types.
# Following this edge is what overflows the checker when cycles exist.
edge Expands { }

# --- Walkers -----------------------------------------------------------------

walker AliasChecker {
    # Explicit guard set — Jac walkers do NOT dedupe, so we carry one.
    has on_path: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    # When we step onto an alias declaration, begin expansion tracking.
    can enter_alias with AliasDecl entry {
        # Re-entering the same alias while it is already on the path
        # is exactly the cycle the original checker crashed on.
        if here.name in self.on_path {
            self.cycle_found = True;
            cycle = self.on_path + [here.name];
            print(f"ERROR: typealias cycle detected: {' -> '.join(cycle)}");
            disengage;
        }
        self.on_path = self.on_path + [here.name];

        # Nominal aliases terminate at their named boundary; structural
        # aliases must still be expanded one more level.
        if here.kind == "nominal" {
            print(f"OK: nominal alias '{here.name}' resolves at named boundary");
            self.on_path = self.on_path[:-1];
            disengage;
        }
        visit [->:Expands:->];
    }

    # A TypeRef we arrive at via Expands: record it, then descend.
    can resolve_ref with TypeRef entry {
        if here.name in self.on_path {
            self.cycle_found = True;
            cycle = self.on_path + [here.name];
            print(f"ERROR: typealias cycle detected: {' -> '.join(cycle)}");
            disengage;
        }
        print(f"  expanding into {here.name}");
        visit [->:Expands:->];
    }
}

# --- Demo graph --------------------------------------------------------------

with entry {
    # Case 1: structural self-reference
    #   typealias Tree = { l: Tree, r: Tree }
    # The original checker recursed Tree -> Tree -> Tree ... and overflowed.
    tree_self = AliasDecl(name="Tree", kind="structural");
    tree_self_ref = TypeRef(name="Tree");
    root +>:Aliases:+> tree_self +>:Expands:+> tree_self_ref +>:Expands:+> tree_self_ref;

    # Case 2: a two-step mutual cycle
    #   typealias A = B
    #   typealias B = A
    a_decl = AliasDecl(name="A", kind="structural");
    b_decl = AliasDecl(name="B", kind="structural");
    a_ref = TypeRef(name="B");
    b_ref = TypeRef(name="A");
    root +>:Aliases:+> a_decl +>:Expands:+> a_ref;
    root +>:Aliases:+> b_decl +>:Expands:+> b_ref;
    a_decl +>:Expands:+> b_ref;

    # Case 3: a nominal recursive type — must still check and build.
    #   type Tree = { l: Tree, r: Tree }   (nominal; recursion terminates on the name)
    nom_decl = AliasDecl(name="Tree", kind="nominal");
    nom_ref = TypeRef(name="Tree");
    root +>:Aliases:+> nom_decl +>:Expands:+> nom_ref +>:Expands:+> nom_ref;

    print("=== Checking structural self-referencing typealias ===");
    c1 = AliasChecker();
    root spawn c1;

    print("=== Checking mutual two-step typealias cycle ===");
    c2 = AliasChecker();
    root spawn c2;

    print("=== Checking nominal recursive type (should be OK) ===");
    c3 = AliasChecker();
    root spawn c3;
}

"""Warehouse stock take: walk the shelves and report per-item quantities."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total_units: int = 0;
    has min_shelf: int = -1;
    has seen: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can count with StockItem entry {
        shelf_label = f"{here.sku}={here.quantity}";
        report shelf_label;
        self.total_units += here.quantity;
        if not self.seen {
            self.min_shelf = here.quantity;
            self.seen = True;
        } else {
            self.min_shelf = self.min_shelf if self.min_shelf <= here.quantity else here.quantity;
        }
        visit [-->];
    }
}

