"""Artifact publication correctness gates: model cumulative HF/GGUF publish,
reload, generation, rollback, and corrupt/interrupted outcomes with typed
edges and a walker-driven audit that walks lineage, detects cycles, and
exercises rollback against a last-known-good checkpoint."""

# ----- Entities -----

node Artifact {
    has name: str = "";
    has label: str = "";
    has format: str = "";
    has state: str = "draft";
    has bytes: int = 0;
    has accepted: bool = True;
}

node Publication {
    has version: int = 0;
    has label: str = "";
    has accepted: bool = False;
}

node Checkpoint {
    has label: str = "";
    has state: str = "good";
    has accepted: bool = False;
}

# ----- Relationships (typed edges carry meaning) -----

edge Produces { }
edge DependsOn { }
edge CheckedBy { }

# ----- Walkers -----

walker LineageAuditor {
    has visited: list[str] = [];
    has cycles: int = 0;
    has depth_cap: int = 8;

    can start with Root entry {
        visit [->:Produces:->];
    }

    can descend with Publication entry {
        plabel = f"pub-v{here.version}";
        if plabel in self.visited {
            self.cycles += 1;
            disengage;
        }
        if len(self.visited) >= self.depth_cap {
            disengage;
        }
        self.visited.append(plabel);
        print(f"[lineage] {plabel} accepted={here.accepted}");
        visit [->:DependsOn:->] else { disengage; }
    }

    can record with Artifact entry {
        flag = "OK" if here.state == "published" else here.state.upper();
        print(f"  artifact {here.name} [{here.format}] {flag} ({here.bytes}B)");
    }
}

walker Rollback {
    has target_label: str = "";
    has restored: list[str] = [];
    has failed: list[str] = [];

    can start with Root entry {
        visit [->:CheckedBy:->];
    }

    # Union trigger: both Checkpoint and Artifact share `label`, `state`, and
    # `accepted`, so a single body safely accesses those common fields.
    can act with Checkpoint | Artifact entry {
        matches = here.label == self.target_label;
        if matches and here.accepted {
            self.restored.append(here.label);
            print(f"[rollback] restored last-known-good {here.label}");
        } elif here.state == "corrupt" {
            self.failed.append(here.label);
            print(f"[rollback] {here.label} marked corrupt, cannot restore");
        } else {
            print(f"[rollback] skip {here.label} (not the target)");
        }
        visit [-->] else { disengage; }
    }
}

# ----- Demonstration graph -----

with entry {
    p1 = Publication(version=1, label="pub-v1", accepted=True);
    p2 = Publication(version=2, label="pub-v2", accepted=True);
    p3 = Publication(version=3, label="pub-v3", accepted=False);

    a_cfg  = Artifact(name="config.json",          label="cfg",    format="HF",      state="published", bytes=2048);
    a_idx  = Artifact(name="model.safetensors.index", label="idx", format="HF",      state="published", bytes=512);
    a_gguf = Artifact(name="model.gguf",           label="gguf",   format="GGUF",    state="corrupt",   bytes=9_900_000);
    a_sum  = Artifact(name="sha256.txt",           label="sha256", format="CHECKSUM", state="published", bytes=128);

    root +>:Produces:+> p1;
    root +>:Produces:+> p2;
    root +>:Produces:+> p3;
    p1 +>:DependsOn:+> p2;
    p2 +>:DependsOn:+> p3;

    p1 +>:Produces:+> a_cfg;
    p2 +>:Produces:+> a_idx;
    p3 +>:Produces:+> a_gguf;
    p2 +>:Produces:+> a_sum;

    lkg = Checkpoint(label="lkg-v2", state="good", accepted=True);
    a_sum +>:CheckedBy:+> lkg;

    print("=== Lineage audit ===");
    root spawn LineageAuditor();

    print("\n=== Rollback to last-known-good ===");
    root spawn Rollback(target_label="lkg-v2");
}

