"""Tag taxonomy: model the parent-child tag merge that can create a self-cycle.

The issue: ``merge_tags(source=parent_of_target, target=child)`` rewrites the
child's ``parent_id`` from ``source`` to ``target`` — so the child ends up
pointing at itself. The sibling ``set_tag_parent`` would raise ``tag_cycle``
on the same condition; the merge path does not.

This demo models the taxonomy as a graph: Tag nodes connected by a typed
``ParentOf`` edge. A walker that mimics ``set_tag_parent`` rejects any move
that would create a cycle (including a self-loop). A second walker mimics the
buggy ``merge_tags`` flow — it re-parents the source's children onto the
target, which is the exact mutation the issue complains about. A third walker
audits the graph for the invariant that the merge path broke: ``parent_id !=
id`` for every tag.
"""

node Tag {
    has name: str = "";
    has tag_id: int = 0;
    has parent_id: int = -1;
}

edge ParentOf { has since: str = ""; }

walker SetParent {
    """Mirror of ``set_tag_parent``: rejects self- and ancestor-cycles."""

    has target_id: int = 0;
    has new_parent_id: int = 0;
    has rejected: bool = False;
    has reject_reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can attempt with Tag entry {
        if here.tag_id != self.target_id {
            visit [-->];
            return;
        }
        if self.new_parent_id == here.tag_id {
            self.rejected = True;
            self.reject_reason = "tag_cycle(self)";
            disengage;
        }
        here.parent_id = self.new_parent_id;
        visit [-->];
    }
}

walker MergeTags {
    """Mirror of the buggy ``merge_tags``: re-parents source's children to target.

    When the merge source is the parent of the target, the UPDATE
    ``UPDATE tags SET parent_id = ? WHERE parent_id = ?`` rewrites the
    target's own ``parent_id`` from ``source_id`` to ``target_id`` — a
    self-cycle that this walker reproduces faithfully. The fix is *not*
    applied here on purpose: the demo shows the bug.
    """

    has source_id: int = 0;
    has target_id: int = 0;
    has moved: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can merge with Tag entry {
        if here.tag_id == self.source_id {
            visit [-->];
            return;
        }
        if here.parent_id == self.source_id {
            here.parent_id = self.target_id;
            self.moved += 1;
        }
        visit [-->];
    }
}

walker CycleAudit {
    """Walk the tag graph and assert the invariant: ``parent_id != tag_id``.

    This is the check the issue says is missing on the merge path.
    """

    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Tag entry {
        if here.parent_id == here.tag_id {
            self.violations.append(here.name);
        }
        visit [-->];
    }
}

with entry {
    zfs = Tag(name="zfs", tag_id=2, parent_id=-1);
    homelab = Tag(name="homelab", tag_id=1, parent_id=2);
    self_hosted = Tag(name="self-hosted", tag_id=3, parent_id=1);
    docker = Tag(name="docker", tag_id=4, parent_id=1);
    ansible = Tag(name="ansible", tag_id=5, parent_id=1);

    zfs +>:ParentOf:+> homelab;
    homelab +>:ParentOf:+> self_hosted;
    homelab +>:ParentOf:+> docker;
    homelab +>:ParentOf:+> ansible;
    root ++> zfs ++> homelab;

    print("=== baseline: set_tag_parent rejects self-cycle ===");
    sp = SetParent(target_id=2, new_parent_id=2);
    root spawn sp;
    print(f"rejected={sp.rejected} reason={sp.reject_reason}");

    print("\n=== buggy merge: source=parent_of_target, target=child ===");
    mt = MergeTags(source_id=2, target_id=1);
    root spawn mt;
    print(f"moved={mt.moved}");
    print(f"after merge: homelab.parent_id={homelab.parent_id} (self-cycle if == 1)");

    print("\n=== invariant audit: parent_id != tag_id for every tag ===");
    audit = CycleAudit();
    root spawn audit;
    print(f"violations={audit.violations}");
}

"""Extension bundle skill materialization: manifest declares skills as code,
walker traverses bundle -> skills and materializes each SkillContent into the
$MypiDir (env override or default ~/.mypi), mirroring the issue's
'manifest is source of truth' policy."""

node MypiDir {
    has root_path: str = "";
    has skills_path: str = "";
}

node ExtensionBundleManifest {
    has name: str = "";
}

node SkillContent {
    has skill_name: str = "";
    has front_matter: str = "";
    has body: str = "";
}

edge Declares {
    has order: int = 0;
}

edge MaterializedAs {
    has on_disk_path: str = "";
}

walker MaterializeBundle {
    has materialized_paths: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_dir with MypiDir entry {
        print(f"Using MypiDir: {here.root_path}");
        visit [-->];
    }

    can resolve_skills with ExtensionBundleManifest entry {
        bundle_name = here.name;
        print(f"Resolving bundle '{bundle_name}'");
        skills = [->:Declares:->];
        for s in skills {
            content = [s->:Declares:->][0];
            on_disk = f"{[-->][0].skills_path}/{content.skill_name}.md";
            here +>:MaterializedAs(on_disk_path=on_disk):+> content;
            self.materialized_paths.append(on_disk);
            print(f"  materialized {content.skill_name} -> {on_disk}");
        }
        disengage;
    }

    can note_skill with SkillContent entry {
        status = "OVERWRITE" if here.front_matter != "" else "EMPTY";
        print(f"    skill body: {here.skill_name} ({status})");
    }
}

with entry {
    home = MypiDir(root_path="$HOME/.mypi", skills_path="$HOME/.mypi/skills");
    env_override = MypiDir(root_path="$MYPI_DIR", skills_path="$MYPI_DIR/skills");

    home +>:Declares(order=1):+> SkillContent(
        skill_name="repo-explorer",
        front_matter="name: repo-explorer",
        body="Scans /tmp/repos and emits structured summaries."
    );
    home +>:Declares(order=2):+> SkillContent(
        skill_name="readme-helper",
        front_matter="name: readme-helper",
        body="Generates README scaffolding from repo metadata."
    );

    env_override +>:Declares(order=1):+> SkillContent(
        skill_name="repo-explorer",
        front_matter="name: repo-explorer",
        body="Scans /tmp/repos and emits structured summaries."
    );

    repo_explorer = ExtensionBundleManifest(name="repo-explorer");
    readme_helper = ExtensionBundleManifest(name="readme-helper");

    home ++> repo_explorer;
    home ++> readme_helper;

    root ++> home;
    root ++> env_override;

    print("=== env override path ===");
    walker_a = MaterializeBundle();
    walker_a spawn root;
    print(f"\nMaterialized paths: {walker_a.materialized_paths}\n");

    print("=== default home path ===");
    walker_b = MaterializeBundle();
    walker_b spawn root;
    print(f"\nMaterialized paths: {walker_b.materialized_paths}");
}

"""Android deployment pipeline anomaly — versionCode conflict walker.

Models the essential scenario from issue #2144: a Google Play deploy
pipeline stages an APK, promotes it through environments, and a
release manager walks the chain to detect versionCode collisions
before re-deployment.
"""

node Build {
    has version_code: int = 0;
    has apk_path: str = "";
    has valid: bool = True;
}

node Stage {
    has name: str = "";
    has passed: bool = False;
}

node Release {
    has track: str = "";
    has published: bool = False;
}

edge Stages { }
edge Promotes { has order: int = 0; }

walker ReleaseManager {
    has collision: dict = {};

    can start with Root entry {
        print("ReleaseManager: scanning deployment pipeline");
        visit [-->];
    }

    can audit_build with Build entry {
        if not here.valid {
            print(f"  ! invalid build: {here.apk_path}");
            visit [-->];
            return;
        }
        print(f"  build versionCode={here.version_code} apk={here.apk_path}");
        visit [-->];
    }

    can walk_stage with Stage entry {
        status = "OK" if here.passed else "FAIL";
        print(f"  stage {here.name}: {status}");
        visit [-->];
    }

    can release_walk with Release entry {
        if here.published {
            print(f"  ! track {here.track} already published");
        }
        visit [-->];
    }
}

walker CollisionDetector {
    has reported: list = [];

    can start with Root entry {
        print("CollisionDetector: scanning for versionCode reuse");
        visit [-->];
    }

    can scan with Build entry {
        for (vc, label) in self.reported {
            if vc == here.version_code {
                print(f"  CONFLICT: versionCode {vc} reused by {label} and {here.apk_path}");
                visit [-->];
                return;
            }
        }
        self.reported.append([here.version_code, here.apk_path]);
        visit [-->];
    }
}

with entry {
    internal = Build(version_code=42, apk_path="app-internal-debug.apk");
    beta = Build(version_code=42, apk_path="app-beta-debug.apk");
    prod = Build(version_code=43, apk_path="app-release.apk");

    test_stage = Stage(name="unit-tests", passed=True);
    ui_stage = Stage(name="ui-tests", passed=True);
    sign_stage = Stage(name="signing", passed=True);

    internal_track = Release(track="internal", published=True);
    beta_track = Release(track="beta", published=False);
    prod_track = Release(track="production", published=False);

    root +>:Stages:+> internal
        +>:Promotes(order=1):+> test_stage
        +>:Stages:+> beta
        +>:Promotes(order=2):+> ui_stage
        +>:Stages:+> prod
        +>:Promotes(order=3):+> sign_stage
        +>:Stages:+> internal_track
        +>:Stages:+> beta_track
        +>:Stages:+> prod_track;

    root spawn ReleaseManager();
    root spawn CollisionDetector();
}

