```jac
"""Compatibility graph demo with typed edges, reachability, depth limits, and cycle detection."""

node Descriptor {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has urn: str = "";
}

node RuntimeNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has node_id: str = "";
}

edge Describes {
    has role: str = "";
}

edge CompatibleWith {
    has reason: str = "";
}

walker CompatibilityWalker {
    has target_urn: str = "";
    has max_depth: int = 3;
    has hops: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can follow_runtime with RuntimeNode entry {
        state = "active" if here.available else "inactive";
        print(f"Runtime node {here.node_id}: {state}");
        visit [->:Describes:->] else {
            disengage;
        }
    }

    can inspect with Descriptor entry {
        if here.urn in self.seen {
            print(f"Cycle detected at {here.urn}");
            disengage;
        }

        self.seen.append(here.urn);
        state = "available" if here.available else "unavailable";
        print(f"Checking {here.title} ({state})");

        if here.urn == self.target_urn {
            print(f"Reached target {here.urn}");
            disengage;
        }

        if self.hops >= self.max_depth {
            print(f"Depth limit reached at {here.urn}");
            disengage;
        }

        self.hops = self.hops + 1;
        visit [->:CompatibleWith:->] else {
            disengage;
        }
    }
}

with entry {
    runtime = RuntimeNode(
        title="Coordinator",
        node_id="coordinator-1"
    );

    source = Descriptor(
        title="Image",
        urn="urn:image"
    );
    text = Descriptor(
        title="Text",
        urn="urn:text"
    );
    bytes = Descriptor(
        title="Bytes",
        urn="urn:bytes"
    );

    root ++> runtime;
    runtime +>:Describes(role="publishes"):+> source;
    source +>:CompatibleWith(reason="image conversion"):+> text;
    text +>:CompatibleWith(reason="byte encoding"):+> bytes;
    bytes +>:CompatibleWith(reason="legacy fallback"):+> text;

    root spawn CompatibilityWalker(
        target_urn="urn:bytes",
        max_depth=3
    );
    root spawn CompatibilityWalker(
        target_urn="urn:missing",
        max_depth=4
    );
}
