"""CGM rebuild audit: detect paths and motifs that retain old node identifiers."""

node CgmBuild {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has build_id: str = "";
    has computed_at: str = "";
    has current_node_ids: list[str] = [];
}

node CgmNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has node_id: str = "";
    has node_type: str = "";
    has build_id: str = "";
}

node CgmPath {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path_id: str = "";
    has from_node_id: str = "";
    has to_node_id: str = "";
    has writer_build_id: str = "";
    has computed_at: str = "";
}

node CgmMotif {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has motif_id: str = "";
    has node_ids_array: list[str] = [];
    has writer_build_id: str = "";
    has computed_at: str = "";
}

edge ContainsAsset {
    has role: str = "";
}

walker OrphanAudit {
    has active_build_id: str = "";
    has current_node_ids: list[str] = [];
    has seen_build_ids: list[str] = [];
    has seen_node_ids: list[str] = [];
    has seen_path_ids: list[str] = [];
    has seen_motif_ids: list[str] = [];
    has orphan_paths: int = 0;
    has orphan_motifs: int = 0;
    has checked_paths: int = 0;
    has checked_motifs: int = 0;

    can start with Root entry {
        print("Starting current-generation CGM audit");
        visit [-->] else { disengage; }
    }

    can enter_build with CgmBuild entry {
        if here.build_id in self.seen_build_ids {
            disengage;
        }
        self.seen_build_ids.append(here.build_id);
        self.active_build_id = here.build_id;
        self.current_node_ids = here.current_node_ids;
        print(f"Build {here.build_id} computed at {here.computed_at}");
        visit [->:ContainsAsset:->] else { disengage; }
    }

    can inspect_node with CgmNode entry {
        if here.node_id in self.seen_node_ids {
            disengage;
        }
        self.seen_node_ids.append(here.node_id);
        print(f"node {here.node_id} is present in {here.build_id}");
    }

    can inspect_path with CgmPath entry {
        if here.path_id in self.seen_path_ids {
            disengage;
        }
        self.seen_path_ids.append(here.path_id);
        self.checked_paths += 1;
        from_current = here.from_node_id in self.current_node_ids;
        to_current = here.to_node_id in self.current_node_ids;
        if from_current and to_current and here.writer_build_id == self.active_build_id {
            print(f"path {here.path_id} is current");
        } else {
            self.orphan_paths += 1;
            print(f"ORPHAN path {here.path_id}: {here.from_node_id} -> {here.to_node_id}, writer {here.writer_build_id}, active {self.active_build_id}");
        }
    }

    can inspect_motif with CgmMotif entry {
        if here.motif_id in self.seen_motif_ids {
            disengage;
        }
        self.seen_motif_ids.append(here.motif_id);
        self.checked_motifs += 1;
        missing_count = 0;
        for node_id in here.node_ids_array {
            if node_id in self.current_node_ids {
            } else {
                missing_count += 1;
            }
        }
        if missing_count == 0 and here.writer_build_id == self.active_build_id {
            print(f"motif {here.motif_id} is current");
        } else {
            self.orphan_motifs += 1;
            print(f"ORPHAN motif {here.motif_id}: {missing_count} node ids missing");
        }
    }

    can summarize with Root exit {
        print(f"Audit result: {self.orphan_paths}/{self.checked_paths} paths orphaned, {self.orphan_motifs}/{self.checked_motifs} motifs orphaned");
    }
}

with entry {
    old_sun = CgmNode(title="Sun (old)", node_id="uuid-old-sun", node_type="graha", build_id="nodes-2026-08-08");
