"""Build system dependency audit.

Models a build graph where tasks depend on shared libraries (diamond
dependency). A walker audits each task exactly once even though the graph
may be reached via multiple paths, and sums the build minutes of every
distinct task visited.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has available: bool = True;
}

walker Auditor {
    has audited_titles: list[str] = [];
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        already = False;
        for name in self.audited_titles {
            if name == here.title {
                already = True;
            }
        }
        if not already {
            self.audited_titles.append(here.title);
            self.total_minutes += here.minutes;
            print(f"[AUDIT] {here.title} (+{here.minutes} min)");
        } else {
            print(f"[skip ] {here.title} already audited");
        }
        visit [-->];
    }
}

with entry {
    shared_lib = Task(title="shared_lib", minutes=10);
    compiler = Task(title="compiler", minutes=20);
    linker = Task(title="linker", minutes=15);
    app_a = Task(title="app_a", minutes=30);
    app_b = Task(title="app_b", minutes=25);

    # Diamond: app_a and app_b both depend on compiler, linker, and
    # shared_lib. Traversal from root reaches the shared nodes via more
    # than one path; the walker must count each task exactly once.
    root ++> compiler
        ++> shared_lib
        ++> linker
        ++> app_a
        ++> app_b;

    root spawn Auditor();
    print("dependency graph audited");
}

"""Native HQL graph demo: lower textual-rule concepts into a canonical condition graph."""

node HqlRule {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has severity: str = "info";
    has evidence: str = "signal";
    has hql_version: str = "0.3.1";
}

node HqlCondition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "ast";
    has field_name: str = "";
    has operator: str = "";
    has literal: str = "";
    has count_value: int = 0;
}

node HqlFact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has fact_kind: str = "";
    has ownership_kind: str = "";
    has lossy: bool = False;
}

edge RuleCondition {
    has position: int = 0;
}

edge ConditionChild {
    has position: int = 0;
}

edge SemanticRequirement {
    has required: bool = True;
}

edge RuleDefinition {
    has position: int = 0;
}

walker HqlCompiler {
    has visited_conditions: list[str] = [];

    can begin with Root entry {
        print("HQL compiler: lowering graph into canonical condition IR");
        visit [->:RuleDefinition:->];
    }

    can compile with HqlRule entry {
        print(f"rule {here.title} [{here.severity}, {here.evidence}, HQL {here.hql_version}]");
        visit [->:RuleCondition:->] else {
            disengage;
        }
    }

    can lower with HqlCondition entry {
        if here.title in self.visited_conditions {
            print(f"cycle detected at condition {here.title}; branch ignored");
        } else {
            self.visited_conditions.append(here.title);
            print(f"condition {here.kind}: {here.field_name} {here.operator} {here.literal}");

            if here.kind != "ast" {
                visit [->:ConditionChild:->] else {
                    disengage;
                }
            }

            visit [->:SemanticRequirement:->] else {
                disengage;
            }
        }
    }

    can validate with HqlFact entry {
        loss_label = "lossy" if here.lossy else "retained";
        print(f"fact {here.fact_kind} ({here.ownership_kind}, {loss_label})");
    }
}

with entry {
    allocator = HqlRule(
        title="memory.allocator_candidate",
        severity="info",
        evidence="candidate"
    );
    allocator_all = HqlCondition(title="allocator.all", kind="all");
    allocator_call = HqlCondition(
        title="allocator.call",
        kind="ast",
        field_name="callee",
        operator="==",
        literal="malloc"
    );
    ownership = HqlFact(
        title="allocator.ownership",
        fact_kind="summary-ownership",
        ownership_kind="allocate"
    );
    barrier = HqlFact(
        title="allocator.barrier",
        fact_kind="summary-barrier",
        lossy=True
    );

    cycle_rule = HqlRule(
        title="anti_analysis.timing_check",
        severity="info",
        evidence="signal"
    );
    cycle_all = HqlCondition(title="timing.all", kind="all");
    cycle_any = HqlCondition(title="timing.any", kind="any");
    timing_fact = HqlFact(
        title="timing.fact",
        fact_kind="timing-signal",
        ownership_kind="observe"
    );

    root +>:RuleDefinition(position=1):+> allocator;
    root +>:RuleDefinition(position=2):+> cycle_rule;

    allocator +>:RuleCondition(position=1):+> allocator_all;
    allocator_all +>:ConditionChild(position=1):+> allocator_call;
    allocator_all +>:SemanticRequirement(required=True):+> ownership;
    allocator_call +>:SemanticRequirement(required=False):+> barrier;

    cycle_rule +>:RuleCondition(position=1):+> cycle_all;
    cycle_all +>:ConditionChild(position=1):+> cycle_any;
    cycle_all +>:SemanticRequirement(required=True):+> timing_fact;
    cycle_any +>:ConditionChild(position=1):+> cycle_all;
    cycle_any +>:SemanticRequirement(required=True):+> timing_fact;

    root spawn HqlCompiler();
}

"""Apex log lifecycle: refresh an org connection, materialize a log file under a canonical path, and route the raw log to a text editor. Models the essential graph the issue describes: Org -> LogRecord -> LocalFile -> Editor, with traversal that classifies authentication, fetch, and persistence outcomes without leaking tokens."""

node OrgConnection {
    has alias: str = "";
    has authenticated: bool = False;
    has auth_token: str = "REDACTED";
}

node ApexLogRecord {
    has log_id: str = "";
    has duration_ms: int = 0;
    has status: str = "Pending";
    has operation: str = "Fetch";
}

node LocalLogFile {
    has log_id: str = "";
    has canonical_path: str = "";
    has materialized: bool = False;
    has safe: bool = True;
}

node EditorTab {
    has editor_name: str = "IntelliJ";
    has opened_path: str = "";
}

edge Routes {
    has stage: str = "";
}

edge DependsOn {
    has order: int = 0;
}

walker LogPipeline {
    has completed: list[str] = [];
    has failures: list[str] = [];

    can begin with Root entry {
        print("=== Apex Log Lifecycle Pipeline ===");
        visit [->:Routes:->];
    }

    can refresh_org with OrgConnection entry {
        here.authenticated = True;
        here.auth_token = "REDACTED";
        self.completed.append(f"refresh:{here.alias}");
        print(f"[OK] refresh org {here.alias}");
        visit [->:Routes:->];
    }

    can fetch_log with ApexLogRecord entry {
        if here.operation == "Fetch" {
            here.status = "Fetched";
            self.completed.append(f"fetch:{here.log_id}");
            print(f"[OK] fetch log {here.log_id} ({here.duration_ms}ms)");
        }
        visit [->:Routes:->];
    }

    can materialize_file with LocalLogFile entry {
        path_safe = here.log_id != "" and here.canonical_path != "";
        here.safe = path_safe;
        if path_safe {
            here.materialized = True;
            self.completed.append(f"materialize:{here.log_id}");
            print(f"[OK] materialize {here.canonical_path}");
        } else {
            here.materialized = False;
            self.failures.append(f"materialize:{here.log_id}:unsafe-path");
            print(f"[FAIL] materialize rejected unsafe path for {here.log_id}");
        }
        visit [->:Routes:->];
    }

    can open_in_editor with EditorTab entry {
        here.opened_path = "REDACTED";
        self.completed.append(f"open:{here.editor_name}");
        print(f"[OK] open in {here.editor_name} editor");
        visit [->:Routes:->];
    }
}

walker ClassifyOutcome {
    has classification: str = "";

    can start with Root entry {
        visit [->:Routes:->];
    }

    can classify_org with OrgConnection entry {
        cls = "AUTH_OK" if here.authenticated else "AUTH_REQUIRED";
        print(f"  classify Org({here.alias}) -> {cls}");
    }

    can classify_log with ApexLogRecord entry {
        cls = "FETCH_OK" if here.status == "Fetched" else "FETCH_PENDING";
        print(f"  classify ApexLog({here.log_id}) -> {cls}");
    }

    can classify_file with LocalLogFile entry {
        cls = "FILE_OK" if here.materialized else ("FILE_UNSAFE" if not here.safe else "FILE_MISSING");
        print(f"  classify LocalFile({here.log_id}) -> {cls}");
    }

    can classify_editor with EditorTab entry {
        cls = "EDITOR_OK" if here.opened_path != "" else "EDITOR_NO_PATH";
        print(f"  classify EditorTab -> {cls}");
    }
}

with entry {
    org = OrgConnection(alias="MyDevOrg");
    log_rec = ApexLogRecord(log_id="07Lxx0000000001", duration_ms=1234);
    file = LocalLogFile(log_id="07Lxx0000000001", canonical_path="/logs/MyDevOrg/07Lxx0000000001.log");
    editor = EditorTab(editor_name="IntelliJ");

    org +>:Routes(stage="refresh"):+> log_rec;
    log_rec +>:Routes(stage="fetch"):+> file;
    file +>:Routes(stage="open"):+> editor;

    org +>:DependsOn(order=1):+> file;
    log_rec +>:DependsOn(order=2):+> editor;

    root spawn LogPipeline();
    print("--- outcome classification ---");
    root spawn ClassifyOutcome();
    print("pipeline done");
}

