A single football action is gathered from compatible evidence across
multiple surface providers (CSV / XML / XLSX), stitched into an
`ActionTrace`, and then walked forward to expose consequence, sequence,
repeated pattern, and analyst interpretation — without losing source
provenance or inflating action counts.
"""

# --- Entity archetypes ----------------------------------------------------

node Match {
    has match_id: str = "";
    has period: int = 0;
    has minute: int = 0;
}

node Actor {
    has actor_id: str = "";
    has name: str = "";
    has team_id: str = "";
}

node Surface {
    has source_role: str = "";
    has format: str = "";
    has provider_row_id: str = "";
}

node EvidenceAtom {
    has label: str = "";
    has x: float = 0.0;
    has y: float = 0.0;
}

node ActionTrace {
    has base_action: str = "";
    has outcome: str = "";
    has qualifier: str = "";
    has progression: str = "";
    has direction: str = "";
    has distance: str = "";
    has gk_relation: str = "";
    has team_reflection: str = "";
    has xlsx_aggregate: str = "";
}

# --- Typed edges ----------------------------------------------------------

edge HasActor {}
edge CarriesAtom {}
edge StitchesTo {}
edge HasTrace {}
edge Follows {}
edge Surfaces {}

walker TraceBuilder {
    """Stitches compatible evidence atoms into a single ActionTrace."""

    can start with Root entry {
        visit [-->];
    }

    can descend_match with Match entry {
        visit [-->];
    }

    can descend_actor with Actor entry {
        visit [-->];
    }

    can assemble with EvidenceAtom entry {
        visit [-->];
    }

    can finish with ActionTrace entry {
        here.base_action = "pass";
        here.outcome = "complete";
        here.qualifier = "through_ball";
        here.progression = "transition";
        here.direction = "forward";
        here.distance = "long";
        here.gk_relation = "no_pressure";
        here.team_reflection = "build_up_phase";
        here.xlsx_aggregate = "pass_count:7";
        print(f"trace assembled: {here.base_action}/{here.outcome} "
              f"({here.qualifier}) -> {here.progression}/{here.direction}/{here.distance}");
        visit [-->];
    }
}

walker AnalystTrace {
    """Walks the spine of action traces: trace -> consequence -> sequence
    -> repeated pattern -> interpretation.  Uses a guard set to enforce
    the cycle policy that the issue requires."""

    has visited: list[str] = [];
    has interpretation: str = "";

    can start with Root entry {
        self.visited = [];
        visit [-->];
    }

    can examine_match with Match entry {
        visit [-->];
    }

    can examine_actor with Actor entry {
        visit [-->];
    }

    can examine_atom with EvidenceAtom entry {
        visit [-->];
    }

    can read with ActionTrace entry {
        trace_id = f"{here.base_action}|{here.outcome}|{here.qualifier}";
        if trace_id in self.visited {
            print(f"  repeated pattern detected: {trace_id}");
            disengage;
        }
        self.visited.append(trace_id);

        print(f"[action] {here.base_action} ({here.qualifier}) "
              f"x={here.xlsx_aggregate}");

        next_traces = [->:Follows:->];
        if next_traces {
            nxt = next_traces[0];
            print(f"[consequence] -> {nxt.base_action}/{nxt.outcome}");
        } else {
            print("[consequence] terminal");
        }

        seq_label = "build_up_sequence" if here.progression == "build_up" else "open_play";
        print(f"[sequence] {seq_label}");

        pattern_note = "rhythm_change" if here.direction == "forward" else "lateral";
        interp = f"interpreter: {pattern_note} after {here.team_reflection}";
        self.interpretation = interp;
        print(f"[interpretation] {interp}");

        visit [-->];
    }
}

with entry {
    m = Match(match_id="M-001", period=1, minute=23);
    a1 = Actor(actor_id="A-9", name="Striker", team_id="T-HOME");
    a2 = Actor(actor_id="A-1", name="Keeper", team_id="T-HOME");

    s_player_csv = Surface(source_role="PLAYER", format="CSV", provider_row_id="PCSV-12");
    s_player_xml = Surface(source_role="PLAYER", format="XML", provider_row_id="PXML-12");
    s_player_xlsx = Surface(source_role="PLAYER", format="XLSX", provider_row_id="PXLSX-12");
    s_team_csv = Surface(source_role="TEAM", format="CSV", provider_row_id="TCSV-3");
    s_team_xml = Surface(source_role="TEAM", format="XML", provider_row_id="TXML-3");
    s_gk_csv = Surface(source_role="GOALKEEPER", format="CSV", provider_row_id="GKCSV-1");
    s_gk_xml = Surface(source_role="GOALKEEPER", format="XML", provider_row_id="GKXML-1");
    s_gk_xlsx = Surface(source_role="GOALKEEPER", format="XLSX", provider_row_id="GKXLSX-1");

    atom = EvidenceAtom(label="pass_attempt", x=78.5, y=42.0);
    trace = ActionTrace();

    root ++> m;
    m +>:HasActor:+> a1;
    m +>:HasActor:+> a2;
    a1 +>:CarriesAtom:+> atom;
    a1 +>:HasTrace:+> trace;

    trace +>:Surfaces:+> s_player_csv;
    trace +>:Surfaces:+> s_player_xml;
    trace +>:Surfaces:+> s_player_xlsx;
    trace +>:Surfaces:+> s_team_csv;
    trace +>:Surfaces:+> s_team_xml;
    trace +>:Surfaces:+> s_gk_csv;
    trace +>:Surfaces:+> s_gk_xml;
    trace +>:Surfaces:+> s_gk_xlsx;

    trace2 = ActionTrace(base_action="shot", outcome="saved",
                          qualifier="header", progression="transition",
                          direction="forward", distance="short",
                          gk_relation="saved", team_reflection="final_third",
                          xlsx_aggregate="shot_count:2");
    trace +>:Follows:+> trace2;

    root spawn TraceBuilder();
    analyst = AnalystTrace();
    root spawn analyst;
    print(f"final interpretation: {analyst.interpretation}");
}

"""Share-link access control: arm and revoke a READ grant on a journal note."""

node Note {
    has title: str = "";
    has body: str = "";
    has owner_only: bool = True;
    has share_armed: bool = False;
}

walker ArmShare {
    can start with Root entry {
        visit [-->];
    }

    can arm with Note entry {
        here.share_armed = True;
        here.owner_only = False;
        flag = "ARMED" if here.share_armed else "DISMISSED";
        access = "shareable" if not here.owner_only else "owner-only";
        print(f"[{flag}] '{here.title}' is now {access}");
        visit [-->];
    }
}

walker RevokeShare {
    can start with Root entry {
        visit [-->];
    }

    can revoke with Note entry {
        here.share_armed = False;
        here.owner_only = True;
        flag = "ARMED" if here.share_armed else "DISMISSED";
        access = "shareable" if not here.owner_only else "owner-only";
        print(f"[{flag}] '{here.title}' reverted to {access}");
        visit [-->];
    }
}

with entry {
    root ++> Note(title="Morning Pages", body="Today I woke up early...")
        ++> Note(title="Trip Recap", body="The cabin by the lake was quiet.")
        ++> Note(title="Book List", body="Dune, Piranesi, Klara and the Sun.");

    print("--- Arming share links ---");
    root spawn ArmShare();
    print("--- Revoking share links ---");
    root spawn RevokeShare();
}

