"""Build-system dependency graph: walk tasks via shared-library edges and
report total build minutes, auditing each task exactly once even when
multiple paths reach it (diamond DAGs)."""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

edge Needs {
    has reason: str = "runtime";
}

walker BuildAuditor {
    has total_minutes: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    def audit_task(task: Task) {
        if task.name not in self.visited {
            self.visited.append(task.name);
            self.total_minutes += task.minutes;
            print(f"[+] {task.name} (+{task.minutes} min, total={self.total_minutes})");
        } else {
            print(f"[skip] {task.name} already audited");
        }
    }

    can audit with Task entry {
        self.audit_task(here);
        visit [-->];
    }
}

# Walkers in jac 0.36.1 have no built-in dedupe; the explicit `visited`
# list on the walker is the audit-once guarantee across diamond paths.

with entry {
    # Diamond DAG:
    #   core <-- utils <-- app <-- reports
    #   core <--   ui   <-- app
    root ++> Task(name="core",     minutes=10)
        ++> Task(name="utils",    minutes=5)
        ++> Task(name="ui",       minutes=7)
        ++> Task(name="app",      minutes=8)
        ++> Task(name="reports",  minutes=3);

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"\nTotal build minutes (each task audited once): {auditor.total_minutes}");
}

"""Team-color modification decoding: walk a team's modification chain,
catching a broken/empty token (the boost-test fallback path) so the
decoding walker reports a clean fallback instead of crashing.

Models the wesnoth `~TC()` image-path function: a `TeamColor` node
carries a chain of `Modifier` nodes linked by typed `Next` edges, one
of which is left empty to reproduce the CI failure mode.
"""

node Modifier {
    has token: str = "";
    has value: int = 0;
}

node TeamColor {
    has team_id: str = "";
    has fallback_used: bool = False;
}

edge Next {}

walker DecodeTC {
    has default_rgb: tuple = (128, 128, 128);

    can start with Root entry {
        visit [->:Next:->];
    }

    can read with TeamColor entry {
        visit [->:Next:->];
    }

    can decode with Modifier entry {
        # Decode the token; an empty token mimics the empty-string
        # case the boost test exercises on the failure path.
        if here.token == "" {
            # The fallback path: mark the team as having used its
            # fallback and stop walking (mirrors the early-return
            # in the C++ catch block).
            print(f"[fallback] empty token -> default {self.default_rgb}");
            disengage;
        } elif here.token == "TC" {
            print(f"[TC] team tint = {here.value}");
            visit [->:Next:->];
        } else {
            print(f"[skip] unknown token {here.token}");
            visit [->:Next:->];
        }
    }
}

with entry {
    team = TeamColor(team_id="side_1");
    m1 = Modifier(token="TC", value=255);
    m2 = Modifier(token="");  # the empty-string failure case
    m3 = Modifier(token="TC", value=64);

    root +>:Next:+> team;
    team +>:Next:+> m1;
    m1 +>:Next:+> m2;
    m2 +>:Next:+> m3;

    root spawn DecodeTC();
}

"""Bidirectional friendships between houses in a small neighborhood.

Each pair of houses is wired together with a buddy edge in one statement.
Two greeter walkers are spawned (one per house) and reach each other using
forward traversal only, with an explicit visited set so they cannot bounce
back and forth forever.
"""

node House {
    has name: str = "";
    has residents: int = 0;
}

edge Buddy {
    has since: str = "";
}

walker Greeter {
    has target: str = "";
    has visited: list[str] = [];
    has greeted: list[str] = [];
    has visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can knock with House entry {
        if here.name in self.visited {
            print(f"Already knocked on {here.name}, skipping");
            visit [-->];
        }
        self.visited.append(here.name);
        self.visits += 1;
        self.greeted.append(here.name);
        print(f"Greeter knocked at {here.name} (stop #{self.visits})");
        if here.name == self.target {
            print(f"Reached target {here.name} in {self.visits} stops");
            disengage;
        }
        if self.visits > 10 {
            print("Too many stops, giving up");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    alice = House(name="Alice", residents=3);
    bob = House(name="Bob", residents=2);
    carol = House(name="Carol", residents=4);
    dave = House(name="Dave", residents=1);

    # Wire every pair as buddies in one statement each (bidirectional).
    alice +>:Buddy(since="2020"):+> bob;
    bob +>:Buddy(since="2020"):+> alice;
    alice +>:Buddy(since="2020"):+> carol;
    carol +>:Buddy(since="2020"):+> alice;
    bob +>:Buddy(since="2021"):+> carol;
    carol +>:Buddy(since="2021"):+> bob;
    bob +>:Buddy(since="2021"):+> dave;
    dave +>:Buddy(since="2021"):+> bob;
    carol +>:Buddy(since="2022"):+> dave;
    dave +>:Buddy(since="2022"):+> carol;

    root ++> alice;
    root ++> bob;
    root ++> carol;
    root ++> dave;

    g_alice = Greeter(target="Dave");
    alice spawn g_alice;

    g_dave = Greeter(target="Alice");
    dave spawn g_dave;

    print(f"Alice's greeter visited: {g_alice.greeted}");
    print(f"Dave's greeter visited: {g_dave.greeted}");
}

