"""Accessibility audit walk across mobile screens: model screens as nodes,
wire accessibility annotations (VoiceOver labels, contrast checks, reduced-motion
honored, RTL support) as typed edges, then walk the screen graph with an auditor
walker that reports per-screen audit results."""

node Screen {
    has name: str = "";
    has wcag_aa_contrast: bool = False;
    has voiceover_labels: bool = False;
    has reduced_motion_honored: bool = False;
    has rtl_layout: bool = False;
}

edge NavigatesTo { has transition: str = "push"; }
edge Contains { }

walker AccessibilityAuditor {
    has visited: list[str] = [];
    has failures: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        print("=== Accessibility Audit (WCAG AA + a11y checks) ===");
        visit [-->];
    }

    can audit with Screen entry {
        # Cycle policy: explicit guard set since walkers don't dedupe.
        already_seen = False;
        for v in self.visited {
            if v == here.name {
                already_seen = True;
                break;
            }
        }
        if already_seen {
            visit [-->] else { disengage; };
            return;
        }
        self.visited.append(here.name);

        print(f"\n[Screen] {here.name}");
        checks = [
            ("WCAG AA contrast", here.wcag_aa_contrast),
            ("VoiceOver labels", here.voiceover_labels),
            ("Reduced-motion honored", here.reduced_motion_honored),
            ("RTL layout", here.rtl_layout)
        ];
        for (label, passed) in checks {
            verdict = "PASS" if passed else "FAIL";
            print(f"  - {label}: {verdict}");
            if not passed {
                self.failures.append(f"{here.name}: {label}");
            }
        }
        visit [-->] else { disengage; };
    }
}

walker AuditReport {
    can start with Root entry {
        print("\n=== Audit Summary ===");
        print("Total screens visited: see AccessibilityAuditor.visited");
        print("Failures collected: see AccessibilityAuditor.failures");
        visit [-->] else { disengage; };
    }
}

with entry {
    # Build a small screen graph: onboarding flow + main tabs.
    welcome = Screen(
        name="Welcome",
        wcag_aa_contrast=True,
        voiceover_labels=True,
        reduced_motion_honored=True,
        rtl_layout=True
    );
    signup = Screen(
        name="SignUp",
        wcag_aa_contrast=True,
        voiceover_labels=False,  # missing VoiceOver on submit button
        reduced_motion_honored=True,
        rtl_layout=False          # RTL layout broken
    );
    home = Screen(
        name="Home",
        wcag_aa_contrast=True,
        voiceover_labels=True,
        reduced_motion_honored=False,  # animates regardless of setting
        rtl_layout=True
    );
    settings = Screen(
        name="Settings",
        wcag_aa_contrast=False,  # low-contrast toggle row
        voiceover_labels=True,
        reduced_motion_honored=True,
        rtl_layout=True
    );

    # Typed edges where navigation semantics matter.
    root +>:NavigatesTo(transition="push"):+> welcome;
    welcome +>:NavigatesTo:+> signup;
    signup +>:NavigatesTo:+> home;
    home +>:NavigatesTo:+> settings;
    settings +>:NavigatesTo(transition="modal"):+> home;

    # Containment edge: Settings tab contains nested accessibility sub-screen.
    settings +>:Contains:+> Screen(
        name="AccessibilityPrefs",
        wcag_aa_contrast=True,
        voiceover_labels=True,
        reduced_motion_honored=True,
        rtl_layout=True
    );

    auditor = AccessibilityAuditor();
    root spawn auditor;
    print(f"\nScreens audited: {auditor.visited}");
    print(f"Failures ({len(auditor.failures)}): {auditor.failures}");

    root spawn AuditReport();
}

"""Hiking trail: plain waypoints chained from trailhead to summit; a hiker walker counts each stop."""

node Trailhead {
    has name: str = "";
}

node Waypoint {
    has marker: bool = True;
}

node Summit {
    has name: str = "";
}

walker Hiker {
    has stop_count: int = 0;
    has required_stops: int = 0;

    can start with Root entry {
        print("Setting out on the trail");
        visit [-->];
    }

    can depart with Trailhead entry {
        label = here.name if here.name else "trailhead";
        print(f"Leaving {label}");
        visit [-->];
    }

    can mark_stop with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
    }

    can finish with Summit entry {
        label = here.name if here.name else "summit";
        if self.stop_count >= self.required_stops {
            print(f"Hike complete — passed {self.stop_count} waypoints; arrived at {label}");
        } else {
            print(f"Arrived at {label} after {self.stop_count} waypoints (expected {self.required_stops})");
        }
        disengage;
    }
}

with entry {
    head = Trailhead(name="Pine Ridge Trailhead");
    peak = Summit(name="Eagle Peak");
    root ++> head
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> peak;
    root spawn Hiker(required_stops=3);
}

