"""Desktop session stale-content bug: model session state and prove that a
fresh session still inherits stale exchanges because the auto-resume walker
follows the typed restore edge from the previous session.

Entities (nodes):
  - Session        : a chat session with an id and a dirty/exchange list
  - Exchange       : a single user/assistant message in a session
  - DesktopState   : the Electron-side UI state that auto-resumes on start
  - SessionIndex   : the ordered list of recent sessions

Relationships (typed edges):
  - Contains       : Session ---> Exchange
  - Tracked        : SessionIndex ---> Session  (recency order)
  - RestoresFrom   : DesktopState ---> Session  (auto-resume target)

The bug is captured by the ``StaleResume`` walker: starting from
``DesktopState``, it follows the ``RestoresFrom`` edge into a previous
``Session`` and prints every ``Exchange`` it still contains. The demo shows
that even after ``here.exchanges == []`` (the source of truth was cleared),
the typed edge still points at the stale Session, so the UI happily
rehydrates from it.
"""

node Exchange {
    has role: str = "user";
    has content: str = "";
    has stale: bool = True;
}

node Session {
    has session_id: str = "";
    has cleared: bool = False;
}

node SessionIndex {
    has name: str = "recent";
    has head: str = "";
}

node DesktopState {
    has auto_resume: bool = True;
    has resume_target: str = "";
}

edge Contains {
    has order: int = 0;
}

edge Tracked {
    has rank: int = 0;
}

edge RestoresFrom {
    has since: str = "";
}

walker StaleResume {
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:RestoresFrom:->];
    }

    can follow_edge with DesktopState entry {
        if not here.auto_resume {
            print(f"[skip] auto_resume disabled on {here}");
            disengage;
        }
        if here.resume_target == "" {
            print(f"[skip] no resume target on {here}");
            disengage;
        }
        visit [->:RestoresFrom:->];
    }

    can land_on_session with Session entry {
        already_seen = False;
        for sid in self.seen {
            if sid == here.session_id {
                already_seen = True;
            }
        }
        if already_seen {
            print(f"[cycle] already visited session {here.session_id}");
            disengage;
        }
        self.seen.append(here.session_id);
        print(
            f"[restore] DesktopState pulls session {here.session_id} "
            f"(cleared={here.cleared})"
        );
        visit [->:Contains:->];
    }

    can show_message with Exchange entry {
        label = "STALE" if here.stale else "FRESH";
        print(f"  -> [{label}] {here.role}: {here.content}");
    }
}

walker FreshnessProbe {
    can start with Root entry {
        visit [->:Tracked:->];
    }

    can scan with SessionIndex entry {
        visit [->:Tracked:->];
    }

    can grade with Session entry {
        print(f"[probe] session {here.session_id} cleared={here.cleared}");
    }
}

with entry {
    # The previous session that should have been forgotten.
    old = Session(session_id="s-old", cleared=True);
    old +>:Contains(order=0):+> Exchange(role="user", content="old prompt A");
    old +>:Contains(order=1):+> Exchange(role="assistant", content="old reply A");

    # The brand-new session that should start empty.
    fresh = Session(session_id="s-new", cleared=False);
    fresh +>:Contains(order=0):+> Exchange(role="user", content="", stale=False);

    # The recent-sessions list (oldest -> newest, rank 0 = most recent).
    index = SessionIndex(name="recent", head="s-new");
    index +>:Tracked(rank=0):+> fresh;
    index +>:Tracked(rank=1):+> old;

    # The Electron-side state still points at the stale session.
    desktop = DesktopState(auto_resume=True, resume_target="s-old");
    desktop +>:RestoresFrom(since="v0.18.2"):+> old;

    root ++> index ++> desktop;

    print("--- StaleResume: walk what the desktop UI auto-restores ---");
    root spawn StaleResume();

    print("--- FreshnessProbe: what the index thinks is clean ---");
    root spawn FreshnessProbe();
}

"""Vending machine controller: model states as nodes and feed a sequence of inputs via a walker."""

node Idle {
    has name: str = "idle";
    has is_accepting: bool = True;
    has is_terminal: bool = False;
}

node Waiting {
    has name: str = "waiting";
    has is_accepting: bool = True;
    has is_terminal: bool = False;
}

node Vend {
    has name: str = "vend";
    has is_accepting: bool = False;
    has is_terminal: bool = True;
}

walker Controller {
    has inputs: list[str] = [];

    can start with Root entry {
        print(f"Starting with inputs: {self.inputs}");
        visit [-->] else { disengage; }
    }

    can drive with Idle entry {
        consumed = False;
        for input in self.inputs {
            if input == "coin" {
                print(f"in idle, coin inserted -> waiting");
                visit [-->] else { disengage; }
                consumed = True;
                break;
            } elif input == "button" {
                print(f"in idle, button pressed -> idle (no change)");
            } else {
                print(f"in idle, no transition for '{input}' -> idle");
            }
        }
        if not consumed {
            print(f"ended in state: {here.name}");
        }
    }

    can drive_wait with Waiting entry {
        for input in self.inputs {
            if input == "coin" {
                print(f"in waiting, coin inserted -> waiting");
            } elif input == "button" {
                print(f"in waiting, button pressed -> vend");
                visit [-->] else { disengage; }
                return;
            } else {
                print(f"in waiting, no transition for '{input}' -> waiting");
            }
        }
        print(f"ended in state: {here.name}");
    }

    can arrive with Vend entry {
        print(f"reached terminal state: {here.name}");
    }
}

with entry {
    inputs = ["coin", "coin", "button", "coin"];
    root ++> Idle(name="idle")
        ++> Waiting(name="waiting")
        ++> Vend(name="vend");
    root spawn Controller(inputs=inputs);
}

