"""SPMD warning policy graph with typed relationships and cycle-safe auditing."""

node Entity {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has decision: str = "allow";

    def describe() -> str {
        return self.title;
    }
}

node Project(Entity) {
    has policy_group: str = "performance";

    override def describe() -> str {
        return f"project {self.title} [{self.policy_group}]";
    }
}

node Backend(Entity) {
    has backend_name: str = "";

    override def describe() -> str {
        return f"backend {self.backend_name}";
    }
}

node Advisory(Entity) {
    has code: str = "W0300";
    has subcategory: str = "";
    has limitation_reason: str = "";
    has phase: str = "early";

    override def describe() -> str {
        return f"{self.code}/{self.subcategory} on {self.backend_name()} ({self.phase}): {self.limitation_reason}";
    }

    def backend_name() -> str {
        return self.title;
    }
}

node Policy(Entity) {
    has effective_level: str = "warn";
    has policy_reason: str = "";
    has baseline_state: str = "unmatched";

    override def describe() -> str {
        return f"policy {self.effective_level}, baseline={self.baseline_state}: {self.policy_reason}";
    }
}

edge Contains { }
edge UsesBackend { has selected: bool = True; }
edge ProducesAdvisory { has phase: str = "early"; }
edge ResolvedBy { has reason: str = ""; }
edge DependsOn { }

walker PolicyAuditor {
    has seen: list[str] = [];
    has findings: int = 0;

    can start with Root entry {
        print("Auditing configured SPMD diagnostics");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Project | Backend | Advisory | Policy entry {
        if here.key in self.seen {
            print(f"cycle detected at {here.key}");
            disengage;
        }

        self.seen.append(here.key);
        print(f"{here.describe()} | decision={here.decision}");

        if here.kind == "advisory" {
            self.findings += 1;
        }

        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    project = Project(
        key="project-typelisp",
        title="typelisp",
        kind="project",
        decision="configured"
    );
    backend = Backend(
        key="backend-teal",
        title="Teal",
        backend_name="Teal",
        kind="backend",
        decision="selected"
    );
    advisory = Advisory(
        key="advisory-w0300",
        title="Teal",
        kind="advisory",
        subcategory="unsupported-spmd-route",
        limitation_reason="selected backend cannot lower the route",
        phase="early",
        decision="warn"
    );
    policy = Policy(
        key="policy-performance",
        title="performance",
        kind="policy",
        effective_level="warn",
        policy_reason="project performance policy",
        baseline_state="new",
        decision="publish"
    );

    root +>:Contains:+> project;
    project +>:UsesBackend(selected=True):+> backend;
    backend +>:ProducesAdvisory(phase="early"):+> advisory;
    advisory +>:ResolvedBy(reason="performance group policy"):+> policy;

    followup = Advisory(
        key="advisory-followup",
        title="Teal",
        kind="advisory",
        subcategory="late-optimization",
        limitation_reason="follow-up advisory retained for artifact builds",
        phase="late",
        decision="allow"
    );
    advisory +>:DependsOn:+> followup;
    followup +>:DependsOn:+> advisory;

    audit = PolicyAuditor();
    root spawn audit;
}
