node Workspace(AuditItem) {
    has kind: str = "workspace";
}

node Package(AuditItem) {
    has version: str = "";
    has production: bool = False;
}

node Advisory(AuditItem) {
    has severity: str = "moderate";
    has fixed_in: str = "";
}

edge Contains {
    has relation: str = "contains";
}

edge DependsOn {
    has scope: str = "runtime";
}

edge HasAdvisory {
    has severity: str = "moderate";
}

walker DependencyAudit {
    has visited_keys: list[str] = [];
    has cycle_hits: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Workspace | Package | Advisory entry {
        if here.key in self.visited_keys {
            self.cycle_hits += 1;
            print(f"Cycle detected at {here.title}");
            disengage;
        } else {
            self.visited_keys.append(here.key);
            label = "available" if here.available else "unavailable";
            print(f"Audited {here.title} ({label})");
            visit [-->] else {
                disengage;
            }
        }
    }
}

