"""Native graph demo for node-local tactic timeout policy."""

node Theory {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "";
    has local_timeout: float = -1.0;
    has entry_timeout: float = -1.0;
    has effective_timeout: float = 0.0;
    has timeout_enabled: bool = True;
    has in_scope: bool = False;
    has visit_state: int = 0;
    has cycle_detected: bool = False;
}

node BuildPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has default_timeout: float = 2.5;
    has cli_timeout: float = -1.0;
    has proof_scope: bool = True;
}

edge SelectedRoot { }
edge DependsOn { }

walker TimeoutPlanner {
    has default_timeout: float = 2.5;
    has cli_timeout: float = -1.0;
    has proof_scope: bool = True;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can load_plan with BuildPlan entry {
        self.default_timeout = here.default_timeout;
        self.cli_timeout = here.cli_timeout;
        self.proof_scope = here.proof_scope;
        visit [->:SelectedRoot:->] else { disengage; }
    }

    can assign_timeout with Theory entry {
        if here.visit_state == 1 {
            here.cycle_detected = True;
            self.cycle_found = True;
            disengage;
        } else {
            if here.visit_state == 0 {
                here.visit_state = 1;
                here.in_scope = self.proof_scope;

                if self.proof_scope {
                    if self.cli_timeout >= 0.0 {
                        here.effective_timeout = self.cli_timeout;
                    } else {
                        if here.local_timeout >= 0.0 {
                            here.effective_timeout = here.local_timeout;
                        } else {
                            if here.entry_timeout >= 0.0 {
                                here.effective_timeout = here.entry_timeout;
                            } else {
                                here.effective_timeout = self.default_timeout;
                            }
                        }
                    }

                    here.timeout_enabled = here.effective_timeout != 0.0;
                } else {
                    here.effective_timeout = 0.0;
                    here.timeout_enabled = False;
                }

                print(f"{here.title}: {here.effective_timeout}s");
                visit [->:DependsOn:->] else { disengage; }
                here.visit_state = 2;
            }
        }
    }
}

with entry {
    plan = BuildPlan(title="App build", default_timeout=2.5);

    app = Theory(
        title="AppTheory",
        source="src/AppScript.sml"
    );

    slow = Theory(
        title="SlowTheory",
        source="src/SlowScript.sml",
        local_timeout=30.0
    );

    base = Theory(
        title="BaseTheory",
        source="src/BaseScript.sml"
    );

    unused = Theory(
        title="UnusedTheory",
        source="src/UnusedScript.sml",
        local_timeout=60.0
    );

    root ++> plan;
    plan +>:SelectedRoot:+> app;
    app +>:DependsOn:+> slow;
    slow +>:DependsOn:+> base;

    root spawn TimeoutPlanner();
}
