"""Thread sharing without cloning: materialize only the invited thread checkout."""

node Thread {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has thread_key: str = "";
}

node Machine {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has machine_name: str = "";
    has checkout_policy: str = "auto";
    has has_spool: bool = False;
}

node Checkout {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has mode: str = "materialized";
    has ready: bool = False;
}

edge Invitation {
    has share_token: str = "";
}

edge Materialization {
    has policy: str = "auto";
}

walker ThreadJoiner {
    has checkout_policy: str = "auto";

    can start with Root entry {
        print("Opening a shared thread without cloning the spool");
        visit [-->] else {
            disengage;
        }
    }

    can follow_invitation with Machine entry {
        print(f"Machine {here.machine_name}: spool present = {here.has_spool}");
        print(f"Using start policy '{self.checkout_policy}'");
        visit [->:Invitation:->] else {
            disengage;
        }
    }

    can materialize_thread with Thread entry {
        if here.available {
            print(f"Authorized thread: {here.title} ({here.thread_key})");
            visit [->:Materialization:->] else {
                disengage;
            }
        } else {
            print(f"Thread unavailable: {here.title}");
            disengage;
        }
    }

    can confirm_checkout with Checkout entry {
        print(f"Checkout at {here.path}: mode={here.mode}, ready={here.ready}");
        print("Sibling thread history was not reached or materialized");
    }
}

with entry {
    machine = Machine(
        title="Empty joiner",
        machine_name="agent-02",
        checkout_policy="auto",
        has_spool=False
    );

    shared = Thread(
        title="Issue #1576 shared work",
        thread_key="thread-1576"
    );

    sibling = Thread(
        title="Private sibling history",
        thread_key="thread-private"
    );

    checkout = Checkout(
        title="Issue #1576 checkout",
        path="/work/heddle/thread-1576",
        mode="materialized",
        ready=False
    );

    root ++> machine;
    machine +>:Invitation(share_token="invite-thread-1576"):+> shared;
    shared +>:Materialization(policy="auto"):+> checkout;

    root spawn ThreadJoiner(checkout_policy="auto");
}

