"""Restaurant kitchen line inspection: grill, fryer, cold prep.

A health-inspector walker visits every station on the line and runs two
checks at each one: a temperature check (any reading above 40 C is a
violation) and a visit log (every station is recorded, in the order the
walker arrives). Both abilities are triggered at every station via a
union entry so neither check is skipped.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
    has violations: int = 0;
}

walker HealthInspector {
    has visited: list[str] = [];
    has violation_count: int = 0;
    has threshold: float = 40.0;

    can start with Root entry {
        print("Health inspector beginning kitchen line walk-through");
        visit [-->] else { disengage; }
    }

    # Union trigger: fires for ANY station type. Both abilities below are
    # bound to the same Station archetype, so every station triggers both.
    can inspect with Station entry {
        # --- Temperature check ---
        if here.temperature > self.threshold {
            here.violations += 1;
            self.violation_count += 1;
            verdict = "VIOLATION";
        } else {
            verdict = "OK";
        }
        # --- Visit log ---
        self.visited.append(here.name);
        print(
            f"[{verdict}] {here.name} @ {here.temperature} C "
            f"(lifetime violations: {here.violations})"
        );
        visit [-->] else { disengage; }
    }
}

with entry {
    grill = Station(name="Grill", temperature=185.0);
    fryer = Station(name="Fryer", temperature=175.0);
    cold_prep = Station(name="Cold Prep", temperature=4.5);

    root ++> grill ++> fryer ++> cold_prep;

    inspector = HealthInspector();
    root spawn inspector;

    print(f"Stations visited: {inspector.visited}");
    print(f"Total violations flagged: {inspector.violation_count}");
    print(
        f"Per-station violations -> "
        f"Grill: {grill.violations}, "
        f"Fryer: {fryer.violations}, "
        f"Cold Prep: {cold_prep.violations}"
    );
}

"""Order auditor: skip invalid orders but halt the walk on fraud.

Two flavors of early return sit side by side:
- `continue` in a `for` loop skips just the bad order and keeps going.
- `disengage;` inside a walker ability aborts the entire walk on the spot
  when an order is flagged as fraud.
"""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has processed: int = 0;

    can start with Root entry {
        print(f"Auditor begins on root");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flag on order {here.order_id} (${here.amount}) — walk aborted");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] order {here.order_id} invalid — audit continues");
            self.processed += 0;
            visit [-->] else { disengage; }
            return;
        }
        print(f"[OK]   order {here.order_id} (${here.amount}) cleared");
        self.processed += 1;
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Order(order_id="A1", amount=120.0, valid=True,  fraud=False)
        ++> Order(order_id="A2", amount= 45.0, valid=False, fraud=False)
        ++> Order(order_id="A3", amount=300.0, valid=True,  fraud=True)
        ++> Order(order_id="A4", amount= 60.0, valid=True,  fraud=False);

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"auditor processed {auditor.processed} valid orders before halt");
}

"""Moderation sweep over game accounts.

Member accounts are audited normally, admin accounts get their
reputation boosted by 5, and the welcome desk greets every bot passing
through no matter what kind of walker it is.
"""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Member(Account) {
    has reputation: int = 0;
    has violation_count: int = 0;

    def audit() -> str {
        verdict = "CLEAN" if self.violation_count == 0 else "FLAGGED";
        return f"[{verdict}] member {self.title} rep={self.reputation}";
    }
}

node Admin(Account) {
    has reputation: int = 0;
    has violation_count: int = 0;

    def audit() -> str {
        boosted = self.reputation + 5;
        verdict = "CLEAN" if self.violation_count == 0 else "FLAGGED";
        return f"[{verdict}] admin {self.title} rep={boosted} (boosted +5)";
    }
}

